#!/usr/bin/env bun

import { readdir, readFile, stat, writeFile } from "node:fs/promises";
import { extname, join, resolve } from "node:path";
import { parseArgs } from "node:util";
import type { MessageWithMetadata } from "@cline/shared";
import { createContextCompactionPrepareTurn } from "../src/extensions/context/compaction";
import { getCompactionSummaryMetadata } from "../src/extensions/context/compaction-shared";
import { normalizeStoredMessagesForPersistence } from "../src/services/session-data";
import type { ProviderConfig } from "../src/types/provider-settings";

type CompactionStrategy = "basic" | "agentic";
type StrategySelection = CompactionStrategy | "both";

const PROVIDER_API_KEY_ENV: Record<string, string> = {
	anthropic: "ANTHROPIC_API_KEY",
	cline: "CLINE_API_KEY",
	gemini: "GOOGLE_API_KEY",
	mistral: "MISTRAL_API_KEY",
	openai: "OPENAI_API_KEY",
	"openai-compatible": "OPENAI_API_KEY",
};

function usage(): never {
	console.error(`Usage:
	  bun -F @cline/core test:compaction -- <session-directory> [options]

Options:
	  --strategy <strategy>       basic, agentic, or both (default: both)
	  --provider <provider-id>    Required for agentic compaction
	  --model <model-id>          Required for agentic compaction
	  --api-key-env <name>        Environment variable containing the API key
	                              (agentic compaction only)
  --base-url <url>            Custom provider base URL
  --max-input-tokens <count>  Summarizer input limit (default: 128000)
  --max-output-tokens <count> Summarizer output limit (default: 1024)
  --preserve-recent-tokens <count>
                              Verbatim tail to retain (default: 0)
	  --output <path>             Write canonical compacted messages JSON. With
	                              --strategy both, .basic and .agentic are added
	                              before the file extension.

The directory must contain messages.json or exactly one *.messages.json file.
For agentic compaction, provider API key defaults are ANTHROPIC_API_KEY,
CLINE_API_KEY, OPENAI_API_KEY, GOOGLE_API_KEY, or MISTRAL_API_KEY, according
to --provider.`);
	process.exit(1);
}

function positiveInteger(
	value: string | undefined,
	name: string,
	fallback: number,
): number {
	if (value === undefined) return fallback;
	const parsed = Number(value);
	if (!Number.isSafeInteger(parsed) || parsed <= 0) {
		throw new Error(`${name} must be a positive integer`);
	}
	return parsed;
}

function nonNegativeInteger(
	value: string | undefined,
	name: string,
	fallback: number,
): number {
	if (value === undefined) return fallback;
	const parsed = Number(value);
	if (!Number.isSafeInteger(parsed) || parsed < 0) {
		throw new Error(`${name} must be a non-negative integer`);
	}
	return parsed;
}

function parseStrategy(value: string | undefined): StrategySelection {
	const strategy = value ?? "both";
	if (strategy !== "basic" && strategy !== "agentic" && strategy !== "both") {
		throw new Error("--strategy must be basic, agentic, or both");
	}
	return strategy;
}

function selectedStrategies(
	selection: StrategySelection,
): CompactionStrategy[] {
	return selection === "both" ? ["basic", "agentic"] : [selection];
}

function strategyOutputPath(
	path: string,
	strategy: CompactionStrategy,
	selection: StrategySelection,
): string {
	const absolutePath = resolve(path);
	if (selection !== "both") return absolutePath;
	const extension = extname(absolutePath);
	const stem = extension
		? absolutePath.slice(0, -extension.length)
		: absolutePath;
	return `${stem}.${strategy}${extension}`;
}

async function resolveMessagesPath(directory: string): Promise<string> {
	const absoluteDirectory = resolve(directory);
	if (!(await stat(absoluteDirectory)).isDirectory()) {
		throw new Error(`Not a directory: ${absoluteDirectory}`);
	}
	const names = await readdir(absoluteDirectory);
	if (names.includes("messages.json"))
		return join(absoluteDirectory, "messages.json");
	const candidates = names.filter((name) => name.endsWith(".messages.json"));
	if (candidates.length !== 1) {
		throw new Error(
			`Expected exactly one *.messages.json in ${absoluteDirectory}; found ${candidates.length}`,
		);
	}
	return join(absoluteDirectory, candidates[0]);
}

function readMessages(payload: unknown): {
	messages: MessageWithMetadata[];
	systemPrompt: string;
	sessionId: string;
} {
	if (!payload || typeof payload !== "object")
		throw new Error("messages.json must contain an object");
	const record = payload as Record<string, unknown>;
	if (!Array.isArray(record.messages) || record.messages.length < 2) {
		throw new Error("messages.json must contain at least two messages");
	}
	for (const [index, message] of record.messages.entries()) {
		if (!message || typeof message !== "object")
			throw new Error(`messages[${index}] must be an object`);
		const candidate = message as Record<string, unknown>;
		if (
			(candidate.role !== "user" && candidate.role !== "assistant") ||
			(typeof candidate.content !== "string" &&
				!Array.isArray(candidate.content))
		) {
			throw new Error(
				`messages[${index}] must have a user/assistant role and string or array content`,
			);
		}
	}
	return {
		messages: record.messages as MessageWithMetadata[],
		systemPrompt:
			typeof record.system_prompt === "string" ? record.system_prompt : "",
		sessionId:
			typeof record.sessionId === "string"
				? record.sessionId
				: "offline-compaction",
	};
}

const { values, positionals } = parseArgs({
	args: process.argv.slice(2),
	allowPositionals: true,
	strict: true,
	options: {
		strategy: { type: "string" },
		provider: { type: "string" },
		model: { type: "string" },
		"api-key-env": { type: "string" },
		"base-url": { type: "string" },
		"max-input-tokens": { type: "string" },
		"max-output-tokens": { type: "string" },
		"preserve-recent-tokens": { type: "string" },
		output: { type: "string" },
	},
});

const directory = positionals[0];
const providerId = values.provider;
const modelId = values.model;
if (!directory || positionals.length !== 1) usage();
const strategySelection = parseStrategy(values.strategy);
const strategies = selectedStrategies(strategySelection);
if (strategies.includes("agentic") && (!providerId || !modelId)) {
	console.error(
		"Error: --provider and --model are required for agentic compaction\n",
	);
	usage();
}

const maxInputTokens = positiveInteger(
	values["max-input-tokens"],
	"--max-input-tokens",
	128_000,
);
const maxOutputTokens = positiveInteger(
	values["max-output-tokens"],
	"--max-output-tokens",
	1_024,
);
const preserveRecentTokens = nonNegativeInteger(
	values["preserve-recent-tokens"],
	"--preserve-recent-tokens",
	0,
);
const needsProviderCredentials = strategies.includes("agentic");
const apiKeyEnvironment = needsProviderCredentials
	? (values["api-key-env"] ??
		(providerId ? PROVIDER_API_KEY_ENV[providerId] : undefined))
	: undefined;
const apiKey = apiKeyEnvironment ? process.env[apiKeyEnvironment] : undefined;
if (apiKeyEnvironment && !apiKey)
	throw new Error(`Missing API key in ${apiKeyEnvironment}`);

const messagesPath = await resolveMessagesPath(directory);
const payload = JSON.parse(await readFile(messagesPath, "utf8")) as unknown;
const { messages, systemPrompt, sessionId } = readMessages(payload);
const resolvedProviderId = providerId ?? "offline";
const resolvedModelId = modelId ?? "offline";
const providerConfig = {
	providerId: resolvedProviderId,
	modelId: resolvedModelId,
	...(apiKey ? { apiKey } : {}),
	...(values["base-url"] ? { baseUrl: values["base-url"] } : {}),
	maxOutputTokens,
	modelInfo: {
		id: resolvedModelId,
		contextWindow: maxInputTokens,
		maxInputTokens,
		maxTokens: maxOutputTokens,
	},
} as ProviderConfig;

console.error(`Reading ${messages.length} messages from ${messagesPath}`);
for (const strategy of strategies) {
	const compact = createContextCompactionPrepareTurn(
		{
			providerId: resolvedProviderId,
			modelId: resolvedModelId,
			providerConfig,
			sessionId,
			compaction: { enabled: true, strategy, preserveRecentTokens },
			logger: {
				debug: (message, metadata) =>
					console.error(`[${strategy}:debug] ${message}`, metadata ?? ""),
				log: (message, metadata) =>
					console.error(`[${strategy}:log] ${message}`, metadata ?? ""),
			},
		},
		{ mode: "manual" },
	);
	if (!compact) throw new Error(`${strategy} compaction was not initialized`);
	console.error(
		strategy === "agentic"
			? `Running agentic compaction with ${resolvedProviderId}/${resolvedModelId}`
			: "Running basic compaction",
	);
	const result = await compact({
		agentId: "offline-compaction",
		conversationId: sessionId,
		parentAgentId: null,
		iteration: 1,
		messages,
		apiMessages: messages,
		abortSignal: new AbortController().signal,
		systemPrompt,
		tools: [],
		model: {
			id: resolvedModelId,
			provider: resolvedProviderId,
			info: {
				id: resolvedModelId,
				contextWindow: maxInputTokens,
				maxInputTokens,
				maxTokens: maxOutputTokens,
			},
		},
	});
	if (!result?.messages)
		throw new Error(`${strategy} compaction produced no result`);

	console.log(`\n===== ${strategy.toUpperCase()} COMPACTION =====`);
	const summary = result.messages
		.map(getCompactionSummaryMetadata)
		.find(Boolean)?.summary;
	if (summary) console.log(summary);
	else console.log(JSON.stringify(result.messages, null, 2));

	if (values.output) {
		const outputPath = strategyOutputPath(
			values.output,
			strategy,
			strategySelection,
		);
		const outputPayload = {
			...(payload as Record<string, unknown>),
			updated_at: new Date().toISOString(),
			messages: normalizeStoredMessagesForPersistence(result.messages),
		};
		await writeFile(
			outputPath,
			`${JSON.stringify(outputPayload, null, 2)}\n`,
			"utf8",
		);
		console.error(`Wrote ${strategy} compacted messages to ${outputPath}`);
	}
}

/**
 * Host-level telemetry smoke test for ENG-1902.
 *
 * Exercises the CLI memoized activation helper and the VS Code shared
 * telemetry factory using the configured OTEL telemetry pipeline + a
 * BasicLogger sink. With OTEL_TELEMETRY_ENABLED unset the OpenTelemetry
 * provider stays disabled, so we observe events through the
 * `TelemetryLoggerSink` log lines (`telemetry.event`). Activation and
 * workspace lifecycle events are routed through normal `capture` so they
 * respect the user's telemetry opt-out setting.
 */

import {
	createClineTelemetryServiceConfig,
	type ITelemetryService,
} from "@cline/shared";
import {
	captureExtensionActivated,
	identifyAccount,
} from "../src/services/telemetry/core-events";
import { createConfiguredTelemetryService } from "../src/services/telemetry/OpenTelemetryProvider";

interface CapturedLog {
	channel: "log" | "debug" | "error";
	message: string;
	metadata?: Record<string, unknown>;
}

class CapturingLogger {
	readonly entries: CapturedLog[] = [];
	log(message: string, metadata?: Record<string, unknown>): void {
		this.entries.push({ channel: "log", message, metadata });
	}
	debug(message: string, metadata?: Record<string, unknown>): void {
		this.entries.push({ channel: "debug", message, metadata });
	}
	error(message: string, metadata?: Record<string, unknown>): void {
		this.entries.push({ channel: "error", message, metadata });
	}
}

function header(t: string) {
	console.log(`\n=== ${t} ===`);
}

function dumpActivationEvents(
	logger: CapturingLogger,
	eventName: string,
): number {
	let count = 0;
	for (const e of logger.entries) {
		if (e.message !== "telemetry.event") {
			continue;
		}
		const md = (e.metadata ?? {}) as {
			event?: string;
			properties?: Record<string, unknown>;
		};
		if (md.event !== eventName) {
			continue;
		}
		count++;
		console.log(`[event] ${md.event} ${JSON.stringify(md.properties ?? {})}`);
	}
	return count;
}

/**
 * Mirror of the per-process memoized CLI activation helper from
 * `apps/cli/src/utils/telemetry.ts` (`captureCliExtensionActivated`).
 *
 * Cross-importing from `apps/cli/...` here would pull the full
 * `@cline/core` barrel which transitively requires `@cline/llms`, so
 * we replicate the exact memoization pattern locally and call the same
 * underlying core helper.
 */
interface AccountContext {
	id?: string;
	email?: string;
	provider?: string;
	organizationId?: string;
	organizationName?: string;
	memberId?: string;
}

function makeMemoizedCliActivator(telemetry: ITelemetryService) {
	let captured = false;
	return (account?: AccountContext) => {
		if (captured) {
			return;
		}
		captured = true;
		// Mirror the real apps/cli helper: identify the active account/org
		// (mapped onto telemetry common properties via `identifyAccount`)
		// strictly before emitting `user.extension_activated`, so the
		// activation event itself carries `organization_id` and friends.
		if (account) {
			identifyAccount(telemetry, account);
		}
		captureExtensionActivated(telemetry);
	};
}

async function smokeCli() {
	header(
		"CLI: memoized captureCliExtensionActivated equivalent (only first call should emit)",
	);
	const logger = new CapturingLogger();
	const cfg = createClineTelemetryServiceConfig({
		metadata: {
			extension_version: "0.0.0-smoke",
			cline_type: "cli",
			platform: "smoke-cli",
			platform_version: process.version,
			os_type: process.platform,
			os_version: "smoke",
		},
	});
	const { telemetry, provider } = createConfiguredTelemetryService({
		...cfg,
		logger,
	});
	const captureCliActivation = makeMemoizedCliActivator(telemetry);
	captureCliActivation();
	captureCliActivation(); // memoized: must NOT emit a second event.
	const captured = dumpActivationEvents(logger, "user.extension_activated");
	console.log(
		`captured ${captured} user.extension_activated event(s); expected exactly 1.`,
	);
	await Promise.allSettled([telemetry.dispose(), provider?.dispose()]);
}

async function smokeCliAuthenticated() {
	header(
		"CLI: authenticated captureCliExtensionActivated should carry organization_id",
	);
	const logger = new CapturingLogger();
	const cfg = createClineTelemetryServiceConfig({
		metadata: {
			extension_version: "0.0.0-smoke",
			cline_type: "cli",
			platform: "smoke-cli",
			platform_version: process.version,
			os_type: process.platform,
			os_version: "smoke",
		},
	});
	const { telemetry, provider } = createConfiguredTelemetryService({
		...cfg,
		logger,
	});
	const captureCliActivation = makeMemoizedCliActivator(telemetry);
	captureCliActivation({
		id: "user-smoke",
		email: "user@example.com",
		provider: "cline",
		organizationId: "org-smoke",
		organizationName: "Smoke Org",
		memberId: "member-smoke",
	});
	const captured = dumpActivationEvents(logger, "user.extension_activated");
	console.log(
		`captured ${captured} user.extension_activated event(s); expected exactly 1, with organization_id="org-smoke".`,
	);
	await Promise.allSettled([telemetry.dispose(), provider?.dispose()]);
}

async function smokeVscode() {
	header("VS Code: createVscodeTelemetry-equivalent shared service");
	const logger = new CapturingLogger();
	const cfg = createClineTelemetryServiceConfig({
		metadata: {
			extension_version: "0.0.0-smoke",
			cline_type: "VSCode Extension",
			platform: "Visual Studio Code",
			platform_version: "1.113.0",
			os_type: process.platform,
			os_version: "smoke",
		},
	});
	const { telemetry, provider } = createConfiguredTelemetryService({
		...cfg,
		logger,
	});
	// Single shared activation event for the VS Code host
	captureExtensionActivated(telemetry);
	const captured = dumpActivationEvents(logger, "user.extension_activated");
	console.log(
		`captured ${captured} user.extension_activated event(s); expected exactly 1.`,
	);
	await Promise.allSettled([telemetry.dispose(), provider?.dispose()]);
}

async function main() {
	await smokeCli();
	await smokeCliAuthenticated();
	await smokeVscode();
	header("Done");
}

main().catch((err) => {
	console.error("host smoke test failed:", err);
	process.exitCode = 1;
});

/**
 * Telemetry smoke test for ENG-1902.
 *
 * Runs each activation/workspace funnel event through the SDK telemetry
 * helpers using a minimal capturing telemetry service. Prints the captured
 * event names and event-specific payloads so a human can verify no raw
 * paths leak and that the legacy snake_case schema is preserved. Activation
 * and workspace events are routed through normal `capture` so they respect
 * the user's telemetry opt-out setting.
 *
 * Usage:
 *   bunx --bun tsx packages/core/scripts/telemetry-smoke.ts
 *   # or
 *   bun packages/core/scripts/telemetry-smoke.ts
 */
import type { ITelemetryService, TelemetryProperties } from "@cline/shared";
import {
	captureConversationTurnEvent,
	captureExtensionActivated,
	captureTaskCompleted,
	captureTaskCreated,
	captureTaskRestarted,
	captureWorkspaceInitError,
	captureWorkspaceInitialized,
	captureWorkspacePathResolved,
} from "../src/services/telemetry/core-events";
import {
	emitWorkspaceLifecycleTelemetry,
	resetWorkspaceTelemetryForTests,
} from "../src/services/workspace/workspace-telemetry";

type RecordedEvent = {
	name: string;
	properties?: Record<string, unknown>;
	required: boolean;
};

/**
 * Minimal capturing stub used by the smoke harness. Intentionally **not**
 * declared `implements ITelemetryService` because this file is a CLI smoke
 * harness — its purpose is to record `capture()` / `captureRequired()`
 * payloads for human inspection, not to track every method that lands on
 * the production telemetry interface (e.g. `setMetadata`,
 * `setCommonProperties`, the `recordCounter` overload). Casting the
 * instance via `unknown as ITelemetryService` at the call site lets the
 * harness stay tiny while still typechecking under
 * `tsconfig.smoke.json`.
 */
class CapturingTelemetry {
	readonly events: RecordedEvent[] = [];

	capture(event: { event: string; properties?: TelemetryProperties }): void {
		this.events.push({
			name: event.event,
			properties: event.properties as Record<string, unknown> | undefined,
			required: false,
		});
	}

	captureRequired(event: string, properties?: TelemetryProperties): void {
		this.events.push({
			name: event,
			properties: properties as Record<string, unknown> | undefined,
			required: true,
		});
	}

	setDistinctId(_id?: string): void {}
	updateCommonProperties(_props: TelemetryProperties): void {}
	identify(_distinctId: string, _properties?: TelemetryProperties): void {}
	isEnabled(): boolean {
		return true;
	}
	async dispose(): Promise<void> {}
	async flush(): Promise<void> {}
	recordCounter(): void {}
	recordHistogram(): void {}
	recordGauge(): void {}
}

/**
 * Cast helper so call sites can pass the harness stub to functions that
 * accept the real `ITelemetryService` without each call duplicating the
 * `unknown` cast. See {@link CapturingTelemetry} for why we don't track
 * the production interface directly.
 */
function asITelemetryService(stub: CapturingTelemetry): ITelemetryService {
	return stub as unknown as ITelemetryService;
}

function header(title: string) {
	console.log(`\n=== ${title} ===`);
}

function rawPathLeakCheck(events: RecordedEvent[], rawPath: string) {
	for (const evt of events) {
		const dump = JSON.stringify(evt.properties ?? {});
		if (dump.includes(rawPath)) {
			console.log(`!! event ${evt.name} leaks raw path; properties=${dump}`);
			process.exitCode = 2;
			return;
		}
	}
	console.log(
		`✓ no raw workspace path "${rawPath}" leaked into ${events.length} captured event(s).`,
	);
}

function dumpEvents(events: RecordedEvent[]) {
	for (const evt of events) {
		// Activation/workspace events are now routed through normal `capture`
		// so the [required] tag is only kept for visibility on any unexpected
		// captureRequired() usage during the smoke run.
		const tag = evt.required ? "[required]" : "[event]   ";
		console.log(`${tag} ${evt.name} ${JSON.stringify(evt.properties ?? {})}`);
	}
}

/**
 * Assertion helper for smoke checks. Logs the comparison and, when the
 * assertion fails, sets `process.exitCode = 1` so CI can catch regressions
 * if the smoke harness is wired into a check step. Without this the script
 * would happily exit 0 on a count mismatch and silently mask broken
 * telemetry plumbing.
 */
function assertSmoke(
	label: string,
	actual: number | string | boolean,
	expected: number | string | boolean,
): void {
	const ok = actual === expected;
	const marker = ok ? "✓" : "!!";
	console.log(`${marker} ${label}: actual=${actual} expected=${expected}`);
	if (!ok) {
		process.exitCode = 1;
	}
}

async function main() {
	resetWorkspaceTelemetryForTests();

	header("user.extension_activated (CLI/VS Code activation parity)");
	{
		const t = new CapturingTelemetry();
		captureExtensionActivated(asITelemetryService(t));
		dumpEvents(t.events);
	}

	header("workspace.initialized + workspace.init_error (lifecycle emitter)");
	{
		const t = new CapturingTelemetry();
		const healthyRoot = "/tmp/healthy-repo";
		const brokenRoot = "/tmp/broken-repo";
		const tSvc = asITelemetryService(t);
		emitWorkspaceLifecycleTelemetry({
			telemetry: tSvc,
			rootPath: healthyRoot,
			rootCount: 1,
			vcsType: "git",
			durationMs: 92.7155,
			featureFlagEnabled: true,
		});
		// duplicate call to verify per-process de-dup
		emitWorkspaceLifecycleTelemetry({
			telemetry: tSvc,
			rootPath: healthyRoot,
			rootCount: 1,
			vcsType: "git",
			durationMs: 12.345,
		});
		emitWorkspaceLifecycleTelemetry({
			telemetry: tSvc,
			rootPath: brokenRoot,
			rootCount: 0,
			vcsType: "none",
			initError: {
				errorType: "WorkspaceSetupError",
				message: "permission denied while probing git repository",
			},
		});
		dumpEvents(t.events);
		rawPathLeakCheck(t.events, healthyRoot);
		rawPathLeakCheck(t.events, brokenRoot);
		const initialized = t.events.filter(
			(e) => e.name === "workspace.initialized",
		);
		const initError = t.events.filter((e) => e.name === "workspace.init_error");
		console.log(
			`emitted ${initialized.length} workspace.initialized and ${initError.length} workspace.init_error events; expected 2 + 1.`,
		);
		assertSmoke(
			"workspace.initialized count (after de-dup gate)",
			initialized.length,
			2,
		);
		assertSmoke("workspace.init_error count", initError.length, 1);
	}

	header("explicit captureWorkspaceInitialized payload sample");
	{
		const t = new CapturingTelemetry();
		captureWorkspaceInitialized(asITelemetryService(t), {
			root_count: 2,
			vcs_types: ["git", "hg"],
			init_duration_ms: 134.5,
			feature_flag_enabled: true,
			is_remote_workspace: false,
		});
		dumpEvents(t.events);
	}

	header("explicit captureWorkspaceInitError payload sample");
	{
		const t = new CapturingTelemetry();
		captureWorkspaceInitError(
			asITelemetryService(t),
			Object.assign(new Error("simulated init failure"), {
				name: "WorkspaceSetupError",
			}),
			{ fallback_to_single_root: true, workspace_count: 0 },
		);
		dumpEvents(t.events);
	}

	header("explicit captureWorkspacePathResolved payload sample");
	{
		const t = new CapturingTelemetry();
		captureWorkspacePathResolved(asITelemetryService(t), {
			ulid: "ulid-smoke-explicit",
			context: "search_codebase",
			resolution_type: "hint_provided",
			hint_type: "workspace_name",
			resolution_success: true,
			target_workspace_index: 1,
			is_multi_root_enabled: true,
		});
		dumpEvents(t.events);
	}

	header("task.created (canonical task-start event for new sessions)");
	{
		const t = new CapturingTelemetry();
		captureTaskCreated(asITelemetryService(t), {
			ulid: "ulid-smoke-task-1",
			apiProvider: "anthropic",
		});
		dumpEvents(t.events);
		const created = t.events.filter((e) => e.name === "task.created");
		console.log(
			`emitted ${created.length} task.created event(s); expected exactly 1.`,
		);
		assertSmoke("task.created count", created.length, 1);
	}

	header("task.restarted (sibling event when an existing task is resumed)");
	{
		const t = new CapturingTelemetry();
		captureTaskRestarted(asITelemetryService(t), {
			ulid: "ulid-smoke-task-1",
			apiProvider: "anthropic",
		});
		dumpEvents(t.events);
		const restarted = t.events.filter((e) => e.name === "task.restarted");
		console.log(
			`emitted ${restarted.length} task.restarted event(s); expected exactly 1.`,
		);
		assertSmoke("task.restarted count", restarted.length, 1);
	}

	header("task.conversation_turn (user + assistant turns)");
	{
		const t = new CapturingTelemetry();
		const tSvc = asITelemetryService(t);
		captureConversationTurnEvent(tSvc, {
			ulid: "ulid-smoke-task-1",
			provider: "anthropic",
			model: "claude-sonnet-4-5",
			source: "user",
			mode: "act",
		});
		captureConversationTurnEvent(tSvc, {
			ulid: "ulid-smoke-task-1",
			provider: "anthropic",
			model: "claude-sonnet-4-5",
			source: "assistant",
			mode: "act",
		});
		dumpEvents(t.events);
		const turns = t.events.filter((e) => e.name === "task.conversation_turn");
		const userTurns = turns.filter((e) => e.properties?.source === "user");
		const assistantTurns = turns.filter(
			(e) => e.properties?.source === "assistant",
		);
		const allHaveTimestamp = turns.every(
			(e) => typeof e.properties?.timestamp === "string",
		);
		console.log(
			`emitted ${turns.length} task.conversation_turn event(s); expected 2 (1 user + 1 assistant).`,
		);
		console.log(
			`  user=${userTurns.length} assistant=${assistantTurns.length} all_have_timestamp=${allHaveTimestamp}`,
		);
		assertSmoke("task.conversation_turn count", turns.length, 2);
		assertSmoke("task.conversation_turn user count", userTurns.length, 1);
		assertSmoke(
			"task.conversation_turn assistant count",
			assistantTurns.length,
			1,
		);
		assertSmoke(
			"task.conversation_turn timestamps populated",
			allHaveTimestamp,
			true,
		);
	}

	header(
		"task.completed source=submit_and_exit (assistant declared completion)",
	);
	{
		const t = new CapturingTelemetry();
		captureTaskCompleted(asITelemetryService(t), {
			ulid: "ulid-smoke-task-1",
			provider: "anthropic",
			modelId: "claude-sonnet-4-5",
			mode: "act",
			durationMs: 12_345,
			source: "submit_and_exit",
		});
		dumpEvents(t.events);
		const completed = t.events.filter((e) => e.name === "task.completed");
		const submitSourced = completed.filter(
			(e) => e.properties?.source === "submit_and_exit",
		);
		console.log(
			`emitted ${completed.length} task.completed event(s); expected 1 with source="submit_and_exit" (got ${submitSourced.length}).`,
		);
		assertSmoke("task.completed (submit_and_exit) count", completed.length, 1);
		assertSmoke(
			"task.completed source=submit_and_exit count",
			submitSourced.length,
			1,
		);
	}

	header(
		"task.completed source=shutdown (non-interactive fallback when submit_and_exit was not observed)",
	);
	{
		const t = new CapturingTelemetry();
		captureTaskCompleted(asITelemetryService(t), {
			ulid: "ulid-smoke-task-2",
			provider: "anthropic",
			modelId: "claude-sonnet-4-5",
			mode: "act",
			durationMs: 9_876,
			source: "shutdown",
		});
		dumpEvents(t.events);
		const completed = t.events.filter((e) => e.name === "task.completed");
		const shutdownSourced = completed.filter(
			(e) => e.properties?.source === "shutdown",
		);
		console.log(
			`emitted ${completed.length} task.completed event(s); expected 1 with source="shutdown" (got ${shutdownSourced.length}).`,
		);
		assertSmoke("task.completed (shutdown) count", completed.length, 1);
		assertSmoke(
			"task.completed source=shutdown count",
			shutdownSourced.length,
			1,
		);
	}

	header(
		"task lifecycle in order: created → conversation_turn × 2 → completed (single capturing telemetry)",
	);
	{
		const t = new CapturingTelemetry();
		const tSvc = asITelemetryService(t);
		const ulid = "ulid-smoke-task-lifecycle";
		captureTaskCreated(tSvc, {
			ulid,
			apiProvider: "anthropic",
		});
		captureConversationTurnEvent(tSvc, {
			ulid,
			provider: "anthropic",
			model: "claude-sonnet-4-5",
			source: "user",
			mode: "act",
		});
		captureConversationTurnEvent(tSvc, {
			ulid,
			provider: "anthropic",
			model: "claude-sonnet-4-5",
			source: "assistant",
			mode: "act",
		});
		captureTaskCompleted(tSvc, {
			ulid,
			provider: "anthropic",
			modelId: "claude-sonnet-4-5",
			mode: "act",
			durationMs: 4_242,
			source: "submit_and_exit",
		});
		dumpEvents(t.events);
		const order = t.events.map((e) => e.name);
		const expectedOrder = [
			"task.created",
			"task.conversation_turn",
			"task.conversation_turn",
			"task.completed",
		];
		const orderOk =
			order.length === expectedOrder.length &&
			order.every((name, idx) => name === expectedOrder[idx]);
		console.log(
			`event order: [${order.join(", ")}]; expected [${expectedOrder.join(", ")}]; ok=${orderOk}.`,
		);
		assertSmoke("task lifecycle event order", orderOk, true);
	}

	header("Done");
}

main().catch((err) => {
	console.error("smoke test failed:", err);
	process.exitCode = 1;
});

import { execFileSync } from "node:child_process";
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { beforeEach, describe, expect, it, vi } from "vitest";
import type { ClineCoreStartInput } from "./cline-core/types";
import type {
	StartSessionInput,
	StartSessionResult,
} from "./runtime/host/runtime-host";

const { createRuntimeHostMock } = vi.hoisted(() => ({
	createRuntimeHostMock: vi.fn(),
}));

vi.mock("./runtime/host/host", () => ({
	createRuntimeHost: createRuntimeHostMock,
}));

import type { AgentResult } from "@cline/shared";
import { ClineCore } from "./ClineCore";
import { NoOpFeatureFlagsProvider } from "./services/feature-flags";

function createStartInput(): ClineCoreStartInput {
	return {
		config: {
			providerId: "anthropic",
			modelId: "claude-sonnet-4-6",
			apiKey: "test",
			cwd: "/tmp/workspace",
			workspaceRoot: "/tmp/workspace",
			systemPrompt: "You are concise.",
			mode: "act",
			enableTools: true,
			enableSpawnAgent: false,
			enableAgentTeams: false,
		},
		prompt: "hello",
		interactive: false,
	};
}

function createStartResult(sessionId: string): StartSessionResult {
	return {
		sessionId,
		manifest: {} as StartSessionResult["manifest"],
		manifestPath: `/tmp/${sessionId}.json`,
		messagesPath: `/tmp/${sessionId}.messages.json`,
	};
}

function createAgentResult(text: string): AgentResult {
	const now = new Date("2026-04-24T10:00:00.000Z");
	return {
		text,
		usage: {
			inputTokens: 1,
			outputTokens: 1,
		},
		messages: [],
		toolCalls: [],
		iterations: 1,
		finishReason: "completed",
		model: {
			id: "test-model",
			provider: "test-provider",
		},
		startedAt: now,
		endedAt: now,
		durationMs: 1,
	};
}

function git(cwd: string, args: string[]): string {
	return execFileSync("git", ["-C", cwd, ...args], {
		encoding: "utf8",
	}).trim();
}

describe("ClineCore", () => {
	beforeEach(() => {
		createRuntimeHostMock.mockReset();
	});

	it("compares a checkpoint to the current workspace through the public SDK API", async () => {
		const dir = mkdtempSync(join(tmpdir(), "cline-core-compare-"));
		let core: ClineCore | undefined;
		try {
			git(dir, ["init", "-b", "main"]);
			git(dir, ["config", "user.email", "test@example.com"]);
			git(dir, ["config", "user.name", "Test User"]);
			writeFileSync(join(dir, "tracked.txt"), "before\n", "utf8");
			git(dir, ["add", "."]);
			git(dir, ["commit", "-m", "initial"]);
			const checkpointRef = git(dir, ["rev-parse", "HEAD"]);
			writeFileSync(join(dir, "tracked.txt"), "after\n", "utf8");

			const host = {
				runtimeAddress: undefined,
				startSession: vi.fn(),
				runTurn: vi.fn(),
				restoreSession: vi.fn(),
				getAccumulatedUsage: vi.fn(),
				abort: vi.fn(),
				stopSession: vi.fn(),
				dispose: vi.fn(),
				getSession: vi.fn(async () => ({
					sessionId: "session-1",
					cwd: dir,
					workspaceRoot: dir,
					metadata: {
						checkpoint: {
							history: [
								{
									ref: checkpointRef,
									runCount: 1,
									createdAt: 1,
									kind: "commit",
								},
							],
						},
					},
				})),
				listSessions: vi.fn(),
				deleteSession: vi.fn(),
				updateSession: vi.fn(),
				readSessionMessages: vi.fn(),
				dispatchHookEvent: vi.fn(),
				subscribe: vi.fn(() => () => {}),
				updateSessionModel: vi.fn(),
			};
			createRuntimeHostMock.mockResolvedValue(host);

			core = await ClineCore.create();
			const result = await core.compareCheckpoint({
				sessionId: "session-1",
				checkpointRunCount: 1,
			});

			expect(host.getSession).toHaveBeenCalledWith("session-1");
			expect(result.checkpoint.ref).toBe(checkpointRef);
			expect(result.diffs).toEqual([
				{
					filePath: join(dir, "tracked.txt"),
					leftContent: "before\n",
					rightContent: "after\n",
				},
			]);
		} finally {
			await core?.dispose();
			rmSync(dir, { recursive: true, force: true });
		}
	});

	it("applies start-session bootstraps before delegating to the host", async () => {
		const listeners: Array<
			(event: { type: string; payload: { sessionId: string } }) => void
		> = [];
		const host = {
			runtimeAddress: undefined,
			startSession: vi.fn(async (input: StartSessionInput) => {
				expect(input.config.systemPrompt).toBe("Bootstrapped prompt");
				expect(input.localRuntime?.extensions).toEqual([
					expect.objectContaining({ name: "enterprise" }),
				]);
				return createStartResult("session-1");
			}),
			runTurn: vi.fn(),
			getAccumulatedUsage: vi.fn(),
			abort: vi.fn(),
			stopSession: vi.fn(),
			dispose: vi.fn(),
			getSession: vi.fn(async () => undefined),
			listSessions: vi.fn(),
			deleteSession: vi.fn(),
			readSessionMessages: vi.fn(),
			subscribe: vi.fn((listener) => {
				listeners.push(listener);
				return () => {};
			}),
			updateSessionModel: vi.fn(),
		};
		createRuntimeHostMock.mockResolvedValue(host);

		const dispose = vi.fn(async () => {});
		const applyToStartSessionInput = vi.fn(
			async (input: ClineCoreStartInput) => ({
				...input,
				config: {
					...input.config,
					systemPrompt: "Bootstrapped prompt",
					extensions: [
						{
							name: "enterprise",
							manifest: { capabilities: [] },
							setup: vi.fn(),
						},
					],
				},
			}),
		);

		const core = await ClineCore.create({
			prepare: async () => ({
				applyToStartSessionInput,
				dispose,
			}),
		});

		await core.start(createStartInput());

		expect(applyToStartSessionInput).toHaveBeenCalledTimes(1);
		expect(host.startSession).toHaveBeenCalledTimes(1);
		expect(dispose).toHaveBeenCalledTimes(1);
		expect(listeners).toHaveLength(1);
	});

	it("preserves an omitted workspace until the execution host resolves it", async () => {
		const host = {
			runtimeAddress: undefined,
			startSession: vi.fn(async (_input: StartSessionInput) =>
				createStartResult("session-pathless"),
			),
			runTurn: vi.fn(),
			getAccumulatedUsage: vi.fn(),
			abort: vi.fn(),
			stopSession: vi.fn(),
			dispose: vi.fn(),
			getSession: vi.fn(async () => undefined),
			listSessions: vi.fn(),
			deleteSession: vi.fn(),
			readSessionMessages: vi.fn(),
			subscribe: vi.fn(() => () => {}),
			updateSessionModel: vi.fn(),
		};
		createRuntimeHostMock.mockResolvedValue(host);
		const core = await ClineCore.create();

		await core.start({
			config: {
				providerId: "anthropic",
				modelId: "claude-sonnet-4-6",
				apiKey: "test",
				systemPrompt: "You are concise.",
				mode: "act",
				enableTools: true,
				enableSpawnAgent: false,
				enableAgentTeams: false,
			},
		});

		expect(host.startSession).toHaveBeenCalledTimes(1);
		const forwarded = host.startSession.mock.calls[0]?.[0];
		expect(forwarded?.config).not.toHaveProperty("cwd");
		expect(forwarded?.config).not.toHaveProperty("workspaceRoot");
	});

	it("disposes active session bootstraps when the session ends", async () => {
		let listener:
			| ((event: { type: string; payload: { sessionId: string } }) => void)
			| undefined;
		const host = {
			runtimeAddress: "127.0.0.1:5317",
			startSession: vi.fn(async () => createStartResult("session-2")),
			runTurn: vi.fn(),
			getAccumulatedUsage: vi.fn(),
			abort: vi.fn(),
			stopSession: vi.fn(),
			dispose: vi.fn(),
			getSession: vi.fn(async () => ({ sessionId: "session-2" })),
			listSessions: vi.fn(),
			deleteSession: vi.fn(),
			readSessionMessages: vi.fn(),
			subscribe: vi.fn((nextListener) => {
				listener = nextListener;
				return () => {};
			}),
			updateSessionModel: vi.fn(),
		};
		createRuntimeHostMock.mockResolvedValue(host);

		const dispose = vi.fn(async () => {});
		const core = await ClineCore.create({
			prepare: async () => ({
				applyToStartSessionInput: (input) => input,
				dispose,
			}),
		});
		expect(core.runtimeAddress).toBe("127.0.0.1:5317");

		await core.start(createStartInput());
		expect(dispose).not.toHaveBeenCalled();

		listener?.({ type: "ended", payload: { sessionId: "session-2" } });
		await Promise.resolve();

		expect(dispose).toHaveBeenCalledTimes(1);
	});

	it("emits session.started telemetry when a new session is started", async () => {
		const host = {
			runtimeAddress: undefined,
			startSession: vi.fn(async () => createStartResult("session-telemetry")),
			runTurn: vi.fn(),
			getAccumulatedUsage: vi.fn(),
			abort: vi.fn(),
			stopSession: vi.fn(),
			dispose: vi.fn(),
			getSession: vi.fn(async () => undefined),
			listSessions: vi.fn(),
			deleteSession: vi.fn(),
			readSessionMessages: vi.fn(),
			subscribe: vi.fn(() => () => {}),
			updateSessionModel: vi.fn(),
		};
		createRuntimeHostMock.mockResolvedValue(host);

		const telemetry = {
			capture: vi.fn(),
			captureRequired: vi.fn(),
			setDistinctId: vi.fn(),
			setMetadata: vi.fn(),
			updateCommonProperties: vi.fn(),
			isEnabled: vi.fn(() => true),
			recordCounter: vi.fn(),
			recordHistogram: vi.fn(),
			recordGauge: vi.fn(),
			flush: vi.fn().mockResolvedValue(undefined),
			dispose: vi.fn().mockResolvedValue(undefined),
		};

		const core = await ClineCore.create({
			backendMode: "local",
			clientName: "unit-test-client",
			telemetry: telemetry as never,
		});
		await core.start(createStartInput());

		expect(telemetry.capture).toHaveBeenCalledWith(
			expect.objectContaining({
				event: "session.started",
				properties: expect.objectContaining({
					sessionId: "session-telemetry",
					source: "core",
					providerId: "anthropic",
					modelId: "claude-sonnet-4-6",
					enableTools: true,
					enableSpawnAgent: false,
					enableAgentTeams: false,
					clientName: "unit-test-client",
				}),
			}),
		);
	});

	it("merges instance and per-start runtime capabilities", async () => {
		const host = {
			runtimeAddress: undefined,
			startSession: vi.fn(async (_input: StartSessionInput) =>
				createStartResult("session-capabilities"),
			),
			runTurn: vi.fn(),
			getAccumulatedUsage: vi.fn(),
			abort: vi.fn(),
			stopSession: vi.fn(),
			dispose: vi.fn(),
			getSession: vi.fn(async () => undefined),
			listSessions: vi.fn(),
			deleteSession: vi.fn(),
			readSessionMessages: vi.fn(),
			subscribe: vi.fn(() => () => {}),
			updateSessionModel: vi.fn(),
		};
		createRuntimeHostMock.mockResolvedValue(host);
		const askQuestion = vi.fn(async () => "yes");
		const submit = vi.fn(async () => "submitted");
		const requestToolApproval = vi.fn(async () => ({ approved: true }));

		const core = await ClineCore.create({
			capabilities: {
				toolExecutors: { askQuestion },
				requestToolApproval,
			},
		});

		await core.start({
			...createStartInput(),
			capabilities: {
				toolExecutors: { submit },
			},
		});

		const startInput = vi.mocked(host.startSession).mock.calls.at(-1)?.[0] as
			| StartSessionInput
			| undefined;
		expect(startInput).toBeDefined();
		if (!startInput) throw new Error("Expected host.startSession to be called");
		expect(startInput.capabilities?.toolExecutors).toMatchObject({
			askQuestion,
			submit,
		});
		expect(startInput.capabilities?.requestToolApproval).toBe(
			requestToolApproval,
		);
	});

	it("normalizes config extension context into local runtime before delegating to the host", async () => {
		const host = {
			runtimeAddress: undefined,
			startSession: vi.fn(async (_input: StartSessionInput) =>
				createStartResult("session-extension-context"),
			),
			runTurn: vi.fn(),
			getAccumulatedUsage: vi.fn(),
			abort: vi.fn(),
			stopSession: vi.fn(),
			dispose: vi.fn(),
			getSession: vi.fn(async () => undefined),
			listSessions: vi.fn(),
			deleteSession: vi.fn(),
			readSessionMessages: vi.fn(),
			subscribe: vi.fn(() => () => {}),
			updateSessionModel: vi.fn(),
		};
		createRuntimeHostMock.mockResolvedValue(host);

		const onTeamRestored = vi.fn();
		const clientContext = {
			name: "VSCode Extension",
			version: "3.27.0",
			platform: "Visual Studio Code",
			platformVersion: "1.102.3",
			isMultiRoot: true,
		};
		const core = await ClineCore.create();

		await core.start({
			...createStartInput(),
			config: {
				...createStartInput().config,
				extensionContext: {
					client: clientContext,
				},
			},
			localRuntime: {
				onTeamRestored,
			},
		});

		const startInput = vi.mocked(host.startSession).mock.calls.at(-1)?.[0] as
			| StartSessionInput
			| undefined;
