import {
	decodeJwtPayload,
	getClineEnvironmentConfig,
	type ITelemetryService,
} from "@cline/shared";
import type { ProviderSettingsManager } from "../services/storage/provider-settings-manager";
import type { ProviderSettings } from "../types/provider-settings";
import {
	type ClineOAuthCredentials,
	getValidClineCredentials,
	loginClineOAuth,
} from "./cline";
import { getValidOpenAICodexCredentials, loginOpenAICodex } from "./codex";
import { getValidOcaCredentials, loginOcaOAuth } from "./oca";
import type { OAuthCredentials, OAuthLoginCallbacks } from "./types";

const WORKOS_TOKEN_PREFIX = "workos:";

export type ProviderOAuthCredentials = OAuthCredentials;

export interface ProviderAuthLoginInput {
	settings?: ProviderSettings;
	callbacks: OAuthLoginCallbacks;
	telemetry?: ITelemetryService;
}

export interface ProviderAuthRefreshInput {
	settings: ProviderSettings;
	credentials: ProviderOAuthCredentials;
	forceRefresh?: boolean;
	telemetry?: ITelemetryService;
}

export interface ProviderAuthSaveCredentialsInput {
	manager: ProviderSettingsManager;
	settings?: ProviderSettings;
	credentials: ProviderOAuthCredentials;
	setLastUsed?: boolean;
	save?: boolean;
}

export interface ProviderAuthHandler {
	providerId: string;
	storageProviderId: string;
	getApiKey(settings: ProviderSettings | undefined): string | undefined;
	login(input: ProviderAuthLoginInput): Promise<ProviderOAuthCredentials>;
	refresh(
		input: ProviderAuthRefreshInput,
	): Promise<ProviderOAuthCredentials | null>;
	saveCredentials(input: ProviderAuthSaveCredentialsInput): ProviderSettings;
	isConfigured(settings: ProviderSettings | undefined): boolean;
	normalizeStoredAccessToken?(accessToken: string): string;
}

function formatClineApiKey(accessToken: string): string {
	const token = accessToken.trim();
	return token.toLowerCase().startsWith(WORKOS_TOKEN_PREFIX)
		? token
		: `${WORKOS_TOKEN_PREFIX}${token}`;
}

function stripClineApiKeyPrefix(accessToken: string): string {
	const token = accessToken.trim();
	return token.toLowerCase().startsWith(WORKOS_TOKEN_PREFIX)
		? token.slice(WORKOS_TOKEN_PREFIX.length)
		: token;
}

function readExpiryFromToken(accessToken: string): number | null {
	const payload = decodeJwtPayload(accessToken);
	const exp = payload?.exp;
	if (typeof exp === "number" && exp > 0) {
		return exp * 1000;
	}
	return null;
}

function deriveCredentialExpiry(
	settings: ProviderSettings,
	normalizedAccessToken: string,
): number {
	const explicitExpiry = settings.auth?.expiresAt;
	if (
		typeof explicitExpiry === "number" &&
		Number.isFinite(explicitExpiry) &&
		explicitExpiry > 0
	) {
		return explicitExpiry;
	}

	const jwtExpiry = readExpiryFromToken(normalizedAccessToken);
	if (jwtExpiry) {
		return jwtExpiry;
	}

	// Unknown expiry should trigger refresh on next resolution.
	return Date.now() - 1;
}

function createCredentialsFromSettings(
	settings: ProviderSettings,
	options?: { normalizeAccessToken?: (accessToken: string) => string },
): ProviderOAuthCredentials | null {
	const rawAccess = settings.auth?.accessToken?.trim();
	const refreshToken = settings.auth?.refreshToken?.trim();
	if (!rawAccess || !refreshToken) {
		return null;
	}
	const access = options?.normalizeAccessToken?.(rawAccess) ?? rawAccess;
	if (!access) {
		return null;
	}

	return {
		access,
		refresh: refreshToken,
		expires: deriveCredentialExpiry(settings, access),
		accountId: settings.auth?.accountId,
		metadata: settings.auth?.metadata,
	};
}

function saveOAuthCredentials(input: {
	manager: ProviderSettingsManager;
	storageProviderId: string;
	settings?: ProviderSettings;
	credentials: ProviderOAuthCredentials;
	formatAccessToken?: (accessToken: string) => string;
	setLastUsed?: boolean;
	save?: boolean;
}): ProviderSettings {
	const accessToken =
		input.formatAccessToken?.(input.credentials.access) ??
		input.credentials.access;
	const auth: NonNullable<ProviderSettings["auth"]> = {
		...(input.settings?.auth ?? {}),
		accessToken,
		refreshToken: input.credentials.refresh,
		accountId: input.credentials.accountId,
		expiresAt: input.credentials.expires,
	};
	const incomingMetadata = Object.fromEntries(
		Object.entries(input.credentials.metadata ?? {}).filter(
			([, value]) => value !== undefined,
		),
	);
	const metadata = {
		...(input.settings?.auth?.metadata ?? {}),
		...incomingMetadata,
	};
	if (Object.keys(metadata).length > 0) {
		auth.metadata = metadata;
	}

	const merged: ProviderSettings = {
		...(input.settings ?? {
			provider: input.storageProviderId as ProviderSettings["provider"],
		}),
		provider: input.storageProviderId as ProviderSettings["provider"],
		auth,
	};
	if (input.save !== false) {
		input.manager.saveProviderSettings(merged, {
			...(input.setLastUsed === undefined
				? {}
				: { setLastUsed: input.setLastUsed }),
			tokenSource: "oauth",
		});
	}
	return merged;
}

function createOAuthHandler(input: {
	providerId: string;
	storageProviderId?: string;
	formatAccessToken?: (accessToken: string) => string;
	normalizeStoredAccessToken?: (accessToken: string) => string;
	login: (input: ProviderAuthLoginInput) => Promise<ProviderOAuthCredentials>;
	refresh: (
		input: ProviderAuthRefreshInput,
	) => Promise<ProviderOAuthCredentials | null>;
}): ProviderAuthHandler {
	const storageProviderId = input.storageProviderId ?? input.providerId;
	return {
		providerId: input.providerId,
		storageProviderId,
		getApiKey(settings) {
			const accessToken = settings?.auth?.accessToken?.trim();
			if (accessToken) {
				return input.formatAccessToken?.(accessToken) ?? accessToken;
			}

			return (
				settings?.apiKey?.trim() || settings?.auth?.apiKey?.trim() || undefined
			);
		},
		login: input.login,
		refresh: input.refresh,
		saveCredentials(saveInput) {
			return saveOAuthCredentials({
				...saveInput,
				storageProviderId,
				formatAccessToken: input.formatAccessToken,
			});
		},
		isConfigured(settings) {
			return !!settings?.auth?.accessToken;
		},
		normalizeStoredAccessToken: input.normalizeStoredAccessToken,
	};
}

function createClineAuthHandler(input: {
	providerId: string;
	storageProviderId?: string;
}): ProviderAuthHandler {
	return createOAuthHandler({
		providerId: input.providerId,
		storageProviderId: input.storageProviderId,
		formatAccessToken: formatClineApiKey,
		normalizeStoredAccessToken: stripClineApiKeyPrefix,
		login: ({ settings, callbacks, telemetry }) =>
			loginClineOAuth({
				apiBaseUrl:
					settings?.baseUrl?.trim() || getClineEnvironmentConfig().apiBaseUrl,
				useWorkOSDeviceAuth: true,
				callbacks,
				telemetry,
			}),
		refresh: ({ settings, credentials, forceRefresh, telemetry }) =>
			getValidClineCredentials(
				credentials as ClineOAuthCredentials,
				{
					apiBaseUrl:
						settings.baseUrl?.trim() || getClineEnvironmentConfig().apiBaseUrl,
					telemetry,
				},
				{ forceRefresh },
			),
	});
}

const providerAuthHandlers = [
	createClineAuthHandler({ providerId: "cline" }),
	createClineAuthHandler({
		providerId: "cline-pass",
		storageProviderId: "cline",
	}),
	createOAuthHandler({
		providerId: "oca",
		login: ({ settings, callbacks, telemetry }) =>
			loginOcaOAuth({ mode: settings?.oca?.mode, callbacks, telemetry }),
		refresh: ({ settings, credentials, forceRefresh, telemetry }) =>
			getValidOcaCredentials(
				credentials,
				{ forceRefresh, telemetry },
				{ mode: settings.oca?.mode, telemetry },
			),
	}),
	createOAuthHandler({
		providerId: "openai-codex",
		login: ({ callbacks, telemetry }) =>
			loginOpenAICodex({
				onAuth: callbacks.onAuth,
				onPrompt: callbacks.onPrompt,
				onProgress: callbacks.onProgress,
				onManualCodeInput: callbacks.onManualCodeInput,
				telemetry,
			}),
		refresh: ({ credentials, forceRefresh, telemetry }) =>
			getValidOpenAICodexCredentials(credentials, { forceRefresh, telemetry }),
	}),
] as const satisfies readonly ProviderAuthHandler[];

const providerAuthHandlerById = new Map<string, ProviderAuthHandler>(
	providerAuthHandlers.map((handler) => [handler.providerId, handler]),
);

export function getProviderAuthHandler(
	providerId: string,
): ProviderAuthHandler | undefined {
	return providerAuthHandlerById.get(providerId.trim().toLowerCase());
}

export function isOAuthProvider(providerId: string): boolean {
	return getProviderAuthHandler(providerId) !== undefined;
}

export function getProviderAuthStorageId(
	providerId: string,
): string | undefined {
	return getProviderAuthHandler(providerId)?.storageProviderId;
}

export function resolveProviderApiKeyFromSettings(
	manager: ProviderSettingsManager,
	providerId: string,
): string | undefined {
	const handler = getProviderAuthHandler(providerId);
	const storageProviderId = handler?.storageProviderId ?? providerId;
	const settings = manager.getProviderSettings(storageProviderId);
	return (
		handler?.getApiKey(settings) ??
		getPersistedProviderApiKey(providerId, settings)
	);
}

export async function loginAndSaveProviderOAuthCredentials(
	manager: ProviderSettingsManager,
	providerId: string,
	input: {
		callbacks: OAuthLoginCallbacks;
		telemetry?: ITelemetryService;
	},
): Promise<ProviderSettings> {
	const handler = getProviderAuthHandler(providerId);
	if (!handler) {
		throw new Error(`Provider "${providerId}" does not support OAuth login`);
	}
	const existing = manager.getProviderSettings(handler.storageProviderId);
	const credentials = await handler.login({
		settings: existing,
		callbacks: input.callbacks,
		telemetry: input.telemetry,
	});
	return handler.saveCredentials({ manager, settings: existing, credentials });
}

export function getProviderOAuthCredentialsFromSettings(
	providerId: string,
	settings: ProviderSettings,
): ProviderOAuthCredentials | null {
	const handler = getProviderAuthHandler(providerId);
	if (!handler) return null;
	return createCredentialsFromSettings(settings, {
		normalizeAccessToken: handler.normalizeStoredAccessToken,
	});
}

export function saveProviderOAuthCredentials(input: {
	manager: ProviderSettingsManager;
	providerId: string;
	settings?: ProviderSettings;
	credentials: ProviderOAuthCredentials;
	setLastUsed?: boolean;
	save?: boolean;
}): ProviderSettings {
	const handler = getProviderAuthHandler(input.providerId);
	if (!handler) {
		throw new Error(
			`Provider "${input.providerId}" does not support OAuth credentials`,
		);
	}
	return handler.saveCredentials({
		manager: input.manager,
		settings: input.settings,
		credentials: input.credentials,
		setLastUsed: input.setLastUsed,
		save: input.save,
	});
}

export function getPersistedProviderApiKey(
	providerId: string,
	settings?: ProviderSettings,
): string | undefined {
	const handler = getProviderAuthHandler(providerId);
	if (handler) {
		return handler.getApiKey(settings);
	}

	return (
		settings?.auth?.accessToken?.trim() ||
		settings?.apiKey?.trim() ||
		settings?.auth?.apiKey?.trim() ||
		undefined
	);
}

export function formatProviderOAuthApiKey(
	providerId: string,
	credentials: Pick<ProviderOAuthCredentials, "access">,
): string {
	const handler = getProviderAuthHandler(providerId);
	if (!handler) return credentials.access;

	return (
		handler.getApiKey({
			provider: handler.storageProviderId,
			auth: { accessToken: credentials.access },
		}) ?? credentials.access
	);
}

import http from "node:http";
import net from "node:net";
import { afterEach, describe, expect, it, vi } from "vitest";
import { startLocalOAuthServer } from "./server";

const socketBindingSupported = await (async () => {
	try {
		const srv = net.createServer();
		await new Promise<void>((resolve, reject) => {
			srv.listen(0, "127.0.0.1", () => resolve());
			srv.once("error", reject);
		});
		await new Promise<void>((resolve, reject) =>
			srv.close((err) => (err ? reject(err) : resolve())),
		);
		return true;
	} catch {
		return false;
	}
})();
const socketIt = socketBindingSupported ? it : it.skip;

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Bind to port 0 to let the OS pick a free port, then release it. */
function getFreePort(): Promise<number> {
	return new Promise((resolve, reject) => {
		const srv = net.createServer();
		srv.listen(0, "127.0.0.1", () => {
			const addr = srv.address() as net.AddressInfo;
			srv.close(() => resolve(addr.port));
		});
		srv.on("error", reject);
	});
}

/** Occupy a port so the OAuth server cannot bind to it. */
function occupyPort(port: number): Promise<http.Server> {
	return new Promise((resolve, reject) => {
		const srv = http.createServer();
		srv.listen(port, "127.0.0.1", () => resolve(srv));
		srv.on("error", reject);
	});
}

/** Close an http.Server, resolving when the socket is gone. */
function closeServer(srv: http.Server): Promise<void> {
	return new Promise((resolve, reject) =>
		srv.close((err) => (err ? reject(err) : resolve())),
	);
}

/** Make a GET request and return status + body. */
function get(url: string): Promise<{ status: number; body: string }> {
	return new Promise((resolve, reject) => {
		http
			.get(url, (res) => {
				let body = "";
				res.on("data", (chunk: Buffer) => {
					body += chunk.toString();
				});
				res.on("end", () => resolve({ status: res.statusCode ?? 0, body }));
			})
			.on("error", reject);
	});
}

/** Flush microtasks + a short macro-task delay for fire-and-forget promises. */
function flushAsync(): Promise<void> {
	return new Promise((resolve) => setTimeout(resolve, 20));
}

// ---------------------------------------------------------------------------
// onListening
// ---------------------------------------------------------------------------

describe("auth/server startLocalOAuthServer — onListening", () => {
	socketIt(
		"is called with host, port, and callbackUrl when the server binds",
		async () => {
			const port = await getFreePort();
			const onListening = vi.fn();

			const server = await startLocalOAuthServer({
				ports: [port],
				callbackPath: "/callback",
				onListening,
			});

			expect(onListening).toHaveBeenCalledOnce();
			expect(onListening).toHaveBeenCalledWith({
				host: "127.0.0.1",
				port,
				callbackUrl: `http://127.0.0.1:${port}/callback`,
			});

			server.close();
		},
	);

	socketIt("is not called when no port can be bound", async () => {
		const port = await getFreePort();
		const blocker = await occupyPort(port);
		const onListening = vi.fn();

		await startLocalOAuthServer({
			ports: [port],
			callbackPath: "/callback",
			onListening,
		});

		expect(onListening).not.toHaveBeenCalled();

		await closeServer(blocker);
	});

	socketIt(
		"fires for the first available port and skips occupied ones",
		async () => {
			const [port1, port2] = await Promise.all([getFreePort(), getFreePort()]);
			const blocker = await occupyPort(port1);
			const onListening = vi.fn();

			const server = await startLocalOAuthServer({
				ports: [port1, port2],
				callbackPath: "/cb",
				onListening,
			});

			expect(onListening).toHaveBeenCalledOnce();
			expect(onListening).toHaveBeenCalledWith(
				expect.objectContaining({ port: port2 }),
			);

			server.close();
			await closeServer(blocker);
		},
	);

	socketIt("swallows errors thrown by the onListening callback", async () => {
		const port = await getFreePort();
		const onListening = vi
			.fn()
			.mockReturnValue(Promise.reject(new Error("listening boom")));

		const server = await startLocalOAuthServer({
			ports: [port],
			callbackPath: "/callback",
			onListening,
		});

		await flushAsync();
		expect(onListening).toHaveBeenCalledOnce();

		server.close();
	});
});

// ---------------------------------------------------------------------------
// onClose
// ---------------------------------------------------------------------------

describe("auth/server startLocalOAuthServer — onClose", () => {
	socketIt("is called with host and port when close() is invoked", async () => {
		const port = await getFreePort();
		const onClose = vi.fn();

		const server = await startLocalOAuthServer({
			ports: [port],
			callbackPath: "/callback",
			onClose,
		});

		server.close();

		expect(onClose).toHaveBeenCalledOnce();
		expect(onClose).toHaveBeenCalledWith({ host: "127.0.0.1", port });
	});

	socketIt(
		"is called with host and port when cancelWait() is invoked",
		async () => {
			const port = await getFreePort();
			const onClose = vi.fn();

			const server = await startLocalOAuthServer({
				ports: [port],
				callbackPath: "/callback",
				onClose,
			});

			server.cancelWait();

			expect(onClose).toHaveBeenCalledOnce();
			expect(onClose).toHaveBeenCalledWith({ host: "127.0.0.1", port });
		},
	);

	socketIt("is called after a successful OAuth callback request", async () => {
		const port = await getFreePort();
		const onClose = vi.fn();

		const server = await startLocalOAuthServer({
			ports: [port],
			callbackPath: "/callback",
			onClose,
		});

		const waitPromise = server.waitForCallback();
		const { status } = await get(
			`http://127.0.0.1:${port}/callback?code=tok123`,
		);
		expect(status).toBe(200);

		await waitPromise;

		expect(onClose).toHaveBeenCalledOnce();
		expect(onClose).toHaveBeenCalledWith({ host: "127.0.0.1", port });
	});

	socketIt("is not called when no port was bound", async () => {
		const port = await getFreePort();
		const blocker = await occupyPort(port);
		const onClose = vi.fn();

		const server = await startLocalOAuthServer({
			ports: [port],
			callbackPath: "/callback",
			onClose,
		});

		server.close();
		expect(onClose).not.toHaveBeenCalled();

		await closeServer(blocker);
	});

	socketIt("swallows errors thrown by the onClose callback", async () => {
		const port = await getFreePort();
		const onClose = vi
			.fn()
			.mockReturnValue(Promise.reject(new Error("teardown failed")));

		const server = await startLocalOAuthServer({
			ports: [port],
			callbackPath: "/callback",
			onClose,
		});

		server.close();
		await flushAsync();

		expect(onClose).toHaveBeenCalledOnce();
	});
});

// ---------------------------------------------------------------------------
// Sequential flows on a fixed port (keep-alive socket teardown)
// ---------------------------------------------------------------------------

describe("auth/server startLocalOAuthServer — sequential flows on a fixed port", () => {
	// A browser / global-fetch connection pool keeps a keep-alive socket to the
	// callback port alive across requests. If close() left those sockets open, a
	// later request to a re-bound port could be delivered over the pooled socket
	// to the first (already-settled) server, and that flow's waitForCallback()
	// would never resolve. close() must therefore drop lingering connections.
	socketIt(
		"does not serve requests over a pooled keep-alive socket after close()",
		async () => {
			const port = await getFreePort();

			// A keep-alive agent models the browser / global-fetch connection pool,
			// which keeps a socket to the fixed callback port alive across requests.
			const agent = new http.Agent({ keepAlive: true, maxSockets: 1 });
			const getOverAgent = (path: string) =>
				new Promise<{ status: number } | { error: string }>((resolve) => {
					const req = http.get(
						{ host: "127.0.0.1", port, path, agent },
						(res) => {
							res.on("data", () => {});
							res.on("end", () => resolve({ status: res.statusCode ?? 0 }));
						},
					);
					req.on("error", (e) =>
						resolve({ error: (e as NodeJS.ErrnoException).code ?? e.message }),
					);
				});

			// First flow: deny. The 400 response leaves a pooled keep-alive socket
			// attached to THIS server.
			const first = await startLocalOAuthServer({
				ports: [port],
				callbackPath: "/callback",
			});
			const firstWait = first.waitForCallback();
			expect(await getOverAgent("/callback?error=access_denied")).toMatchObject(
				{ status: 400 },
			);
			expect((await firstWait)?.error).toBe("access_denied");
			first.close();

			// A second request over the same agent must not be served by the closed
			// first server. close() destroys the pooled socket, so the reused
			// connection errors rather than reaching the (already-settled) server —
			// which is what would otherwise swallow a subsequent flow's callback.
			const reused = await getOverAgent("/callback?code=abc123&state=xyz");
			expect(reused).not.toHaveProperty("status");
			expect(reused).toHaveProperty("error");

			// And a brand-new server can bind the same port and serve normally.
			const second = await startLocalOAuthServer({
				ports: [port],
				callbackPath: "/callback",
			});
			const secondWait = second.waitForCallback();
			expect(
				await get(`http://127.0.0.1:${port}/callback?code=abc123&state=xyz`),
			).toMatchObject({ status: 200 });
			const secondPayload = await Promise.race([
				secondWait,
				new Promise<never>((_, rej) =>
					setTimeout(() => rej(new Error("flow 2 callback hung")), 3000),
				),
			]);
			expect(secondPayload?.code).toBe("abc123");

			second.close();
			agent.destroy();
		},
	);
});

