				expect(listReply.ok).toBe(true);
				const listedSchedule = (
					listReply.payload?.schedules as Array<{
						scheduleId: string;
						mode: string;
					}>
				).find((item) => item.scheduleId === created.scheduleId);
				expect(listedSchedule).toMatchObject({ mode: "plan" });
			} finally {
				await service.dispose();
			}
		},
	);
