import {
	type BasicLogger,
	type ChatRunTurnRequest,
	type ChatStartSessionArtifacts,
	type ChatStartSessionRequest,
	type HubScheduleCreateInput,
	type HubScheduleUpdateInput,
	ONE_TIME_SCHEDULE_CRON_PATTERN,
	ONE_TIME_SCHEDULE_RUN_AT_METADATA_KEY,
	type ScheduleExecutionRecord,
	type ScheduleExecutionStatus,
	type ScheduleRecord,
} from "@cline/shared";
import { CronMaterializer } from "../runner/cron-materializer";
import { CronRunner } from "../runner/cron-runner";
import { validateCronPattern } from "../schedule/scheduler";
import {
	type CronRunRecord,
	type CronSpecRecord,
	type ListRunsOptions,
	type ListSpecsOptions,
	SqliteCronStore,
} from "../store/sqlite-cron-store";

type HubScheduleTurnResult = {
	text: string;
	usage?: {
		inputTokens?: number;
		outputTokens?: number;
		cacheReadTokens?: number;
		cacheWriteTokens?: number;
		totalCost?: number;
	};
	inputTokens?: number;
	outputTokens?: number;
	iterations?: number;
	finishReason?: string;
	messages?: unknown[];
	toolCalls?: Array<{
		name: string;
		input?: unknown;
		output?: unknown;
		error?: string;
		durationMs?: number;
	}>;
};

export interface HubScheduleRuntimeHandlers {
	startSession(request: ChatStartSessionRequest): Promise<{
		sessionId: string;
		startResult?: ChatStartSessionArtifacts;
	}>;
	sendSession(
		sessionId: string,
		request: ChatRunTurnRequest,
	): Promise<{
		result: HubScheduleTurnResult;
	}>;
	abortSession(sessionId: string): Promise<{ applied: boolean }>;
	stopSession(sessionId: string): Promise<{ applied: boolean }>;
}

export interface ActiveScheduledExecution {
	executionId: string;
	scheduleId: string;
	sessionId: string;
	startedAt: string;
	timeoutAt?: string;
}

export interface HubScheduleServiceOptions {
	runtimeHandlers: HubScheduleRuntimeHandlers;
	eventPublisher?: (
		eventType: string,
		payload: Record<string, unknown>,
	) => void;
	logger?: BasicLogger;
	dbPath?: string;
	pollIntervalMs?: number;
	globalMaxConcurrency?: number;
	claimLeaseSeconds?: number;
}

export interface ListSchedulesOptions {
	enabled?: boolean;
	limit?: number;
	tags?: string[];
}

export interface ListScheduleExecutionsOptions {
	scheduleId?: string;
	status?: ScheduleExecutionStatus;
	limit?: number;
}

export interface ScheduleExecutionStats {
	totalRuns: number;
	successRate: number;
	avgDurationSeconds: number;
	lastFailure?: ScheduleExecutionRecord;
}

function toMillis(value: string | undefined): number | undefined {
	return value ? new Date(value).getTime() : undefined;
}

function scheduleMetadata(
	spec: CronSpecRecord,
): Record<string, unknown> | undefined {
	const metadata = spec.metadata ? { ...spec.metadata } : undefined;
	if (metadata) {
		delete metadata.__hubScheduleCreatedBy;
		delete metadata.__hubScheduleCwd;
		delete metadata.__hubRuntimeOptions;
	}
	return metadata;
}

function specToSchedule(spec: CronSpecRecord): ScheduleRecord {
	const metadata = spec.metadata;
	return {
		scheduleId: spec.externalId,
		name: spec.title,
		cronPattern:
			spec.triggerKind === "one_off"
				? ONE_TIME_SCHEDULE_CRON_PATTERN
				: (spec.scheduleExpr ?? ""),
		prompt: spec.prompt ?? "",
		workspaceRoot: spec.workspaceRoot ?? "",
		cwd:
			typeof metadata?.__hubScheduleCwd === "string"
				? metadata.__hubScheduleCwd
				: undefined,
		modelSelection:
			spec.providerId || spec.modelId
				? {
						providerId: spec.providerId ?? "",
						modelId: spec.modelId ?? "",
					}
				: undefined,
		enabled: spec.enabled && !spec.removed && spec.parseStatus === "valid",
		mode: spec.mode === "plan" ? "plan" : spec.mode === "act" ? "act" : "yolo",
		systemPrompt: spec.systemPrompt,
		maxIterations: spec.maxIterations,
		timeoutSeconds: spec.timeoutSeconds,
		maxParallel: spec.maxParallel ?? 1,
		createdAt: new Date(spec.createdAt).getTime(),
		updatedAt: new Date(spec.updatedAt).getTime(),
		nextRunAt: toMillis(spec.nextRunAt),
		lastRunAt: toMillis(spec.lastRunAt),
		createdBy:
			typeof metadata?.__hubScheduleCreatedBy === "string"
				? metadata.__hubScheduleCreatedBy
				: undefined,
		tags: spec.tags,
		runtimeOptions:
			metadata?.__hubRuntimeOptions &&
			typeof metadata.__hubRuntimeOptions === "object" &&
			!Array.isArray(metadata.__hubRuntimeOptions)
				? (metadata.__hubRuntimeOptions as ScheduleRecord["runtimeOptions"])
				: undefined,
		metadata: scheduleMetadata(spec) as ScheduleRecord["metadata"],
	};
}

function runStatusToScheduleStatus(
	status: CronRunRecord["status"],
): ScheduleExecutionStatus {
	switch (status) {
		case "done":
			return "success";
		case "cancelled":
			return "aborted";
		case "running":
			return "running";
		case "queued":
			return "pending";
		default:
			return "failed";
	}
}

function runToExecution(
	run: CronRunRecord,
	scheduleId: string,
): ScheduleExecutionRecord {
	return {
		executionId: run.runId,
		scheduleId,
		sessionId: run.sessionId,
		triggeredAt: new Date(run.scheduledFor ?? run.createdAt).getTime(),
		startedAt: toMillis(run.startedAt),
		endedAt: toMillis(run.completedAt),
		status: runStatusToScheduleStatus(run.status),
		errorMessage: run.error,
	};
}

export class HubScheduleService {
	private readonly store: SqliteCronStore;
	private readonly materializer: CronMaterializer;
	private readonly runner: CronRunner;
	private started = false;
	private disposed = false;

	constructor(options: HubScheduleServiceOptions) {
		this.store = new SqliteCronStore({
			dbPath: options.dbPath,
		});
		this.materializer = new CronMaterializer({ store: this.store });
		this.runner = new CronRunner({
			store: this.store,
			materializer: this.materializer,
			runtimeHandlers: options.runtimeHandlers,
			eventPublisher: options.eventPublisher,
			workspaceRoot: "",
			logger: options.logger,
			pollIntervalMs: options.pollIntervalMs,
			claimLeaseSeconds: options.claimLeaseSeconds,
			globalMaxConcurrency: options.globalMaxConcurrency,
		});
	}

	public async start(): Promise<void> {
		if (this.disposed) throw new Error("HubScheduleService has been disposed");
		if (this.started) return;
		this.started = true;
		await this.runner.start();
	}

	public async stop(): Promise<void> {
		await this.runner.stop();
		this.started = false;
	}

	public async dispose(): Promise<void> {
		if (this.disposed) return;
		this.disposed = true;
		await this.runner.dispose();
		this.store.close();
	}

	public createSchedule(input: HubScheduleCreateInput): ScheduleRecord {
		this.validateScheduleTiming(input.cronPattern, input.metadata, true);
		if (!input.workspaceRoot?.trim()) {
			throw new Error("workspaceRoot is required for schedules");
		}
		return specToSchedule(this.store.createHubSchedule(input));
	}

	public getSchedule(scheduleId: string): ScheduleRecord | undefined {
		const spec = this.store.getHubSchedule(scheduleId);
		return spec ? specToSchedule(spec) : undefined;
	}

	public listSchedules(options: ListSchedulesOptions = {}): ScheduleRecord[] {
		return this.store
			.listHubSchedules(options)
			.map((spec) => specToSchedule(spec));
	}

	public updateSchedule(
		scheduleId: string,
		updates: HubScheduleUpdateInput,
	): ScheduleRecord | undefined {
		const current = this.store.getHubSchedule(scheduleId);
		if (!current) return undefined;
		const nextWorkspaceRoot =
			updates.workspaceRoot !== undefined
				? updates.workspaceRoot.trim()
				: current.workspaceRoot;
		const nextEnabled = updates.enabled ?? current.enabled;
		const currentSchedule = specToSchedule(current);
		this.validateScheduleTiming(
			updates.cronPattern ?? currentSchedule.cronPattern,
			updates.metadata ?? currentSchedule.metadata,
			nextEnabled,
		);
		if (nextEnabled && !nextWorkspaceRoot) {
			throw new Error("workspaceRoot is required for enabled schedules");
		}
		const updated = this.store.updateHubSchedule(scheduleId, {
			...updates,
			scheduleId,
		});
		return updated ? specToSchedule(updated) : undefined;
	}

	private validateScheduleTiming(
		cronPattern: string,
		metadata: HubScheduleCreateInput["metadata"],
		requireFutureRunAt: boolean,
	): void {
		if (cronPattern.trim() !== ONE_TIME_SCHEDULE_CRON_PATTERN) {
			validateCronPattern(cronPattern);
			return;
		}
		const runAt = metadata?.[ONE_TIME_SCHEDULE_RUN_AT_METADATA_KEY];
		if (
			typeof runAt !== "number" ||
			!Number.isFinite(runAt) ||
			(requireFutureRunAt && runAt <= Date.now())
		) {
			throw new Error("runAt must be a future timestamp");
		}
	}

	public deleteSchedule(scheduleId: string): boolean {
		return this.store.deleteHubSchedule(scheduleId);
	}

	public pauseSchedule(scheduleId: string): ScheduleRecord | undefined {
		return this.updateSchedule(scheduleId, { scheduleId, enabled: false });
	}

	public resumeSchedule(scheduleId: string): ScheduleRecord | undefined {
		return this.updateSchedule(scheduleId, { scheduleId, enabled: true });
	}

	public async triggerScheduleNow(
		scheduleId: string,
	): Promise<ScheduleExecutionRecord | undefined> {
		const run = this.store.enqueueHubScheduleRun(scheduleId, "manual");
		if (!run) return undefined;
		await this.runner.tick();
		const completed = this.store.getRun(run.runId) ?? run;
		return runToExecution(completed, scheduleId);
	}

	public triggerScheduleNowDetached(
		scheduleId: string,
	): ScheduleExecutionRecord | undefined {
		const run = this.store.enqueueHubScheduleRun(scheduleId, "manual");
		if (!run) return undefined;
		void this.runner.tick().catch(() => undefined);
		return runToExecution(run, scheduleId);
	}

	public listScheduleExecutions(
		options: ListScheduleExecutionsOptions,
	): ScheduleExecutionRecord[] {
		const spec = options.scheduleId
			? this.store.getHubSchedule(options.scheduleId)
			: undefined;
		const runOptions: ListRunsOptions = {
			specId: spec?.specId,
			limit: options.limit,
		};
		const runs = this.store.listRuns(runOptions);
		return runs
			.map((run) => {
				const runSpec = spec ?? this.store.getSpec(run.specId);
				if (!runSpec || runSpec.source !== "hub-schedule") return undefined;
				return runToExecution(run, runSpec.externalId);
			})
			.filter((record): record is ScheduleExecutionRecord => {
				if (!record) return false;
				return !options.status || record.status === options.status;
			});
	}

	public getScheduleStats(scheduleId: string): ScheduleExecutionStats {
		const all = this.listScheduleExecutions({ scheduleId, limit: 10_000 });
		if (all.length === 0) {
			return { totalRuns: 0, successRate: 0, avgDurationSeconds: 0 };
		}
		let success = 0;
		let withDuration = 0;
		let durationMsTotal = 0;
		let lastFailure: ScheduleExecutionRecord | undefined;
		for (const execution of all) {
			if (execution.status === "success" || execution.status === "completed") {
				success += 1;
			}
			if (
				!lastFailure &&
				execution.status !== "success" &&
				execution.status !== "completed"
			) {
				lastFailure = execution;
			}
			if (execution.startedAt && execution.endedAt) {
				durationMsTotal += execution.endedAt - execution.startedAt;
				withDuration += 1;
			}
		}
		return {
			totalRuns: all.length,
			successRate: success / all.length,
			avgDurationSeconds:
				withDuration > 0 ? durationMsTotal / withDuration / 1000 : 0,
			lastFailure,
		};
	}

	public getActiveExecutions(): ActiveScheduledExecution[] {
		return this.runner.getActiveRuns().flatMap((run) => {
			const spec = this.store.getSpec(run.specId);
			if (!spec || spec.source !== "hub-schedule" || !run.sessionId) return [];
			return [
				{
					executionId: run.runId,
					scheduleId: spec.externalId,
					sessionId: run.sessionId,
					startedAt: run.startedAt ?? new Date().toISOString(),
					timeoutAt:
						spec.timeoutSeconds && run.startedAt
							? new Date(
									new Date(run.startedAt).getTime() +
										spec.timeoutSeconds * 1000,
								).toISOString()
							: undefined,
				},
			];
		});
	}

	public getUpcomingRuns(limit = 20): Array<{
		scheduleId: string;
		name: string;
		nextRunAt: string;
	}> {
		const options: ListSpecsOptions = {
			triggerKind: "schedule",
			enabled: true,
			limit,
		};
		return this.store
			.listSpecs(options)
			.flatMap((spec) =>
				spec.source === "hub-schedule" && spec.nextRunAt
					? [{ spec, nextRunAt: spec.nextRunAt }]
					: [],
			)
			.sort((a, b) => String(a.nextRunAt).localeCompare(String(b.nextRunAt)))
			.slice(0, limit)
			.map(({ spec, nextRunAt }) => ({
				scheduleId: spec.externalId,
				name: spec.title,
				nextRunAt,
			}));
	}
}

import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { SqliteCronStore } from "../store/sqlite-cron-store";
import { CronReconciler } from "./cron-reconciler";

describe("CronReconciler", () => {
	let root: string;
	let cronDir: string;
	let dbPath: string;
	let store: SqliteCronStore;
	let reconciler: CronReconciler;

	beforeEach(() => {
		root = mkdtempSync(join(tmpdir(), "cline-reconciler-"));
		cronDir = join(root, "cron-specs");
		mkdirSync(cronDir, { recursive: true });
		dbPath = join(root, "cron.db");
		store = new SqliteCronStore({ dbPath });
		reconciler = new CronReconciler({
			store,
			specs: { cronSpecsDir: cronDir },
		});
	});

	afterEach(() => {
		store.close();
		rmSync(root, { recursive: true, force: true });
	});

	function writeSpec(rel: string, content: string) {
		const full = join(cronDir, rel);
		mkdirSync(join(full, ".."), { recursive: true });
		writeFileSync(full, content, "utf8");
	}

	function requireValue<T>(value: T | undefined): T {
		expect(value).toBeDefined();
		if (value === undefined) {
			throw new Error("Expected value to be defined");
		}
		return value;
	}

	it("imports valid one-off and schedule specs on startup", async () => {
		writeSpec(
			"cleanup.md",
			`---\nid: cleanup\nworkspaceRoot: /ws\n---\nRemove stale files`,
		);
		writeSpec(
			"nightly.cron.md",
			`---\nid: nightly\nworkspaceRoot: /ws\nschedule: "0 2 * * *"\n---\nNightly`,
		);

		const summary = await reconciler.reconcileAll();
		expect(summary.scanned).toBe(2);
		expect(summary.upserted).toBe(2);
		expect(summary.invalidParses).toBe(0);

		const specs = store.listSpecs();
		expect(specs.length).toBe(2);
		const schedule = specs.find((s) => s.triggerKind === "schedule");
		expect(schedule?.scheduleExpr).toBe("0 2 * * *");
		expect(schedule?.nextRunAt).toBeDefined();
	});

	it("records invalid specs without failing the whole scan", async () => {
		writeSpec("bad.md", `---\nid: [unclosed\n---\nbody`);
		writeSpec(
			"good.md",
			`---\nid: good\nworkspaceRoot: /ws\n---\nDo good work`,
		);

		const summary = await reconciler.reconcileAll();
		expect(summary.upserted).toBe(2);
		expect(summary.invalidParses).toBe(1);

		const invalid = store
			.listSpecs({ parseStatus: "invalid" })
			.find((s) => s.sourcePath === "bad.md");
		expect(invalid).toBeDefined();
		expect(invalid?.parseError).toBeTruthy();
		expect(invalid?.enabled).toBe(false);

		const valid = store
			.listSpecs({ parseStatus: "valid" })
			.find((s) => s.sourcePath === "good.md");
		expect(valid?.enabled).toBe(true);
	});

	it("marks specs as removed when source files disappear", async () => {
		writeSpec("cleanup.md", `---\nid: cleanup\nworkspaceRoot: /ws\n---\nBody`);
		await reconciler.reconcileAll();
		rmSync(join(cronDir, "cleanup.md"));

		const summary = await reconciler.reconcileAll();
		expect(summary.removed).toBe(1);

		const remaining = store.listSpecs({ includeRemoved: false });
		expect(remaining.length).toBe(0);
		const all = store.listSpecs({ includeRemoved: true });
		expect(all[0]?.removed).toBe(true);
	});

	it("cancels queued runs when spec is removed", async () => {
		writeSpec("cleanup.md", `---\nid: cleanup\nworkspaceRoot: /ws\n---\nBody`);
		await reconciler.reconcileAll();
		const spec = requireValue(store.listSpecs()[0]);
		store.enqueueRun({
			specId: spec.specId,
			specRevision: spec.revision,
			triggerKind: "one_off",
		});

		rmSync(join(cronDir, "cleanup.md"));
		await reconciler.reconcileAll();

		const run = requireValue(store.listRuns({ specId: spec.specId })[0]);
		expect(run.status).toBe("cancelled");
	});

	it("preserves overdue schedule next_run_at on startup refresh", async () => {
		writeSpec(
			"nightly.cron.md",
			`---\nid: nightly\nworkspaceRoot: /ws\nschedule: "* * * * *"\n---\nNightly`,
		);
		await reconciler.reconcileAll();
		const spec = requireValue(store.listSpecs({ triggerKind: "schedule" })[0]);
		const overdue = new Date(Date.now() - 60_000).toISOString();
		store.updateSpecNextRunAt(spec.specId, overdue);

		reconciler.refreshScheduleNextRunAt();

		const refreshed = requireValue(store.getSpec(spec.specId));
		expect(refreshed.nextRunAt).toBe(overdue);
	});
});

import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
import { relative } from "node:path";
import type { CronSpecParseResult } from "@cline/shared";
import {
	type ResolveCronSpecsDirOptions,
	resolveCronSpecsDir,
} from "@cline/shared/storage";
import { getNextCronTime } from "../schedule/scheduler";
import type {
	CronSpecRecord,
	SqliteCronStore,
	UpsertSpecResult,
} from "../store/sqlite-cron-store";
import { type ParseCronSpecInput, parseCronSpecFile } from "./cron-spec-parser";

/**
 * Scan the configured cron specs directory on disk, parse every file, and
 * upsert spec state into the cron DB. This is the startup source of truth:
 * watcher events are triggers to re-run reconciliation for one file, not a
 * replacement.
 */

export interface CronReconcilerOptions {
	store: SqliteCronStore;
	/**
	 * Cron spec source location. Defaults to global `~/.cline/cron`.
	 * Pass `{ scope: "workspace", workspaceRoot }` later to enable
	 * workspace-level cron sources without changing reconciler internals.
	 */
	specs?: ResolveCronSpecsDirOptions;
	/** @deprecated Use `specs: { scope: "workspace", workspaceRoot }`. */
	workspaceRoot?: string;
}

export interface ReconcileChange {
	relativePath: string;
	result: UpsertSpecResult;
	parse: CronSpecParseResult;
}

export interface ReconcileSummary {
	scanned: number;
	upserted: number;
	invalidParses: number;
	removed: number;
	changes: ReconcileChange[];
}

function toPosixRelative(fromDir: string, absolutePath: string): string {
	return relative(fromDir, absolutePath).replace(/\\/g, "/");
}

function walk(dir: string): string[] {
	if (!existsSync(dir)) return [];
	const result: string[] = [];
	const stack: string[] = [dir];
	while (stack.length > 0) {
		const current = stack.pop();
		if (!current) continue;
		let entries: import("node:fs").Dirent[];
		try {
			entries = readdirSync(current, { withFileTypes: true });
		} catch {
			continue;
		}
		for (const entry of entries) {
			const full = `${current}/${entry.name}`;
			if (entry.isDirectory()) {
				// Skip the generated reports subdirectory — not spec sources.
				if (entry.name === "reports") continue;
				stack.push(full);
				continue;
			}
			if (!entry.isFile()) continue;
			if (!entry.name.endsWith(".md")) continue;
			result.push(full);
		}
	}
	return result;
}

export class CronReconciler {
	private readonly store: SqliteCronStore;
	private readonly cronDir: string;

	constructor(options: CronReconcilerOptions) {
		this.store = options.store;
		this.cronDir = resolveCronSpecsDir(
			options.specs ??
				(options.workspaceRoot
					? { scope: "workspace", workspaceRoot: options.workspaceRoot }
					: undefined),
		);
	}

	public getCronDir(): string {
		return this.cronDir;
	}

	/**
	 * Reconcile every file under the cron specs directory into the DB and mark specs
	 * whose source files no longer exist as `removed=1`.
	 */
	public async reconcileAll(): Promise<ReconcileSummary> {
		const summary: ReconcileSummary = {
			scanned: 0,
			upserted: 0,
			invalidParses: 0,
			removed: 0,
			changes: [],
		};

		const files = walk(this.cronDir);
		const seenPaths = new Set<string>();

		for (const abs of files) {
			const rel = toPosixRelative(this.cronDir, abs);
			seenPaths.add(rel);
			summary.scanned += 1;
			const change = await this.reconcileFile(rel, abs);
			if (change) {
				summary.changes.push(change);
				summary.upserted += 1;
				if (change.parse.error) summary.invalidParses += 1;
			}
		}

		const existing = this.store.listSpecs({
			includeRemoved: false,
			limit: 10_000,
		});
		for (const spec of existing) {
			if (!seenPaths.has(spec.sourcePath)) {
				this.handleFileDeleted(spec);
				summary.removed += 1;
			}
		}

		this.refreshScheduleNextRunAt();

		return summary;
	}

	/**
	 * Reconcile a single file (absolute path). `relativePath` is expected to
	 * be POSIX-relative to the cron specs directory. Returns the reconciliation change
	 * or undefined if the file could not be read.
	 */
	public async reconcileFile(
		relativePath: string,
		absolutePath: string,
	): Promise<ReconcileChange | undefined> {
		const existing = this.store.getSpecBySourcePath(relativePath);
		let raw: string;
		let mtimeMs: number | undefined;
		try {
			raw = readFileSync(absolutePath, "utf8");
			mtimeMs = statSync(absolutePath).mtimeMs;
		} catch {
			return undefined;
		}
		const input: ParseCronSpecInput = { relativePath, raw };
		const parse = parseCronSpecFile(input);
		const result = this.store.upsertSpec({
			externalId: parse.externalId,
			sourcePath: relativePath,
			triggerKind: parse.triggerKind,
			sourceMtimeMs: mtimeMs,
			sourceHash: parse.contentHash,
			parseStatus: parse.error ? "invalid" : "valid",
			parseError: parse.error,
			spec: parse.spec,
		});

		// For valid schedule specs, compute next_run_at if missing or reset
		// when schedule_expr changed.
		if (
			!parse.error &&
			parse.triggerKind === "schedule" &&
			result.record.enabled
		) {
			this.applyScheduleNextRunAt(result.record, {
				forceReset:
					!existing ||
					existing.removed ||
					!existing.enabled ||
					existing.scheduleExpr !== result.record.scheduleExpr ||
					existing.timezone !== result.record.timezone,
			});
		}

		return { relativePath, result, parse };
	}

	/**
	 * Handle a file that disappeared from disk between reconciliations.
	 * Marks the spec as removed and cancels any queued runs for it.
	 */
	public handleFileDeleted(spec: CronSpecRecord): void {
		this.store.markSpecRemoved(spec.specId);
		this.store.cancelQueuedRunsForSpec(spec.specId);
	}

	/**
	 * Refresh next_run_at for every enabled schedule spec.
	 * Used at startup to handle the "one overdue catch-up on startup then
	 * advance to next slot" policy.
	 */
	public refreshScheduleNextRunAt(): void {
		const schedules = this.store.listSpecs({
			triggerKind: "schedule",
			enabled: true,
			parseStatus: "valid",
		});
		for (const spec of schedules) {
			this.applyScheduleNextRunAt(spec, { forceReset: false });
		}
	}

	private applyScheduleNextRunAt(
		spec: CronSpecRecord,
		options: { forceReset: boolean },
	): void {
		if (!spec.scheduleExpr) return;
		if (!options.forceReset && spec.nextRunAt) return;
		try {
			const now = Date.now();
			const base = spec.lastRunAt
				? Math.max(now, new Date(spec.lastRunAt).getTime())
				: now;
			const nextMs = getNextCronTime(spec.scheduleExpr, base, spec.timezone);
			const nextIso = new Date(nextMs).toISOString();
			if (spec.nextRunAt !== nextIso) {
				this.store.updateSpecNextRunAt(spec.specId, nextIso);
			}
		} catch {
			// Invalid cron pattern — leave next_run_at as is; the upsert's
			// parse_status already reflects the spec correctness.
		}
	}
}

