				.prepare(
					`UPDATE cron_event_log SET
						processing_status = ?,
						matched_spec_count = COALESCE(?, matched_spec_count),
						queued_run_count = COALESCE(?, queued_run_count),
						suppressed_count = COALESCE(?, suppressed_count),
						error = ?,
						updated_at = ?
					WHERE event_id = ?`,
