					WHERE r.spec_id = ?
						AND r.trigger_kind = 'event'
						AND e.dedupe_key = ?
						AND e.received_at >= ?
					LIMIT 1`,
			)
			.get(options.specId, options.dedupeKey, options.sinceIso);
