name: foo
---
Run the foo workflow.`,
		);
		await writeFile(
			join(workflowsDir, "foo-skill.md"),
			`---
name: foo-skill
---
Run the explicitly named foo-skill workflow.`,
		);

		const watcher = createUserInstructionConfigWatcher({
			skills: { directories: [join(tempRoot, "skills")] },
			rules: { directories: [] },
