	});

	it("keeps tool-use and tool-result pairs coherent when dropping history", () => {
		const result = buildBudgetProjection({
			messages: [
				{ role: "user", content: "original task" },
				{
					role: "assistant",
					content: [
						{
							type: "tool_use",
