				context: {
					agentId: "test-agent",
					iteration: 1,
					signal: controller.signal,
				},
			});
			controller.abort();
			await expect(call).rejects.toMatchObject({ name: "AbortError" });
		} finally {
			await client.disconnect();
		}
	}, 30_000);
});

