const DEFAULT_MCP_OAUTH_CALLBACK_PATH = "/mcp/oauth/callback";
const DEFAULT_MCP_OAUTH_CALLBACK_PORTS = [1456, 1457, 1458];
const DEFAULT_MCP_OAUTH_TIMEOUT_MS = 5 * 60 * 1000;

export type McpSdkAuthCapableTransport =
	| SSEClientTransport
	| StreamableHTTPClientTransport;

export interface CreateMcpOAuthProviderContextOptions {
	settingsPath?: string;
	serverName: string;
	redirectUrl: string;
	onAuthorizationUrl?: (url: string) => void | Promise<void>;
}

export interface McpOAuthProviderContext {
	provider: OAuthClientProvider;
	getLastAuthorizationUrl(): string | undefined;
	getLastOAuthState(): string | undefined;
	resetInteractiveState(): Promise<void>;
	markError(errorMessage: string): Promise<void>;
	clearError(): Promise<void>;
}

export interface AuthorizeMcpServerOAuthOptions {
	serverName: string;
	filePath?: string;
	clientName?: string;
	clientVersion?: string;
	fetch?: FetchLike;
	openUrl?: (url: string) => void | Promise<void>;
	callbackHost?: string;
	callbackPorts?: number[];
	callbackPath?: string;
	timeoutMs?: number;
	successHtml?: string;
	onServerListening?: (info: OAuthServerListeningInfo) => void | Promise<void>;
	onServerClose?: (info: OAuthServerCloseInfo) => void | Promise<void>;
}

export interface AuthorizeMcpServerOAuthResult {
	serverName: string;
	authorized: true;
	message: string;
}

function toErrorMessage(error: unknown): string {
	if (error instanceof Error) {
		const message = error.message.trim();
		if (message.length > 0) {
			return message;
		}
	}
	return String(error);
}

function createOAuthClientMetadata(redirectUrl: string): OAuthClientMetadata {
	return {
		client_name: "Cline",
		redirect_uris: [redirectUrl],
		grant_types: ["authorization_code", "refresh_token"],
		response_types: ["code"],
		token_endpoint_auth_method: "none",
	};
}

export function createMcpOAuthProviderContext(
	options: CreateMcpOAuthProviderContextOptions,
): McpOAuthProviderContext {
	let state: McpServerOAuthState = {};
	try {
		state =
			getMcpServerOAuthState(options.serverName, {
				filePath: options.settingsPath,
			}) ?? {};
	} catch {
		state = {};
	}
	let lastAuthorizationUrl: string | undefined;
	let lastOAuthState: string | undefined;

	const patch = async (
		updater: (current: McpServerOAuthState) => McpServerOAuthState,
	): Promise<void> => {
		const nextState = normalizeMcpServerOAuthState(updater(state)) ?? {};
		try {
			state = updateMcpServerOAuthState(options.serverName, () => nextState, {
				filePath: options.settingsPath,
			});
		} catch {
			state = nextState;
		}
	};

	const provider: OAuthClientProvider = {
		get redirectUrl() {
			return state.redirectUrl ?? options.redirectUrl;
		},
		get clientMetadata() {
			return createOAuthClientMetadata(
				state.redirectUrl ?? options.redirectUrl,
			);
		},
		state: () => {
			lastOAuthState = randomUUID();
			return lastOAuthState;
		},
		clientInformation: () =>
			state.clientInformation as OAuthClientInformationMixed | undefined,
		saveClientInformation: async (clientInformation) => {
			await patch((current) => ({
				...current,
				clientInformation: clientInformation as Record<string, unknown>,
				redirectUrl: options.redirectUrl,
				lastError: undefined,
			}));
		},
		tokens: () => state.tokens as OAuthTokens | undefined,
		saveTokens: async (tokens) => {
			const lastAuthenticatedAt = Date.now();
			await patch((current) => ({
				...current,
				tokens: tokens as Record<string, unknown>,
				redirectUrl: options.redirectUrl,
				lastError: undefined,
				lastAuthenticatedAt,
			}));
		},
		redirectToAuthorization: async (authorizationUrl) => {
			lastAuthorizationUrl = authorizationUrl.toString();
			await options.onAuthorizationUrl?.(lastAuthorizationUrl);
		},
		saveCodeVerifier: async (codeVerifier) => {
			await patch((current) => ({
				...current,
				codeVerifier,
				redirectUrl: options.redirectUrl,
			}));
		},
		codeVerifier: () => {
			if (!state.codeVerifier) {
				throw new Error(
					`Missing OAuth code verifier for MCP server "${options.serverName}".`,
				);
			}
			return state.codeVerifier;
		},
		invalidateCredentials: async (scope) => {
			await patch((current) => {
				if (scope === "all") {
					return {
						lastError: current.lastError,
						redirectUrl: current.redirectUrl,
					};
				}
				return {
					...current,
					...(scope === "client" ? { clientInformation: undefined } : {}),
					...(scope === "tokens"
						? { tokens: undefined, lastAuthenticatedAt: undefined }
						: {}),
					...(scope === "verifier" ? { codeVerifier: undefined } : {}),
					...(scope === "discovery" ? { discoveryState: undefined } : {}),
				};
			});
		},
		saveDiscoveryState: async (discoveryState) => {
			await patch((current) => ({
				...current,
				discoveryState: discoveryState as unknown as Record<string, unknown>,
			}));
		},
		discoveryState: () =>
			state.discoveryState as OAuthDiscoveryState | undefined,
	};

	return {
		provider,
		getLastAuthorizationUrl: () => lastAuthorizationUrl,
		getLastOAuthState: () => lastOAuthState,
		resetInteractiveState: async () => {
			await patch((current) => ({
				...current,
				clientInformation: undefined,
				codeVerifier: undefined,
				discoveryState: undefined,
				lastError: undefined,
				redirectUrl: options.redirectUrl,
			}));
		},
		markError: async (errorMessage) => {
			await patch((current) => ({
				...current,
				lastError: errorMessage,
			}));
		},
		clearError: async () => {
			await patch((current) => ({
				...current,
				lastError: undefined,
			}));
		},
	};
}

export function createMcpSdkTransport(input: {
	registration: McpServerRegistration;
	oauthProvider?: OAuthClientProvider;
	fetch?: FetchLike;
}): McpSdkAuthCapableTransport {
	const transport = input.registration.transport;
	if (transport.type === "stdio") {
		throw new Error(
			`MCP server "${input.registration.name}" uses stdio transport and does not support OAuth browser flow.`,
		);
	}

	const requestInit = transport.headers
		? {
				headers: transport.headers,
			}
		: undefined;
	if (transport.type === "sse") {
		return new SSEClientTransport(new URL(transport.url), {
			authProvider: input.oauthProvider,
			requestInit,
			fetch: input.fetch,
		});
	}

	return new StreamableHTTPClientTransport(new URL(transport.url), {
		authProvider: input.oauthProvider,
		requestInit,
		fetch: input.fetch,
	});
}

function buildClient(input: {
	clientName?: string;
	clientVersion?: string;
}): Client {
	return new Client({
		name: input.clientName?.trim() || "@cline/core",
		version: input.clientVersion?.trim() || "0.0.0",
	});
}

export async function authorizeMcpServerOAuth(
	options: AuthorizeMcpServerOAuthOptions,
): Promise<AuthorizeMcpServerOAuthResult> {
	const serverName = options.serverName.trim();
	if (!serverName) {
		throw new Error("MCP server name cannot be empty.");
	}

	const { resolveMcpServerRegistrations } = await import("./config-loader");
	const registration = resolveMcpServerRegistrations({
		filePath: options.filePath,
	}).find((entry) => entry.name === serverName);
	if (!registration) {
		throw new Error(`MCP server "${serverName}" is not configured.`);
	}
	if (registration.disabled) {
		throw new Error(
			`MCP server "${serverName}" is disabled. Enable it before running OAuth.`,
		);
	}
	if (registration.transport.type === "stdio") {
		throw new Error(
			`MCP server "${serverName}" uses stdio transport and does not support OAuth browser flow.`,
		);
	}
	const requestTimeoutMs = resolveMcpRequestTimeoutMs(
		registration.timeoutSeconds,
	);

	const callbackServer = await startLocalOAuthServer({
		host: options.callbackHost,
		ports: options.callbackPorts?.length
			? options.callbackPorts
			: DEFAULT_MCP_OAUTH_CALLBACK_PORTS,
		callbackPath: options.callbackPath ?? DEFAULT_MCP_OAUTH_CALLBACK_PATH,
		timeoutMs: options.timeoutMs ?? DEFAULT_MCP_OAUTH_TIMEOUT_MS,
		successHtml: options.successHtml,
		onListening: options.onServerListening,
		onClose: options.onServerClose,
	});
	if (!callbackServer.callbackUrl) {
		throw new Error("Unable to bind local MCP OAuth callback server.");
	}

	const oauthContext = createMcpOAuthProviderContext({
		settingsPath: options.filePath,
		serverName,
		redirectUrl: callbackServer.callbackUrl,
		onAuthorizationUrl: async (url) => {
			await options.openUrl?.(url);
		},
	});
	await oauthContext.resetInteractiveState();

	const client = buildClient(options);
	let retryClient: Client | undefined;
	try {
		const transport = createMcpSdkTransport({
			registration,
			oauthProvider: oauthContext.provider,
			fetch: options.fetch,
		});
		try {
			await client.connect(transport, { timeout: requestTimeoutMs });
			await client.listTools(undefined, { timeout: requestTimeoutMs });
			await oauthContext.clearError();
			return {
				serverName,
				authorized: true,
				message: `MCP server "${serverName}" is already authorized.`,
			};
		} catch (error) {
			if (!(error instanceof UnauthorizedError)) {
				throw error;
			}
			const authUrl = oauthContext.getLastAuthorizationUrl();
			if (!authUrl) {
				throw new Error(
					`MCP server "${serverName}" did not provide an authorization URL.`,
				);
			}
			const callback = await callbackServer.waitForCallback();
			if (!callback) {
				throw new Error(
					"Timed out waiting for MCP OAuth authorization callback.",
				);
			}
			if (callback.error) {
				throw new Error(`OAuth authorization failed: ${callback.error}`);
			}
			if (!callback.code) {
				throw new Error(
					"OAuth callback did not include an authorization code.",
				);
			}
			const expectedState = oauthContext.getLastOAuthState();
			if (!expectedState) {
				throw new Error(
					`MCP server "${serverName}" did not start an OAuth stateful authorization flow.`,
				);
			}
			if (callback.state !== expectedState) {
				throw new Error("OAuth authorization failed: state mismatch.");
			}

			await transport.finishAuth(callback.code);
			retryClient = buildClient(options);
			const retryTransport = createMcpSdkTransport({
				registration,
				oauthProvider: oauthContext.provider,
				fetch: options.fetch,
			});
			await retryClient.connect(retryTransport, {
				timeout: requestTimeoutMs,
			});
			await retryClient.listTools(undefined, { timeout: requestTimeoutMs });
			await oauthContext.clearError();
			return {
				serverName,
				authorized: true,
				message: `MCP server "${serverName}" OAuth authorization completed.`,
			};
		}
	} catch (error) {
		const message = toErrorMessage(
			augmentMcpTimeoutError(error, serverName, requestTimeoutMs),
		);
		await oauthContext.markError(message);
		throw new Error(message);
	} finally {
		await client.close().catch(() => undefined);
		await retryClient?.close().catch(() => undefined);
		callbackServer.close();
	}
}

import { describe, expect, it } from "vitest";
import { normalizePluginMcpServerRegistration } from "./plugin-server-registration";

describe("plugin MCP server registration", () => {
	it("normalizes streamable HTTP plugin MCP servers", () => {
		const result = normalizePluginMcpServerRegistration({
			name: "remote",
			transport: {
				type: "streamableHttp",
				url: "https://example.com/mcp",
				headers: {
					Authorization: "Bearer token",
				},
			},
		});

		expect(result.loadError).toBeUndefined();
		expect(result.registration).toEqual({
			name: "remote",
			transport: {
				type: "streamableHttp",
				url: "https://example.com/mcp",
				headers: {
					Authorization: "Bearer token",
				},
			},
		});
	});

	it("normalizes SSE plugin MCP servers", () => {
		const result = normalizePluginMcpServerRegistration({
			name: "remote-sse",
			transport: {
				type: "sse",
				url: "https://example.com/sse",
			},
		});

		expect(result.loadError).toBeUndefined();
		expect(result.registration).toEqual({
			name: "remote-sse",
			transport: {
				type: "sse",
				url: "https://example.com/sse",
			},
		});
	});

	it("keeps top-level env scoped to stdio transports", () => {
		const result = normalizePluginMcpServerRegistration({
			name: "remote",
			transport: {
				type: "streamableHttp",
				url: "https://example.com/mcp",
			},
			env: {
				TOKEN: {
					fromEnv: "TOKEN",
					required: true,
				},
			},
		});

		expect(result.registration).toBeUndefined();
		expect(result.loadError).toContain(
			"top-level env is only supported for stdio MCP transports",
		);
	});

	it("reports missing stdio command before missing required env", () => {
		const result = normalizePluginMcpServerRegistration({
			name: "local",
			transport: {
				type: "stdio",
				command: "",
			},
			env: {
				MISSING_TOKEN: {
					fromEnv: "CLINE_TEST_MISSING_PLUGIN_MCP_TOKEN",
					required: true,
				},
			},
		});

		expect(result.registration).toBeUndefined();
		expect(result.loadError).toBe("stdio MCP transport requires command");
	});

	it("normalizes whitespace-only server names to empty-name errors", () => {
		const result = normalizePluginMcpServerRegistration({
			name: "   ",
			transport: {
				type: "stdio",
				command: "node",
			},
		});

		expect(result.registration).toBeUndefined();
		expect(result).toEqual({
			name: "",
			loadError: "empty MCP server name",
		});
	});
});

import type {
	AgentExtensionMcpEnvValue,
	AgentExtensionMcpServer,
} from "@cline/shared";
import type { McpServerRegistration } from "./types";

export interface PluginMcpServerResolution<TOwner> {
	owner: TOwner;
	name: string;
	registration?: McpServerRegistration;
	loadError?: string;
}

type ResolvedPluginMcpEnv =
	| {
			ok: true;
			env?: Record<string, string>;
	  }
	| {
			ok: false;
			reason: string;
	  };

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isStringRecord(value: unknown): value is Record<string, string> {
	return (
		isRecord(value) &&
		Object.values(value).every((entry) => typeof entry === "string")
	);
}

function isStringArray(value: unknown): value is string[] {
	return (
		Array.isArray(value) && value.every((entry) => typeof entry === "string")
	);
}

function isPluginMcpEnvValue(
	value: unknown,
): value is AgentExtensionMcpEnvValue {
	if (!isRecord(value)) {
		return false;
	}
	return (
		(value.fromEnv === undefined || typeof value.fromEnv === "string") &&
		(value.value === undefined || typeof value.value === "string") &&
		(value.required === undefined || typeof value.required === "boolean")
	);
}

function resolvePluginMcpEnv(
	server: AgentExtensionMcpServer,
): ResolvedPluginMcpEnv {
	const entries = server.env ? Object.entries(server.env) : [];
	if (entries.length === 0) {
		return { ok: true };
	}

	const env: Record<string, string> = {};
	for (const [targetName, value] of entries) {
		if (typeof value === "string") {
			env[targetName] = value;
			continue;
		}

		const sourceName = value.fromEnv?.trim() || targetName;
		const sourceValue = process.env[sourceName];
		if (typeof sourceValue === "string" && sourceValue.length > 0) {
			env[targetName] = sourceValue;
			continue;
		}
		if (typeof value.value === "string") {
			env[targetName] = value.value;
			continue;
		}
		if (value.required === true) {
			return {
				ok: false,
				reason: `required environment variable "${sourceName}" is not set`,
			};
		}
	}

	return { ok: true, env: Object.keys(env).length > 0 ? env : undefined };
}

export function normalizePluginMcpServerRegistration(
	server: AgentExtensionMcpServer,
): {
	name: string;
	registration?: McpServerRegistration;
	loadError?: string;
} {
	if (!isRecord(server)) {
		return { name: "", loadError: "invalid MCP server registration" };
	}
	const name = typeof server.name === "string" ? server.name.trim() : "";
	if (!name) {
		return {
			name,
			loadError: "empty MCP server name",
		};
	}

	const envValue = server.env;
	const env = envValue === undefined ? undefined : envValue;
	if (env !== undefined) {
		if (!isRecord(env)) {
			return { name, loadError: "invalid env" };
		}
		for (const [key, value] of Object.entries(env)) {
			if (typeof value !== "string" && !isPluginMcpEnvValue(value)) {
				return { name, loadError: `invalid env "${key}"` };
			}
		}
	}

	const transport = server.transport;
	if (!isRecord(transport)) {
		return { name, loadError: "invalid MCP transport" };
	}
	const type = transport.type;
	if (type !== "stdio" && type !== "sse" && type !== "streamableHttp") {
		return { name, loadError: "invalid MCP transport type" };
	}
	if (type !== "stdio" && env !== undefined) {
		return {
			name,
			loadError: "top-level env is only supported for stdio MCP transports",
		};
	}

	const metadata = isRecord(server.metadata) ? server.metadata : undefined;
	if (type === "stdio") {
		const command = transport.command;
		if (typeof command !== "string" || !command.trim()) {
			return { name, loadError: "stdio MCP transport requires command" };
		}
		const args = transport.args;
		if (args !== undefined && !isStringArray(args)) {
			return { name, loadError: "stdio MCP transport args must be strings" };
		}
		const cwd = transport.cwd;
		if (cwd !== undefined && typeof cwd !== "string") {
			return { name, loadError: "stdio MCP transport cwd must be a string" };
		}
		const transportEnv = transport.env;
		if (transportEnv !== undefined && !isStringRecord(transportEnv)) {
			return { name, loadError: "stdio MCP transport env must be strings" };
		}

		const resolvedEnv = resolvePluginMcpEnv({
			name,
			transport: {
				type: "stdio",
				command,
				args,
				cwd,
				env: transportEnv,
			},
			env,
			metadata,
		});
		if (!resolvedEnv.ok) {
			return { name, loadError: resolvedEnv.reason };
		}

		const resolvedTransportEnv =
			transportEnv || resolvedEnv.env
				? {
						...(transportEnv ?? {}),
						...(resolvedEnv.env ?? {}),
					}
				: undefined;
		return {
			name,
			registration: {
				name,
				transport: {
					type: "stdio",
					command,
					args,
					cwd,
					env: resolvedTransportEnv,
				},
				metadata,
			},
		};
	}

	if (typeof transport.url !== "string" || !transport.url.trim()) {
		return { name, loadError: `${type} MCP transport requires url` };
	}
	const headers = transport.headers;
	if (headers !== undefined && !isStringRecord(headers)) {
		return { name, loadError: `${type} MCP transport headers must be strings` };
	}

	return {
		name,
		registration: {
			name,
			transport:
				type === "sse"
					? {
							type: "sse",
							url: transport.url,
							headers,
						}
					: {
							type: "streamableHttp",
							url: transport.url,
							headers,
						},
			metadata,
		},
	};
}

export function resolvePluginMcpServerRegistrations<TOwner>(
	servers: readonly {
		server: AgentExtensionMcpServer;
		owner: TOwner;
		ownerLabel?: string;
	}[],
): PluginMcpServerResolution<TOwner>[] {
	const firstOwnerByName = new Map<string, string | undefined>();
	return servers.map(({ server, owner, ownerLabel }) => {
		const normalized = normalizePluginMcpServerRegistration(server);
		if (!normalized.registration) {
			return {
				owner,
				name: normalized.name,
				loadError: normalized.loadError ?? "invalid MCP server registration",
			};
		}

		const firstOwner = firstOwnerByName.get(normalized.registration.name);
		if (firstOwnerByName.has(normalized.registration.name)) {
			const ownerText = firstOwner
				? ` already registered by ${firstOwner}`
				: "";
			return {
				owner,
				name: normalized.registration.name,
				loadError: `duplicate MCP server name "${normalized.registration.name}"${ownerText}`,
			};
		}

		firstOwnerByName.set(normalized.registration.name, ownerLabel);
		return {
			owner,
			name: normalized.registration.name,
			registration: normalized.registration,
		};
	});
}

import type { ToolPolicy } from "@cline/shared";
import { defaultMcpToolNameTransform } from "./name-transform";
import type { McpToolNameTransform } from "./types";

export interface CreateDisabledMcpToolPolicyOptions {
	serverName: string;
	toolName: string;
	nameTransform?: McpToolNameTransform;
}

export interface CreateDisabledMcpToolPoliciesOptions {
	serverName: string;
	toolNames: readonly string[];
	nameTransform?: McpToolNameTransform;
}

export function createDisabledMcpToolPolicy(
	options: CreateDisabledMcpToolPolicyOptions,
): Record<string, ToolPolicy> {
	const nameTransform = options.nameTransform ?? defaultMcpToolNameTransform;
	const name = nameTransform({
		serverName: options.serverName,
		toolName: options.toolName,
	});
	return {
		[name]: {
			enabled: false,
		},
	};
}

export function createDisabledMcpToolPolicies(
	options: CreateDisabledMcpToolPoliciesOptions,
): Record<string, ToolPolicy> {
	const policies: Record<string, ToolPolicy> = {};
	for (const toolName of options.toolNames) {
		Object.assign(
			policies,
			createDisabledMcpToolPolicy({
				serverName: options.serverName,
				toolName,
				nameTransform: options.nameTransform,
			}),
		);
	}
	return policies;
}

import {
	formatMcpTimeoutErrorMessage,
	resolveMcpTimeoutSeconds,
} from "@cline/shared";
import { ErrorCode, McpError } from "@modelcontextprotocol/sdk/types.js";

export function resolveMcpRequestTimeoutMs(timeoutSeconds: unknown): number {
	return resolveMcpTimeoutSeconds(timeoutSeconds) * 1000;
}

export function augmentMcpTimeoutError(
	error: unknown,
	serverName: string,
	timeoutMs: number,
): unknown {
	if (!(error instanceof McpError) || error.code !== ErrorCode.RequestTimeout) {
		return error;
	}
	return new McpError(
		error.code,
		formatMcpTimeoutErrorMessage(serverName, timeoutMs),
		error.data,
	);
}

import { type AgentTool, createTool } from "@cline/shared";
import { defaultMcpToolNameTransform } from "./name-transform";
import type { CreateMcpToolsOptions, McpToolDescriptor } from "./types";

function defaultMcpDescription(
	serverName: string,
	tool: McpToolDescriptor,
): string {
	const base = tool.description?.trim();
	if (base) {
		return base;
	}
	return `Execute MCP tool "${tool.name}" from server "${serverName}".`;
}

export async function createMcpTools(
	options: CreateMcpToolsOptions,
): Promise<AgentTool[]> {
	const descriptors = await options.provider.listTools(options.serverName);
	const nameTransform = options.nameTransform ?? defaultMcpToolNameTransform;

	return descriptors.map((descriptor) => {
		const agentToolName = nameTransform({
			serverName: options.serverName,
			toolName: descriptor.name,
		});

		return createTool({
			name: agentToolName,
			description: defaultMcpDescription(options.serverName, descriptor),
			inputSchema: descriptor.inputSchema,
			timeoutMs: options.timeoutMs,
			retryable: options.retryable,
			maxRetries: options.maxRetries,
			execute: async (input: unknown, context) =>
				options.provider.callTool({
					serverName: options.serverName,
					toolName: descriptor.name,
					arguments:
						input && typeof input === "object" && !Array.isArray(input)
							? (input as Record<string, unknown>)
							: undefined,
					context,
				}),
		});
	});
}

import type { AgentToolContext } from "@cline/shared";

