import { resolve } from "node:path";
import type { AgentExtension, PluginSetupContext } from "@cline/shared";
import { normalizePluginManifest } from "@cline/shared";
import type {
	PluginInitializationFailure,
	PluginInitializationWarning,
} from "./plugin-load-report";
import { importPluginModule } from "./plugin-module-import";
import {
	matchesPluginManifestTargeting,
	type PluginTargeting,
} from "./plugin-targeting";

type PluginLike = {
	name: string;
	manifest: {
		capabilities: string[];
		providerIds?: string[];
		modelIds?: string[];
	};
};

export interface LoadAgentPluginFromPathOptions {
	exportName?: string;
	cwd?: string;
	useCache?: boolean;
	session?: PluginSetupContext["session"];
	client?: PluginSetupContext["client"];
	user?: PluginSetupContext["user"];
	workspaceInfo?: PluginSetupContext["workspaceInfo"];
	automation?: PluginSetupContext["automation"];
	logger?: PluginSetupContext["logger"];
	telemetry?: PluginSetupContext["telemetry"];
}

function isObject(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null;
}

function hasValidStringArray(value: unknown): value is string[] {
	return (
		Array.isArray(value) && value.every((entry) => typeof entry === "string")
	);
}

function validatePluginManifest(
	plugin: PluginLike,
	absolutePath: string,
): void {
	if (!isObject(plugin.manifest)) {
		throw new Error(
			`Invalid plugin module at ${absolutePath}: missing required "manifest"`,
		);
	}
	if (!hasValidStringArray(plugin.manifest.capabilities)) {
		throw new Error(
			`Invalid plugin module at ${absolutePath}: manifest.capabilities must be a string array`,
		);
	}
	if (plugin.manifest.capabilities.length === 0) {
		throw new Error(
			`Invalid plugin module at ${absolutePath}: manifest.capabilities cannot be empty`,
		);
	}
	if (
		Object.hasOwn(plugin.manifest, "providerIds") &&
		!hasValidStringArray(plugin.manifest.providerIds)
	) {
		throw new Error(
			`Invalid plugin module at ${absolutePath}: manifest.providerIds must be a string array when provided`,
		);
	}
	if (
		Object.hasOwn(plugin.manifest, "modelIds") &&
		!hasValidStringArray(plugin.manifest.modelIds)
	) {
		throw new Error(
			`Invalid plugin module at ${absolutePath}: manifest.modelIds must be a string array when provided`,
		);
	}
}

function validatePluginExport(
	plugin: unknown,
	absolutePath: string,
): asserts plugin is PluginLike {
	if (!isObject(plugin)) {
		throw new Error(
			`Invalid plugin module at ${absolutePath}: expected object export`,
		);
	}
	if (typeof plugin.name !== "string" || plugin.name.length === 0) {
		throw new Error(
			`Invalid plugin module at ${absolutePath}: expected non-empty "name"`,
		);
	}
	if (!Object.hasOwn(plugin, "manifest")) {
		throw new Error(
			`Invalid plugin module at ${absolutePath}: missing required "manifest"`,
		);
	}
	validatePluginManifest(plugin as PluginLike, absolutePath);
}

export async function loadAgentPluginFromPath(
	pluginPath: string,
	options: LoadAgentPluginFromPathOptions = {},
): Promise<AgentExtension> {
	const absolutePath = resolve(options.cwd ?? process.cwd(), pluginPath);
	const moduleExports = await importPluginModule(absolutePath, {
		useCache: options.useCache,
	});
	const exportName = options.exportName ?? "plugin";
	const plugin = (moduleExports.default ??
		moduleExports[exportName]) as unknown;

	validatePluginExport(plugin, absolutePath);
	const pluginTyped = plugin as AgentExtension;
	const originalSetup = pluginTyped.setup;

	// Wrap setup to inject workspace context
	const setupWithContext: AgentExtension["setup"] = originalSetup
		? (api, _ctx) => {
				const session = {
					...options.session,
					..._ctx.session,
				};
				const ctx = {
					..._ctx,
					session: Object.keys(session).length > 0 ? session : undefined,
					client: options.client ?? _ctx.client,
					user: options.user ?? _ctx.user,
					workspaceInfo: options.workspaceInfo ?? _ctx.workspaceInfo,
					automation: options.automation ?? _ctx.automation,
					logger: options.logger ?? _ctx.logger,
					telemetry: options.telemetry ?? _ctx.telemetry,
				};
				return originalSetup(api, ctx);
			}
		: undefined;

	return {
		...pluginTyped,
		manifest: normalizePluginManifest(pluginTyped.manifest),
		setup: setupWithContext,
	};
}

export async function loadAgentPluginsFromPaths(
	pluginPaths: string[],
	options: LoadAgentPluginFromPathOptions & PluginTargeting = {},
): Promise<AgentExtension[]> {
	const report = await loadAgentPluginsFromPathsWithDiagnostics(
		pluginPaths,
		options,
	);
	return report.plugins;
}

export async function loadAgentPluginsFromPathsWithDiagnostics(
	pluginPaths: string[],
	options: LoadAgentPluginFromPathOptions & PluginTargeting = {},
): Promise<{
	plugins: AgentExtension[];
	pluginPaths: string[];
	failures: PluginInitializationFailure[];
	warnings: PluginInitializationWarning[];
}> {
	const failures: PluginInitializationFailure[] = [];
	const warnings: PluginInitializationWarning[] = [];
	const loadedByName = new Map<
		string,
		{ plugin: AgentExtension; pluginPath: string; order: number }
	>();
	let order = 0;

	for (const pluginPath of pluginPaths) {
		try {
			const plugin = await loadAgentPluginFromPath(pluginPath, options);
			if (!matchesPluginManifestTargeting(plugin.manifest, options)) {
				continue;
			}
			const existing = loadedByName.get(plugin.name);
			if (existing) {
				warnings.push({
					type: "duplicate_plugin_override",
					pluginName: plugin.name,
					pluginPath,
					overriddenPluginPath: existing.pluginPath,
					message: `Plugin "${plugin.name}" from ${pluginPath} overrides ${existing.pluginPath}`,
				});
			}
			loadedByName.set(plugin.name, { plugin, pluginPath, order: order++ });
		} catch (error) {
			const message = error instanceof Error ? error.message : String(error);
			failures.push({
				pluginPath,
				phase: "load",
				message,
				stack: error instanceof Error ? error.stack : undefined,
			});
		}
	}

	const loadedEntries = [...loadedByName.values()].sort(
		(left, right) => left.order - right.order,
	);
	return {
		plugins: loadedEntries.map((entry) => entry.plugin),
		pluginPaths: loadedEntries.map((entry) => entry.pluginPath),
		failures,
		warnings,
	};
}

import { existsSync, readFileSync } from "node:fs";
import { builtinModules, createRequire } from "node:module";
import { dirname, extname, isAbsolute, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { PLUGIN_FILE_EXTENSIONS } from "@cline/shared";

const MODULE_DIR = dirname(fileURLToPath(import.meta.url));
const HOST_REQUIRE = createRequire(import.meta.url);
// `plugin-module-import.ts` lives at `packages/core/src/extensions/plugin`, so
// walking up five levels lands at the repo root.
const WORKSPACE_ROOT = resolve(MODULE_DIR, "..", "..", "..", "..", "..");
const WORKSPACE_ALIASES = collectWorkspaceAliases(WORKSPACE_ROOT);
const HOST_PROVIDED_SDK_SPECIFIERS = [
	"@cline/sdk",
	"@cline/agents",
	"@cline/core",
	"@cline/core/hub",
	"@cline/core/hub/daemon-entry",
	"@cline/core/telemetry",
	"@cline/llms",
	"@cline/llms/browser",
	"@cline/shared",
	"@cline/shared/automation",
	"@cline/shared/browser",
	"@cline/shared/storage",
	"@cline/shared/db",
	"@cline/shared/types",
];
const BUILTIN_MODULES = new Set(
	builtinModules.flatMap((id) => [id, id.replace(/^node:/, "")]),
);
const SUPPORTED_PLUGIN_EXTENSIONS = new Set(PLUGIN_FILE_EXTENSIONS);
const WORKSPACE_EXPORT_CONDITIONS = [
	"development",
	"node",
	"import",
	"require",
	"default",
];

export interface ImportPluginModuleOptions {
	useCache?: boolean;
}

function collectWorkspaceAliases(root: string): Record<string, string> {
	const aliases: Record<string, string> = {};
	const candidates: Record<string, string> = {
		"@cline/sdk": resolve(root, "packages/sdk/src/index.ts"),
		"@cline/agents": resolve(root, "packages/agents/src/index.ts"),
		"@cline/core": resolve(root, "packages/core/src/index.ts"),
		"@cline/llms": resolve(root, "packages/llms/src/index.ts"),
		"@cline/shared": resolve(root, "packages/shared/src/index.ts"),
		"@cline/shared/storage": resolve(
			root,
			"packages/shared/src/storage/index.ts",
		),
		"@cline/shared/db": resolve(root, "packages/shared/src/db/index.ts"),
	};
	for (const [key, value] of Object.entries(candidates)) {
		if (existsSync(value)) {
			aliases[key] = value;
		}
	}
	for (const packageName of ["agents", "core", "llms", "shared"]) {
		const packageRoot = resolve(root, "packages", packageName);
		const packageJsonPath = resolve(packageRoot, "package.json");
		if (!existsSync(packageJsonPath)) {
			continue;
		}
		try {
			const pkg = JSON.parse(readFileSync(packageJsonPath, "utf8")) as {
				name?: unknown;
				exports?: unknown;
			};
			if (typeof pkg.name !== "string" || !pkg.exports) {
				continue;
			}
			if (typeof pkg.exports === "string") {
				const target = resolve(packageRoot, pkg.exports);
				if (existsSync(target)) {
					aliases[pkg.name] = target;
				}
				continue;
			}
			if (typeof pkg.exports !== "object") {
				continue;
			}
			for (const [exportPath, exportValue] of Object.entries(pkg.exports)) {
				const sourcePath = resolveWorkspaceExportSourcePath(
					packageRoot,
					exportValue,
				);
				if (!sourcePath) {
					continue;
				}
				const specifier =
					exportPath === "."
						? pkg.name
						: `${pkg.name}/${exportPath.replace(/^\.\//, "")}`;
				aliases[specifier] = sourcePath;
			}
		} catch {
			// Workspace aliases are a development convenience; ignore malformed
			// package manifests and let normal resolution report any real failure.
		}
	}
	return aliases;
}

function resolveWorkspaceExportSourcePath(
	packageRoot: string,
	exportValue: unknown,
): string | null {
	const exportPath = selectWorkspaceExportPath(exportValue);
	if (!exportPath) {
		return null;
	}
	const candidates = inferWorkspaceSourceCandidates(packageRoot, exportPath);
	for (const candidate of candidates) {
		if (existsSync(candidate)) {
			return candidate;
		}
	}
	return null;
}

function selectWorkspaceExportPath(
	exportValue: unknown,
	seen = new Set<unknown>(),
): string | null {
	if (typeof exportValue === "string") {
		return exportValue;
	}
	if (!exportValue || typeof exportValue !== "object") {
		return null;
	}
	if (seen.has(exportValue)) {
		return null;
	}
	seen.add(exportValue);
	const exports = exportValue as Record<string, unknown>;
	for (const condition of WORKSPACE_EXPORT_CONDITIONS) {
		const resolved = selectWorkspaceExportPath(exports[condition], seen);
		if (resolved) {
			return resolved;
		}
	}
	return null;
}

function inferWorkspaceSourceCandidates(
	packageRoot: string,
	exportPath: string,
): string[] {
	const normalizedPath = exportPath.replace(/^\.\//, "");
	const candidates = [resolve(packageRoot, exportPath)];
	if (normalizedPath.startsWith("dist/")) {
		const sourceBasePath = normalizedPath
			.replace(/^dist\//, "src/")
			.replace(/\.(mjs|cjs|js)$/, "");
		return [
			resolve(packageRoot, `${sourceBasePath}.ts`),
			resolve(packageRoot, `${sourceBasePath}.tsx`),
			resolve(packageRoot, `${sourceBasePath}.mts`),
			resolve(packageRoot, `${sourceBasePath}.cts`),
			...candidates,
		];
	}
	return candidates;
}

function sortAliasesBySpecificity(
	aliases: Record<string, string>,
): Record<string, string> {
	return Object.fromEntries(
		Object.entries(aliases).sort(
			([left], [right]) => right.length - left.length,
		),
	);
}

function isBareSpecifier(specifier: string): boolean {
	return !(
		specifier.startsWith(".") ||
		specifier.startsWith("/") ||
		specifier.startsWith("file:") ||
		specifier.startsWith("data:") ||
		specifier.startsWith("http:") ||
		specifier.startsWith("https:")
	);
}

function getPackageName(specifier: string): string {
	if (specifier.startsWith("@")) {
		const [scope, name] = specifier.split("/", 3);
		return name ? `${scope}/${name}` : specifier;
	}
	return specifier.split("/", 1)[0] ?? specifier;
}

function getPackageExportPath(specifier: string): string {
	const packageName = getPackageName(specifier);
	if (specifier === packageName) {
		return ".";
	}
	return `.${specifier.slice(packageName.length)}`;
}

function isClineSdkSpecifier(specifier: string): boolean {
	return getPackageName(specifier).startsWith("@cline/");
}

function hasInstalledDependency(
	pluginFilePath: string,
	specifier: string,
): boolean {
	const packageName = getPackageName(specifier);
	let current = dirname(pluginFilePath);
	while (true) {
		const packageDir = resolve(current, "node_modules", packageName);
		if (
			existsSync(packageDir) ||
			existsSync(resolve(packageDir, "package.json"))
		) {
			return true;
		}
		const parent = resolve(current, "..");
		if (parent === current) {
			return false;
		}
		current = parent;
	}
}

function resolvesFromHostRuntime(specifier: string): boolean {
	return resolveFromHostRuntime(specifier) !== null;
}

function resolveFromHostRuntime(specifier: string): string | null {
	try {
		return HOST_REQUIRE.resolve(specifier);
	} catch {
		// Continue with package export resolution for ESM-only package exports.
	}
	return resolveHostPackageExport(specifier);
}

function resolveHostPackageExport(specifier: string): string | null {
	const packageName = getPackageName(specifier);
	const packageRoot = findHostPackageRoot(packageName);
	if (!packageRoot) {
		return null;
	}
	const packageJsonPath = resolve(packageRoot, "package.json");
	try {
		const pkg = JSON.parse(readFileSync(packageJsonPath, "utf8")) as {
			exports?: unknown;
			main?: unknown;
		};
		const exportPath = getPackageExportPath(specifier);
		const exportValue =
			exportPath === "." && typeof pkg.exports === "string"
				? pkg.exports
				: pkg.exports &&
						typeof pkg.exports === "object" &&
						Object.hasOwn(pkg.exports, exportPath)
					? (pkg.exports as Record<string, unknown>)[exportPath]
					: undefined;
		const resolvedExportPath =
			selectWorkspaceExportPath(exportValue) ??
			(exportPath === "." && typeof pkg.main === "string" ? pkg.main : null);
		if (!resolvedExportPath) {
			return null;
		}
		const exportTarget = resolve(packageRoot, resolvedExportPath);
		const candidates = [
			exportTarget,
			...inferWorkspaceSourceCandidates(packageRoot, resolvedExportPath).filter(
				(candidate) => candidate !== exportTarget,
			),
		];
		for (const candidate of candidates) {
			if (existsSync(candidate)) {
				return candidate;
			}
		}
		return null;
	} catch {
		return null;
	}
}

function getHostPackageSearchRoots(): string[] {
	const roots = [MODULE_DIR];
	const wrapperPath = process.env.CLINE_WRAPPER_PATH?.trim();
	if (wrapperPath) {
		roots.push(dirname(dirname(wrapperPath)));
	}
	const execPath = process.execPath?.trim();
	if (execPath) {
		roots.push(dirname(execPath));
	}
	return [...new Set(roots.map((root) => resolve(root)))];
}

function findHostPackageRootFrom(
	startDir: string,
	packageName: string,
): string | null {
	let current = startDir;
	while (true) {
		const packageJsonPath = resolve(current, "package.json");
		if (existsSync(packageJsonPath)) {
			try {
				const pkg = JSON.parse(readFileSync(packageJsonPath, "utf8")) as {
					name?: unknown;
				};
				if (pkg.name === packageName) {
					return current;
				}
			} catch {
				// Keep walking; malformed manifests are not useful for resolution.
			}
		}
		const dependencyPackageJsonPath = resolve(
			current,
			"node_modules",
			packageName,
			"package.json",
		);
		if (existsSync(dependencyPackageJsonPath)) {
			return dirname(dependencyPackageJsonPath);
		}
		const parent = resolve(current, "..");
		if (parent === current) {
			return null;
		}
		current = parent;
	}
}

function findHostPackageRoot(packageName: string): string | null {
	for (const root of getHostPackageSearchRoots()) {
		const packageRoot = findHostPackageRootFrom(root, packageName);
		if (packageRoot) {
			return packageRoot;
		}
	}
	return null;
}

function isPackageBasedPlugin(pluginFilePath: string): boolean {
	// Walk up from the plugin file looking for a package.json with a `cline`
	// manifest. Stop at the first package.json we encounter; if it doesn't
	// declare `cline` we've left the plugin boundary (e.g. hit the workspace
	// root).  Also cap the traversal so we never wander far from the plugin
	// search root (.cline/plugins).
	const MAX_DEPTH = 4;
	let current = dirname(pluginFilePath);
	for (let depth = 0; depth < MAX_DEPTH; depth++) {
		const packageJsonPath = resolve(current, "package.json");
		if (existsSync(packageJsonPath)) {
			try {
				const pkg = JSON.parse(readFileSync(packageJsonPath, "utf8"));
				return pkg != null && typeof pkg === "object" && "cline" in pkg;
			} catch {
				return false;
			}
		}
		const parent = resolve(current, "..");
		if (parent === current) {
			return false;
		}
		current = parent;
	}
	return false;
}

function resolveRelativeImportPath(
	fromPath: string,
	specifier: string,
): string | null {
	const resolvedBase = specifier.startsWith("file:")
		? fileURLToPath(specifier)
		: isAbsolute(specifier)
			? specifier
			: resolve(dirname(fromPath), specifier);
	if (
		existsSync(resolvedBase) &&
		SUPPORTED_PLUGIN_EXTENSIONS.has(extname(resolvedBase))
	) {
		return resolvedBase;
	}
	for (const extension of SUPPORTED_PLUGIN_EXTENSIONS) {
		const withExtension = `${resolvedBase}${extension}`;
		if (existsSync(withExtension)) {
			return withExtension;
		}
	}
	for (const extension of SUPPORTED_PLUGIN_EXTENSIONS) {
		const indexPath = resolve(resolvedBase, `index${extension}`);
		if (existsSync(indexPath)) {
			return indexPath;
		}
	}
	return null;
}

function collectStaticModuleSpecifiers(source: string): string[] {
	const specifiers = new Set<string>();
	const patterns = [
		/\bimport\s+(?:type\s+)?[^"'`]*?\bfrom\s*["'`]([^"'`]+)["'`]/g,
		/\bexport\s+[^"'`]*?\bfrom\s*["'`]([^"'`]+)["'`]/g,
		/\bimport\s*\(\s*["'`]([^"'`]+)["'`]\s*\)/g,
		/\brequire\s*\(\s*["'`]([^"'`]+)["'`]\s*\)/g,
	];
	for (const pattern of patterns) {
		for (const match of source.matchAll(pattern)) {
			const specifier = match[1];
			if (specifier) {
				specifiers.add(specifier);
			}
		}
	}
	return [...specifiers];
}

function shouldPreflightBareDependencies(pluginPath: string): boolean {
	// TypeScript source can contain type-only import syntax that is not runtime
	// dependency evidence. Let jiti and Node report real runtime load failures.
	return extname(pluginPath) !== ".ts";
}

function assertPluginDependenciesInstalled(
	pluginPath: string,
	preferHostRuntimeDependencies: boolean,
	seen = new Set<string>(),
): void {
	if (seen.has(pluginPath) || !existsSync(pluginPath)) {
		return;
	}
	seen.add(pluginPath);

	if (!SUPPORTED_PLUGIN_EXTENSIONS.has(extname(pluginPath))) {
		return;
	}

	const source = readFileSync(pluginPath, "utf8");
	const preflightBareDependencies = shouldPreflightBareDependencies(pluginPath);
	for (const specifier of collectStaticModuleSpecifiers(source)) {
		if (specifier.startsWith("node:") || BUILTIN_MODULES.has(specifier)) {
			continue;
		}
		if (isBareSpecifier(specifier)) {
			if (!preflightBareDependencies) {
				continue;
			}
			if (
				Object.hasOwn(WORKSPACE_ALIASES, specifier) ||
				Object.hasOwn(WORKSPACE_ALIASES, getPackageName(specifier)) ||
				hasInstalledDependency(pluginPath, specifier) ||
				(isClineSdkSpecifier(specifier) &&
					resolvesFromHostRuntime(specifier)) ||
				(preferHostRuntimeDependencies && resolvesFromHostRuntime(specifier))
			) {
				continue;
			}
			throw new Error(`Cannot find module '${getPackageName(specifier)}'`);
		}
		const resolvedPath = resolveRelativeImportPath(pluginPath, specifier);
		if (resolvedPath) {
			assertPluginDependenciesInstalled(
				resolvedPath,
				preferHostRuntimeDependencies,
				seen,
			);
		}
	}
}

function collectPluginStaticModuleSpecifiers(
	pluginPath: string,
	seen = new Set<string>(),
	specifiers = new Set<string>(),
): Set<string> {
	if (seen.has(pluginPath) || !existsSync(pluginPath)) {
		return specifiers;
	}
	seen.add(pluginPath);

	if (!SUPPORTED_PLUGIN_EXTENSIONS.has(extname(pluginPath))) {
		return specifiers;
	}

	const source = readFileSync(pluginPath, "utf8");
	for (const specifier of collectStaticModuleSpecifiers(source)) {
		specifiers.add(specifier);
		if (isBareSpecifier(specifier)) {
			continue;
		}
		const resolvedPath = resolveRelativeImportPath(pluginPath, specifier);
		if (resolvedPath) {
			collectPluginStaticModuleSpecifiers(resolvedPath, seen, specifiers);
		}
	}
	return specifiers;
}

function collectPluginImportAliases(
	pluginPath: string,
	preferHostRuntimeDependencies: boolean,
): Record<string, string> {
	const pluginRequire = createRequire(pluginPath);
	const aliases: Record<string, string> = {};
	const staticSpecifiers = collectPluginStaticModuleSpecifiers(pluginPath);
	const hostRuntimeSpecifiers = new Set(HOST_PROVIDED_SDK_SPECIFIERS);
	for (const [specifier, sourcePath] of Object.entries(WORKSPACE_ALIASES)) {
		try {
			pluginRequire.resolve(specifier);
			continue;
		} catch {
			// Use the workspace source only when the plugin package does not provide
			// its own installed SDK dependency.
		}
		aliases[specifier] = sourcePath;
	}
	for (const specifier of staticSpecifiers) {
		if (
			isBareSpecifier(specifier) &&
			(isClineSdkSpecifier(specifier) || preferHostRuntimeDependencies)
		) {
			hostRuntimeSpecifiers.add(specifier);
		}
	}
	for (const specifier of hostRuntimeSpecifiers) {
		if (
			Object.hasOwn(aliases, specifier) ||
			hasInstalledDependency(pluginPath, specifier)
		) {
			continue;
		}
		const resolved = resolveFromHostRuntime(specifier);
		if (resolved) {
			aliases[specifier] = resolved;
		}
	}
	if (!preferHostRuntimeDependencies) {
		return aliases;
	}
	for (const specifier of staticSpecifiers) {
		if (
			!isBareSpecifier(specifier) ||
			Object.hasOwn(aliases, specifier) ||
			hasInstalledDependency(pluginPath, specifier) ||
			specifier.startsWith("node:") ||
			BUILTIN_MODULES.has(specifier)
		) {
			continue;
		}
		const resolved = resolveFromHostRuntime(specifier);
		if (resolved) {
			aliases[specifier] = resolved;
		}
	}
	return aliases;
}

function shouldTransformAliasTarget(target: string): boolean {
	const extension = extname(target);
	return (
		extension === ".ts" ||
		extension === ".tsx" ||
		extension === ".mts" ||
		extension === ".cts"
	);
}

type JitiTransform = (opts: {
	source: string;
	filename?: string;
	ts?: boolean;
	async?: boolean;
	jsx?: unknown;
	[key: string]: unknown;
}) => { code: string; error?: unknown };

let cachedJitiTransform: JitiTransform | null | undefined;

function loadJitiBabelTransform(): JitiTransform | null {
	if (cachedJitiTransform !== undefined) {
		return cachedJitiTransform;
	}
	// jiti's default lazyTransform path is
	//   createRequire(import.meta.url)("../dist/babel.cjs")
	// which fails in a `bun build --compile` binary: `import.meta.url` is
	// `bunfs:/root/chunk-XXXX.js`, so the relative resolve has nothing to
	// walk through. The wrapper install layout still has the real file at
	// <wrapper>/node_modules/jiti/dist/babel.cjs, so locate it on disk via
	// our host-package resolver and createRequire from an actual on-disk
	// path. Returning null falls back to jiti's own loader (works in dev).
	const jitiRoot = findHostPackageRoot("jiti");
	if (!jitiRoot) {
		cachedJitiTransform = null;
		return null;
	}
	const babelPath = resolve(jitiRoot, "dist", "babel.cjs");
	if (!existsSync(babelPath)) {
		cachedJitiTransform = null;
		return null;
	}
	try {
		const requireFromBabel = createRequire(babelPath);
		const transform = requireFromBabel(babelPath) as unknown;
		cachedJitiTransform =
			typeof transform === "function" ? (transform as JitiTransform) : null;
	} catch {
		cachedJitiTransform = null;
	}
	return cachedJitiTransform;
}

export async function importPluginModule(
	pluginPath: string,
	options: ImportPluginModuleOptions = {},
): Promise<Record<string, unknown>> {
	const preferHostRuntimeDependencies = !isPackageBasedPlugin(pluginPath);
	assertPluginDependenciesInstalled(pluginPath, preferHostRuntimeDependencies);
	const aliases = collectPluginImportAliases(
		pluginPath,
		preferHostRuntimeDependencies,
	);
	const sortedAliases = sortAliasesBySpecificity(aliases);
	const jitiModule = (await import("jiti")) as unknown;
	const createJiti =
		typeof jitiModule === "function"
			? jitiModule
			: typeof (jitiModule as { default?: unknown }).default === "function"
				? (jitiModule as { default: typeof import("jiti").default }).default
				: undefined;
	if (!createJiti) {
		throw new Error("Unable to load jiti");
	}
	const transformModules = Object.entries(sortedAliases)
		.filter(([, target]) => shouldTransformAliasTarget(target))
		.map(([specifier]) => specifier);
	// jiti's lazyTransform uses `createRequire(import.meta.url)("../dist/babel.cjs")`
	// to load its babel transformer on demand. In a `bun build --compile`
	// binary that fails because `import.meta.url` points inside the bunfs
	// bundle; the wrapper install still has the file on real disk though, so
	// we locate it via our host-package resolver and inject the transform.
	//
	// jiti threads its top-level `interopDefault` into babel via the transform
	// call's options (babel uses `noInterop: !interopDefault`). We want babel
	// to emit the CJS interop wrapper so `import YAML from "yaml"` works for
	// CJS deps, but we do not want jiti's runtime to wrap returned modules
	// in a default-synthesizing Proxy (that proxy makes `moduleExports.default`
	// truthy even for namespace-only modules, which breaks named-export
	// plugins). Pin `interopDefault: true` going into babel by overriding it
	// in the transform call, while keeping `interopDefault: false` on the jiti
	// instance so the loader sees raw exports.
	const baseBabelTransform = loadJitiBabelTransform();
	const babelTransform: JitiTransform | undefined = baseBabelTransform
		? (opts) => baseBabelTransform({ ...opts, interopDefault: true })
		: undefined;
	const jiti = createJiti(pluginPath, {
		alias: sortedAliases,
		cache: options.useCache,
		requireCache: options.useCache,
		esmResolve: true,
		interopDefault: false,
		nativeModules: [...BUILTIN_MODULES],
		transformModules,
		// On Bun (the packaged binary), tryNative defaults to true, which makes
		// jiti hand the plugin path straight to Bun's `import()`. Bun then owns
		// every nested import in the plugin, sees `import "@cline/core"` with no
		// node_modules adjacent to the drop-in plugin. Forcing tryNative off keeps
		// jiti in charge so bare specifiers can be rewritten through aliases first.
		tryNative: false,
		...(babelTransform ? { transform: babelTransform } : {}),
	});
	return (await jiti.import(pluginPath, {})) as Record<string, unknown>;
}

/**
 * Bootstrap script for the plugin sandbox subprocess.
 *
 * This file runs inside an isolated Node.js child process spawned by
 * {@link SubprocessSandbox}. It receives RPC calls over IPC and dynamically
 * imports plugin modules, wiring up their contributions (tools, commands,
 * message builders, providers) and lifecycle hooks.
 *
 * Because it executes in a separate process it must stay bundle-safe and only
 * depend on local helpers that can be inlined into the sandbox build.
 */

import {
	type AgentExtensionMcpServer,
	type AutomationEventEnvelope,
	normalizePluginManifest,
	type PluginManifest,
} from "@cline/shared";
import { importPluginModule } from "./plugin-module-import";
import {
	matchesPluginManifestTargeting,
	type PluginTargeting,
} from "./plugin-targeting";

// ---------------------------------------------------------------------------
// Types (intentionally minimal – mirrors only what the RPC protocol needs)
// ---------------------------------------------------------------------------

interface PluginTool {
	name: string;
	description?: string;
	inputSchema?: unknown;
	timeoutMs?: number;
	retryable?: boolean;
	execute: (input: unknown, context: unknown) => Promise<unknown>;
}

interface PluginCommand {
	name: string;
	description?: string;
	handler?: (
		input: string,
	) => Promise<PluginCommandResult> | PluginCommandResult;
}

// Keep this local mirror in sync with AgentExtensionCommandResult from @cline/shared.
// The sandbox bootstrap runs in an isolated process and avoids host package imports.
type PluginCommandResult =
	| string
	| {
			reply?: string;
			submitPrompt?: string;
	  };

interface PluginRule {
	id: string;
	content: string | (() => string | Promise<string>);
	source?: string;
}

interface PluginMessageBuilder {
	name: string;
	build: (message: unknown[]) => unknown[]; // Message[]
}

interface PluginProvider {
	name: string;
	description?: string;
	metadata?: Record<string, unknown>;
}

interface PluginAutomationEventType {
	eventType: string;
	source: string;
	description?: string;
	attributesSchema?: Record<string, unknown>;
	payloadSchema?: Record<string, unknown>;
	examples?: AutomationEventEnvelope[];
	metadata?: Record<string, unknown>;
}

interface PluginApi {
	registerTool(tool: PluginTool): void;
	registerCommand(command: PluginCommand): void;
	registerRule(rule: PluginRule): void;
	registerMessageBuilder(builder: PluginMessageBuilder): void;
	registerProvider(provider: PluginProvider): void;
	registerAutomationEventType(eventType: PluginAutomationEventType): void;
	registerMcpServer(server: AgentExtensionMcpServer): void;
}

interface PluginSetupCtx {
	session?: unknown;
	client?: unknown;
	user?: unknown;
	workspaceInfo?: unknown;
	automation?: {
		ingestEvent(event: AutomationEventEnvelope): void | Promise<void>;
	};
	logger?: {
		debug(message: string, metadata?: Record<string, unknown>): void;
		log(message: string, metadata?: Record<string, unknown>): void;
		error(message: string, metadata?: Record<string, unknown>): void;
	};
	telemetry?: PluginTelemetryBridge;
}

/**
 * Sandbox-side telemetry proxy, shaped like the host's ITelemetryService.
 * Live telemetry clients cannot cross the JSON IPC boundary, so capture and
 * record calls are forwarded to the host as `plugin_telemetry` events and
 * routed into the host telemetry service there. Identity and common-property
 * setters are host concerns and are intentionally no-ops in the sandbox.
 */
interface PluginTelemetryBridge {
	capture(input: {
		event: string;
		properties?: Record<string, unknown>;
	}): void;
	captureRequired(event: string, properties?: Record<string, unknown>): void;
	recordCounter(
		name: string,
		value: number,
		attributes?: Record<string, unknown>,
		description?: string,
		required?: boolean,
	): void;
	recordHistogram(
		name: string,
		value: number,
		attributes?: Record<string, unknown>,
		description?: string,
		required?: boolean,
	): void;
	recordGauge(
		name: string,
		value: number,
		attributes?: Record<string, unknown>,
		description?: string,
		required?: boolean,
	): void;
	isEnabled(): boolean;
	setDistinctId(distinctId?: string): void;
	setMetadata(metadata: Record<string, unknown>): void;
	updateMetadata(metadata: Record<string, unknown>): void;
	setCommonProperties(properties: Record<string, unknown>): void;
	updateCommonProperties(properties: Record<string, unknown>): void;
	flush(): Promise<void>;
	dispose(): Promise<void>;
}

interface PluginModule {
	name: string;
	manifest: PluginManifest;
	setup?: (api: PluginApi, ctx: PluginSetupCtx) => void | Promise<void>;
	hooks?: Record<string, (ctx: unknown) => unknown | Promise<unknown>>;
}

interface ContributionDescriptor {
	id: string;
	name: string;
	description?: string;
	inputSchema?: unknown;
	timeoutMs?: number;
	retryable?: boolean;
	value?: string;
	defaultValue?: boolean | string | number;
	metadata?: Record<string, unknown>;
}

interface RuleContributionDescriptor {
	id: string;
	ruleId: string;
	content?: string;
	source?: string;
	hasContentHandler?: boolean;
}

interface AutomationEventTypeDescriptor {
	id: string;
	eventType: string;
	source: string;
	description?: string;
	attributesSchema?: Record<string, unknown>;
	payloadSchema?: Record<string, unknown>;
	examples?: AutomationEventEnvelope[];
	metadata?: Record<string, unknown>;
}

interface PluginDescriptor {
	pluginId: string;
	pluginPath: string;
	name: string;
	manifest: PluginManifest;
	hooks?: string[];
	contributions: {
		tools: ContributionDescriptor[];
		commands: ContributionDescriptor[];
		rules: RuleContributionDescriptor[];
		messageBuilders: ContributionDescriptor[];
		providers: ContributionDescriptor[];
		automationEventTypes: AutomationEventTypeDescriptor[];
		mcpServers: AgentExtensionMcpServer[];
		shortcuts?: ContributionDescriptor[];
		flags?: ContributionDescriptor[];
	};
}

interface PluginInitializationFailure {
	pluginPath: string;
	pluginName?: string;
	phase: "load" | "setup";
	message: string;
	stack?: string;
}

interface PluginInitializationWarning {
	type: "duplicate_plugin_override";
	pluginPath: string;
	pluginName: string;
	overriddenPluginPath: string;
	message: string;
}

interface InitializeResult {
	plugins: PluginDescriptor[];
	failures: PluginInitializationFailure[];
	warnings: PluginInitializationWarning[];
}

interface PluginState {
	plugin: PluginModule;
	handlers: {
		tools: Map<string, PluginTool["execute"]>;
		commands: Map<string, NonNullable<PluginCommand["handler"]>>;
		rules: Map<string, () => string | Promise<string>>;
		messageBuilders: Map<string, PluginMessageBuilder["build"]>;
	};
}

type LoadedPluginResult =
	| {
			type: "loaded";
			descriptor: PluginDescriptor;
			state: PluginState;
	  }
	| {
			type: "skipped";
	  }
	| {
			type: "failure";
			failure: PluginInitializationFailure;
	  };

function isObject(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null;
}

function hasValidStringArray(value: unknown): value is string[] {
	return (
		Array.isArray(value) && value.every((entry) => typeof entry === "string")
	);
}

function assertValidPluginModule(
	plugin: unknown,
	pluginPath: string,
): asserts plugin is PluginModule {
	if (!isObject(plugin)) {
		throw new Error(`Invalid plugin module: ${pluginPath}`);
	}
	if (typeof plugin.name !== "string" || !plugin.name) {
		throw new Error(`Invalid plugin name: ${pluginPath}`);
	}
	if (!isObject(plugin.manifest)) {
		throw new Error(`Invalid plugin manifest: ${pluginPath}`);
	}
	if (
		Object.hasOwn(plugin.manifest, "providerIds") &&
		!hasValidStringArray(plugin.manifest.providerIds)
	) {
		throw new Error(`Invalid plugin manifest.providerIds: ${pluginPath}`);
	}
	if (
		Object.hasOwn(plugin.manifest, "modelIds") &&
		!hasValidStringArray(plugin.manifest.modelIds)
	) {
		throw new Error(`Invalid plugin manifest.modelIds: ${pluginPath}`);
	}
}

function assertValidPluginSetupCtx(
	ctx: unknown,
): asserts ctx is PluginSetupCtx {
	if (!isObject(ctx)) {
		throw new Error("Plugin setup context must be an object");
	}
	if (ctx.session !== undefined && !isObject(ctx.session)) {
		throw new Error("Plugin setup context session must be an object");
	}
	if (ctx.client !== undefined && !isObject(ctx.client)) {
		throw new Error("Plugin setup context client must be an object");
	}
	if (ctx.user !== undefined && !isObject(ctx.user)) {
		throw new Error("Plugin setup context user must be an object");
	}
	if (ctx.workspaceInfo !== undefined && !isObject(ctx.workspaceInfo)) {
		throw new Error("Plugin setup context workspaceInfo must be an object");
	}
	if (ctx.automation !== undefined && !isObject(ctx.automation)) {
		throw new Error("Plugin setup context automation must be an object");
	}
	if (
		ctx.automation !== undefined &&
		typeof ctx.automation.ingestEvent !== "function"
	) {
		throw new Error(
			"Plugin setup context automation.ingestEvent must be a function",
		);
	}
	if (ctx.logger !== undefined && !isObject(ctx.logger)) {
		throw new Error("Plugin setup context logger must be an object");
	}
}

// ---------------------------------------------------------------------------
// State
// ---------------------------------------------------------------------------

let pluginCounter = 0;
const pluginState = new Map<string, PluginState>();
const contributionCounters = new Map<string, number>();

// ---------------------------------------------------------------------------
// IPC helpers
// ---------------------------------------------------------------------------

function toErrorPayload(error: unknown): { message: string; stack?: string } {
	const message = error instanceof Error ? error.message : String(error);
	const stack = error instanceof Error ? error.stack : undefined;
	return { message, stack };
}

function sendResponse(
	id: string,
	ok: boolean,
	result: unknown,
	error?: { message: string; stack?: string },
): void {
	if (!process.send) return;
	process.send({ type: "response", id, ok, result, error });
}

function emitEvent(name: string, payload?: unknown): void {
	if (!process.send) return;
	process.send({ type: "event", name, payload });
}

// Expose event emitter to plugins.
(globalThis as Record<string, unknown>).__clinePluginHost = { emitEvent };

/**
 * Session workspace env — populated by `initialize()` and available to any
 * plugin code that executes before the setup hook, or cannot use hook context.
 * Prefer using PluginSetupCtx from the setup function when possible.
 */
(globalThis as Record<string, unknown>).__clineSessionEnv = {
	cwd: undefined as string | undefined,
	workspaceInfo: undefined as unknown,
};

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function sanitizeObject(value: unknown): Record<string, unknown> {
	if (!value || typeof value !== "object") return {};
	return value as Record<string, unknown>;
}

function sanitizeLogMetadata(
	value: unknown,
): Record<string, unknown> | undefined {
	if (!value || typeof value !== "object") {
		return undefined;
	}
	const metadata = { ...(value as Record<string, unknown>) };
	if (metadata.error instanceof Error) {
		metadata.error = {
			name: metadata.error.name,
			message: metadata.error.message,
			stack: metadata.error.stack,
		};
	}
	return metadata;
}

function createPluginLogger(
	pluginName: string,
): NonNullable<PluginSetupCtx["logger"]> {
	const emitLog = (
		level: "debug" | "log" | "error",
		message: string,
		metadata?: Record<string, unknown>,
	) => {
		emitEvent("plugin_log", {
			level,
			pluginName,
			message,
			metadata: sanitizeLogMetadata(metadata),
		});
	};
	return {
		debug: (message, metadata) => emitLog("debug", message, metadata),
		log: (message, metadata) => emitLog("log", message, metadata),
		error: (message, metadata) => emitLog("error", message, metadata),
	};
}

function createPluginTelemetry(pluginName: string): PluginTelemetryBridge {
	const emit = (payload: Record<string, unknown>) => {
		emitEvent("plugin_telemetry", { pluginName, ...payload });
	};
	const record =
		(metric: "counter" | "histogram" | "gauge") =>
		(
			name: string,
			value: number,
			attributes?: Record<string, unknown>,
			description?: string,
			required?: boolean,
		) => {
			emit({
				kind: "metric",
				metric,
				name,
				value,
				attributes: sanitizeLogMetadata(attributes),
				description,
				required,
			});
		};
	const noop = () => {
		// Identity and common properties are managed by the host telemetry
		// service; sandboxed plugins cannot change them.
	};
	return {
		capture: (input) => {
			emit({
				kind: "event",
				event: input?.event,
				properties: sanitizeLogMetadata(input?.properties),
			});
		},
		captureRequired: (event, properties) => {
			emit({
				kind: "event",
				event,
				properties: sanitizeLogMetadata(properties),
				required: true,
			});
		},
		recordCounter: record("counter"),
		recordHistogram: record("histogram"),
		recordGauge: record("gauge"),
		// The bridge is stateless: the host is the arbiter of whether
		// telemetry is enabled and drops forwarded events when the user has
		// opted out. Reporting true keeps plugins emitting unconditionally —
		// which also means isEnabled() cannot be used to skip expensive
		// property computation in sandboxed plugins; keep properties cheap.
		isEnabled: () => true,
		setDistinctId: noop,
		setMetadata: noop,
		updateMetadata: noop,
		setCommonProperties: noop,
		updateCommonProperties: noop,
		flush: async () => {},
		dispose: async () => {},
	};
}

function makeId(pluginId: string, prefix: string): string {
	const key = `${pluginId}:${prefix}`;
	const next = (contributionCounters.get(key) ?? 0) + 1;
	contributionCounters.set(key, next);
	return `${pluginId}_${prefix}_${next}`;
}

function normalizeAutomationEventType(
	eventType: PluginAutomationEventType,
): PluginAutomationEventType {
	const normalizedEventType =
		typeof eventType.eventType === "string" ? eventType.eventType.trim() : "";
	const source =
		typeof eventType.source === "string" ? eventType.source.trim() : "";
	if (!normalizedEventType) {
		throw new Error("Automation event type contribution requires eventType");
	}
	if (!source) {
		throw new Error("Automation event type contribution requires source");
	}
	return {
		...eventType,
		eventType: normalizedEventType,
		source,
		examples: eventType.examples ? [...eventType.examples] : undefined,
		metadata: eventType.metadata
			? sanitizeObject(eventType.metadata)
			: undefined,
	};
}

function getPlugin(pluginId: string): PluginState {
	const state = pluginState.get(pluginId);
	if (!state) {
		throw new Error(`Unknown sandbox plugin id: ${pluginId}`);
	}
	return state;
}

async function loadPluginDescriptor(args: {
	pluginPath: string;
	pluginId: string;
	exportName: string;
	targeting: PluginTargeting;
	setupCtxBase: Pick<
		PluginSetupCtx,
		"session" | "client" | "user" | "workspaceInfo"
	>;
	loggerEnabled?: boolean;
	telemetryEnabled?: boolean;
}): Promise<LoadedPluginResult> {
	let plugin: PluginModule | undefined;
	try {
		const moduleExports = await importPluginModule(args.pluginPath);
		plugin = (moduleExports.default ??
			moduleExports[args.exportName]) as unknown as PluginModule;
		assertValidPluginModule(plugin, args.pluginPath);
		plugin.manifest = normalizePluginManifest(plugin.manifest);
		if (!matchesPluginManifestTargeting(plugin.manifest, args.targeting)) {
			return { type: "skipped" };
		}

		const contributions: PluginDescriptor["contributions"] = {
			tools: [],
			commands: [],
			rules: [],
			messageBuilders: [],
			providers: [],
			automationEventTypes: [],
			mcpServers: [],
			shortcuts: [],
			flags: [],
		};
		const handlers: PluginState["handlers"] = {
			tools: new Map(),
			commands: new Map(),
			rules: new Map(),
			messageBuilders: new Map(),
		};

		const api: PluginApi = {
			registerTool: (tool) => {
				const id = makeId(args.pluginId, "tool");
				handlers.tools.set(id, tool.execute);
				contributions.tools.push({
					id,
					name: tool.name,
					description: tool.description,
					inputSchema: tool.inputSchema,
					timeoutMs: tool.timeoutMs,
					retryable: tool.retryable,
				});
			},
			registerCommand: (command) => {
				const id = makeId(args.pluginId, "command");
				if (typeof command.handler === "function") {
					handlers.commands.set(id, command.handler);
				}
				contributions.commands.push({
					id,
					name: command.name,
					description: command.description,
				});
			},
			registerRule: (rule) => {
				const id = makeId(args.pluginId, "rule");
				if (typeof rule.content === "function") {
					handlers.rules.set(id, rule.content);
					contributions.rules.push({
						id,
						ruleId: rule.id,
						source: rule.source,
						hasContentHandler: true,
					});
					return;
				}
				contributions.rules.push({
					id,
					ruleId: rule.id,
					content: rule.content,
					source: rule.source,
				});
			},
			registerMessageBuilder: (builder) => {
				const id = makeId(args.pluginId, "builder");
				handlers.messageBuilders.set(id, builder.build);
				contributions.messageBuilders.push({ id, name: builder.name });
			},
			registerProvider: (provider) => {
				contributions.providers.push({
					id: makeId(args.pluginId, "provider"),
					name: provider.name,
					description: provider.description,
					metadata: sanitizeObject(provider.metadata),
				});
			},
			registerAutomationEventType: (eventType) => {
				contributions.automationEventTypes.push({
					id: makeId(args.pluginId, "automation_event"),
					...normalizeAutomationEventType(eventType),
				});
			},
			registerMcpServer: (server) => {
				contributions.mcpServers.push(server);
			},
		};

		if (typeof plugin.setup === "function") {
			try {
				const setupCtx = {
					...args.setupCtxBase,
					// Only offered when the host actually has a telemetry service:
					// the feature-detection contract (`ctx.telemetry?.capture`) must
					// mean "someone is listening", matching in-process behavior.
					...(args.telemetryEnabled
						? { telemetry: createPluginTelemetry(plugin.name) }
						: {}),
					...(args.loggerEnabled
						? { logger: createPluginLogger(plugin.name) }
						: {}),
					...(plugin.manifest.capabilities.includes("automationEvents")
						? {
								automation: {
									ingestEvent: (event: AutomationEventEnvelope) => {
										emitEvent("automation_event", event);
									},
								},
							}
						: {}),
				};
				assertValidPluginSetupCtx(setupCtx);
				await plugin.setup(api, setupCtx);
			} catch (error) {
				return {
					type: "failure",
					failure: {
						pluginPath: args.pluginPath,
						pluginName: plugin.name,
						phase: "setup",
						message: error instanceof Error ? error.message : String(error),
						stack: error instanceof Error ? error.stack : undefined,
					},
				};
			}
		}

		return {
			type: "loaded",
			state: { plugin, handlers },
			descriptor: {
				pluginId: args.pluginId,
				pluginPath: args.pluginPath,
				name: plugin.name,
				manifest: plugin.manifest,
				hooks: plugin.hooks
					? Object.entries(plugin.hooks)
							.filter(([, hook]) => typeof hook === "function")
							.map(([name]) => name)
					: undefined,
				contributions,
			},
		};
	} catch (error) {
		return {
			type: "failure",
			failure: {
				pluginPath: args.pluginPath,
				pluginName: plugin?.name,
				phase: "load",
				message: error instanceof Error ? error.message : String(error),
				stack: error instanceof Error ? error.stack : undefined,
			},
		};
	}
}

// ---------------------------------------------------------------------------
// RPC methods
// ---------------------------------------------------------------------------

async function initialize(args: {
	pluginPaths?: string[];
	exportName?: string;
	providerId?: string;
	modelId?: string;
	cwd?: string;
	session?: unknown;
	client?: unknown;
	user?: unknown;
	workspaceInfo?: unknown;
	loggerEnabled?: boolean;
	telemetryEnabled?: boolean;
}): Promise<InitializeResult> {
	pluginState.clear();
	pluginCounter = 0;
	contributionCounters.clear();

	// Apply the session's working directory so that process.cwd() and relative
	// path resolution inside plugins reflect the correct workspace, not the
	// host process's cwd (which may differ when --cwd was used without calling
	// process.chdir() on the host side).
	if (args.cwd) {
		try {
			process.chdir(args.cwd);
		} catch {
			// Ignore — best-effort; path may not exist in unusual environments.
		}
	}

	// Keep the global escape-hatch in sync with the active session.
	const sessionEnv = (globalThis as Record<string, unknown>)
		.__clineSessionEnv as Record<string, unknown>;
	if (sessionEnv) {
		sessionEnv.cwd = args.cwd;
		sessionEnv.workspaceInfo = args.workspaceInfo;
	}

	const descriptors: PluginDescriptor[] = [];
	const failures: PluginInitializationFailure[] = [];
	const warnings: PluginInitializationWarning[] = [];
	const exportName = args.exportName || "plugin";
	const pluginIndexByName = new Map<string, number>();
	const targeting: PluginTargeting = {
		providerId: args.providerId,
		modelId: args.modelId,
	};
	const setupCtxBase = {
		session: args.session,
		client: args.client,
		user: args.user,
		workspaceInfo: args.workspaceInfo,
	};

	const loadResults = await Promise.all(
		(args.pluginPaths || []).map((pluginPath) => {
			const pluginId = `plugin_${++pluginCounter}`;
			return loadPluginDescriptor({
				pluginPath,
				pluginId,
				exportName,
				targeting,
				setupCtxBase,
				loggerEnabled: args.loggerEnabled,
				telemetryEnabled: args.telemetryEnabled,
			});
		}),
	);

	for (const result of loadResults) {
		if (result.type === "skipped") {
			continue;
		}
		if (result.type === "failure") {
			failures.push(result.failure);
			continue;
		}

		const { descriptor, state } = result;
		const previousIndex = pluginIndexByName.get(descriptor.name);
		if (previousIndex !== undefined) {
			const previous = descriptors[previousIndex];
			if (!previous) {
				pluginIndexByName.delete(descriptor.name);
			} else {
				warnings.push({
					type: "duplicate_plugin_override",
					pluginName: descriptor.name,
					pluginPath: descriptor.pluginPath,
					overriddenPluginPath: previous.pluginPath,
					message: `Plugin "${descriptor.name}" from ${descriptor.pluginPath} overrides ${previous.pluginPath}`,
				});
				pluginState.delete(previous.pluginId);
				descriptors.splice(previousIndex, 1);
				pluginIndexByName.clear();
				for (const [index, descriptor] of descriptors.entries()) {
					pluginIndexByName.set(descriptor.name, index);
				}
			}
		}

		pluginState.set(descriptor.pluginId, state);
		pluginIndexByName.set(descriptor.name, descriptors.length);
		descriptors.push(descriptor);
	}

	return { plugins: descriptors, failures, warnings };
}

async function invokeHook(args: {
	pluginId: string;
	hookName: string;
	payload: unknown;
}): Promise<unknown> {
	const state = getPlugin(args.pluginId);
	const handler = state.plugin.hooks?.[args.hookName];
	if (typeof handler !== "function") {
		return undefined;
	}
	return await (handler as (payload: unknown) => Promise<unknown>)(
		args.payload,
	);
}

async function executeTool(args: {
	pluginId: string;
	contributionId: string;
	input: unknown;
	context: unknown;
}): Promise<unknown> {
	const state = getPlugin(args.pluginId);
	const handler = state.handlers.tools.get(args.contributionId);
	if (typeof handler !== "function") {
		throw new Error("Unknown sandbox tool contribution");
	}
	return await handler(args.input, args.context);
}

async function executeCommand(args: {
	pluginId: string;
	contributionId: string;
	input: string;
}): Promise<PluginCommandResult> {
	const state = getPlugin(args.pluginId);
	const handler = state.handlers.commands.get(args.contributionId);
	if (typeof handler !== "function") {
		return "";
	}
	return await handler(args.input);
}

async function buildMessages(args: {
	pluginId: string;
	contributionId: string;
	messages: unknown[];
}): Promise<unknown[]> {
	const state = getPlugin(args.pluginId);
	const handler = state.handlers.messageBuilders.get(args.contributionId);
	if (typeof handler !== "function") {
		return [];
	}
	return await handler(args.messages);
}

async function resolveRuleContent(args: {
	pluginId: string;
	contributionId: string;
}): Promise<string> {
	const state = getPlugin(args.pluginId);
	const handler = state.handlers.rules.get(args.contributionId);
	if (typeof handler !== "function") {
		return "";
	}
	return await handler();
}

// ---------------------------------------------------------------------------
// Message dispatch
// ---------------------------------------------------------------------------

const methods: Record<string, (args: never) => Promise<unknown>> = {
	initialize,
	invokeHook,
	executeTool,
	executeCommand,
	buildMessages,
	resolveRuleContent,
};

process.on(
	"message",
	async (message: {
		type: string;
		id: string;
		method: string;
		args?: unknown;
	}) => {
		if (!message || message.type !== "call") {
			return;
		}
		const method = methods[message.method];
		if (!method) {
			sendResponse(message.id, false, undefined, {
				message: `Unknown method: ${String(message.method)}`,
			});
			return;
		}
		try {
			const result = await method((message.args || {}) as never);
			sendResponse(message.id, true, result);
		} catch (error) {
			sendResponse(message.id, false, undefined, toErrorPayload(error));
		}
	},
);

