function registerMessageBuilders(
	api: AgentExtensionApi,
	sandbox: SubprocessSandbox,
	descriptor: SandboxedPluginDescriptor,
	timeoutMs: number,
	reinitialize: () => Promise<void>,
): void {
	for (const bd of descriptor.contributions?.messageBuilders ?? []) {
		api.registerMessageBuilder({
			name: bd.name,
			async build(messages) {
				try {
					const result = await sandbox.call<unknown[]>(
						"buildMessages",
						{
							pluginId: descriptor.pluginId,
							contributionId: bd.id,
							messages,
						},
						{ timeoutMs },
					);
					return isMessageArray(result) ? result : messages;
				} catch (error) {
					if (!isUnknownPluginIdError(error)) {
						throw error;
					}
					await reinitialize();
					const result = await sandbox.call<unknown[]>(
						"buildMessages",
						{
							pluginId: descriptor.pluginId,
							contributionId: bd.id,
							messages,
						},
						{ timeoutMs },
					);
					return isMessageArray(result) ? result : messages;
				}
			},
		});
	}
}

function isMessageArray(value: unknown): value is Message[] {
	return (
		Array.isArray(value) &&
		value.every(
			(entry) =>
				typeof entry === "object" &&
				entry !== null &&
				"role" in entry &&
				"content" in entry,
		)
	);
}

function makeHookHandler(
	sandbox: SubprocessSandbox,
	pluginId: string,
	hookName: string,
	timeoutMs: number,
	reinitialize: () => Promise<void>,
): (payload: unknown) => Promise<unknown> {
	return async (payload: unknown) => {
		const invoke = async (sandboxPayload: unknown) => {
			try {
				return await sandbox.call(
					"invokeHook",
					{ pluginId, hookName, payload: sandboxPayload },
					{ timeoutMs },
				);
			} catch (error) {
				if (!isUnknownPluginIdError(error)) {
					throw error;
				}
				await reinitialize();
				return await sandbox.call(
					"invokeHook",
					{ pluginId, hookName, payload: sandboxPayload },
					{ timeoutMs },
				);
			}
		};
		return await callWithSerializableFallback(invoke, payload, (error) =>
			warnNonSerializablePayloadOnce("hook", hookName, error),
		);
	};
}

function createSandboxRuntimeHooks(
	sandbox: SubprocessSandbox,
	descriptor: SandboxedPluginDescriptor,
	hookTimeoutMs: number,
	reinitialize: () => Promise<void>,
): Partial<AgentRuntimeHooks> | undefined {
	const hooks: Partial<
		Record<keyof AgentRuntimeHooks, (payload: unknown) => Promise<unknown>>
	> = {};
	for (const hookName of descriptor.hooks ?? []) {
		hooks[hookName] = makeHookHandler(
			sandbox,
			descriptor.pluginId,
			hookName,
			hookTimeoutMs,
			reinitialize,
		);
	}
	return Object.keys(hooks).length > 0
		? (hooks as Partial<AgentRuntimeHooks>)
		: undefined;
}

import type { PluginManifest } from "@cline/shared";

export interface PluginTargeting {
	providerId?: string;
	modelId?: string;
}

export function matchesPluginManifestTargeting(
	manifest: PluginManifest | undefined,
	targeting: PluginTargeting | undefined,
): boolean {
	if (!manifest) {
		return true;
	}

	if (manifest.providerIds?.length) {
		if (
			!targeting?.providerId ||
			!manifest.providerIds.includes(targeting.providerId)
		) {
			return false;
		}
	}

	if (manifest.modelIds?.length) {
		if (!targeting?.modelId || !manifest.modelIds.includes(targeting.modelId)) {
			return false;
		}
	}

	return true;
}

