});

/**
 * Plan-Mode Command Guard Extension
 *
 * Runtime extension that enforces the plan-mode command blacklist
 * (./command-guard.ts) as a `beforeTool` hook. The runtime builder registers
 * it for plan-mode sessions, making command blocking session policy in one
 * shared place: the hook fires for every `run_commands` tool in the runtime —
 * the SDK built-in and host-provided replacements like the VS Code
 * extension's terminal-backed tool — without threading a flag through each
 * layer.
 *
 * Because `beforeTool` hooks run before tool policies and user approval,
 * a blocked call is rejected up front: the user is never asked to approve a
 * command that would only fail, and the model receives the plan-mode error
 * as the tool result (`skip`, not `stop`, so the run continues).
 */

import type {
	AgentBeforeToolContext,
	AgentBeforeToolResult,
	AgentExtension,
	ITelemetryService,
} from "@cline/shared";
import { capturePlanModeCommandBlocked } from "../../services/telemetry/core-events";
import {
	findFileEditingCommand,
	formatPlanModeBlockedCommandError,
} from "./command-guard";
import { DefaultToolNames } from "./constants";
import { normalizeRunCommandsInput } from "./helpers";

export const PLAN_MODE_COMMAND_GUARD_EXTENSION_NAME =
	"core.plan-mode-command-guard";

export interface PlanModeCommandGuardOptions {
	telemetry?: ITelemetryService;
}

export function createPlanModeCommandGuardExtension(
	options: PlanModeCommandGuardOptions = {},
): AgentExtension {
	const beforeTool = (
		context: AgentBeforeToolContext,
	): AgentBeforeToolResult | undefined => {
		if (context.tool.name !== DefaultToolNames.RUN_COMMANDS) {
			return undefined;
		}

		let commands: ReturnType<typeof normalizeRunCommandsInput>;
		try {
			commands = normalizeRunCommandsInput(context.input);
		} catch {
			// Unparseable input: let the tool produce its own validation error.
			return undefined;
		}

		for (const command of commands) {
			const blocked = findFileEditingCommand(command);
			if (blocked) {
				capturePlanModeCommandBlocked(options.telemetry, {
					tool_name: "run_commands",
					blocked_construct: blocked,
					command_count: commands.length,
					agent_id: context.snapshot.agentId,
					conversation_id: context.snapshot.conversationId,
					run_id: context.snapshot.runId,
					iteration: context.snapshot.iteration,
					tool_call_id: context.toolCall.toolCallId,
				});
				return {
					skip: true,
					reason: formatPlanModeBlockedCommandError(blocked),
				};
			}
		}

		return undefined;
	};

	return {
		name: PLAN_MODE_COMMAND_GUARD_EXTENSION_NAME,
		manifest: {
			capabilities: ["hooks"],
		},
		hooks: {
			beforeTool,
		},
	};
}

import { describe, expect, it } from "vitest";
import {
	findFileEditingCommand,
	formatPlanModeBlockedCommandError,
} from "./command-guard";

/** Convenience: true when the guard blocks the command. */
function blocks(command: string): boolean {
	return findFileEditingCommand(command) !== undefined;
}

describe("findFileEditingCommand — read-only commands pass", () => {
	it.each([
		"ls -la",
		"pwd",
		"cat package.json",
		"head -n 50 src/index.ts",
		"tail -f /var/log/syslog",
		"grep -rn 'createShellTool' src/",
		"rg --files-with-matches 'ToolPresets'",
		"find . -name '*.ts' -not -path '*/node_modules/*'",
		"git status --short",
		"git log --oneline -20",
		"git diff HEAD~1",
		"git show HEAD:src/index.ts",
		"git blame src/index.ts",
		"git fetch origin main",
		"git branch --list",
		"wc -l src/*.ts",
		"du -sh node_modules",
		"df -h",
		"ps aux",
		"which node",
		"node --version",
		"npm ls --depth=0",
		"npm view zod versions",
		"bun run test",
		"bun test src/extensions",
		"cargo check",
		"cargo tree",
		"pip show requests",
		"brew list",
		"sed -n '1,20p' src/index.ts",
		"sed 's/foo/bar/' input.txt",
		"sort -u names.txt",
		"awk '{print $1}' data.csv",
		"awk '$3 > 100 {print}' data.csv",
		"diff a.txt b.txt",
		"curl -s https://example.com/api",
		"echo hello world",
		"printf '%s\\n' one two",
		"env | sort",
		"xargs -n1 echo < list.txt",
		"stat src/index.ts",
		"file dist/extension.js",
		"tree -L 2 src",
	])("allows %s", (command) => {
		expect(findFileEditingCommand(command)).toBeUndefined();
	});

	it("allows redirection to /dev/null and fd duplication", () => {
		expect(blocks("ls > /dev/null")).toBe(false);
		expect(blocks("ls 2> /dev/null")).toBe(false);
		expect(blocks("make check 2>&1 | tail -n 50")).toBe(false);
		expect(blocks("echo warn >&2")).toBe(false);
		expect(blocks("cmd &> /dev/null")).toBe(false);
	});

	it("allows redirection and tee into /tmp (documented output-capture pattern)", () => {
		expect(blocks("bun run build > /tmp/build.log 2>&1")).toBe(false);
		expect(blocks("npm test >> /tmp/test-output.txt")).toBe(false);
		expect(blocks("cargo build 2>&1 | tee /tmp/cargo.log")).toBe(false);
		expect(blocks("long_cmd > $TMPDIR/out.log")).toBe(false);
	});

	it("does not flag operators inside quotes", () => {
		expect(blocks("grep '=>' src/index.ts")).toBe(false);
		expect(blocks('echo "a > b"')).toBe(false);
		expect(blocks("git log --grep='rm -rf'")).toBe(false);
		expect(blocks('rg "touch(ed)?" docs/')).toBe(false);
		expect(blocks("echo 'mkdir is a command'")).toBe(false);
	});

	it("does not flag blocked names in argument position", () => {
		expect(blocks("man rm")).toBe(false);
		expect(blocks("which mv cp rm")).toBe(false);
		expect(blocks("git log -- rm.txt")).toBe(false);
		expect(blocks("cat mv-guide.md")).toBe(false);
	});

	it("does not flag heredoc bodies fed to read-only commands", () => {
		const command = ["python3 <<'EOF'", "x = 10", "print(x > 5)", "EOF"].join(
			"\n",
		);
		expect(blocks(command)).toBe(false);
	});

	it("skips escaped characters and comments", () => {
		expect(blocks("echo a \\> b")).toBe(false);
		expect(blocks("ls # > notes.txt")).toBe(false);
	});
});

describe("findFileEditingCommand — file mutations are blocked", () => {
	it.each([
		["rm -rf build", "`rm`"],
		["rm file.txt", "`rm`"],
		["mv a.txt b.txt", "`mv`"],
		["cp src.txt dst.txt", "`cp`"],
		["touch new-file.ts", "`touch`"],
		["mkdir -p src/new-dir", "`mkdir`"],
		["chmod +x script.sh", "`chmod`"],
		["chown user file", "`chown`"],
		["ln -s a b", "`ln`"],
		["truncate -s 0 log.txt", "`truncate`"],
		["dd if=/dev/zero of=file bs=1M count=1", "`dd`"],
		["patch -p1 < fix.patch", "`patch`"],
		["rsync -a src/ dst/", "`rsync`"],
		["install -m 755 bin/tool /usr/local/bin", "`install`"],
	])("blocks %s", (command, reason) => {
		expect(findFileEditingCommand(command)).toBe(reason);
	});

	it("blocks Windows and PowerShell file mutations", () => {
		expect(findFileEditingCommand("del /f file.txt")).toBe("`del`");
		expect(findFileEditingCommand("move a.txt b.txt")).toBe("`move`");
