// =============================================================================
// Default Tools Factory
// =============================================================================

/**
 * Create a set of default tools for an agent
 *
 * This function creates the default tools based on the provided configuration
 * and executors. Only tools that are enabled AND have an executor provided
 * will be included in the returned array.
 *
 * @example
 * ```typescript
 * import { Agent, createDefaultTools } from "@cline/core"
 * import * as fs from "fs/promises"
 * import { exec } from "child_process"
 *
 * const tools = createDefaultTools({
 *   executors: {
 *     readFile: async ({ path }) => fs.readFile(path, "utf-8"),
 *     bash: async (cmd, cwd) => {
 *       return new Promise((resolve, reject) => {
 *         exec(cmd, { cwd }, (err, stdout, stderr) => {
 *           if (err) reject(new Error(stderr || err.message))
 *           else resolve(stdout)
 *         })
 *       })
 *     },
 *   },
 *   enableReadFiles: true,
 *   enableBash: true,
 *   enableSearch: false, // Disabled
 *   enableWebFetch: false, // Disabled
 *   cwd: "/path/to/project",
 * })
 *
 * const agent = new Agent({
 *   // ... provider config
 *   tools,
 * })
 * ```
 */
export function createDefaultTools(
	options: CreateDefaultToolsOptions,
): AgentTool[] {
	const {
		executors,
		enableReadFiles = true,
		enableSearch = true,
		enableBash = true,
		enableWebFetch = true,
		enableApplyPatch = false,
		enableEditor = true,
		enableSkills = true,
		enableAskQuestion = true,
		enableSubmitAndExit = false,
		...config
	} = options;

	const tools: AgentTool<never, unknown>[] = [];

	// Add read_files tool if enabled and executor provided
	if (enableReadFiles && executors.readFile) {
		tools.push(createReadFilesTool(executors.readFile, config));
	}

	// Add search_codebase tool if enabled and executor provided
	if (enableSearch && executors.search) {
		tools.push(createSearchTool(executors.search, config));
	}

	// Add run_commands tool if enabled and executor provided
	if (enableBash && executors.bash) {
		tools.push(createShellTool(executors.bash, config));
	}

	// Add fetch_web_content tool if enabled and executor provided
	if (enableWebFetch && executors.webFetch) {
		tools.push(createWebFetchTool(executors.webFetch, config));
	}

	// Add editor tool if enabled and executor provided,
	// else check if apply_patch tool is enabled and executor provided
	// NOTE: Do not enable two similar tools at the same time.
	if (enableEditor && executors.editor) {
		tools.push(createEditorTool(executors.editor, config));
	} else if (enableApplyPatch && executors.applyPatch) {
		tools.push(createApplyPatchTool(executors.applyPatch, config));
	}

	// Add skills tool if enabled and executor provided
	if (enableSkills && executors.skills) {
		tools.push(createSkillsTool(executors.skills, config));
	}

	const submitExecutor = enableSubmitAndExit ? executors.submit : undefined;

	// Add ask_question tool if enabled and executor provided
	if (enableAskQuestion && executors.askQuestion && !submitExecutor) {
		tools.push(createAskQuestionTool(executors.askQuestion));
	}

	// Add submit_and_exit tool if enabled and executor provided
	if (submitExecutor) {
		tools.push(createSubmitAndExitTool(submitExecutor, config));
	}

	return tools as unknown as AgentTool[];
}

/**
 * Apply Patch parser and patch model types.
 *
 * This parser supports the Cline apply_patch format used by the legacy runtime.
 */

export const PATCH_MARKERS = {
	BEGIN: "*** Begin Patch",
	END: "*** End Patch",
	ADD: "*** Add File: ",
	UPDATE: "*** Update File: ",
	DELETE: "*** Delete File: ",
	MOVE: "*** Move to: ",
	SECTION: "@@",
	END_FILE: "*** End of File",
} as const;

export const BASH_WRAPPERS = ["%%bash", "apply_patch", "EOF", "```"] as const;

export enum PatchActionType {
	ADD = "add",
	DELETE = "delete",
	UPDATE = "update",
}

export interface PatchChunk {
	origIndex: number;
	delLines: string[];
	insLines: string[];
}

export interface PatchAction {
	type: PatchActionType;
	newFile?: string;
	chunks: PatchChunk[];
	movePath?: string;
}

export interface PatchWarning {
	path: string;
	chunkIndex?: number;
	message: string;
	context?: string;
}

export interface Patch {
	actions: Record<string, PatchAction>;
	warnings?: PatchWarning[];
}

export class DiffError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "DiffError";
	}
}

function canonicalize(input: string): string {
	const punctuationMap: Record<string, string> = {
		"\u2010": "-",
		"\u2011": "-",
		"\u2012": "-",
		"\u2013": "-",
		"\u2014": "-",
		"\u2212": "-",
		"\u201C": '"',
		"\u201D": '"',
		"\u201E": '"',
		"\u00AB": '"',
		"\u00BB": '"',
		"\u2018": "'",
		"\u2019": "'",
		"\u201B": "'",
		"\u00A0": " ",
		"\u202F": " ",
	};
	return input
		.normalize("NFC")
		.replace(/./gu, (char) => punctuationMap[char] ?? char)
		.replace(/\\`/g, "`")
		.replace(/\\'/g, "'")
		.replace(/\\"/g, '"');
}

export class PatchParser {
	private patch: Patch = { actions: {}, warnings: [] };
	private index = 0;
	private fuzz = 0;
	private currentPath?: string;

	constructor(
		private readonly lines: string[],
		private readonly currentFiles: Record<string, string>,
	) {}

	parse(): { patch: Patch; fuzz: number } {
		this.skipBeginSentinel();

		while (this.hasMoreLines() && !this.isEndMarker()) {
			this.parseNextAction();
		}

		if (this.patch.warnings?.length === 0) {
			delete this.patch.warnings;
		}

		return { patch: this.patch, fuzz: this.fuzz };
	}

	private addWarning(warning: PatchWarning): void {
		if (!this.patch.warnings) {
			this.patch.warnings = [];
		}
		this.patch.warnings.push(warning);
	}

	private skipBeginSentinel(): void {
		if (this.lines[this.index]?.startsWith(PATCH_MARKERS.BEGIN)) {
			this.index++;
		}
	}

	private hasMoreLines(): boolean {
		return this.index < this.lines.length;
	}

	private isEndMarker(): boolean {
		return this.lines[this.index]?.startsWith(PATCH_MARKERS.END) ?? false;
	}

	private parseNextAction(): void {
		const line = this.lines[this.index];
		if (line?.startsWith(PATCH_MARKERS.UPDATE)) {
			this.parseUpdate(line.substring(PATCH_MARKERS.UPDATE.length).trim());
			return;
		}
		if (line?.startsWith(PATCH_MARKERS.DELETE)) {
			this.parseDelete(line.substring(PATCH_MARKERS.DELETE.length).trim());
			return;
		}
		if (line?.startsWith(PATCH_MARKERS.ADD)) {
			this.parseAdd(line.substring(PATCH_MARKERS.ADD.length).trim());
			return;
		}
		throw new DiffError(`Unknown line while parsing: ${line}`);
	}

	private checkDuplicate(path: string, operation: string): void {
		if (path in this.patch.actions) {
			throw new DiffError(`Duplicate ${operation} for file: ${path}`);
		}
	}

	private parseUpdate(path: string): void {
		this.checkDuplicate(path, "update");
		this.currentPath = path;

		this.index++;
		const movePath = this.lines[this.index]?.startsWith(PATCH_MARKERS.MOVE)
			? (this.lines[this.index++] ?? "")
					.substring(PATCH_MARKERS.MOVE.length)
					.trim()
			: undefined;

		if (!(path in this.currentFiles)) {
			throw new DiffError(`Update File Error: Missing File: ${path}`);
		}

		const text = this.currentFiles[path] ?? "";
		const action = this.parseUpdateFile(text, path);
		action.movePath = movePath;
		this.patch.actions[path] = action;
		this.currentPath = undefined;
	}

	private parseUpdateFile(text: string, path: string): PatchAction {
		const action: PatchAction = { type: PatchActionType.UPDATE, chunks: [] };
		const fileLines = text.split("\n");
		let index = 0;

		const stopMarkers = [
			PATCH_MARKERS.END,
			PATCH_MARKERS.UPDATE,
			PATCH_MARKERS.DELETE,
			PATCH_MARKERS.ADD,
			PATCH_MARKERS.END_FILE,
		];

		while (
			!stopMarkers.some((marker) =>
				this.lines[this.index]?.startsWith(marker.trim()),
			)
		) {
			const currentLine = this.lines[this.index];
			const defStr = currentLine?.startsWith("@@ ")
				? currentLine.substring(3)
				: undefined;
			const sectionStr = currentLine === "@@" ? currentLine : undefined;

			if (defStr !== undefined || sectionStr !== undefined) {
				this.index++;
			} else if (index !== 0) {
				throw new DiffError(`Invalid Line:\n${this.lines[this.index]}`);
			}

			if (defStr?.trim()) {
				const canonDefStr = canonicalize(defStr.trim());
				for (let i = index; i < fileLines.length; i++) {
					const fileLine = fileLines[i];
					if (
						fileLine &&
						(canonicalize(fileLine) === canonDefStr ||
							canonicalize(fileLine.trim()) === canonDefStr)
					) {
						index = i + 1;
						if (
							canonicalize(fileLine.trim()) === canonDefStr &&
							canonicalize(fileLine) !== canonDefStr
						) {
							this.fuzz++;
						}
						break;
					}
				}
			}

			const [nextChunkContext, chunks, endPatchIndex, eof] = peek(
				this.lines,
				this.index,
			);
			const [newIndex, fuzz, similarity] = findContext(
				fileLines,
				nextChunkContext,
				index,
				eof,
			);

			if (newIndex === -1) {
				const contextText = nextChunkContext.join("\n");
				this.addWarning({
					path: this.currentPath || path,
					chunkIndex: action.chunks.length,
					message: `Could not find matching context (similarity: ${similarity.toFixed(2)}). Chunk skipped.`,
					context:
						contextText.length > 200
							? `${contextText.substring(0, 200)}...`
							: contextText,
				});
				this.index = endPatchIndex;
			} else {
				this.fuzz += fuzz;
				for (const chunk of chunks) {
					chunk.origIndex += newIndex;
					action.chunks.push(chunk);
				}
				index = newIndex + nextChunkContext.length;
				this.index = endPatchIndex;
			}
		}

		return action;
	}

	private parseDelete(path: string): void {
		this.checkDuplicate(path, "delete");
		if (!(path in this.currentFiles)) {
			throw new DiffError(`Delete File Error: Missing File: ${path}`);
		}
		this.patch.actions[path] = { type: PatchActionType.DELETE, chunks: [] };
		this.index++;
	}

	private parseAdd(path: string): void {
		this.checkDuplicate(path, "add");
		if (path in this.currentFiles) {
			throw new DiffError(`Add File Error: File already exists: ${path}`);
		}

		this.index++;
		const lines: string[] = [];
		const stopMarkers = [
			PATCH_MARKERS.END,
			PATCH_MARKERS.UPDATE,
			PATCH_MARKERS.DELETE,
			PATCH_MARKERS.ADD,
		];

		while (
			this.hasMoreLines() &&
			!stopMarkers.some((marker) =>
				this.lines[this.index]?.startsWith(marker.trim()),
			)
		) {
			const line = this.lines[this.index++];
			if (line === undefined) {
				break;
			}
			if (!line.startsWith("+")) {
				throw new DiffError(`Invalid Add File line (missing '+'): ${line}`);
			}
			lines.push(line.substring(1));
		}

		this.patch.actions[path] = {
			type: PatchActionType.ADD,
			newFile: lines.join("\n"),
			chunks: [],
		};
	}
}

function calculateSimilarity(str1: string, str2: string): number {
	const longer = str1.length > str2.length ? str1 : str2;
	const shorter = str1.length > str2.length ? str2 : str1;
	if (longer.length === 0) {
		return 1;
	}
	const editDistance = levenshteinDistance(shorter, longer);
	return (longer.length - editDistance) / longer.length;
}

function levenshteinDistance(str1: string, str2: string): number {
	const rows = str2.length + 1;
	const cols = str1.length + 1;
	const matrix = new Array<number>(rows * cols).fill(0);
	const at = (r: number, c: number): number => matrix[r * cols + c] ?? 0;
	const set = (r: number, c: number, value: number): void => {
		matrix[r * cols + c] = value;
	};

	for (let i = 0; i <= str2.length; i++) set(i, 0, i);
	for (let j = 0; j <= str1.length; j++) set(0, j, j);

	for (let i = 1; i <= str2.length; i++) {
		for (let j = 1; j <= str1.length; j++) {
			if (str2[i - 1] === str1[j - 1]) {
				set(i, j, at(i - 1, j - 1));
			} else {
				set(i, j, 1 + Math.min(at(i - 1, j - 1), at(i, j - 1), at(i - 1, j)));
			}
		}
	}

	return at(str2.length, str1.length);
}

function findContext(
	lines: string[],
	context: string[],
	start: number,
	eof: boolean,
): [number, number, number] {
	if (context.length === 0) {
		return [start, 0, 1];
	}

	let bestSimilarity = 0;
	const findCore = (startIdx: number): [number, number, number] => {
		const canonicalContext = canonicalize(context.join("\n"));

		for (let i = startIdx; i < lines.length; i++) {
			const segment = canonicalize(
				lines.slice(i, i + context.length).join("\n"),
			);
			if (segment === canonicalContext) {
				return [i, 0, 1];
			}
			const similarity = calculateSimilarity(segment, canonicalContext);
			if (similarity > bestSimilarity) {
				bestSimilarity = similarity;
			}
		}

		for (let i = startIdx; i < lines.length; i++) {
			const segment = canonicalize(
				lines
					.slice(i, i + context.length)
					.map((line) => line.trimEnd())
					.join("\n"),
			);
			const canonicalTrimmed = canonicalize(
				context.map((line) => line.trimEnd()).join("\n"),
			);
			if (segment === canonicalTrimmed) {
				return [i, 1, 1];
			}
		}

		for (let i = startIdx; i < lines.length; i++) {
			const segment = canonicalize(
				lines
					.slice(i, i + context.length)
					.map((line) => line.trim())
					.join("\n"),
			);
			const canonicalTrimmed = canonicalize(
				context.map((line) => line.trim()).join("\n"),
			);
			if (segment === canonicalTrimmed) {
				return [i, 100, 1];
			}
		}

		const similarityThreshold = 0.66;
		for (let i = startIdx; i < lines.length; i++) {
			const segment = canonicalize(
				lines.slice(i, i + context.length).join("\n"),
			);
			const similarity = calculateSimilarity(segment, canonicalContext);
			if (similarity >= similarityThreshold) {
				return [i, 1000, similarity];
			}
			if (similarity > bestSimilarity) {
				bestSimilarity = similarity;
			}
		}

		return [-1, 0, bestSimilarity];
	};

	if (eof) {
		let [newIndex, fuzz, similarity] = findCore(lines.length - context.length);
		if (newIndex !== -1) {
			return [newIndex, fuzz, similarity];
		}
		[newIndex, fuzz, similarity] = findCore(start);
		return [newIndex, fuzz + 10000, similarity];
	}

	return findCore(start);
}

type PeekResult = [string[], PatchChunk[], number, boolean];

function peek(lines: string[], initialIndex: number): PeekResult {
	let index = initialIndex;
	const old: string[] = [];
	let delLines: string[] = [];
	let insLines: string[] = [];
	const chunks: PatchChunk[] = [];
	let mode: "keep" | "add" | "delete" = "keep";

	const stopMarkers = [
		"@@",
		PATCH_MARKERS.END,
		PATCH_MARKERS.UPDATE,
		PATCH_MARKERS.DELETE,
		PATCH_MARKERS.ADD,
		PATCH_MARKERS.END_FILE,
	];

	while (index < lines.length) {
		const sourceLine = lines[index];
		if (
			!sourceLine ||
			stopMarkers.some((marker) => sourceLine.startsWith(marker.trim()))
		) {
			break;
		}
		if (sourceLine === "***") {
			break;
		}
		if (sourceLine.startsWith("***")) {
			throw new DiffError(`Invalid line: ${sourceLine}`);
		}

		index++;
		const previousMode: "keep" | "add" | "delete" = mode;
		let line = sourceLine;

		if (line[0] === "+") {
			mode = "add";
		} else if (line[0] === "-") {
			mode = "delete";
		} else if (line[0] === " ") {
			mode = "keep";
		} else {
			mode = "keep";
			line = ` ${line}`;
		}

		line = line.slice(1);

		if (mode === "keep" && previousMode !== mode) {
			if (insLines.length || delLines.length) {
				chunks.push({
					origIndex: old.length - delLines.length,
					delLines,
					insLines,
				});
			}
			delLines = [];
			insLines = [];
		}

		if (mode === "delete") {
			delLines.push(line);
			old.push(line);
		} else if (mode === "add") {
			insLines.push(line);
		} else {
			old.push(line);
		}
	}

	if (insLines.length || delLines.length) {
		chunks.push({
			origIndex: old.length - delLines.length,
			delLines,
			insLines,
		});
	}

	if (index < lines.length && lines[index] === PATCH_MARKERS.END_FILE) {
		index++;
		return [old, chunks, index, true];
	}

	return [old, chunks, index, false];
}

import * as fs from "node:fs/promises";
import * as os from "node:os";
import * as path from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { createApplyPatchExecutor } from "./apply-patch";

describe("createApplyPatchExecutor", () => {
	let tempDir: string;

	beforeEach(async () => {
		tempDir = await fs.mkdtemp(path.join(os.tmpdir(), "apply-patch-"));
	});

	afterEach(async () => {
		await fs.rm(tempDir, { recursive: true, force: true });
	});

	it("applies the documented freeform patch format without shell wrappers", async () => {
		const filePath = path.join(tempDir, "page.tsx");
		await fs.writeFile(
			filePath,
			[
				"export default function Page() {",
				"\treturn (",
				"\t\t<div>",
				'\t\t\t<button onClick={() => console.log("clicked")}>Click me</button>',
				"\t\t</div>",
				"\t);",
				"}",
			].join("\n"),
			"utf-8",
		);

		const execute = createApplyPatchExecutor();
		const result = await execute(
			{
				input: [
					"*** Update File: page.tsx",
					"@@",
					" export default function Page() {",
					" \treturn (",
					" \t\t<div>",
					' \t\t\t<button onClick={() => console.log("clicked")}>Click me</button>',
					'+\t\t\t<button onClick={() => console.log("cancel clicked")}>Cancel</button>',
					" \t\t</div>",
					" \t);",
					" }",
				].join("\n"),
			},
			tempDir,
			{} as never,
		);

		await expect(fs.readFile(filePath, "utf-8")).resolves.toContain(
			'console.log("cancel clicked")',
		);
		expect(result).toContain("Successfully applied patch");
		expect(result).toContain("page.tsx");
	});

	it("accepts the legacy shell wrapper around the patch", async () => {
		const filePath = path.join(tempDir, "note.txt");
		const execute = createApplyPatchExecutor();

		await execute(
			{
				input: [
					"%%bash",
					'apply_patch <<"EOF"',
					"*** Begin Patch",
					"*** Add File: note.txt",
					"+hello",
					"*** End Patch",
					"EOF",
				].join("\n"),
			},
			tempDir,
			{} as never,
		);

		await expect(fs.readFile(filePath, "utf-8")).resolves.toBe("hello");
	});

	it("does not strip valid patch lines that begin with wrapper tokens after the patch prefix", async () => {
		const filePath = path.join(tempDir, "note.txt");
		await fs.writeFile(
			filePath,
			["alpha", "EOF literal", "``` fence", "omega"].join("\n"),
			"utf-8",
		);

		const execute = createApplyPatchExecutor();
		await execute(
			{
				input: [
					"*** Update File: note.txt",
					"@@",
					" alpha",
					" EOF literal",
					" ``` fence",
					"+tail",
					" omega",
				].join("\n"),
			},
			tempDir,
			{} as never,
		);

		await expect(fs.readFile(filePath, "utf-8")).resolves.toBe(
			["alpha", "EOF literal", "``` fence", "tail", "omega"].join("\n"),
		);
	});

	it("accepts an end sentinel with trailing whitespace", async () => {
		const filePath = path.join(tempDir, "note.txt");
		const execute = createApplyPatchExecutor();

		await execute(
			{
				input: [
					"*** Begin Patch",
					"*** Add File: note.txt",
					"+hello",
					"*** End Patch ",
				].join("\n"),
			},
			tempDir,
			{} as never,
		);

		await expect(fs.readFile(filePath, "utf-8")).resolves.toBe("hello");
	});

	it("rejects incomplete patch sentinels", async () => {
		const execute = createApplyPatchExecutor();

		await expect(
			execute(
				{
					input: "*** Begin Patch\n*** Add File: note.txt\n+hello",
				},
				tempDir,
				{} as never,
			),
		).rejects.toThrow("Invalid patch text - incomplete sentinels");
	});

	it("rejects a patch when a hunk context does not match", async () => {
		const filePath = path.join(tempDir, "note.txt");
		const original = ["alpha", "beta", "gamma"].join("\n");
		await fs.writeFile(filePath, original, "utf-8");
		const execute = createApplyPatchExecutor();

		await expect(
			execute(
				{
					input: [
						"*** Update File: note.txt",
						"@@",
						" unrelated heading",
						" missing middle",
						"+replacement",
						" absent footer",
					].join("\n"),
				},
				tempDir,
				{} as never,
			),
		).rejects.toThrow(/note\.txt: hunk 1: Could not find matching context/);

		await expect(fs.readFile(filePath, "utf-8")).resolves.toBe(original);
	});
});

/**
 * Apply Patch Executor
 *
 * Built-in implementation for the documented GPT-5 apply_patch grammar.
 * It accepts the freeform patch body directly and tolerates the legacy shell
 * wrapper form used by older prompts.
 */

import * as fs from "node:fs/promises";
import * as path from "node:path";
import type { AgentToolContext } from "@cline/shared";
import type { ApplyPatchInput } from "../schemas";
import type { ApplyPatchExecutor } from "../types";
import {
	BASH_WRAPPERS,
	DiffError,
	PATCH_MARKERS,
	PatchActionType,
	type PatchChunk,
	PatchParser,
	type PatchWarning,
} from "./apply-patch-parser";

export interface PatchFileChange {
	type: PatchActionType;
	oldContent?: string;
	newContent?: string;
	movePath?: string;
}

interface NormalizedPatchInput {
	lines: string[];
}

/**
 * Options for the apply_patch executor
 */
export interface ApplyPatchExecutorOptions {
	/**
	 * File encoding used for read/write operations
	 * @default "utf-8"
	 */
	encoding?: BufferEncoding;

	/**
	 * Restrict relative-path file operations to paths inside cwd.
	 * Absolute paths are always accepted as-is.
	 * @default true
	 */
	restrictToCwd?: boolean;
}

function resolveFilePath(
	cwd: string,
	inputPath: string,
	restrictToCwd: boolean,
): string {
	const isAbsoluteInput = path.isAbsolute(inputPath);
	const resolved = isAbsoluteInput
		? path.normalize(inputPath)
		: path.resolve(cwd, inputPath);
	if (!restrictToCwd || isAbsoluteInput) {
		return resolved;
	}

	const rel = path.relative(cwd, resolved);
	if (rel.startsWith("..") || path.isAbsolute(rel)) {
		throw new DiffError(`Path must stay within cwd: ${inputPath}`);
	}
	return resolved;
}

function normalizeLineEndings(input: string): string[] {
	return input.split("\n").map((line) => line.replace(/\r$/, ""));
}

function isWrapperLine(line: string): boolean {
	if (line.trim() === "") {
		return false;
	}
	return BASH_WRAPPERS.some((wrapper) => line.startsWith(wrapper));
}

function trimWrapperLines(lines: string[]): string[] {
	let start = 0;
	let end = lines.length;

	while (start < end && isWrapperLine(lines[start] ?? "")) {
		start++;
	}

	while (end > start && isWrapperLine(lines[end - 1] ?? "")) {
		end--;
	}

	return lines.slice(start, end);
}

function normalizePatchInput(input: string): NormalizedPatchInput {
	const rawLines = normalizeLineEndings(input);
	const beginIndex = rawLines.findIndex((line) =>
		line.startsWith(PATCH_MARKERS.BEGIN),
	);
	let endIndex = -1;
	for (let i = rawLines.length - 1; i >= 0; i--) {
		if (rawLines[i]?.startsWith(PATCH_MARKERS.END)) {
			endIndex = i;
			break;
		}
	}

	if (beginIndex !== -1 || endIndex !== -1) {
		if (beginIndex === -1 || endIndex === -1 || endIndex < beginIndex) {
			throw new DiffError(
				"Invalid patch text - incomplete sentinels. Try breaking it into smaller patches.",
			);
		}
		const lines = rawLines.slice(beginIndex, endIndex + 1);
		return {
			lines,
		};
	}

	const stripped = trimWrapperLines(rawLines);
	while (stripped.length > 0 && stripped[0] === "") {
		stripped.shift();
	}
	while (stripped.length > 0 && stripped[stripped.length - 1] === "") {
		stripped.pop();
	}

	const lines = [PATCH_MARKERS.BEGIN, ...stripped, PATCH_MARKERS.END];
	return {
		lines,
	};
}

function extractFilesForOperations(
	lines: readonly string[],
	markers: readonly string[],
): string[] {
	const files = new Set<string>();

	for (const line of lines) {
		for (const marker of markers) {
			if (line.startsWith(marker)) {
				files.add(line.substring(marker.length).trim());
				break;
			}
		}
	}

	return [...files];
}

function applyChunks(
	content: string,
	chunks: PatchChunk[],
	filePath: string,
): string {
	if (chunks.length === 0) {
		return content;
	}

	const lines = content.split("\n");
	const result: string[] = [];
	let currentIndex = 0;

	for (const chunk of chunks) {
		if (chunk.origIndex > lines.length) {
			throw new DiffError(
				`${filePath}: chunk.origIndex ${chunk.origIndex} > lines.length ${lines.length}`,
			);
		}
		if (currentIndex > chunk.origIndex) {
			throw new DiffError(
				`${filePath}: currentIndex ${currentIndex} > chunk.origIndex ${chunk.origIndex}`,
			);
		}
		result.push(...lines.slice(currentIndex, chunk.origIndex));
		result.push(...chunk.insLines);
		currentIndex = chunk.origIndex + chunk.delLines.length;
	}

	result.push(...lines.slice(currentIndex));
	return result.join("\n");
}

async function loadFiles(
	lines: readonly string[],
	cwd: string,
	encoding: BufferEncoding,
	restrictToCwd: boolean,
): Promise<Record<string, string>> {
	const filesToLoad = extractFilesForOperations(lines, [
		PATCH_MARKERS.UPDATE,
		PATCH_MARKERS.DELETE,
	]);
	const files: Record<string, string> = {};

	for (const filePath of filesToLoad) {
		const absolutePath = resolveFilePath(cwd, filePath, restrictToCwd);
		let fileContent: string;
		try {
			fileContent = await fs.readFile(absolutePath, encoding);
		} catch {
			throw new DiffError(`File not found: ${filePath}`);
		}
		files[filePath] = fileContent.replace(/\r\n/g, "\n");
	}

	return files;
}

function patchToChanges(
	patch: ReturnType<PatchParser["parse"]>["patch"],
	originalFiles: Record<string, string>,
): Record<string, PatchFileChange> {
	const changes: Record<string, PatchFileChange> = {};

	for (const [filePath, action] of Object.entries(patch.actions)) {
		switch (action.type) {
			case PatchActionType.DELETE:
				changes[filePath] = {
					type: PatchActionType.DELETE,
					oldContent: originalFiles[filePath],
				};
				break;
			case PatchActionType.ADD:
				if (action.newFile === undefined) {
					throw new DiffError("ADD action without file content");
				}
				changes[filePath] = {
					type: PatchActionType.ADD,
					newContent: action.newFile,
				};
				break;
			case PatchActionType.UPDATE:
				changes[filePath] = {
					type: PatchActionType.UPDATE,
					oldContent: originalFiles[filePath],
					newContent: applyChunks(
						originalFiles[filePath] ?? "",
						action.chunks,
						filePath,
					),
					movePath: action.movePath,
				};
				break;
		}
	}

	return changes;
}

function formatSkippedHunkFailure(warnings: readonly PatchWarning[]): string {
	const lines = [
		`Patch could not be applied because ${warnings.length} hunk${warnings.length === 1 ? "" : "s"} did not match the current file content.`,
	];

	for (const warning of warnings) {
		const hunkNumber =
			warning.chunkIndex === undefined
				? "unknown"
				: String(warning.chunkIndex + 1);
		lines.push(`${warning.path}: hunk ${hunkNumber}: ${warning.message}`);
		if (warning.context) {
			lines.push(`Context:\n${warning.context}`);
		}
	}

	return lines.join("\n");
}

async function applyChanges(
	changes: Record<string, PatchFileChange>,
	cwd: string,
	encoding: BufferEncoding,
	restrictToCwd: boolean,
): Promise<string[]> {
	const touched: string[] = [];

	for (const [filePath, change] of Object.entries(changes)) {
		const sourceAbsPath = resolveFilePath(cwd, filePath, restrictToCwd);
		switch (change.type) {
			case PatchActionType.DELETE:
				await fs.rm(sourceAbsPath, { force: true });
				touched.push(`${filePath}: [deleted]`);
				break;
			case PatchActionType.ADD:
				if (change.newContent === undefined) {
					throw new DiffError(`Cannot create ${filePath} with no content`);
				}
				await fs.mkdir(path.dirname(sourceAbsPath), { recursive: true });
				await fs.writeFile(sourceAbsPath, change.newContent, { encoding });
				touched.push(filePath);
				break;
			case PatchActionType.UPDATE: {
				if (change.newContent === undefined) {
					throw new DiffError(
						`UPDATE change for ${filePath} has no new content`,
					);
				}

				if (change.movePath) {
					const moveAbsPath = resolveFilePath(
						cwd,
						change.movePath,
						restrictToCwd,
					);
					await fs.mkdir(path.dirname(moveAbsPath), { recursive: true });
					await fs.writeFile(moveAbsPath, change.newContent, { encoding });
					await fs.rm(sourceAbsPath, { force: true });
					touched.push(`${filePath} -> ${change.movePath}`);
				} else {
					await fs.writeFile(sourceAbsPath, change.newContent, { encoding });
					touched.push(filePath);
				}
				break;
			}
		}
	}

	return touched;
}

/**
 * Parse a patch and compute the per-file changes it would apply, without
 * writing anything to disk. Reads the current contents of the files the patch
 * references. Exposed so hosts can preview a patch (e.g. in a diff editor)
 * before the executor applies it.
 */
export async function computePatchChanges(
	patchText: string,
	cwd: string,
	options: ApplyPatchExecutorOptions = {},
): Promise<{ changes: Record<string, PatchFileChange>; fuzz: number }> {
	const { encoding = "utf-8", restrictToCwd = true } = options;
	const normalizedInput = normalizePatchInput(patchText);
	const currentFiles = await loadFiles(
		normalizedInput.lines,
		cwd,
		encoding,
		restrictToCwd,
	);
	const parser = new PatchParser(normalizedInput.lines, currentFiles);
	const { patch, fuzz } = parser.parse();
	if (patch.warnings && patch.warnings.length > 0) {
		throw new DiffError(formatSkippedHunkFailure(patch.warnings));
	}

	return { changes: patchToChanges(patch, currentFiles), fuzz };
}

/**
 * Create an apply_patch executor using Node.js fs module.
 */
export function createApplyPatchExecutor(
	options: ApplyPatchExecutorOptions = {},
): ApplyPatchExecutor {
	const { encoding = "utf-8", restrictToCwd = true } = options;

	return async (
		input: ApplyPatchInput,
		cwd: string,
		_context: AgentToolContext,
	): Promise<string> => {
		const { changes, fuzz } = await computePatchChanges(input.input, cwd, {
			encoding,
			restrictToCwd,
		});
		const touched = await applyChanges(changes, cwd, encoding, restrictToCwd);

		const responseLines = [
			"Successfully applied patch to the following files:",
		];
		for (const file of touched) {
			responseLines.push(file);
		}
		if (fuzz > 0) {
			responseLines.push(`Note: Patch applied with fuzz factor ${fuzz}`);
		}
		return responseLines.join("\n");
	};
}

