import {
	CLINE_HUB_DEV_PORT,
	CLINE_HUB_PORT,
	resolveClineBuildEnv,
} from "@cline/shared";

const HUB_HOST_ENV = "CLINE_HUB_HOST";
const HUB_PORT_ENV = "CLINE_HUB_PORT";
const HUB_PATHNAME_ENV = "CLINE_HUB_PATHNAME";

export const DEFAULT_HUB_HOST = "127.0.0.1";
export const DEFAULT_HUB_PORT = CLINE_HUB_PORT;
export const DEFAULT_HUB_PATHNAME = "/hub";

export interface HubEndpointOverrides {
	host?: string;
	port?: number;
	pathname?: string;
}

export interface ResolveHubDefaultsOptions {
	env?: NodeJS.ProcessEnv;
	execArgv?: string[];
}

function fallbackHubPort(options: ResolveHubDefaultsOptions): number {
	return resolveClineBuildEnv(options) === "development"
		? CLINE_HUB_DEV_PORT
		: DEFAULT_HUB_PORT;
}

export function resolveDefaultHubHost(
	options: ResolveHubDefaultsOptions = {},
): string {
	const env = options.env ?? process.env;
	return env[HUB_HOST_ENV]?.trim() || DEFAULT_HUB_HOST;
}

export function resolveDefaultHubPort(
	options: ResolveHubDefaultsOptions = {},
): number {
	const env = options.env ?? process.env;
	const raw = env[HUB_PORT_ENV]?.trim();
	if (!raw) {
		return fallbackHubPort(options);
	}
	const port = Number.parseInt(raw, 10);
	if (!Number.isInteger(port) || port < 1 || port > 65_535) {
		return fallbackHubPort(options);
	}
	return port;
}

export function resolveDefaultHubPathname(
	options: ResolveHubDefaultsOptions = {},
): string {
	const env = options.env ?? process.env;
	return env[HUB_PATHNAME_ENV]?.trim() || DEFAULT_HUB_PATHNAME;
}

export function resolveHubEndpointOptions(
	overrides: HubEndpointOverrides = {},
	options: ResolveHubDefaultsOptions = {},
): Required<HubEndpointOverrides> {
	return {
		host: overrides.host ?? resolveDefaultHubHost(options),
		port: overrides.port ?? resolveDefaultHubPort(options),
		pathname: overrides.pathname ?? resolveDefaultHubPathname(options),
	};
}

import { chmod, mkdir, stat, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import {
	clearHubDiscovery,
	probeHubServer,
	readHubDiscovery,
	resolveHubOwnerContext,
	writeHubDiscovery,
} from ".";

type EnvSnapshot = {
	CLINE_DATA_DIR: string | undefined;
	CLINE_HUB_DISCOVERY_PATH: string | undefined;
};

function captureEnv(): EnvSnapshot {
	return {
		CLINE_DATA_DIR: process.env.CLINE_DATA_DIR,
		CLINE_HUB_DISCOVERY_PATH: process.env.CLINE_HUB_DISCOVERY_PATH,
	};
}

function restoreEnv(snapshot: EnvSnapshot): void {
	process.env.CLINE_DATA_DIR = snapshot.CLINE_DATA_DIR;
	process.env.CLINE_HUB_DISCOVERY_PATH = snapshot.CLINE_HUB_DISCOVERY_PATH;
}

describe("hub discovery", () => {
	let snapshot: EnvSnapshot = captureEnv();

	afterEach(() => {
		restoreEnv(snapshot);
	});

	it("stores shared hub discovery under the locks directory by default", () => {
		snapshot = captureEnv();
		delete process.env.CLINE_HUB_DISCOVERY_PATH;
		process.env.CLINE_DATA_DIR = "/tmp/cline-data";

		expect(resolveHubOwnerContext("shared").discoveryPath).toBe(
			join(
				"/tmp/cline-data",
				"locks",
				"hub",
				"owners",
				"hub-a4d26868017c.json",
			),
		);
	});

	it("honors an explicit hub discovery path override", () => {
		snapshot = captureEnv();
		process.env.CLINE_HUB_DISCOVERY_PATH = "/tmp/custom-hub-discovery.json";

		expect(resolveHubOwnerContext("shared").discoveryPath).toBe(
			"/tmp/custom-hub-discovery.json",
		);
	});

	it("writes and clears discovery records at the resolved location", async () => {
		snapshot = captureEnv();
		delete process.env.CLINE_HUB_DISCOVERY_PATH;
		process.env.CLINE_DATA_DIR = "/tmp/cline-data";

		const discoveryPath = resolveHubOwnerContext("shared").discoveryPath;
		const record = {
			hubId: "hub_123",
			protocolVersion: "v1",
			authToken: "test-token",
			host: "127.0.0.1",
			port: 25463,
			url: "ws://127.0.0.1:25463/hub",
			startedAt: new Date().toISOString(),
			updatedAt: new Date().toISOString(),
		};

		await mkdir(dirname(discoveryPath), { recursive: true });
		await writeFile(discoveryPath, "{}\n", "utf8");
		await chmod(discoveryPath, 0o644);
		await writeHubDiscovery(discoveryPath, record);
		await expect(readHubDiscovery(discoveryPath)).resolves.toMatchObject(
			record,
		);
		// Windows does not support Unix file permissions; chmod is a no-op there.
		if (process.platform !== "win32") {
			expect((await stat(discoveryPath)).mode & 0o777).toBe(0o600);
		}
		await clearHubDiscovery(discoveryPath);
		await expect(readHubDiscovery(discoveryPath)).resolves.toBeUndefined();
	});

	it("rejects discovery records without an auth token", async () => {
		snapshot = captureEnv();
		delete process.env.CLINE_HUB_DISCOVERY_PATH;
		process.env.CLINE_DATA_DIR = "/tmp/cline-data";

		const discoveryPath = resolveHubOwnerContext("missing-auth").discoveryPath;
		await mkdir(dirname(discoveryPath), { recursive: true });
		await writeFile(
			discoveryPath,
			`${JSON.stringify({
				hubId: "hub_123",
				protocolVersion: "v1",
				host: "127.0.0.1",
				port: 25463,
				url: "ws://127.0.0.1:25463/hub",
				startedAt: new Date().toISOString(),
				updatedAt: new Date().toISOString(),
			})}\n`,
			"utf8",
		);

		await expect(readHubDiscovery(discoveryPath)).resolves.toBeUndefined();
	});

	it("returns only public health fields for unauthenticated probes", async () => {
		const fetchMock = async () =>
			({
				ok: true,
				json: async () => ({
					ok: true,
					protocolVersion: "v1",
					minClientProtocolVersion: "v1",
					maxClientProtocolVersion: "v1",
					coreVersion: "1.0.0",
					host: "127.0.0.1",
					port: 25463,
					url: "ws://127.0.0.1:25463/hub",
				}),
			}) as Response;
		const originalFetch = globalThis.fetch;
		globalThis.fetch = fetchMock as typeof fetch;
		try {
			const record = await probeHubServer("ws://127.0.0.1:25463/hub");

			expect(record).toMatchObject({
				protocolVersion: "v1",
				host: "127.0.0.1",
				port: 25463,
				url: "ws://127.0.0.1:25463/hub",
			});
			expect(record?.hubId).toBeUndefined();
			expect(record?.startedAt).toBeUndefined();
			expect(record?.updatedAt).toBeUndefined();
		} finally {
			globalThis.fetch = originalFetch;
		}
	});
});

import { createHash, randomBytes } from "node:crypto";
import { existsSync } from "node:fs";
import { chmod, mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { resolveClineDataDir, resolveClineDir } from "@cline/shared/storage";
import corePackage from "../../../package.json";

const HUB_DISCOVERY_ENV = "CLINE_HUB_DISCOVERY_PATH";
const HUB_BUILD_ID_ENV = "CLINE_HUB_BUILD_ID";
const HUB_STARTUP_LOCK_MAX_AGE_MS = 30_000;
const HUB_STARTUP_LOCK_WAIT_MS = 15_000;
const HUB_STARTUP_LOCK_POLL_MS = 100;

export interface HubServerDiscoveryRecord {
	hubId: string;
	protocolVersion: string;
	minClientProtocolVersion?: string;
	maxClientProtocolVersion?: string;
	capabilities?: readonly string[];
	coreVersion?: string;
	buildId?: string;
	authToken: string;
	host: string;
	port: number;
	url: string;
	pid?: number;
	startedAt: string;
	updatedAt: string;
}

export type HubServerProbeRecord = {
	protocolVersion: string;
	minClientProtocolVersion?: string;
	maxClientProtocolVersion?: string;
	capabilities?: readonly string[];
	coreVersion?: string;
	buildId?: string;
	host: string;
	port: number;
	url: string;
	hubId?: string;
	authToken?: string;
	pid?: number;
	startedAt?: string;
	updatedAt?: string;
};

export interface HubOwnerContext {
	ownerId: string;
	discoveryPath: string;
}

function sanitizeKey(value: string): string {
	return value.replace(/[^a-zA-Z0-9_.-]+/g, "_");
}

function hashValue(value: string): string {
	return createHash("sha256").update(value).digest("hex").slice(0, 12);
}

function isPidAlive(pid: number | undefined): boolean {
	if (!Number.isInteger(pid) || !pid || pid <= 0) {
		return false;
	}
	try {
		process.kill(pid, 0);
		return true;
	} catch (error) {
		return error instanceof Error && "code" in error
			? String((error as NodeJS.ErrnoException).code) === "EPERM"
			: false;
	}
}

export function createHubAuthToken(): string {
	return randomBytes(32).toString("hex");
}

function sleep(ms: number): Promise<void> {
	return new Promise((resolve) => setTimeout(resolve, ms));
}

function getStartupLockDir(discoveryPath: string): string {
	return `${discoveryPath}.lock`;
}

async function readStartupLockRecord(
	lockDir: string,
): Promise<{ pid: number; acquiredAt: string } | undefined> {
	try {
		const parsed = JSON.parse(
			await readFile(join(lockDir, "owner.json"), "utf8"),
		) as Partial<{ pid: number; acquiredAt: string }>;
		if (
			typeof parsed.pid !== "number" ||
			typeof parsed.acquiredAt !== "string"
		) {
			return undefined;
		}
		return { pid: parsed.pid, acquiredAt: parsed.acquiredAt };
	} catch {
		return undefined;
	}
}

async function removeStartupLock(lockDir: string): Promise<void> {
	await rm(lockDir, { recursive: true, force: true }).catch(() => undefined);
}

export function resolveHubBuildId(): string {
	return process.env[HUB_BUILD_ID_ENV]?.trim() || String(corePackage.version);
}

export function resolveHubOwnerContext(
	ownerBasis: string = process.argv[1]?.trim() || process.cwd(),
): HubOwnerContext {
	const ownerId = `hub-${hashValue(ownerBasis)}`;
	const discoveryPath =
		process.env[HUB_DISCOVERY_ENV]?.trim() ||
		join(
			resolveClineDataDir(),
			"locks",
			"hub",
			"owners",
			`${sanitizeKey(ownerId)}.json`,
		);
	return { ownerId, discoveryPath };
}

export function createInMemoryHubOwnerContext(
	label = `hub-${Date.now().toString(36)}`,
): HubOwnerContext {
	return resolveHubOwnerContext(label);
}

export async function readHubDiscovery(
	discoveryPath: string,
): Promise<HubServerDiscoveryRecord | undefined> {
	try {
		const parsed = JSON.parse(
			await readFile(discoveryPath, "utf8"),
		) as Partial<HubServerDiscoveryRecord>;
		if (
			typeof parsed.hubId !== "string" ||
			typeof parsed.protocolVersion !== "string" ||
			typeof parsed.authToken !== "string" ||
			typeof parsed.host !== "string" ||
			typeof parsed.port !== "number" ||
			typeof parsed.url !== "string" ||
			typeof parsed.startedAt !== "string" ||
			typeof parsed.updatedAt !== "string"
		) {
			return undefined;
		}
		return {
			hubId: parsed.hubId,
			protocolVersion: parsed.protocolVersion,
			minClientProtocolVersion:
				typeof parsed.minClientProtocolVersion === "string"
					? parsed.minClientProtocolVersion
					: undefined,
			maxClientProtocolVersion:
				typeof parsed.maxClientProtocolVersion === "string"
					? parsed.maxClientProtocolVersion
					: undefined,
			capabilities: Array.isArray(parsed.capabilities)
				? parsed.capabilities.filter(
						(capability): capability is string =>
							typeof capability === "string",
					)
				: undefined,
			coreVersion:
				typeof parsed.coreVersion === "string" ? parsed.coreVersion : undefined,
			buildId: typeof parsed.buildId === "string" ? parsed.buildId : undefined,
			authToken: parsed.authToken,
			host: parsed.host,
			port: parsed.port,
			url: parsed.url,
			pid: typeof parsed.pid === "number" ? parsed.pid : undefined,
			startedAt: parsed.startedAt,
			updatedAt: parsed.updatedAt,
		};
	} catch {
		return undefined;
	}
}

export async function writeHubDiscovery(
	discoveryPath: string,
	record: HubServerDiscoveryRecord,
): Promise<void> {
	await mkdir(dirname(discoveryPath), { recursive: true });
	// Remove any existing file first so writeFile creates it fresh with the
	// correct mode. On Linux, the mode option is ignored for existing files.
	await rm(discoveryPath, { force: true }).catch(() => undefined);
	await writeFile(discoveryPath, `${JSON.stringify(record, null, 2)}\n`, {
		encoding: "utf8",
		mode: 0o600,
	});
	await chmod(discoveryPath, 0o600);
}

export async function clearHubDiscovery(discoveryPath: string): Promise<void> {
	await rm(discoveryPath, { force: true }).catch(() => undefined);
}

export async function withHubStartupLock<T>(
	discoveryPath: string,
	callback: () => Promise<T>,
): Promise<T> {
	const lockDir = getStartupLockDir(discoveryPath);
	await mkdir(dirname(lockDir), { recursive: true });
	const deadline = Date.now() + HUB_STARTUP_LOCK_WAIT_MS;

	while (true) {
		try {
			await mkdir(lockDir, { recursive: false });
			await writeFile(
				join(lockDir, "owner.json"),
				`${JSON.stringify(
					{ pid: process.pid, acquiredAt: new Date().toISOString() },
					null,
					2,
				)}\n`,
				"utf8",
			);
			try {
				return await callback();
			} finally {
				await removeStartupLock(lockDir);
			}
		} catch (error) {
			const code =
				error instanceof Error && "code" in error
					? String((error as NodeJS.ErrnoException).code)
					: "";
			if (code !== "EEXIST") {
				throw error;
			}
			const record = await readStartupLockRecord(lockDir);
			const lockAge = record
				? Date.now() - Date.parse(record.acquiredAt)
				: HUB_STARTUP_LOCK_MAX_AGE_MS + 1;
			if (
				!record ||
				!isPidAlive(record.pid) ||
				lockAge > HUB_STARTUP_LOCK_MAX_AGE_MS
			) {
				await removeStartupLock(lockDir);
				continue;
			}
			if (Date.now() >= deadline) {
				throw new Error(`Timed out waiting for hub startup lock ${lockDir}`);
			}
			await sleep(HUB_STARTUP_LOCK_POLL_MS);
		}
	}
}

export async function probeHubServer(
	url: string,
	options?: { authToken?: string },
): Promise<HubServerProbeRecord | undefined> {
	try {
		const response = await fetch(
			options?.authToken ? toHubStatusUrl(url) : toHubHealthUrl(url),
			{
				headers: options?.authToken
					? { authorization: `Bearer ${options.authToken}` }
					: undefined,
			},
		);
		if (!response.ok) {
			return undefined;
		}
		const parsed = (await response.json()) as Partial<HubServerProbeRecord>;
		if (
			typeof parsed.protocolVersion !== "string" ||
			typeof parsed.host !== "string" ||
			typeof parsed.port !== "number" ||
			typeof parsed.url !== "string"
		) {
			return undefined;
		}
		return {
			protocolVersion: parsed.protocolVersion,
			minClientProtocolVersion:
				typeof parsed.minClientProtocolVersion === "string"
					? parsed.minClientProtocolVersion
					: undefined,
			maxClientProtocolVersion:
				typeof parsed.maxClientProtocolVersion === "string"
					? parsed.maxClientProtocolVersion
					: undefined,
			capabilities: Array.isArray(parsed.capabilities)
				? parsed.capabilities.filter(
						(capability): capability is string =>
							typeof capability === "string",
					)
				: undefined,
			coreVersion:
				typeof parsed.coreVersion === "string" ? parsed.coreVersion : undefined,
			buildId: typeof parsed.buildId === "string" ? parsed.buildId : undefined,
			host: parsed.host,
			port: parsed.port,
			url: parsed.url,
			hubId: typeof parsed.hubId === "string" ? parsed.hubId : undefined,
			authToken:
				typeof parsed.authToken === "string" ? parsed.authToken : undefined,
			pid: typeof parsed.pid === "number" ? parsed.pid : undefined,
			startedAt:
				typeof parsed.startedAt === "string" ? parsed.startedAt : undefined,
			updatedAt:
				typeof parsed.updatedAt === "string" ? parsed.updatedAt : undefined,
		};
	} catch {
		return undefined;
	}
}

export function createHubServerUrl(
	host: string,
	port: number,
	pathname = "/hub",
): string {
	return new URL(`ws://${host}:${port}${pathname}`).toString();
}

export function toHubHealthUrl(wsUrl: string): string {
	const parsed = new URL(wsUrl);
	parsed.protocol = parsed.protocol === "wss:" ? "https:" : "http:";
	parsed.pathname = "/health";
	parsed.search = "";
	return parsed.toString();
}

export function toHubStatusUrl(wsUrl: string): string {
	const parsed = new URL(toHubHealthUrl(wsUrl));
	parsed.pathname = "/status";
	return parsed.toString();
}

export function isDiscoveryFilePresent(pathname: string): boolean {
	return existsSync(pathname);
}

