function agentDoneEvents(events: unknown[]) {
	return events.filter(
		(
			event,
		): event is {
			type: "agent_event";
			payload: { event: { type: "done"; [key: string]: unknown } };
		} =>
			!!event &&
			typeof event === "object" &&
			(event as { type?: unknown }).type === "agent_event" &&
			(event as { payload?: { event?: { type?: unknown } } }).payload?.event
				?.type === "done",
	);
}

