		createLocalHubScheduleRuntimeHandlers();

		expect(localRuntimeHostMock).toHaveBeenCalledTimes(1);
		const constructorArgs = localRuntimeHostMock.mock.calls[0]?.[0] as {
			fetch?: typeof fetch;
		};
		expect(constructorArgs.fetch).toBeUndefined();
