	it("provides an executable headless completion tool to the real yolo runtime builder", async () => {
		localRuntimeHostMock.mockClear();
		const { createLocalHubScheduleRuntimeHandlers } = await import(
			"../daemon/runtime-handlers"
		);
		const { DefaultRuntimeBuilder } = await import(
			"../../runtime/orchestration/runtime-builder"
		);

		createLocalHubScheduleRuntimeHandlers();

		const constructorArgs = localRuntimeHostMock.mock.calls[0]?.[0] as {
			capabilities?: RuntimeCapabilities;
		};
		const toolExecutors = constructorArgs.capabilities?.toolExecutors;
		expect(toolExecutors?.submit).toBeTypeOf("function");

		const runtime = await new DefaultRuntimeBuilder().build({
			config: {
				providerId: "cline",
				modelId: CLINE_DEFAULT_MODEL_ID,
				cwd: process.cwd(),
				workspaceRoot: process.cwd(),
				systemPrompt: "Run unattended.",
				mode: "yolo",
				enableTools: true,
				enableSpawnAgent: false,
				enableAgentTeams: false,
			},
			toolExecutors,
			toolPolicies: {
				"*": { enabled: false, autoApprove: true },
				submit_and_exit: { enabled: true, autoApprove: true },
				ask_question: { enabled: false, autoApprove: true },
			},
		});

		try {
			const toolNames = runtime.tools.map((tool) => tool.name);
			expect(toolNames).toContain("submit_and_exit");
			expect(toolNames).not.toContain("ask_question");
			const submitTool = runtime.tools.find(
				(tool) => tool.name === "submit_and_exit",
			);
			if (!submitTool) {
				throw new Error("Expected submit_and_exit to be available.");
			}
			expect(submitTool.lifecycle).toEqual({ completesRun: true });
			expect(runtime.completionPolicy).toEqual({
				requireCompletionTool: true,
			});
			await expect(
				submitTool.execute(
					{
						summary: "Scheduled work completed successfully.",
						verified: true,
					},
					{
						agentId: "scheduled-agent",
						conversationId: "scheduled-conversation",
						iteration: 1,
					},
				),
			).resolves.toBe("Scheduled work completed successfully.");
		} finally {
			await runtime.shutdown("test complete");
		}
	});
});

import type {
	HubCommandEnvelope,
	HubReplyEnvelope,
	ToolApprovalRequest,
} from "@cline/shared";
import { createSessionId } from "@cline/shared";
import { errorReply, type HubTransportContext, okReply } from "./context";

export async function requestToolApproval(
	ctx: HubTransportContext,
	request: ToolApprovalRequest,
): Promise<{ approved: boolean; reason?: string }> {
	const approvalId = createSessionId("approval_");
	const sessionId = request.sessionId;
	const state = ctx.sessionState.get(sessionId);
	if (state?.interactive === false) {
		return {
			approved: false,
			reason:
				"Tool approval requires an interactive session, but this session is non-interactive.",
		};
	}
	return await new Promise((resolve) => {
		ctx.pendingApprovals.set(approvalId, {
			sessionId,
			resolve,
		});
		ctx.publish(
			ctx.buildEvent(
				"approval.requested",
				{
					approvalId,
					sessionId: request.sessionId,
					agentId: request.agentId,
					conversationId: request.conversationId,
					iteration: request.iteration,
					toolCallId: request.toolCallId,
					toolName: request.toolName,
					inputJson: JSON.stringify(request.input ?? null),
					policy: request.policy,
				},
				sessionId,
			),
		);
	});
}

export function resolvePendingApproval(
	ctx: HubTransportContext,
	approvalId: string,
	result: { approved: boolean; reason?: string },
): { sessionId: string } | undefined {
	const pending = ctx.pendingApprovals.get(approvalId);
	if (!pending) {
		return undefined;
	}
	ctx.pendingApprovals.delete(approvalId);
	pending.resolve(result);
	return { sessionId: pending.sessionId };
}

export function cancelPendingApprovals(
	ctx: HubTransportContext,
	filter: (approval: { approvalId: string; sessionId: string }) => boolean,
	reason: string,
): number {
	let cancelled = 0;
	for (const [approvalId, pending] of [...ctx.pendingApprovals.entries()]) {
		if (!filter({ approvalId, sessionId: pending.sessionId })) {
			continue;
		}
		ctx.pendingApprovals.delete(approvalId);
		pending.resolve({ approved: false, reason });
		ctx.publish(
			ctx.buildEvent(
				"approval.resolved",
				{ approvalId, approved: false, cancelled: true, reason },
				pending.sessionId,
			),
		);
		cancelled += 1;
	}
	return cancelled;
}

export async function handleApprovalRespond(
	ctx: HubTransportContext,
	envelope: HubCommandEnvelope,
): Promise<HubReplyEnvelope> {
	const approvalId =
		typeof envelope.payload?.approvalId === "string"
			? envelope.payload.approvalId.trim()
			: "";
	const pending = ctx.pendingApprovals.get(approvalId);
	if (!pending) {
		return errorReply(
			envelope,
			"approval_not_found",
			`Unknown approval: ${approvalId}`,
		);
	}
	const reason =
		typeof envelope.payload?.reason === "string"
			? envelope.payload.reason
			: envelope.payload?.payload &&
					typeof envelope.payload.payload === "object" &&
					!Array.isArray(envelope.payload.payload) &&
					typeof (envelope.payload.payload as Record<string, unknown>)
						.reason === "string"
				? ((envelope.payload.payload as Record<string, unknown>)
						.reason as string)
				: undefined;
	const approved = envelope.payload?.approved === true;
	const resolved = resolvePendingApproval(ctx, approvalId, {
		approved,
		reason,
	});
	if (!resolved) {
		return errorReply(
			envelope,
			"approval_not_found",
			`Unknown approval: ${approvalId}`,
		);
	}
	ctx.publish(
		ctx.buildEvent(
			"approval.resolved",
			{ approvalId, approved, reason },
			resolved.sessionId,
		),
	);
	return okReply(envelope, { approvalId, approved });
}

import type { HubCommandEnvelope, HubReplyEnvelope } from "@cline/shared";
import { createSessionId } from "@cline/shared";
import { logHubMessage } from "../hub-server-logging";
import { errorReply, type HubTransportContext, okReply } from "./context";

export async function requestCapability(
	ctx: HubTransportContext,
	sessionId: string,
	capabilityName: string,
	payload: Record<string, unknown>,
	targetClientId: string,
	onProgress?: (payload: Record<string, unknown>) => void,
): Promise<Record<string, unknown> | undefined> {
	const requestId = createSessionId("capreq_");
	const startedAt = performance.now();
	logHubMessage("info", "capability.request.start", {
		requestId,
		sessionId,
		capabilityName,
		targetClientId,
	});
	return await new Promise((resolve, reject) => {
		ctx.pendingCapabilityRequests.set(requestId, {
			sessionId,
			targetClientId,
			capabilityName,
			onProgress,
			resolve: (result) => {
				logHubMessage(result.ok ? "info" : "warn", "capability.request.end", {
					requestId,
					sessionId,
					capabilityName,
					targetClientId,
					ok: result.ok,
					error: result.error,
					durationMs: Math.round(performance.now() - startedAt),
				});
				if (!result.ok) {
					reject(
						new Error(
							result.error ||
								`Capability ${capabilityName} was rejected by ${targetClientId}.`,
						),
					);
					return;
				}
				resolve(result.payload);
			},
		});
		ctx.publish(
			ctx.buildEvent(
				"capability.requested",
				{
					requestId,
					targetClientId,
					capabilityName,
					payload,
				},
				sessionId,
			),
		);
		logHubMessage("info", "capability.request.published", {
			requestId,
			sessionId,
			capabilityName,
			targetClientId,
		});
	});
}

export function handleCapabilityProgress(
	ctx: HubTransportContext,
	envelope: HubCommandEnvelope,
): HubReplyEnvelope {
	const requestId =
		typeof envelope.payload?.requestId === "string"
			? envelope.payload.requestId.trim()
			: "";
	const pending = ctx.pendingCapabilityRequests.get(requestId);
	if (!pending) {
		// Duplicate/late progress after resolve is common with multiple connectors;
		// ack quietly instead of capability_not_found spam.
		return okReply(envelope, { requestId, ignored: true });
	}
	const responderClientId = envelope.clientId?.trim() || "";
	if (responderClientId !== pending.targetClientId) {
		return errorReply(
			envelope,
			"capability_wrong_client",
			`Capability request ${requestId} is owned by ${pending.targetClientId}`,
		);
	}
	if (
		envelope.sessionId?.trim() &&
		envelope.sessionId.trim() !== pending.sessionId
	) {
		return errorReply(
			envelope,
			"capability_wrong_session",
			`Capability request ${requestId} belongs to session ${pending.sessionId}`,
		);
	}
	const payload =
		envelope.payload?.payload &&
		typeof envelope.payload.payload === "object" &&
		!Array.isArray(envelope.payload.payload)
			? (envelope.payload.payload as Record<string, unknown>)
			: {};
	pending.onProgress?.(payload);
	return okReply(envelope, { requestId });
}

export function cancelPendingCapabilityRequests(
	ctx: HubTransportContext,
	filter: (request: {
		requestId: string;
		sessionId: string;
		targetClientId: string;
		capabilityName: string;
	}) => boolean,
	reason: string,
): number {
	let cancelled = 0;
	for (const [requestId, pending] of [
		...ctx.pendingCapabilityRequests.entries(),
	]) {
		if (!filter({ requestId, ...pending })) {
			continue;
		}
		ctx.pendingCapabilityRequests.delete(requestId);
		logHubMessage("warn", "capability.request.cancelled", {
			requestId,
			sessionId: pending.sessionId,
			capabilityName: pending.capabilityName,
			targetClientId: pending.targetClientId,
			reason,
		});
		pending.resolve({ ok: false, error: reason });
		ctx.publish(
			ctx.buildEvent(
				"capability.resolved",
				{
					requestId,
					capabilityName: pending.capabilityName,
					targetClientId: pending.targetClientId,
					ok: false,
					cancelled: true,
					error: reason,
				},
				pending.sessionId,
			),
		);
		cancelled += 1;
	}
	return cancelled;
}

export async function handleCapabilityRequest(
	ctx: HubTransportContext,
	envelope: HubCommandEnvelope,
): Promise<HubReplyEnvelope> {
	const sessionId =
		typeof envelope.payload?.sessionId === "string"
			? envelope.payload.sessionId.trim()
			: envelope.sessionId?.trim() || "";
	const capabilityName =
		typeof envelope.payload?.capabilityName === "string"
			? envelope.payload.capabilityName.trim()
			: "";
	const targetClientId =
		typeof envelope.payload?.targetClientId === "string"
			? envelope.payload.targetClientId.trim()
			: "";
	if (!sessionId || !capabilityName || !targetClientId) {
		return errorReply(
			envelope,
			"invalid_capability_request",
			"capability.request requires sessionId, capabilityName, and targetClientId",
		);
	}
	try {
		const payload =
			envelope.payload?.payload &&
			typeof envelope.payload.payload === "object" &&
			!Array.isArray(envelope.payload.payload)
				? (envelope.payload.payload as Record<string, unknown>)
				: {};
		const response = await ctx.requestCapability(
			sessionId,
			capabilityName,
			payload,
			targetClientId,
		);
		return okReply(envelope, response);
	} catch (error) {
		return errorReply(
			envelope,
			"capability_request_failed",
			error instanceof Error ? error.message : String(error),
		);
	}
}

export function handleCapabilityRespond(
	ctx: HubTransportContext,
	envelope: HubCommandEnvelope,
): HubReplyEnvelope {
	const requestId =
		typeof envelope.payload?.requestId === "string"
			? envelope.payload.requestId.trim()
			: "";
	const pending = ctx.pendingCapabilityRequests.get(requestId);
	if (!pending) {
		// A second connector (or a retried client) often answers after the first
		// already resolved the request. Treat as a no-op success.
		return okReply(envelope, { requestId, ignored: true });
	}
	const responderClientId = envelope.clientId?.trim() || "";
	if (responderClientId !== pending.targetClientId) {
		return errorReply(
			envelope,
			"capability_wrong_client",
			`Capability request ${requestId} is owned by ${pending.targetClientId}`,
		);
	}
	if (
		envelope.sessionId?.trim() &&
		envelope.sessionId.trim() !== pending.sessionId
	) {
		return errorReply(
			envelope,
			"capability_wrong_session",
			`Capability request ${requestId} belongs to session ${pending.sessionId}`,
		);
	}
	ctx.pendingCapabilityRequests.delete(requestId);
	const payload =
		envelope.payload?.payload &&
		typeof envelope.payload.payload === "object" &&
		!Array.isArray(envelope.payload.payload)
			? (envelope.payload.payload as Record<string, unknown>)
			: undefined;
	const error =
		typeof envelope.payload?.error === "string"
			? envelope.payload.error
			: undefined;
	const ok = envelope.payload?.ok === true;
	logHubMessage(ok ? "info" : "warn", "capability.respond", {
		requestId,
		sessionId: pending.sessionId,
		capabilityName: pending.capabilityName,
		targetClientId: pending.targetClientId,
		respondedByClientId: responderClientId,
		ok,
		error,
	});
	pending.resolve({ ok, payload, error });
	ctx.publish(
		ctx.buildEvent(
			"capability.resolved",
			{
				requestId,
				capabilityName: pending.capabilityName,
				targetClientId: pending.targetClientId,
				respondedByClientId: responderClientId,
				ok,
				payload,
				error,
			},
			pending.sessionId,
		),
	);
	return okReply(envelope, { requestId, ok });
}

import type {
	HubClientRegistration,
	HubCommandEnvelope,
	HubReplyEnvelope,
} from "@cline/shared";
import { createSessionId } from "@cline/shared";
import {
	asPlainRecord,
	errorReply,
	type HubTransportContext,
	okReply,
} from "./context";

export function handleClientRegister(
	ctx: HubTransportContext,
	envelope: HubCommandEnvelope,
): HubReplyEnvelope {
	const payload = envelope.payload as HubClientRegistration | undefined;
	const clientId =
		payload?.clientId?.trim() ||
		envelope.clientId?.trim() ||
		createSessionId("client_");
	ctx.clients.set(clientId, {
		clientId,
		clientType: payload?.clientType ?? "unknown",
		displayName: payload?.displayName,
		actorKind: payload?.actorKind ?? "client",
		connectedAt: Date.now(),
		lastSeenAt: Date.now(),
		transport: payload?.transport ?? "native",
		capabilities: payload?.capabilities ?? [],
		metadata: payload?.metadata,
		workspaceContext: payload?.workspaceContext,
	});
	ctx.publish(
		ctx.buildEvent("hub.client.registered", {
			clientId,
			clientType: payload?.clientType ?? "unknown",
			displayName: payload?.displayName,
			connectedAt: Date.now(),
		}),
	);
	return okReply(envelope, { clientId });
}

export function handleClientUpdate(
	ctx: HubTransportContext,
	envelope: HubCommandEnvelope,
): HubReplyEnvelope {
	const clientId = envelope.clientId?.trim();
	const client = clientId ? ctx.clients.get(clientId) : undefined;
	if (!clientId || !client) {
		return errorReply(
			envelope,
			"client_not_found",
			"Client is not registered with this hub.",
		);
	}
	const metadata = asPlainRecord(envelope.payload?.metadata);
	client.lastSeenAt = Date.now();
	if (metadata) {
		client.metadata = JSON.parse(JSON.stringify(metadata));
	}
	return okReply(envelope);
}

export function handleClientUnregister(
	ctx: HubTransportContext,
	envelope: HubCommandEnvelope,
	onClientRemoved: (clientId: string) => void,
): HubReplyEnvelope {
	const clientId = envelope.clientId?.trim();
	if (clientId) {
		ctx.clients.delete(clientId);
		onClientRemoved(clientId);
		ctx.publish(ctx.buildEvent("hub.client.disconnected", { clientId }));
	}
	return okReply(envelope);
}

export function handleClientList(
	ctx: HubTransportContext,
	envelope: HubCommandEnvelope,
): HubReplyEnvelope {
	return okReply(envelope, { clients: [...ctx.clients.values()] });
}

import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import type { HubCommandEnvelope } from "@cline/shared";
import {
	type ConnectorConfigRecord,
	type ConnectorConnectionRecord,
	withConnectorStore,
} from "@cline/shared/db";
import { afterEach, describe, expect, it, vi } from "vitest";
import {
	type ConnectorSupervisor,
	setActiveConnectorSupervisor,
} from "../../../services/connectors/connector-supervisor";
import { __test__, handleConnectorCommand } from "./connector-handlers";
import type { HubTransportContext } from "./context";

describe("connector hub handlers", () => {
	const previousDataDir = process.env.CLINE_DATA_DIR;
	const tempRoots: string[] = [];

	afterEach(() => {
		process.env.CLINE_DATA_DIR = previousDataDir;
		for (const root of tempRoots.splice(0)) {
			rmSync(root, { recursive: true, force: true });
		}
	});

	function useTempDataDir(): string {
		const root = mkdtempSync(join(tmpdir(), "hub-connectors-"));
		tempRoots.push(root);
		process.env.CLINE_DATA_DIR = root;
		return root;
	}

	function createHubContext(
		telemetry = { capture: vi.fn() },
	): HubTransportContext {
		return {
			clients: new Map(),
			sessionState: new Map(),
			pendingApprovals: new Map(),
			pendingCapabilityRequests: new Map(),
			suppressNextTerminalEventBySession: new Map(),
			telemetry: telemetry as never,
			sessionHost: {} as never,
			publish: vi.fn(),
			buildEvent: vi.fn() as never,
			requestCapability: vi.fn() as never,
		};
	}

	function connectorCommand(
		command: HubCommandEnvelope["command"],
		payload?: Record<string, unknown>,
	): HubCommandEnvelope {
		return {
			version: "v1",
			requestId: `req-${command}`,
			command,
			payload,
		};
	}

	function readPersistedConnector(
		channel: string,
	): ConnectorConfigRecord | undefined {
		return withConnectorStore((store) => store.getConfig(channel));
	}

	function readPersistedConnectorValues(
		channel: string,
	): Record<string, string> {
		return readPersistedConnector(channel)?.values ?? {};
	}

	function readPersistedConnection(
		channel: string,
		instanceId: string,
	): ConnectorConnectionRecord | undefined {
		return withConnectorStore((store) =>
			store.getConnection(channel, instanceId),
		);
	}

	it("configures a connector through hub settings without starting it", () => {
		useTempDataDir();

		const response = __test__.configureConnector({
			channel: "telegram",
			values: { "-k": "123456:fake-token" },
			security: { enabled: true, values: { userId: "123456789" } },
		});

		expect(response.active).toEqual([]);
		expect(response.configured).toEqual([
			expect.objectContaining({ id: "telegram", type: "telegram" }),
		]);

		const persisted = readPersistedConnector("telegram");
		expect(persisted?.values["-k"]).toBe("123456:fake-token");
		expect(persisted?.security).toEqual({
			enabled: true,
			values: { userId: "123456789" },
		});
		expect(readPersistedConnection("telegram", "cline_bot")).toBeUndefined();
	});

	it("does not surface CLI-only connections as dashboard configurations", () => {
		useTempDataDir();
		withConnectorStore((store) =>
			store.recordConnected("telegram", "cline_bot", [
				"-k",
				"123456:fake-token",
			]),
		);

		expect(__test__.connectorChannelsPayload().configured).toEqual([]);
		expect(readPersistedConnector("telegram")).toBeUndefined();
		expect(readPersistedConnection("telegram", "cline_bot")).toBeDefined();
	});

	it("refreshes reconnect args when a configured credential changes", () => {
		useTempDataDir();
		withConnectorStore((store) => {
			store.recordConnected("telegram", "old_bot", [
				"--provider",
				"openrouter",
				"--bot-token",
				"123456:old-token",
				"--bot-username",
				"old_bot",
				"--cwd",
				"/workspace",
				"--no-tools",
				"--hook-command",
				"custom-hook",
			]);
			store.setEnabled("telegram", false);
		});

		__test__.configureConnector({
			channel: "telegram",
			values: { "-k": "123456:rotated-token" },
			security: { enabled: true, values: { userId: "987654321" } },
		});

		const persisted = readPersistedConnection("telegram", "old_bot");
		expect(persisted?.connectArgs).toEqual([
			"--provider",
			"openrouter",
			"--cwd",
			"/workspace",
			"--no-tools",
			"-k",
			"123456:rotated-token",
			"--allowed-user-id",
			"987654321",
		]);
		expect(persisted?.enabled).toBe(false);
	});

	it("saves dashboard config without rewriting multiple persisted instances", () => {
		useTempDataDir();
		withConnectorStore((store) => {
			store.recordConnected("telegram", "first_bot", [
				"-k",
				"123456:first-token",
			]);
			store.recordConnected("telegram", "second_bot", [
				"-k",
				"123456:second-token",
			]);
		});

		const response = __test__.configureConnector({
			channel: "telegram",
			values: { "-k": "123456:dashboard-token" },
		});

		expect(response.configured).toEqual([
			expect.objectContaining({ id: "telegram", type: "telegram" }),
		]);
		expect(readPersistedConnectorValues("telegram")).toEqual({
			"-k": "123456:dashboard-token",
		});
		expect(
			withConnectorStore((store) =>
				store
					.listConnections("telegram")
					.map((connection) => connection.connectArgs),
			),
