	options: PrepareRemoteConfigCoreIntegrationOptions,
): ITelemetryService | undefined {
	const telemetryConfig: Partial<OpenTelemetryClientConfig> | undefined =
		prepared.telemetry || options.telemetryService
			? {
					...(options.telemetryService ?? {}),
					...(prepared.telemetry ?? {}),
				}
			: undefined;

	if (!telemetryConfig) {
		return undefined;
	}

	return createConfiguredTelemetryService(
		createClineTelemetryServiceConfig(telemetryConfig),
	).telemetry;
}

export function createRemoteConfigSessionMessagesArtifactUploader(): SessionMessagesArtifactUploader {
	const uploader = createSharedRemoteConfigSessionMessagesArtifactUploader();
	return {
		async uploadMessagesFile(input) {
			await uploader.uploadMessagesFile(input);
		},
	};
}

export async function prepareRemoteConfigCoreIntegration(
	options: PrepareRemoteConfigCoreIntegrationOptions,
): Promise<PreparedRemoteConfigCoreIntegration> {
	const prepared = await prepareRemoteConfigRuntime(options);
	const telemetry = createTelemetryService(prepared, options);
	const extensions = [prepared.pluginDefinition];
	const userDistinctId = prepared.claims?.subject;
	const blobUploadMetadataTemplate = buildRemoteConfigSessionBlobUploadMetadata(
		prepared.bundle?.remoteConfig,
		userDistinctId,
	);
	let registeredSessionId: string | undefined;

	return {
		prepared,
		extensions,
		telemetry,
		applyToStartSessionInput(input: ClineCoreStartInput): ClineCoreStartInput {
			const existingExtensions = input.config.extensions ?? [];
			const existingTelemetry = input.config.telemetry;
			const sessionId = blobUploadMetadataTemplate
				? input.config.sessionId?.trim() || createSessionId()
				: input.config.sessionId;
			if (sessionId && blobUploadMetadataTemplate) {
				registeredSessionId = sessionId;
			}
			const blobUploadMetadata =
				sessionId && blobUploadMetadataTemplate
					? registerRemoteConfigSessionBlobUpload(
							sessionId,
							prepared.bundle?.remoteConfig,
							userDistinctId,
						)
					: undefined;
			const sessionMetadata = blobUploadMetadata
				? {
						...(input.sessionMetadata ?? {}),
						[REMOTE_CONFIG_SESSION_BLOB_UPLOAD_METADATA_KEY]:
							blobUploadMetadata,
					}
				: input.sessionMetadata;
			return {
				...input,
				...(sessionMetadata ? { sessionMetadata } : {}),
				config: {
					...input.config,
					...(sessionId ? { sessionId } : {}),
					extensions: [...existingExtensions, ...extensions],
					telemetry: telemetry ?? existingTelemetry,
				},
			};
		},
		async dispose(): Promise<void> {
			if (registeredSessionId) {
				clearRemoteConfigSessionBlobUpload(registeredSessionId);
			}
		},
	};
}

export {
	buildRemoteConfigSessionBlobUploadMetadata,
	REMOTE_CONFIG_SESSION_BLOB_UPLOAD_METADATA_KEY,
	readRemoteConfigSessionBlobUploadMetadata,
	registerRemoteConfigSessionBlobUpload,
};

import type { RuntimeCapabilities } from "./runtime-capabilities";

export function normalizeRuntimeCapabilities(
	...sources: Array<RuntimeCapabilities | undefined>
): RuntimeCapabilities | undefined {
	let toolExecutors: RuntimeCapabilities["toolExecutors"] | undefined;
	let requestToolApproval:
		| RuntimeCapabilities["requestToolApproval"]
		| undefined;

	for (const source of sources) {
		if (!source) continue;
		if (source.toolExecutors) {
			toolExecutors = {
				...(toolExecutors ?? {}),
				...source.toolExecutors,
			};
		}
		if (source.requestToolApproval) {
			requestToolApproval = source.requestToolApproval;
		}
	}

	const hasToolExecutors =
		toolExecutors && Object.keys(toolExecutors).length > 0;
	if (!hasToolExecutors && !requestToolApproval) {
		return undefined;
	}
	return {
		...(hasToolExecutors ? { toolExecutors } : {}),
		...(requestToolApproval ? { requestToolApproval } : {}),
	};
}

import type { ToolApprovalRequest, ToolApprovalResult } from "@cline/shared";
import type { ToolExecutors } from "../../extensions/tools";

export interface RuntimeCapabilities {
	toolExecutors?: Partial<ToolExecutors>;
	requestToolApproval?: (
		request: ToolApprovalRequest,
	) => Promise<ToolApprovalResult> | ToolApprovalResult;
}

import { EMPTY_CONTENT_TEXT } from "@cline/shared";
import { describe, expect, it } from "vitest";
import {
	agentMessageToMessageWithMetadata,
	messagesToAgentMessages,
	messageToAgentMessages,
} from "./agent-message-codec";

describe("agent message codec", () => {
	it("replaces empty persisted messages with an explicit error text part", () => {
		expect(
			messageToAgentMessages({
				id: "empty",
				role: "assistant",
				ts: 1,
				content: [],
			}),
		).toEqual([
			{
				id: "empty",
				role: "assistant",
				content: [{ type: "text", text: EMPTY_CONTENT_TEXT }],
				createdAt: 1,
				metadata: undefined,
				modelInfo: undefined,
				metrics: undefined,
			},
		]);
		expect(
			messageToAgentMessages({
				id: "blank",
				role: "user",
				ts: 1,
				content: "",
			}),
		).toEqual([
			{
				id: "blank",
				role: "user",
				content: [{ type: "text", text: EMPTY_CONTENT_TEXT }],
				createdAt: 1,
				metadata: undefined,
				modelInfo: undefined,
				metrics: undefined,
			},
		]);
		expect(
			messageToAgentMessages({
				id: "whitespace",
				role: "assistant",
				ts: 1,
				content: "   \n\t  ",
			}),
		).toEqual([
			{
				id: "whitespace",
				role: "assistant",
				content: [{ type: "text", text: EMPTY_CONTENT_TEXT }],
				createdAt: 1,
				metadata: undefined,
				modelInfo: undefined,
				metrics: undefined,
			},
		]);
	});

	it("preserves mixed tool result and user text order", () => {
		const messages = messageToAgentMessages({
			id: "msg_mixed",
			role: "user",
			ts: 1,
			content: [
				{
					type: "tool_result",
					tool_use_id: "toolu_1",
					name: "run_commands",
					content: "tool output",
				},
				{
					type: "text",
					text: "steer this next",
				},
			],
		});

		expect(messages.map((message) => message.role)).toEqual(["tool", "user"]);
		expect(messages[0]?.content).toEqual([
			{
				type: "tool-result",
				toolCallId: "toolu_1",
				toolName: "run_commands",
				output: "tool output",
				isError: undefined,
			},
		]);
		expect(messages[1]?.content).toEqual([
			{
				type: "text",
				text: "steer this next",
			},
		]);
	});

	it("assigns a persisted user-run span to only one split segment", () => {
		const messages = messageToAgentMessages({
			id: "compacted-mixed",
			role: "user",
			ts: 1,
			content: [
				{ type: "text", text: "Earlier user context" },
				{
					type: "tool_result",
					tool_use_id: "toolu_1",
					name: "read_files",
					content: "Tool output",
				},
				{ type: "text", text: "Later user context" },
			],
			metadata: {
				kind: "compaction",
				userRunSpan: 3,
			},
		});

		expect(messages.map((message) => message.role)).toEqual([
			"user",
			"tool",
			"user",
		]);
		expect(messages.map((message) => message.metadata?.userRunSpan)).toEqual([
			3, 0, 0,
		]);

		const persistedParts = messages.map(agentMessageToMessageWithMetadata);
		const restored = messagesToAgentMessages(persistedParts);
		expect(restored.map((message) => message.metadata?.userRunSpan)).toEqual([
			3, 0, 0,
		]);
	});

	it("keeps user text before later tool results", () => {
		const messages = messageToAgentMessages({
			id: "msg_text_first",
			role: "user",
			ts: 1,
			content: [
				{
					type: "text",
					text: "before",
				},
				{
					type: "tool_result",
					tool_use_id: "toolu_2",
					name: "read_files",
					content: "tool output",
				},
			],
		});

		expect(messages.map((message) => message.role)).toEqual(["user", "tool"]);
		expect(messages[0]?.content).toEqual([{ type: "text", text: "before" }]);
		expect(messages[1]?.content).toEqual([
			expect.objectContaining({
				type: "tool-result",
				toolCallId: "toolu_2",
				toolName: "read_files",
			}),
		]);
	});

	it("round-trips Gemini tool call thought signatures", () => {
		const persisted = agentMessageToMessageWithMetadata({
			id: "msg_tool_call",
			role: "assistant",
			createdAt: 1,
			content: [
				{
					type: "tool-call",
					toolCallId: "toolu_4",
					toolName: "editor",
					input: { path: "/tmp/out.txt" },
					metadata: {
						thoughtSignature: "sig_4",
					},
				},
			],
		});

		expect(persisted.content).toEqual([
			expect.objectContaining({
				type: "tool_use",
				id: "toolu_4",
				name: "editor",
				signature: "sig_4",
			}),
		]);

		const [restored] = messagesToAgentMessages([persisted]);
		expect(restored?.content[0]).toMatchObject({
			type: "tool-call",
			toolCallId: "toolu_4",
			toolName: "editor",
			metadata: {
				signature: "sig_4",
			},
		});
	});

	it("keeps tool result message ids stable across restore/persist round-trips", () => {
		// Regression: the tool-id suffix used to be re-appended on every
		// conversion, so each agent.restore() mutated the id. Ids feed the
		// compaction source-prefix hash, so the drift silently invalidated
		// saved compaction state and the model kept receiving the full
		// transcript after a successful /compact.
		const persisted = {
			id: "msg_result_1",
			role: "user" as const,
			content: [
				{
					type: "tool_result" as const,
					tool_use_id: "call_abc_1",
					name: "read_files",
					content: "file contents",
				},
			],
			ts: 1_784_249_275_514,
		};

		const [firstPass] = messagesToAgentMessages([persisted]);
		expect(firstPass?.id).toBe("msg_result_1");

		const roundTripped = agentMessageToMessageWithMetadata(firstPass!);
		const [secondPass] = messagesToAgentMessages([roundTripped]);
		expect(secondPass?.id).toBe("msg_result_1");
		expect(agentMessageToMessageWithMetadata(secondPass!)).toEqual(
			roundTripped,
		);
	});

	it("still disambiguates tool results split out of a mixed message", () => {
		const mixed = {
			id: "msg_mixed",
			role: "user" as const,
			content: [
				{ type: "text" as const, text: "feedback" },
				{
					type: "tool_result" as const,
					tool_use_id: "call_a",
					name: "read_files",
					content: "a",
				},
				{
					type: "tool_result" as const,
					tool_use_id: "call_b",
					name: "read_files",
					content: "b",
				},
			],
			ts: 1,
		};

		const split = messagesToAgentMessages([mixed]);
		expect(split.map((message) => message.id)).toEqual([
			"msg_mixed",
			"msg_mixed_tool_call_a",
			"msg_mixed_tool_call_b",
		]);

		// A second round-trip of the split parts must not grow the ids.
		const persistedParts = split.map(agentMessageToMessageWithMetadata);
		const secondPass = messagesToAgentMessages(persistedParts);
		expect(secondPass.map((message) => message.id)).toEqual([
			"msg_mixed",
			"msg_mixed_tool_call_a",
			"msg_mixed_tool_call_b",
		]);
	});
});

import type {
	AgentMessage,
	AgentMessagePart,
	AgentTextPart,
	ContentBlock,
	FileContent,
	ImageContent,
	Message,
	MessageWithMetadata,
	RedactedThinkingContent,
	TextContent,
	ThinkingContent,
	ToolResultContent,
	ToolUseContent,
} from "@cline/shared";
import { EMPTY_CONTENT_TEXT } from "@cline/shared";

export function messageToAgentMessages(
	message: MessageWithMetadata,
): AgentMessage[] {
	const blocks = normalizeContentBlocks(message.content);
	const out: AgentMessage[] = [];
	const baseId = message.id ?? generateMessageId();
	let nonToolSegmentCount = 0;
	let nonToolBlocks: Exclude<ContentBlock, ToolResultContent>[] = [];
	const storedUserRunSpan =
		message.role === "user" &&
		typeof message.metadata?.userRunSpan === "number" &&
		Number.isInteger(message.metadata.userRunSpan) &&
		message.metadata.userRunSpan >= 0
			? message.metadata.userRunSpan
			: undefined;
	let userRunSpanAssigned = false;
	const segmentMetadata = (
		representsUserContent: boolean,
	): MessageWithMetadata["metadata"] => {
		if (storedUserRunSpan === undefined) {
			return message.metadata;
		}
		if (representsUserContent && !userRunSpanAssigned) {
			userRunSpanAssigned = true;
			return message.metadata;
		}
		return { ...message.metadata, userRunSpan: 0 };
	};

	const flushNonToolBlocks = () => {
		if (nonToolBlocks.length === 0) {
			return;
		}
		const id =
			nonToolSegmentCount === 0
				? baseId
				: `${baseId}_part_${nonToolSegmentCount}`;
		nonToolSegmentCount += 1;
		out.push({
			id,
			role: message.role,
			content: nonToolBlocks.map(contentBlockToAgentPart),
			createdAt: message.ts ?? Date.now(),
			metadata: segmentMetadata(true),
			modelInfo: message.modelInfo,
			metrics: metricsToAgentMetrics(message.metrics),
		});
		nonToolBlocks = [];
	};

	if (blocks.length === 0) {
		out.push({
			id: baseId,
			role: message.role,
			content: [{ type: "text", text: EMPTY_CONTENT_TEXT }],
			createdAt: message.ts ?? Date.now(),
			metadata: message.metadata,
			modelInfo: message.modelInfo,
			metrics: metricsToAgentMetrics(message.metrics),
		});
		return out;
	}

	// A message that is already a single tool result needs no id
	// disambiguation — the suffix only distinguishes the parts of a split
	// message. Keeping the id verbatim makes restore/persist round-trips
	// byte-stable; ids feed the compaction source-prefix hash, and a
	// re-suffixed id silently invalidates saved compaction state (and grows
	// without bound across restores).
	const isPureToolResult =
		blocks.length === 1 && blocks[0].type === "tool_result";

	for (const block of blocks) {
		if (block.type !== "tool_result") {
			nonToolBlocks.push(block);
			continue;
		}
		flushNonToolBlocks();
		const toolIdSuffix = `_tool_${block.tool_use_id}`;
		out.push({
			id:
				isPureToolResult || baseId.endsWith(toolIdSuffix)
					? baseId
					: `${baseId}${toolIdSuffix}`,
			role: "tool",
			content: [toolResultContentToAgentPart(block)],
			createdAt: message.ts ?? Date.now(),
			metadata: segmentMetadata(false),
		});
	}
	flushNonToolBlocks();

	return out;
}

export function messagesToAgentMessages(
	messages: readonly MessageWithMetadata[],
): AgentMessage[] {
	return messages.flatMap(messageToAgentMessages);
}

export function agentMessageToMessageWithMetadata(
	message: AgentMessage,
): MessageWithMetadata {
	const content = message.content
		.map(agentPartToContentBlock)
		.filter((block): block is ContentBlock => block !== undefined);
	return {
		id: message.id,
		role: message.role === "tool" ? "user" : message.role,
		content,
		ts: message.createdAt,
		metadata: message.metadata,
		modelInfo: message.modelInfo,
		metrics: agentMetricsToMetrics(message.metrics),
	};
}

export function agentMessagesToMessagesWithMetadata(
	messages: readonly AgentMessage[],
): MessageWithMetadata[] {
	return messages.map(agentMessageToMessageWithMetadata);
}

export function agentMessagesToMessages(
	messages: readonly AgentMessage[],
): Message[] {
	const out: Message[] = [];
	for (const message of messages) {
		const content = message.content
			.map(agentPartToContentBlock)
			.filter((block): block is ContentBlock => block !== undefined);
		const role = message.role === "tool" ? "user" : message.role;
		const previous = out[out.length - 1];
		if (
			role === "user" &&
			content.length > 0 &&
			content.every((block) => block.type === "tool_result") &&
			previous?.role === "user" &&
			Array.isArray(previous.content) &&
			previous.content.every((block) => block.type === "tool_result")
		) {
			previous.content.push(...content);
			continue;
		}
		out.push({ role, content });
	}
	return out;
}

function normalizeContentBlocks(content: Message["content"]): ContentBlock[] {
	if (typeof content === "string") {
		return content.trim().length > 0
			? [{ type: "text", text: content } as TextContent]
			: [];
	}
	return [...content];
}

function contentBlockToAgentPart(block: ContentBlock): AgentMessagePart {
	switch (block.type) {
		case "text":
			return { type: "text", text: block.text };
		case "thinking":
			return {
				type: "reasoning",
				text: block.thinking,
				metadata: block.signature
					? { signature: block.signature, details: block.details }
					: block.details
						? { details: block.details }
						: undefined,
			};
		case "redacted_thinking":
			return {
				type: "reasoning",
				text: "",
				redacted: true,
				metadata: { data: block.data },
			};
		case "image":
			return { type: "image", image: block.data, mediaType: block.mediaType };
		case "file":
			return { type: "file", path: block.path, content: block.content };
		case "tool_use":
			return {
				type: "tool-call",
				toolCallId: block.id,
				toolName: block.name,
				input: block.input,
				metadata: block.signature
					? {
							signature: block.signature,
						}
					: undefined,
			};
		case "tool_result":
			return toolResultContentToAgentPart(block);
	}
}

function toolResultContentToAgentPart(
	block: ToolResultContent,
): AgentMessagePart {
	return {
		type: "tool-result",
		toolCallId: block.tool_use_id,
		toolName: block.name,
		output: block.content,
		isError: block.is_error,
	};
}

function agentPartToContentBlock(
	part: AgentMessagePart,
): ContentBlock | undefined {
	switch (part.type) {
		case "text":
			return { type: "text", text: (part as AgentTextPart).text };
		case "reasoning": {
			if (part.redacted === true) {
				const data =
					(part.metadata as { data?: string } | undefined)?.data ?? "";
				return {
					type: "redacted_thinking",
					data,
				} satisfies RedactedThinkingContent;
			}
			const metadata = part.metadata as
				| { signature?: string; details?: unknown[] }
				| undefined;
			return {
				type: "thinking",
				thinking: part.text,
				signature: metadata?.signature,
				details: metadata?.details,
			} satisfies ThinkingContent;
		}
		case "image":
			return typeof part.image === "string"
				? ({
						type: "image",
						data: part.image,
						mediaType: part.mediaType ?? "image/png",
					} satisfies ImageContent)
				: undefined;
		case "file":
			return {
				type: "file",
				path: part.path,
				content: part.content,
			} satisfies FileContent;
		case "tool-call": {
			const metadata = part.metadata as
				| {
						signature?: string;
						thoughtSignature?: string;
				  }
				| undefined;
			return {
				type: "tool_use",
				id: part.toolCallId,
				name: part.toolName,
				input: (part.input as Record<string, unknown>) ?? {},
				signature: metadata?.thoughtSignature ?? metadata?.signature,
			} satisfies ToolUseContent;
		}
		case "tool-result": {
			const output = part.output;
			const content =
				typeof output === "string"
					? output
					: Array.isArray(output)
						? (output as ToolResultContent["content"])
						: JSON.stringify(output);
			return {
				type: "tool_result",
				tool_use_id: part.toolCallId,
				name: part.toolName,
				content,
				is_error: part.isError,
			} satisfies ToolResultContent;
		}
	}
}

function metricsToAgentMetrics(
	metrics: MessageWithMetadata["metrics"],
): AgentMessage["metrics"] {
	if (!metrics) return undefined;
	return {
		inputTokens: metrics.inputTokens ?? 0,
		outputTokens: metrics.outputTokens ?? 0,
		cacheReadTokens: metrics.cacheReadTokens ?? 0,
		cacheWriteTokens: metrics.cacheWriteTokens ?? 0,
		cost: metrics.cost,
	};
}

function agentMetricsToMetrics(
	metrics: AgentMessage["metrics"],
): MessageWithMetadata["metrics"] {
	if (!metrics) return undefined;
	return {
		inputTokens: metrics.inputTokens,
		outputTokens: metrics.outputTokens,
		cacheReadTokens: metrics.cacheReadTokens,
		cacheWriteTokens: metrics.cacheWriteTokens,
		cost: metrics.cost,
	};
}

let msgSeq = 0;
function generateMessageId(): string {
	msgSeq += 1;
	return `msg_${Date.now().toString(36)}_${msgSeq.toString(36)}`;
}

