/**
 * Build an `AgentRuntimeConfig` from an `AgentConfig` plus session-owned
 * supporting objects (model handler, tools, hooks, plugins, telemetry).
 *
 * The function is intentionally **pure**: it does not create handlers or tools
 * itself; it receives them already resolved from the caller (`SessionRuntime`)
 * and wires them into an `AgentRuntimeConfig`.
 *
 * Fields that do **not** round-trip into `AgentRuntimeConfig`
 * (e.g. `execution.maxConsecutiveMistakes`, `execution.loopDetection`) are
 * consumed by `SessionRuntime` / `MistakeTracker` /
 * `LoopDetectionTracker` — not passed through here.
 */

import type {
	AgentConfig,
	AgentMessage,
	AgentModel,
	AgentRuntimeConfig,
	AgentRuntimeHooks,
	AgentRuntimePlugin,
	AgentRuntimePrepareTurnContext,
	AgentRuntimePrepareTurnResult,
	AgentTool,
	BasicLogger,
	ITelemetryService,
} from "@cline/shared";

/**
 * Inputs required to assemble an `AgentRuntimeConfig`. Distinct from
 * `AgentConfig` because some of these (the model adapter, the hook
 * bridge's runtime-hooks bag, a resolved plugin list) can only be
 * produced inside `SessionRuntime`.
 */
export interface CreateAgentRuntimeConfigInput {
	readonly agentConfig: AgentConfig;
	/**
	 * Core/hub runtime session identifier used for host lifecycle operations,
	 * event routing, persistence, and approval delivery.
	 */
	readonly sessionId?: string;
	readonly agentId: string;
	/**
	 * Agent conversation/transcript identifier used by tools, hooks, telemetry,
	 * and model history correlation.
	 */
	readonly conversationId?: string;
	readonly parentAgentId?: string;
	/** The role label for teammates (`AgentConfig.role` in sub-agent configs). */
	readonly agentRole?: string;
	/** Pre-built model adapter (produced by `apiHandlerToAgentModel`). */
	readonly model: AgentModel;
	readonly logger?: BasicLogger;
	readonly telemetry?: ITelemetryService;
	/** Pre-built tool array (builtins + plugin-contributed + session extras). */
	readonly tools?: readonly AgentTool<unknown, unknown>[];
	readonly toolContextMetadata?: Record<string, unknown>;
	/** Pre-resolved plugin list from the plugin loader. */
	readonly plugins?: readonly AgentRuntimePlugin[];
	/** Runtime hooks supplied by the session/runtime builder. */
	readonly hooks?: Partial<AgentRuntimeHooks>;
	/** Host-owned context pipeline invoked before runtime model hooks. */
	readonly prepareTurn?: (
		context: AgentRuntimePrepareTurnContext,
	) =>
		| Promise<AgentRuntimePrepareTurnResult | undefined>
		| AgentRuntimePrepareTurnResult
		| undefined;
	/** Seed messages (usually `session.conversation.getMessages()`). */
	readonly initialMessages?: readonly AgentMessage[];
	/**
	 * Override for `AgentRuntimeConfig.systemPrompt` — useful when
	 * the caller has composed additional guidance (e.g. via
	 * `LocalRuntimeHost.composeSystemPrompt`). Defaults to
	 * `agentConfig.systemPrompt`.
	 */
	readonly systemPrompt?: string;
}

/**
 * Produce an `AgentRuntimeConfig` from session-owned runtime inputs.
 */
export function createAgentRuntimeConfig(
	input: CreateAgentRuntimeConfigInput,
): AgentRuntimeConfig {
	const { agentConfig } = input;

	const modelOptions = buildModelOptions(agentConfig);
	const messageModelInfo = buildMessageModelInfo(agentConfig);
	const hooks = input.hooks;
	const toolExecution = resolveToolExecution(agentConfig.maxParallelToolCalls);

	const config: AgentRuntimeConfig = {
		sessionId: input.sessionId ?? agentConfig.sessionId,
		agentId: input.agentId,
		conversationId: input.conversationId,
		parentAgentId: input.parentAgentId,
		agentRole: input.agentRole,
		systemPrompt: input.systemPrompt ?? agentConfig.systemPrompt,
		messageModelInfo,
		model: input.model,
		modelOptions,
		tools: input.tools,
		hooks,
		prepareTurn: input.prepareTurn,
		consumePendingUserMessage: agentConfig.consumePendingUserMessage,
		plugins: input.plugins,
		logger: input.logger ?? agentConfig.logger,
		telemetry: input.telemetry ?? agentConfig.telemetry,
		initialMessages: input.initialMessages,
		completionPolicy: agentConfig.completionPolicy,
		maxIterations: agentConfig.maxIterations,
		toolExecution,
		toolPolicies: agentConfig.toolPolicies,
		toolContextMetadata: input.toolContextMetadata,
		requestToolApproval: agentConfig.requestToolApproval,
	};

	return config;
}

// =============================================================================
// Helpers
// =============================================================================

/**
 * Collect the provider-/reasoning-related fields from `AgentConfig`
 * into `AgentRuntimeConfig.modelOptions`. Kept undefined when every
 * field is undefined so the runtime does not receive an empty object.
 */
export function buildModelOptions(
	config: AgentConfig,
): Record<string, unknown> | undefined {
	const options: Record<string, unknown> = {};
	if (config.thinking !== undefined) {
		options.thinking = config.thinking;
	}
	if (config.reasoningEffort !== undefined) {
		options.reasoningEffort = config.reasoningEffort;
	}
	if (config.thinkingBudgetTokens !== undefined) {
		options.thinkingBudgetTokens = config.thinkingBudgetTokens;
	}
	if (config.maxTokensPerTurn !== undefined) {
		options.maxTokensPerTurn = config.maxTokensPerTurn;
	}
	if (config.temperature !== undefined) {
		options.temperature = config.temperature;
	}
	if (config.apiTimeoutMs !== undefined) {
		options.apiTimeoutMs = config.apiTimeoutMs;
	}
	return Object.keys(options).length > 0 ? options : undefined;
}

/**
 * Compose `messageModelInfo` from the provider-related fields per
 * §3.2.1: `{ id: modelId, provider: providerId, family:
 * providerConfig?.family }`.
 */
export function buildMessageModelInfo(
	config: AgentConfig,
): AgentMessage["modelInfo"] {
	const family = (config.providerConfig as { family?: string } | undefined)
		?.family;
	return {
		id: config.modelId,
		provider: config.providerId,
		family,
	};
}

/**
 * `"parallel"` when `maxParallelToolCalls ≥ 2`, `"sequential"` when
 * `1`, `undefined` when the caller did not specify.
 */
export function resolveToolExecution(
	maxParallelToolCalls: number | undefined,
): "sequential" | "parallel" | undefined {
	if (maxParallelToolCalls === undefined) {
		return undefined;
	}
	return maxParallelToolCalls >= 2 ? "parallel" : "sequential";
}

import { describe, expect, it } from "vitest";
import { buildConnectionUpdate } from "./connection-update";

describe("buildConnectionUpdate", () => {
	const base = {
		providerId: "openai",
		modelId: "codex-test",
		apiKey: "sk-test",
	};

	it("includes only the connection fields that are defined", () => {
		expect(buildConnectionUpdate(base)).toEqual(base);
		expect(
			buildConnectionUpdate({
				...base,
				baseUrl: "https://example.test",
				headers: { "x-a": "1" },
			}),
		).toEqual({
			...base,
			baseUrl: "https://example.test",
			headers: { "x-a": "1" },
		});
	});

	it("passes an empty string through so callers can clear a field", () => {
		expect(buildConnectionUpdate({ ...base, apiKey: "" })).toEqual({
			...base,
			apiKey: "",
		});
	});

	it("clears reasoning when thinking is explicitly false", () => {
		expect(
			buildConnectionUpdate({
				...base,
				thinking: false,
				reasoningEffort: "high",
				thinkingBudgetTokens: 1024,
			}),
		).toEqual({
			...base,
			thinking: false,
			reasoningEffort: null,
			thinkingBudgetTokens: null,
		});
	});

	it("enables reasoning with the selected effort", () => {
		expect(
			buildConnectionUpdate({
				...base,
				thinking: true,
				reasoningEffort: "low",
			}),
		).toEqual({
			...base,
			thinking: true,
			reasoningEffort: "low",
			thinkingBudgetTokens: null,
		});
	});

	it("clears stale effort and budget when thinking is enabled without them", () => {
		expect(buildConnectionUpdate({ ...base, thinking: true })).toEqual({
			...base,
			thinking: true,
			reasoningEffort: null,
			thinkingBudgetTokens: null,
		});
	});

	it("keeps a provided budget when thinking is enabled explicitly", () => {
		expect(
			buildConnectionUpdate({
				...base,
				thinking: true,
				thinkingBudgetTokens: 1024,
			}),
		).toEqual({
			...base,
			thinking: true,
			reasoningEffort: null,
			thinkingBudgetTokens: 1024,
		});
	});

	it("enables thinking when only an effort is provided", () => {
		expect(
			buildConnectionUpdate({ ...base, reasoningEffort: "medium" }),
		).toEqual({ ...base, thinking: true, reasoningEffort: "medium" });
	});

	it("enables thinking and truncates a fractional budget", () => {
		expect(
			buildConnectionUpdate({ ...base, thinkingBudgetTokens: 2048.7 }),
		).toEqual({ ...base, thinking: true, thinkingBudgetTokens: 2048 });
	});

	it("leaves reasoning untouched when thinking is unset", () => {
		expect(buildConnectionUpdate(base)).toEqual(base);
	});
});

import type { CoreSessionConfig } from "../../types/config";

export interface ConnectionUpdate {
	providerId?: string;
	modelId?: string;
	apiKey?: string;
	baseUrl?: string;
	headers?: Record<string, string>;
	providerConfig?: CoreSessionConfig["providerConfig"];
	reasoningEffort?: CoreSessionConfig["reasoningEffort"] | null;
	thinking?: CoreSessionConfig["thinking"] | null;
	thinkingBudgetTokens?: CoreSessionConfig["thinkingBudgetTokens"] | null;
}

export interface ConnectionUpdateInput {
	providerId?: string;
	modelId?: string;
	apiKey?: string;
	baseUrl?: string;
	headers?: Record<string, string>;
	providerConfig?: CoreSessionConfig["providerConfig"];
	thinking?: boolean;
	reasoningEffort?: CoreSessionConfig["reasoningEffort"];
	thinkingBudgetTokens?: number;
}

/**
 * Builds a ConnectionUpdate for switching a live session's provider/model
 * connection. Shared by clients (CLI, desktop sidecar, …) so the
 * thinking/reasoning transition rules stay consistent:
 * - `thinking: false` disables reasoning and clears effort/budget.
 * - `thinking: true` (or a provided effort/budget) enables reasoning; an
 *   explicit `thinking: true` resets the reasoning state, so a stale effort or
 *   token budget from the previous connection is cleared unless a replacement
 *   accompanies it. A bare effort/budget without a `thinking` flag updates
 *   only the provided field.
 * - `thinking: undefined` leaves the session's reasoning state untouched.
 * Connection fields are included only when defined; an empty string is passed
 * through (it means "clear"), so callers that want to skip blanks must drop
 * them before calling.
 */
export function buildConnectionUpdate(
	input: ConnectionUpdateInput,
): ConnectionUpdate {
	const update: ConnectionUpdate = {};
	if (input.providerId !== undefined) update.providerId = input.providerId;
	if (input.modelId !== undefined) update.modelId = input.modelId;
	if (input.apiKey !== undefined) update.apiKey = input.apiKey;
	if (input.baseUrl !== undefined) update.baseUrl = input.baseUrl;
	if (input.headers !== undefined) update.headers = input.headers;
	if (input.providerConfig !== undefined) {
		update.providerConfig = input.providerConfig;
	}
	if (input.thinking === false) {
		update.thinking = false;
		update.reasoningEffort = null;
		update.thinkingBudgetTokens = null;
		return update;
	}
	if (input.thinking === true) {
		update.thinking = true;
		update.reasoningEffort = input.reasoningEffort ?? null;
		// Cleared symmetrically with reasoningEffort; a valid budget below
		// overwrites the null.
		update.thinkingBudgetTokens = null;
	} else if (input.reasoningEffort !== undefined) {
		update.thinking = true;
		update.reasoningEffort = input.reasoningEffort;
	}
	if (
		typeof input.thinkingBudgetTokens === "number" &&
		Number.isFinite(input.thinkingBudgetTokens) &&
		input.thinkingBudgetTokens > 0
	) {
		update.thinking = true;
		update.thinkingBudgetTokens = Math.trunc(input.thinkingBudgetTokens);
	}
	return update;
}

export function normalizeConnectionUpdate(
	updates: ConnectionUpdate,
): ConnectionUpdate {
	const normalized: ConnectionUpdate = { ...updates };
	const hasThinking = Object.hasOwn(updates, "thinking");
	const hasThinkingBudgetTokens = Object.hasOwn(
		updates,
		"thinkingBudgetTokens",
	);
	const disablesThinking =
		updates.thinking === false || updates.thinking === null;

	if (disablesThinking) {
		normalized.reasoningEffort = undefined;
		normalized.thinkingBudgetTokens = undefined;
		return normalized;
	}

	if (
		!hasThinking &&
		hasThinkingBudgetTokens &&
		typeof updates.thinkingBudgetTokens === "number" &&
		Number.isFinite(updates.thinkingBudgetTokens) &&
		updates.thinkingBudgetTokens > 0
	) {
		normalized.thinking = true;
	}

	return normalized;
}

