async function writeManifest(
	sessionId: string,
	manifest: Record<string, unknown>,
): Promise<void> {
	const sessionDir = join(tempSessionDataDir, sessionId);
	const completeManifest = {
		version: 1,
		session_id: sessionId,
		source: "cli",
		pid: 1,
		started_at: "2026-04-20T00:00:00.000Z",
