		const continueFn = vi.fn(async (prompt: string) => {
			turn += 1;
			messages = [
				...messages,
				{
					role: "user",
					content: [{ type: "text", text: prompt }],
				},
				{
					role: "assistant",
					content: [{ type: "text", text: `reply:${turn}:${prompt}` }],
