		let activeRun = false;
		let rejectRun: ((error: Error) => void) | undefined;
		let markRunStarted: (() => void) | undefined;
		const runStarted = new Promise<void>((resolve) => {
			markRunStarted = resolve;
		});
		const run = vi
			.fn()
			.mockImplementationOnce(
				() =>
					new Promise<AgentResult>((_resolve, reject) => {
						activeRun = true;
						rejectRun = (error) => {
							activeRun = false;
							reject(error);
						};
						markRunStarted?.();
					}),
			)
