		const firstTurn = manager.runTurn({ sessionId, prompt: "slow" });
		await runStarted;
		await manager.runTurn({
			sessionId,
			prompt: "queued prompt",
			delivery: "queue",
		});
		await manager.runTurn({
			sessionId,
			prompt: "steered prompt",
			delivery: "steer",
		});
