import { existsSync } from "node:fs";
import { readFile } from "node:fs/promises";
import type * as LlmsProviders from "@cline/llms";
import type { HookEventPayload } from "../../hooks";
import type { CoreSessionEvent } from "../../types/events";
import type {
	RuntimeHostSubscribeOptions,
	SessionAccumulatedUsage,
} from "./runtime-host";

export class RuntimeHostEventBus {
	private readonly listeners = new Set<{
		listener: (event: CoreSessionEvent) => void;
		sessionId?: string;
	}>();

	subscribe(
		listener: (event: CoreSessionEvent) => void,
		options?: RuntimeHostSubscribeOptions,
	): () => void {
		const entry = {
			listener,
			sessionId: options?.sessionId?.trim() || undefined,
		};
		this.listeners.add(entry);
		return () => {
			this.listeners.delete(entry);
		};
	}

	emit(event: CoreSessionEvent): void {
		const sessionId = event.payload.sessionId?.trim();
		for (const entry of this.listeners) {
			if (entry.sessionId && entry.sessionId !== sessionId) {
				continue;
			}
			entry.listener(event);
		}
	}

	get size(): number {
		return this.listeners.size;
	}
}

// Returns the persisted messages verbatim. User messages keep their
// runtime-generated <user_input mode="..."> wrappers and <mode_notice>
// elements: they are the durable record of which mode each message was sent
// in, and session restarts re-seed new sessions through this read path, so
// stripping here would launder that history off disk (and out of the model's
// context) a little more on every restart. Display surfaces are responsible
// for their own formatting via formatDisplayUserInput.
export async function readPersistedMessagesFile(
	messagesPath?: string | null,
): Promise<LlmsProviders.Message[]> {
	const path = messagesPath?.trim();
	if (!path || !existsSync(path)) return [];
	try {
		const raw = (await readFile(path, "utf8")).trim();
		if (!raw) return [];
		const parsed = JSON.parse(raw) as unknown;
		if (Array.isArray(parsed)) {
			return parsed as LlmsProviders.Message[];
		}
		if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
			const messages = (parsed as { messages?: unknown }).messages;
			if (Array.isArray(messages)) {
				return messages as LlmsProviders.Message[];
			}
		}
		return [];
	} catch {
		return [];
	}
}

export function cloneAccumulatedUsage(
	usage: SessionAccumulatedUsage | undefined,
): SessionAccumulatedUsage | undefined {
	return usage ? { ...usage } : undefined;
}

type HookAuditBackend = {
	queueSpawnRequest(payload: HookEventPayload): Promise<void>;
	upsertSubagentSessionFromHook(
		payload: HookEventPayload,
	): Promise<string | undefined>;
	appendSubagentHookAudit(
		sessionId: string,
		payload: HookEventPayload,
	): Promise<void>;
	applySubagentStatus(
		sessionId: string,
		payload: HookEventPayload,
	): Promise<void>;
};

export async function replaySubagentHookEvent(
	payload: HookEventPayload,
	backend: HookAuditBackend,
): Promise<void> {
	const shouldTouchSessions =
		payload.hookName === "tool_call" || !!payload.parent_agent_id;
	if (!shouldTouchSessions) {
		return;
	}
	await backend.queueSpawnRequest(payload);
	const subSessionId = await backend.upsertSubagentSessionFromHook(payload);
	if (!subSessionId) {
		return;
	}
	await backend.appendSubagentHookAudit(subSessionId, payload);
	await backend.applySubagentStatus(subSessionId, payload);
}

import { describe, expect, it } from "vitest";
import { SessionRunInProgressError } from "../orchestration/session-runtime-orchestrator";
import {
	isSessionNotFoundError,
	isUnusableSessionError,
	SessionNotFoundError,
} from "./runtime-host";

describe("isUnusableSessionError", () => {
	it("matches a missing session", () => {
		expect(isUnusableSessionError(new SessionNotFoundError("sess_1"))).toBe(
			true,
		);
		expect(
			isUnusableSessionError(
				Object.assign(new Error("session not found: sess_1"), {
					code: "session_not_found",
				}),
			),
		).toBe(true);
	});

	it("matches a session wedged on a run that never drained", () => {
		expect(
			isUnusableSessionError(new SessionRunInProgressError("agent_1")),
		).toBe(true);
	});

	it("matches the wedged-run error by message once the code is gone", () => {
		// Errors reaching a connector have crossed the hub's JSON boundary, which
		// leaves only the message — and hub and CLI are often different versions.
		expect(
			isUnusableSessionError(
				new Error(
					"SessionRuntime.shutdown called while a run is in progress (agentId=agent_1)",
				),
			),
		).toBe(true);
		expect(
			isUnusableSessionError({
				message:
					"SessionRuntime.shutdown called while a run is in progress (agentId=agent_1)",
			}),
		).toBe(true);
	});

	it("leaves ordinary run failures alone", () => {
		// Replacing the session would hide a real error and lose the conversation.
		expect(isUnusableSessionError(new Error("provider returned 500"))).toBe(
			false,
		);
		expect(isUnusableSessionError(new Error("aborted by user"))).toBe(false);
		expect(isUnusableSessionError(undefined)).toBe(false);
		expect(isUnusableSessionError("some string")).toBe(false);
	});

	it("keeps the narrower missing-session check narrow", () => {
		// Callers that specifically mean "the hub forgot this session" must not
		// start matching wedged runtimes.
		expect(
			isSessionNotFoundError(new SessionRunInProgressError("agent_1")),
		).toBe(false);
	});
});

describe("SessionRunInProgressError", () => {
	it("carries a stable code and keeps the original message", () => {
		const error = new SessionRunInProgressError("agent_1");

		expect(error.code).toBe("session_run_in_progress");
		expect(error.message).toBe(
			"SessionRuntime.shutdown called while a run is in progress (agentId=agent_1)",
		);
		expect(error).toBeInstanceOf(Error);
	});

	it("reads sensibly without an agent id", () => {
		expect(new SessionRunInProgressError().message).toBe(
			"SessionRuntime.shutdown called while a run is in progress",
		);
	});
});

