describe("RuntimeEventAdapter — tool lifecycle", () => {
	let adapter: RuntimeEventAdapter;
	beforeEach(() => {
		adapter = new RuntimeEventAdapter();
	});

	it("maps tool-started → content_start(tool) with toolName/toolCallId/input", () => {
		const toolCall = makeToolCall({
			toolCallId: "call_abc",
			toolName: "read_file",
			input: { path: "/tmp/a" },
		});
		const out = adapter.translate({
			type: "tool-started",
			snapshot: makeSnapshot(),
			iteration: 1,
			toolCall,
		});
		expect(out).toEqual([
			{
				type: "content_start",
				contentType: "tool",
				toolName: "read_file",
				toolCallId: "call_abc",
				input: { path: "/tmp/a" },
			},
		]);
	});

	it("maps tool-updated → content_update(tool) with update", () => {
		const toolCall = makeToolCall({ toolCallId: "call_abc" });
		const out = adapter.translate({
			type: "tool-updated",
			snapshot: makeSnapshot(),
			iteration: 1,
			toolCall,
			update: { progress: 0.5 },
		});
		expect(out).toEqual([
			{
				type: "content_update",
				contentType: "tool",
				toolName: "read_file",
				toolCallId: "call_abc",
				update: { progress: 0.5 },
			},
		]);
	});

	it("maps tool-finished with tracked timing → content_end(tool) with durationMs", () => {
		vi.useFakeTimers();
		try {
			vi.setSystemTime(new Date(1_700_000_000_000));
			const toolCall = makeToolCall({ toolCallId: "call_42" });
			adapter.translate({
				type: "tool-started",
				snapshot: makeSnapshot(),
				iteration: 1,
				toolCall,
			});
			vi.advanceTimersByTime(250);
			const out = adapter.translate({
				type: "tool-finished",
				snapshot: makeSnapshot(),
				iteration: 1,
				toolCall,
				message: {
					id: "msg_tool",
					role: "tool",
					createdAt: 1_700_000_000_250,
					content: [
						{
							type: "tool-result",
							toolCallId: "call_42",
							toolName: "read_file",
							output: "file contents here",
						},
					],
				},
			});
			expect(out).toEqual([
				{
					type: "content_end",
					contentType: "tool",
					toolName: "read_file",
					toolCallId: "call_42",
					output: "file contents here",
					error: undefined,
					durationMs: 250,
				},
			]);
		} finally {
			vi.useRealTimers();
		}
	});

	it("populates error on tool-finished when the result is marked isError", () => {
		const toolCall = makeToolCall({ toolCallId: "call_err" });
		adapter.translate({
			type: "tool-started",
			snapshot: makeSnapshot(),
			iteration: 1,
			toolCall,
		});
		const out = adapter.translate({
			type: "tool-finished",
			snapshot: makeSnapshot(),
			iteration: 1,
			toolCall,
			message: {
				id: "msg_err",
				role: "tool",
				createdAt: 0,
				content: [
					{
						type: "tool-result",
						toolCallId: "call_err",
						toolName: "read_file",
						output: "file not found",
						isError: true,
					},
				],
			},
		});
		expect(out[0]).toMatchObject({
			type: "content_end",
			contentType: "tool",
			error: "file not found",
		});
	});

	it("reports durationMs:undefined when tool-started was never seen", () => {
		const toolCall = makeToolCall({ toolCallId: "call_orphan" });
		const out = adapter.translate({
			type: "tool-finished",
			snapshot: makeSnapshot(),
			iteration: 1,
			toolCall,
			message: {
				id: "m",
				role: "tool",
				createdAt: 0,
				content: [
					{
						type: "tool-result",
						toolCallId: "call_orphan",
						toolName: "read_file",
						output: "ok",
					},
				],
			},
		});
		expect(out[0]).toMatchObject({ durationMs: undefined });
	});
});

