describe("RuntimeOAuthTokenManager", () => {
	beforeEach(() => {
		vi.clearAllMocks();
	});

	it("refreshes and persists OpenAI Codex OAuth credentials", async () => {
		const getProviderSettings = vi.fn().mockReturnValue({
			provider: "openai-codex",
			auth: {
				accessToken: "access-old",
				refreshToken: "refresh-old",
				expiresAt: Date.now() - 1_000,
				accountId: "acct-old",
			},
		});
		const saveProviderSettings = vi.fn();

		getValidOpenAICodexCredentials.mockResolvedValueOnce({
			access: "access-new",
			refresh: "refresh-new",
			expires: 4_000_000_000_000,
			accountId: "acct-new",
		});

		const manager = new RuntimeOAuthTokenManager({
			providerSettingsManager: {
				getProviderSettings,
				saveProviderSettings,
			} as never,
		});

		const result = await manager.resolveProviderApiKey({
			providerId: "openai-codex",
		});

		expect(result).toMatchObject({
			apiKey: "access-new",
			accountId: "acct-new",
			refreshed: true,
		});
		expect(saveProviderSettings).toHaveBeenCalledWith(
			expect.objectContaining({
				auth: expect.objectContaining({
					accessToken: "access-new",
					refreshToken: "refresh-new",
					accountId: "acct-new",
					expiresAt: 4_000_000_000_000,
				}),
			}),
			{ setLastUsed: false, tokenSource: "oauth" },
		);
	});

	it("resolves ClinePass OAuth using Cline storage and WorkOS formatting", async () => {
		const getProviderSettings = vi.fn().mockReturnValue({
			provider: "cline",
			baseUrl: "https://api.cline.test",
			auth: {
				accessToken: "workos:access-old",
				refreshToken: "refresh-old",
				expiresAt: Date.now() - 1_000,
				accountId: "acct-old",
			},
		});
		const saveProviderSettings = vi.fn();

		getValidClineCredentials.mockResolvedValueOnce({
			access: "access-new",
			refresh: "refresh-new",
			expires: 4_000_000_000_000,
			accountId: "acct-new",
		});

		const manager = new RuntimeOAuthTokenManager({
			providerSettingsManager: {
				getProviderSettings,
				saveProviderSettings,
			} as never,
		});

		const result = await manager.resolveProviderApiKey({
			providerId: "cline-pass",
		});

		expect(getProviderSettings).toHaveBeenCalledWith("cline");
		expect(getValidClineCredentials).toHaveBeenCalledWith(
			expect.objectContaining({
				access: "access-old",
				refresh: "refresh-old",
			}),
			expect.objectContaining({ apiBaseUrl: "https://api.cline.test" }),
			{ forceRefresh: false },
		);
		expect(result).toMatchObject({
			apiKey: "workos:access-new",
			accountId: "acct-new",
			refreshed: true,
		});
		expect(saveProviderSettings).toHaveBeenCalledWith(
			expect.objectContaining({
				provider: "cline",
				auth: expect.objectContaining({
					accessToken: "workos:access-new",
					refreshToken: "refresh-new",
					accountId: "acct-new",
					expiresAt: 4_000_000_000_000,
				}),
			}),
			{ setLastUsed: false, tokenSource: "oauth" },
		);
	});

	it("throws re-auth required when refresh returns null", async () => {
		getValidOpenAICodexCredentials.mockResolvedValueOnce(null);
		const manager = new RuntimeOAuthTokenManager({
			providerSettingsManager: {
				getProviderSettings: vi.fn().mockReturnValue({
					provider: "openai-codex",
					auth: {
						accessToken: "access-old",
						refreshToken: "refresh-old",
						expiresAt: Date.now() - 1_000,
					},
				}),
				saveProviderSettings: vi.fn(),
			} as never,
		});

		await expect(
			manager.resolveProviderApiKey({ providerId: "openai-codex" }),
		).rejects.toBeInstanceOf(OAuthReauthRequiredError);
	});

	it("de-duplicates concurrent refresh calls per provider", async () => {
		const refreshBarrier = Promise.resolve().then(() => ({
			access: "access-new",
			refresh: "refresh-new",
			expires: Date.now() + 60_000,
		}));
		getValidOpenAICodexCredentials.mockImplementationOnce(
			async () => refreshBarrier,
		);

		const manager = new RuntimeOAuthTokenManager({
			providerSettingsManager: {
				getProviderSettings: vi.fn().mockReturnValue({
					provider: "openai-codex",
					auth: {
						accessToken: "access-old",
						refreshToken: "refresh-old",
						expiresAt: Date.now() - 1_000,
					},
				}),
				saveProviderSettings: vi.fn(),
			} as never,
		});

		const [first, second] = await Promise.all([
			manager.resolveProviderApiKey({ providerId: "openai-codex" }),
			manager.resolveProviderApiKey({ providerId: "openai-codex" }),
		]);

		expect(first?.apiKey).toBe("access-new");
		expect(second?.apiKey).toBe("access-new");
		expect(getValidOpenAICodexCredentials).toHaveBeenCalledTimes(1);
	});
});

import type { ITelemetryService } from "@cline/shared";
import { hashSecret, sdkDebug } from "../../logging/early-logger";
import {
	getProviderAuthHandler,
	getProviderOAuthCredentialsFromSettings,
	saveProviderOAuthCredentials,
} from "../../auth/provider-auth-registry";
import { ProviderSettingsManager } from "../../services/storage/provider-settings-manager";
import type { ProviderSettings } from "../../types/provider-settings";

type ManagedOAuthProviderId = string;

function authSettingsEqual(
	a: ProviderSettings["auth"] | undefined,
	b: ProviderSettings["auth"] | undefined,
): boolean {
	const aExpiry = (
		a as (ProviderSettings["auth"] & { expiresAt?: number }) | undefined
	)?.expiresAt;
	const bExpiry = (
		b as (ProviderSettings["auth"] & { expiresAt?: number }) | undefined
	)?.expiresAt;
	return (
		a?.accessToken === b?.accessToken &&
		a?.refreshToken === b?.refreshToken &&
		a?.accountId === b?.accountId &&
		aExpiry === bExpiry
	);
}

export class OAuthReauthRequiredError extends Error {
	public readonly providerId: ManagedOAuthProviderId;

	constructor(providerId: ManagedOAuthProviderId) {
		super(
			`OAuth credentials for provider "${providerId}" are no longer valid. Re-run authentication for this provider.`,
		);
		this.name = "OAuthReauthRequiredError";
		this.providerId = providerId;
	}
}

export type RuntimeOAuthResolution = {
	apiKey: string;
	accountId?: string;
	refreshed: boolean;
};

export class RuntimeOAuthTokenManager {
	private readonly providerSettingsManager: ProviderSettingsManager;
	private readonly telemetry?: ITelemetryService;
	private readonly refreshInFlight = new Map<
		ManagedOAuthProviderId,
		Promise<RuntimeOAuthResolution | null>
	>();

	constructor(options?: {
		providerSettingsManager?: ProviderSettingsManager;
		telemetry?: ITelemetryService;
	}) {
		this.providerSettingsManager =
			options?.providerSettingsManager ?? new ProviderSettingsManager();
		this.telemetry = options?.telemetry;
	}

	public async resolveProviderApiKey(input: {
		providerId: string;
		forceRefresh?: boolean;
	}): Promise<RuntimeOAuthResolution | null> {
		const handler = getProviderAuthHandler(input.providerId);
		if (!handler) {
			return null;
		}
		return this.resolveWithSingleFlight(
			handler.providerId,
			handler.storageProviderId,
			input.forceRefresh,
		);
	}

	private async resolveWithSingleFlight(
		providerId: ManagedOAuthProviderId,
		storageProviderId: ManagedOAuthProviderId,
		forceRefresh = false,
	): Promise<RuntimeOAuthResolution | null> {
		const currentInFlight = this.refreshInFlight.get(storageProviderId);
		if (currentInFlight) {
			return currentInFlight;
		}
		const pending = this.resolveProviderApiKeyInternal(
			providerId,
			storageProviderId,
			forceRefresh,
		)
			.catch((error) => {
				throw error;
			})
			.finally(() => {
				this.refreshInFlight.delete(storageProviderId);
			});
		this.refreshInFlight.set(storageProviderId, pending);
		return pending;
	}

	private async resolveProviderApiKeyInternal(
		providerId: ManagedOAuthProviderId,
		storageProviderId: ManagedOAuthProviderId,
		forceRefresh: boolean,
	): Promise<RuntimeOAuthResolution | null> {
		const handler = getProviderAuthHandler(providerId);
		if (!handler) {
			return null;
		}
		const settings =
			this.providerSettingsManager.getProviderSettings(storageProviderId);
		if (!settings) {
			sdkDebug(
				`oauth.resolve providerId=${providerId} storageProviderId=${storageProviderId} outcome=no_settings`,
			);
			return null;
		}

		const currentCredentials = getProviderOAuthCredentialsFromSettings(
			providerId,
			settings,
		);
		if (!currentCredentials) {
			sdkDebug(
				`oauth.resolve providerId=${providerId} storageProviderId=${storageProviderId} outcome=no_credentials`,
			);
			return null;
		}

		sdkDebug(
			`oauth.resolve.start providerId=${providerId} storageProviderId=${storageProviderId} forceRefresh=${forceRefresh} accessTokenHash=${hashSecret(currentCredentials.access)} refreshTokenHash=${hashSecret(currentCredentials.refresh)}`,
		);

		const nextCredentials = await handler.refresh({
			settings,
			credentials: currentCredentials,
			forceRefresh,
			telemetry: this.telemetry,
		});
		if (!nextCredentials) {
			sdkDebug(
				`oauth.resolve providerId=${providerId} outcome=refresh_returned_null`,
			);
			throw new OAuthReauthRequiredError(providerId);
		}

		const nextSettings: ProviderSettings = saveProviderOAuthCredentials({
			manager: this.providerSettingsManager,
			providerId,
			settings,
			credentials: nextCredentials,
			setLastUsed: false,
			save: false,
		});
		const wasRefreshed = !authSettingsEqual(settings.auth, nextSettings.auth);
		if (wasRefreshed) {
			sdkDebug(
				`oauth.resolve.refreshed providerId=${providerId} newAccessTokenHash=${hashSecret(nextCredentials.access)} newRefreshTokenHash=${hashSecret(nextCredentials.refresh)} savingToDisk=true`,
			);
			this.providerSettingsManager.saveProviderSettings(nextSettings, {
				setLastUsed: false,
				tokenSource: "oauth",
			});
		} else {
			sdkDebug(`oauth.resolve providerId=${providerId} outcome=not_refreshed`);
		}

		return {
			apiKey: handler.getApiKey(nextSettings) ?? nextCredentials.access,
			accountId: nextCredentials.accountId,
			refreshed: wasRefreshed,
		};
	}
}

import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import type { AgentTool } from "@cline/shared";
import { setClineDir, setHomeDir } from "@cline/shared/storage";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { createBuiltinTools } from "../../extensions/tools";
import { DefaultRuntimeBuilder } from "./runtime-builder";

type LegacyConfig = {
	providerId: string;
	modelId: string;
	apiKey: string;
	systemPrompt: string;
	cwd: string;
	enableTools: boolean;
	enableSpawnAgent: boolean;
	enableAgentTeams: boolean;
};

function legacyBuiltinTools(cwd: string): AgentTool[] {
	return createBuiltinTools({
		cwd,
		enableReadFiles: true,
		enableSearch: true,
		enableBash: true,
		enableWebFetch: true,
	});
}

function legacyBuildRuntimeEnvironment(
	config: LegacyConfig,
	createSpawnTool?: () => AgentTool,
): AgentTool[] {
	const tools: AgentTool[] = [];
	if (config.enableTools) {
		tools.push(...legacyBuiltinTools(config.cwd));
	}
	if (config.enableSpawnAgent && createSpawnTool) {
		const spawnTool = createSpawnTool();
		tools.push({
			...spawnTool,
			execute: async (input, context) => spawnTool.execute(input, context),
		});
	}
	return tools;
}

function normalizeParityToolNames(toolNames: string[]): string[] {
	// Skills are discovered from user/workspace config and can appear in tests
	// depending on the machine state. MCP tools may also be configured outside
	// the test workspace. They are intentionally excluded from strict legacy
	// parity checks.
	return toolNames.filter(
		(toolName) => toolName !== "skills" && !toolName.includes("__"),
	);
}

function makeEmptyWorkspaceCwd(): string {
	return mkdtempSync(join(tmpdir(), "runtime-parity-"));
}

function makeSpawnTool(): AgentTool {
	return {
		name: "spawn_agent",
		description: "Spawn a subagent",
		inputSchema: { type: "object", properties: {}, required: [] },
		execute: async () => ({ ok: true }),
	};
}

describe("runtime tool parity", () => {
	const envSnapshot = {
		HOME: process.env.HOME,
		CLINE_DIR: process.env.CLINE_DIR,
	};
	let isolatedHomeDir = "";

	beforeEach(() => {
		isolatedHomeDir = mkdtempSync(join(tmpdir(), "runtime-parity-home-"));
		process.env.HOME = isolatedHomeDir;
		process.env.CLINE_DIR = join(isolatedHomeDir, ".cline");
		setHomeDir(isolatedHomeDir);
		setClineDir(process.env.CLINE_DIR);
	});

	afterEach(() => {
		process.env.HOME = envSnapshot.HOME;
		process.env.CLINE_DIR = envSnapshot.CLINE_DIR;
		setHomeDir(envSnapshot.HOME ?? "~");
		setClineDir(envSnapshot.CLINE_DIR ?? join("~", ".cline"));
	});

	it("matches legacy tool list when tools+spawn are enabled", async () => {
		const config: LegacyConfig = {
			providerId: "anthropic",
			modelId: "claude-sonnet-4-6",
			apiKey: "key",
			systemPrompt: "test",
			cwd: makeEmptyWorkspaceCwd(),
			enableTools: true,
			enableSpawnAgent: true,
			enableAgentTeams: false,
		};
		const createSpawnTool = makeSpawnTool;
		const expected = normalizeParityToolNames(
			legacyBuildRuntimeEnvironment(config, createSpawnTool).map(
				(tool) => tool.name,
			),
		);
		const runtime = await new DefaultRuntimeBuilder().build({
			config,
			createSpawnTool,
		});
		const actual = runtime.tools.map((tool) => tool.name);

		expect(normalizeParityToolNames(actual)).toEqual(expected);
	});

	it("matches legacy tool list when only spawn is enabled", async () => {
		const config: LegacyConfig = {
			providerId: "anthropic",
			modelId: "claude-sonnet-4-6",
			apiKey: "key",
			systemPrompt: "test",
			cwd: makeEmptyWorkspaceCwd(),
			enableTools: false,
			enableSpawnAgent: true,
			enableAgentTeams: false,
		};
		const createSpawnTool = makeSpawnTool;
		const expected = normalizeParityToolNames(
			legacyBuildRuntimeEnvironment(config, createSpawnTool).map(
				(tool) => tool.name,
			),
		);
		const runtime = await new DefaultRuntimeBuilder().build({
			config,
			createSpawnTool,
		});
		const actual = runtime.tools.map((tool) => tool.name);

		expect(normalizeParityToolNames(actual)).toEqual(expected);
	});

	it("matches legacy tool list when tools+spawn are disabled", async () => {
		const config: LegacyConfig = {
			providerId: "anthropic",
			modelId: "claude-sonnet-4-6",
			apiKey: "key",
			systemPrompt: "test",
			cwd: makeEmptyWorkspaceCwd(),
			enableTools: false,
			enableSpawnAgent: false,
			enableAgentTeams: false,
		};
		const expected = normalizeParityToolNames(
			legacyBuildRuntimeEnvironment(config).map((tool) => tool.name),
		);
		const runtime = await new DefaultRuntimeBuilder().build({ config });
		const actual = runtime.tools.map((tool) => tool.name);

		expect(normalizeParityToolNames(actual)).toEqual(expected);
	});
});

/**
 * Unit tests for the new `SessionRuntime` orchestrator (PLAN.md
 * Step 8d).
 *
 * Scope:
 *  - constructor wires every state owner (conversation store, mistake
 *    tracker, loop detector, hook bridge, event adapter) correctly;
 *  - `run()` drives the injected `AgentRuntime` and fans adapted
 *    legacy `AgentEvent`s to subscribers;
 *  - `abort()` forwards into the active runtime;
 *  - `subscribeEvents` delivers **legacy** `AgentEvent` shapes;
 *  - `addTools` / `updateConnection` / `clearHistory` / `restore`
 *    mutate state;
 *  - `canStartRun` / `shutdown` guards enforce the lifecycle rules.
 */

