						createdAt: 2,
					},
					{
						id: "m2",
						role: "tool",
						content: [
							{
								type: "tool-result",
								toolCallId: "t1",
								toolName: "read_files",
								output: JSON.stringify([
									{ path: "src/a.ts", result: staleRead },
								]),
							},
						],
						createdAt: 3,
					},
					{
						id: "m3",
						role: "assistant",
						content: [
							{
								type: "tool-call",
								toolCallId: "t2",
								toolName: "read_files",
								input: { files: [{ path: "src/a.ts" }] },
							},
						],
						createdAt: 4,
					},
					{
						id: "m4",
						role: "tool",
						content: [
							{
								type: "tool-result",
								toolCallId: "t2",
								toolName: "read_files",
								output: JSON.stringify([
									{ path: "src/a.ts", result: latestRead },
								]),
							},
						],
						createdAt: 5,
					},
				],
				tools: [],
			},
		});
		expect(JSON.stringify(beforeRestore?.messages?.[2])).toContain("outdated");

		session.restore([]);
		const afterRestore = await beforeModel({
			snapshot: makeSnapshot(),
			request: {
				systemPrompt: "system",
				messages: [
					{
						id: "r1",
						role: "assistant",
						content: [
