								toolName: "read_files",
								output: JSON.stringify([
									{ path: "src/a.ts", result: staleRead },
								]),
							},
						],
						createdAt: 7,
					},
				],
				tools: [],
			},
		});

		expect(JSON.stringify(afterRestore?.messages)).not.toContain("outdated");
		expect(JSON.stringify(afterRestore?.messages)).toContain(
			"export const x = 1;",
		);
	});
