describe("SubprocessSandbox call", () => {
	it("rejects non-serializable payloads without arming the timeout shutdown", async () => {
		const sandbox = new SubprocessSandbox({
			name: "sandbox-serialization-test",
			// Echo server; the "slow" method answers after a delay so a call can
			// be held in flight while the failed send's timeout window elapses.
			bootstrapScript: [
				"process.on('message', (m) => {",
				"  if (!m || m.type !== 'call') return;",
				"  const reply = () => process.send({ type: 'response', id: m.id, ok: true, result: m.args });",
				"  if (m.method === 'slow') { setTimeout(reply, 800); } else { reply(); }",
				"});",
			].join("\n"),
		});
		try {
			const cyclic: Record<string, unknown> = {};
			cyclic.self = cyclic;

			const slowCall = sandbox.call("slow", { ok: true }, { timeoutMs: 5000 });

			// send() throws synchronously for cyclic payloads. Before the fix the
			// pending timeout timer survived the rejection and fired ~250 ms
			// later, shutting the sandbox down and killing the in-flight slow
			// call above.
			await expect(
				sandbox.call("echo", cyclic, { timeoutMs: 250 }),
			).rejects.toThrow(/cyclic|circular/i);

			await expect(slowCall).resolves.toEqual({ ok: true });
		} finally {
			await sandbox.shutdown();
		}
	}, 20_000);
});

import { type ChildProcess, spawn } from "node:child_process";
import { basename } from "node:path";
import {
	augmentNodeCommandForDebug,
	withResolvedClineBuildEnv,
} from "@cline/shared";

interface SandboxCallMessage {
	type: "call";
	id: string;
	method: string;
	args: unknown;
}

interface SandboxResponseMessage {
	type: "response";
	id: string;
	ok: boolean;
	result?: unknown;
	error?: { message: string; stack?: string };
}

interface SandboxEventMessage {
	type: "event";
	name: string;
	payload?: unknown;
}

export interface SubprocessSandboxOptions {
	/** Inline script to execute via `node -e`. Mutually exclusive with {@link bootstrapFile}. */
	bootstrapScript?: string;
	/** Path to a JavaScript file to execute via `node <file>`. Mutually exclusive with {@link bootstrapScript}. */
	bootstrapFile?: string;
	/** Runtime executable for internal JavaScript helpers. Defaults to node/bun instead of packaged CLI binaries. */
	runtimeExecutable?: string;
	name?: string;
	onEvent?: (event: { name: string; payload?: unknown }) => void;
}

export interface SandboxCallOptions {
	timeoutMs?: number;
}

type PendingRequest = {
	resolve: (value: unknown) => void;
	reject: (error: Error) => void;
	timeout?: NodeJS.Timeout;
};

function asError(value: unknown): Error {
	if (value instanceof Error) {
		return value;
	}
	return new Error(String(value));
}

export const CLINE_JS_RUNTIME_PATH_ENV = "CLINE_JS_RUNTIME_PATH";

function isRuntimeExecutable(value: string | undefined): boolean {
	const trimmed = value?.trim();
	if (!trimmed) {
		return false;
	}
	const name = basename(trimmed).toLowerCase();
	return (
		name === "node" ||
		name === "node.exe" ||
		name === "bun" ||
		name === "bun.exe"
	);
}

export function resolveSubprocessRuntimeExecutable(
	options: {
		env?: NodeJS.ProcessEnv;
		execPath?: string;
		runtimeExecutable?: string;
	} = {},
): string {
	const env = options.env ?? process.env;
	const explicit =
		options.runtimeExecutable?.trim() || env[CLINE_JS_RUNTIME_PATH_ENV]?.trim();
	if (explicit) {
		return explicit;
	}

	const execPath = options.execPath?.trim() || process.execPath;
	if (isRuntimeExecutable(execPath)) {
		return execPath;
	}

	for (const candidate of [
		env.BUN_EXEC_PATH,
		env.npm_node_execpath,
		env.NODE,
	]) {
		const trimmed = candidate?.trim();
		if (trimmed && isRuntimeExecutable(trimmed)) {
			return trimmed;
		}
	}

	return "node";
}

export function buildSubprocessSandboxCommand(
	args: string[],
	options: {
		env?: NodeJS.ProcessEnv;
		execArgv?: string[];
		name?: string;
		execPath?: string;
		runtimeExecutable?: string;
	} = {},
): string[] {
	const runtimeExecutable = resolveSubprocessRuntimeExecutable({
		env: options.env,
		execPath: options.execPath,
		runtimeExecutable: options.runtimeExecutable,
	});
	return augmentNodeCommandForDebug([runtimeExecutable, ...args], {
		env: options.env,
		execArgv: options.execArgv,
		debugRole: options.name === "plugin-sandbox" ? "plugin-sandbox" : "sandbox",
	});
}

export class SubprocessSandbox {
	private readonly options: SubprocessSandboxOptions;
	private process: ChildProcess | null = null;
	private requestCounter = 0;
	private readonly pending = new Map<string, PendingRequest>();

	constructor(options: SubprocessSandboxOptions) {
		this.options = options;
	}

	private get processLabel(): string {
		return this.options.name ?? "sandbox";
	}

	private clearPendingRequest(id: string): PendingRequest | undefined {
		const pending = this.pending.get(id);
		if (!pending) {
			return undefined;
		}
		this.pending.delete(id);
		if (pending.timeout) {
			clearTimeout(pending.timeout);
		}
		return pending;
	}

	start(): void {
		if (this.process && this.process.exitCode === null) {
			return;
		}

		const args = this.options.bootstrapFile
			? [this.options.bootstrapFile]
			: ["-e", this.options.bootstrapScript ?? ""];

		const command = buildSubprocessSandboxCommand(args, {
			name: this.options.name,
			runtimeExecutable: this.options.runtimeExecutable,
		});
		const child = spawn(
			command[0] ?? resolveSubprocessRuntimeExecutable(this.options),
			command.slice(1),
			{
				stdio: ["ignore", "ignore", "pipe", "ipc"],
				env: withResolvedClineBuildEnv(process.env),
				// Prevent a console window from flashing on Windows.
				windowsHide: true,
			},
		);
		this.process = child;
		let stderrBuffer = "";
		const appendStderr = (chunk: string) => {
			const next = stderrBuffer + chunk;
			// Keep only a small tail so errors include useful context
			// without unbounded memory growth.
			stderrBuffer = next.length > 4000 ? next.slice(-4000) : next;
		};
		child.stderr?.setEncoding("utf8");
		child.stderr?.on("data", (chunk: string) => {
			appendStderr(chunk);
		});
		child.on("message", (message) => {
			this.onMessage(message as SandboxResponseMessage | SandboxEventMessage);
		});
		child.on("error", (error) => {
			this.failPending(
				new Error(
					`${this.processLabel} process error: ${asError(error).message}`,
				),
			);
		});
		child.on("exit", (code, signal) => {
			this.process = null;
			const stderrDetail = stderrBuffer.trim();
			this.failPending(
				new Error(
					`${this.options.name ?? "sandbox"} process exited (code=${String(code)}, signal=${String(signal)})${stderrDetail ? `: ${stderrDetail}` : ""}`,
				),
			);
		});
	}

	async call<TResult = unknown>(
		method: string,
		args: unknown,
		options: SandboxCallOptions = {},
	): Promise<TResult> {
		this.start();
		const child = this.process;
		if (!child || child.exitCode !== null) {
			throw new Error(`${this.processLabel} process is not available`);
		}

		const id = `req_${++this.requestCounter}`;
		const message: SandboxCallMessage = {
			type: "call",
			id,
			method,
			args,
		};

		return await new Promise<TResult>((resolve, reject) => {
			const pending: PendingRequest = {
				resolve: (value) => resolve(value as TResult),
				reject,
			};
			if ((options.timeoutMs ?? 0) > 0) {
				pending.timeout = setTimeout(() => {
					this.clearPendingRequest(id);
					this.shutdown().catch(() => {
						// Best-effort process shutdown after timeout.
					});
					reject(
						new Error(
							`${this.processLabel} call timed out after ${options.timeoutMs}ms: ${method}`,
						),
					);
				}, options.timeoutMs);
			}
			this.pending.set(id, pending);
			try {
				child.send(message, (error) => {
					if (!error) {
						return;
					}
					const entry = this.clearPendingRequest(id);
					if (!entry) {
						return;
					}
					entry.reject(
						new Error(
							`${this.processLabel} failed to send call "${method}": ${asError(error).message}`,
						),
					);
				});
			} catch (error) {
				// send() throws synchronously when the message is not
				// serializable (e.g. cyclic structures). Cancel the pending
				// entry so the timeout timer above never fires — otherwise it
				// would shut down the sandbox process out from under unrelated
				// in-flight calls. Reject with the original error so callers
				// can classify it (see isSerializationError in plugin-sandbox).
				this.clearPendingRequest(id);
				reject(asError(error));
			}
		});
	}

	async shutdown(): Promise<void> {
		const child = this.process;
		this.process = null;
		if (!child || child.exitCode !== null) {
			this.failPending(new Error(`${this.processLabel} shutdown`));
			return;
		}
		await new Promise<void>((resolve) => {
			const timeout = setTimeout(() => {
				try {
					child.kill("SIGKILL");
				} catch {
					// Ignore kill failures.
				}
				resolve();
			}, 300);
			child.once("exit", () => {
				clearTimeout(timeout);
				resolve();
			});
			try {
				child.kill("SIGTERM");
			} catch {
				clearTimeout(timeout);
				resolve();
			}
		});
		this.failPending(new Error(`${this.processLabel} shutdown`));
	}

	private onMessage(
		message: SandboxResponseMessage | SandboxEventMessage,
	): void {
		if (!message) {
			return;
		}
		if (message.type === "event") {
			if (typeof message.name === "string" && message.name.length > 0) {
				this.options.onEvent?.({
					name: message.name,
					payload: message.payload,
				});
			}
			return;
		}
		if (message.type !== "response" || !message.id) {
			return;
		}
		const pending = this.clearPendingRequest(message.id);
		if (!pending) {
			return;
		}
		if (message.ok) {
			pending.resolve(message.result);
			return;
		}
		pending.reject(
			new Error(message.error?.message || `${this.processLabel} call failed`),
		);
	}

	private failPending(error: Error): void {
		for (const [id, pending] of this.pending.entries()) {
			this.pending.delete(id);
			if (pending.timeout) {
				clearTimeout(pending.timeout);
			}
			pending.reject(error);
		}
	}
}

import { mkdir, readFile, unlink, writeFile } from "node:fs/promises";
import { join } from "node:path";
import type { ToolApprovalRequest, ToolApprovalResult } from "@cline/shared";

export type DesktopToolApprovalOptions = {
	approvalDir?: string;
	sessionId?: string;
	timeoutMs?: number;
	pollIntervalMs?: number;
	nowIso?: () => string;
};

function sanitizeApprovalToken(value: string): string {
	return value.replace(/[^a-zA-Z0-9._-]+/g, "_");
}

function delay(ms: number): Promise<void> {
	return new Promise((resolve) => setTimeout(resolve, ms));
}

async function unlinkIfPresent(path: string): Promise<void> {
	try {
		await unlink(path);
	} catch {
		// Best-effort cleanup.
	}
}

export async function requestDesktopToolApproval(
	request: ToolApprovalRequest,
	options: DesktopToolApprovalOptions = {},
): Promise<ToolApprovalResult> {
	const approvalDir = options.approvalDir?.trim();
	const sessionId = options.sessionId?.trim();
	if (!approvalDir || !sessionId) {
		return {
			approved: false,
			reason: "Desktop tool approval IPC is not configured",
		};
	}

	await mkdir(approvalDir, { recursive: true });
	const requestId = sanitizeApprovalToken(`${request.toolCallId}`);
	const requestPath = join(
		approvalDir,
		`${sessionId}.request.${requestId}.json`,
	);
	const decisionPath = join(
		approvalDir,
		`${sessionId}.decision.${requestId}.json`,
	);
	const nowIso = options.nowIso ?? (() => new Date().toISOString());

	await writeFile(
		requestPath,
		`${JSON.stringify(
			{
				requestId,
				sessionId,
				createdAt: nowIso(),
				toolCallId: request.toolCallId,
				toolName: request.toolName,
				input: request.input,
				iteration: request.iteration,
				agentId: request.agentId,
				conversationId: request.conversationId,
			},
			null,
			2,
		)}\n`,
		"utf8",
	);

	const timeoutMs = options.timeoutMs ?? 5 * 60_000;
	const pollIntervalMs = options.pollIntervalMs ?? 200;
	const startedAt = Date.now();
	while (Date.now() - startedAt < timeoutMs) {
		try {
			const raw = await readFile(decisionPath, "utf8");
			const parsed = JSON.parse(raw) as {
				approved?: boolean;
				reason?: string;
			};
			const result = {
				approved: parsed.approved === true,
				reason: typeof parsed.reason === "string" ? parsed.reason : undefined,
			};
			await Promise.all([
				unlinkIfPresent(decisionPath),
				unlinkIfPresent(requestPath),
			]);
			return result;
		} catch {
			// Decision not available yet.
		}
		await delay(pollIntervalMs);
	}

	await unlinkIfPresent(requestPath);

	return { approved: false, reason: "Tool approval request timed out" };
}

import { describe, expect, it, vi } from "vitest";
import type { CoreSessionEvent } from "../../types/events";
import type { ActiveSession } from "../../types/session";
import {
	type PendingPromptQueueState,
	PendingPromptService,
	PendingPromptsController,
} from "./pending-prompt-service";

function createState(): PendingPromptQueueState {
	return { pendingPrompts: [] };
}

describe("PendingPromptService", () => {
	it("deduplicates prompts and prioritizes steer delivery", () => {
		const service = new PendingPromptService();
		const state = createState();

		service.enqueue(state, { prompt: "first", delivery: "queue" });
		service.enqueue(state, { prompt: "second", delivery: "queue" });
		service.enqueue(state, { prompt: "first", delivery: "steer" });

		expect(
			service.list(state).map(({ prompt, delivery }) => ({ prompt, delivery })),
		).toEqual([
			{ prompt: "first", delivery: "steer" },
			{ prompt: "second", delivery: "queue" },
		]);
		expect(state.pendingPrompts).toHaveLength(2);
	});

	it("updates prompts and reorders when delivery changes", () => {
		const service = new PendingPromptService();
		const state = createState();

		service.enqueue(state, { prompt: "first", delivery: "queue" });
		service.enqueue(state, { prompt: "second", delivery: "queue" });
		const queued = service.list(state);

		const edited = service.update(state, {
			sessionId: "sess-1",
			promptId: queued[0]?.id,
			prompt: "edited first",
		});
		expect(edited.updated).toBe(true);
		expect(edited.prompts.map((prompt) => prompt.prompt)).toEqual([
			"edited first",
			"second",
		]);

		const steered = service.update(state, {
			sessionId: "sess-1",
			promptId: queued[1]?.id,
			delivery: "steer",
		});
		expect(
			steered.prompts.map(({ prompt, delivery }) => ({ prompt, delivery })),
		).toEqual([
			{ prompt: "second", delivery: "steer" },
			{ prompt: "edited first", delivery: "queue" },
		]);
	});

	it("consumes steer prompts before queued turns", () => {
		const service = new PendingPromptService();
		const state = createState();

		service.enqueue(state, { prompt: "queued", delivery: "queue" });
		service.enqueue(state, { prompt: "steered", delivery: "steer" });

		const steered = service.consumeSteer(state);
		expect(steered.entry?.prompt).toBe("steered");
		expect(steered.prompts.map((prompt) => prompt.prompt)).toEqual(["queued"]);

		const queued = service.shiftNext(state);
		expect(queued.entry?.prompt).toBe("queued");
		expect(queued.prompts).toEqual([]);
	});

	it("deletes prompts and reports missing prompts without mutation", () => {
		const service = new PendingPromptService();
		const state = createState();

		service.enqueue(state, { prompt: "keep", delivery: "queue" });
		service.enqueue(state, { prompt: "remove", delivery: "queue" });
		const removeId = service.list(state)[1]?.id;

		const missing = service.delete(state, {
			sessionId: "sess-1",
			promptId: "missing",
		});
		expect(missing.removed).toBe(false);
		expect(missing.prompts.map((prompt) => prompt.prompt)).toEqual([
			"keep",
			"remove",
		]);

		const removed = service.delete(state, {
			sessionId: "sess-1",
			promptId: removeId,
		});
		expect(removed.removed).toBe(true);
		expect(removed.prompt?.prompt).toBe("remove");
		expect(removed.prompts.map((prompt) => prompt.prompt)).toEqual(["keep"]);
	});

	it("normalizes edited prompt text and rejects empty prompts", () => {
		const service = new PendingPromptService();
		const state = createState();

		service.enqueue(state, { prompt: "first", delivery: "queue" });
		const queued = service.list(state);

		expect(() =>
			service.update(state, {
				sessionId: "sess-1",
				promptId: queued[0]?.id,
				prompt: "   ",
			}),
		).toThrow("prompt cannot be empty");
	});

	it("requeues a drained prompt when send fails", async () => {
		const sessionId = "sess-drain-failure";
		const session = {
			sessionId,
			pendingPrompts: [
				{
					id: "pending-1",
					prompt: "try later",
					delivery: "steer",
				},
			],
			aborting: false,
			drainingPendingPrompts: false,
			status: "completed",
			agent: {
				canStartRun: () => true,
			},
		} as unknown as ActiveSession;
		const events: CoreSessionEvent[] = [];
		const controller = new PendingPromptsController({
			getSession: () => session,
			emit: (event) => events.push(event),
			send: vi.fn().mockRejectedValue(new Error("send failed")),
		});

		await controller.drain(sessionId);

		expect(controller.list(sessionId).map((prompt) => prompt.prompt)).toEqual([
			"try later",
		]);
		expect(
			events.some(
				(event) =>
					event.type === "pending_prompts" &&
					event.payload.prompts.length === 0,
			),
		).toBe(true);
		expect(
			events.some(
				(event) =>
					event.type === "pending_prompts" &&
					event.payload.prompts.some((prompt) => prompt.prompt === "try later"),
			),
		).toBe(true);
	});
});

import { type AgentMode, normalizeUserInput } from "@cline/shared";
import { nanoid } from "nanoid";
import type {
	CoreSessionEvent,
	SessionPendingPrompt,
} from "../../types/events";
import type { ActiveSession, PendingPrompt } from "../../types/session";
import type {
	PendingPromptMutationResult,
	PendingPromptsDeleteInput,
	PendingPromptsUpdateInput,
} from "../host/runtime-host";

export type PendingPromptDelivery = "queue" | "steer";

export interface PendingPromptEntry {
	id: string;
	prompt: string;
	mode?: AgentMode;
	delivery: PendingPromptDelivery;
	userImages?: string[];
	userFiles?: string[];
}

export interface PendingPromptQueueState {
	pendingPrompts: PendingPromptEntry[];
}

export interface PendingPromptsControllerDeps {
	getSession(sessionId: string): ActiveSession | undefined;
	emit(event: CoreSessionEvent): void;
	send(input: {
		sessionId: string;
		prompt: string;
		mode?: AgentMode;
		userImages?: string[];
		userFiles?: string[];
	}): Promise<unknown>;
}

export interface PendingPromptEnqueueInput {
	prompt: string;
	mode?: AgentMode;
	delivery: PendingPromptDelivery;
	userImages?: string[];
	userFiles?: string[];
}

export interface PendingPromptConsumeResult {
	entry?: PendingPromptEntry;
	prompts: SessionPendingPrompt[];
}

export class PendingPromptService {
	list(state: PendingPromptQueueState | undefined): SessionPendingPrompt[] {
		return state ? snapshotPrompts(state) : [];
	}

	update(
		state: PendingPromptQueueState | undefined,
		input: PendingPromptsUpdateInput,
	): PendingPromptMutationResult {
		if (!state) {
			return { sessionId: input.sessionId, prompts: [], updated: false };
		}
		const promptId = input.promptId.trim();
		const index = state.pendingPrompts.findIndex(
			(entry) => entry.id === promptId,
		);
		if (index < 0) {
			return {
				sessionId: input.sessionId,
				prompts: snapshotPrompts(state),
				updated: false,
			};
		}

		const existing = state.pendingPrompts[index];
		if (!existing) {
			return {
				sessionId: input.sessionId,
				prompts: snapshotPrompts(state),
				updated: false,
			};
		}
		const prompt =
			input.prompt === undefined
				? existing.prompt
				: normalizeUserInput(input.prompt).trim();
		if (!prompt) {
			throw new Error("prompt cannot be empty");
		}
		const delivery = input.delivery ?? existing.delivery;
		const next: PendingPromptEntry = {
			...existing,
			prompt,
			mode: input.mode ?? existing.mode,
			delivery,
		};
		state.pendingPrompts.splice(index, 1);
		insertUpdatedPrompt(state, next, index, existing.delivery);
		return {
			sessionId: input.sessionId,
			prompts: snapshotPrompts(state),
			prompt: snapshotPrompt(next),
			updated: true,
		};
	}

	delete(
		state: PendingPromptQueueState | undefined,
		input: PendingPromptsDeleteInput,
	): PendingPromptMutationResult {
		if (!state) {
			return { sessionId: input.sessionId, prompts: [], removed: false };
		}
		const promptId = input.promptId.trim();
		const index = state.pendingPrompts.findIndex(
			(entry) => entry.id === promptId,
		);
		if (index < 0) {
			return {
				sessionId: input.sessionId,
				prompts: snapshotPrompts(state),
				removed: false,
			};
		}
		const [removed] = state.pendingPrompts.splice(index, 1);
		return {
			sessionId: input.sessionId,
			prompts: snapshotPrompts(state),
			prompt: removed ? snapshotPrompt(removed) : undefined,
			removed: true,
		};
	}

	enqueue(
		state: PendingPromptQueueState,
		input: PendingPromptEnqueueInput,
	): SessionPendingPrompt[] {
		const { prompt, mode, delivery, userImages, userFiles } = input;
		const existingIndex = state.pendingPrompts.findIndex(
			(queued) => queued.prompt === prompt,
		);
		if (existingIndex >= 0) {
			const [existing] = state.pendingPrompts.splice(existingIndex, 1);
			const next: PendingPromptEntry = {
				...existing,
				prompt,
				mode: mode ?? existing.mode,
				userImages: userImages ?? existing.userImages,
				userFiles: userFiles ?? existing.userFiles,
			};
			if (delivery === "steer" || existing.delivery === "steer") {
				state.pendingPrompts.unshift({ ...next, delivery: "steer" });
			} else {
				state.pendingPrompts.push(next);
			}
		} else {
			const newEntry: PendingPromptEntry = {
				id: `pending_${Date.now()}_${nanoid(5)}`,
				prompt,
				mode,
				delivery,
				userImages,
				userFiles,
			};
			if (delivery === "steer") {
				state.pendingPrompts.unshift(newEntry);
			} else {
				state.pendingPrompts.push(newEntry);
			}
		}
		return snapshotPrompts(state);
	}

	consumeSteer(state: PendingPromptQueueState): PendingPromptConsumeResult {
		const steerIndex = state.pendingPrompts.findIndex(
			(entry) => entry.delivery === "steer",
		);
		if (steerIndex < 0) {
			return { prompts: snapshotPrompts(state) };
		}
		const [entry] = state.pendingPrompts.splice(steerIndex, 1);
		return { entry, prompts: snapshotPrompts(state) };
	}

	shiftNext(state: PendingPromptQueueState): PendingPromptConsumeResult {
		const entry = state.pendingPrompts.shift();
		return { entry, prompts: snapshotPrompts(state) };
	}

	requeueFront(
		state: PendingPromptQueueState,
		entry: PendingPromptEntry,
	): SessionPendingPrompt[] {
		state.pendingPrompts.unshift(entry);
		return snapshotPrompts(state);
	}

	clear(state: PendingPromptQueueState): SessionPendingPrompt[] {
		state.pendingPrompts.length = 0;
		return [];
	}
}

export class PendingPromptsController {
	private readonly service = new PendingPromptService();

	constructor(private readonly deps: PendingPromptsControllerDeps) {}

	list(sessionId: string): SessionPendingPrompt[] {
		return this.service.list(this.deps.getSession(sessionId));
	}

	update(input: PendingPromptsUpdateInput): PendingPromptMutationResult {
		const session = this.deps.getSession(input.sessionId);
		if (!session || session.aborting) {
			return { sessionId: input.sessionId, prompts: [], updated: false };
		}
		const result = this.service.update(session, input);
		this.emitPrompts(session);
		this.scheduleDrain(input.sessionId, session);
		return result;
	}

	delete(input: PendingPromptsDeleteInput): PendingPromptMutationResult {
		const session = this.deps.getSession(input.sessionId);
		if (!session || session.aborting) {
			return { sessionId: input.sessionId, prompts: [], removed: false };
		}
		const result = this.service.delete(session, input);
		this.emitPrompts(session);
		this.scheduleDrain(input.sessionId, session);
		return result;
	}

	enqueue(
		sessionId: string,
		entry: {
			prompt: string;
			mode?: AgentMode;
			delivery: "queue" | "steer";
			userImages?: string[];
			userFiles?: string[];
		},
	): void {
		const session = this.deps.getSession(sessionId);
		if (!session || session.aborting) return;
		this.service.enqueue(session, entry);
		this.emitPrompts(session);
		this.scheduleDrain(sessionId, session);
	}

	consumeSteer(sessionId: string): PendingPromptEntry | undefined {
		const session = this.deps.getSession(sessionId);
		if (!session) return undefined;
		const { entry: steer } = this.service.consumeSteer(session);
		if (!steer) return undefined;
		this.emitPrompts(session);
		this.emitSubmitted(session, steer);
		return steer;
	}

	clearAborted(session: ActiveSession): void {
		if (session.pendingPrompts.length === 0) return;
		this.service.clear(session);
		this.emitPrompts(session);
	}

	emitPrompts(session: ActiveSession): void {
		this.deps.emit({
			type: "pending_prompts",
			payload: {
				sessionId: session.sessionId,
				prompts: snapshotPrompts(session),
			},
		});
	}

	scheduleDrain(sessionId: string, session: ActiveSession): void {
		if (
			session.pendingPrompts.length === 0 ||
			session.aborting ||
			session.drainingPendingPrompts ||
			!session.agent.canStartRun()
		) {
			return;
		}
		queueMicrotask(() => {
			void this.drain(sessionId);
		});
	}

	async drain(sessionId: string): Promise<void> {
		const session = this.deps.getSession(sessionId);
		if (!session) return;
		if (session.aborting || session.drainingPendingPrompts) {
			return;
		}
		if (!session.agent.canStartRun()) {
			return;
		}
		const { entry: next } = this.service.shiftNext(session);
		if (!next) return;
		this.emitPrompts(session);
		this.emitSubmitted(session, next);
		session.drainingPendingPrompts = true;
		let continueDrain = true;
		try {
			await this.deps.send({
				sessionId,
				prompt: next.prompt,
				...(next.mode ? { mode: next.mode } : {}),
				userImages: next.userImages,
				userFiles: next.userFiles,
			});
		} catch {
			continueDrain = false;
			this.service.requeueFront(session, next);
			this.emitPrompts(session);
		} finally {
			session.drainingPendingPrompts = false;
			if (
				continueDrain &&
				session.pendingPrompts.length > 0 &&
				session.status !== "failed" &&
				session.status !== "cancelled"
			) {
				queueMicrotask(() => {
					void this.drain(sessionId);
				});
			}
		}
	}

	private emitSubmitted(session: ActiveSession, entry: PendingPrompt): void {
		const prompt = snapshotPrompt(entry);
		this.deps.emit({
			type: "pending_prompt_submitted",
			payload: {
				sessionId: session.sessionId,
				id: prompt.id,
				prompt: prompt.prompt,
				delivery: prompt.delivery,
				attachmentCount: prompt.attachmentCount,
				userImages: prompt.userImages,
				userFiles: prompt.userFiles,
			},
		});
	}
}

function snapshotPrompt(entry: PendingPromptEntry): SessionPendingPrompt {
	return {
		id: entry.id,
		prompt: entry.prompt,
		delivery: entry.delivery,
		attachmentCount:
			(entry.userImages?.length ?? 0) + (entry.userFiles?.length ?? 0),
		userImages: entry.userImages,
		userFiles: entry.userFiles,
	};
}

function snapshotPrompts(
	state: PendingPromptQueueState,
): SessionPendingPrompt[] {
	return state.pendingPrompts.map(snapshotPrompt);
}

function insertUpdatedPrompt(
	state: PendingPromptQueueState,
	next: PendingPromptEntry,
	previousIndex: number,
	previousDelivery: PendingPromptDelivery,
): void {
	if (next.delivery === "steer") {
		state.pendingPrompts.unshift(next);
	} else if (previousDelivery === "steer") {
		state.pendingPrompts.push(next);
	} else {
		state.pendingPrompts.splice(previousIndex, 0, next);
	}
}

import type { AgentEvent } from "@cline/shared";
import type { SessionAccumulatedUsage } from "../runtime/host/runtime-host";
import type { CoreSessionConfig } from "../types/config";
import type { CoreSessionEvent } from "../types/events";
import type { ActiveSession } from "../types/session";
import { serializeAgentEvent } from "./session-data";
import {
	captureConversationTurnEvent,
	captureDiffEditFailure,
	captureSkillUsed,
	captureTokenUsage,
	captureToolUsage,
	type TelemetryAgentIdentityProperties,
} from "./telemetry/core-events";
import {
	accumulateUsageTotals,
	createInitialAccumulatedUsage,
	sumUsageTotals,
} from "./usage";

export function extractSkillNameFromToolInput(
	input: unknown,
): string | undefined {
	if (!input || typeof input !== "object") return undefined;
	const record = input as Record<string, unknown>;
	const skillName = record.skill ?? record.skill_name ?? record.skillName;
	if (typeof skillName !== "string") return undefined;
	const trimmed = skillName.trim();
	return trimmed.length > 0 ? trimmed : undefined;
}

export interface AgentEventContext {
	sessionId: string;
	config: CoreSessionConfig;
	liveSession: ActiveSession | undefined;
	usageBySession: Map<string, SessionAccumulatedUsage>;
	aggregateUsageBySession: Map<string, SessionAccumulatedUsage>;
	persistMessages: (
		sessionId: string,
		messages: unknown[],
		systemPrompt?: string,
	) => void;
	emit: (event: CoreSessionEvent) => void;
}

export interface AgentTelemetryContextOverrides {
	agentId?: string;
	conversationId?: string;
	parentAgentId?: string | null;
	createdByAgentId?: string;
	teamId?: string;
	teamName?: string;
	teamRole?: "lead" | "teammate";
	teamAgentId?: string;
	isPrimaryAgentEvent?: boolean;
}

export function extractAgentEventMetadata(event: AgentEvent): {
	agentId?: string;
	conversationId?: string;
	parentAgentId?: string;
} {
	if (!event || typeof event !== "object") {
		return {};
	}
	const record = event as unknown as Record<string, unknown>;
	return {
		agentId: typeof record.agentId === "string" ? record.agentId : undefined,
		conversationId:
			typeof record.conversationId === "string"
				? record.conversationId
				: undefined,
		parentAgentId:
			typeof record.parentAgentId === "string"
				? record.parentAgentId
				: undefined,
	};
}

export function buildTelemetryAgentIdentity(
	context: AgentTelemetryContextOverrides,
): TelemetryAgentIdentityProperties | undefined {
	const agentId = context.agentId?.trim();
	if (!agentId) {
		return undefined;
	}
	const parentAgentId = context.parentAgentId?.trim() || undefined;
	const teamRole = context.teamRole;
	let agentKind: TelemetryAgentIdentityProperties["agentKind"] = "root";
	if (teamRole === "teammate") {
		agentKind = "team_teammate";
	} else if (teamRole === "lead") {
		agentKind = "team_lead";
	} else if (parentAgentId) {
		agentKind = "subagent";
	}
	return {
		agentId,
		agentKind,
		conversationId: context.conversationId?.trim() || undefined,
		parentAgentId,
		createdByAgentId:
			context.createdByAgentId?.trim() || parentAgentId || undefined,
		isSubagent: Boolean(parentAgentId),
		teamId: context.teamId?.trim() || undefined,
		teamName: context.teamName?.trim() || undefined,
		teamRole,
		teamAgentId: context.teamAgentId?.trim() || undefined,
	};
}

function usageDeltaFromEvent(event: Extract<AgentEvent, { type: "usage" }>) {
	return {
		inputTokens: event.inputTokens,
		outputTokens: event.outputTokens,
		cacheWriteTokens: event.cacheWriteTokens,
		cacheReadTokens: event.cacheReadTokens,
		totalCost: event.cost,
	};
}

function resolveUsageAgentKey(input: {
	isPrimaryAgentEvent: boolean;
	overrides?: AgentTelemetryContextOverrides;
	eventMetadata: ReturnType<typeof extractAgentEventMetadata>;
}): string {
	const candidates = input.isPrimaryAgentEvent
		? [
				input.overrides?.agentId,
				input.eventMetadata.agentId,
				input.overrides?.teamAgentId,
			]
		: [
				input.overrides?.teamAgentId,
				input.overrides?.agentId,
				input.eventMetadata.agentId,
				input.eventMetadata.conversationId,
			];
	for (const candidate of candidates) {
		const value = candidate?.trim();
		if (value) return value;
	}
	return input.isPrimaryAgentEvent ? "root" : "unknown";
}

export function handleAgentEvent(
	ctx: AgentEventContext,
	event: AgentEvent,
	overrides?: AgentTelemetryContextOverrides,
): void {
	const { sessionId, config, liveSession, emit } = ctx;
	const telemetry = config.telemetry;
	const teamRuntime = liveSession?.runtime.teamRuntime;
	const isPrimaryAgentEvent = overrides?.isPrimaryAgentEvent ?? true;
	const eventMetadata = extractAgentEventMetadata(event);
	const agentIdentity = buildTelemetryAgentIdentity({
		agentId: overrides?.agentId ?? eventMetadata.agentId,
		conversationId: overrides?.conversationId ?? eventMetadata.conversationId,
		parentAgentId: overrides?.parentAgentId ?? eventMetadata.parentAgentId,
		createdByAgentId: overrides?.createdByAgentId,
		teamId: overrides?.teamId ?? teamRuntime?.getTeamId(),
		teamName: overrides?.teamName ?? teamRuntime?.getTeamName(),
		teamRole: overrides?.teamRole,
		teamAgentId: overrides?.teamAgentId,
	});

	if (
		event.type === "content_start" &&
		event.contentType === "tool" &&
		event.toolName === "skills"
	) {
		const skillName = extractSkillNameFromToolInput(event.input);
		if (skillName) {
			captureSkillUsed(telemetry, {
				ulid: sessionId,
				skillName,
				skillSource: "project",
				skillsAvailableGlobal: 0,
				skillsAvailableProject: 0,
				provider: config.providerId,
				modelId: config.modelId,
				...agentIdentity,
			});
		}
	}

	if (event.type === "content_end" && event.contentType === "tool") {
		const toolName = event.toolName ?? "unknown";
		const success = !event.error;
		captureToolUsage(telemetry, {
			ulid: sessionId,
			tool: toolName,
			autoApproved: undefined,
			success,
			modelId: config.modelId,
			provider: config.providerId,
			...agentIdentity,
		});
		if (!success && (toolName === "editor" || toolName === "apply_patch")) {
			captureDiffEditFailure(telemetry, {
				ulid: sessionId,
				modelId: config.modelId,
				provider: config.providerId,
				errorType: event.error,
				...agentIdentity,
			});
		}
	}

	if (event.type === "usage" && liveSession?.turnUsageBaseline) {
		const usageDelta = usageDeltaFromEvent(event);
		if (isPrimaryAgentEvent) {
			liveSession.turnPrimaryUsage = accumulateUsageTotals(
				liveSession.turnPrimaryUsage ?? createInitialAccumulatedUsage(),
				usageDelta,
			);
			const mainUsage = accumulateUsageTotals(
				liveSession.turnUsageBaseline,
				liveSession.turnPrimaryUsage,
			);
			ctx.usageBySession.set(sessionId, mainUsage);
			captureConversationTurnEvent(telemetry, {
				ulid: sessionId,
				provider: config.providerId,
				model: config.modelId,
				source: "assistant",
				mode: config.mode,
				...agentIdentity,
			});
			captureTokenUsage(telemetry, {
				ulid: sessionId,
				tokensIn: event.inputTokens,
				tokensOut: event.outputTokens,
				cacheWriteTokens: event.cacheWriteTokens,
				cacheReadTokens: event.cacheReadTokens,
				totalCost: event.cost,
				model: config.modelId,
				...agentIdentity,
			});
		} else {
			const agentKey = resolveUsageAgentKey({
				isPrimaryAgentEvent,
				overrides,
				eventMetadata,
			});
			const turnUsageByAgent =
				liveSession.turnUsageByAgent ??
				new Map<string, SessionAccumulatedUsage>();
			liveSession.turnUsageByAgent = turnUsageByAgent;
			turnUsageByAgent.set(
				agentKey,
				accumulateUsageTotals(
					turnUsageByAgent.get(agentKey) ?? createInitialAccumulatedUsage(),
					usageDelta,
				),
			);
		}
		const aggregateTurnUsage = accumulateUsageTotals(
			liveSession.turnPrimaryUsage ?? createInitialAccumulatedUsage(),
			sumUsageTotals(liveSession.turnUsageByAgent?.values() ?? []),
		);
		ctx.aggregateUsageBySession.set(
			sessionId,
			accumulateUsageTotals(
				liveSession.turnAggregateUsageBaseline ?? liveSession.turnUsageBaseline,
				aggregateTurnUsage,
			),
		);
	}

	if (event.type === "iteration_end" && isPrimaryAgentEvent) {
		ctx.persistMessages(
			sessionId,
			liveSession?.agent.getMessages() ?? [],
			liveSession?.config.systemPrompt,
		);
	}

	emit({
		type: "agent_event",
		payload: {
			sessionId,
			event,
			teamAgentId: overrides?.teamAgentId,
			teamRole:
				overrides !== undefined
					? (overrides.teamRole ?? (isPrimaryAgentEvent ? "lead" : undefined))
					: undefined,
		},
	});
	emit({
		type: "chunk",
		payload: {
			sessionId,
			stream: "agent",
			chunk: serializeAgentEvent(event),
			ts: Date.now(),
		},
	});
}

