		const record = withStore((store) =>
			store.getConnection("telegram", "cline_bot"),
		);
		expect(record?.connectArgs).toEqual([
			"-k",
			"123:token",
			"--allow-user",
			"42",
			"--cwd",
			"/workspace",
		]);
		expect(record?.enabled).toBe(true);
	});

	it("reconnects only enabled connectors with stored connect args", async () => {
		useTempDataDir();
		persistConnectorConnection(
			"telegram",
			"cline_bot",
			["-k", "123:token"],
			"/telegram-workspace",
		);
		persistConnectorConnection(
			"slack",
			"workspace",
			["--bot-token", "xoxb"],
			"/slack-workspace",
		);
		disableConnectorAutostart("slack");
		withStore((store) =>
			store.upsertConfig({ channel: "linear", values: { "-k": "lin" } }),
		);

		const start = vi.fn().mockResolvedValue(true);
		const attempts = await reconnectPersistedConnectors({ start });

		expect(start).toHaveBeenCalledTimes(1);
		expect(start).toHaveBeenCalledWith({
			channel: "telegram",
			instanceId: "cline_bot",
			args: ["-k", "123:token", "--cwd", "/telegram-workspace"],
		});
		expect(attempts).toEqual([
			{ channel: "telegram", instanceId: "cline_bot", ok: true },
		]);
	});

	it("persists the originating workspace for env-only connectors", async () => {
		useTempDataDir();
		persistConnectorConnection("telegram", "cline_bot", [], "/workspace");

		const start = vi.fn().mockResolvedValue(true);
		const attempts = await reconnectPersistedConnectors({ start });

		expect(start).toHaveBeenCalledTimes(1);
		expect(start).toHaveBeenCalledWith({
			channel: "telegram",
			instanceId: "cline_bot",
			args: ["--cwd", "/workspace"],
		});
		expect(attempts).toEqual([
			{ channel: "telegram", instanceId: "cline_bot", ok: true },
		]);
	});

	it("lets the host skip connectors that are known to be healthy", async () => {
		useTempDataDir();
		persistConnectorConnection("telegram", "cline_bot", ["-k", "123:token"]);

		const start = vi.fn().mockResolvedValue(true);
		const attempts = await reconnectPersistedConnectors({
			start,
			isHealthy: ({ channel, instanceId }) =>
				channel === "telegram" && instanceId === "cline_bot",
		});

		expect(start).not.toHaveBeenCalled();
		expect(attempts).toEqual([]);
	});

	it("preserves an explicitly configured workspace", () => {
		useTempDataDir();
		persistConnectorConnection(
			"telegram",
			"cline_bot",
			["-k", "123:token", "--cwd=/explicit"],
			"/ignored",
		);

		expect(
			withStore(
				(store) => store.getConnection("telegram", "cline_bot")?.connectArgs,
			),
		).toEqual(["-k", "123:token", "--cwd=/explicit"]);
	});

	it("reports failed reconnect attempts", async () => {
		useTempDataDir();
		persistConnectorConnection("telegram", "cline_bot", ["-k", "123:token"]);

		const start = vi.fn().mockRejectedValue(new Error("boom"));
		const attempts = await reconnectPersistedConnectors({ start });

		expect(attempts).toEqual([
			{
				channel: "telegram",
				instanceId: "cline_bot",
				ok: false,
				error: "boom",
			},
		]);
	});

	it("reconnects every persisted instance in the same channel", async () => {
		useTempDataDir();
		persistConnectorConnection("telegram", "first_bot", ["-k", "first:token"]);
		persistConnectorConnection("telegram", "second_bot", [
			"-k",
			"second:token",
		]);

		const start = vi.fn().mockResolvedValue(true);
		const attempts = await reconnectPersistedConnectors({ start });

		expect(start).toHaveBeenCalledTimes(2);
		expect(attempts).toEqual([
			{ channel: "telegram", instanceId: "first_bot", ok: true },
			{ channel: "telegram", instanceId: "second_bot", ok: true },
		]);
	});

	it("disables all connectors when no channel is given", async () => {
		useTempDataDir();
		persistConnectorConnection("telegram", "cline_bot", ["-k", "123:token"]);
		persistConnectorConnection("slack", "workspace", ["--bot-token", "xoxb"]);
		disableConnectorAutostart();

		const start = vi.fn().mockResolvedValue(true);
		expect(await reconnectPersistedConnectors({ start })).toEqual([]);
		expect(start).not.toHaveBeenCalled();
	});
});

import {
	type ConnectorConnectionRecord,
	withConnectorStore,
} from "@cline/shared/db";

const INTERACTIVE_FLAGS = new Set(["-i", "--interactive"]);

function normalizeReconnectArgs(args: string[], cwd: string): string[] {
	const normalized = args.filter((arg) => !INTERACTIVE_FLAGS.has(arg));
	const hasExplicitCwd = normalized.some(
		(arg) => arg === "--cwd" || arg.startsWith("--cwd="),
	);
	return hasExplicitCwd ? normalized : [...normalized, "--cwd", cwd];
}

/**
 * Record a successful connector start so the connector can be reconnected
 * automatically after a hub or host restart.
 */
export function persistConnectorConnection(
	channel: string,
	instanceId: string,
	rawArgs: string[],
	cwd = process.cwd(),
): void {
	try {
		const reconnectArgs = normalizeReconnectArgs(rawArgs, cwd);
		withConnectorStore((store) =>
			store.recordConnected(channel, instanceId, reconnectArgs),
		);
	} catch {
		// Persistence is best-effort; never fail the connector start over it.
	}
}

/** Stop auto-reconnecting one instance, one channel, or every connector. */
export function disableConnectorAutostart(
	channel?: string,
	instanceId?: string,
): void {
	try {
		withConnectorStore((store) => {
			if (channel) {
				store.setEnabled(channel, false, instanceId);
			} else {
				store.disableAll();
			}
		});
	} catch {
		// Persistence is best-effort; never fail the connector stop over it.
	}
}

export function getPersistedConnectorConnection(
	channel: string,
	instanceId: string,
): ConnectorConnectionRecord | undefined {
	try {
		return withConnectorStore((store) =>
			store.getConnection(channel, instanceId),
		);
	} catch {
		return undefined;
	}
}

export function removePersistedConnectorConnection(
	channel: string,
	instanceId: string,
): void {
	try {
		withConnectorStore((store) => store.deleteConnection(channel, instanceId));
	} catch {
		// Replacement cleanup is best-effort.
	}
}

export interface ReconnectTarget {
	channel: string;
	instanceId: string;
	args: string[];
}

export interface ReconnectAttempt {
	channel: string;
	instanceId: string;
	ok: boolean;
	error?: string;
}

export interface ReconnectPersistedConnectorsOptions {
	/** Starts one connector instance with its stored, non-interactive arguments. */
	start: (target: ReconnectTarget) => Promise<boolean>;
	/** Reports whether this exact connector instance is healthy in the host. */
	isHealthy?: (target: ReconnectTarget) => boolean;
	log?: (message: string) => void;
}

/**
 * Reconnect every connector that has stored connection arguments, is enabled,
 * and is not already active in the calling host.
 */
export async function reconnectPersistedConnectors(
	options: ReconnectPersistedConnectorsOptions,
): Promise<ReconnectAttempt[]> {
	const log = options.log ?? (() => {});
	let candidates: ReconnectTarget[];
	try {
		candidates = withConnectorStore((store) => store.listConnections())
			.filter((entry) => entry.enabled)
			.map((entry) => ({
				channel: entry.channel,
				instanceId: entry.instanceId,
				args: entry.connectArgs,
			}));
	} catch (error) {
		log(
			`[connect] failed to read persisted connectors: ${
				error instanceof Error ? error.message : String(error)
			}`,
		);
		return [];
	}

	const attempts: ReconnectAttempt[] = [];
	for (const target of candidates) {
		const { channel, instanceId } = target;
		if (options.isHealthy?.(target)) {
			log(
				`[connect] skipping ${channel} connector ${instanceId}: already live in this host`,
			);
			continue;
		}
		log(`[connect] reconnecting ${channel} connector ${instanceId}`);
		try {
			const ok = await options.start(target);
			attempts.push({ channel, instanceId, ok });
			if (!ok) {
				log(`[connect] failed to reconnect ${channel} connector ${instanceId}`);
			}
		} catch (error) {
			const message = error instanceof Error ? error.message : String(error);
			attempts.push({
				channel,
				instanceId,
				ok: false,
				error: message,
			});
			log(
				`[connect] failed to reconnect ${channel} connector ${instanceId}: ${message}`,
			);
		}
	}
	return attempts;
}

import {
	CLINE_CONNECTOR_STARTING_INSTANCE_ENV,
	CLINE_RUN_AS_HUB_DAEMON_ENV,
} from "@cline/shared";

/**
 * Env markers a connector sets on its own detached child: the shared
 * `CLINE_CONNECTOR_DETACHED_CHILD` plus one per adapter
 * (`CLINE_SLACK_CONNECT_CHILD`, `CLINE_TELEGRAM_CONNECT_CHILD`, ...). They are
 * owned by the CLI, so match them by shape rather than importing upward.
 */
const CONNECTOR_CHILD_MARKER_PATTERN =
	/^CLINE_(?:CONNECTOR_DETACHED_CHILD|[A-Z0-9]+_CONNECT_CHILD)$/;

/**
 * Environment for a CLI process the hub daemon launches.
 *
 * The daemon inherits the environment of whichever connector spawned it, and
 * those inherited markers are actively harmful downstream: the daemon sentinel
 * would make the child try to become a hub, and a child marker tells a connector
 * "you are already the detached child", which makes it skip its own
 * already-running check and start alongside a live instance holding the same
 * credentials.
 */
export function buildConnectorChildEnv(
	env: NodeJS.ProcessEnv = process.env,
): NodeJS.ProcessEnv {
	const childEnv = { ...env };
	delete childEnv[CLINE_RUN_AS_HUB_DAEMON_ENV];
	delete childEnv[CLINE_CONNECTOR_STARTING_INSTANCE_ENV];
	for (const key of Object.keys(childEnv)) {
		if (CONNECTOR_CHILD_MARKER_PATTERN.test(key)) {
			delete childEnv[key];
		}
	}
	return childEnv;
}

export const __test__ = { CONNECTOR_CHILD_MARKER_PATTERN };

