/**
 * Deterministic clock + timer queue: restart backoff is the behaviour under
 * test, so nothing here may depend on real time.
 */
function createHarness(
	overrides: Partial<{
		children: FakeChild[];
		autostartEnabled: boolean;
		launchSpec: ConnectorCliLaunchSpec | undefined;
		active: Array<{ type: string; instanceId: string; pid: number }>;
		killProcess: (
			pid: number,
			signal: NodeJS.Signals,
			alivePids: Set<number>,
		) => void;
	}> = {},
) {
	let now = 1_000_000;
	const timers: Array<{ id: number; at: number; callback: () => void }> = [];
	let nextTimerId = 1;
	const spawned: Array<{
		launcher: string;
		args: string[];
		options: { cwd: string; env: NodeJS.ProcessEnv; detached: boolean };
	}> = [];
	const children = overrides.children ?? [];
	let childIndex = 0;
	const alivePids = new Set<number>();
	const cleanups: string[] = [];
	const logs: string[] = [];
	const kills: string[] = [];

	const spawnProcess = vi.fn(
		(launcher: string, args: string[], options: Record<string, unknown>) => {
			spawned.push(
				options as unknown as (typeof spawned)[number] extends infer T
					? T
					: never,
			);
			spawned[spawned.length - 1] = {
				launcher,
				args,
				options: options as unknown as {
					cwd: string;
					env: NodeJS.ProcessEnv;
					detached: boolean;
				},
			};
			const child = children[childIndex++] ?? new FakeChild(5000 + childIndex);
			if (child.pid !== undefined) {
				alivePids.add(child.pid);
				child.once("exit", () => {
					if (child.pid !== undefined) {
						alivePids.delete(child.pid);
					}
				});
			}
			return child as never;
		},
	);

	const supervisor = new ConnectorSupervisor({
		launchSpec: () => ("launchSpec" in overrides ? overrides.launchSpec : spec),
		spawnProcess: spawnProcess as never,
		isProcessRunning: (pid) => alivePids.has(pid),
		// Injected so tests never signal real pids; the default drops the pid so
		// a stop's wait-for-exit resolves the way a real SIGTERM would.
		killProcess: (pid, signal) => {
			kills.push(`${pid}:${signal}`);
			if (overrides.killProcess) {
				overrides.killProcess(pid, signal, alivePids);
				return;
			}
			alivePids.delete(pid);
		},
		listActive: () => (overrides.active ?? []) as never,
		cleanupInstance: async (channel, instanceId) => {
			cleanups.push(`${channel}:${instanceId}`);
		},
		isAutostartEnabled: () => overrides.autostartEnabled ?? true,
		log: (message) => logs.push(message),
		now: () => now,
		setTimer: (callback, delayMs) => {
			const id = nextTimerId++;
			timers.push({ id, at: now + delayMs, callback });
			return id;
		},
		clearTimer: (handle) => {
			const index = timers.findIndex((timer) => timer.id === handle);
			if (index >= 0) {
				timers.splice(index, 1);
			}
		},
	});

	return {
		supervisor,
		spawned,
		cleanups,
		logs,
		kills,
		alivePids,
		spawnProcess,
		advance(ms: number) {
			now += ms;
			const due = timers.filter((timer) => timer.at <= now);
			for (const timer of due) {
				const index = timers.indexOf(timer);
				if (index >= 0) {
					timers.splice(index, 1);
				}
				timer.callback();
			}
		},
		setNow(value: number) {
			now = value;
		},
		pendingTimers: () => timers.length,
		nextDelay: () => (timers[0] ? timers[0].at - now : undefined),
	};
}

async function flush(): Promise<void> {
	await new Promise((resolve) => setImmediate(resolve));
	await new Promise((resolve) => setImmediate(resolve));
}

describe("ConnectorSupervisor", () => {
	beforeEach(() => {
		vi.clearAllMocks();
		mocks.getPersistedConnectorConnection.mockReturnValue(undefined);
	});

	it("spawns a connector detached and reports it as running", async () => {
		const harness = createHarness();

		const result = await harness.supervisor.start({
			channel: "slack",
			instanceId: "cline-slack",
			args: ["--bot-token", "xoxb"],
		});

		expect(result.started).toBe(true);
		expect(result.record.state).toBe("running");
		expect(result.record.origin).toBe("spawned");
		expect(harness.spawned[0]?.launcher).toBe("/usr/local/bin/bun");
		expect(harness.spawned[0]?.args).toEqual([
			"/repo/apps/cli/src/index.ts",
			"connect",
			"slack",
			"--bot-token",
			"xoxb",
		]);
		// Detached: a hub restart must not take the connector down with it.
		expect(harness.spawned[0]?.options.detached).toBe(true);
	});

	it("refuses a second instance of a live connector", async () => {
		const harness = createHarness();
		await harness.supervisor.start({
			channel: "slack",
			instanceId: "cline-slack",
			args: ["--bot-token", "xoxb"],
		});

		const second = await harness.supervisor.start({
			channel: "slack",
			instanceId: "cline-slack",
			args: ["--bot-token", "xoxb"],
		});

		expect(second.started).toBe(false);
		expect(second.reason).toBe("already_running");
		// The whole point: one process per instance, so one socket per token.
		expect(harness.spawnProcess).toHaveBeenCalledTimes(1);
	});

	it("replaces a live instance when restart is requested", async () => {
		const harness = createHarness();
		await harness.supervisor.start({
			channel: "slack",
			instanceId: "cline-slack",
			args: ["--bot-token", "old"],
		});

		const restarted = await harness.supervisor.start({
			channel: "slack",
			instanceId: "cline-slack",
			args: ["--bot-token", "new"],
			restart: true,
		});

		expect(restarted.started).toBe(true);
		expect(harness.spawnProcess).toHaveBeenCalledTimes(2);
		expect(harness.spawned[1]?.args).toContain("new");
		// A restart must not disable the autostart record.
		expect(mocks.disableConnectorAutostart).not.toHaveBeenCalled();
	});

	it("strips daemon and connector-child markers from the child environment", async () => {
		process.env.CLINE_RUN_AS_HUB_DAEMON = "1";
		process.env.CLINE_SLACK_CONNECT_CHILD = "1";
		process.env.CLINE_CONNECTOR_DETACHED_CHILD = "1";
		process.env.CLINE_CONNECTOR_STARTING_INSTANCE = '{"channel":"slack"}';
		try {
			const harness = createHarness();
			await harness.supervisor.start({
				channel: "slack",
				instanceId: "cline-slack",
				args: [],
			});

			const env = harness.spawned[0]?.options.env ?? {};
			expect(env.CLINE_RUN_AS_HUB_DAEMON).toBeUndefined();
			expect(env.CLINE_SLACK_CONNECT_CHILD).toBeUndefined();
			expect(env.CLINE_CONNECTOR_DETACHED_CHILD).toBeUndefined();
			expect(env.CLINE_CONNECTOR_STARTING_INSTANCE).toBeUndefined();
			expect(env.PATH).toBe(process.env.PATH);
		} finally {
			delete process.env.CLINE_RUN_AS_HUB_DAEMON;
			delete process.env.CLINE_SLACK_CONNECT_CHILD;
			delete process.env.CLINE_CONNECTOR_DETACHED_CHILD;
			delete process.env.CLINE_CONNECTOR_STARTING_INSTANCE;
		}
	});

	it("reaps a dead connector and restarts it with exponential backoff", async () => {
		const first = new FakeChild(101);
		const second = new FakeChild(102);
		const harness = createHarness({ children: [first, second] });
		await harness.supervisor.start({
			channel: "slack",
			instanceId: "cline-slack",
			args: ["--bot-token", "xoxb"],
		});

		first.exit(1);
		await flush();

		// Reaping is what keeps Slack threads from pointing at dead sessions.
		expect(harness.cleanups).toEqual(["slack:cline-slack"]);
		expect(harness.supervisor.list()[0]?.state).toBe("backoff");
		expect(harness.nextDelay()).toBe(RESTART_BASE_DELAY_MS);

		harness.advance(RESTART_BASE_DELAY_MS);
		await flush();

		expect(harness.spawnProcess).toHaveBeenCalledTimes(2);
		const record = harness.supervisor.list()[0];
		expect(record?.state).toBe("running");
		expect(record?.restarts).toBe(1);
	});

	it("backs off further on each successive crash and caps the delay", async () => {
		const children = Array.from(
			{ length: 4 },
			(_, i) => new FakeChild(200 + i),
		);
		const harness = createHarness({ children });
		await harness.supervisor.start({
			channel: "slack",
			instanceId: "cline-slack",
			args: [],
		});

		const delays: Array<number | undefined> = [];
		for (let attempt = 0; attempt < 3; attempt += 1) {
			children[attempt]?.exit(1);
			await flush();
			delays.push(harness.nextDelay());
			harness.advance(harness.nextDelay() ?? 0);
			await flush();
		}

		expect(delays).toEqual([
			RESTART_BASE_DELAY_MS,
			RESTART_BASE_DELAY_MS * 2,
			RESTART_BASE_DELAY_MS * 4,
		]);
		expect(delays.every((delay) => (delay ?? 0) <= RESTART_MAX_DELAY_MS)).toBe(
			true,
		);
	});

	it("gives up after too many consecutive restarts", async () => {
		const children = Array.from(
			{ length: RESTART_GIVE_UP_AFTER + 2 },
			(_, i) => new FakeChild(300 + i),
		);
		const harness = createHarness({ children });
		await harness.supervisor.start({
			channel: "slack",
			instanceId: "cline-slack",
			args: [],
		});

		for (let attempt = 0; attempt <= RESTART_GIVE_UP_AFTER; attempt += 1) {
			children[attempt]?.exit(1);
			await flush();
			harness.advance(harness.nextDelay() ?? 0);
			await flush();
		}

		const record = harness.supervisor.list()[0];
		expect(record?.state).toBe("failed");
		expect(record?.restarts).toBe(RESTART_GIVE_UP_AFTER);
		// A revoked token must not become an endless spawn loop.
		expect(harness.pendingTimers()).toBe(0);
		expect(harness.logs.some((line) => line.includes("giving up"))).toBe(true);
	});

	it("clears the restart counter after a run that stayed up", async () => {
		const children = Array.from(
			{ length: 3 },
			(_, i) => new FakeChild(400 + i),
		);
		const harness = createHarness({ children });
		await harness.supervisor.start({
			channel: "slack",
			instanceId: "cline-slack",
			args: [],
		});

		children[0]?.exit(1);
		await flush();
		harness.advance(RESTART_BASE_DELAY_MS);
		await flush();
		expect(harness.supervisor.list()[0]?.restarts).toBe(1);

		// Second run stays healthy for well over the reset window before dying.
		harness.advance(10 * 60_000);
		children[1]?.exit(1);
		await flush();

		expect(harness.nextDelay()).toBe(RESTART_BASE_DELAY_MS);
		expect(harness.supervisor.list()[0]?.restarts).toBe(1);
	});

	it("cancels a pending backoff restart when a new start replaces the entry", async () => {
		// A user runs `cline connect` while the instance is waiting out its
		// backoff. The old entry's timer must not survive the replacement: it
		// holds a closure over the old entry, so firing it would spawn a second
		// process for the same instance — untracked by the map, so invisible to
		// list() and unreachable by stop() — two processes on one bot token.
		const children = [
			new FakeChild(1300),
			new FakeChild(1301),
			new FakeChild(1302),
		];
		const harness = createHarness({ children });
		await harness.supervisor.start({
			channel: "slack",
			instanceId: "cline-slack",
			args: ["--bot-token", "xoxb"],
		});

		children[0]?.exit(1);
		await flush();
		expect(harness.supervisor.list()[0]?.state).toBe("backoff");
		expect(harness.pendingTimers()).toBe(1);

		const second = await harness.supervisor.start({
			channel: "slack",
			instanceId: "cline-slack",
			args: ["--bot-token", "xoxb"],
		});

		expect(second.started).toBe(true);
		expect(harness.pendingTimers()).toBe(0);

		// Even well past every possible backoff, nothing else may spawn.
		harness.advance(RESTART_MAX_DELAY_MS);
		await flush();
		expect(harness.spawnProcess).toHaveBeenCalledTimes(2);
		expect(harness.supervisor.list()).toHaveLength(1);
		expect(harness.supervisor.list()[0]?.state).toBe("running");
	});

	it("serialises a boot-time restart with a concurrent user start", async () => {
		// Observed live: a new hub's boot reconnect restarts an adopted survivor
		// — which suspends inside stop() waiting on the CLI cleanup — while a
		// user `cline connect` for the same instance arrives over the hub.
		// Unserialised, both spawned: the map tracked one process while the other
		// lived on untracked, holding the connector's webhook port, and the
		// tracked chain crash-looped on EADDRINUSE until it gave up.
		mocks.getPersistedConnectorConnection.mockReturnValue({
			channel: "slack",
			instanceId: "cline-slack",
			connectArgs: ["--bot-token", "stored"],
			lastSuccessfulArgs: [],
			enabled: true,
			updatedAt: "",
			lastConnectedAt: "",
		});
		const harness = createHarness({
			active: [{ type: "slack", instanceId: "cline-slack", pid: 700 }],
		});
		harness.alivePids.add(700);
		harness.supervisor.adoptRunningConnectors();

		const [restarted, userStart] = await Promise.all([
			harness.supervisor.start({
				channel: "slack",
				instanceId: "cline-slack",
				args: ["--bot-token", "stored"],
				restart: true,
			}),
			harness.supervisor.start({
				channel: "slack",
				instanceId: "cline-slack",
				args: ["--bot-token", "stored"],
			}),
		]);

		expect(restarted.started).toBe(true);
		expect(userStart.started).toBe(false);
		expect(userStart.reason).toBe("already_running");
		// The survivor was actually stopped, exactly one replacement exists, and
		// the supervisor tracks it.
		expect(harness.kills).toContain("700:SIGTERM");
		expect(harness.spawnProcess).toHaveBeenCalledTimes(1);
		expect(harness.supervisor.list()).toHaveLength(1);
		expect(harness.supervisor.list()[0]?.state).toBe("running");
	});

	it("waits for a stopped process to die, escalating to SIGKILL", async () => {
		// A replacement spawned while the old process still holds the
		// connector's listen port fails on EADDRINUSE, so stop must not return
		// until the process is actually gone.
		const child = new FakeChild(800);
		const harness = createHarness({
			children: [child],
			killProcess: (pid, signal, alivePids) => {
				// This process ignores SIGTERM and lingers on its port.
				if (signal === "SIGKILL") {
					alivePids.delete(pid);
				}
			},
		});
		await harness.supervisor.start({
			channel: "slack",
			instanceId: "cline-slack",
			args: [],
		});

		let resolved = false;
		const pending = harness.supervisor
			.stop({ channel: "slack", instanceId: "cline-slack" })
			.then((stopped) => {
				resolved = true;
				return stopped;
			});

		// Drive the exit poll past the SIGTERM window.
		const iterations = STOP_SIGTERM_TIMEOUT_MS / 100 + 5;
		for (let step = 0; step < iterations && !resolved; step += 1) {
			await flush();
			harness.advance(100);
		}
		await flush();

		await expect(pending).resolves.toBe(true);
		expect(harness.kills).toContain("800:SIGTERM");
		expect(harness.kills).toContain("800:SIGKILL");
		expect(harness.alivePids.has(800)).toBe(false);
		expect(harness.supervisor.list()).toEqual([]);
	});

	it("does not schedule a restart for an entry replaced while its cleanup was in flight", async () => {
		// Between a crash and its restart timer there is a window where the
		// exit-cleanup chain is still running and no timer exists yet to cancel.
		// A replacement made in that window must make the chain stand down
		// instead of scheduling a restart for the retired entry.
		const children = [new FakeChild(1400), new FakeChild(1401)];
		const harness = createHarness({ children });
		await harness.supervisor.start({
			channel: "slack",
			instanceId: "cline-slack",
			args: ["--bot-token", "xoxb"],
		});

		children[0]?.exit(1);
		// No flush: the cleanup chain has not completed when the start arrives.
		const second = await harness.supervisor.start({
			channel: "slack",
			instanceId: "cline-slack",
			args: ["--bot-token", "xoxb"],
		});
		await flush();

		expect(second.started).toBe(true);
		expect(harness.pendingTimers()).toBe(0);
		expect(harness.spawnProcess).toHaveBeenCalledTimes(2);
		expect(harness.supervisor.list()).toHaveLength(1);
	});

	it("restarts a connector that was started with no arguments", async () => {
		// A connector configured entirely through the connector store launches with
		// an empty argv. Emptiness must not be mistaken for "argv unknown", or the
		// hub can never bring it back.
		mocks.getPersistedConnectorConnection.mockReturnValue(undefined);
		const children = [new FakeChild(1100), new FakeChild(1101)];
		const harness = createHarness({ children });
		await harness.supervisor.start({
			channel: "slack",
			instanceId: "cline-slack",
			args: [],
		});

		children[0]?.exit(1);
		await flush();
		harness.advance(RESTART_BASE_DELAY_MS);
		await flush();

		expect(harness.spawnProcess).toHaveBeenCalledTimes(2);
		expect(harness.supervisor.list()[0]?.state).toBe("running");
		expect(harness.spawned[1]?.args).toEqual([
			"/repo/apps/cli/src/index.ts",
			"connect",
			"slack",
		]);
	});

	it("does not restart a connector whose autostart is disabled", async () => {
		const child = new FakeChild(500);
		const harness = createHarness({
			children: [child],
			autostartEnabled: false,
		});
		await harness.supervisor.start({
			channel: "slack",
			instanceId: "cline-slack",
			args: [],
		});

		child.exit(0);
		await flush();

		expect(harness.cleanups).toEqual(["slack:cline-slack"]);
		expect(harness.pendingTimers()).toBe(0);
		expect(harness.supervisor.list()).toEqual([]);
	});

	it("stops a connector on request without restarting it", async () => {
		const child = new FakeChild(600);
		const harness = createHarness({ children: [child] });
		await harness.supervisor.start({
			channel: "slack",
			instanceId: "cline-slack",
			args: [],
		});

		const stopped = await harness.supervisor.stop({
			channel: "slack",
			instanceId: "cline-slack",
		});
		child.exit(null, "SIGTERM");
		await flush();

		expect(stopped).toBe(true);
		expect(mocks.disableConnectorAutostart).toHaveBeenCalledWith(
			"slack",
			"cline-slack",
		);
		expect(harness.supervisor.list()).toEqual([]);
		expect(harness.pendingTimers()).toBe(0);
	});

	it("adopts connectors that predate this hub and polls them for death", async () => {
		mocks.getPersistedConnectorConnection.mockReturnValue({
			channel: "slack",
			instanceId: "cline-slack",
			connectArgs: ["--bot-token", "stored"],
			lastSuccessfulArgs: [],
			enabled: true,
			updatedAt: "",
			lastConnectedAt: "",
		});
		const harness = createHarness({
			active: [{ type: "slack", instanceId: "cline-slack", pid: 700 }],
		});
		harness.alivePids.add(700);

		const adopted = harness.supervisor.adoptRunningConnectors();
		expect(adopted).toHaveLength(1);
		expect(adopted[0]?.origin).toBe("adopted");
		expect(adopted[0]?.pid).toBe(700);

		// Adopted processes have no child handle, so death is only visible by poll.
		harness.alivePids.delete(700);
		harness.advance(10_000);
		await flush();

		expect(harness.cleanups).toEqual(["slack:cline-slack"]);
		harness.advance(RESTART_BASE_DELAY_MS);
		await flush();

		// Restart args come from the persisted record: an adopted process's argv
		// is not ours to reconstruct.
		expect(harness.spawned[0]?.args).toEqual([
			"/repo/apps/cli/src/index.ts",
			"connect",
			"slack",
			"--bot-token",
			"stored",
		]);
	});

	it("does not adopt an instance it already supervises", async () => {
		const harness = createHarness({
			active: [{ type: "slack", instanceId: "cline-slack", pid: 800 }],
		});
		await harness.supervisor.start({
			channel: "slack",
			instanceId: "cline-slack",
			args: [],
		});

		expect(harness.supervisor.adoptRunningConnectors()).toEqual([]);
		expect(harness.supervisor.list()).toHaveLength(1);
	});

	it("fails a start when no launch specification is available", async () => {
		const harness = createHarness({ launchSpec: undefined });

		const result = await harness.supervisor.start({
			channel: "slack",
			instanceId: "cline-slack",
			args: [],
		});

		expect(result.started).toBe(false);
		expect(result.record.state).toBe("failed");
		expect(harness.spawnProcess).not.toHaveBeenCalled();
	});

	it("cannot restart an adopted connector with no stored arguments", async () => {
		mocks.getPersistedConnectorConnection.mockReturnValue(undefined);
		const harness = createHarness({
			active: [{ type: "slack", instanceId: "cline-slack", pid: 900 }],
		});
		harness.alivePids.add(900);
		harness.supervisor.adoptRunningConnectors();

		harness.alivePids.delete(900);
		harness.advance(10_000);
		await flush();
		harness.advance(RESTART_BASE_DELAY_MS);
		await flush();

		expect(harness.spawnProcess).not.toHaveBeenCalled();
		expect(harness.supervisor.list()[0]?.state).toBe("failed");
	});

	it("leaves running connectors alone when disposed so the next hub can adopt them", async () => {
		const child = new FakeChild(1000);
		const harness = createHarness({ children: [child] });
		await harness.supervisor.start({
			channel: "slack",
			instanceId: "cline-slack",
			args: [],
		});

		harness.supervisor.dispose();

		expect(harness.alivePids.has(1000)).toBe(true);
		expect(harness.supervisor.list()).toEqual([]);
		// A post-dispose exit must not trigger cleanup or a restart.
		child.exit(1);
		await flush();
		expect(harness.cleanups).toEqual([]);
		expect(harness.pendingTimers()).toBe(0);
	});

	it("exposes the active supervisor to hub command handlers", () => {
		const harness = createHarness();
		expect(getActiveConnectorSupervisor()).toBeUndefined();
		setActiveConnectorSupervisor(harness.supervisor);
		expect(getActiveConnectorSupervisor()).toBe(harness.supervisor);
		setActiveConnectorSupervisor(undefined);
		expect(getActiveConnectorSupervisor()).toBeUndefined();
	});
});

import { type ChildProcess, spawn } from "node:child_process";
import { openSync } from "node:fs";
import {
	CLINE_CONNECTOR_SUPERVISED_ENV,
	type ConnectorCliLaunchSpec,
	type ConnectorStartRequest,
	type ConnectorStartResult,
	readConnectorCliLaunchSpec,
	type SupervisedConnectorOrigin,
	type SupervisedConnectorRecord,
	type SupervisedConnectorState,
} from "@cline/shared";
import {
	ensureParentDir,
	resolveConnectorLogPath,
} from "@cline/shared/storage";
import { listActiveConnectors } from "./active-connectors";
import {
	disableConnectorAutostart,
	getPersistedConnectorConnection,
} from "./connector-autostart";
import { buildConnectorChildEnv } from "./connector-child-env";

export const RESTART_BASE_DELAY_MS = 1_000;
export const RESTART_MAX_DELAY_MS = 60_000;
/** Consecutive failed restarts before the hub stops trying. */
export const RESTART_GIVE_UP_AFTER = 5;
/**
 * A run that lasts this long is treated as healthy, clearing the restart
 * counter. Without it a connector that stays up for hours and then dies would
 * inherit stale failures and be given up on immediately.
 */
export const RESTART_COUNTER_RESET_MS = 60_000;
/** How often adopted connectors (no child handle) are checked for liveness. */
export const ADOPTED_POLL_INTERVAL_MS = 5_000;
/** How long a stop waits for SIGTERM to land before escalating to SIGKILL. */
export const STOP_SIGTERM_TIMEOUT_MS = 5_000;
/** How long a stop waits for SIGKILL to land before giving up on the wait. */
export const STOP_SIGKILL_TIMEOUT_MS = 2_000;
const EXIT_POLL_INTERVAL_MS = 100;

export interface ConnectorSupervisorDeps {
	launchSpec?: () => ConnectorCliLaunchSpec | undefined;
	spawnProcess?: typeof spawn;
	isProcessRunning?: (pid: number) => boolean;
	killProcess?: (pid: number, signal: NodeJS.Signals) => void;
	listActive?: typeof listActiveConnectors;
	/**
	 * Reap a dead instance's leftovers: state file, thread bindings and hub
	 * sessions. Delegated because all of that is connector-specific and owned by
	 * the CLI; the supervisor only knows a process died.
	 */
	cleanupInstance?: (channel: string, instanceId: string) => Promise<void>;
	isAutostartEnabled?: (channel: string, instanceId: string) => boolean;
	log?: (message: string) => void;
	now?: () => number;
	setTimer?: (callback: () => void, delayMs: number) => unknown;
	clearTimer?: (handle: unknown) => void;
}

interface SupervisedEntry {
	channel: string;
	instanceId: string;
	args: string[];
	/**
	 * Whether `args` is this instance's real argv. An adopted process's argv is
	 * not ours to reconstruct, and an empty argv is legitimate for a connector
	 * configured entirely through the connector store — so emptiness cannot
	 * stand in for "unknown".
	 */
	argsKnown: boolean;
	origin: SupervisedConnectorOrigin;
	state: SupervisedConnectorState;
	pid?: number;
	child?: ChildProcess;
	startedAt?: number;
	restarts: number;
	nextRestartAt?: number;
	restartTimer?: unknown;
	lastExitCode?: number;
	lastExitSignal?: string;
	lastError?: string;
}

function instanceKey(channel: string, instanceId: string): string {
	return `${channel}\u0000${instanceId}`;
}

function defaultIsProcessRunning(pid: number): boolean {
	if (!Number.isInteger(pid) || pid <= 0) {
		return false;
	}
	try {
		process.kill(pid, 0);
		return true;
	} catch {
		return false;
	}
}

function toIsoString(value: number | undefined): string | undefined {
	return value === undefined ? undefined : new Date(value).toISOString();
}

/**
 * Owns the lifecycle of connector processes on behalf of the hub.
 *
 * Three responsibilities, in order of why this exists:
 *
 * 1. **Single instance per (channel, instanceId).** The in-memory map is the
 *    authority, so two connectors can never hold the same bot token because two
 *    processes raced on a state file.
 * 2. **Reaping.** When a connector dies its state file, thread bindings and hub
 *    sessions would otherwise linger until the next manual start, leaving
 *    Slack threads bound to sessions that no longer exist.
 * 3. **Restart with backoff.** Replaces external watchdogs, and refuses to
 *    spin forever on a connector that cannot start (a revoked token).
 *
 * Connectors are spawned detached so a hub restart does not take them down; a
 * later hub adopts the survivors by pid from their state files. That is why exit
 * detection has two paths: child events for processes this hub spawned, pid
 * polling for adopted ones.
 */
export class ConnectorSupervisor {
	private readonly entries = new Map<string, SupervisedEntry>();
	/**
	 * Tail of the in-flight start/stop chain per instance key. `start` suspends
	 * on `stop` (which shells into the CLI for cleanup, taking seconds), and two
	 * unserialised starts interleaving across that suspension each spawn their
	 * own process — the map ends up tracking one while the other survives as an
	 * untracked ghost holding the connector's credentials and ports.
	 */
	private readonly instanceLocks = new Map<string, Promise<unknown>>();
	private pollTimer: unknown;
	private disposed = false;

	private readonly launchSpec: () => ConnectorCliLaunchSpec | undefined;
	private readonly spawnProcess: typeof spawn;
	private readonly isProcessRunning: (pid: number) => boolean;
	private readonly killProcess: (pid: number, signal: NodeJS.Signals) => void;
	private readonly listActive: typeof listActiveConnectors;
	private readonly cleanupInstance?: (
		channel: string,
		instanceId: string,
	) => Promise<void>;
	private readonly isAutostartEnabled: (
		channel: string,
		instanceId: string,
	) => boolean;
	private readonly log: (message: string) => void;
	private readonly now: () => number;
	private readonly setTimer: (callback: () => void, delayMs: number) => unknown;
	private readonly clearTimer: (handle: unknown) => void;

	constructor(deps: ConnectorSupervisorDeps = {}) {
		this.launchSpec = deps.launchSpec ?? readConnectorCliLaunchSpec;
		this.spawnProcess = deps.spawnProcess ?? spawn;
		this.isProcessRunning = deps.isProcessRunning ?? defaultIsProcessRunning;
		this.killProcess =
			deps.killProcess ?? ((pid, signal) => process.kill(pid, signal));
		this.listActive = deps.listActive ?? listActiveConnectors;
		this.cleanupInstance = deps.cleanupInstance;
		this.isAutostartEnabled =
			deps.isAutostartEnabled ??
			((channel, instanceId) =>
				getPersistedConnectorConnection(channel, instanceId)?.enabled === true);
		this.log =
			deps.log ??
			((message) => process.stderr.write(`[hub-daemon] ${message}\n`));
		this.now = deps.now ?? (() => Date.now());
		this.setTimer =
			deps.setTimer ??
			((callback, delayMs) => {
				const timer = setTimeout(callback, delayMs);
				// Never let a pending restart hold the process open.
				timer.unref?.();
				return timer;
			});
		this.clearTimer =
			deps.clearTimer ??
			((handle) => clearTimeout(handle as ReturnType<typeof setTimeout>));
	}

	/**
	 * Take over connectors that are already running, so a replacement hub reaps
	 * and restarts the processes it inherited instead of ignoring them.
	 */
	adoptRunningConnectors(): SupervisedConnectorRecord[] {
		const adopted: SupervisedConnectorRecord[] = [];
		for (const record of this.listActive()) {
			const key = instanceKey(record.type, record.instanceId);
			if (this.entries.has(key)) {
				continue;
			}
			const entry: SupervisedEntry = {
				channel: record.type,
				instanceId: record.instanceId,
				// Reconstructed from the autostart record on the first restart.
				args: [],
				argsKnown: false,
				origin: "adopted",
				state: "running",
				pid: record.pid,
				startedAt: record.startedAt ? Date.parse(record.startedAt) : this.now(),
				restarts: 0,
			};
			this.entries.set(key, entry);
			adopted.push(this.toRecord(entry));
			this.log(
				`[connect] adopted running ${record.type} connector ${record.instanceId} pid=${record.pid}`,
			);
		}
		if (adopted.length > 0) {
			this.ensurePolling();
		}
		return adopted;
	}

	/**
	 * Serialise start/stop work per instance key. Both operations suspend
	 * mid-flight — a stop waits for the process to die and for the CLI cleanup,
	 * a start may embed a stop — and interleaving two of them across those
	 * suspensions is how the map ends up tracking one process while another
	 * lives on untracked. One instance, one queue.
	 */
	private withInstanceLock<T>(key: string, task: () => Promise<T>): Promise<T> {
		const previous = this.instanceLocks.get(key) ?? Promise.resolve();
		const run = previous.then(task, task);
		const tail = run.then(
			() => undefined,
			() => undefined,
		);
		this.instanceLocks.set(key, tail);
		void tail.then(() => {
			if (this.instanceLocks.get(key) === tail) {
				this.instanceLocks.delete(key);
			}
		});
		return run;
	}

	async start(request: ConnectorStartRequest): Promise<ConnectorStartResult> {
		return this.withInstanceLock(
			instanceKey(request.channel, request.instanceId),
			() => this.startLocked(request),
		);
	}

	private async startLocked(
		request: ConnectorStartRequest,
	): Promise<ConnectorStartResult> {
		const { channel, instanceId } = request;
		const key = instanceKey(channel, instanceId);
		const existing = this.entries.get(key);
		if (existing && this.isEntryAlive(existing)) {
			if (!request.restart) {
				return {
					started: false,
					reason: "already_running",
					record: this.toRecord(existing),
				};
			}
			await this.stopLocked({ channel, instanceId, disableAutostart: false });
		} else if (existing) {
			// A dead entry can still act: a pending backoff timer would spawn a
			// second process for this instance once it fires — untracked, so
			// unstoppable — and an exit-cleanup chain still in flight would
			// schedule that timer after this replacement is made. Retire the old
			// entry explicitly; both paths check for "stopped" and stand down.
			this.cancelRestart(existing);
			existing.state = "stopped";
			existing.child?.removeAllListeners("exit");
		}
		const entry: SupervisedEntry = {
			channel,
			instanceId,
			args: [...request.args],
			argsKnown: true,
			origin: "spawned",
			state: "running",
			restarts: existing?.restarts ?? 0,
		};
		this.entries.set(key, entry);
		this.spawnEntry(entry);
		if (entry.state !== "running") {
			return { started: false, record: this.toRecord(entry) };
		}
		return { started: true, record: this.toRecord(entry) };
	}

	async stop(request: {
		channel: string;
		instanceId: string;
		disableAutostart?: boolean;
	}): Promise<boolean> {
		return this.withInstanceLock(
			instanceKey(request.channel, request.instanceId),
			() => this.stopLocked(request),
		);
	}

	private async stopLocked(request: {
		channel: string;
		instanceId: string;
		disableAutostart?: boolean;
	}): Promise<boolean> {
		const key = instanceKey(request.channel, request.instanceId);
		const entry = this.entries.get(key);
		if (request.disableAutostart !== false) {
			disableConnectorAutostart(request.channel, request.instanceId);
		}
		if (!entry) {
			return false;
		}
		this.cancelRestart(entry);
		// Mark before signalling so the exit handler does not restart it.
		entry.state = "stopped";
		const pid = entry.child?.pid ?? entry.pid;
		if (pid && this.isProcessRunning(pid)) {
			this.signal(pid, "SIGTERM");
			// Wait for the process to actually die. A replacement spawned while
			// the old process still holds the connector's listen port or socket
			// fails on it — observed as an EADDRINUSE crash loop when a webhook
			// connector was restarted for a new hub session.
			if (!(await this.waitForProcessExit(pid, STOP_SIGTERM_TIMEOUT_MS))) {
				this.signal(pid, "SIGKILL");
				await this.waitForProcessExit(pid, STOP_SIGKILL_TIMEOUT_MS);
			}
		}
		await this.runCleanup(entry);
		this.entries.delete(key);
		return true;
	}

	private signal(pid: number, signal: NodeJS.Signals): void {
		try {
			this.killProcess(pid, signal);
		} catch {
			// Already gone, or not ours to signal.
		}
	}

	private async waitForProcessExit(
		pid: number,
		timeoutMs: number,
	): Promise<boolean> {
		const deadline = this.now() + timeoutMs;
		while (this.isProcessRunning(pid)) {
			if (this.now() >= deadline) {
				return false;
			}
			await new Promise<void>((resolve) => {
				this.setTimer(resolve, EXIT_POLL_INTERVAL_MS);
			});
		}
		return true;
	}

	list(): SupervisedConnectorRecord[] {
		return [...this.entries.values()]
			.map((entry) => this.toRecord(entry))
			.sort(
				(left, right) =>
					left.channel.localeCompare(right.channel) ||
					left.instanceId.localeCompare(right.instanceId),
			);
	}

	/**
	 * Stop supervising without touching the processes: they are detached and
	 * outlive this hub on purpose, and the next hub adopts them.
	 */
	dispose(): void {
		this.disposed = true;
		for (const entry of this.entries.values()) {
			this.cancelRestart(entry);
			entry.child?.removeAllListeners("exit");
		}
		if (this.pollTimer !== undefined) {
			this.clearTimer(this.pollTimer);
			this.pollTimer = undefined;
		}
		this.entries.clear();
		this.instanceLocks.clear();
	}

	private spawnEntry(entry: SupervisedEntry): void {
		const spec = this.launchSpec();
		if (!spec) {
			entry.state = "failed";
			entry.lastError = "connector CLI launch information is unavailable";
			this.log(
				`[connect] cannot start ${entry.channel} connector ${entry.instanceId}: ${entry.lastError}`,
			);
			return;
		}
		const logPath = resolveConnectorLogPath(entry.channel, entry.instanceId);
		let stdio: ["ignore", "ignore" | number, "ignore" | number] = [
			"ignore",
			"ignore",
			"ignore",
		];
		try {
			ensureParentDir(logPath);
			const fd = openSync(logPath, "a");
			stdio = ["ignore", fd, fd];
		} catch {
			// Without a log the connector still runs; only diagnostics are lost.
		}
		try {
			const child = this.spawnProcess(
				spec.launcher,
				[...spec.connectArgsPrefix, entry.channel, ...entry.args],
				{
					cwd: spec.cwd,
					env: {
						...buildConnectorChildEnv(),
						// Tells the connector to run in this process rather than asking
						// the hub to start it (which would loop back here) or spawning
						// its own detached child and exiting (which would leave us
						// holding a handle to a process that is already gone).
						[CLINE_CONNECTOR_SUPERVISED_ENV]: "1",
					},
					// Detached so it survives this hub, but not unref'd from our
					// listener: we still want the exit event while we are alive.
					detached: true,
					stdio,
					windowsHide: true,
				},
			);
			entry.child = child;
			entry.pid = child.pid ?? undefined;
			entry.startedAt = this.now();
			entry.state = "running";
			entry.lastError = undefined;
			child.unref?.();
			child.once("error", (error: unknown) => {
				entry.lastError =
					error instanceof Error ? error.message : String(error);
				this.handleExit(entry, undefined, undefined);
			});
			child.once("exit", (code: number | null, signal: string | null) => {
				this.handleExit(entry, code ?? undefined, signal ?? undefined);
			});
			this.log(
				`[connect] started ${entry.channel} connector ${entry.instanceId} pid=${entry.pid}`,
			);
		} catch (error) {
			entry.state = "backoff";
			entry.lastError = error instanceof Error ? error.message : String(error);
			this.log(
				`[connect] failed to spawn ${entry.channel} connector ${entry.instanceId}: ${entry.lastError}`,
			);
			this.scheduleRestart(entry);
		}
	}

	private handleExit(
		entry: SupervisedEntry,
		code: number | undefined,
		signal: string | undefined,
	): void {
		if (this.disposed || entry.state === "stopped") {
			return;
		}
		entry.child = undefined;
		entry.pid = undefined;
		entry.lastExitCode = code;
		entry.lastExitSignal = signal;
		const ranLongEnough =
			entry.startedAt !== undefined &&
			this.now() - entry.startedAt >= RESTART_COUNTER_RESET_MS;
		if (ranLongEnough) {
			entry.restarts = 0;
		}
		this.log(
			`[connect] ${entry.channel} connector ${entry.instanceId} exited` +
				`${code === undefined ? "" : ` code=${code}`}` +
				`${signal ? ` signal=${signal}` : ""}`,
		);
		void this.runCleanup(entry).then(() => {
			const key = instanceKey(entry.channel, entry.instanceId);
			if (
				this.disposed ||
				entry.state === "stopped" ||
				// A concurrent start may have replaced this entry while cleanup was
				// running; the retired generation must not restart or delete the
				// replacement's map entry.
				this.entries.get(key) !== entry
			) {
				return;
			}
			if (!this.isAutostartEnabled(entry.channel, entry.instanceId)) {
				this.log(
					`[connect] not restarting ${entry.channel} connector ${entry.instanceId}: autostart is disabled`,
				);
				this.entries.delete(key);
				return;
			}
			this.scheduleRestart(entry);
		});
	}

	private scheduleRestart(entry: SupervisedEntry): void {
		if (entry.restarts >= RESTART_GIVE_UP_AFTER) {
			entry.state = "failed";
			entry.nextRestartAt = undefined;
			this.log(
				`[connect] giving up on ${entry.channel} connector ${entry.instanceId} after ${entry.restarts} failed restarts` +
					`${entry.lastError ? `: ${entry.lastError}` : ""}`,
			);
			return;
		}
		const delayMs = Math.min(
			RESTART_BASE_DELAY_MS * 2 ** entry.restarts,
			RESTART_MAX_DELAY_MS,
		);
		entry.restarts += 1;
		entry.state = "backoff";
		entry.nextRestartAt = this.now() + delayMs;
		this.log(
			`[connect] restarting ${entry.channel} connector ${entry.instanceId} in ${delayMs}ms (attempt ${entry.restarts})`,
		);
		const key = instanceKey(entry.channel, entry.instanceId);
		entry.restartTimer = this.setTimer(() => {
			entry.restartTimer = undefined;
			entry.nextRestartAt = undefined;
			// Under the instance lock: a restart spawn must not interleave with a
			// start or stop in flight for the same instance.
			void this.withInstanceLock(key, async () => {
				if (
					this.disposed ||
					entry.state === "stopped" ||
					this.entries.get(key) !== entry
				) {
					return;
				}
				const args = this.resolveRestartArgs(entry);
				if (!args) {
					entry.state = "failed";
					this.log(
						`[connect] cannot restart ${entry.channel} connector ${entry.instanceId}: no stored launch arguments`,
					);
					return;
				}
				entry.args = args;
				entry.argsKnown = true;
				entry.origin = "spawned";
				this.spawnEntry(entry);
			});
		}, delayMs);
	}

	/**
	 * An adopted connector has no argv of its own here, so its restart arguments
	 * come from the persisted autostart record.
	 */
	private resolveRestartArgs(entry: SupervisedEntry): string[] | undefined {
		if (entry.argsKnown) {
			return entry.args;
		}
		const persisted = getPersistedConnectorConnection(
			entry.channel,
			entry.instanceId,
		);
		return persisted?.connectArgs?.length ? persisted.connectArgs : undefined;
	}

	private cancelRestart(entry: SupervisedEntry): void {
		if (entry.restartTimer !== undefined) {
			this.clearTimer(entry.restartTimer);
			entry.restartTimer = undefined;
		}
		entry.nextRestartAt = undefined;
	}

	private async runCleanup(entry: SupervisedEntry): Promise<void> {
		if (!this.cleanupInstance) {
			return;
		}
		try {
			await this.cleanupInstance(entry.channel, entry.instanceId);
		} catch (error) {
			this.log(
				`[connect] cleanup failed for ${entry.channel} connector ${entry.instanceId}: ${
					error instanceof Error ? error.message : String(error)
				}`,
			);
		}
	}

	private isEntryAlive(entry: SupervisedEntry): boolean {
		if (entry.state === "backoff" || entry.state === "failed") {
			return false;
		}
		const pid = entry.child?.pid ?? entry.pid;
		return pid !== undefined && this.isProcessRunning(pid);
	}

	/**
	 * Adopted connectors have no child handle, so their death is only visible by
	 * polling. Processes this hub spawned report their own exit and are skipped.
	 */
	private ensurePolling(): void {
		if (this.pollTimer !== undefined || this.disposed) {
			return;
		}
		const tick = () => {
			this.pollTimer = undefined;
			if (this.disposed) {
				return;
			}
			for (const entry of [...this.entries.values()]) {
				if (
					entry.origin !== "adopted" ||
					entry.state !== "running" ||
					entry.child
				) {
					continue;
				}
				if (entry.pid === undefined || !this.isProcessRunning(entry.pid)) {
					this.handleExit(entry, undefined, undefined);
				}
			}
			if (this.hasAdoptedRunning()) {
				this.pollTimer = this.setTimer(tick, ADOPTED_POLL_INTERVAL_MS);
			}
		};
		this.pollTimer = this.setTimer(tick, ADOPTED_POLL_INTERVAL_MS);
	}

	private hasAdoptedRunning(): boolean {
		for (const entry of this.entries.values()) {
			if (entry.origin === "adopted" && entry.state === "running") {
				return true;
			}
		}
		return false;
	}

	private toRecord(entry: SupervisedEntry): SupervisedConnectorRecord {
		return {
			channel: entry.channel,
			instanceId: entry.instanceId,
			state: entry.state,
			origin: entry.origin,
			restarts: entry.restarts,
			...(entry.pid === undefined ? {} : { pid: entry.pid }),
			...(entry.startedAt === undefined
				? {}
				: { startedAt: toIsoString(entry.startedAt) }),
			...(entry.nextRestartAt === undefined
				? {}
				: { nextRestartAt: toIsoString(entry.nextRestartAt) }),
			...(entry.lastExitCode === undefined
				? {}
				: { lastExitCode: entry.lastExitCode }),
			...(entry.lastExitSignal === undefined
				? {}
				: { lastExitSignal: entry.lastExitSignal }),
			...(entry.lastError === undefined ? {} : { lastError: entry.lastError }),
		};
	}
}

let activeSupervisor: ConnectorSupervisor | undefined;

/**
 * The hub daemon's supervisor. Hub command handlers reach it through here
 * because they are invoked per-request and have no other shared state.
 */
export function setActiveConnectorSupervisor(
	supervisor: ConnectorSupervisor | undefined,
): void {
	activeSupervisor = supervisor;
}

export function getActiveConnectorSupervisor():
	| ConnectorSupervisor
	| undefined {
	return activeSupervisor;
}

import { CLINE_CONNECTOR_STARTING_INSTANCE_ENV } from "@cline/shared";
import { afterEach, describe, expect, it, vi } from "vitest";
import type { ConnectorSupervisor } from "./connector-supervisor";
import { reconnectDaemonConnectors } from "./daemon-connector-reconnect";

const mocks = vi.hoisted(() => ({
	reconnectPersistedConnectors: vi.fn(),
	getActiveConnectorSupervisor: vi.fn(),
}));

vi.mock("./connector-autostart", async (importOriginal) => {
	const actual = await importOriginal<typeof import("./connector-autostart")>();
	return {
		...actual,
		reconnectPersistedConnectors: mocks.reconnectPersistedConnectors,
	};
});

vi.mock("./connector-supervisor", async (importOriginal) => {
	const actual =
		await importOriginal<typeof import("./connector-supervisor")>();
	return {
		...actual,
		getActiveConnectorSupervisor: mocks.getActiveConnectorSupervisor,
	};
});

type StartArgs = {
	channel: string;
	instanceId: string;
	args: string[];
	restart?: boolean;
};

function createSupervisor(
	options: {
		supervised?: Array<{ channel: string; instanceId: string }>;
		started?: boolean;
		reason?: "already_running";
	} = {},
) {
	const starts: StartArgs[] = [];
	const supervisor = {
		list: () =>
			(options.supervised ?? []).map((entry) => ({
				...entry,
				state: "running" as const,
				origin: "adopted" as const,
				restarts: 0,
			})),
		start: vi.fn(async (request: StartArgs) => {
			starts.push(request);
			return {
				started: options.started ?? true,
				...(options.reason ? { reason: options.reason } : {}),
				record: {
					channel: request.channel,
					instanceId: request.instanceId,
					state: "running" as const,
					origin: "spawned" as const,
					restarts: 0,
				},
			};
		}),
	} as unknown as ConnectorSupervisor;
	return { supervisor, starts };
}

describe("reconnectDaemonConnectors", () => {
	const originalStartingInstance =
		process.env[CLINE_CONNECTOR_STARTING_INSTANCE_ENV];

	afterEach(() => {
		vi.clearAllMocks();
		if (originalStartingInstance === undefined) {
			delete process.env[CLINE_CONNECTOR_STARTING_INSTANCE_ENV];
		} else {
			process.env[CLINE_CONNECTOR_STARTING_INSTANCE_ENV] =
				originalStartingInstance;
		}
	});

	it("starts a persisted connector through the supervisor", async () => {
		delete process.env[CLINE_CONNECTOR_STARTING_INSTANCE_ENV];
		const { supervisor, starts } = createSupervisor();
		mocks.reconnectPersistedConnectors.mockImplementation(async (options) => {
			const ok = await options.start({
				channel: "telegram",
				instanceId: "cline_bot",
				args: ["-k", "token"],
			});
			return [{ channel: "telegram", instanceId: "cline_bot", ok }];
		});

		await expect(
			reconnectDaemonConnectors(vi.fn(), supervisor),
		).resolves.toEqual([
			{ channel: "telegram", instanceId: "cline_bot", ok: true },
		]);
		expect(starts).toEqual([
			{
				channel: "telegram",
				instanceId: "cline_bot",
				args: ["-k", "token"],
				restart: false,
			},
		]);
	});

	it("restarts a connector that survived the previous hub", async () => {
		delete process.env[CLINE_CONNECTOR_STARTING_INSTANCE_ENV];
		const { supervisor, starts } = createSupervisor({
			supervised: [{ channel: "telegram", instanceId: "cline_bot" }],
		});
		const log = vi.fn();
		mocks.reconnectPersistedConnectors.mockImplementation(async (options) => {
			await options.start({
				channel: "telegram",
				instanceId: "cline_bot",
				args: ["-k", "token"],
			});
			return [];
		});

		await reconnectDaemonConnectors(log, supervisor);

		// A survivor authenticated against the dead hub's token, so it has to come
		// back rather than keep running.
		expect(starts[0]?.restart).toBe(true);
		expect(log).toHaveBeenCalledWith(
			"[connect] restarting surviving telegram connector cline_bot for the new hub session",
		);
	});

	it("does not reconnect the connector instance that is starting this daemon", async () => {
		process.env[CLINE_CONNECTOR_STARTING_INSTANCE_ENV] = JSON.stringify({
			channel: "telegram",
			instanceId: "cline_bot",
		});
		const { supervisor } = createSupervisor();
		let isHealthy:
			| ((target: { channel: string; instanceId: string }) => boolean)
			| undefined;
		mocks.reconnectPersistedConnectors.mockImplementation(async (options) => {
			isHealthy = options.isHealthy;
			return [];
		});

		await reconnectDaemonConnectors(vi.fn(), supervisor);

		expect(isHealthy?.({ channel: "telegram", instanceId: "cline_bot" })).toBe(
			true,
		);
		// A different instance of the same channel still needs reconnecting.
		expect(isHealthy?.({ channel: "telegram", instanceId: "other_bot" })).toBe(
			false,
		);
		expect(isHealthy?.({ channel: "slack", instanceId: "cline_bot" })).toBe(
			false,
		);
	});

	it("reconnects every persisted instance when no connector is starting", async () => {
		delete process.env[CLINE_CONNECTOR_STARTING_INSTANCE_ENV];
		const { supervisor } = createSupervisor();
		let isHealthy:
			| ((target: { channel: string; instanceId: string }) => boolean)
			| undefined;
		mocks.reconnectPersistedConnectors.mockImplementation(async (options) => {
			isHealthy = options.isHealthy;
			return [];
		});

		await reconnectDaemonConnectors(vi.fn(), supervisor);

		expect(isHealthy?.({ channel: "telegram", instanceId: "cline_bot" })).toBe(
			false,
		);
	});

	it("reports an already-running instance without treating it as started", async () => {
		delete process.env[CLINE_CONNECTOR_STARTING_INSTANCE_ENV];
		const { supervisor } = createSupervisor({
			started: false,
			reason: "already_running",
		});
		const log = vi.fn();
		mocks.reconnectPersistedConnectors.mockImplementation(async (options) => {
			const ok = await options.start({
				channel: "slack",
				instanceId: "cline-slack",
				args: [],
			});
			return [{ channel: "slack", instanceId: "cline-slack", ok }];
		});

		await expect(reconnectDaemonConnectors(log, supervisor)).resolves.toEqual([
			{ channel: "slack", instanceId: "cline-slack", ok: false },
		]);
		expect(log).toHaveBeenCalledWith(
			"[connect] slack connector cline-slack is already running under this hub",
		);
	});

	it("does nothing when no supervisor is active", async () => {
		const log = vi.fn();
		mocks.getActiveConnectorSupervisor.mockReturnValue(undefined);

		await expect(reconnectDaemonConnectors(log)).resolves.toEqual([]);
		expect(mocks.reconnectPersistedConnectors).not.toHaveBeenCalled();
		expect(log).toHaveBeenCalledWith(
			"[connect] cannot reconnect connectors: no connector supervisor is active",
		);
	});
});

import { readStartingConnectorInstance } from "@cline/shared";
import {
	type ReconnectAttempt,
	reconnectPersistedConnectors,
} from "./connector-autostart";
import type { ConnectorSupervisor } from "./connector-supervisor";
import { getActiveConnectorSupervisor } from "./connector-supervisor";

/**
 * Bring persisted connectors back under the new hub's supervision.
 *
 * Called once per daemon boot, after the supervisor has adopted whatever
 * survived the previous hub. Survivors still have to be *restarted* rather than
 * left running: their hub client authenticated against the old hub's token and
 * cannot re-authenticate against this one, so the process has to come back to
 * attach to the new session.
 *
 * Spawning itself belongs to the supervisor, which is the single authority on
 * how many processes may hold one connector's credentials.
 */
export async function reconnectDaemonConnectors(
	log: (message: string) => void = (message) =>
		process.stderr.write(`[hub-daemon] ${message}\n`),
	supervisor: ConnectorSupervisor | undefined = getActiveConnectorSupervisor(),
): Promise<ReconnectAttempt[]> {
	if (!supervisor) {
		log(
			"[connect] cannot reconnect connectors: no connector supervisor is active",
		);
		return [];
	}
	const supervisedBefore = new Set(
		supervisor
			.list()
			.map((record) => `${record.channel}\0${record.instanceId}`),
	);
	// The connector that spawned this daemon is mid-startup and attaches itself.
	// Starting it here would put a second process on the same credentials, and
	// for socket-mode adapters both would hold a live connection and split
	// incoming events between them.
	const startingInstance = readStartingConnectorInstance();

	return await reconnectPersistedConnectors({
		isHealthy: ({ channel, instanceId }) =>
			startingInstance?.channel === channel &&
			startingInstance.instanceId === instanceId,
		start: async ({ channel, instanceId, args }) => {
			const survived = supervisedBefore.has(`${channel}\0${instanceId}`);
			if (survived) {
				log(
					`[connect] restarting surviving ${channel} connector ${instanceId} for the new hub session`,
				);
			}
			const result = await supervisor.start({
				channel,
				instanceId,
				args,
				restart: survived,
			});
			if (!result.started && result.reason === "already_running") {
				log(
					`[connect] ${channel} connector ${instanceId} is already running under this hub`,
				);
			}
			return result.started;
		},
		log,
	});
}

import { mkdtempSync, readFileSync, writeFileSync } from "node:fs";
