const MARKETPLACE_COMMAND_TIMEOUT_MS = 120_000;
const MAX_OUTPUT_CHARS = 12_000;
const SECRET_PATTERN =
	/(api[_ -]?key|access[_ -]?token|refresh[_ -]?token|auth(?:orization)?[_ -]?token|token|secret|password|authorization|credential)/i;
const SECRET_KEY_VALUE_PATTERN =
	/((?:^|[^\w])(?:[a-z0-9_]*?(?:api[_ -]?key|access[_ -]?token|refresh[_ -]?token|auth(?:orization)?[_ -]?token|token|secret|password|credential)[a-z0-9_]*)\s*[:=]\s*)(.+)$/gi;
const SECRET_BEARER_VALUE_PATTERN =
	/((?:^|[^\w])authorization\s*[:=]\s*)bearer\s+([^\s,"'}\]]+)/gi;
const SECRET_AUTHORIZATION_VALUE_PATTERN =
	/((?:^|[^\w])authorization\s*[:=])(?!\s*bearer\b)\s*(.+)$/gi;

function getMarketplaceEntryArgs(entry: MarketplaceEntryInput): string[] {
	return entry.install?.args ?? [];
}

function resolveHomeDir(): string {
	return (
		process.env.HOME?.trim() || process.env.USERPROFILE?.trim() || homedir()
	);
}

function trimSkillSegmentEdges(value: string): string {
	let start = 0;
	let end = value.length;
	while (start < end && (value[start] === "." || value[start] === "-")) {
		start++;
	}
	while (end > start && (value[end - 1] === "." || value[end - 1] === "-")) {
		end--;
	}
	return value.slice(start, end);
}

function sanitizeSkillSegment(value: string): string {
	const sanitized = trimSkillSegmentEdges(
		value.toLowerCase().replace(/[^a-z0-9._]+/g, "-"),
	).slice(0, 255);
	return sanitized || "skill";
}

function redactOutput(value: string): string {
	return value
		.split(/\r?\n/)
		.map((line) => {
			if (!SECRET_PATTERN.test(line)) return line;
			return line
				.replace(SECRET_KEY_VALUE_PATTERN, "$1[redacted]")
				.replace(SECRET_BEARER_VALUE_PATTERN, "$1Bearer [redacted]")
				.replace(
					/\b(Bearer)\s+(?!\[redacted\])([^\s,"'}\]]+)/gi,
					"$1 [redacted]",
				)
				.replace(SECRET_AUTHORIZATION_VALUE_PATTERN, "$1 [redacted]")
				.replace(
					/((?:^|[^\w])(?:api\s+key|access\s+token|refresh\s+token|auth(?:orization)?\s+token|secret|password|credential)\s+(?:is\s+)?)(\S+)/gi,
					"$1[redacted]",
				);
		})
		.join("\n")
		.slice(-MAX_OUTPUT_CHARS);
}

function commandOutput(result: MarketplaceSpawnResult): string | undefined {
	const output = redactOutput(
		[result.stdout, result.stderr].filter(Boolean).join("\n"),
	).trim();
	return output.length > 0 ? output : undefined;
}

function quoteCommandPart(value: string): string {
	if (value === "") return '""';
	if (/^[a-zA-Z0-9_./:=@%+,-]+$/.test(value)) return value;
	return JSON.stringify(value);
}

function formatCommand(command: string, args: string[]): string {
	return [command, ...args]
		.map((part) => quoteCommandPart(redactOutput(part).trim()))
		.join(" ");
}

const defaultMarketplaceSpawnCommand: MarketplaceSpawnCommand = async (
	command,
	args,
) =>
	new Promise<MarketplaceSpawnResult>((resolve, reject) => {
		let settled = false;
		let timedOut = false;
		const child = spawn(command, args, {
			env: process.env,
			shell: platform() === "win32",
			stdio: ["ignore", "pipe", "pipe"],
			windowsHide: true,
		});
		let stdout = "";
		let stderr = "";
		const forceKillTimeout = setTimeout(() => {
			if (!settled) child.kill("SIGKILL");
		}, MARKETPLACE_COMMAND_TIMEOUT_MS + 5_000);
		const timeout = setTimeout(() => {
			timedOut = true;
			stderr += `\nTimed out after ${MARKETPLACE_COMMAND_TIMEOUT_MS / 1000}s.`;
			child.kill("SIGTERM");
		}, MARKETPLACE_COMMAND_TIMEOUT_MS);
		forceKillTimeout.unref?.();
		timeout.unref?.();
		child.stdout?.on("data", (chunk) => {
			stdout += String(chunk);
			if (stdout.length > MAX_OUTPUT_CHARS * 2) {
				stdout = stdout.slice(-MAX_OUTPUT_CHARS);
			}
		});
		child.stderr?.on("data", (chunk) => {
			stderr += String(chunk);
			if (stderr.length > MAX_OUTPUT_CHARS * 2) {
				stderr = stderr.slice(-MAX_OUTPUT_CHARS);
			}
		});
		child.once("error", (error) => {
			clearTimeout(timeout);
			clearTimeout(forceKillTimeout);
			reject(error);
		});
		child.once("close", (code, signal) => {
			settled = true;
			clearTimeout(timeout);
			clearTimeout(forceKillTimeout);
			resolve({
				exitCode: timedOut ? 124 : (code ?? (signal === "SIGINT" ? 130 : 1)),
				stdout,
				stderr,
			});
		});
	});

export function marketplaceEntryKey(
	entry: Pick<MarketplaceEntryInput, "id" | "type">,
): string {
	return `${entry.type}:${entry.id}`;
}

export function resolveMarketplaceMcpServerName(
	entry: MarketplaceEntryInput,
): string {
	const args = getMarketplaceEntryArgs(entry);
	if (args.length === 0) {
		throw new Error("Marketplace install args are required.");
	}
	return parseMcpInstallArgs(args).name;
}

export function uninstallMarketplaceMcpServerFromSettings(
	entry: MarketplaceEntryInput,
	options: Pick<UninstallMarketplaceEntryOptions, "mcpSettingsPath"> = {},
): { name: string; deleted: boolean } {
	const name = resolveMarketplaceMcpServerName(entry);
	const settingsPath = options.mcpSettingsPath ?? resolveMcpSettingsPath();
	const deleted = updateMcpSettingsFileSync(settingsPath, (settings) => {
		const servers =
			settings.mcpServers &&
			typeof settings.mcpServers === "object" &&
			!Array.isArray(settings.mcpServers)
				? (settings.mcpServers as Record<string, unknown>)
				: {};
		const hadServer = Object.hasOwn(servers, name);
		if (hadServer) {
			delete servers[name];
		}
		settings.mcpServers = servers;
		return hadServer;
	});
	return { name, deleted };
}

export function getMarketplaceSkillCandidates(
	entry: MarketplaceEntryInput,
): string[] {
	const candidates = new Set<string>();
	const addCandidate = (value: string | undefined) => {
		const normalized = sanitizeSkillSegment(value ?? "");
		if (normalized && normalized !== "skill") {
			candidates.add(normalized);
		}
	};
	addCandidate(entry.id);
	addCandidate(entry.name);
	const installArgs = getMarketplaceEntryArgs(entry);
	for (let index = 0; index < installArgs.length; index++) {
		const arg = installArgs[index];
		if ((arg === "--skill" || arg === "-s") && installArgs[index + 1]) {
			addCandidate(installArgs[index + 1]);
			index++;
			continue;
		}
		const skillFilter = arg.split("@").at(1);
		if (skillFilter) {
			addCandidate(skillFilter);
		}
	}
	return [...candidates];
}

export function getGlobalMarketplaceSkillPaths(skillName: string): string[] {
	return [
		join(resolveClineDir(), "skills", skillName, "SKILL.md"),
		join(resolveHomeDir(), ".agents", "skills", skillName, "SKILL.md"),
	].filter((path, index, paths) => paths.indexOf(path) === index);
}

export function findInstalledGlobalMarketplaceSkillName(
	entry: MarketplaceEntryInput,
): string | undefined {
	if (entry.type !== "skill") return undefined;
	return getMarketplaceSkillCandidates(entry).find((candidate) =>
		getGlobalMarketplaceSkillPaths(candidate).some((path) => existsSync(path)),
	);
}

export function isMarketplaceSkillInstalled(
	entry: MarketplaceEntryInput,
): boolean {
	return findInstalledGlobalMarketplaceSkillName(entry) !== undefined;
}

function removeRemainingMarketplaceSkillPaths(
	entry: MarketplaceEntryInput,
): string[] {
	const removedPaths: string[] = [];
	if (entry.type !== "skill") return removedPaths;
	for (const candidate of getMarketplaceSkillCandidates(entry)) {
		for (const skillPath of getGlobalMarketplaceSkillPaths(candidate)) {
			if (!existsSync(skillPath)) continue;
			const skillDir = dirname(skillPath);
			rmSync(skillDir, { recursive: true, force: true });
			removedPaths.push(skillDir);
		}
	}
	return removedPaths;
}

export async function uninstallMarketplaceSkill(
	entry: MarketplaceEntryInput,
	options: Pick<UninstallMarketplaceEntryOptions, "spawnCommand"> = {},
): Promise<MarketplaceActionResult> {
	const installedName = findInstalledGlobalMarketplaceSkillName(entry);
	if (!installedName) {
		return {
			id: entry.id,
			type: "skill",
			status: "uninstalled",
			message: `${entry.name ?? entry.id} is not installed.`,
		};
	}
	const command = "npx";
	const commandArgs = [
		"-y",
		"skills@latest",
		"remove",
		installedName,
		"-g",
		"-y",
	];
	const displayCommand = formatCommand(command, commandArgs);
	const spawnCommand = options.spawnCommand ?? defaultMarketplaceSpawnCommand;
	let result: MarketplaceSpawnResult;
	try {
		result = await spawnCommand(command, commandArgs);
	} catch (error) {
		throw new Error(
			`Failed to start ${entry.name ?? entry.id} uninstall command:\n${displayCommand}\n${
				error instanceof Error ? error.message : String(error)
			}`,
		);
	}
	const output = commandOutput(result);
	if (result.exitCode !== 0) {
		throw new Error(
			`${entry.name ?? entry.id} uninstall failed with exit code ${result.exitCode}.\nCommand:\n${displayCommand}${
				output ? `\n\n${output}` : ""
			}`,
		);
	}
	const removedPaths = removeRemainingMarketplaceSkillPaths(entry);
	if (isMarketplaceSkillInstalled(entry)) {
		throw new Error(
			`Skill uninstall completed, but ${entry.name ?? entry.id} is still present in Cline's global skills directories.`,
		);
	}
	return {
		id: entry.id,
		type: "skill",
		status: "uninstalled",
		message: `Uninstalled ${entry.name ?? entry.id}.`,
		output:
			[output, ...removedPaths.map((path) => `Removed: ${path}`)]
				.filter(Boolean)
				.join("\n") || undefined,
	};
}

export async function uninstallMarketplacePlugin(
	entry: MarketplaceEntryInput,
	options: Pick<UninstallMarketplaceEntryOptions, "workspaceRoot"> = {},
): Promise<MarketplaceActionResult> {
	const [source] = getMarketplaceEntryArgs(entry);
	const target = source?.trim() || entry.id;
	if (!target) {
		throw new Error("Plugin marketplace uninstalls require a plugin name.");
	}
	const result = await uninstallPlugin({
		name: target,
		workspaceRoot: options.workspaceRoot,
	});
	return {
		id: entry.id,
		type: "plugin",
		status: "uninstalled",
		message: `Uninstalled ${entry.name ?? result.name ?? entry.id}.`,
		output: [
			`Path: ${result.installPath}`,
			...result.removedPaths.map((path) => `Removed: ${path}`),
		].join("\n"),
	};
}

export async function uninstallMarketplaceEntry(
	entry: MarketplaceEntryInput,
	options: UninstallMarketplaceEntryOptions = {},
): Promise<MarketplaceActionResult> {
	if (entry.type === "mcp") {
		const name = resolveMarketplaceMcpServerName(entry);
		if (options.deleteMcpServer) {
			await options.deleteMcpServer(name);
		} else {
			uninstallMarketplaceMcpServerFromSettings(entry, options);
		}
		return {
			id: entry.id,
			type: entry.type,
			status: "uninstalled",
			message: `Uninstalled ${entry.name ?? name ?? entry.id}.`,
		};
	}
	if (entry.type === "skill") {
		return uninstallMarketplaceSkill(entry, options);
	}
	if (entry.type === "plugin") {
		return uninstallMarketplacePlugin(entry, options);
	}
	throw new Error(`Unsupported marketplace entry type: ${entry.type}`);
}

import {
	existsSync,
	mkdtempSync,
	readFileSync,
	rmSync,
	writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import {
	buildMcpInstallTransport,
	installMcpServer,
	parseMcpInstallArgs,
} from "./mcp-install";

describe("MCP install service", () => {
	let root = "";

	beforeEach(() => {
		root = mkdtempSync(join(tmpdir(), "core-mcp-install-"));
	});

	afterEach(() => {
		rmSync(root, { recursive: true, force: true });
	});

	function readSettings(settingsPath: string): Record<string, unknown> & {
		mcpServers?: Record<string, { transport?: unknown }>;
	} {
		return JSON.parse(readFileSync(settingsPath, "utf8")) as Record<
			string,
			unknown
		> & {
			mcpServers?: Record<string, { transport?: unknown }>;
		};
	}

	it("builds stdio installs without shell-joining command args", () => {
		expect(
			buildMcpInstallTransport({
				name: "fs",
				targetArgs: [
					"npx",
					"-y",
					"@modelcontextprotocol/server-filesystem",
					"/tmp/my dir",
				],
			}),
		).toEqual({
			name: "fs",
			transport: {
				type: "stdio",
				command: "npx",
				args: ["-y", "@modelcontextprotocol/server-filesystem", "/tmp/my dir"],
			},
			warnings: [],
		});
	});

	it("installs remote MCP servers with headers into the settings file", () => {
		const settingsPath = join(root, "cline_mcp_settings.json");
		const result = installMcpServer({
			name: "docs",
			transport: "http",
			headers: ["Authorization: Bearer <token>"],
			targetArgs: ["https://example.com/mcp", "--header=X-Extra: yes"],
			settingsPath,
		});

		expect(result).toEqual({
			name: "docs",
			status: "installed",
			transport: {
				type: "streamableHttp",
				url: "https://example.com/mcp",
				headers: {
					Authorization: "Bearer <token>",
					"X-Extra": "yes",
				},
			},
			warnings: [
				'Header "Authorization" looks like it contains a placeholder. Update it in MCP settings before using this server.',
			],
		});
		expect(readSettings(settingsPath).mcpServers?.docs).toEqual({
			transport: result.transport,
		});
	});

	it("parses marketplace-style MCP install args in core", () => {
		expect(
			parseMcpInstallArgs([
				"docs",
				"--transport=http",
				"https://example.com/mcp",
				"--header",
				"Authorization: Bearer <token>",
				"--header=X-Extra: yes",
			]),
		).toEqual({
			name: "docs",
			transport: "http",
			targetArgs: ["https://example.com/mcp"],
			headers: ["Authorization: Bearer <token>", "X-Extra: yes"],
		});

		expect(() => parseMcpInstallArgs([])).toThrow(
			/Marketplace MCP install args/,
		);
	});

	it("keeps transport-like values as stdio command args for direct builder input", () => {
		expect(
			buildMcpInstallTransport({
				name: "custom",
				targetArgs: ["node", "server.js", "--transport", "ipc"],
			}).transport,
		).toEqual({
			type: "stdio",
			command: "node",
			args: ["server.js", "--transport", "ipc"],
		});
	});

	it("preserves existing MCP settings while adding a server", () => {
		const settingsPath = join(root, "cline_mcp_settings.json");
		writeFileSync(
			settingsPath,
			JSON.stringify(
				{
					mcpServers: {
						existing: {
							transport: { type: "stdio", command: "node" },
							disabled: true,
						},
					},
					customTopLevelKey: true,
				},
				null,
				2,
			),
			"utf8",
		);

		installMcpServer({
			name: "new-server",
			targetArgs: ["node", "server.js"],
			settingsPath,
		});

		const written = readSettings(settingsPath);
		expect(written.customTopLevelKey).toBe(true);
		expect(written.mcpServers).toMatchObject({
			existing: {
				transport: { type: "stdio", command: "node" },
				disabled: true,
			},
			"new-server": {
				transport: {
					type: "stdio",
					command: "node",
					args: ["server.js"],
				},
			},
		});
	});

	it("creates a missing settings file on first install", () => {
		const settingsPath = join(root, "nested", "settings.json");

		installMcpServer({
			name: "fs",
			targetArgs: ["node", "server.js"],
			settingsPath,
		});

		expect(existsSync(settingsPath)).toBe(true);
		expect(readSettings(settingsPath).mcpServers?.fs).toEqual({
			transport: {
				type: "stdio",
				command: "node",
				args: ["server.js"],
			},
		});
	});

	it("rejects invalid install arguments before writing settings", () => {
		const settingsPath = join(root, "settings.json");

		expect(() =>
			installMcpServer({
				name: "fs",
				settingsPath,
			}),
		).toThrow(/requires a command/);
		expect(() =>
			installMcpServer({
				name: "bad",
				transport: "http",
				targetArgs: ["file:///tmp/server"],
				settingsPath,
			}),
		).toThrow(/only http and https are supported/);
		expect(existsSync(settingsPath)).toBe(false);
	});
});

import type { McpServerTransportConfig } from "../extensions/mcp";
import {
	resolveDefaultMcpSettingsPath,
	updateMcpSettingsFileSync,
} from "../extensions/mcp";

export interface McpInstallOptions {
	name: string;
	headers?: string[];
	targetArgs?: string[];
	transport?: string;
	settingsPath?: string;
}

export interface McpInstallResult {
	name: string;
	status: "installed";
	transport: McpServerTransportConfig;
	warnings: string[];
}

function normalizeTransportType(
	value: string | undefined,
): McpServerTransportConfig["type"] {
	const normalized = (value ?? "stdio").trim();
	if (normalized === "http" || normalized === "streamable-http") {
		return "streamableHttp";
	}
	if (
		normalized === "stdio" ||
		normalized === "sse" ||
		normalized === "streamableHttp"
	) {
		return normalized;
	}
	throw new Error(
		`Unsupported MCP transport "${normalized}". Expected stdio, sse, http, streamable-http, or streamableHttp.`,
	);
}

function assertValidUrl(url: string): void {
	let parsed: URL;
	try {
		parsed = new URL(url);
	} catch {
		throw new Error(`Invalid MCP server URL: ${url}`);
	}
	if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
		throw new Error(
			`Invalid MCP server URL: ${url} (only http and https are supported)`,
		);
	}
}

function parseHeader(value: string): [string, string] {
	const separatorIndex = value.indexOf(":");
	if (separatorIndex <= 0) {
		throw new Error(
			`Invalid MCP header "${value}". Expected "Header-Name: header value".`,
		);
	}
	const name = value.slice(0, separatorIndex).trim();
	const headerValue = value.slice(separatorIndex + 1).trim();
	if (!name || !headerValue) {
		throw new Error(
			`Invalid MCP header "${value}". Expected "Header-Name: header value".`,
		);
	}
	if (!/^[!#$%&'*+\-.^_`|~0-9A-Za-z]+$/.test(name)) {
		throw new Error(`Invalid MCP header name "${name}".`);
	}
	return [name, headerValue];
}

function containsPlaceholder(value: string): boolean {
	const openIndex = value.indexOf("<");
	return openIndex >= 0 && value.indexOf(">", openIndex + 1) > openIndex + 1;
}

function splitTargetArgsAndHeaders(input: {
	headers?: string[];
	parseTransport?: boolean;
	targetArgs?: string[];
	transport?: string;
}): { headers: string[]; targetArgs: string[]; transport?: string } {
	const headers = [...(input.headers ?? [])];
	const targetArgs: string[] = [];
	let transport = input.transport;
	const args = input.targetArgs ?? [];
	for (let index = 0; index < args.length; index++) {
		const arg = args[index];
		if (input.parseTransport && arg === "--transport") {
			const value = args[index + 1];
			if (!value) {
				throw new Error("--transport requires a value");
			}
			transport = value;
			index++;
			continue;
		}
		if (input.parseTransport && arg?.startsWith("--transport=")) {
			transport = arg.slice("--transport=".length);
			continue;
		}
		if (arg === "--header") {
			const value = args[index + 1];
			if (!value) {
				throw new Error("--header requires a value");
			}
			headers.push(value);
			index++;
			continue;
		}
		if (arg?.startsWith("--header=")) {
			headers.push(arg.slice("--header=".length));
			continue;
		}
		targetArgs.push(arg);
	}
	return { headers, targetArgs, transport };
}

function buildHeaders(values: string[]): {
	headers?: Record<string, string>;
	warnings: string[];
} {
	if (values.length === 0) return { warnings: [] };
	const headers: Record<string, string> = {};
	const warnings: string[] = [];
	for (const value of values) {
		const [name, headerValue] = parseHeader(value);
		headers[name] = headerValue;
		if (containsPlaceholder(headerValue)) {
			warnings.push(
				`Header "${name}" looks like it contains a placeholder. Update it in MCP settings before using this server.`,
			);
		}
	}
	return { headers, warnings };
}

export function buildMcpInstallTransport(options: {
	headers?: string[];
	name: string;
	targetArgs?: string[];
	transport?: string;
}): { name: string; transport: McpServerTransportConfig; warnings: string[] } {
	const name = options.name.trim();
	if (!name) {
		throw new Error("MCP server name is required");
	}
	const {
		headers: rawHeaders,
		targetArgs,
		transport,
	} = splitTargetArgsAndHeaders({
		headers: options.headers,
		targetArgs: options.targetArgs,
		transport: options.transport,
	});
	const type = normalizeTransportType(transport);
	const { headers, warnings } = buildHeaders(rawHeaders);
	if (type === "stdio") {
		if (rawHeaders.length > 0) {
			throw new Error("Stdio MCP installs do not support request headers.");
		}
		const [command, ...args] = targetArgs;
		if (!command?.trim()) {
			throw new Error(
				"Stdio MCP install requires a command after the server name, for example: cline mcp install fs --yes -- npx -y @modelcontextprotocol/server-filesystem /tmp",
			);
		}
		return {
			name,
			transport: {
				type,
				command,
				args: args.length > 0 ? args : undefined,
			},
			warnings,
		};
	}

	if (targetArgs.length !== 1) {
		throw new Error(
			"Remote MCP install requires exactly one URL argument after the server name.",
		);
	}
	const url = targetArgs[0]?.trim() ?? "";
	assertValidUrl(url);
	return {
		name,
		transport: headers ? { type, url, headers } : { type, url },
		warnings,
	};
}

export function parseMcpInstallArgs(args: string[]): McpInstallOptions {
	const [name, ...targetArgs] = args;
	if (!name) {
		throw new Error(
			"Marketplace MCP install args must start with a server name.",
		);
	}
	return {
		name,
		...splitTargetArgsAndHeaders({
			parseTransport: true,
			targetArgs,
		}),
	};
}

function addMcpServer(
	name: string,
	transport: McpServerTransportConfig,
	settingsPath: string,
): void {
	updateMcpSettingsFileSync(settingsPath, (settings) => {
		const serversValue = settings.mcpServers;
		const servers =
			serversValue &&
			typeof serversValue === "object" &&
			!Array.isArray(serversValue)
				? { ...(serversValue as Record<string, unknown>) }
				: {};
		servers[name] = { transport };
		settings.mcpServers = servers;
	});
}

export function installMcpServer(options: McpInstallOptions): McpInstallResult {
	const { name, transport, warnings } = buildMcpInstallTransport(options);
	addMcpServer(
		name,
		transport,
		options.settingsPath ?? resolveDefaultMcpSettingsPath(),
	);
	return {
		name,
		status: "installed",
		transport,
		warnings,
	};
}

