			resolveLocalClineAuthToken({
				provider: "cline" as never,
				auth: { accessToken: "tok123" },
			}),
		).toBe("tok123");
	});

	it("falls back to apiKey when accessToken is absent", () => {
		expect(
			resolveLocalClineAuthToken({
				provider: "cline" as never,
				apiKey: "api-key-456",
			}),
		).toBe("api-key-456");
	});

	it("prefers accessToken over apiKey", () => {
		expect(
			resolveLocalClineAuthToken({
				provider: "cline" as never,
				apiKey: "api-key",
				auth: { accessToken: "access-token" },
