import * as LlmsModels from "@cline/llms";
import { isOAuthProvider } from "../../auth/provider-auth-registry";

export type ProviderConfigFieldKey =
	| "apiKey"
	| "baseUrl"
	| "azureApiVersion"
	| "awsRegion"
	| "awsProfile"
	| "gcpProjectId"
	| "gcpRegion"
	| "sapClientId"
	| "sapClientSecret"
	| "sapTokenUrl"
	| "sapResourceGroup"
	| "sapDeploymentId";

export interface ProviderConfigFieldRequirement {
	defaultValue?: string;
	label?: string;
	note?: string;
	placeholder?: string;
	optional?: boolean;
}

export interface ProviderConfigFields {
	providerId: string;
	authMethod: "api-key" | "oauth" | "local";
	fields: Partial<
		Record<ProviderConfigFieldKey, ProviderConfigFieldRequirement>
	>;
	/** Optional description shown above the fields (e.g. AWS region auto-fill hint). */
	description?: string;
}

const FIELD_KEYS: ProviderConfigFieldKey[] = [
	"apiKey",
	"baseUrl",
	"azureApiVersion",
	"awsRegion",
	"awsProfile",
	"gcpProjectId",
	"gcpRegion",
	"sapClientId",
	"sapClientSecret",
	"sapTokenUrl",
	"sapResourceGroup",
	"sapDeploymentId",
];

interface ProviderConfigFieldMetadata {
	description?: string;
	fields: Partial<
		Record<ProviderConfigFieldKey, ProviderConfigFieldRequirement>
	>;
	mode?: "merge" | "replace";
}

