import { basename, resolve } from "node:path";
import { performance } from "node:perf_hooks";
import type { WorkspaceInfo } from "@cline/shared";
import { processWorkspaceInfo } from "@cline/shared";
import simpleGit from "simple-git";

export interface WorkspaceInfoDiagnostics {
	info: WorkspaceInfo;
	vcsType: "git" | "none";
	gitState: GitWorkspaceState;
	error?: { errorType: string; message: string };
}

export interface BuiltWorkspaceMetadata {
	workspaceInfo: WorkspaceInfo;
	workspaceMetadata: string;
	durationMs: number;
	vcsType: "git" | "none";
	gitState: GitWorkspaceState;
	initError?: { errorType: string; message: string };
}

export interface GitWorkspaceState {
	url?: string;
	branch?: string;
}

export function readSessionGitMetadata(
	metadata: Record<string, unknown> | undefined,
): GitWorkspaceState {
	const git = metadata?.git;
	if (!git || typeof git !== "object" || Array.isArray(git)) return {};
	const record = git as Record<string, unknown>;
	return {
		...(typeof record.url === "string" && record.url.trim()
			? { url: record.url.trim() }
			: {}),
		...(typeof record.branch === "string" && record.branch.trim()
			? { branch: record.branch.trim() }
			: {}),
	};
}

export function withSessionGitMetadata(
	metadata: Record<string, unknown> | undefined,
	state: GitWorkspaceState,
): Record<string, unknown> | undefined {
	const next = { ...(metadata ?? {}) };
	if (!state.url && !state.branch) {
		delete next.git;
		return Object.keys(next).length > 0 ? next : undefined;
	}
	const existingGit =
		next.git && typeof next.git === "object" && !Array.isArray(next.git)
			? (next.git as Record<string, unknown>)
			: {};
	const git = { ...existingGit };
	if (state.url) git.url = state.url;
	else delete git.url;
	if (state.branch) git.branch = state.branch;
	else delete git.branch;
	next.git = git;
	return next;
}

export function hasCurrentSessionGitMetadata(
	metadata: Record<string, unknown> | undefined,
	state: GitWorkspaceState,
): boolean {
	const current = readSessionGitMetadata(metadata);
	return current.url === state.url && current.branch === state.branch;
}

function selectPrimaryGitRemoteUrl(
	remotes: ReadonlyArray<{
		name: string;
		refs: { fetch: string; push: string };
	}>,
): string | undefined {
	const remote = remotes.find(({ name }) => name === "origin") ?? remotes[0];
	return (remote?.refs.fetch || remote?.refs.push)?.trim() || undefined;
}

export function normalizeWorkspacePath(workspacePath: string): string {
	return resolve(workspacePath);
}

export async function generateWorkspaceInfo(
	workspacePath: string,
): Promise<WorkspaceInfo> {
	return (await generateWorkspaceInfoWithDiagnostics(workspacePath)).info;
}

/**
 * Git failures that reflect a normal repository state — e.g. a freshly
 * initialized repo with no commits, where `git rev-parse HEAD` fails —
 * rather than a broken workspace. These must not be reported as
 * workspace init errors.
 */
function isBenignGitError(error: unknown): boolean {
	const message = error instanceof Error ? error.message : String(error);
	// Deliberately excludes "bad revision": that can also indicate a corrupt
	// .git/HEAD, which is a genuinely broken workspace worth reporting.
	return /unknown revision|ambiguous argument|does not have any commits yet/i.test(
		message,
	);
}

function toWorkspaceInfoError(error: unknown): {
	errorType: string;
	message: string;
} {
	if (error instanceof Error) {
		return {
			errorType: error.name?.trim() || error.constructor.name || "Error",
			message: error.message,
		};
	}
	return { errorType: "Error", message: String(error) };
}

export async function generateWorkspaceInfoWithDiagnostics(
	workspacePath: string,
): Promise<WorkspaceInfoDiagnostics> {
	const rootPath = normalizeWorkspacePath(workspacePath);
	const info: WorkspaceInfo = {
		rootPath,
		// basename("/") and basename("C:\\") are "", which WorkspaceInfoSchema
		// rejects — omit the hint for root paths instead.
		hint: basename(rootPath) || undefined,
	};
	const gitState: GitWorkspaceState = {};
	let firstError: { errorType: string; message: string } | undefined;

	try {
		const git = simpleGit({ baseDir: rootPath });
		const isRepo = await git.checkIsRepo();
		if (!isRepo) {
			return { info, vcsType: "none", gitState };
		}

		try {
			const remotes = await git.getRemotes(true);
			if (remotes.length > 0) {
				const associatedRemoteUrls = remotes.map((remote) => {
					const remoteUrl = remote.refs.fetch || remote.refs.push;
					return `${remote.name}: ${remoteUrl}`;
				});
				info.associatedRemoteUrls = associatedRemoteUrls;
				const url = selectPrimaryGitRemoteUrl(remotes);
				if (url) gitState.url = url;
			}
		} catch (error) {
			firstError ??= toWorkspaceInfoError(error);
		}

		try {
			const latestGitCommitHash = (await git.revparse(["HEAD"])).trim();
			if (latestGitCommitHash.length > 0) {
				info.latestGitCommitHash = latestGitCommitHash;
			}
		} catch (error) {
			if (!isBenignGitError(error)) {
				firstError ??= toWorkspaceInfoError(error);
			}
		}

		try {
			const latestGitBranchName = (await git.branch()).current.trim();
			if (latestGitBranchName.length > 0) {
				info.latestGitBranchName = latestGitBranchName;
				gitState.branch = latestGitBranchName;
			}
		} catch (error) {
			if (!isBenignGitError(error)) {
				firstError ??= toWorkspaceInfoError(error);
			}
		}

		return { info, vcsType: "git", gitState, error: firstError };
	} catch (error) {
		// Non-git workspaces keep only path + hint.
		return {
			info,
			vcsType: "none",
			gitState,
			error: toWorkspaceInfoError(error),
		};
	}
}

/** Read the mutable git identity persisted with an active session. */
export async function readGitWorkspaceState(
	workspacePath: string,
): Promise<GitWorkspaceState | undefined> {
	try {
		const git = simpleGit({ baseDir: normalizeWorkspacePath(workspacePath) });
		if (!(await git.checkIsRepo())) return {};
		const [remotes, branchSummary] = await Promise.all([
			git.getRemotes(true),
			git.branch(),
		]);
		const url = selectPrimaryGitRemoteUrl(remotes);
		const branch = branchSummary.current.trim();
		return {
			...(url ? { url } : {}),
			...(branch ? { branch } : {}),
		};
	} catch {
		return undefined;
	}
}

export async function buildWorkspaceMetadata(cwd: string): Promise<string> {
	const workspaceInfo = await generateWorkspaceInfo(cwd);
	return processWorkspaceInfo(workspaceInfo);
}

/**
 * Generate workspace metadata as both a structured `WorkspaceInfo` object and
 * its pre-serialized string form.
 *
 * Use this instead of calling `buildWorkspaceMetadata` + `generateWorkspaceInfo`
 * separately so the git I/O only happens once.
 */
export async function buildWorkspaceMetadataWithInfo(
	cwd: string,
): Promise<BuiltWorkspaceMetadata> {
	const startedAt = performance.now();
	const diagnostics = await generateWorkspaceInfoWithDiagnostics(cwd);
	const durationMs = performance.now() - startedAt;
	const workspaceInfo = diagnostics.info;
	return {
		workspaceInfo,
		workspaceMetadata: processWorkspaceInfo(workspaceInfo),
		durationMs,
		vcsType: diagnostics.vcsType,
		gitState: diagnostics.gitState,
		initError: diagnostics.error,
	};
}

import type { ITelemetryService } from "@cline/shared";
import { afterEach, beforeEach, describe, expect, test, vi } from "vitest";
import {
	emitWorkspaceLifecycleTelemetry,
	resetWorkspaceTelemetryForTests,
} from "./workspace-telemetry";

interface TelemetryStub {
	telemetry: ITelemetryService;
	capture: ReturnType<typeof vi.fn>;
	captureRequired: ReturnType<typeof vi.fn>;
}

function createTelemetryStub(): TelemetryStub {
	const capture = vi.fn();
	const captureRequired = vi.fn();
	const telemetry = {
		capture,
		captureRequired,
		setDistinctId: vi.fn(),
		updateCommonProperties: vi.fn(),
		identify: vi.fn(),
	} as unknown as ITelemetryService;
	return { telemetry, capture, captureRequired };
}

function findCalls(
	stub: TelemetryStub,
	event: string,
): { event: string; properties?: Record<string, unknown> }[] {
	return stub.capture.mock.calls
		.filter(([arg]) => (arg as { event: string }).event === event)
		.map(
			([arg]) => arg as { event: string; properties?: Record<string, unknown> },
		);
}

describe("emitWorkspaceLifecycleTelemetry", () => {
	beforeEach(() => {
		resetWorkspaceTelemetryForTests();
	});

	afterEach(() => {
		resetWorkspaceTelemetryForTests();
	});

	test("emits workspace.initialized once per process per workspace path", () => {
		const stub = createTelemetryStub();
		emitWorkspaceLifecycleTelemetry({
			telemetry: stub.telemetry,
			rootPath: "/tmp/repo",
			vcsType: "git",
			rootCount: 1,
			durationMs: 12,
		});
		emitWorkspaceLifecycleTelemetry({
			telemetry: stub.telemetry,
			rootPath: "/tmp/repo",
			vcsType: "git",
			rootCount: 1,
			durationMs: 12,
		});
		const initialized = findCalls(stub, "workspace.initialized");
		expect(initialized).toHaveLength(1);
	});

	test("emits separate workspace.initialized events for distinct paths", () => {
		const stub = createTelemetryStub();
		emitWorkspaceLifecycleTelemetry({
			telemetry: stub.telemetry,
			rootPath: "/tmp/repo-a",
			vcsType: "git",
			rootCount: 1,
		});
		emitWorkspaceLifecycleTelemetry({
			telemetry: stub.telemetry,
			rootPath: "/tmp/repo-b",
			vcsType: "none",
			rootCount: 1,
		});
		expect(findCalls(stub, "workspace.initialized")).toHaveLength(2);
	});

	test("emits workspace.init_error only when diagnostics report a failure", () => {
		const stub = createTelemetryStub();
		emitWorkspaceLifecycleTelemetry({
			telemetry: stub.telemetry,
			rootPath: "/tmp/healthy",
			vcsType: "git",
		});
		expect(findCalls(stub, "workspace.init_error")).toHaveLength(0);

		emitWorkspaceLifecycleTelemetry({
			telemetry: stub.telemetry,
			rootPath: "/tmp/broken",
			vcsType: "none",
			initError: { errorType: "GitProbeError", message: "permission denied" },
		});
		const errors = findCalls(stub, "workspace.init_error");
		expect(errors).toHaveLength(1);
		expect(errors[0]?.properties?.error_type).toBe("GitProbeError");
		expect(errors[0]?.properties?.fallback_to_single_root).toBe(true);
	});

	test("does not emit raw workspace path in event properties", () => {
		const stub = createTelemetryStub();
		const rootPath = "/tmp/super-secret-repo-name";
		emitWorkspaceLifecycleTelemetry({
			telemetry: stub.telemetry,
			rootPath,
			vcsType: "git",
			rootCount: 1,
		});
		expect(stub.captureRequired).not.toHaveBeenCalled();
		for (const call of stub.capture.mock.calls) {
			const arg = call[0] as {
				event: string;
				properties?: Record<string, unknown>;
			};
			expect(JSON.stringify(arg.properties ?? {})).not.toContain(rootPath);
		}
	});

	test("emits derived has_git/has_mercurial/is_multi_root flags", () => {
		const stub = createTelemetryStub();
		emitWorkspaceLifecycleTelemetry({
			telemetry: stub.telemetry,
			rootPath: "/tmp/multi",
			rootCount: 2,
			vcsTypes: ["git", "hg"],
		});
		const initialized = findCalls(stub, "workspace.initialized");
		expect(initialized).toHaveLength(1);
		const props = initialized[0]?.properties as Record<string, unknown>;
		expect(props.is_multi_root).toBe(true);
		expect(props.has_git).toBe(true);
		expect(props.has_mercurial).toBe(true);
		expect(props.vcs_types).toEqual(["git", "hg"]);
	});

	test("no-ops when telemetry is undefined", () => {
		expect(() =>
			emitWorkspaceLifecycleTelemetry({
				telemetry: undefined,
				rootPath: "/tmp/quiet",
				vcsType: "none",
			}),
		).not.toThrow();
	});

	test("resetWorkspaceTelemetryForTests clears the dedup cache", () => {
		const stub = createTelemetryStub();
		emitWorkspaceLifecycleTelemetry({
			telemetry: stub.telemetry,
			rootPath: "/tmp/repo",
			vcsType: "git",
		});
		resetWorkspaceTelemetryForTests();
		emitWorkspaceLifecycleTelemetry({
			telemetry: stub.telemetry,
			rootPath: "/tmp/repo",
			vcsType: "git",
		});
		expect(findCalls(stub, "workspace.initialized")).toHaveLength(2);
	});
});

import { createHash } from "node:crypto";
import type { ITelemetryService, WorkspaceInfo } from "@cline/shared";
import {
	captureWorkspaceInitError,
	captureWorkspaceInitialized,
} from "../telemetry/core-events";

export interface WorkspaceLifecycleTelemetryInput {
	telemetry?: ITelemetryService;
	rootPath: string;
	workspaceInfo?: WorkspaceInfo;
	rootCount?: number;
	vcsType?: "git" | "none";
	vcsTypes?: ReadonlyArray<string>;
	durationMs?: number;
	initError?: { errorType: string; message: string };
	featureFlagEnabled?: boolean;
	isRemoteWorkspace?: boolean;
}

const initializedWorkspaceHashes = new Set<string>();
const initErrorWorkspaceHashes = new Set<string>();

function hashWorkspacePath(rootPath: string): string {
	return createHash("sha256").update(rootPath).digest("hex");
}

function normalizeVcsTypes(
	input: WorkspaceLifecycleTelemetryInput,
): ReadonlyArray<string> {
	if (input.vcsTypes && input.vcsTypes.length > 0) {
		return input.vcsTypes;
	}
	return [input.vcsType === "git" ? "git" : "none"];
}

export function emitWorkspaceLifecycleTelemetry(
	input: WorkspaceLifecycleTelemetryInput,
): void {
	if (!input.telemetry) {
		return;
	}
	const workspaceHash = hashWorkspacePath(input.rootPath);
	const rootCount = input.rootCount ?? 1;
	if (!initializedWorkspaceHashes.has(workspaceHash)) {
		initializedWorkspaceHashes.add(workspaceHash);
		captureWorkspaceInitialized(input.telemetry, {
			root_count: rootCount,
			vcs_types: normalizeVcsTypes(input),
			init_duration_ms: input.durationMs,
			feature_flag_enabled: input.featureFlagEnabled ?? true,
			is_remote_workspace: input.isRemoteWorkspace,
		});
	}

	if (input.initError && !initErrorWorkspaceHashes.has(workspaceHash)) {
		initErrorWorkspaceHashes.add(workspaceHash);
		const error = new Error(input.initError.message);
		error.name = input.initError.errorType || "Error";
		captureWorkspaceInitError(input.telemetry, error, {
			fallback_to_single_root: true,
			workspace_count: rootCount,
		});
	}
}

export function resetWorkspaceTelemetryForTests(): void {
	initializedWorkspaceHashes.clear();
	initErrorWorkspaceHashes.clear();
}

import { execFileSync } from "node:child_process";
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import {
	buildCheckpointWorkspaceDiff,
	compareCheckpointToWorkspace,
	createCheckpointComparePlan,
} from "./checkpoint-diff";

function git(cwd: string, args: string[]): string {
	return execFileSync("git", ["-C", cwd, ...args], {
		encoding: "utf8",
		stdio: ["ignore", "pipe", "pipe"],
	}).trim();
}

describe("checkpoint workspace comparison", () => {
	let dir = "";
	let checkpointRef = "";

	beforeEach(() => {
		dir = mkdtempSync(join(tmpdir(), "core-checkpoint-diff-"));
		mkdirSync(dir, { recursive: true });
		git(dir, ["init"]);
		git(dir, ["config", "user.name", "Cline Test"]);
		git(dir, ["config", "user.email", "cline@example.com"]);
		writeFileSync(join(dir, "tracked.txt"), "base\n", "utf8");
		writeFileSync(join(dir, "deleted.txt"), "delete me\n", "utf8");
		git(dir, ["add", "."]);
		git(dir, ["commit", "-m", "initial"]);
		checkpointRef = git(dir, ["rev-parse", "HEAD"]);
	});

	afterEach(() => {
		rmSync(dir, { recursive: true, force: true });
	});

	it("builds content diffs from a checkpoint ref to the current worktree", async () => {
		writeFileSync(join(dir, "tracked.txt"), "changed\n", "utf8");
		rmSync(join(dir, "deleted.txt"));
		writeFileSync(join(dir, "untracked.txt"), "new file\n", "utf8");

		const diffs = await buildCheckpointWorkspaceDiff(dir, {
			ref: checkpointRef,
			createdAt: Date.now(),
			runCount: 1,
			kind: "commit",
		});

		expect(diffs.map((diff) => diff.filePath.replaceAll("\\", "/"))).toEqual([
			join(dir, "deleted.txt").replaceAll("\\", "/"),
			join(dir, "tracked.txt").replaceAll("\\", "/"),
			join(dir, "untracked.txt").replaceAll("\\", "/"),
		]);
		expect(
			diffs.find((diff) => diff.filePath.endsWith("tracked.txt")),
		).toMatchObject({
			leftContent: "base\n",
			rightContent: "changed\n",
		});
		expect(
			diffs.find((diff) => diff.filePath.endsWith("deleted.txt")),
		).toMatchObject({
			leftContent: "delete me\n",
			rightContent: "",
		});
		expect(
			diffs.find((diff) => diff.filePath.endsWith("untracked.txt")),
		).toMatchObject({
			leftContent: "",
			rightContent: "new file\n",
		});
	});

	it("uses the worktree snapshot stored in SDK stash checkpoints", async () => {
		writeFileSync(join(dir, "tracked.txt"), "checkpoint dirty\n", "utf8");
		const stashRef = git(dir, ["stash", "create", "cline checkpoint test"]);
		writeFileSync(join(dir, "tracked.txt"), "current dirty\n", "utf8");

		const diffs = await buildCheckpointWorkspaceDiff(dir, {
			ref: stashRef,
			createdAt: Date.now(),
			runCount: 1,
			kind: "stash",
		});

		expect(diffs).toHaveLength(1);
		expect(diffs[0]).toMatchObject({
			filePath: join(dir, "tracked.txt"),
			leftContent: "checkpoint dirty\n",
			rightContent: "current dirty\n",
		});
	});

	it("selects the nearest checkpoint at or before the requested run", async () => {
		const session = {
			sessionId: "session-1",
			source: "cli",
			status: "running",
			startedAt: "2026-01-01T00:00:00.000Z",
			updatedAt: "2026-01-01T00:00:00.000Z",
			interactive: true,
			provider: "mock",
			model: "mock",
			cwd: dir,
			workspaceRoot: dir,
			enableTools: true,
			enableSpawn: true,
			enableTeams: true,
			isSubagent: false,
			metadata: {
				checkpoint: {
					latest: { ref: "bbbb", createdAt: 2, runCount: 3 },
					history: [
						{ ref: "aaaa", createdAt: 1, runCount: 1 },
						{ ref: "bbbb", createdAt: 2, runCount: 3 },
					],
				},
			},
		} as const;

		const plan = createCheckpointComparePlan({
			session,
			checkpointRunCount: 2,
		});

		expect(plan.checkpoint).toMatchObject({ ref: "aaaa", runCount: 1 });
		expect(plan.cwd).toBe(dir);
	});

	it("returns the compare plan and workspace diffs together", async () => {
		writeFileSync(join(dir, "tracked.txt"), "changed\n", "utf8");
		const session = {
			sessionId: "session-1",
			source: "cli",
			status: "running",
			startedAt: "2026-01-01T00:00:00.000Z",
			updatedAt: "2026-01-01T00:00:00.000Z",
			interactive: true,
			provider: "mock",
			model: "mock",
			cwd: dir,
			workspaceRoot: dir,
			enableTools: true,
			enableSpawn: true,
			enableTeams: true,
			isSubagent: false,
			metadata: {
				checkpoint: {
					latest: { ref: checkpointRef, createdAt: 1, runCount: 1 },
					history: [{ ref: checkpointRef, createdAt: 1, runCount: 1 }],
				},
			},
		} as const;

		const result = await compareCheckpointToWorkspace({
			session,
			checkpointRunCount: 1,
		});

		expect(result.checkpoint.ref).toBe(checkpointRef);
		expect(result.diffs).toHaveLength(1);
		expect(result.diffs[0]).toMatchObject({
			filePath: join(dir, "tracked.txt"),
			leftContent: "base\n",
			rightContent: "changed\n",
		});
	});
});

import { execFile as execFileCallback } from "node:child_process";
import * as fs from "node:fs/promises";
import * as path from "node:path";
import { promisify } from "node:util";
import type { CheckpointEntry } from "../hooks/checkpoint-hooks";
import type { SessionRecord } from "../types/sessions";
import {
	findCheckpointForRun,
	readSessionCheckpointHistory,
} from "./checkpoint-restore";

const execFile = promisify(execFileCallback);
const MAX_GIT_OUTPUT = 50 * 1024 * 1024;

export interface CheckpointContentDiff {
	filePath: string;
	leftContent: string;
	rightContent: string;
}

export interface CheckpointComparePlan {
	checkpoint: CheckpointEntry;
	cwd: string;
}

export interface CheckpointWorkspaceCompareResult
	extends CheckpointComparePlan {
	diffs: CheckpointContentDiff[];
}

async function runGit(cwd: string, args: string[]): Promise<string> {
	const { stdout } = await execFile("git", ["-C", cwd, ...args], {
		windowsHide: true,
		maxBuffer: MAX_GIT_OUTPUT,
		encoding: "utf8",
	});
	return stdout;
}

function parseNulList(output: string): string[] {
	return output.split("\0").filter(Boolean);
}

function resolveGitPath(cwd: string, relativePath: string): string {
	const absolutePath = path.resolve(cwd, relativePath);
	const relativeFromCwd = path.relative(cwd, absolutePath);
	if (relativeFromCwd.startsWith("..") || path.isAbsolute(relativeFromCwd)) {
		throw new Error(`Checkpoint diff path escapes workspace: ${relativePath}`);
	}
	return absolutePath;
}

async function readCheckpointFile(
	cwd: string,
	ref: string,
	relativePath: string,
): Promise<string> {
	try {
		return await runGit(cwd, ["show", `${ref}:${relativePath}`]);
	} catch {
		return "";
	}
}

async function readWorktreeFile(
	cwd: string,
	relativePath: string,
): Promise<string> {
	try {
		return await fs.readFile(resolveGitPath(cwd, relativePath), "utf8");
	} catch {
		return "";
	}
}

async function listChangedPaths(
	cwd: string,
	checkpoint: CheckpointEntry,
): Promise<string[]> {
	await runGit(cwd, ["cat-file", "-e", `${checkpoint.ref}^{tree}`]);
	const [trackedOutput, untrackedOutput] = await Promise.all([
		runGit(cwd, ["diff", "--name-only", "-z", checkpoint.ref, "--"]),
		runGit(cwd, ["ls-files", "--others", "--exclude-standard", "-z"]),
	]);
	const paths = new Set([
		...parseNulList(trackedOutput),
		...parseNulList(untrackedOutput),
	]);
	return [...paths].sort((a, b) => a.localeCompare(b));
}

export function createCheckpointComparePlan(input: {
	session: SessionRecord;
	checkpointRunCount: number;
	cwd?: string;
}): CheckpointComparePlan {
	const runCount = input.checkpointRunCount;
	if (!Number.isInteger(runCount) || runCount < 1) {
		throw new Error("checkpointRunCount must be a positive integer");
	}
	const checkpoint = findCheckpointForRun(
		readSessionCheckpointHistory(input.session),
		runCount,
	);
	if (!checkpoint) {
		throw new Error(
			`No checkpoint found at or before run ${runCount} in session ${input.session.sessionId}`,
		);
	}
	const cwd = (
		input.cwd?.trim() ||
		input.session.cwd ||
		input.session.workspaceRoot
	).trim();
	if (!cwd) {
		throw new Error("cwd or workspaceRoot is required to compare a checkpoint");
	}
	return { checkpoint, cwd };
}

export async function buildCheckpointWorkspaceDiff(
	cwd: string,
	checkpoint: CheckpointEntry,
): Promise<CheckpointContentDiff[]> {
	const changedPaths = await listChangedPaths(cwd, checkpoint);
	const diffs = await Promise.all(
		changedPaths.map(async (relativePath) => {
			const [leftContent, rightContent] = await Promise.all([
				readCheckpointFile(cwd, checkpoint.ref, relativePath),
				readWorktreeFile(cwd, relativePath),
			]);
			return {
				filePath: resolveGitPath(cwd, relativePath),
				leftContent,
				rightContent,
			};
		}),
	);
	return diffs.filter((diff) => diff.leftContent !== diff.rightContent);
}

export async function compareCheckpointToWorkspace(input: {
	session: SessionRecord;
	checkpointRunCount: number;
	cwd?: string;
}): Promise<CheckpointWorkspaceCompareResult> {
	const plan = createCheckpointComparePlan(input);
	const diffs = await buildCheckpointWorkspaceDiff(plan.cwd, plan.checkpoint);
	return { ...plan, diffs };
}

import { execFileSync } from "node:child_process";
import {
	existsSync,
	mkdirSync,
	mkdtempSync,
	readFileSync,
	rmSync,
	writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import {
	type CheckpointEntry,
	createCheckpointHooks,
} from "../hooks/checkpoint-hooks";
import {
	applyCheckpointToWorktree,
	beginWorktreeRestoreTransaction,
	createCheckpointRestorePlan,
	createRestoredCheckpointMetadata,
	trimMessagesBeforeUserRun,
	trimMessagesToCheckpoint,
} from "./checkpoint-restore";

function git(cwd: string, args: string[]): string {
	return execFileSync("git", ["-C", cwd, ...args], {
		encoding: "utf8",
		stdio: ["ignore", "pipe", "pipe"],
	}).trim();
}

/**
 * Creates a checkpoint of the CURRENT worktree through the real creation hook,
 * so the snapshot captures untracked files as a third parent exactly like
 * production. Returns the recorded checkpoint entry.
 */
async function snapshotCurrentWorktree(
	cwd: string,
	sessionId = "snap",
): Promise<CheckpointEntry> {
	let metadata: Record<string, unknown> | undefined;
	const hooks = createCheckpointHooks({
		cwd,
		sessionId,
		readSessionMetadata: async () => metadata,
		writeSessionMetadata: async (next) => {
			metadata = next;
		},
	});
	const userMessage = {
		id: "user-make-a-change",
		role: "user" as const,
		content: [{ type: "text" as const, text: "make a change" }],
		createdAt: 1,
	};
	const snapshot = {
		agentId: "agent_1",
		parentAgentId: undefined,
		conversationId: "conv_1",
		runId: "run_1",
		status: "running" as const,
		iteration: 1,
		messages: [userMessage],
		pendingToolCalls: [],
		usage: {
			inputTokens: 0,
			outputTokens: 0,
			cacheReadTokens: 0,
			cacheWriteTokens: 0,
		},
	};
	await hooks.beforeRun?.({ snapshot: { ...snapshot, iteration: 0 } });
	await hooks.beforeModel?.({ snapshot, request: { messages: [], tools: [] } });
	const checkpoint = (
		metadata?.checkpoint as { latest?: CheckpointEntry } | undefined
	)?.latest;
	if (!checkpoint) {
		throw new Error("failed to record a checkpoint for the current worktree");
	}
	return checkpoint;
}

function createRepo(cwd: string): void {
	git(cwd, ["init"]);
	git(cwd, ["config", "user.name", "Codex Test"]);
	git(cwd, ["config", "user.email", "codex@example.com"]);
	// Keep fixture contents stable regardless of the runner's global Windows
	// checkout settings. These tests validate restoration, not autocrlf.
	git(cwd, ["config", "core.autocrlf", "false"]);
	writeFileSync(join(cwd, "tracked.txt"), "base\n", "utf8");
	git(cwd, ["add", "tracked.txt"]);
	git(cwd, ["commit", "-m", "initial"]);
}

describe("applyCheckpointToWorktree", () => {
	let dir = "";

	beforeEach(() => {
		dir = mkdtempSync(join(tmpdir(), "checkpoint-restore-"));
		mkdirSync(dir, { recursive: true });
		createRepo(dir);
	});

	afterEach(() => {
		rmSync(dir, { recursive: true, force: true });
	});

	it("validates the checkpoint ref before resetting or cleaning the worktree", async () => {
		writeFileSync(join(dir, "tracked.txt"), "dirty\n", "utf8");
		writeFileSync(join(dir, "untracked.txt"), "keep me\n", "utf8");

		await expect(
			applyCheckpointToWorktree(dir, {
				ref: "0000000000000000000000000000000000000000",
				createdAt: Date.now(),
				runCount: 1,
				kind: "stash",
			}),
		).rejects.toThrow();

		expect(readFileSync(join(dir, "tracked.txt"), "utf8")).toBe("dirty\n");
		expect(readFileSync(join(dir, "untracked.txt"), "utf8")).toBe("keep me\n");
	});

	it("restores a stash checkpoint on its original base after later commits", async () => {
		writeFileSync(join(dir, "tracked.txt"), "checkpoint state\n", "utf8");
		const checkpointRef = git(dir, [
			"stash",
			"create",
			"checkpoint before edited run",
		]);
		const checkpointBase = git(dir, ["rev-parse", `${checkpointRef}^1`]);

		writeFileSync(join(dir, "tracked.txt"), "discarded later state\n", "utf8");
		git(dir, ["add", "tracked.txt"]);
		git(dir, ["commit", "-m", "discarded later commit"]);
		writeFileSync(join(dir, "later-untracked.txt"), "keep me\n", "utf8");

		await applyCheckpointToWorktree(dir, {
			ref: checkpointRef,
			createdAt: Date.now(),
			runCount: 2,
			kind: "stash",
		});

		expect(readFileSync(join(dir, "tracked.txt"), "utf8")).toBe(
			"checkpoint state\n",
		);
		// Legacy 2-parent stash (no untracked third parent): untracked files
		// cannot be reconstructed, so they are left untouched rather than
		// destroyed.
		expect(readFileSync(join(dir, "later-untracked.txt"), "utf8")).toBe(
			"keep me\n",
		);
		expect(git(dir, ["rev-parse", "HEAD"])).toBe(checkpointBase);
	});

	it("fully rewinds a snapshot checkpoint: untracked reverted, created-after removed, no apply conflict", async () => {
		// State captured by the checkpoint: a tracked edit plus an untracked
		// file at "v2".
		writeFileSync(join(dir, "tracked.txt"), "checkpoint\n", "utf8");
		writeFileSync(join(dir, "untracked.md"), "v2\n", "utf8");
		const checkpoint = await snapshotCurrentWorktree(dir);
		// The snapshot must carry the untracked third parent.
		expect(git(dir, ["cat-file", "-t", `${checkpoint.ref}^3`])).toBe("commit");

		// Work done after the checkpoint: mutate tracked, mutate the untracked
		// file to different content (this is the "already exists" apply-conflict
		// case), and create a brand-new file.
		writeFileSync(join(dir, "tracked.txt"), "later\n", "utf8");
		writeFileSync(join(dir, "untracked.md"), "v3\n", "utf8");
		writeFileSync(join(dir, "created-after.txt"), "made later\n", "utf8");

		await applyCheckpointToWorktree(dir, checkpoint);

		expect(readFileSync(join(dir, "tracked.txt"), "utf8")).toBe("checkpoint\n");
		// Untracked file modified after the checkpoint is reverted to its
		// checkpoint-time content (from the ^3 parent), not left at "v3".
		expect(readFileSync(join(dir, "untracked.md"), "utf8")).toBe("v2\n");
		// A file created after the checkpoint is rewound away.
		expect(existsSync(join(dir, "created-after.txt"))).toBe(false);
	});

	it("keeps .gitignored files when rewinding a snapshot checkpoint", async () => {
		writeFileSync(join(dir, ".gitignore"), "ignored.log\n", "utf8");
		git(dir, ["add", ".gitignore"]);
		git(dir, ["commit", "-m", "add gitignore"]);
		writeFileSync(join(dir, "tracked.txt"), "checkpoint\n", "utf8");
		writeFileSync(join(dir, "kept.txt"), "keep\n", "utf8");
		const checkpoint = await snapshotCurrentWorktree(dir);

		writeFileSync(join(dir, "tracked.txt"), "later\n", "utf8");
		writeFileSync(join(dir, "ignored.log"), "build output\n", "utf8");

		await applyCheckpointToWorktree(dir, checkpoint);

		expect(readFileSync(join(dir, "tracked.txt"), "utf8")).toBe("checkpoint\n");
		expect(readFileSync(join(dir, "kept.txt"), "utf8")).toBe("keep\n");
		// git clean -fd (no -x) never touches ignored paths.
		expect(readFileSync(join(dir, "ignored.log"), "utf8")).toBe(
			"build output\n",
		);
	});

	it("infers a kindless stash checkpoint without treating it as a commit", async () => {
		writeFileSync(join(dir, "tracked.txt"), "checkpoint state\n", "utf8");
		const checkpointRef = git(dir, [
			"stash",
			"create",
			"cline checkpoint session=legacy run=1",
		]);
		const checkpointBase = git(dir, ["rev-parse", `${checkpointRef}^1`]);

		writeFileSync(join(dir, "tracked.txt"), "discarded state\n", "utf8");
		git(dir, ["add", "tracked.txt"]);
		git(dir, ["commit", "-m", "discarded commit"]);

		await applyCheckpointToWorktree(dir, {
			ref: checkpointRef,
			createdAt: Date.now(),
			runCount: 1,
		});

		expect(readFileSync(join(dir, "tracked.txt"), "utf8")).toBe(
			"checkpoint state\n",
		);
		expect(git(dir, ["rev-parse", "HEAD"])).toBe(checkpointBase);
	});

	it("restores a kindless root commit without reading a nonexistent parent", async () => {
		const checkpointRef = git(dir, ["rev-parse", "HEAD"]);
		writeFileSync(join(dir, "tracked.txt"), "discarded state\n", "utf8");
		git(dir, ["add", "tracked.txt"]);
		git(dir, ["commit", "-m", "discarded commit"]);
		writeFileSync(join(dir, "later-untracked.txt"), "keep me\n", "utf8");

		await applyCheckpointToWorktree(dir, {
			ref: checkpointRef,
			createdAt: Date.now(),
			runCount: 1,
		});

		expect(readFileSync(join(dir, "tracked.txt"), "utf8")).toBe("base\n");
		// HEAD-commit fallback (no untracked third parent): untracked left alone.
		expect(readFileSync(join(dir, "later-untracked.txt"), "utf8")).toBe(
			"keep me\n",
		);
		expect(git(dir, ["rev-parse", "HEAD"])).toBe(checkpointRef);
	});

	it("rolls back HEAD plus staged, unstaged, and untracked changes", async () => {
		writeFileSync(join(dir, "tracked.txt"), "existing stash\n", "utf8");
		git(dir, ["stash", "push", "--message", "existing user stash"]);
		const stashListBefore = git(dir, ["stash", "list"]);
		const originalHead = git(dir, ["rev-parse", "HEAD"]);

		writeFileSync(join(dir, "tracked.txt"), "staged state\n", "utf8");
		git(dir, ["add", "tracked.txt"]);
		writeFileSync(join(dir, "tracked.txt"), "unstaged state\n", "utf8");
		writeFileSync(join(dir, "untracked.txt"), "untracked state\n", "utf8");

		const transaction = await beginWorktreeRestoreTransaction(dir);
		expect(git(dir, ["status", "--short"])).toBe("");
		expect(git(dir, ["stash", "list"])).toBe(stashListBefore);

		writeFileSync(join(dir, "tracked.txt"), "replacement state\n", "utf8");
		git(dir, ["add", "tracked.txt"]);
		git(dir, ["commit", "-m", "replacement checkpoint"]);
		writeFileSync(join(dir, "replacement.txt"), "remove me\n", "utf8");

		await transaction.rollback();

		expect(git(dir, ["rev-parse", "HEAD"])).toBe(originalHead);
		expect(readFileSync(join(dir, "tracked.txt"), "utf8")).toBe(
			"unstaged state\n",
		);
		expect(git(dir, ["show", ":tracked.txt"])).toBe("staged state");
		expect(readFileSync(join(dir, "untracked.txt"), "utf8")).toBe(
			"untracked state\n",
		);
		expect(existsSync(join(dir, "replacement.txt"))).toBe(false);
		expect(git(dir, ["stash", "list"])).toBe(stashListBefore);
		expect(
			git(dir, [
				"for-each-ref",
				"--format=%(refname)",
				"refs/cline/restore-transactions",
			]),
		).toBe("");
	});

	it("discards the recovery snapshot after a committed restore", async () => {
		writeFileSync(join(dir, "tracked.txt"), "discarded state\n", "utf8");
		writeFileSync(join(dir, "untracked.txt"), "discarded untracked\n", "utf8");
		const stashListBefore = git(dir, ["stash", "list"]);

		const transaction = await beginWorktreeRestoreTransaction(dir);
		await transaction.commit();

		expect(readFileSync(join(dir, "tracked.txt"), "utf8")).toBe("base\n");
		expect(existsSync(join(dir, "untracked.txt"))).toBe(false);
		expect(git(dir, ["stash", "list"])).toBe(stashListBefore);
		expect(
			git(dir, [
				"for-each-ref",
				"--format=%(refname)",
				"refs/cline/restore-transactions",
			]),
		).toBe("");
	});

	it("carries checkpoint metadata through the restored run", () => {
		const metadata = createRestoredCheckpointMetadata(
			{
				metadata: {
					checkpoint: {
						latest: { ref: "cccc", createdAt: 3, runCount: 3 },
						history: [
							{ ref: "aaaa", createdAt: 1, runCount: 1 },
							{ ref: "bbbb", createdAt: 2, runCount: 2 },
							{ ref: "cccc", createdAt: 3, runCount: 3 },
						],
					},
				},
			},
			2,
		);

		expect(metadata?.latest.runCount).toBe(2);
		expect(metadata?.history.map((entry) => entry.runCount)).toEqual([1, 2]);
	});
});

describe("checkpoint message trimming", () => {
	it("can trim either through or before the checkpoint user message", () => {
		const messages = [
			{ role: "user" as const, content: "first" },
			{ role: "assistant" as const, content: "first response" },
			{ role: "user" as const, content: "second" },
			{ role: "assistant" as const, content: "second response" },
		];

		expect(trimMessagesToCheckpoint(messages, 2)).toEqual([
			{ role: "user", content: "first" },
			{ role: "assistant", content: "first response" },
			{ role: "user", content: "second" },
		]);
		expect(trimMessagesBeforeUserRun(messages, 2)).toEqual([
			{ role: "user", content: "first" },
			{ role: "assistant", content: "first response" },
		]);
		expect(trimMessagesBeforeUserRun(messages, 1)).toEqual([]);
	});

	it("preserves absolute run positions across system-displayed compaction messages", () => {
		const compactedContext = {
			role: "user" as const,
			content: "Compacted context",
			metadata: {
				kind: "compaction",
				displayRole: "system",
				userRunSpan: 3,
			},
		};
		const recoveryNotice = {
			role: "user" as const,
			content: "Recovered context",
			metadata: {
				kind: "recovery_notice",
			},
		};
		const messages = [
			compactedContext,
			recoveryNotice,
			{ role: "user" as const, content: "first visible prompt" },
			{ role: "assistant" as const, content: "first response" },
			{ role: "user" as const, content: "second visible prompt" },
		];

		expect(trimMessagesBeforeUserRun(messages, 4)).toEqual([
			compactedContext,
			recoveryNotice,
		]);
		expect(trimMessagesBeforeUserRun(messages, 5)).toEqual([
			compactedContext,
			recoveryNotice,
			{ role: "user", content: "first visible prompt" },
			{ role: "assistant", content: "first response" },
		]);
		expect(trimMessagesToCheckpoint(messages, 5)).toEqual(messages);
		expect(() => trimMessagesToCheckpoint(messages, 2)).toThrow(
			"folded into a compacted message spanning runs 1-3",
		);
		expect(() => trimMessagesBeforeUserRun(messages, 3)).toThrow(
			"Cannot fork before run 3",
		);
	});

	it("uses the nearest earlier checkpoint when an identical snapshot was deduplicated", () => {
		const messages = [
			{ role: "user" as const, content: "first" },
			{ role: "assistant" as const, content: "first response" },
			{ role: "user" as const, content: "second" },
			{ role: "assistant" as const, content: "second response" },
			{ role: "user" as const, content: "third" },
		];

		const plan = createCheckpointRestorePlan({
			session: {
				sessionId: "session-1",
				source: "cli",
				status: "running",
				startedAt: "2026-01-01T00:00:00.000Z",
				updatedAt: "2026-01-01T00:00:00.000Z",
				interactive: true,
				provider: "mock",
				model: "mock",
				cwd: "/tmp/project",
				workspaceRoot: "/tmp/project",
				enableTools: true,
				enableSpawn: true,
				enableTeams: true,
				isSubagent: false,
				metadata: {
					checkpoint: {
						latest: { ref: "cccc", createdAt: 3, runCount: 3 },
						history: [
							{ ref: "aaaa", createdAt: 1, runCount: 1 },
							{ ref: "cccc", createdAt: 3, runCount: 3 },
						],
					},
				},
			},
			messages,
			checkpointRunCount: 2,
		});

		expect(plan.checkpoint).toMatchObject({ ref: "aaaa", runCount: 1 });
		expect(plan.messages).toEqual([
			{ role: "user", content: "first" },
			{ role: "assistant", content: "first response" },
			{ role: "user", content: "second" },
		]);
	});
});

import { execFile as execFileCallback } from "node:child_process";
import { randomUUID } from "node:crypto";
import { promisify } from "node:util";
import type * as LlmsProviders from "@cline/llms";
import type {
	CheckpointEntry,
	CheckpointMetadata,
} from "../hooks/checkpoint-hooks";
import { isCheckpointStashMessage } from "../hooks/checkpoint-hooks";
import type { SessionRecord } from "../types/sessions";
import { getUserRunSpan } from "./user-run-messages";

const execFile = promisify(execFileCallback);

export interface CheckpointRestorePlan {
	checkpoint: CheckpointEntry;
	messages?: LlmsProviders.Message[];
	cwd: string;
}

export interface WorktreeRestoreTransaction {
	commit(): Promise<void>;
	rollback(): Promise<void>;
}

async function resolveOptionalGitRef(
	cwd: string,
	ref: string,
): Promise<string | undefined> {
	try {
		const result = await execFile(
			"git",
			["-C", cwd, "rev-parse", "--verify", "--quiet", ref],
			{ windowsHide: true },
		);
		return result.stdout.trim() || undefined;
	} catch {
		return undefined;
	}
}

/**
 * Captures the current worktree before a destructive checkpoint restore.
 *
 * `git stash create` omits untracked files, but checkpoint restoration runs
 * `git clean -fd`. Use a short-lived `stash push --include-untracked`, move
 * its object behind a private ref, and immediately remove it from the user's
 * visible stash list. The private ref remains only until commit or rollback.
 */
export async function beginWorktreeRestoreTransaction(
	cwd: string,
): Promise<WorktreeRestoreTransaction> {
	const check = await execFile(
		"git",
		["-C", cwd, "rev-parse", "--is-inside-work-tree"],
		{ windowsHide: true },
	);
	if (check.stdout.trim() !== "true") {
		throw new Error(`${cwd} is not a git repository`);
	}
	const originalHead = (
		await execFile("git", ["-C", cwd, "rev-parse", "--verify", "HEAD"], {
			windowsHide: true,
		})
	).stdout.trim();
	const previousStashRef = await resolveOptionalGitRef(cwd, "refs/stash");
	const transactionId = randomUUID();
	const privateRef = `refs/cline/restore-transactions/${transactionId}`;

	await execFile(
		"git",
		[
			"-C",
			cwd,
			"stash",
			"push",
			"--include-untracked",
			"--message",
			`cline restore transaction ${transactionId}`,
		],
		{ windowsHide: true },
	);

	const capturedRef = await resolveOptionalGitRef(cwd, "refs/stash");
	const hasSnapshot =
		capturedRef !== undefined && capturedRef !== previousStashRef;
	if (hasSnapshot) {
		try {
			await execFile(
				"git",
				["-C", cwd, "update-ref", privateRef, capturedRef],
				{ windowsHide: true },
			);
			await execFile("git", ["-C", cwd, "stash", "drop", "stash@{0}"], {
				windowsHide: true,
			});
		} catch (captureError) {
			try {
				await execFile("git", ["-C", cwd, "reset", "--hard", originalHead], {
					windowsHide: true,
				});
				await execFile("git", ["-C", cwd, "clean", "-fd"], {
					windowsHide: true,
				});
				await execFile(
					"git",
					["-C", cwd, "stash", "apply", "--index", capturedRef],
					{ windowsHide: true },
				);
			} catch (rollbackError) {
				throw new AggregateError(
					[captureError, rollbackError],
					"Workspace snapshot and rollback both failed",
				);
			}
			throw captureError;
		}
	}

	let completed = false;
	return {
		async commit() {
			if (completed) return;
			completed = true;
			if (!hasSnapshot) return;
			// A cleanup failure must not turn a successfully started replacement
			// session into a reported failure. The private ref is harmless and
			// keeps the recovery object reachable if deletion ever fails.
			await execFile("git", ["-C", cwd, "update-ref", "-d", privateRef], {
				windowsHide: true,
			}).catch(() => undefined);
		},
		async rollback() {
			if (completed) return;
			await execFile("git", ["-C", cwd, "reset", "--hard", originalHead], {
				windowsHide: true,
			});
			await execFile("git", ["-C", cwd, "clean", "-fd"], {
				windowsHide: true,
			});
			if (hasSnapshot) {
				await execFile(
					"git",
					["-C", cwd, "stash", "apply", "--index", privateRef],
					{ windowsHide: true },
				);
				await execFile("git", ["-C", cwd, "update-ref", "-d", privateRef], {
					windowsHide: true,
				});
			}
			completed = true;
		},
	};
}

export function readSessionCheckpointHistory(
	session: Pick<SessionRecord, "metadata"> | undefined,
): CheckpointEntry[] {
	const checkpoint =
		session?.metadata?.checkpoint &&
		typeof session.metadata.checkpoint === "object" &&
		!Array.isArray(session.metadata.checkpoint)
			? (session.metadata.checkpoint as Record<string, unknown>)
			: undefined;
	const history = Array.isArray(checkpoint?.history) ? checkpoint.history : [];
	return history
		.filter(
			(entry): entry is Record<string, unknown> =>
				!!entry && typeof entry === "object" && !Array.isArray(entry),
		)
		.flatMap((entry): CheckpointEntry[] => {
			const ref = String(entry.ref ?? "").trim();
			const createdAt = Number(entry.createdAt ?? 0);
			const runCount = Number(entry.runCount ?? 0);
			if (
				ref.length === 0 ||
				!Number.isFinite(createdAt) ||
				!Number.isInteger(runCount) ||
				runCount < 1
			) {
				return [];
			}
			const kind =
				entry.kind === "stash" || entry.kind === "commit"
					? entry.kind
					: undefined;
			return [{ ref, createdAt, runCount, ...(kind ? { kind } : {}) }];
		});
}

export function createRestoredCheckpointMetadata(
	session: Pick<SessionRecord, "metadata"> | undefined,
	runCount: number,
): CheckpointMetadata | undefined {
	const history = readSessionCheckpointHistory(session).filter(
		(entry) => entry.runCount <= runCount,
	);
	const latest = history.at(-1);
	return latest ? { latest, history } : undefined;
}

export function findCheckpointForRun(
	history: readonly CheckpointEntry[],
	runCount: number,
): CheckpointEntry | undefined {
	return history.reduce<CheckpointEntry | undefined>((best, entry) => {
		if (entry.runCount > runCount) {
			return best;
		}
		if (!best || entry.runCount > best.runCount) {
			return entry;
		}
		return best;
	}, undefined);
}

function findUserRunMessage(
	messages: LlmsProviders.Message[],
	runCount: number,
): { index: number; span: number } {
	let userRunCount = 0;
	for (let index = 0; index < messages.length; index += 1) {
		const message = messages[index];
		if (!message) {
			continue;
		}
		const span = getUserRunSpan(message);
		if (span < 1) {
			continue;
		}
		const firstRunCount = userRunCount + 1;
		userRunCount += span;
		if (userRunCount === runCount) {
			return { index, span };
		}
		if (userRunCount > runCount) {
			throw new Error(
				`Run ${runCount} is folded into a compacted message spanning runs ${firstRunCount}-${userRunCount}`,
			);
		}
	}
	throw new Error(`Could not find user message for run ${runCount}`);
}

export function trimMessagesToCheckpoint(
	messages: LlmsProviders.Message[],
	runCount: number,
): LlmsProviders.Message[] {
	const { index } = findUserRunMessage(messages, runCount);
	return messages.slice(0, index + 1);
}

export function trimMessagesBeforeUserRun(
	messages: LlmsProviders.Message[],
	runCount: number,
): LlmsProviders.Message[] {
	const { index, span } = findUserRunMessage(messages, runCount);
	if (span !== 1) {
		throw new Error(
			`Cannot fork before run ${runCount} because it is folded into a compacted message`,
		);
	}
	return messages.slice(0, index);
}

export function createCheckpointRestorePlan(input: {
	session: SessionRecord;
	messages?: LlmsProviders.Message[];
	checkpointRunCount: number;
	cwd?: string;
	restoreMessages?: boolean;
}): CheckpointRestorePlan {
	const runCount = input.checkpointRunCount;
	if (!Number.isInteger(runCount) || runCount < 1) {
		throw new Error("checkpointRunCount must be a positive integer");
	}
	const checkpoint = findCheckpointForRun(
		readSessionCheckpointHistory(input.session),
		runCount,
	);
	if (!checkpoint) {
		throw new Error(
			`No checkpoint found at or before run ${runCount} in session ${input.session.sessionId}`,
		);
	}
	const cwd = (
		input.cwd?.trim() ||
		input.session.cwd ||
		input.session.workspaceRoot
	).trim();
	if (!cwd) {
		throw new Error("cwd or workspaceRoot is required to restore a checkpoint");
	}
	return {
		checkpoint,
		cwd,
		...(input.restoreMessages !== false
			? {
					messages: trimMessagesToCheckpoint(input.messages ?? [], runCount),
				}
			: {}),
	};
}

async function resolveCheckpointKind(
	cwd: string,
	checkpoint: CheckpointEntry,
): Promise<NonNullable<CheckpointEntry["kind"]>> {
	if (checkpoint.kind) {
		return checkpoint.kind;
	}
	const result = await execFile(
		"git",
		["-C", cwd, "show", "-s", "--format=%P%x00%B", checkpoint.ref],
		{ windowsHide: true },
	);
	const separatorIndex = result.stdout.indexOf("\0");
	const parents =
		separatorIndex < 0
			? []
			: result.stdout
					.slice(0, separatorIndex)
					.trim()
					.split(/\s+/)
					.filter(Boolean);
	const message =
		separatorIndex < 0 ? "" : result.stdout.slice(separatorIndex + 1);

	// Checkpoints created before `kind` was persisted used Cline's stash
	// message. Requiring both its merge shape and marker keeps ordinary merge
	// commits from being passed to `git stash apply`.
	return parents.length >= 2 && isCheckpointStashMessage(message)
		? "stash"
		: "commit";
}

/**
 * True when `ref` is a snapshot stash that also captured untracked files as a
 * third parent (created by `createWorktreeStashCommit`). Such snapshots can be
 * fully rewound; older 2-parent stashes and HEAD-commit fallbacks cannot bring
 * untracked files back, so restore leaves untracked files untouched for them.
 */
async function checkpointCapturedUntracked(
	cwd: string,
	ref: string,
): Promise<boolean> {
	try {
		await execFile("git", ["-C", cwd, "cat-file", "-e", `${ref}^3^{commit}`], {
			windowsHide: true,
		});
		return true;
	} catch {
		return false;
	}
}

export async function applyCheckpointToWorktree(
	cwd: string,
	checkpoint: CheckpointEntry,
): Promise<void> {
	const check = await execFile(
		"git",
		["-C", cwd, "rev-parse", "--is-inside-work-tree"],
		{ windowsHide: true },
	);
	if (check.stdout.trim() !== "true") {
		throw new Error(`${cwd} is not a git repository`);
	}
	await execFile(
		"git",
		["-C", cwd, "cat-file", "-e", `${checkpoint.ref}^{commit}`],
		{ windowsHide: true },
	);
	const checkpointKind = await resolveCheckpointKind(cwd, checkpoint);
	const restoreBase =
		checkpointKind === "commit" ? checkpoint.ref : `${checkpoint.ref}^1`;
	await execFile(
		"git",
		["-C", cwd, "cat-file", "-e", `${restoreBase}^{commit}`],
		{ windowsHide: true },
	);
	if (checkpointKind === "stash") {
		await execFile(
			"git",
			["-C", cwd, "cat-file", "-e", `${checkpoint.ref}^2^{commit}`],
			{ windowsHide: true },
		);
	}
	const capturedUntracked = await checkpointCapturedUntracked(
		cwd,
		checkpoint.ref,
	);
	await execFile("git", ["-C", cwd, "reset", "--hard", restoreBase], {
		windowsHide: true,
	});
	// Only clear untracked files for snapshots that captured them (third
	// parent): the following `git stash apply` restores each one to its
	// checkpoint-time content from ^3, and files created after the checkpoint
	// are meant to be rewound away. `git clean -fd` leaves .gitignored paths
	// (build output, node_modules, .env) alone, and clearing before apply also
	// avoids "already exists" apply conflicts. For 2-parent stashes and
	// HEAD-commit fallbacks (no ^3) untracked files can't be reconstructed, so
	// they are left untouched — deleting them would be unrecoverable data loss.
	if (capturedUntracked) {
		await execFile("git", ["-C", cwd, "clean", "-fd"], { windowsHide: true });
	}
	if (checkpointKind === "commit") {
		return;
	}
	await execFile("git", ["-C", cwd, "stash", "apply", checkpoint.ref], {
		windowsHide: true,
	});
}

