				latest: { ref: "cccc", createdAt: 3, runCount: 3, kind: "stash" },
			},
			usage: { totalCost: 0.5 },
		});
		expect(snapshot.messages).toEqual(messages);
		expect(snapshot.messages).not.toBe(messages);
		expect(snapshot.metadata).not.toBe(makeSession().metadata);
	});
});

