	SessionPersistenceAdapter,
	StoredMessageWithMetadata,
} from "../../types/session";
import {
	readSessionHistoryOriginMetadata,
	withSessionHistoryOriginMetadata,
} from "../history-origin";
import {
	deriveSubsessionStatus,
	makeSubSessionId,
	makeTeamTaskSubSessionId,
} from "../models/session-graph";
import type { SessionRow, UpsertSubagentInput } from "../models/session-row";
import type { SessionManifestStore } from "../stores/session-manifest-store";

const SpawnAgentInputSchema = z.looseObject({
	task: z.string().optional(),
	systemPrompt: z.string().optional(),
});

export class TeamChildSessionManager {
	private readonly teamTaskSessionsByAgent = new Map<string, string[]>();
	private readonly teamTaskLastHeartbeatBySession = new Map<string, number>();
	private readonly teamTaskLastProgressLineBySession = new Map<
		string,
		string
	>();

	constructor(
		private readonly adapter: SessionPersistenceAdapter,
		private readonly manifestStore: SessionManifestStore,
		private readonly toPersistedMessages: (
			messages: LlmsProviders.Message[] | undefined,
			result?: AgentResult,
			previousMessages?: LlmsProviders.Message[],
		) => StoredMessageWithMetadata[] | undefined,
		private readonly heartbeatLogIntervalMs: number,
	) {}

	private teamTaskQueueKey(rootSessionId: string, agentId: string): string {
		return `${rootSessionId}::${agentId}`;
	}

	private activeTeamTaskSessionId(
		rootSessionId: string,
		parentAgentId: string,
	): string | undefined {
		const queue = this.teamTaskSessionsByAgent.get(
			this.teamTaskQueueKey(rootSessionId, parentAgentId),
		);
		return queue?.at(-1);
	}

	private buildSubsessionRow(
		root: SessionRow,
		opts: {
			sessionId: string;
			mode: "subagent" | "team";
			parentSessionId: string;
			parentAgentId: string;
			agentId: string;
			conversationId?: string | null;
			prompt: string;
			startedAt: string;
			messagesPath: string;
		},
	): SessionRow {
		const rootHistoryOrigin = readSessionHistoryOriginMetadata(root.metadata);
		return {
			sessionId: opts.sessionId,
			source: root.source,
			pid: process.ppid,
			startedAt: opts.startedAt,
			endedAt: null,
			exitCode: null,
			status: "running",
			statusLock: 0,
			interactive: false,
			provider: root.provider,
			model: root.model,
			cwd: root.cwd,
			workspaceRoot: root.workspaceRoot,
			teamName: root.teamName ?? null,
			enableTools: root.enableTools,
			enableSpawn: root.enableSpawn,
			enableTeams: root.enableTeams,
			parentSessionId: opts.parentSessionId,
			parentAgentId: opts.parentAgentId,
			agentId: opts.agentId,
			conversationId: opts.conversationId ?? null,
			isSubagent: true,
			prompt: opts.prompt,
			metadata: resolveMetadataWithTitle({
				metadata: withSessionHistoryOriginMetadata(undefined, {
					mode: opts.mode,
					version: rootHistoryOrigin?.version,
				}),
				prompt: opts.prompt,
			}),
			hookPath: "",
			messagesPath: opts.messagesPath,
			updatedAt: opts.startedAt,
		};
	}

	async queueSpawnRequest(event: HookEventPayload): Promise<void> {
		if (event.hookName !== "tool_call" || event.parent_agent_id !== null)
			return;
		if (event.tool_call?.name !== "spawn_agent") return;

		const rootSessionId = resolveRootSessionId(event.sessionContext);
		if (!rootSessionId) return;

		const parsed = SpawnAgentInputSchema.safeParse(event.tool_call.input);
		await this.adapter.enqueueSpawnRequest({
			rootSessionId,
			parentAgentId: event.agent_id,
			task: parsed.success ? parsed.data.task : undefined,
			systemPrompt: parsed.success ? parsed.data.systemPrompt : undefined,
		});
	}

	async upsertSubagentSession(
		input: UpsertSubagentInput,
	): Promise<string | undefined> {
		const rootSessionId = input.rootSessionId;
		if (!rootSessionId) return undefined;

		const root = await this.adapter.getSession(rootSessionId);
		if (!root) return undefined;

		const sessionId = makeSubSessionId(rootSessionId, input.agentId);
		const existing = await this.adapter.getSession(sessionId);
		const startedAt = nowIso();
		const artifactPaths = this.manifestStore.artifacts.subagentArtifactPaths(
			sessionId,
			input.agentId,
			this.activeTeamTaskSessionId(rootSessionId, input.parentAgentId),
		);

		let prompt = input.prompt ?? existing?.prompt ?? undefined;
		if (!prompt) {
			prompt =
				(await this.adapter.claimSpawnRequest(
					rootSessionId,
					input.parentAgentId,
				)) ?? `Subagent run by ${input.parentAgentId}`;
		}

		if (!existing) {
			const row = this.buildSubsessionRow(root, {
				sessionId,
				mode: "subagent",
				parentSessionId: rootSessionId,
				parentAgentId: input.parentAgentId,
				agentId: input.agentId,
				conversationId: input.conversationId,
				prompt,
				startedAt,
				...artifactPaths,
			});
			await this.adapter.upsertSession(row);
			this.manifestStore.initializeMessagesFile(
				row,
				artifactPaths.messagesPath,
				startedAt,
			);
			return sessionId;
		}

		await this.adapter.updateSession({
			sessionId,
			setRunning: true,
			parentSessionId: rootSessionId,
			parentAgentId: input.parentAgentId,
			agentId: input.agentId,
			conversationId: input.conversationId,
			prompt: existing.prompt ?? prompt ?? null,
			metadata: resolveMetadataWithTitle({
				metadata: withSessionHistoryOriginMetadata(existing.metadata, {
					mode: "subagent",
					version: readSessionHistoryOriginMetadata(root.metadata)?.version,
				}),
				prompt: existing.prompt ?? prompt ?? null,
			}),
			expectedStatusLock: existing.statusLock,
		});
		return sessionId;
	}

	async upsertSubagentSessionFromHook(
		event: HookEventPayload,
	): Promise<string | undefined> {
		if (!event.parent_agent_id) return undefined;
		const rootSessionId = resolveRootSessionId(event.sessionContext);
		if (!rootSessionId) return undefined;
		if (event.hookName === "session_shutdown") {
			const sessionId = makeSubSessionId(rootSessionId, event.agent_id);
			const existing = await this.adapter.getSession(sessionId);
			return existing ? sessionId : undefined;
		}
		return await this.upsertSubagentSession({
			agentId: event.agent_id,
			parentAgentId: event.parent_agent_id,
			conversationId: event.taskId,
			rootSessionId,
		});
	}

	async applySubagentStatus(
		subSessionId: string,
		event: HookEventPayload,
	): Promise<void> {
		await this.applySubagentStatusBySessionId(
			subSessionId,
			deriveSubsessionStatus(event),
		);
	}

	async applySubagentStatusBySessionId(
		subSessionId: string,
		status: SessionStatus,
	): Promise<void> {
		const row = await this.adapter.getSession(subSessionId);
		if (!row) return;
		const endedAt = isNonTerminalSessionStatus(status) ? null : nowIso();
		const exitCode = isNonTerminalSessionStatus(status)
			? null
			: status === "failed"
				? 1
				: 0;
		await this.adapter.updateSession({
			sessionId: subSessionId,
			status,
			endedAt,
			exitCode,
			expectedStatusLock: row.statusLock,
		});
	}

	async applyStatusToRunningChildSessions(
		parentSessionId: string,
		status: TerminalSessionStatus,
	): Promise<void> {
		if (!parentSessionId) return;
		const rows = await this.adapter.listSessions({
			limit: 2000,
			parentSessionId,
			status: "running",
		});
		for (const row of rows) {
			await this.applySubagentStatusBySessionId(row.sessionId, status);
		}
	}

	async onTeamTaskStart(
		rootSessionId: string,
		agentId: string,
		message: string,
	): Promise<void> {
		const root = await this.adapter.getSession(rootSessionId);
		if (!root) return;
		const sessionId = makeTeamTaskSubSessionId(rootSessionId, agentId);
		const startedAt = nowIso();
		const { messagesPath } = this.manifestStore.artifacts.subagentArtifactPaths(
			sessionId,
			agentId,
		);
		const row = this.buildSubsessionRow(root, {
			sessionId,
			mode: "team",
			parentSessionId: rootSessionId,
			parentAgentId: "lead",
			agentId,
			prompt: message || `Team task for ${agentId}`,
			startedAt,
			messagesPath,
		});
		await this.adapter.upsertSession(row);
		this.manifestStore.initializeMessagesFile(row, messagesPath, startedAt);
		const key = this.teamTaskQueueKey(rootSessionId, agentId);
		const queue = this.teamTaskSessionsByAgent.get(key) ?? [];
		queue.push(sessionId);
		this.teamTaskSessionsByAgent.set(key, queue);
	}

	async onTeamTaskEnd(
		rootSessionId: string,
		agentId: string,
		status: SessionStatus,
		_summary?: string,
		result?: AgentResult,
		messages?: LlmsProviders.Message[],
	): Promise<void> {
		const key = this.teamTaskQueueKey(rootSessionId, agentId);
		const queue = this.teamTaskSessionsByAgent.get(key);
		if (!queue || queue.length === 0) return;
		const sessionId = queue.shift();
		if (queue.length === 0) this.teamTaskSessionsByAgent.delete(key);
		if (!sessionId) return;
		const teammateMessages = result?.messages ?? messages;
		const persistedMessages = this.toPersistedMessages(
			teammateMessages,
			result,
			messages,
		);
		if (persistedMessages) {
			await this.manifestStore.persistSessionMessages(
				sessionId,
				persistedMessages,
			);
		}
		await this.applySubagentStatusBySessionId(sessionId, status);
		this.teamTaskLastHeartbeatBySession.delete(sessionId);
		this.teamTaskLastProgressLineBySession.delete(sessionId);
	}

	async onTeamTaskProgress(
		rootSessionId: string,
		agentId: string,
		progress: string,
		options?: { kind?: "heartbeat" | "progress" | "text" },
	): Promise<void> {
		const key = this.teamTaskQueueKey(rootSessionId, agentId);
		const sessionId = this.teamTaskSessionsByAgent.get(key)?.[0];
		if (!sessionId) return;
		const trimmed = progress.trim();
		if (!trimmed) return;
		const kind = options?.kind ?? "progress";
		if (kind === "heartbeat") {
			const now = Date.now();
			const last = this.teamTaskLastHeartbeatBySession.get(sessionId) ?? 0;
			if (now - last < this.heartbeatLogIntervalMs) {
				return;
			}
			this.teamTaskLastHeartbeatBySession.set(sessionId, now);
		}
		const line =
			kind === "heartbeat"
				? "[progress] heartbeat"
				: kind === "text"
					? `[progress] text: ${trimmed}`
					: `[progress] ${trimmed}`;
		if (this.teamTaskLastProgressLineBySession.get(sessionId) === line) return;
		this.teamTaskLastProgressLineBySession.set(sessionId, line);
	}

	async handleSubAgentStart(
		rootSessionId: string,
		context: SubAgentStartContext,
	): Promise<void> {
		const subSessionId = await this.upsertSubagentSession({
			agentId: context.subAgentId,
			parentAgentId: context.parentAgentId,
			conversationId: context.conversationId,
			prompt: context.input.task,
			rootSessionId,
		});
		if (!subSessionId) return;
		await this.applySubagentStatusBySessionId(subSessionId, "running");
	}

	async handleSubAgentEnd(
		rootSessionId: string,
		context: SubAgentEndContext,
	): Promise<void> {
		const subSessionId = await this.upsertSubagentSession({
			agentId: context.subAgentId,
			parentAgentId: context.parentAgentId,
			conversationId: context.conversationId,
			prompt: context.input.task,
			rootSessionId,
		});
		if (!subSessionId) return;
		if (context.error) {
			await this.applySubagentStatusBySessionId(subSessionId, "failed");
			return;
		}
		const persistedMessages = this.toPersistedMessages(
			context.agentResult?.messages,
			context.agentResult,
		);
		if (persistedMessages) {
			await this.manifestStore.persistSessionMessages(
				subSessionId,
				persistedMessages,
			);
		}
		const reason = context.result?.finishReason ?? "completed";
		await this.applySubagentStatusBySessionId(
			subSessionId,
			reason === "aborted" ? "cancelled" : "completed",
		);
	}

	appendSubagentHookAudit(event: HookEventPayload): void {
		const envPath = process.env.CLINE_HOOKS_LOG_PATH?.trim() || undefined;
		const logPath = envPath ?? join(ensureHookLogDir(), "hooks.jsonl");
		appendFileSync(
			logPath,
			`${JSON.stringify({ ts: nowIso(), ...event })}\n`,
			"utf8",
		);
	}
}

import {
	type AgentMode,
	type AgentResult,
	formatUserInputBlock,
} from "@cline/shared";
import type { TeamEvent } from "../../extensions/tools/team";
import {
	buildTeamProgressSummary,
	toTeamProgressLifecycleEvent,
} from "../../extensions/tools/team";
import type { CoreSessionEvent } from "../../types/events";
import type { ActiveSession, TeamRunUpdate } from "../../types/session";

export function trackTeamRunState(
	session: ActiveSession,
	event: TeamEvent,
): void {
	switch (event.type) {
		case "run_queued":
		case "run_started":
			session.activeTeamRunIds.add(event.run.id);
			break;
		case "run_completed":
		case "run_failed":
		case "run_cancelled":
		case "run_interrupted": {
			let runError: string | undefined;
			if (event.type === "run_failed") {
				runError = event.run.error;
			} else if (
				event.type === "run_cancelled" ||
				event.type === "run_interrupted"
			) {
				runError = event.run.error ?? event.reason;
			}
			session.activeTeamRunIds.delete(event.run.id);
			session.pendingTeamRunUpdates.push({
				runId: event.run.id,
				agentId: event.run.agentId,
				taskId: event.run.taskId,
				status: event.type.replace("run_", "") as TeamRunUpdate["status"],
				error: runError,
				iterations: (event.run.result as { iterations?: number } | undefined)
					?.iterations,
			});
			notifyTeamRunWaiters(session);
			break;
		}
		default:
			break;
	}
}

export async function dispatchTeamEventToBackend(
	rootSessionId: string,
	event: TeamEvent,
	invokeOptional: (method: string, ...args: unknown[]) => Promise<void>,
): Promise<void> {
	switch (event.type) {
		case "run_progress":
			await invokeOptional(
				"onTeamTaskProgress",
				rootSessionId,
				event.run.agentId,
				event.message,
				{ kind: event.message === "heartbeat" ? "heartbeat" : "progress" },
			);
			break;
		case "agent_event":
			if (
				event.event.type === "content_start" &&
				event.event.contentType === "text" &&
				typeof event.event.text === "string"
			) {
				const snippet = event.event.text
					.replace(/\s+/g, " ")
					.trim()
					.slice(0, 120);
				if (snippet) {
					await invokeOptional(
						"onTeamTaskProgress",
						rootSessionId,
						event.agentId,
						snippet,
						{ kind: "text" },
					);
				}
			}
			break;
		case "task_start":
			await invokeOptional(
				"onTeamTaskStart",
				rootSessionId,
				event.agentId,
				event.message,
			);
			break;
		case "task_end": {
			if (event.error) {
				await invokeOptional(
					"onTeamTaskEnd",
					rootSessionId,
					event.agentId,
					"failed",
					`[error] ${event.error.message}`,
					undefined,
					event.messages,
				);
			} else if (event.result?.finishReason === "aborted") {
				await invokeOptional(
					"onTeamTaskEnd",
					rootSessionId,
					event.agentId,
					"cancelled",
					"[done] aborted",
					event.result,
					event.result.messages,
				);
			} else {
				await invokeOptional(
					"onTeamTaskEnd",
					rootSessionId,
					event.agentId,
					"completed",
					`[done] ${event.result?.finishReason ?? "completed"}`,
					event.result,
					event.result?.messages,
				);
			}
			break;
		}
		default:
			break;
	}
}

export function emitTeamProgress(
	session: ActiveSession,
	rootSessionId: string,
	event: TeamEvent,
	emit: (event: CoreSessionEvent) => void,
): void {
	if (!session.runtime.teamRuntime) return;
	const teamName = session.runtime.teamRuntime.getTeamName();
	emit({
		type: "team_progress",
		payload: {
			sessionId: rootSessionId,
			teamName,
			lifecycle: toTeamProgressLifecycleEvent({
				teamName,
				sessionId: rootSessionId,
				event,
			}),
			summary: buildTeamProgressSummary(
				teamName,
				session.runtime.teamRuntime.exportState(),
			),
		},
	});
}

export function hasPendingTeamRunWork(session: ActiveSession): boolean {
	return (
		session.activeTeamRunIds.size > 0 ||
		session.pendingTeamRunUpdates.length > 0
	);
}

export function shouldAutoContinueTeamRuns(
	session: ActiveSession,
	finishReason: AgentResult["finishReason"],
): boolean {
	if (session.aborting) {
		return false;
	}
	const canAutoContinue =
		finishReason === "completed" || finishReason === "max_iterations";
	if (!canAutoContinue) {
		return false;
	}
	return (
		session.config.enableAgentTeams === true && hasPendingTeamRunWork(session)
	);
}

export function notifyTeamRunWaiters(session: ActiveSession): void {
	const waiters = session.teamRunWaiters.splice(0);
	for (const resolve of waiters) resolve();
}

export async function waitForTeamRunUpdates(
	session: ActiveSession,
): Promise<TeamRunUpdate[]> {
	while (true) {
		if (session.aborting) return [];
		if (session.pendingTeamRunUpdates.length > 0) {
			const updates = [...session.pendingTeamRunUpdates];
			session.pendingTeamRunUpdates.length = 0;
			return updates;
		}
		if (session.activeTeamRunIds.size === 0) return [];
		await new Promise<void>((resolve) => {
			session.teamRunWaiters.push(resolve);
		});
	}
}

export function buildTeamRunContinuationPrompt(
	session: ActiveSession,
	updates: TeamRunUpdate[],
): string {
	const lines = updates.map((u) => {
		const parts = [`- ${u.runId} (${u.agentId}) -> ${u.status}`];
		if (u.taskId) parts.push(` task=${u.taskId}`);
		if (typeof u.iterations === "number")
			parts.push(` iterations=${u.iterations}`);
		if (u.error) parts.push(` error=${u.error}`);
		return parts.join("");
	});
	const remaining = session.activeTeamRunIds.size;
	const instruction =
		remaining > 0
			? `There are still ${remaining} teammate run(s) in progress. Continue coordination and decide whether to wait for more updates.`
			: "No teammate runs are currently in progress. Continue coordination using these updates.";
	return formatModePrompt(
		`System-delivered teammate async run updates:\n${lines.join("\n")}\n\n${instruction}`,
		session.config.mode,
	);
}

export function formatModePrompt(
	prompt: string,
	mode: AgentMode | undefined,
): string {
	return formatUserInputBlock(
		prompt,
		mode === "plan" ? "plan" : mode === "yolo" ? "yolo" : "act",
	);
}

import { describe, expect, it } from "vitest";
import {
	countUserRunMessages,
	getUserRunSpan,
	isUserRunMessage,
	resolveMessageDisplayRole,
} from "./user-run-messages";

describe("user run messages", () => {
	it("counts genuine user prompts but excludes tool results and notices", () => {
		expect(getUserRunSpan({ role: "user", content: "Build it" })).toBe(1);
		expect(
			getUserRunSpan({
				role: "user",
				content: [
					{
						type: "tool_result",
						tool_use_id: "tool-1",
						content: "done",
					},
				],
			}),
		).toBe(0);
		expect(
			getUserRunSpan({
				role: "user",
				content: [
					{ type: "tool-result", toolUseId: "tool-2", content: "done" },
					{ type: "image", mediaType: "image/png", data: "abc" },
				],
			}),
		).toBe(0);
		expect(
			getUserRunSpan({
				role: "user",
				content: "Recovered context",
				metadata: { kind: "recovery_notice" },
			}),
		).toBe(0);
		expect(
			getUserRunSpan({
				role: "user",
				content: "Visible mid-run steering",
				metadata: { userRunSpan: 0 },
			}),
		).toBe(0);
		expect(
			getUserRunSpan({
				role: "user",
				content:
					'<user_input mode="act">[TASK RESUMPTION] Please continue where you left off.</user_input>',
			}),
		).toBe(0);
		expect(
			getUserRunSpan({
				role: "user",
				content: [
					{
						type: "text",
						text: "[TASK RESUMPTION] Please continue where you left off.",
					},
					{ type: "image", mediaType: "image/png", data: "abc" },
				],
			}),
		).toBe(1);
	});

	it("uses persisted compaction spans as absolute run contributions", () => {
		const basicCompaction = {
			role: "user",
			content: "Compacted context",
			metadata: {
				kind: "compaction",
				displayRole: "system",
				userRunSpan: 3,
			},
		};
		const agenticCompaction = {
			role: "user",
			content: "Context summary",
			metadata: {
				kind: "compaction_summary",
				displayRole: "system",
				userRunSpan: 2,
			},
		};
		const messages = [
			basicCompaction,
			agenticCompaction,
			{ role: "user", content: "Latest prompt" },
		];

		expect(getUserRunSpan(basicCompaction)).toBe(3);
		expect(getUserRunSpan(agenticCompaction)).toBe(2);
		expect(countUserRunMessages(messages)).toBe(6);
		expect(isUserRunMessage(basicCompaction)).toBe(true);
		expect(resolveMessageDisplayRole(basicCompaction)).toBe("system");
	});

	it("defaults malformed or legacy compaction spans to one run", () => {
		expect(
			getUserRunSpan({
				role: "user",
				content: "Legacy summary",
				metadata: { kind: "compaction_summary" },
			}),
		).toBe(1);
		expect(
			getUserRunSpan({
				role: "user",
				content: "Malformed span",
				metadata: { kind: "compaction", userRunSpan: -2 },
			}),
		).toBe(1);
	});
});

import { formatDisplayUserInput } from "@cline/shared";

export type MessageDisplayRole =
	| "user"
	| "assistant"
	| "tool"
	| "system"
	| "status"
	| "error";

type MessageLike = {
	role?: unknown;
	content?: unknown;
	metadata?: unknown;
};

const SYNTHETIC_USER_MESSAGE_KINDS = new Set([
	"auto_compaction",
	"compaction_budget_emergency",
	"completion_reminder",
	"loop_detection_notice",
	"manual_compaction",
	"mistake_stop_notice",
	"recovery_notice",
]);

function normalizeMessageRole(role: unknown): MessageDisplayRole {
	switch (role) {
		case "user":
		case "assistant":
		case "tool":
		case "system":
		case "status":
		case "error":
			return role;
		default:
			return "assistant";
	}
}

function readMessageMetadata(
	message: MessageLike,
): Record<string, unknown> | undefined {
	return message.metadata &&
		typeof message.metadata === "object" &&
		!Array.isArray(message.metadata)
		? (message.metadata as Record<string, unknown>)
		: undefined;
}

function readStoredUserRunSpan(
	metadata: Record<string, unknown> | undefined,
): number | undefined {
	const span = metadata?.userRunSpan;
	return typeof span === "number" && Number.isInteger(span) && span >= 0
		? span
		: undefined;
}

function readVisibleUserContent(message: MessageLike): {
	hasAttachment: boolean;
	text: string;
} {
	if (typeof message.content === "string") {
		return { hasAttachment: false, text: message.content };
	}
	if (!Array.isArray(message.content)) {
		// Some history consumers only project role and metadata. Preserve the
		// established role-based behavior when content is unavailable.
		return { hasAttachment: false, text: "unknown" };
	}
	let hasAttachment = false;
	let hasToolResult = false;
	const text: string[] = [];
	for (const item of message.content) {
		if (!item || typeof item !== "object" || Array.isArray(item)) {
			continue;
		}
		const block = item as Record<string, unknown>;
		if (block.type === "text" && typeof block.text === "string") {
			text.push(block.text);
		} else if (block.type === "tool_result" || block.type === "tool-result") {
			hasToolResult = true;
		} else if (block.type === "file" || block.type === "image") {
			hasAttachment = true;
		}
	}
	return {
		// Tool-result messages can contain media, but that media belongs to the
		// tool output rather than a visible user prompt.
		hasAttachment: hasAttachment && !hasToolResult,
		text: text.join("\n"),
	};
}

function isSyntheticContinuationPrompt(text: string): boolean {
	const normalized = formatDisplayUserInput(text);
	return (
		normalized.startsWith("[TASK RESUMPTION]") ||
		normalized ===
			"The user approved switching to act mode. Continue with the approved plan now."
	);
}

/** Resolves the role a persisted message should use when presented to a user. */
export function resolveMessageDisplayRole(
	message: MessageLike,
): MessageDisplayRole {
	const role = normalizeMessageRole(message.role);
	const metadata = readMessageMetadata(message);
	const displayRole =
		typeof metadata?.displayRole === "string"
			? metadata.displayRole.trim().toLowerCase()
			: "";
	if (
		displayRole === "system" ||
		displayRole === "status" ||
		displayRole === "error"
	) {
		return displayRole;
	}
	return role;
}

/**
 * Returns how many absolute root runs a persisted message represents.
 *
 * Compaction can fold several earlier user turns into one synthetic message.
 * Its persisted span keeps later visible prompts aligned with checkpoint
 * history. Tool results and system-injected user-role messages contribute no
 * runs.
 */
export function getUserRunSpan(message: MessageLike): number {
	if (normalizeMessageRole(message.role) !== "user") {
		return 0;
	}
	const metadata = readMessageMetadata(message);
	const kind = typeof metadata?.kind === "string" ? metadata.kind : undefined;
	const storedSpan = readStoredUserRunSpan(metadata);
	if (kind === "compaction" || kind === "compaction_summary") {
		return storedSpan ?? 1;
	}
	if (storedSpan !== undefined) {
		return storedSpan;
	}
	if (kind && SYNTHETIC_USER_MESSAGE_KINDS.has(kind)) {
		return 0;
	}
	const content = readVisibleUserContent(message);
	if (!content.hasAttachment && !formatDisplayUserInput(content.text)) {
		return 0;
	}
	if (!content.hasAttachment && isSyntheticContinuationPrompt(content.text)) {
		return 0;
	}
	return 1;
}

export function isUserRunMessage(message: MessageLike): boolean {
	return getUserRunSpan(message) > 0;
}

export function countUserRunMessages(
	messages: readonly MessageLike[] | undefined,
): number {
	let count = 0;
	for (const message of messages ?? []) {
		count += getUserRunSpan(message);
	}
	return count;
}

