import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import type { ModelInfo } from "@cline/shared";
import {
	fetchClineRecommendedModelsPayload,
	normalizeClineRecommendedProviderModels,
} from "../src/catalog/catalog-cline-recommended";
import type { ModelsDevGeneratedProviderSpec } from "../src/catalog/catalog-live";
import { loadModelsDevCatalog } from "./models/generate-models-dev";

const MODEL_OUTPUT_FILE = "src/catalog/catalog.generated.ts";
const PROVIDER_OUTPUT_FILE = "src/providers/providers.generated.ts";
const PROVIDER_IDS_OUTPUT_FILE = "src/providers/provider-ids.generated.ts";

function sortObjectByKey<T>(
	input: Record<string, T>,
	order: "asc" | "desc" = "asc",
): Record<string, T> {
	return Object.fromEntries(
		Object.entries(input).sort(([a], [b]) =>
			order === "asc" ? a.localeCompare(b) : b.localeCompare(a),
		),
	);
}

function normalizeValue(value: unknown): unknown {
	if (Array.isArray(value)) {
		return value.map(normalizeValue);
	}
	if (value && typeof value === "object") {
		const objectValue = value as Record<string, unknown>;
		return Object.fromEntries(
			Object.entries(objectValue)
				.sort(([a], [b]) => a.localeCompare(b))
				.map(([key, nestedValue]) => [key, normalizeValue(nestedValue)]),
		);
	}
	return value;
}

async function writeGeneratedProviderIds(
	outputPath: string,
	generatedProviderIds: readonly string[],
): Promise<void> {
	const output = `/**
 * Auto-generated provider identifiers.
 *
 * Generated by: @cline/llms/scripts/generate-models.ts
 *
 * This is only the models.dev-derived subset. Use BUILT_IN_PROVIDER_IDS from
 * ./ids.ts for the complete registry, including handwritten product and local
 * providers from ./builtins.ts.
 *
 * WARNING: DO NOT EDIT THIS FILE MANUALLY.
 */
export const GENERATED_PROVIDER_IDS = ${JSON.stringify(generatedProviderIds, null, 2)} as const;
`;

	mkdirSync(dirname(outputPath), { recursive: true });

	if (existsSync(outputPath)) {
		if (readFileSync(outputPath, "utf8") === output) {
			console.log(`No changes detected for ${PROVIDER_IDS_OUTPUT_FILE}`);
			return;
		}
	}

	writeFileSync(outputPath, output, "utf8");
	console.log(`Generated ${PROVIDER_IDS_OUTPUT_FILE}`);
}

async function writeGeneratedProviderSpecs(
	outputPath: string,
	providerIdsOutputPath: string,
	providerSpecs: Record<string, ModelsDevGeneratedProviderSpec>,
): Promise<void> {
	if (Object.keys(providerSpecs).length === 0) {
		if (existsSync(outputPath)) {
			console.warn(
				`Skipping provider generation: no provider specs were loaded. Existing generated providers were left unchanged.`,
			);
			return;
		}
		throw new Error(
			"Aborting provider generation: no provider specs were loaded. No existing generated providers file was found.",
		);
	}

	const generatedProviderSpecs = Object.values(providerSpecs);
	const generatedProviderIds = generatedProviderSpecs.map((spec) => spec.id);
	const output = `/**
 * Auto-generated provider catalog.
 *
 * Generated by: @cline/llms/scripts/generate-models.ts
 *
 * To generate a models.dev provider, ensure its upstream entry uses an AI SDK
 * package supported by catalog-live.ts. Add an ID mapping in provider-keys.ts
 * when Cline's generated ID differs from the models.dev key, and ensure the ID
 * is not in MODELS_DEV_BLOCKED_PROVIDER_IDS. Then run:
 *   bun -F @cline/llms generate:models
 *
 * Product/runtime-only providers belong in builtins.ts and are merged with
 * this catalog; they do not need to appear in this generated file.
 *
 * WARNING: DO NOT EDIT THIS FILE MANUALLY.
 */
import type { BuiltinSpec } from "./builtin-types";

export const GENERATED_PROVIDER_SPECS: readonly BuiltinSpec[] = ${JSON.stringify(generatedProviderSpecs, null, 2)};
`;

	mkdirSync(dirname(outputPath), { recursive: true });
	await writeGeneratedProviderIds(providerIdsOutputPath, generatedProviderIds);

	if (existsSync(outputPath)) {
		if (readFileSync(outputPath, "utf8") === output) {
			console.log(`No changes detected for ${PROVIDER_OUTPUT_FILE}`);
			console.log(`Generated providers: ${generatedProviderSpecs.length}`);
			return;
		}
	}

	writeFileSync(outputPath, output, "utf8");
	console.log(`Generated ${PROVIDER_OUTPUT_FILE}`);
	console.log(`Generated providers: ${generatedProviderSpecs.length}`);
}

async function generate(): Promise<void> {
	const __filename = fileURLToPath(import.meta.url);
	const __dirname = dirname(__filename);
	const root = join(__dirname, "..");
	const modelOutputPath = join(root, MODEL_OUTPUT_FILE);
	const providerOutputPath = join(root, PROVIDER_OUTPUT_FILE);
	const providerIdsOutputPath = join(root, PROVIDER_IDS_OUTPUT_FILE);

	const providerModels: Record<string, Record<string, ModelInfo>> = {};
	let providerSpecs: Record<string, ModelsDevGeneratedProviderSpec> = {};
	let loadError: Error | undefined;

	const [modelsDevResult, clineRecommendedPayloadResult] = await Promise.all([
		loadModelsDevCatalog().catch((error) => {
			loadError =
				error instanceof Error ? error : new Error(String(error ?? "unknown"));
			return {
				providerModels: {},
				providerSpecs: {},
			};
		}),
		fetchClineRecommendedModelsPayload(fetch).catch((error) => {
			loadError =
				error instanceof Error ? error : new Error(String(error ?? "unknown"));
			return undefined;
		}),
	]);

	Object.assign(providerModels, modelsDevResult.providerModels);
	providerSpecs = modelsDevResult.providerSpecs;

	if (clineRecommendedPayloadResult) {
		Object.assign(
			providerModels,
			normalizeClineRecommendedProviderModels(
				clineRecommendedPayloadResult,
				providerModels.openrouter || {},
			),
		);
	}

	if (Object.keys(providerModels).length === 0) {
		const details = loadError?.message ?? "unknown error";
		if (existsSync(modelOutputPath)) {
			console.warn(
				`Skipping model generation: no provider models were loaded (${details}). Existing generated catalog was left unchanged.`,
			);
			return;
		}
		throw new Error(
			`Aborting model generation: no provider models were loaded (${details}). No existing generated catalog was found.`,
		);
	}

	const sortedProviders = sortObjectByKey(providerModels);
	const sortedProviderSpecs = sortObjectByKey(providerSpecs);
	const generatedModelsVersion = Date.now();
	const output = `/**
 * Auto-generated model catalog.
 *
 * Generated by: @cline/llms/scripts/generate-models.ts
 *
 * WARNING: DO NOT EDIT THIS FILE MANUALLY.
 */
import type { ModelInfo } from "@cline/shared";
/**
 * Model list auto-generated for built-in providers
 * listed in @cline/llms/src/providers/provider-keys.ts
*/
export const GENERATED_PROVIDER_MODELS: {
  version: number
  providers: Record<string, Record<string, ModelInfo>>
} = {
  version: ${JSON.stringify(generatedModelsVersion)},
  providers: ${JSON.stringify(sortedProviders, null, 2)}
}
`;
	mkdirSync(dirname(modelOutputPath), { recursive: true });

	if (existsSync(modelOutputPath)) {
		const nextProviders = normalizeValue(sortedProviders);
		let existingProviders: unknown | undefined;
		try {
			const existingModule = (await import(
				"../src/catalog/catalog.generated.js"
			)) as {
				GENERATED_PROVIDER_MODELS?: {
					providers?: Record<string, Record<string, ModelInfo>>;
				};
			};
			existingProviders = existingModule.GENERATED_PROVIDER_MODELS?.providers;
		} catch {
			existingProviders = undefined;
		}
		if (
			existingProviders &&
			JSON.stringify(normalizeValue(existingProviders)) ===
				JSON.stringify(nextProviders)
		) {
			await writeGeneratedProviderSpecs(
				providerOutputPath,
				providerIdsOutputPath,
				sortedProviderSpecs,
			);
			const totalModels = Object.values(sortedProviders).reduce(
				(count, models) => count + Object.keys(models).length,
				0,
			);
			console.log(`No changes detected for ${MODEL_OUTPUT_FILE}`);
			console.log(`Providers: ${Object.keys(sortedProviders).length}`);
			console.log(`Models: ${totalModels}`);
			return;
		}
	}

	writeFileSync(modelOutputPath, output, "utf8");

	await writeGeneratedProviderSpecs(
		providerOutputPath,
		providerIdsOutputPath,
		sortedProviderSpecs,
	);

	const totalModels = Object.values(sortedProviders).reduce(
		(count, models) => count + Object.keys(models).length,
		0,
	);
	console.log(`Generated ${MODEL_OUTPUT_FILE}`);
	console.log(`Providers: ${Object.keys(sortedProviders).length}`);
	console.log(`Models: ${totalModels}`);
}

generate().catch((error) => {
	console.error(error instanceof Error ? error.message : String(error));
	process.exitCode = 1;
});

#!/usr/bin/env bun

import type { ModelInfo } from "@cline/shared";
import {
	fetchModelsDevCatalog,
	fetchModelsDevProviderModels,
	type ModelsDevGeneratedProviderSpec,
} from "../../src/catalog/catalog-live";

function sortObjectByKey<T>(
	input: Record<string, T>,
	order: "asc" | "desc" = "asc",
): Record<string, T> {
	return Object.fromEntries(
		Object.entries(input).sort(([a], [b]) =>
			order === "asc" ? a.localeCompare(b) : b.localeCompare(a),
		),
	);
}

export async function loadModelsDevProviderModels(): Promise<
	Record<string, Record<string, ModelInfo>>
> {
	const providerModels = await fetchModelsDevProviderModels(
		"https://models.dev/api.json",
	);
	return sortObjectByKey(providerModels);
}

export async function loadModelsDevCatalog(): Promise<{
	providerModels: Record<string, Record<string, ModelInfo>>;
	providerSpecs: Record<string, ModelsDevGeneratedProviderSpec>;
}> {
	const catalog = await fetchModelsDevCatalog("https://models.dev/api.json");
	return {
		providerModels: sortObjectByKey(catalog.providerModels),
		providerSpecs: sortObjectByKey(catalog.providerSpecs),
	};
}

import { getClineEnvironmentConfig } from "@cline/shared";
import type { ModelInfo } from "./types";

export interface ClineRecommendedModelEntry {
	id: string;
	name?: string;
	description?: string;
}

export interface ClineRecommendedModelsPayload {
	clinePass?: ClineRecommendedModelEntry[];
	free?: ClineRecommendedModelEntry[];
}

type ModelCapabilities = Pick<
	ModelInfo,
	| "contextWindow"
	| "maxInputTokens"
	| "maxTokens"
	| "capabilities"
	| "reasoningOptions"
	| "pricing"
>;

const CLINE_PASS_PROVIDER_ID = "cline-pass";
const CLINE_PROVIDER_ID = "cline";

const CLINE_PASS_MODEL_DEFAULTS = {
	contextWindow: 128_000,
	maxInputTokens: 128_000,
	maxTokens: 8_192,
	capabilities: ["tools", "reasoning", "temperature"],
	pricing: {
		input: 0,
		output: 0,
		cacheRead: 0,
		cacheWrite: 0,
	},
} as const satisfies ModelCapabilities;

function findORModelCapabilities(
	entry: ClineRecommendedModelEntry,
	openRouterModels: Record<string, ModelInfo>,
): ModelCapabilities {
	if (!openRouterModels) {
		return CLINE_PASS_MODEL_DEFAULTS;
	}

	const modelSlug = entry.id.split("/").at(-1) ?? entry.id;

	return openRouterModels[modelSlug] || CLINE_PASS_MODEL_DEFAULTS;
}

// Cline-Pass models have only the model name (and not the lab),
// so we need to look-up using glm-5.2 instead of cline-pass/glm-5.2
function buildModelsNameMap(
	openrouterModels: Record<string, ModelInfo>,
): Record<string, ModelInfo> {
	const nameMap: Record<string, ModelInfo> = {};

	for (const model of Object.values(openrouterModels)) {
		const modelSlugWithoutProvider = model.id.split("/").at(-1) ?? model.id;

		nameMap[modelSlugWithoutProvider] = model;
	}

	return nameMap;
}

export function normalizeClineRecommendedProviderModels(
	payload: ClineRecommendedModelsPayload,
	openRouterModels: Record<string, ModelInfo>,
): Record<string, Record<string, ModelInfo>> {
	const clinePass = payload.clinePass ?? [];
	const models: Record<string, ModelInfo> = {};
	const clineFreeModels: Record<string, ModelInfo> = {};
	const openRouterModelsByName = buildModelsNameMap(openRouterModels);

	clinePass.forEach((entry) => {
		const capabilities = findORModelCapabilities(entry, openRouterModelsByName);

		models[entry.id] = {
			// We should use the OR name, unless there is not one (like when using defaults)
			name: entry.name,
			...capabilities,
			id: entry.id,
			description: entry.description,
		};
	});

	// Cline free models are selectable on the ClinePass provider too (same API
	// underneath; they ride usage billing at $0 instead of the subscription quota).
	// Unlike pass models their ids are full OpenRouter-style ids or cline-free ids,
	// so look up capabilities by full id before falling back to the slug map.
	(payload.free ?? []).forEach((entry) => {
		const capabilities =
			openRouterModels?.[entry.id] ??
			findORModelCapabilities(entry, openRouterModelsByName);
		// The recommended-models endpoint only sends slug-like names (e.g.
		// "deepseek-v4-flash"), so prefer the OpenRouter catalog's display name
		// for every free entry. Without this, the free overlay overwrites the
		// nice OpenRouter names in the merged cline/cline-pass catalogs and the
		// pickers end up rendering raw model ids for the Free section.
		const entryName =
			capabilities.name?.trim() || entry.name?.trim() || entry.id;
		const name = entry.id.startsWith("cline-free/")
			? `${entryName} (free)`
			: entryName;

		const modelInfo = {
			...capabilities,
			name,
			id: entry.id,
			description: entry.description,
		};

		clineFreeModels[entry.id] = {
			...modelInfo,
			pricing: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
		};

		if (models[entry.id]) {
			return;
		}

		models[entry.id] = {
			...modelInfo,
			pricing: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
		};
	});

	const result: Record<string, Record<string, ModelInfo>> = {};
	if (Object.keys(clineFreeModels).length > 0) {
		result[CLINE_PROVIDER_ID] = clineFreeModels;
	}
	if (clinePass.length > 0) {
		result[CLINE_PASS_PROVIDER_ID] = models;
	}
	return result;
}

export async function fetchClineRecommendedModelsPayload(
	fetcher: typeof fetch = fetch,
): Promise<ClineRecommendedModelsPayload> {
	const url = `${getClineEnvironmentConfig().apiBaseUrl}/api/v1/ai/cline/recommended-models`;
	const response = await fetcher(url);
	if (!response.ok) {
		throw new Error(
			`Failed to load Cline recommended models from ${url}: HTTP ${response.status}`,
		);
	}

	return (await response.json()) as ClineRecommendedModelsPayload;
}

export async function fetchClineRecommendedProviderModels(
	fetcher: typeof fetch = fetch,
	openRouterModels: Record<string, ModelInfo>,
): Promise<Record<string, Record<string, ModelInfo>>> {
	const payload = await fetchClineRecommendedModelsPayload(fetcher);
	return normalizeClineRecommendedProviderModels(payload, openRouterModels);
}

