// Ollama: the vendor-level retry wrap was replaced by the central one; prove
// the provider still retries after the refactor.

const ollamaDoStreamMock = vi.hoisted(() =>
	vi.fn<() => Promise<LanguageModelV4StreamResult>>(),
);

vi.mock("ollama-ai-provider-v2", () => ({
	createOllama: () => ({
		chat: (modelId: string) => ({
			specificationVersion: "v4",
			provider: "ollama",
			modelId,
			supportedUrls: {},
			doGenerate: async () => {
				throw new Error("doGenerate is not used by the streaming path");
			},
			doStream: ollamaDoStreamMock,
		}),
	}),
}));

const v4Usage = {
	inputTokens: {
		total: 1,
		noCache: undefined,
		cacheRead: undefined,
		cacheWrite: undefined,
	},
	outputTokens: { total: 1, text: undefined, reasoning: undefined },
} as never;

function v4Stream(
	parts: LanguageModelV4StreamPart[],
): LanguageModelV4StreamResult {
	return {
		stream: new ReadableStream<LanguageModelV4StreamPart>({
			start(controller) {
				for (const part of parts) {
					controller.enqueue(part);
				}
				controller.close();
			},
		}),
	};
}

const v4EmptyParts: LanguageModelV4StreamPart[] = [
	{ type: "stream-start", warnings: [] },
	{
		type: "finish",
		finishReason: { unified: "stop", raw: "stop" },
		usage: v4Usage,
	},
];
const v4TextParts: LanguageModelV4StreamPart[] = [
	{ type: "stream-start", warnings: [] },
	{ type: "text-start", id: "t" },
	{ type: "text-delta", id: "t", delta: "hello" },
	{ type: "text-end", id: "t" },
	{
		type: "finish",
		finishReason: { unified: "stop", raw: "stop" },
		usage: v4Usage,
	},
];

async function streamThroughOllama(
	parts: LanguageModelV4StreamPart[][],
): Promise<AgentModelEvent[]> {
	ollamaDoStreamMock.mockReset();
	for (const attempt of parts) {
		ollamaDoStreamMock.mockResolvedValueOnce(v4Stream(attempt));
	}
	const config = { providerId: "ollama" };
	const provider = await createOllamaProvider(config);
	return collect(
		await provider.stream(streamRequest(), providerContext("ollama", config)),
	);
}

describe("ollama (central wrap replaces the old vendor-level wrap)", () => {
	it("retries an empty turn and streams the successful attempt", async () => {
		const events = await streamThroughOllama([v4EmptyParts, v4TextParts]);

		expect(ollamaDoStreamMock).toHaveBeenCalledTimes(2);
		expect(hasTextDelta(events, "hello")).toBe(true);
		expect(finishEvents(events)).toHaveLength(1);
	});
});

describe("full path: model output classes through emitAiSdkEvents", () => {
	it("converts a file-only turn into a file event instead of retrying or dropping it", async () => {
		const events = await streamThroughOllama([
			[
				{ type: "stream-start", warnings: [] },
				{
					type: "file",
					mediaType: "image/png",
					data: { type: "data", data: "aGVsbG8=" },
				} as LanguageModelV4StreamPart,
				{
					type: "finish",
					finishReason: { unified: "stop", raw: "stop" },
					usage: v4Usage,
				},
			],
		]);

		// Not retried (a generated file is content)...
		expect(ollamaDoStreamMock).toHaveBeenCalledTimes(1);
		// ...and converted, so the assistant message will not be empty.
		const fileEvent = events.find((event) => event.type === "file");
		expect(fileEvent).toMatchObject({
			type: "file",
			mediaType: "image/png",
			data: "aGVsbG8=",
		});
	});

	it("does not retry a custom-only turn (unsupported output is not empty)", async () => {
		const events = await streamThroughOllama([
			[
				{ type: "stream-start", warnings: [] },
				{
					type: "custom",
					kind: "anthropic.container",
				} as LanguageModelV4StreamPart,
				{
					type: "finish",
					finishReason: { unified: "stop", raw: "stop" },
					usage: v4Usage,
				},
			],
		]);

		// The model responded; retrying would re-bill for the same output.
		// The adapter does not convert custom parts (explicitly unsupported),
		// so no content events are emitted — the downstream empty-message
		// failure, if it happens, is honest rather than masked by retries.
		expect(ollamaDoStreamMock).toHaveBeenCalledTimes(1);
		expect(events.some((event) => event.type === "text-delta")).toBe(false);
		expect(finishEvents(events)).toHaveLength(1);
	});

	it("aggregates discarded-attempt usage into the final usage event", async () => {
		const usageOf = (input: number, output: number) =>
			({
				inputTokens: {
					total: input,
					noCache: undefined,
					cacheRead: undefined,
					cacheWrite: undefined,
				},
				outputTokens: { total: output, text: undefined, reasoning: undefined },
			}) as never;
		const emptyAttempt = (input: number, output: number) => [
			{ type: "stream-start", warnings: [] } as LanguageModelV4StreamPart,
			{
				type: "finish",
				finishReason: { unified: "stop", raw: "stop" },
				usage: usageOf(input, output),
			} as LanguageModelV4StreamPart,
		];
		const events = await streamThroughOllama([
			emptyAttempt(7, 3),
			emptyAttempt(9, 2),
			[
				{ type: "stream-start", warnings: [] },
				{ type: "text-start", id: "t" },
				{ type: "text-delta", id: "t", delta: "hello" },
				{ type: "text-end", id: "t" },
				{
					type: "finish",
					finishReason: { unified: "stop", raw: "stop" },
					usage: usageOf(11, 5),
				},
			],
		]);

		expect(ollamaDoStreamMock).toHaveBeenCalledTimes(3);
		const usageEvent = events.find((event) => event.type === "usage") as
			| { usage: { inputTokens?: number; outputTokens?: number } }
			| undefined;
		expect(usageEvent).toBeDefined();
		// 7 + 9 + 11 input, 3 + 2 + 5 output across all three attempts.
		expect(usageEvent?.usage.inputTokens).toBe(27);
		expect(usageEvent?.usage.outputTokens).toBe(10);
	});
});

describe("withEmptyResponseRetry", () => {
	function fakeModel(results: LanguageModelV4StreamResult[]): LanguageModelV4 {
		const doStream = vi.fn();
		for (const result of results) {
			doStream.mockResolvedValueOnce(result);
		}
		return {
			specificationVersion: "v4",
			provider: "fake",
			modelId: "fake-model",
			supportedUrls: {},
			doGenerate: vi.fn(),
			doStream,
		} as unknown as LanguageModelV4;
	}

	it("returns the model unchanged when a vendor opts out", () => {
		const model = fakeModel([]);
		expect(withEmptyResponseRetry(model, false, undefined)).toBe(model);
	});

	it("wraps by default, preserving the model identity fields", () => {
		const model = fakeModel([]);
		const wrapped = withEmptyResponseRetry(
			model,
			undefined,
			undefined,
		) as LanguageModelV4;
		expect(wrapped).not.toBe(model);
		expect(wrapped.specificationVersion).toBe("v4");
		expect(wrapped.provider).toBe("fake");
		expect(wrapped.modelId).toBe("fake-model");
	});

	it("threads vendor-provided retry options to the middleware", async () => {
		const model = fakeModel([
			v4Stream(v4EmptyParts),
			v4Stream(v4EmptyParts),
			v4Stream(v4EmptyParts),
		]);
		const wrapped = withEmptyResponseRetry(
			model,
			{ maxAttempts: 2, retryDelayMs: 0 },
			undefined,
		) as LanguageModelV4;

		const result = await wrapped.doStream({} as never);
		const reader = result.stream.getReader();
		while (!(await reader.read()).done) {
			// drain
		}

		expect(model.doStream).toHaveBeenCalledTimes(2);
	});
});

import { describe, expect, it } from "vitest";
import fixtures from "../../fixtures/usage.json";
import { normalizeUsage } from "./ai-sdk";

/**
 * These tests validate usage normalization across different AI SDK stream result shapes.
 * We test against real fixture data from multiple providers to ensure:
 * - Finish part usage (AiSdkStreamFinishPart.totalUsage) normalizes correctly
 * - Stream.usage promise result (AiSdkStreamUsage) normalizes correctly with raw data
 * - Token counts map from provider-specific field names to standard format
 * - Cost extraction works when available in raw provider response
 */

// Import normalizeUsage - would need to export this from ai-sdk.ts for testing
// For now, documenting what we'd test when exported
const testCases = [
	{
		provider: "openrouter",
		description: "handles cache tokens and upstream cost breakdown",
		finishUsage: (
			(fixtures as Record<string, unknown>).openrouter_finish as Record<
				string,
				unknown
			>
		).totalUsage,
		streamUsage: (fixtures as Record<string, unknown>)
			.openrouter_stream_usage as Record<string, unknown>,
		expectedNormalized: {
			inputTokens: 9096,
			outputTokens: 77,
			cacheReadTokens: 9090,
			cacheWriteTokens: 0,
		},
		expectedNormalizedStreamUsage: {
			inputTokens: 9096,
			outputTokens: 77,
			cacheReadTokens: 9090,
			cacheWriteTokens: 0,
			totalCost: 0.0068249999999999995, // BYOK fee + upstream provider cost
		},
	},
	{
		provider: "gemini",
		description: "maps Gemini's promptTokenCount to inputTokens",
		finishUsage: (
			(fixtures as Record<string, unknown>).gemini_finish as Record<
				string,
				unknown
			>
		).totalUsage,
		streamUsage: (fixtures as Record<string, unknown>)
			.gemini_stream_usage as Record<string, unknown>,
		expectedNormalized: {
			inputTokens: 4605,
			outputTokens: 120,
			cacheReadTokens: 0,
			cacheWriteTokens: 0,
		},
	},
	{
		provider: "anthropic",
		description: "extracts cache tokens from Anthropic's raw response",
		finishUsage: (
			(fixtures as Record<string, unknown>).anthropic_finish as Record<
				string,
				unknown
			>
		).totalUsage,
		streamUsage: (fixtures as Record<string, unknown>)
			.anthropic_stream_usage as Record<string, unknown>,
		expectedNormalized: {
			inputTokens: 6538,
			outputTokens: 176,
			cacheReadTokens: 0,
			cacheWriteTokens: 6535, // Now extracted from nested inputTokenDetails.cacheWriteTokens
		},
		expectedNormalizedStreamUsage: {
			inputTokens: 6538,
			outputTokens: 176,
			cacheReadTokens: 0,
			cacheWriteTokens: 6535, // Extracted from nested inputTokenDetails.cacheWriteTokens
		},
	},
	{
		provider: "openai",
		description: "handles OpenAI's input_tokens_details.cached_tokens",
		finishUsage: (
			(fixtures as Record<string, unknown>).openai_finish as Record<
				string,
				unknown
			>
		).totalUsage,
		streamUsage: (fixtures as Record<string, unknown>)
			.openai_stream_usage as Record<string, unknown>,
		expectedNormalized: {
			inputTokens: 3824,
			outputTokens: 14,
			cacheReadTokens: 0,
			cacheWriteTokens: 0,
		},
	},
	{
		provider: "vercel",
		description:
			"preserves finish-part totals when Vercel reports cached tokens",
		finishUsage: (
			(fixtures as Record<string, unknown>).vercel_finish as Record<
				string,
				unknown
			>
		).totalUsage,
		streamUsage: (fixtures as Record<string, unknown>)
			.vercel_stream_usage as Record<string, unknown>,
		expectedNormalized: {
			inputTokens: 6781,
			outputTokens: 70,
			cacheReadTokens: 6667,
			cacheWriteTokens: 0,
		},
		expectedNormalizedStreamUsage: {
			inputTokens: 4550,
			outputTokens: 10,
			cacheReadTokens: 0,
			cacheWriteTokens: 0,
			totalCost: 0.000641,
		},
	},
];

describe("ai-sdk usage normalization", () => {
	describe.each(testCases)("$provider", ({
		description,
		finishUsage,
		streamUsage,
		expectedNormalized,
		expectedNormalizedStreamUsage,
	}) => {
		it(`finish part: ${description}`, () => {
			const normalized = normalizeUsage(finishUsage as Record<string, unknown>);
			expect(normalized.inputTokens).toBe(expectedNormalized.inputTokens);
			expect(normalized.outputTokens).toBe(expectedNormalized.outputTokens);
			expect(normalized.cacheReadTokens).toBe(
				expectedNormalized.cacheReadTokens,
			);
			expect(normalized.cacheWriteTokens).toBe(
				expectedNormalized.cacheWriteTokens,
			);
		});

		it(`stream.usage: ${description}`, () => {
			const normalized = normalizeUsage(streamUsage as Record<string, unknown>);
			const expected = (expectedNormalizedStreamUsage ??
				expectedNormalized) as Record<string, unknown>;
			expect(normalized.inputTokens).toBe(expected.inputTokens);
			expect(normalized.outputTokens).toBe(expected.outputTokens);
			expect(normalized.cacheReadTokens).toBe(expected.cacheReadTokens);
			expect(normalized.cacheWriteTokens).toBe(expected.cacheWriteTokens);
			if (typeof expected.totalCost === "number") {
				expect(normalized.totalCost).toBeCloseTo(expected.totalCost, 5);
			}
		});
	});

	it("finish part lacks raw provider metadata", () => {
		const finishPart = (fixtures as Record<string, unknown>)
			.openrouter_finish as Record<string, unknown>;
		expect(finishPart).not.toHaveProperty("raw");
		expect(finishPart).toHaveProperty("type", "finish");
	});

	it("stream.usage includes raw provider response", () => {
		const streamUsage = (fixtures as Record<string, unknown>)
			.openrouter_stream_usage as Record<string, unknown>;
		expect(streamUsage).toHaveProperty("raw");
		expect(streamUsage.raw).toHaveProperty("cost_details");
	});

	it("maps provider reasoning tokens to reasoningTokenCount", () => {
		expect(
			normalizeUsage({
				completion_tokens_details: { reasoning_tokens: 17 },
			}).reasoningTokenCount,
		).toBe(17);
		expect(
			normalizeUsage({
				outputTokenDetails: { reasoningTokens: 23 },
			}).reasoningTokenCount,
		).toBe(23);
		expect(
			normalizeUsage({
				raw: { outputTokenDetails: { reasoningTokens: 31 } },
			}).reasoningTokenCount,
		).toBe(31);
		expect(
			normalizeUsage({}, { openrouter: { usage: { reasoning_tokens: 37 } } })
				.reasoningTokenCount,
		).toBe(37);
	});

	it("preserves source precedence when multiple reasoning token values exist", () => {
		const normalized = normalizeUsage(
			{
				reasoningTokens: 11,
				raw: { reasoningTokens: 22 },
			},
			{ openrouter: { usage: { reasoning_tokens: 33 } } },
		);

		expect(normalized.reasoningTokenCount).toBe(11);
	});

	it("coerces string reasoning token counts", () => {
		expect(
			normalizeUsage({
				raw: { outputTokenDetails: { reasoningTokens: "41" } },
			}).reasoningTokenCount,
		).toBe(41);
	});

	describe("cost extraction with pricing fallback", () => {
		it("uses market_cost when available (Vercel)", () => {
			const vercelUsage = (fixtures as Record<string, unknown>)
				.vercel_stream_usage as Record<string, unknown>;
			const normalized = normalizeUsage(vercelUsage);
			expect(normalized.totalCost).toBe(0.000641);
		});

		it("sums BYOK fee + upstream provider cost when OpenRouter marks the request as BYOK", () => {
			const openrouterUsage = (fixtures as Record<string, unknown>)
				.openrouter_stream_usage as Record<string, unknown>;
			const normalized = normalizeUsage(openrouterUsage);
			expect(normalized.totalCost).toBeCloseTo(0.006825, 5);
		});

		it("does not double-count OpenRouter credit-billed usage when upstream mirrors cost", () => {
			const normalized = normalizeUsage({
				prompt_tokens: 15,
				completion_tokens: 5,
				cost: 0.0000301,
				is_byok: false,
				cost_details: {
					upstream_inference_cost: 0.0000301,
				},
			});

			expect(normalized.totalCost).toBe(0.0000301);
		});

		it("uses upstream inference cost when OpenRouter reports no account charge for BYOK", () => {
			const normalized = normalizeUsage({
				prompt_tokens: 10,
				completion_tokens: 5,
				cost: 0,
				is_byok: true,
				cost_details: {
					upstream_inference_cost: 0.000036,
				},
			});

			expect(normalized.totalCost).toBe(0.000036);
		});

		it("falls back to upstream inference cost when it is the only explicit cost", () => {
			const normalized = normalizeUsage({
				prompt_tokens: 10,
				completion_tokens: 5,
				cost_details: {
					upstream_inference_cost: 0.000036,
				},
			});

			expect(normalized.totalCost).toBe(0.000036);
		});

		it("calculates cost from pricing when no explicit cost in response", () => {
			const pricingInput = { input: 2.5, output: 10 }; // per 1M tokens
			const normalized = normalizeUsage(
				{ inputTokens: 1000, outputTokens: 100 },
				undefined,
				pricingInput,
			);
			// (1000/1M) * 2.5 + (100/1M) * 10 = 0.0025 + 0.001 = 0.0035
			expect(normalized.totalCost).toBeCloseTo(0.0035, 5);
		});
	});

	describe("field mapping across providers", () => {
		it("maps AI SDK v3 usage token details", () => {
			const normalized = normalizeUsage({
				inputTokens: {
					total: 4605,
					noCache: 1000,
					cacheRead: 3605,
					cacheWrite: undefined,
				},
				outputTokens: {
					total: 120,
					text: 120,
					reasoning: 0,
				},
				raw: {
					promptTokenCount: 4605,
					candidatesTokenCount: 120,
					cachedContentTokenCount: 3605,
				},
			} as Record<string, unknown>);

			expect(normalized.inputTokens).toBe(4605);
			expect(normalized.outputTokens).toBe(120);
			expect(normalized.cacheReadTokens).toBe(3605);
			expect(normalized.cacheWriteTokens).toBe(0);
		});

		it("falls back to raw Gemini usage metadata", () => {
			const normalized = normalizeUsage({
				raw: {
					promptTokenCount: 4605,
					candidatesTokenCount: 120,
					cachedContentTokenCount: 3605,
				},
			} as Record<string, unknown>);

			expect(normalized.inputTokens).toBe(4605);
			expect(normalized.outputTokens).toBe(120);
			expect(normalized.cacheReadTokens).toBe(3605);
			expect(normalized.cacheWriteTokens).toBe(0);
		});

		it("maps camelCase inputTokens from multiple naming conventions", () => {
			const inputs = [
				{ inputTokens: 100 }, // Already camelCase
				{ input_tokens: 100 }, // snake_case
				{ prompt_tokens: 100 }, // OpenAI convention
			];
			// Each should normalize to inputTokens: 100
			expect(inputs.length).toBe(3);
		});

		it("extracts cacheReadTokens from nested structures", () => {
			const nested = {
				inputTokenDetails: { cacheReadTokens: 50 }, // Nested camelCase
			};
			const flattened = {
				cache_read_tokens: 50, // Flat snake_case
			};
			// Both should normalize to cacheReadTokens: 50
			expect(nested).toBeDefined();
			expect(flattened).toBeDefined();
		});

		it("extracts Qwen cache writes from OpenRouter prompt token details", () => {
			const normalized = normalizeUsage({
				prompt_tokens: 10126,
				completion_tokens: 13,
				prompt_tokens_details: {
					cached_tokens: 0,
					cache_write_tokens: 10106,
				},
			});

			expect(normalized).toEqual(
				expect.objectContaining({
					inputTokens: 10126,
					outputTokens: 13,
					cacheReadTokens: 0,
					cacheWriteTokens: 10106,
				}),
			);
		});

		it("extracts Qwen cache reads from raw prompt token details", () => {
			const normalized = normalizeUsage({
				raw: {
					prompt_tokens_details: {
						cached_tokens: 8885,
						cache_write_tokens: 10106,
					},
				},
			});

			expect(normalized).toEqual(
				expect.objectContaining({
					cacheReadTokens: 8885,
					cacheWriteTokens: 10106,
				}),
			);
		});

		it("handles Anthropic's cache_creation metadata", () => {
			const anthropicRaw = (
				(fixtures as Record<string, unknown>).anthropic_stream_usage as Record<
					string,
					unknown
				>
			).raw;
			expect(anthropicRaw).toHaveProperty("cache_creation");
			expect(
				(anthropicRaw as Record<string, unknown>).cache_creation,
			).toHaveProperty("ephemeral_5m_input_tokens");
		});

		it("handles Gemini's promptTokenCount naming", () => {
			const geminiRaw = (
				(fixtures as Record<string, unknown>).gemini_stream_usage as Record<
					string,
					unknown
				>
			).raw;
			expect(geminiRaw).toHaveProperty("promptTokenCount");
			expect(geminiRaw).toHaveProperty("candidatesTokenCount");
		});
	});
});

import type {
	AgentModelEvent,
	AgentToolDefinition,
	GatewayProviderContext,
	GatewayStreamRequest,
} from "@cline/shared";
import { NoSuchToolError } from "ai";
import { describe, expect, it } from "vitest";
import {
	createOpenAICompatibleProvider,
	repairMalformedToolCall,
} from "./ai-sdk";

/**
 * Integration tests for malformed tool-call handling in the AI SDK adapter.
 *
 * Weaker models routinely emit tool calls with type mismatches (a bare string
 * where the schema wants an array) or arguments that are not valid JSON
 * (truncated payloads, single quotes). These tests drive the real adapter
 * with a fake OpenAI-compatible SSE response and assert that such calls are
 * coerced/repaired instead of being rejected before execution
 * (`metadata.inputParseError`), which surfaced as the
 * tool_call_type_validation / tool_call_invalid_json buckets under
 * task.provider_api_error.
 */

const RUN_COMMANDS_TOOL: AgentToolDefinition = {
	name: "run_commands",
	description: "Run shell commands",
	inputSchema: {
		type: "object",
		properties: {
			commands: { type: "array", items: { type: "string" } },
		},
		required: ["commands"],
	},
};

const READ_FILES_TOOL: AgentToolDefinition = {
	name: "read_files",
	description: "Read files",
	inputSchema: {
		type: "object",
		properties: {
			files: {
				type: "array",
				items: {
					type: "object",
					properties: { path: { type: "string" } },
					required: ["path"],
				},
			},
		},
		required: ["files"],
	},
};

function sseToolCall(toolName: string, args: string): string {
	const chunk = (delta: unknown, finish: string | null = null) =>
		`data: ${JSON.stringify({
			id: "cmpl-1",
			object: "chat.completion.chunk",
			created: 1,
			model: "test-model",
			choices: [{ index: 0, delta, finish_reason: finish }],
		})}\n\n`;
	return (
		chunk({
			role: "assistant",
			tool_calls: [
				{
					index: 0,
					id: "call_1",
					type: "function",
					function: { name: toolName, arguments: "" },
				},
			],
		}) +
		chunk({ tool_calls: [{ index: 0, function: { arguments: args } }] }) +
		chunk({}, "tool_calls") +
		"data: [DONE]\n\n"
	);
}

async function streamToolCallEvents(
	sseBody: string,
	tools: AgentToolDefinition[],
): Promise<AgentModelEvent[]> {
	const config = {
		providerId: "openai-compatible",
		apiKey: "test-key",
		baseUrl: "http://fake.local/v1",
		fetch: (async () =>
			new Response(sseBody, {
				status: 200,
				headers: { "content-type": "text/event-stream" },
			})) as unknown as typeof fetch,
	};
	const provider = await createOpenAICompatibleProvider(config);
	const model = {
		id: "test-model",
		providerId: "openai-compatible",
		name: "test-model",
	};
	const context = {
		provider: {
			id: "openai-compatible",
			name: "OpenAI Compatible",
			defaultModelId: "test-model",
			models: [model],
		},
		model,
		config,
	} as unknown as GatewayProviderContext;
	const request = {
		providerId: "openai-compatible",
		modelId: "test-model",
		messages: [
			{
				id: "msg_user",
				role: "user",
				content: [{ type: "text", text: "do the thing" }],
				createdAt: new Date(),
			},
		],
		tools,
	} as unknown as GatewayStreamRequest;

	const events: AgentModelEvent[] = [];
	for await (const event of await provider.stream(request, context)) {
		events.push(event);
	}
	return events;
}

function findParseError(events: AgentModelEvent[]): string | undefined {
	for (const event of events) {
		if (event.type !== "tool-call-delta") continue;
		const metadata = event.metadata as Record<string, unknown> | undefined;
		if (typeof metadata?.inputParseError === "string") {
			return metadata.inputParseError;
		}
	}
	return undefined;
}

function findToolInput(events: AgentModelEvent[]): unknown {
	for (const event of events) {
		if (event.type === "tool-call-delta" && event.input !== undefined) {
			return event.input;
		}
	}
	return undefined;
}

describe("ai-sdk adapter malformed tool calls", () => {
	it("passes schema-mismatched input through to the tool instead of rejecting", async () => {
		// The executor's lenient union schema accepts a bare string for a
		// string[] property; rejecting at the adapter would prevent that.
		const events = await streamToolCallEvents(
			sseToolCall("run_commands", '{"commands": "ls -la"}'),
			[RUN_COMMANDS_TOOL],
		);

		expect(findParseError(events)).toBeUndefined();
		expect(findToolInput(events)).toEqual({ commands: "ls -la" });
	});

	it("passes well-formed input through unchanged", async () => {
		const events = await streamToolCallEvents(
			sseToolCall("run_commands", '{"commands": ["ls", "pwd"]}'),
			[RUN_COMMANDS_TOOL],
		);

		expect(findParseError(events)).toBeUndefined();
		expect(findToolInput(events)).toEqual({ commands: ["ls", "pwd"] });
	});

	it("repairs truncated JSON arguments", async () => {
		const events = await streamToolCallEvents(
			sseToolCall("read_files", '{"files": [{"path": "/tmp/a.txt"}]'),
			[READ_FILES_TOOL],
		);

		expect(findParseError(events)).toBeUndefined();
		expect(findToolInput(events)).toEqual({ files: [{ path: "/tmp/a.txt" }] });
	});

	it("repairs single-quoted JSON arguments", async () => {
		const events = await streamToolCallEvents(
			sseToolCall("run_commands", "{'commands': ['ls']}"),
			[RUN_COMMANDS_TOOL],
		);

		expect(findParseError(events)).toBeUndefined();
		expect(findToolInput(events)).toEqual({ commands: ["ls"] });
	});

	it("still surfaces a parse error for unrepairable argument text", async () => {
		const events = await streamToolCallEvents(
			sseToolCall("run_commands", "run ls for me please"),
			[RUN_COMMANDS_TOOL],
		);

		expect(findParseError(events)).toContain("Invalid input");
	});

	it("keeps the unavailable-tool error for unknown tools", async () => {
		const events = await streamToolCallEvents(
			sseToolCall("editor", '{"path": "/tmp/a.txt", "new_text": "x"}'),
			[RUN_COMMANDS_TOOL, READ_FILES_TOOL],
		);

		expect(findParseError(events)).toContain("unavailable tool 'editor'");
	});
});

describe("repairMalformedToolCall", () => {
	const toolCall = (input: string) => ({
		toolCallId: "call_1",
		toolName: "run_commands",
		input,
	});

	it("repairs truncated JSON", async () => {
		const repaired = await repairMalformedToolCall({
			toolCall: toolCall('{"commands": ["ls"'),
			error: new Error("JSON parsing failed"),
		});
		expect(repaired?.input).toBe('{"commands":["ls"]}');
	});

	it("repairs single-quoted JSON", async () => {
		const repaired = await repairMalformedToolCall({
			toolCall: toolCall("{'commands': ['ls']}"),
			error: new Error("JSON parsing failed"),
		});
		expect(repaired?.input).toBe('{"commands":["ls"]}');
	});

	it("returns null for already-valid JSON (schema failures are not repairable here)", async () => {
		const repaired = await repairMalformedToolCall({
			toolCall: toolCall('{"commands": "ls"}'),
			error: new Error("Type validation failed"),
		});
		expect(repaired).toBeNull();
	});

	it("returns null for unknown-tool errors", async () => {
		const repaired = await repairMalformedToolCall({
			toolCall: toolCall('{"commands": ["ls"]}'),
			error: new NoSuchToolError({ toolName: "run_commands" }),
		});
		expect(repaired).toBeNull();
	});

	it("returns null for unrepairable garbage", async () => {
		const repaired = await repairMalformedToolCall({
			toolCall: toolCall("run ls for me"),
			error: new Error("JSON parsing failed"),
		});
		expect(repaired).toBeNull();
	});
});

