const BUILTIN_PROVIDER_MAP = new Map(
	BUILTIN_PROVIDER_REGISTRATIONS.map((registration) => [
		registration.manifest.id,
		registration,
	]),
);

function toGatewayCapabilities(
	capabilities: readonly string[] | undefined,
): GatewayModelDefinition["capabilities"] {
	if (!capabilities?.length) {
		return undefined;
	}

	const mapped = new Set<
		NonNullable<GatewayModelDefinition["capabilities"]>[number]
	>();
	for (const capability of capabilities) {
		switch (capability) {
			case "tools":
			case "reasoning":
			case "prompt-cache":
			case "images":
			case "audio":
				mapped.add(capability);
				break;
			case "files":
			case "streaming":
			case "temperature":
			case "reasoning-effort":
			case "computer-use":
			case "global-endpoint":
				mapped.add("text");
				break;
			case "structured_output":
				mapped.add("structured-output");
				break;
			default:
				mapped.add("text");
		}
	}

	mapped.add("text");
	return [...mapped];
}

function toGatewayModelDefinition(
	providerId: string,
	model: ModelInfo,
): GatewayModelDefinition {
	return {
		id: model.id,
		name: model.name ?? model.id,
		description: model.description,
		providerId,
		contextWindow: model.contextWindow,
		maxInputTokens: model.maxInputTokens,
		maxOutputTokens: model.maxTokens,
		capabilities: toGatewayCapabilities(model.capabilities),
		reasoningOptions: model.reasoningOptions,
		metadata: {
			family: model.family,
			pricing: model.pricing,
			status: model.status,
			releaseDate: model.releaseDate,
		},
	};
}

function resolveFactory(
	providerId: string,
	transport?: {
		client?: ProviderClient;
		protocol?: ProviderProtocol;
	},
): GatewayProviderFactory {
	if (
		transport?.client === "openai" ||
		transport?.protocol === "openai-responses"
	) {
		return createOpenAIProvider;
	}
	switch (transport?.client) {
		case "anthropic":
			return createAnthropicProvider;
		case "gemini":
			return createGoogleProvider;
		case "vertex":
			return createVertexProvider;
		case "bedrock":
			return createBedrockProvider;
		case "openai-compatible":
			return createOpenAICompatibleProvider;
	}

	const normalized = normalizeProviderId(providerId);
	switch (normalized) {
		case "openai-codex":
		case "openai-native":
			return createOpenAIProvider;
		case "anthropic":
		case "minimax":
			return createAnthropicProvider;
		case "gemini":
			return createGoogleProvider;
		case "vertex":
			return createVertexProvider;
		case "bedrock":
			return createBedrockProvider;
		case "mistral":
			return createMistralProvider;
		case "claude-code":
			return createClaudeCodeProvider;
		case "openai-codex-cli":
			return createOpenAICodexProvider;
		case "opencode":
			return createOpenCodeProvider;
		case "dify":
			return createDifyProvider;
		case "ollama":
			return createOllamaProvider;
		case "sapaicore":
			return createSapAiCoreProvider;
		default:
			return createOpenAICompatibleProvider;
	}
}

async function resolveProviderRegistration(
	config: ProviderConfig,
): Promise<GatewayProviderRegistration | undefined> {
	const providerId = normalizeProviderId(config.providerId);
	const routedProviderId = normalizeProviderId(
		resolveRoutingProviderId(config),
	);
	const builtin = BUILTIN_PROVIDER_MAP.get(providerId);
	if (builtin && providerId === routedProviderId) {
		return undefined;
	}

	const collection =
		(await getProviderCollection(providerId)) ??
		(providerId !== routedProviderId
			? await getProviderCollection(routedProviderId)
			: undefined);
	if (!collection) {
		const routedBuiltin = BUILTIN_PROVIDER_MAP.get(routedProviderId);
		if (!routedBuiltin || providerId === routedProviderId) {
			return undefined;
		}
		return {
			manifest: {
				...routedBuiltin.manifest,
				id: providerId,
				name: routedBuiltin.manifest.name,
				models: routedBuiltin.manifest.models.map((model) => ({
					...model,
					providerId,
				})),
			},
			defaults: routedBuiltin.defaults,
			createProvider: routedBuiltin.createProvider,
			loadProvider: routedBuiltin.loadProvider,
		};
	}

	const routedBuiltin = BUILTIN_PROVIDER_MAP.get(routedProviderId);
	return {
		manifest: {
			id: providerId,
			name: collection.provider.name,
			description: collection.provider.description,
			defaultModelId: collection.provider.defaultModelId,
			models: Object.values(collection.models).map((model) =>
				toGatewayModelDefinition(providerId, model),
			),
			api: collection.provider.baseUrl,
			apiKeyEnv: collection.provider.env,
		},
		defaults: {
			...(routedBuiltin?.defaults ?? {}),
			baseUrl: collection.provider.baseUrl ?? routedBuiltin?.defaults?.baseUrl,
			apiKeyEnv: collection.provider.env ?? routedBuiltin?.defaults?.apiKeyEnv,
		},
		createProvider:
			routedBuiltin?.createProvider ??
			resolveFactory(routedProviderId, {
				client: config.clientType ?? collection.provider.client,
				protocol: collection.provider.protocol,
			}),
		loadProvider: routedBuiltin?.loadProvider,
	};
}

function resolveProviderRegistrationSync(
	config: ProviderConfig,
): GatewayProviderRegistration | undefined {
	const providerId = normalizeProviderId(config.providerId);
	const routedProviderId = normalizeProviderId(
		resolveRoutingProviderId(config),
	);
	const builtin = BUILTIN_PROVIDER_MAP.get(providerId);
	if (builtin && providerId === routedProviderId) {
		return undefined;
	}

	const collection =
		getProviderCollectionSync(providerId) ??
		(providerId !== routedProviderId
			? getProviderCollectionSync(routedProviderId)
			: undefined);
	if (!collection) {
		const routedBuiltin = BUILTIN_PROVIDER_MAP.get(routedProviderId);
		if (!routedBuiltin || providerId === routedProviderId) {
			return undefined;
		}
		return {
			manifest: {
				...routedBuiltin.manifest,
				id: providerId,
				models: routedBuiltin.manifest.models.map((model) => ({
					...model,
					providerId,
				})),
			},
			defaults: routedBuiltin.defaults,
			createProvider: routedBuiltin.createProvider,
			loadProvider: routedBuiltin.loadProvider,
		};
	}

	const routedBuiltin = BUILTIN_PROVIDER_MAP.get(routedProviderId);
	return {
		manifest: {
			id: providerId,
			name: collection.provider.name,
			description: collection.provider.description,
			defaultModelId: collection.provider.defaultModelId,
			models: Object.values(collection.models).map((model) =>
				toGatewayModelDefinition(providerId, model),
			),
			api: collection.provider.baseUrl,
			apiKeyEnv: collection.provider.env,
		},
		defaults: {
			...(routedBuiltin?.defaults ?? {}),
			baseUrl: collection.provider.baseUrl ?? routedBuiltin?.defaults?.baseUrl,
			apiKeyEnv: collection.provider.env ?? routedBuiltin?.defaults?.apiKeyEnv,
		},
		createProvider:
			routedBuiltin?.createProvider ??
			resolveFactory(routedProviderId, {
				client: config.clientType ?? collection.provider.client,
				protocol: collection.provider.protocol,
			}),
		loadProvider: routedBuiltin?.loadProvider,
	};
}

export function toGatewayRequestMessages(
	messages: Message[],
): GatewayStreamRequest["messages"] {
	const toolNames = new Map<string, string>();

	for (const message of messages) {
		if (!Array.isArray(message.content)) {
			continue;
		}
		for (const part of message.content) {
			if (part.type === "tool_use") {
				toolNames.set(part.id, part.name);
				if (part.call_id) {
					toolNames.set(part.call_id, part.name);
				}
			}
		}
	}

	return messages.map((message) => {
		const content =
			typeof message.content === "string"
				? [{ type: "text", text: message.content }]
				: message.content.flatMap((part): Array<Record<string, unknown>> => {
						switch (part.type) {
							case "text":
								return [{ type: "text", text: part.text }];
							case "thinking":
								return [
									{
										type: "reasoning" as const,
										text: part.thinking,
										metadata:
											part.signature || part.call_id
												? {
														signature: part.signature,
														callId: part.call_id,
														details: part.details,
													}
												: undefined,
									},
								];
							case "tool_use":
								return [
									{
										type: "tool-call" as const,
										toolCallId: part.call_id ?? part.id,
										toolName: part.name,
										input: part.input,
										metadata: part.signature
											? { thoughtSignature: part.signature }
											: undefined,
									},
								];
							case "tool_result":
								// Pass the raw tool-result content through unchanged.
								// `formatMessagesForAiSdk` -> `toAiSdkToolResultOutput`
								// downstream walks any structured `output` (including the
								// `[{query, result, success}]` `ToolOperationResult` shape
								// produced by `read_files`) and pulls nested image blocks
								// out as `image-data` content parts. We don't need (and
								// must not) detach images into sibling user messages here:
								// that produces a malformed message stream where image
								// parts are not attached to the originating tool call.
								return [
									{
										type: "tool-result" as const,
										toolCallId: part.tool_use_id,
										toolName: toolNames.get(part.tool_use_id) ?? "tool",
										output: part.content,
										isError: part.is_error ?? false,
									},
								];
							case "image":
								return [
									{
										type: "image" as const,
										image: `data:${part.mediaType};base64,${part.data}`,
										mediaType: part.mediaType,
									},
								];
							case "file":
								return [{ type: "text" as const, text: part.content }];
							case "redacted_thinking":
								return [];
							default:
								return [];
						}
					});

		return {
			id: nanoid(),
			role: message.role,
			content,
			createdAt: Date.now(),
		} as unknown as GatewayStreamRequest["messages"][number];
	});
}

function toGatewayTools(
	tools: ToolDefinition[] | undefined,
): GatewayStreamRequest["tools"] {
	return tools?.map((tool) => ({
		name: tool.name,
		description: tool.description,
		inputSchema: tool.inputSchema,
	}));
}

function buildGatewayRequest(
	config: ProviderConfig,
	systemPrompt: string,
	messages: Message[],
	tools?: ToolDefinition[],
	signal?: AbortSignal,
): GatewayStreamRequest {
	return {
		providerId: normalizeProviderId(config.providerId),
		modelId: config.modelId,
		systemPrompt,
		messages: toGatewayRequestMessages(messages),
		tools: toGatewayTools(tools),
		maxTokens: config.maxOutputTokens,
		reasoning:
			config.thinking !== undefined ||
			config.reasoningEffort ||
			config.thinkingBudgetTokens !== undefined
				? {
						enabled: config.thinking,
						effort: config.reasoningEffort,
						budgetTokens: config.thinkingBudgetTokens,
					}
				: undefined,
		signal,
	};
}

function buildGatewayModels(
	providerId: string,
	config: ProviderConfig,
): Omit<GatewayModelDefinition, "providerId">[] | undefined {
	const definitions = new Map<
		string,
		Omit<GatewayModelDefinition, "providerId">
	>();
	for (const model of Object.values(config.knownModels ?? {})) {
		const { providerId: _providerId, ...definition } = toGatewayModelDefinition(
			providerId,
			model,
		);
		definitions.set(definition.id, definition);
	}

	// Caller-configured limits are authoritative for the selected model —
	// project them onto its gateway definition so the resolved model carries
	// the right limits (e.g. Ollama's num_ctx derives from the resolved
	// model's context window). `maxInputTokens` is where
	// `ProviderSettings.contextWindow` lands via `toProviderConfig`; an
	// explicit `modelInfo` override wins over the generic limit.
	const configuredContextWindow =
		typeof config.maxInputTokens === "number" &&
		Number.isFinite(config.maxInputTokens) &&
		config.maxInputTokens > 0
			? Math.floor(config.maxInputTokens)
			: undefined;
	const modelInfo =
		config.modelInfo && config.modelInfo.id === config.modelId
			? config.modelInfo
			: undefined;
	if (config.modelId && (configuredContextWindow !== undefined || modelInfo)) {
		const base = definitions.get(config.modelId) ?? {
			id: config.modelId,
			name: config.modelId,
		};
		const { providerId: _providerId, ...modelInfoDefinition } = modelInfo
			? toGatewayModelDefinition(providerId, modelInfo)
			: { providerId };
		const definedOverrides = Object.fromEntries(
			Object.entries(modelInfoDefinition).filter(([key, value]) => {
				if (value === undefined) {
					return false;
				}
				// toGatewayModelDefinition always emits a metadata object; drop
				// it when it carries no actual values so it can't clobber the
				// base definition's real metadata.
				if (key === "metadata") {
					return Object.values(value as Record<string, unknown>).some(
						(entry) => entry !== undefined,
					);
				}
				return true;
			}),
		);
		definitions.set(config.modelId, {
			...base,
			...(configuredContextWindow !== undefined
				? {
						contextWindow: configuredContextWindow,
						maxInputTokens: configuredContextWindow,
					}
				: {}),
			...definedOverrides,
		} as Omit<GatewayModelDefinition, "providerId">);
	}

	return definitions.size > 0 ? [...definitions.values()] : undefined;
}

function buildGatewayConfig(config: ProviderConfig) {
	const providerId = normalizeProviderId(config.providerId);
	return {
		providerId,
		apiKey: config.apiKey ?? config.accessToken,
		baseUrl: config.baseUrl,
		headers: config.headers,
		timeoutMs: config.timeoutMs,
		fetch: config.fetch,
		defaultModelId: config.modelId,
		models: buildGatewayModels(providerId, config),
		options: {
			region: config.region ?? config.gcp?.region,
			project: config.gcp?.projectId,
			projectId: config.gcp?.projectId,
			location: config.region ?? config.gcp?.region,
			accessKeyId: config.aws?.accessKey,
			secretAccessKey: config.aws?.secretKey,
			sessionToken: config.aws?.sessionToken,
			authentication: config.aws?.authentication,
			profile: config.aws?.profile,
			endpoint: config.aws?.endpoint,
			customModelBaseId: config.aws?.customModelBaseId,
			apiVersion: config.azure?.apiVersion,
			useIdentity: config.azure?.useIdentity,
			mode: config.oca?.mode,
			usePromptCache: config.aws?.usePromptCache ?? config.oca?.usePromptCache,
			...config.codex,
			...config.claudeCode,
			...config.opencode,
			...config.sap,
		},
	};
}

function toApiStreamChunk(
	id: string,
	event: AgentModelEvent,
): ApiStreamChunk | undefined {
	switch (event.type) {
		case "text-delta":
			return { type: "text", id, text: event.text };
		case "file":
			// The legacy ApiStream contract has no file chunk type; generated
			// files are only representable on the AgentModelEvent path.
			return undefined;
		case "reasoning-delta": {
			const metadata = event.metadata as Record<string, unknown> | undefined;
			return {
				type: "reasoning",
				id,
				reasoning: event.text,
				signature:
					typeof metadata?.thoughtSignature === "string"
						? metadata.thoughtSignature
						: typeof metadata?.signature === "string"
							? metadata.signature
							: undefined,
				details: metadata?.details,
			};
		}
		case "tool-call-delta": {
			const metadata = event.metadata as Record<string, unknown> | undefined;
			const args =
				typeof event.inputText === "string" || event.input === undefined
					? event.inputText
					: (event.input as Record<string, unknown>);
			return {
				type: "tool_calls",
				id,
				signature:
					typeof metadata?.thoughtSignature === "string"
						? metadata.thoughtSignature
						: undefined,
				tool_call: {
					call_id: event.toolCallId,
					function: {
						id: event.toolCallId,
						name: event.toolName,
						arguments: args,
					},
				},
			};
		}
		case "usage":
			return {
				type: "usage",
				id,
				inputTokens: event.usage.inputTokens ?? 0,
				outputTokens: event.usage.outputTokens ?? 0,
				cacheReadTokens: event.usage.cacheReadTokens,
				cacheWriteTokens: event.usage.cacheWriteTokens,
				thoughtsTokenCount: event.usage.reasoningTokenCount,
				totalCost: event.usage.totalCost,
			};
		case "finish":
			return {
				type: "done",
				id,
				success: event.reason !== "error",
				error: event.error,
				incompleteReason:
					event.reason === "max-tokens" ? "max_tokens" : undefined,
			};
	}
}

function resolveModelInfo(config: ProviderConfig): ModelInfo {
	return (
		config.modelInfo ??
		(config.modelId ? config.knownModels?.[config.modelId] : undefined) ?? {
			id: config.modelId,
			name: config.modelId,
			capabilities: ["streaming"],
		}
	);
}

class GatewayApiHandler implements ApiHandler {
	private abortSignal: AbortSignal | undefined;

	constructor(private readonly config: ProviderConfig) {
		this.abortSignal = config.abortSignal;
	}

	getMessages(systemPrompt: string, messages: Message[]): unknown {
		return buildGatewayRequest(
			this.config,
			systemPrompt,
			messages,
			undefined,
			this.abortSignal,
		);
	}

	createMessage(
		systemPrompt: string,
		messages: Message[],
		tools?: ToolDefinition[],
	): ApiStream {
		const gateway = createGateway({
			providerConfigs: [buildGatewayConfig(this.config)],
			fetch: this.config.fetch,
			logger: this.config.logger ?? this.config.extensionContext?.logger,
			telemetry: this.config.extensionContext?.telemetry,
		});
		const registration = resolveProviderRegistrationSync(this.config);
		if (registration) {
			gateway.registerProvider(registration);
		}

		const request = buildGatewayRequest(
			this.config,
			systemPrompt,
			messages,
			tools,
			this.abortSignal,
		);
		const id = `gw_${nanoid(10)}`;
		const stream = (async function* () {
			for await (const event of await gateway.stream(request)) {
				const chunk = toApiStreamChunk(id, event);
				if (chunk) {
					yield chunk;
				}
			}
		})() as ApiStream;
		stream.id = id;
		return stream;
	}

	getModel(): HandlerModelInfo {
		return {
			id: this.config.modelId,
			info: resolveModelInfo(this.config),
		};
	}

	abort(): void {
		// Requests are cancelled via the configured AbortSignal.
	}

	setAbortSignal(signal: AbortSignal | undefined): void {
		this.abortSignal = signal;
	}
}

export function createGatewayApiHandler(config: ProviderConfig): ApiHandler {
	return new GatewayApiHandler(config);
}

export async function createGatewayApiHandlerAsync(
	config: ProviderConfig,
): Promise<ApiHandler> {
	const gateway = createGateway({
		providerConfigs: [buildGatewayConfig(config)],
		fetch: config.fetch,
		logger: config.logger ?? config.extensionContext?.logger,
		telemetry: config.extensionContext?.telemetry,
	});
	const registration = await resolveProviderRegistration(config);
	if (registration) {
		gateway.registerProvider(registration);
	}
	return new (class extends GatewayApiHandler {
		override createMessage(
			systemPrompt: string,
			messages: Message[],
			tools?: ToolDefinition[],
		): ApiStream {
			const request = buildGatewayRequest(
				config,
				systemPrompt,
				messages,
				tools,
				config.abortSignal,
			);
			const id = `gw_${nanoid(10)}`;
			const stream = (async function* () {
				for await (const event of await gateway.stream(request)) {
					const chunk = toApiStreamChunk(id, event);
					if (chunk) {
						yield chunk;
					}
				}
			})() as ApiStream;
			stream.id = id;
			return stream;
		}
	})(config);
}

/**
 * Internal test hook. Not part of the public API; production callers go
 * through `createGatewayApiHandler(Async)`.
 */
export const _testing = {
	buildGatewayConfig,
	buildGatewayModels,
};

/**
 * Provider Configuration Types
 *
 * Unified configuration interface for all providers.
 * This replaces the per-provider config chaos with a single structure.
 */

import type {
	BasicLogger,
	ExtensionContext,
	ReasoningEffort,
} from "@cline/shared";
import type { ModelInfo, ProviderClient } from "../catalog/types";
import {
	BUILT_IN_PROVIDER,
	BUILT_IN_PROVIDER_IDS,
	type BuiltInProviderId,
	isBuiltInProviderId,
	normalizeProviderId,
} from "./ids";

// Re-export for convenience
export {
	BUILT_IN_PROVIDER,
	BUILT_IN_PROVIDER_IDS,
	type BuiltInProviderId,
	isBuiltInProviderId,
	normalizeProviderId,
};

/**
 * All supported provider IDs (built-in + custom)
 *
 * Custom provider IDs can be registered via `registerHandler()` or `registerAsyncHandler()`.
 * Any string is accepted to allow for custom handlers that extend BaseHandler.
 */
export type ProviderId = BuiltInProviderId | (string & {});

/**
 * Provider categories based on underlying SDK/protocol
 */
export type ProviderCategory =
	| "anthropic" // Anthropic SDK
	| "openai" // OpenAI SDK (native features)
	| "openai-compat" // OpenAI-compatible APIs
	| "openai-responses" // OpenAI-Responses APIs
	| "gemini" // Google GenAI SDK
	| "bedrock" // AWS Bedrock SDK
	| "custom"; // Custom implementations

// =============================================================================
// Provider Capabilities
// =============================================================================

/**
 * Capabilities that a provider/model may support
 */
export type ProviderCapability =
	| "reasoning" // Extended thinking/reasoning
	| "prompt-cache" // Prompt caching
	| "streaming" // Streaming responses
	| "tools" // Tool/function calling
	| "vision" // Image inputs
	| "computer-use" // Computer use tools
	| "oauth"; // OAuth authentication flow

// =============================================================================
// Configuration Components
// =============================================================================

/**
 * Authentication configuration
 */
export interface AuthConfig {
	/** API key (most common) */
	apiKey?: string;
	/** OAuth access token */
	accessToken?: string;
	/** Refresh token for OAuth */
	refreshToken?: string;
	/** Account ID (for account-based auth) */
	accountId?: string;
	/** OAuth callback path (e.g., for Qwen Code) */
	oauthPath?: string;
}

/**
 * Endpoint configuration
 */
export interface EndpointConfig {
	/** Base URL for the API */
	baseUrl?: string;
	/** Custom headers to include */
	headers?: Record<string, string>;
	/** Request timeout in milliseconds */
	timeoutMs?: number;
	/**
	 * Custom `fetch` implementation used by the AI gateway providers when
	 * issuing requests. When supplied, it is forwarded to
	 * `GatewayProviderSettings.fetch` (and as a top-level fallback on
	 * `GatewayConfig.fetch`) so hosts can inject custom HTTP behavior such
	 * as proxies, retries, tracing, or test doubles.
	 */
	fetch?: typeof fetch;
}

/**
 * Model configuration
 */
export interface ModelConfig {
	/** Model identifier */
	modelId: string;
	/** Pre-fetched model info (optional - will use defaults if not provided) */
	modelInfo?: ModelInfo;
	/** Known models for this provider with their info */
	knownModels?: Record<string, ModelInfo>;
}

/**
 * Token limits configuration
 */
export interface TokenConfig {
	/** Maximum input tokens (overrides model default) */
	maxInputTokens?: number;
	/** Maximum output tokens (overrides model default) */
	maxOutputTokens?: number;
	/** Sampling temperature (overrides model default) */
	temperature?: number;
}

/**
 * Reasoning/thinking model configuration
 */
export interface ReasoningConfig {
	/** Reasoning effort level */
	reasoningEffort?: ReasoningEffort;
	/** Extended thinking budget in tokens */
	thinkingBudgetTokens?: number;
	/** Enable thinking with provider/model defaults when supported */
	thinking?: boolean;
}

/**
 * Region configuration (shared across cloud providers)
 */
export interface RegionConfig {
	/** Cloud region (AWS, GCP, Azure, or provider-specific like Qwen's china/international) */
	region?: string;
	/** API line for region-specific routing (e.g., "china" | "international" for Qwen) */
	apiLine?: "china" | "international";
	/** Use cross-region inference (Bedrock) */
	useCrossRegionInference?: boolean;
	/** Use global inference (Bedrock) */
	useGlobalInference?: boolean;
}

/**
 * AWS-specific configuration (for Bedrock)
 */
export interface AwsConfig {
	accessKey?: string;
	secretKey?: string;
	sessionToken?: string;
	authentication?: "iam" | "api-key" | "apikey" | "profile";
	profile?: string;
	usePromptCache?: boolean;
	endpoint?: string;
	customModelBaseId?: string;
}

/**
 * Google Cloud configuration (for Vertex AI)
 */
export interface GcpConfig {
	projectId?: string;
	region?: string;
}

/**
 * Azure configuration (for Azure OpenAI)
 */
export interface AzureConfig {
	apiVersion?: string;
	useIdentity?: boolean;
}

/**
 * SAP AI Core configuration
 */
export interface SapConfig {
	clientId?: string;
	clientSecret?: string;
	tokenUrl?: string;
	resourceGroup?: string;
	deploymentId?: string;
	useOrchestrationMode?: boolean;
	api?: "orchestration" | "foundation-models";
	defaultSettings?: Record<string, unknown>;
}

/**
 * OCA (Oracle Cloud AI) configuration
 */
export interface OcaConfig {
	mode?: "internal" | "external";
	usePromptCache?: boolean;
}

/**
 * Codex CLI provider options
 */
export interface CodexConfig {
	defaultSettings?: Record<string, unknown>;
	modelSettings?: Record<string, unknown>;
}

/**
 * Claude Code provider options
 */
export interface ClaudeCodeConfig {
	[key: string]: unknown;
}

/**
 * OpenCode provider options
 */
export interface OpenCodeConfig {
	hostname?: string;
	port?: number;
	autoStartServer?: boolean;
	serverTimeout?: number;
	defaultSettings?: Record<string, unknown>;
	modelSettings?: Record<string, unknown>;
}

/**
 * Cloud provider configurations (grouped)
 */
export interface CloudConfig {
	/** AWS/Bedrock options */
	aws?: AwsConfig;
	/** Google Cloud/Vertex options */
	gcp?: GcpConfig;
	/** Azure options */
	azure?: AzureConfig;
	/** SAP AI Core options */
	sap?: SapConfig;
	/** OCA options */
	oca?: OcaConfig;
}

/**
 * Provider-specific options that don't fit other categories
 */
export interface ProviderOptions {
	/** OpenRouter provider sorting preference */
	openRouterProviderSorting?: string;
	/** Runtime model catalog refresh configuration */
	modelCatalog?: ModelCatalogConfig;
}

/**
 * Runtime model catalog refresh options
 */
export interface ModelCatalogConfig {
	/** Fetch latest catalog at handler initialization */
	loadLatestOnInit?: boolean;
	/** Fetch provider-private models when auth is available */
	loadPrivateOnAuth?: boolean;
	/** Catalog endpoint URL */
	url?: string;
	/** Cache TTL for live catalog in milliseconds */
	cacheTtlMs?: number;
	/** Throw when live catalog refresh fails */
	failOnError?: boolean;
}

// =============================================================================
// Main Configuration Interface
// =============================================================================

/**
 * Unified provider configuration interface
 *
 * This is the single configuration interface that clients provide.
 * All provider-specific options are grouped into logical sub-interfaces.
 */
export interface ProviderConfig
	extends AuthConfig,
		EndpointConfig,
		ModelConfig,
		TokenConfig,
		ReasoningConfig,
		RegionConfig,
		CloudConfig,
		ProviderOptions {
	/** Client type - determines which handler to use - OpenAI-Compatible deafult */
	clientType?: ProviderClient;

	/** Provider ID */
	providerId: ProviderId;

	/**
	 * Optional built-in provider family to use for handler routing.
	 *
	 * This lets clients expose a custom provider ID and model catalog while
	 * reusing the runtime behavior of a built-in provider implementation.
	 */
	routingProviderId?: ProviderId;

	/** Capabilities this provider/model supports */
	capabilities?: ProviderCapability[];

	/** Task/session ID for telemetry */
	taskId?: string;

	/** AbortSignal for cancelling requests */
	abortSignal?: AbortSignal;

	/** Optional runtime logger for provider-level diagnostics */
	logger?: BasicLogger;

	/**
	 * Ambient runtime context: user identity, client surface, workspace info,
	 * logger, and telemetry service. Prefer reading logger and telemetry from
	 * here when available; the top-level logger field is kept for compatibility.
	 */
	extensionContext?: ExtensionContext;

	/** Codex CLI-specific options */
	codex?: CodexConfig;

	/** Claude Code-specific options */
	claudeCode?: ClaudeCodeConfig;

	/** OpenCode-specific options */
	opencode?: OpenCodeConfig;
}

/**
 * Simplified configuration for common use cases
 */
export interface SimpleProviderConfig {
	providerId: ProviderId;
	clientType: ProviderClient;
	apiKey: string;
	modelId: string;
	baseUrl?: string;
}

/**
 * Create a full ProviderConfig from a simple config
 */
export function createConfig(simple: SimpleProviderConfig): ProviderConfig {
	return {
		providerId: simple.providerId,
		clientType: simple.clientType,
		apiKey: simple.apiKey,
		modelId: simple.modelId,
		baseUrl: simple.baseUrl,
	};
}

// =============================================================================
// Helper Functions
// =============================================================================

/**
 * Check if a provider config has a specific capability
 */
export function hasCapability(
	config: ProviderConfig,
	capability: ProviderCapability,
): boolean {
	return config.capabilities?.includes(capability) ?? false;
}

/**
 * Check if provider supports reasoning/thinking
 */
export function supportsReasoning(config: ProviderConfig): boolean {
	return hasCapability(config, "reasoning");
}

/**
 * Check if provider supports prompt caching
 */
export function supportsPromptCache(config: ProviderConfig): boolean {
	return hasCapability(config, "prompt-cache");
}

/**
 * Resolve the provider ID used for handler selection and built-in behavior.
 */
export function resolveRoutingProviderId(
	config: Pick<ProviderConfig, "providerId" | "routingProviderId">,
): string {
	return normalizeProviderId(config.routingProviderId ?? config.providerId);
}

