export type ProviderDefaultsConfig = Pick<
	ProviderConfig,
	"baseUrl" | "modelId" | "knownModels" | "headers" | "capabilities"
>;

import {
	APICallError,
	NoOutputGeneratedError,
	RetryError,
	TypeValidationError,
} from "ai";
import { describe, expect, it } from "vitest";
import { classifyProviderError } from "./error-classification";

describe("classifyProviderError", () => {
	describe("context_window_exceeded", () => {
		it("classifies the gateway-forwarded Alibaba Qwen rejection (captured shape)", () => {
			// Same payload format.test.ts verifies extractErrorMessage against.
			expect(
				classifyProviderError({
					code: "error",
					message: "Stream error occurred",
					name: "AI_TypeValidationError",
					cause: {
						name: "ZodError",
						message:
							'[\n  {\n    "code": "invalid_union",\n    "path": [],\n    "message": "Invalid input"\n  }\n]',
					},
					value: {
						error_type: "validation_error",
						error_message: JSON.stringify({
							error: {
								message:
									"This model's maximum context length is 40960 tokens. However, you requested 100 output tokens and your prompt contains at least 40861 input tokens.",
								code: 400,
							},
						}),
					},
				}),
			).toBe("context_window_exceeded");
		});

		it("classifies an AI SDK APICallError-shaped 400 with context detail in responseBody", () => {
			const error = Object.assign(new Error("Bad Request"), {
				name: "AI_APICallError",
				statusCode: 400,
				responseBody: JSON.stringify({
					error: {
						message:
							"This model's maximum context length is 128000 tokens. However, your messages resulted in 130000 tokens.",
						type: "invalid_request_error",
						code: "context_length_exceeded",
					},
				}),
			});
			expect(classifyProviderError(error)).toBe("context_window_exceeded");
		});

		it("classifies by explicit context_length_exceeded code alone", () => {
			expect(
				classifyProviderError({
					error: { code: "context_length_exceeded" },
				}),
			).toBe("context_window_exceeded");
		});

		it("classifies Anthropic prompt-too-long rejections", () => {
			expect(
				classifyProviderError({
					status: 400,
					error: {
						type: "invalid_request_error",
						message: "prompt is too long: 213462 tokens > 200000 maximum",
					},
				}),
			).toBe("context_window_exceeded");
		});

		it("classifies Bedrock input-too-long validation errors", () => {
			const error = Object.assign(new Error("Bad Request"), {
				name: "AI_APICallError",
				statusCode: 400,
				responseBody: JSON.stringify({
					message: "Input is too long for requested model.",
				}),
			});
			expect(classifyProviderError(error)).toBe("context_window_exceeded");
		});

		it("classifies Cerebras reduce-the-length rejections", () => {
			expect(
				classifyProviderError({
					statusCode: 400,
					message: "Please reduce the length of the messages or completion.",
				}),
			).toBe("context_window_exceeded");
		});

		it("classifies OpenRouter errors JSON-encoded into the message string", () => {
			expect(
				classifyProviderError(
					new Error(
						'Provider returned error: {"error":{"message":"This endpoint\'s maximum context length is 65536 tokens.","code":400}}',
					),
				),
			).toBe("context_window_exceeded");
		});

		it("classifies an already-flattened message string", () => {
			expect(
				classifyProviderError(
					"input length and max_tokens exceed context limit: 199999 + 8192 > 200000",
				),
			).toBe("context_window_exceeded");
		});
	});

	describe("unknown", () => {
		it("vetoes token-per-minute rate limits despite token wording", () => {
			expect(
				classifyProviderError({
					status: 429,
					error: {
						type: "rate_limit_error",
						message:
							"Number of request tokens has exceeded your per-minute rate limit.",
					},
				}),
			).toBe("unknown");
		});

		it("vetoes rate-limit wording even without a status", () => {
			expect(
				classifyProviderError(
					new Error("Rate limit reached for gpt-4o on tokens per min (TPM)"),
				),
			).toBe("unknown");
		});

		it("vetoes context wording on a non-invalid-request status", () => {
			expect(
				classifyProviderError({
					statusCode: 500,
					message: "internal error computing context length",
				}),
			).toBe("unknown");
		});

		it("leaves auth errors unclassified", () => {
			expect(
				classifyProviderError({
					statusCode: 401,
					message: "invalid x-api-key",
				}),
			).toBe("unknown");
		});

		it("leaves generic stream failures unclassified", () => {
			expect(
				classifyProviderError(new Error("fetch failed: other side closed")),
			).toBe("unknown");
		});

		it("handles null, primitives, and empty objects", () => {
			expect(classifyProviderError(null)).toBe("unknown");
			expect(classifyProviderError(undefined)).toBe("unknown");
			expect(classifyProviderError(42)).toBe("unknown");
			expect(classifyProviderError({})).toBe("unknown");
		});

		it("survives self-referential error objects", () => {
			const cyclic: Record<string, unknown> = { message: "boom" };
			cyclic.cause = cyclic;
			expect(classifyProviderError(cyclic)).toBe("unknown");
		});
	});

	describe("typed AI SDK error instances", () => {
		const overflowApiCallError = () =>
			new APICallError({
				message: "Bad Request",
				url: "https://api.anthropic.com/v1/messages",
				requestBodyValues: {},
				statusCode: 400,
				responseBody: JSON.stringify({
					type: "error",
					error: {
						type: "invalid_request_error",
						message: "prompt is too long: 213462 tokens > 200000 maximum",
					},
				}),
			});

		it("classifies an APICallError 400 with a prompt-too-long body", () => {
			expect(classifyProviderError(overflowApiCallError())).toBe(
				"context_window_exceeded",
			);
		});

		it("treats the typed statusCode as authoritative: 429 vetoes token wording", () => {
			const error = new APICallError({
				message: "Too Many Requests",
				url: "https://api.anthropic.com/v1/messages",
				requestBodyValues: {},
				statusCode: 429,
				responseBody: JSON.stringify({
					error: {
						message: "Request tokens exceed your available quota.",
					},
				}),
			});
			expect(classifyProviderError(error)).toBe("unknown");
		});

		it("treats the typed statusCode as authoritative: 500 vetoes context wording", () => {
			const error = new APICallError({
				message: "Internal Server Error",
				url: "https://api.openai.com/v1/chat/completions",
				requestBodyValues: {},
				statusCode: 500,
				responseBody: JSON.stringify({
					error: {
						message: "internal error computing maximum context length",
					},
				}),
			});
			expect(classifyProviderError(error)).toBe("unknown");
		});

		it("treats the typed statusCode as authoritative: an explicit overflow code cannot override it", () => {
			const withStatus = (statusCode: number) =>
				new APICallError({
					message: "Request failed",
					url: "https://api.openai.com/v1/chat/completions",
					requestBodyValues: {},
					statusCode,
					responseBody: JSON.stringify({
						error: {
							message: "This model's maximum context length is 128000 tokens.",
							code: "context_length_exceeded",
						},
					}),
				});
			expect(classifyProviderError(withStatus(429))).toBe("unknown");
			expect(classifyProviderError(withStatus(500))).toBe("unknown");
			// The gate must not swallow genuine overflow rejections.
			expect(classifyProviderError(withStatus(400))).toBe(
				"context_window_exceeded",
			);
		});

		it("unwraps a RetryError to its last attempt's error", () => {
			const error = new RetryError({
				message: "Failed after 3 attempts.",
				reason: "maxRetriesExceeded",
				errors: [new Error("fetch failed"), overflowApiCallError()],
			});
			expect(classifyProviderError(error)).toBe("context_window_exceeded");
		});

		it("classifies an untyped final RetryError attempt without earlier attempts vetoing it", () => {
			// Attempt 1 was a retryable 429; the final attempt is a plain
			// (untyped) overflow rejection. The earlier rate limit must not
			// veto the final attempt's verdict.
			const error = new RetryError({
				message: "Failed after 2 attempts.",
				reason: "errorNotRetryable",
				errors: [
					new APICallError({
						message: "Too Many Requests",
						url: "https://api.anthropic.com/v1/messages",
						requestBodyValues: {},
						statusCode: 429,
						responseBody: JSON.stringify({
							error: {
								type: "rate_limit_error",
								message: "Rate limit reached.",
							},
						}),
					}),
					{
						status: 400,
						error: {
							type: "invalid_request_error",
							message: "prompt is too long: 213462 tokens > 200000 maximum",
						},
					},
				],
			});
			expect(classifyProviderError(error)).toBe("context_window_exceeded");
		});

		it("does not let earlier RetryError attempts fake an overflow for an untyped final attempt", () => {
			const error = new RetryError({
				message: "Failed after 2 attempts.",
				reason: "errorNotRetryable",
				errors: [
					{
						status: 400,
						error: {
							message: "prompt is too long: 213462 tokens > 200000 maximum",
						},
					},
					new Error("fetch failed: other side closed"),
				],
			});
			expect(classifyProviderError(error)).toBe("unknown");
		});

		it("classifies a TypeValidationError by the gateway payload in value", () => {
			// A real instance of the ENG-2394 failure: the Vercel gateway streams
			// the upstream rejection as the value that failed schema validation.
			const error = new TypeValidationError({
				value: {
					error_type: "validation_error",
					error_message: JSON.stringify({
						error: {
							message:
								"This model's maximum context length is 40960 tokens. However, you requested 100 output tokens and your prompt contains at least 40861 input tokens.",
							code: 400,
						},
					}),
				},
				cause: Object.assign(
					new Error(
						'[\n  {\n    "code": "invalid_union",\n    "path": [],\n    "message": "Invalid input"\n  }\n]',
					),
					{ name: "ZodError" },
				),
			});
			expect(classifyProviderError(error)).toBe("context_window_exceeded");
		});

		it("recurses through a generic AISDKError wrapper's cause", () => {
			const error = new NoOutputGeneratedError({
				message: "No output generated.",
				cause: overflowApiCallError(),
			});
			expect(classifyProviderError(error)).toBe("context_window_exceeded");
		});
	});
});

import { type ProviderErrorClass, safeJsonParse } from "@cline/shared";
import { AISDKError, APICallError, RetryError, TypeValidationError } from "ai";

/**
 * Provider codes that unambiguously identify a context-window overflow
 * (OpenAI-family `error.code`).
 */
const CONTEXT_WINDOW_CODES = new Set(["context_length_exceeded"]);

/**
 * Message shapes providers use for context-window overflow. Sourced from the
 * legacy extension's per-provider detectors (OpenAI, OpenRouter, Anthropic,
 * Cerebras, Bedrock, Vercel gateway / Alibaba Qwen) — the wire messages are
 * provider-authored and identical on the SDK arch; only the surrounding
 * error-object structure changed (handled by the signal walk below).
 */
const CONTEXT_WINDOW_PATTERNS = [
	/\bcontext\s*(?:length|window|limit)\b/i,
	/\bmaximum\s*context\b/i,
	/\b(?:input\s*)?tokens?\s+exceeds?\b/i,
	/\btoo\s*many\s*tokens?\b/i,
	/\binput\s+is\s+too\s+long\b/i,
	/\bprompt\s+is\s+too\s+long\b/i,
	/reduce\s+the\s+length\s+of\s+the\s+messages\s+or\s+completion/i,
	/requested\s+input\s+length\s+.*exceeds\s+.*maximum/i,
];

/**
 * Signals that the request failed for throughput/quota reasons rather than
 * size. Token-per-minute limit messages also talk about tokens being
 * "exceeded", so these veto a context-window match.
 */
const RATE_LIMIT_PATTERNS = [/rate[\s_-]?limit/i, /per[\s_-]?minute\b/i];

/** Overflow rejections arrive as invalid-request-family statuses. */
const CONTEXT_WINDOW_STATUSES = new Set([400, 413, 422]);
const RATE_LIMIT_STATUS = 429;

const MAX_WALK_DEPTH = 8;

/**
 * Object keys whose values carry further error detail — human-readable text
 * (message/detail/error_message; strings are recorded by the string branch)
 * or nested error structures the providers and gateways wrap around them.
 */
const DETAIL_KEYS = [
	"message",
	"detail",
	"error_message",
	"error",
	"errors",
	"cause",
	"responseBody",
	"data",
	"value",
	"param",
] as const;

/** Object keys that may carry an HTTP status. */
const STATUS_KEYS = ["status", "statusCode", "code"] as const;

interface ErrorSignals {
	messages: string[];
	statuses: Set<number>;
	codes: Set<string>;
}

function recordStatus(signals: ErrorSignals, value: unknown): void {
	const numeric =
		typeof value === "number"
			? value
			: typeof value === "string" && /^\d{3}$/.test(value.trim())
				? Number(value.trim())
				: undefined;
	if (numeric !== undefined && numeric >= 100 && numeric <= 599) {
		signals.statuses.add(numeric);
	}
}

function collectSignals(
	value: unknown,
	signals: ErrorSignals,
	visited: Set<unknown>,
	depth: number,
): void {
	if (value == null || depth > MAX_WALK_DEPTH) {
		return;
	}
	if (typeof value === "string") {
		const text = value.trim();
		if (!text) {
			return;
		}
		signals.messages.push(text);
		// Providers and gateways JSON-encode upstream rejections into message
		// strings (OpenRouter mid-stream errors, Vercel `value.error_message`);
		// parse so embedded status/code fields become structured signals.
		const parsed = safeJsonParse<unknown>(text);
		if (parsed !== undefined && typeof parsed === "object") {
			collectSignals(parsed, signals, visited, depth + 1);
		} else {
			// Not full JSON — still mine embedded `"code": 400` / `"status": 400`.
			const embedded = text.match(/"(?:code|status)"\s*:\s*"?(\d{3})"?/);
			if (embedded) {
				recordStatus(signals, embedded[1]);
			}
		}
		return;
	}
	if (typeof value !== "object") {
		return;
	}
	if (visited.has(value)) {
		return;
	}
	visited.add(value);

	if (Array.isArray(value)) {
		for (const item of value) {
			collectSignals(item, signals, visited, depth + 1);
		}
		return;
	}

	const record = value as Record<string, unknown>;
	for (const key of STATUS_KEYS) {
		recordStatus(signals, record[key]);
	}
	for (const key of ["code", "type", "name"]) {
		const candidate = record[key];
		if (typeof candidate === "string" && candidate.trim()) {
			signals.codes.add(candidate.trim());
		}
	}
	for (const key of DETAIL_KEYS) {
		const nested = record[key];
		if (
			nested !== undefined &&
			nested !== value &&
			typeof nested !== "number"
		) {
			collectSignals(nested, signals, visited, depth + 1);
		}
	}
}

/**
 * Apply the detection rules to collected signals. Shared between the typed
 * AI SDK pre-pass and the structural walk so both paths classify identically:
 * a context-window verdict requires an overflow message pattern (or explicit
 * provider code), no rate-limit signal, and — when any HTTP status is
 * visible — an invalid-request-family status.
 */
function verdictFromSignals(signals: ErrorSignals): ProviderErrorClass {
	if ([...signals.codes].some((code) => CONTEXT_WINDOW_CODES.has(code))) {
		return "context_window_exceeded";
	}

	if (signals.statuses.has(RATE_LIMIT_STATUS)) {
		return "unknown";
	}
	if (
		signals.messages.some((message) =>
			RATE_LIMIT_PATTERNS.some((pattern) => pattern.test(message)),
		)
	) {
		return "unknown";
	}
	if (
		signals.statuses.size > 0 &&
		![...signals.statuses].some((status) => CONTEXT_WINDOW_STATUSES.has(status))
	) {
		return "unknown";
	}
	if (
		signals.messages.some((message) =>
			CONTEXT_WINDOW_PATTERNS.some((pattern) => pattern.test(message)),
		)
	) {
		return "context_window_exceeded";
	}
	return "unknown";
}

function collectSignalsFrom(values: readonly unknown[]): ErrorSignals {
	const signals: ErrorSignals = {
		messages: [],
		statuses: new Set(),
		codes: new Set(),
	};
	const visited = new Set<unknown>();
	for (const value of values) {
		collectSignals(value, signals, visited, 0);
	}
	return signals;
}

/**
 * Classify errors that are real AI SDK error instances, using their typed
 * fields instead of guessing at shape. Returns `undefined` when the error is
 * not a recognized instance (or a typed wrapper leads nowhere), so the caller
 * falls back to the structural walk.
 *
 * `isInstance()` is the AI SDK's symbol-based guard, so it holds across
 * duplicated package copies — but it can never match gateway-forwarded plain
 * JSON payloads that merely *name* an AI SDK error (ENG-2394); those stay the
 * structural walk's job.
 */
function classifyTypedError(
	error: unknown,
	depth: number,
): ProviderErrorClass | undefined {
	if (depth > MAX_WALK_DEPTH) {
		return undefined;
	}
	// Specific classes before the generic guard — every AI SDK error
	// subclasses AISDKError, so the generic check would swallow them.
	if (RetryError.isInstance(error)) {
		// Only the final attempt decides the verdict: earlier attempts were
		// retried away (typically rate limits) and must neither veto nor fake
		// its classification — so an untyped final error is walked alone
		// rather than falling back to the whole wrapper's `errors` array.
		const last = error.lastError ?? error.errors[error.errors.length - 1];
		if (last == null) {
			return undefined;
		}
		return (
			classifyTypedError(last, depth + 1) ??
			verdictFromSignals(collectSignalsFrom([last]))
		);
	}
	if (APICallError.isInstance(error)) {
		// The typed statusCode is the sole authoritative status and gates the
		// whole verdict: nothing in the payload — not even an explicit
		// overflow code echoed inside a rate-limit or server-failure body —
		// out-votes the HTTP layer. Absent a statusCode, the payload decides.
		const status =
			typeof error.statusCode === "number" ? error.statusCode : undefined;
		if (status !== undefined && !CONTEXT_WINDOW_STATUSES.has(status)) {
			return "unknown";
		}
		const signals = collectSignalsFrom([
			error.message,
			error.responseBody,
			error.data,
		]);
		signals.statuses = new Set(status !== undefined ? [status] : []);
		return verdictFromSignals(signals);
	}
	if (TypeValidationError.isInstance(error)) {
		// `value` holds the payload that failed validation — for gateway
		// streams, the upstream provider rejection.
		const verdict = verdictFromSignals(collectSignalsFrom([error.value]));
		return verdict === "context_window_exceeded" ? verdict : undefined;
	}
	if (AISDKError.isInstance(error)) {
		const verdict = classifyTypedError(error.cause, depth + 1);
		return verdict === "context_window_exceeded" ? verdict : undefined;
	}
	return undefined;
}

/**
 * Classify a raw provider error (or an already-flattened error message) into
 * a {@link ProviderErrorClass}. Call this where the structured error object
 * is still available — `extractErrorMessage` discards the structure this
 * classification relies on.
 *
 * Typed AI SDK error instances are classified first via their typed fields;
 * everything else — including plain JSON payloads that only *look* like AI
 * SDK errors — goes through the conservative structural walk.
 */
export function classifyProviderError(error: unknown): ProviderErrorClass {
	try {
		const typed = classifyTypedError(error, 0);
		if (typed !== undefined) {
			return typed;
		}
	} catch {
		// Fall through to the structural walk.
	}

	const signals: ErrorSignals = {
		messages: [],
		statuses: new Set(),
		codes: new Set(),
	};
	try {
		collectSignals(error, signals, new Set(), 0);
	} catch {
		return "unknown";
	}
	return verdictFromSignals(signals);
}

import { describe, expect, it } from "vitest";
import { isClinePassLimitMessage } from "../index.browser";
import {
	extractClineFreeModelLimitResetTime,
	extractClinePassLimitMessage,
	isClineFreeModelLimitMessage,
} from "./errors";

describe("isClinePassLimitMessage", () => {
	it("matches the ClinePass weekly limit message", () => {
		const message =
			"You have reached your weekly Clinepass limit. The limit resets in 7d, please try again later.";
		expect(isClinePassLimitMessage(message)).toBe(true);
	});

	it("matches the 5-hour ClinePass limit message", () => {
		const message =
			"You have reached your 5-hour Clinepass limit. The limit resets in 5h, please try again later.";
		expect(isClinePassLimitMessage(message)).toBe(true);
	});

	it("handles tab-heavy non-matches without regex backtracking", () => {
		expect(
			isClinePassLimitMessage(`You have reached your\t${"\t".repeat(10_000)}`),
		).toBe(false);
		expect(
			isClinePassLimitMessage(`You have reached your\t-${"\t".repeat(10_000)}`),
		).toBe(false);
		expect(
			isClinePassLimitMessage(
				`You have reached your\t-\tClinepass limit.The limit resets in\t${"\t".repeat(10_000)}`,
			),
		).toBe(false);
	});
});

describe("extractClinePassLimitMessage", () => {
	it("extracts the ClinePass weekly limit message", () => {
		const message =
			"You have reached your weekly Clinepass limit. The limit resets in 7d, please try again later.";

		const extracted = extractClinePassLimitMessage(`Error: ${message}`);
		expect(extracted).toBe(message);
	});

	it("extracts the 5-hour ClinePass limit message", () => {
		const message =
			"You have reached your 5-hour Clinepass limit. The limit resets in 5h, please try again later.";

		const extracted = extractClinePassLimitMessage(`Error: ${message}`);
		expect(extracted).toBe(message);
	});
});

describe("Cline free model limit messages", () => {
	const message =
		"Daily free limit reached on model deepseek/deepseek-v4-flash. Try again in 23h 59m";

	it("detects the message in an HTTP error", () => {
		const error = `Error: Error 429: ${message}`;
		expect(isClineFreeModelLimitMessage(error)).toBe(true);
		expect(extractClineFreeModelLimitResetTime(error)).toBe("23h 59m");
	});

	it("does not match unrelated daily limits", () => {
		expect(
			isClineFreeModelLimitMessage(
				"Your daily spend limit has been reached. Try again in 23h 59m",
			),
		).toBe(false);
	});
});

import { getClineEnvironmentConfig } from "@cline/shared";

export const CLINE_NOT_SUBSCRIBED_RESPONSE_MESSAGE =
	"the user is not subscribed to required model plan";
const CLINE_NOT_SUBSCRIBED_FORMATTED_MESSAGE_PREFIX =
	"no access to clinepass subscription models yet. subscribe to clinepass";
export const CLINE_ORG_INDIVIDUAL_INFERENCE_SUBSCRIPTION_RESPONSE_MESSAGE =
	"organization accounts cannot use individual model inference subscriptions";

const CLINE_PASS_LIMIT_PREFIX = "you have reached your";
const CLINE_PASS_LIMIT_MARKER = "clinepass limit";
const CLINE_PASS_LIMIT_SUFFIX = "please try again later.";
const CLINE_FREE_MODEL_LIMIT_MARKER = "free limit reached on model";
const CLINE_FREE_MODEL_LIMIT_RETRY_MARKER = "try again in ";
const CLINE_MODEL_NOT_FOUND_MARKER = "model not found";

function findClinePassLimitMessageBounds(
	text: string,
): { start: number; end: number } | undefined {
	const normalized = text.toLowerCase();
	const start = normalized.indexOf(CLINE_PASS_LIMIT_PREFIX);
	if (start === -1) {
		return undefined;
	}

	const suffixStart = normalized.indexOf(CLINE_PASS_LIMIT_SUFFIX, start);
	if (suffixStart === -1) {
		return undefined;
	}

	const end = suffixStart + CLINE_PASS_LIMIT_SUFFIX.length;
	if (!normalized.slice(start, end).includes(CLINE_PASS_LIMIT_MARKER)) {
		return undefined;
	}

	return { start, end };
}

export function getClinePassSubscriptionUrl(): string {
	return `${new URL(
		"/dashboard/subscription?personal=true",
		getClineEnvironmentConfig().appBaseUrl,
