			options,
		}),
	);

	const call = streamTextSpy.mock.calls.at(-1)?.[0] as
		| {
				reasoning?: unknown;
				providerOptions?: Record<string, { reasoning?: unknown }>;
		  }
		| undefined;
	return call?.reasoning ?? call?.providerOptions?.[providerId]?.reasoning;
}

