function readCaptureRecords(dir: string): Array<Record<string, unknown>> {
	return readdirSync(dir)
		.filter((file) => file.endsWith(".provider-request.json"))
		.sort()
		.map(
			(file) =>
				JSON.parse(readFileSync(join(dir, file), "utf8")) as Record<
					string,
					unknown
				>,
		);
}

