// LanguageModelV4 middleware that recovers image bytes from
// `role:"tool"` messages whose content arrays the downstream chat-completions
// converter would otherwise destroy.
//
// Background: AI SDK's `LanguageModelV4ToolResultOutput` of type `'content'`
// may contain `image-data`, `image-url`, `file-data`, `file-url`, or
// `image-file-id` parts. The OpenAI Chat Completions wire format does NOT
// support multimodal tool messages — `role:"tool"` content must be a single
// string. The `@ai-sdk/openai-compatible` chat-messages converter therefore
// just `JSON.stringify`s the parts array. The image bytes survive as escaped
// base64 inside a string, which the model treats as ~50KB of opaque text and
// hallucinates the image's actual contents.
//
// This middleware operates on the typed `LanguageModelV4Prompt` BEFORE the
// downstream converter runs. For every `role:"tool"` message containing
// image/file parts inside a tool-result `output.type === 'content'` value,
// it:
//
//   1. Replaces the media parts inside the tool-result with placeholder
//      text parts: `(see following user message for image)`. The
//      tool-result then carries only text — safe for any wire format.
//   2. Inserts a synthetic `role:"user"` message right after the tool
//      message, carrying the media parts as `LanguageModelV4FilePart`s.
//
// Because the synthetic user message is typed (not raw JSON), every
// downstream converter — Chat Completions, Mistral, Anthropic, Bedrock,
// etc. — translates it to its own native multimodal user-content shape
// without further help.
//
// This pattern is documented in the OpenAI Chat Completions spec
// (consecutive `user` messages are concatenated by the model) and is a
// direct port of the proven wire pattern used by classic Cline's
// `convertToOpenAiMessages` (see `src/core/api/transform/openai-format.ts`
// in origin/main).
//
// Replaces fetch interceptor `vendors/openai-compatible-image-rewrite.ts`,
// which did the same rewrite at the wire layer (post-converter). The
// middleware approach is preferred because:
//   * No JSON parse / restringify round-trip on every chat-completions
//     request.
//   * Works equally for any converter — `@ai-sdk/mistral` (which has its
//     own chat-messages converter) was previously uncovered.
//   * Decoupled from the AI SDK's wire-output shape: if the SDK ever
//     changes how it serialises content arrays, this layer doesn't care.

import type {
	LanguageModelV4CallOptions,
	LanguageModelV4FilePart,
	LanguageModelV4Message,
	LanguageModelV4Middleware,
	LanguageModelV4TextPart,
	LanguageModelV4ToolResultOutput,
	LanguageModelV4ToolResultPart,
} from "@ai-sdk/provider";
import {
	createMediaBudgetState,
	DEFAULT_MAX_IMAGE_DECODED_BYTES,
	DEFAULT_MAX_IMAGE_ENCODED_BYTES,
	IMAGE_OMITTED_PLACEHOLDER,
	isCanonicalBase64,
	type MediaBudgetState,
	reserveImageMediaBytes,
	validateAndReserveImageMedia,
} from "@cline/shared";

const IMAGE_PLACEHOLDER = "(see following user message for image)";

type ContentOutput = Extract<
	LanguageModelV4ToolResultOutput,
	{ type: "content" }
>;
type ContentPart = ContentOutput["value"][number];

function isMediaContentPart(
	part: ContentPart,
): part is Extract<ContentPart, { type: "file" }> {
	return part.type === "file";
}

/**
 * Convert a media content-part from a `ToolResultOutput` of type `'content'`
 * into the equivalent `LanguageModelV4FilePart` for use in a user message.
 * Returns `null` for `image-file-id` parts because `LanguageModelV4FilePart`
 * has no provider-file-id slot — those parts are left in place inside the
 * tool-result and pass through to the converter as-is. (Image-file-id is
 * an OpenAI-specific reference; if a caller is using it they are already
 * on a multimodal-aware path and don't need this rewrite.)
 */
function mediaPartToFilePart(
	part: Extract<ContentPart, { type: "file" }>,
): LanguageModelV4FilePart | null {
	if (part.data.type === "reference") {
		return null;
	}
	return {
		type: "file",
		data: part.data,
		mediaType: part.mediaType,
		...(part.filename ? { filename: part.filename } : {}),
		...(part.providerOptions ? { providerOptions: part.providerOptions } : {}),
	};
}

interface SplitResult {
	stripped: ContentOutput;
	media: LanguageModelV4FilePart[];
}

function imageOmittedTextPart(): LanguageModelV4TextPart {
	return {
		type: "text",
		text: IMAGE_OMITTED_PLACEHOLDER,
	};
}

function reserveUnknownUrlMediaBudget(
	url: string,
	mediaState: MediaBudgetState,
): boolean {
	let parsed: URL;
	try {
		parsed = new URL(url);
	} catch {
		return false;
	}

	if (parsed.protocol === "data:") {
		const commaIndex = url.indexOf(",");
		if (commaIndex === -1) {
			return false;
		}
		const metadata = url.slice("data:".length, commaIndex).toLowerCase();
		if (!metadata.endsWith(";base64")) {
			return false;
		}
		const base64 = url.slice(commaIndex + 1);
		if (!isCanonicalBase64(base64)) {
			return false;
		}
		return (
			reserveImageMediaBytes(
				base64.length,
				0,
				{
					maxImageEncodedBytes: DEFAULT_MAX_IMAGE_ENCODED_BYTES,
					maxImageDecodedBytes: DEFAULT_MAX_IMAGE_DECODED_BYTES,
				},
				mediaState,
			) === null
		);
	}

	if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
		return false;
	}

	// Remote URL byte size is unknown at formatting time, so charge the
	// conservative per-image cap instead of letting URL media count as free.
	return (
		reserveImageMediaBytes(
			DEFAULT_MAX_IMAGE_ENCODED_BYTES,
			0,
			{
				maxImageEncodedBytes: DEFAULT_MAX_IMAGE_ENCODED_BYTES,
				maxImageDecodedBytes: DEFAULT_MAX_IMAGE_DECODED_BYTES,
			},
			mediaState,
		) === null
	);
}

function isDataUrl(url: string): boolean {
	try {
		return new URL(url).protocol === "data:";
	} catch {
		return false;
	}
}

function estimateMediaDataEncodedBytes(data: unknown): number {
	if (typeof data === "string") {
		return data.length;
	}
	if (data instanceof Uint8Array) {
		return data.byteLength;
	}
	if (data instanceof ArrayBuffer) {
		return data.byteLength;
	}
	return Number.POSITIVE_INFINITY;
}

function reserveGenericMediaDataBudget(
	data: unknown,
	mediaState: MediaBudgetState,
): boolean {
	return (
		reserveImageMediaBytes(
			estimateMediaDataEncodedBytes(data),
			0,
			{
				maxImageEncodedBytes: DEFAULT_MAX_IMAGE_ENCODED_BYTES,
				maxImageDecodedBytes: DEFAULT_MAX_IMAGE_DECODED_BYTES,
			},
			mediaState,
		) === null
	);
}

/**
 * Split a tool-result `output` of type `'content'` into:
 *   - a `stripped` output where every media part is replaced by a
 *     placeholder text part, and
 *   - the list of media parts converted to `LanguageModelV4FilePart`.
 *
 * Returns `null` if the output isn't of type `'content'`, or if it doesn't
 * carry any extractable media parts (in which case no rewrite is needed).
 */
function splitContentOutputMedia(
	output: LanguageModelV4ToolResultOutput,
	mediaState: MediaBudgetState,
): SplitResult | null {
	if (output.type !== "content") {
		return null;
	}
	const media: LanguageModelV4FilePart[] = [];
	const newValue: ContentOutput["value"] = [];
	let mutated = false;
	for (const part of output.value) {
		if (!isMediaContentPart(part)) {
			newValue.push(part);
			continue;
		}
		let currentPart = part;
		if (
			currentPart.mediaType.startsWith("image/") &&
			currentPart.data.type === "data" &&
			typeof currentPart.data.data === "string"
		) {
			const validation = validateAndReserveImageMedia(
				currentPart.mediaType,
				currentPart.data.data,
				{
					maxImageEncodedBytes: DEFAULT_MAX_IMAGE_ENCODED_BYTES,
					maxImageDecodedBytes: DEFAULT_MAX_IMAGE_DECODED_BYTES,
				},
				mediaState,
			);
			if (!validation.ok) {
				newValue.push({
					type: "text",
					text: IMAGE_OMITTED_PLACEHOLDER,
				});
				mutated = true;
				continue;
			}
			currentPart = {
				...currentPart,
				data: { type: "data", data: validation.base64 },
				mediaType: validation.mediaType,
			};
		} else if (
			currentPart.mediaType.startsWith("image/") &&
			currentPart.data.type === "url"
		) {
			const url = currentPart.data.url.toString();
			if (isDataUrl(url)) {
				const validation = validateAndReserveImageMedia(
					undefined,
					url,
					{
						maxImageEncodedBytes: DEFAULT_MAX_IMAGE_ENCODED_BYTES,
						maxImageDecodedBytes: DEFAULT_MAX_IMAGE_DECODED_BYTES,
					},
					mediaState,
				);
				if (!validation.ok) {
					newValue.push(imageOmittedTextPart());
					mutated = true;
					continue;
				}
				currentPart = {
					...currentPart,
					data: {
						type: "url",
						url: new URL(
							`data:${validation.mediaType};base64,${validation.base64}`,
						),
					},
				};
			} else if (!reserveUnknownUrlMediaBudget(url, mediaState)) {
				newValue.push(imageOmittedTextPart());
				mutated = true;
				continue;
			}
		} else if (currentPart.data.type === "url") {
			if (
				!reserveUnknownUrlMediaBudget(
					currentPart.data.url.toString(),
					mediaState,
				)
			) {
				newValue.push(imageOmittedTextPart());
				mutated = true;
				continue;
			}
		} else if (currentPart.data.type === "data") {
			if (!reserveGenericMediaDataBudget(currentPart.data.data, mediaState)) {
				newValue.push(imageOmittedTextPart());
				mutated = true;
				continue;
			}
		}
		const filePart = mediaPartToFilePart(currentPart);
		if (!filePart) {
			// Unhandled media kind (image-file-id) — pass through unchanged.
			newValue.push(currentPart);
			continue;
		}
		media.push(filePart);
		mutated = true;
		const placeholder: LanguageModelV4TextPart = {
			type: "text",
			text: IMAGE_PLACEHOLDER,
		};
		newValue.push(placeholder);
	}
	if (!mutated) {
		return null;
	}
	return {
		stripped: {
			type: "content",
			value: newValue,
		},
		media,
	};
}

/**
 * Walk a `LanguageModelV4Prompt` and rewrite every `role:"tool"` message
 * containing image/file parts inside its tool-result `output`s. See the
 * file-level comment for the rewrite shape.
 *
 * Returns the (possibly new) prompt array and a `mutated` flag for
 * test/observation use.
 */
export function rewritePromptToolImages(prompt: LanguageModelV4Message[]): {
	prompt: LanguageModelV4Message[];
	mutated: boolean;
} {
	const newPrompt: LanguageModelV4Message[] = [];
	let mutated = false;
	const mediaState = createMediaBudgetState();

	for (const message of prompt) {
		if (message.role !== "tool") {
			newPrompt.push(message);
			continue;
		}

		const collectedMedia: LanguageModelV4FilePart[] = [];
		const newContent: typeof message.content = message.content.map((part) => {
			if (part.type !== "tool-result") {
				return part;
			}
			const split = splitContentOutputMedia(part.output, mediaState);
			if (!split) {
				return part;
			}
			collectedMedia.push(...split.media);
			mutated = true;
			const newPart: LanguageModelV4ToolResultPart = {
				...part,
				output: split.stripped,
			};
			return newPart;
		});

		newPrompt.push({ ...message, content: newContent });

		if (collectedMedia.length > 0) {
			newPrompt.push({
				role: "user",
				content: collectedMedia,
			});
		}
	}

	return { prompt: newPrompt, mutated };
}

/**
 * `LanguageModelV4Middleware` that splits image-carrying tool-result
 * messages so chat-completions-style converters don't lose the bytes.
 *
 * Apply via `wrapLanguageModel({ model, middleware: splitToolImagesMiddleware })`
 * in any provider whose downstream converter doesn't natively handle
 * multimodal `role:"tool"` content (currently: `@ai-sdk/openai-compatible`,
 * `@ai-sdk/mistral`).
 *
 * Anthropic's converter natively renders content arrays on tool-result
 * messages and should NOT use this middleware — it would replace
 * structurally-faithful tool-results with the placeholder text + sibling
 * user message pattern unnecessarily.
 */
export const splitToolImagesMiddleware: LanguageModelV4Middleware = {
	specificationVersion: "v4",
	transformParams: async ({ params }) => {
		const { prompt: newPrompt, mutated } = rewritePromptToolImages(
			params.prompt,
		);
		if (!mutated) {
			return params;
		}
		const next: LanguageModelV4CallOptions = {
			...params,
			prompt: newPrompt,
		};
		return next;
	},
};

// Single, exhaustive classification of every `LanguageModelV4StreamPart`.
//
// Two consumers previously held independent, incomplete interpretations of
// this union: the empty-response retry middleware decided "did the model
// produce anything?" and `emitAiSdkEvents()` in `ai-sdk.ts` decided "what do
// we convert into agent events?". A part counted by one but not the other
// produced exactly the failure the retry exists to prevent — e.g. a
// file-only turn was "content" to the middleware (never retried) but was
// dropped by the adapter, so the assistant message came out empty and the
// task still died with "Model returned empty response".
//
// This module is the one place that assigns each part a class; the retry
// middleware derives retry eligibility from it, and the adapter's supported
// set must stay in sync with `converted-content` (asserted by tests). The
// switch is exhaustive with a `never` check, so an AI SDK upgrade that adds
// a new part type fails compilation here instead of silently landing in the
// wrong bucket.

import type { LanguageModelV4StreamPart } from "@ai-sdk/provider";

export type ModelStreamPartClass =
	/**
	 * Output that `emitAiSdkEvents()` converts into `AgentModelEvent`s and
	 * that therefore reaches the assistant message. A turn containing any of
	 * these is not empty.
	 */
	| "converted-content"
	/**
	 * Real model output that Cline does not (yet) convert into agent events.
	 * The model responded, so retrying would waste billable requests and
	 * likely reproduce the same output — never retried. If a turn contains
	 * ONLY unsupported output the assistant message can still come out
	 * empty; that is an explicit contract gap of this bucket, preferred over
	 * silently re-billing a turn the model did answer.
	 */
	| "unsupported-output"
	/** Markers and metadata that do not constitute model output. */
	| "structural"
	/** `stream-start` — carries warnings; one per attempt. */
	| "stream-start"
	/** Terminal accounting part — carries usage and the finish reason. */
	| "finish"
	/** An upstream error surfaced as a stream part. */
	| "error";

export function classifyModelStreamPart(
	part: LanguageModelV4StreamPart,
): ModelStreamPartClass {
	switch (part.type) {
		case "text-delta":
		case "reasoning-delta":
			return part.delta.length > 0 ? "converted-content" : "structural";
		// Tool activity: the adapter converts tool calls (and their streaming
		// input parts assemble into them). A tool-call-only turn is the
		// normal shape when the model wants to act — never empty.
		case "tool-call":
		case "tool-input-start":
		case "tool-input-delta":
		case "tool-input-end":
			return "converted-content";
		// Generated files are converted into `file` agent events (see
		// `emitAiSdkEvents`) and land in the assistant message as image or
		// file parts.
		case "file":
			return "converted-content";
		// Provider-executed tool results arrive after a converted tool-call;
		// the result itself is not translated into an agent event.
		case "tool-result":
		// Provider-side approval requests for provider-executed tools.
		case "tool-approval-request":
		// Opaque reasoning blobs (e.g. encrypted/redacted thinking files).
		case "reasoning-file":
		// Provider-specific content in `{provider}.{type}` envelopes.
		case "custom":
		// URL citations attached to generated text.
		case "source":
			return "unsupported-output";
		case "text-start":
		case "text-end":
		case "reasoning-start":
		case "reasoning-end":
		case "response-metadata":
		case "raw":
			return "structural";
		case "stream-start":
			return "stream-start";
		case "finish":
			return "finish";
		case "error":
			return "error";
		default: {
			// Exhaustiveness guard: a new AI SDK part type must be classified
			// deliberately, not fall through.
			const unhandled: never = part;
			throw new Error(
				`Unclassified model stream part: ${JSON.stringify(unhandled)}`,
			);
		}
	}
}

/**
 * Whether a completed attempt that contained only parts for which this
 * returns `false` (plus `stream-start`/`finish`) counts as a genuinely empty
 * turn. Both converted and unsupported output mean "the model responded".
 */
export function isModelOutputPart(part: LanguageModelV4StreamPart): boolean {
	const kind = classifyModelStreamPart(part);
	return kind === "converted-content" || kind === "unsupported-output";
}

import type {
	GatewayModelRoute,
	GatewayProviderContext,
	GatewayReasoningFormat,
	GatewayStreamRequest,
	ModelReasoningOption,
	ReasoningEffort,
} from "@cline/shared";
import { REASONING_LEVELS } from "@cline/shared";

const ACTIVE_REASONING_EFFORTS = REASONING_LEVELS.filter(
	(level): level is ReasoningEffort => level !== "none",
);

interface ModelReasoningControls {
	effort?: Extract<ModelReasoningOption, { type: "effort" }>;
	budget?: Extract<ModelReasoningOption, { type: "budget_tokens" }>;
	toggle: boolean;
	efforts: ReasoningEffort[];
	supportsOff: boolean;
	supportsDefault: boolean;
}

export function getModelReasoningControls(
	options: readonly ModelReasoningOption[] | undefined,
): ModelReasoningControls | undefined {
	if (options === undefined) {
		return undefined;
	}

	const effort = options.find((option) => option.type === "effort");
	const budget = options.find((option) => option.type === "budget_tokens");
	const toggle = options.some((option) => option.type === "toggle");
	const advertised = new Set(effort?.values ?? []);
	return {
		effort,
		budget,
		toggle,
		efforts: ACTIVE_REASONING_EFFORTS.filter((value) => advertised.has(value)),
		supportsOff: toggle || advertised.has("none"),
		supportsDefault: advertised.has("default"),
	};
}

export function normalizeReasoningEffort(
	effort: ReasoningEffort,
	supportedEfforts: readonly ReasoningEffort[],
): ReasoningEffort | undefined {
	if (supportedEfforts.length === 0) {
		return undefined;
	}
	if (supportedEfforts.includes(effort)) {
		return effort;
	}

	const requestedIndex = ACTIVE_REASONING_EFFORTS.indexOf(effort);
	return supportedEfforts.reduce((nearest, candidate) => {
		const nearestDistance = Math.abs(
			ACTIVE_REASONING_EFFORTS.indexOf(nearest) - requestedIndex,
		);
		const candidateDistance = Math.abs(
			ACTIVE_REASONING_EFFORTS.indexOf(candidate) - requestedIndex,
		);
		// On a tie, preserve more capability.
		return candidateDistance <= nearestDistance ? candidate : nearest;
	});
}

export function resolveModelFamily(
	context: GatewayProviderContext,
): string | undefined {
	const family = context.model.metadata?.family;
	return typeof family === "string" ? family : undefined;
}

export function normalizeRoutingValue(value: string | undefined) {
	const normalized = value?.trim().toLowerCase();
	return normalized ? normalized : undefined;
}

function normalizedFamily(context: GatewayProviderContext): string {
	return normalizeRoutingValue(resolveModelFamily(context)) ?? "";
}

function normalizedModelId(
	request: Pick<GatewayStreamRequest, "modelId">,
): string {
	return normalizeRoutingValue(request.modelId) ?? "";
}

function geminiModelDescriptor(input: {
	request: Pick<GatewayStreamRequest, "modelId">;
	context: GatewayProviderContext;
}): string {
	return [
		input.request.modelId,
		input.context.model.id,
		input.context.model.name,
		input.context.model.metadata?.family,
	]
		.filter(Boolean)
		.join(" ")
		.toLowerCase();
}

function isProviderBaseOrigin(
	context: GatewayProviderContext,
	origin: string,
): boolean {
	const baseUrl = normalizeRoutingValue(
		context.config.baseUrl ?? context.provider.api,
	)?.replace(/\/+$/, "");
	if (!baseUrl) {
		return false;
	}

	try {
		return new URL(baseUrl).origin.toLowerCase() === origin;
	} catch {
		return baseUrl === origin || baseUrl.startsWith(`${origin}/`);
	}
}

function isAnthropicLineageValue(value: string | undefined): boolean {
	const normalized = normalizeRoutingValue(value);
	return normalized
		? normalized.includes("anthropic") || normalized.includes("claude")
		: false;
}

function isClaudeLineageValue(value: string | undefined): boolean {
	return normalizeRoutingValue(value)?.includes("claude") ?? false;
}

function isQwenLineageValue(value: string | undefined): boolean {
	const normalized = normalizeRoutingValue(value);
	return normalized
		? /(^|[/:._-])qwen(?:$|[/:._-]|\d)/.test(normalized)
		: false;
}

export function isAnthropicCompatibleModel(options: {
	modelId?: string;
	family?: string;
}): boolean {
	const family = normalizeRoutingValue(options.family);
	if (family) {
		return isAnthropicLineageValue(family);
	}

	return isAnthropicCompatibleModelId(options.modelId);
}

export function isAnthropicCompatibleModelId(
	modelId: string | undefined,
): boolean {
	if (!modelId) {
		return false;
	}

	return isAnthropicLineageValue(modelId);
}

export function isClaudeModelId(modelId: string | undefined): boolean {
	if (!modelId) {
		return false;
	}

	return isClaudeLineageValue(modelId);
}

export function isClaudeFableModelId(modelId: string | undefined): boolean {
	return normalizeRoutingValue(modelId)?.includes("claude-fable") ?? false;
}

// Known pre-adaptive Claude families that only accept the manual
// `thinking: {type: "enabled", budgetTokens}` wire shape (or no thinking at
// all): Claude Instant, 2.x, and 3.x version-first ids. Mirrors the legacy
// guard in @ai-sdk/anthropic's capability lookup.
const CLAUDE_LEGACY_FAMILY_PATTERN =
	/claude-(?:instant(?:-|$)|v?2(?=$|[-.:])|3(?=$|[-.]))/;

// Matches modern name-first Anthropic ids ("claude-sonnet-4-6",
// "claude-opus-5", "anthropic.claude-opus-4-8-v1:0", "claude-sonnet-4.6").
// The minor is capped at two digits so date-stamp suffixes
// ("claude-sonnet-5-20260629") do not parse as versions.
const CLAUDE_NAME_FIRST_VERSION_PATTERN =
	/claude-(?:opus|sonnet|haiku)-(\d+)(?:[.-](\d{1,2}))?(?=$|[-.:@])/;

/**
 * Wire-shape era of a Claude model id, used only as a fallback when catalog
 * `reasoningOptions` metadata is unavailable (offline baked catalog,
 * user-typed unlisted ids such as "claude-opus-4-6:1m").
 *
 * - "adaptive": 4.6+/5.x models; the Anthropic API rejects the manual
 *   `thinking: {type: "enabled", budgetTokens}` shape for these.
 * - "legacy": known pre-4.6 families that require the manual shape.
 * - "unknown-claude": a Claude id the version parser does not recognize.
 *   Callers should treat these as NEWER than the known list and prefer
 *   adaptive — the forward-compatible policy the ecosystem converged on
 *   (vercel/ai#17804 for @ai-sdk/anthropic's capability lookup; opencode's
 *   transform.ts after repeated allowlist misses for opus-4.7, sonnet-5,
 *   and opus-5). New Claude releases reject the manual shape, so an
 *   allowlist that lags a release turns every reasoning request into a
 *   hard API error.
 * - "not-claude": non-Claude ids (including Anthropic-compatible aliases)
 *   stay conservative for third-party endpoints.
 */
export type ClaudeThinkingEra =
	| "adaptive"
	| "legacy"
	| "unknown-claude"
	| "not-claude";

export function resolveClaudeThinkingEra(
	modelId: string | undefined,
): ClaudeThinkingEra {
	const normalized = normalizeRoutingValue(modelId);
	if (!normalized || !normalized.includes("claude")) {
		return "not-claude";
	}
	if (CLAUDE_LEGACY_FAMILY_PATTERN.test(normalized)) {
		return "legacy";
	}

	const match = CLAUDE_NAME_FIRST_VERSION_PATTERN.exec(normalized);
	if (match) {
		const major = Number(match[1]);
		const minor = match[2] !== undefined ? Number(match[2]) : 0;
		return major >= 5 || (major === 4 && minor >= 6) ? "adaptive" : "legacy";
	}

	return "unknown-claude";
}

export function isQwenModel(options: {
	modelId?: string;
	family?: string;
}): boolean {
	const family = normalizeRoutingValue(options.family);
	if (isQwenLineageValue(family)) {
		return true;
	}

	return isQwenLineageValue(options.modelId);
}

// OpenAI reasoning-era chat models: the o-series (o1/o3/o4, including -mini,
// -pro, and dated variants) and the gpt-5 family (including gpt-5-chat).
// These models diverge from classic chat-completions parameter rules — most
// importantly they reject `max_tokens` and require `max_completion_tokens`.
// Detection is an id-pattern fallback (mirroring the legacy extension's
// OpenAI handler) because OpenAI-compatible endpoints accept free-form,
// user-typed model ids with no catalog metadata to rely on. The patterns
// require non-alphanumeric boundaries so ids like "gpt-4o" or "yolo1" never
// match, while namespaced ids like "openai/o3-mini" do.
//
// Maintenance:
// - If OpenAI ships a new family with the same parameter rules (e.g. gpt-6),
//   add a pattern here and cases to the positive/negative lists in
//   `vendors/openai-compatible.test.ts`. The failure mode until then is the
//   loud, self-describing OpenAI 400 ("'max_tokens' is not supported with
//   this model. Use 'max_completion_tokens' instead."), not silent breakage.
// - Keep the boundary anchoring on BOTH sides of each pattern; loosening it
//   risks renaming the parameter for unrelated third-party models.
// - Only `withMaxCompletionTokensForReasoningModels` in
//   `vendors/openai-compatible.ts` consumes this. If a future
//   `@ai-sdk/openai-compatible` maps `max_completion_tokens` itself (as
//   `@ai-sdk/openai` already does), delete that transform and this helper.
const OPENAI_O_SERIES_MODEL_ID_PATTERN = /(^|[^a-z0-9])o[134](?=$|[^a-z0-9])/;
const OPENAI_GPT5_FAMILY_MODEL_ID_PATTERN =
	/(^|[^a-z0-9])gpt-?5(?=$|[^a-z0-9])/;

export function isOpenAIReasoningEraModelId(
	modelId: string | undefined,
): boolean {
	const normalized = normalizeRoutingValue(modelId);
	if (!normalized) {
		return false;
	}

	return (
		OPENAI_O_SERIES_MODEL_ID_PATTERN.test(normalized) ||
		OPENAI_GPT5_FAMILY_MODEL_ID_PATTERN.test(normalized)
	);
}

export function resolveGeminiThinkingMode(input: {
	request: Pick<GatewayStreamRequest, "modelId">;
	context: GatewayProviderContext;
}): "level" | "budget" | undefined {
	const controls = getModelReasoningControls(
		input.context.model.reasoningOptions,
	);
	if (controls) {
		return controls.effort
			? "level"
			: controls.budget || controls.toggle
				? "budget"
				: undefined;
	}

	// Legacy/offline catalogs do not yet carry reasoning_options. Keep their
	// wire choice in one fallback boundary; live models use metadata above.
	const descriptor = geminiModelDescriptor(input);
	return /(^|[/\s])gemini-3([.-]|$)/.test(descriptor)
		? "level"
		: /(^|[/\s])gemini-2\.5([-\s]|$)/.test(descriptor) ||
				descriptor.includes("gemini-flash-latest")
			? "budget"
			: undefined;
}

function modelFamilyMatches(
	family: string | undefined,
	routeFamily: string | undefined,
): boolean {
	const normalizedFamily = normalizeRoutingValue(family);
	const normalizedRouteFamily = normalizeRoutingValue(routeFamily);
	if (!normalizedFamily || !normalizedRouteFamily) {
		return false;
	}
	if (normalizedFamily === normalizedRouteFamily) {
		return true;
	}
	return normalizedRouteFamily === "qwen"
		? isQwenLineageValue(normalizedFamily)
		: false;
}

export function modelRouteMatches(
	route: GatewayModelRoute,
	options: {
		modelId?: string;
		family?: string;
		capabilities?: readonly string[];
	},
): boolean {
	if (
		"requiredCapability" in route &&
		route.requiredCapability &&
		!options.capabilities?.includes(route.requiredCapability)
	) {
		return false;
	}

	switch (route.matcher) {
		case "anthropic-compatible":
			return isAnthropicCompatibleModel(options);
		case "model-family":
			return modelFamilyMatches(options.family, route.family);
		case "model-id":
			return (
				normalizeRoutingValue(options.modelId) ===
				normalizeRoutingValue(route.modelId)
			);
	}
}

export function providerReasoningRouteMatches(
	format: GatewayReasoningFormat,
	request: Pick<GatewayStreamRequest, "modelId">,
	context: GatewayProviderContext,
): boolean {
	const reasoning = context.provider.metadata?.routing?.reasoning;
	if (reasoning?.format !== format) {
		return false;
	}

	return reasoning.routes.some((route) =>
		modelRouteMatches(route, {
			modelId: request.modelId,
			family: resolveModelFamily(context),
			capabilities: context.model.capabilities,
		}),
	);
}

export function isGlmModel(
	request: Pick<GatewayStreamRequest, "modelId">,
	context: GatewayProviderContext,
): boolean {
	const family = normalizedFamily(context);

	// Dynamic provider fallback: some routed/local catalogs only provide ids.
	return family.includes("glm") || normalizedModelId(request).includes("glm");
}

export function isMiniMaxM3Model(
	request: Pick<GatewayStreamRequest, "modelId">,
	_context: GatewayProviderContext,
): boolean {
	const modelId = normalizedModelId(request);

	return modelId === "minimax-m3" || modelId === "minimax/minimax-m3";
}

export function isKimiK26Family(context: GatewayProviderContext): boolean {
	return normalizedFamily(context) === "kimi-k2.6";
}

export function isMoonshotKimiModelIdFallback(
	request: Pick<GatewayStreamRequest, "modelId">,
): boolean {
	// Dynamic provider fallback for Moonshot-routed model ids when family
	// metadata is absent or not specific enough.
	return normalizedModelId(request).includes("moonshotai/kimi-");
}

export function isDeepSeekFamily(context: GatewayProviderContext): boolean {
	return normalizedFamily(context).includes("deepseek");
}

/**
 * Whether the resolved model advertises image input (`"images"` in its
 * gateway capabilities). Models with no capability data at all (e.g. ids
 * resolved outside any catalog) fail open: images are kept rather than
 * hidden from a possibly capable model.
 */
export function modelSupportsImageInput(
	context: GatewayProviderContext,
): boolean {
	const capabilities = context.model.capabilities;
	if (!capabilities) {
		return true;
	}
	return capabilities.includes("images");
}

export function getReasoningDefaultOnMetadata(
	context: GatewayProviderContext,
): boolean | undefined {
	const value = context.model.metadata?.reasoningDefaultOn;
	return typeof value === "boolean" ? value : undefined;
}

export function isOllamaQwen3ModelIdFallback(
	request: Pick<GatewayStreamRequest, "providerId" | "modelId">,
): boolean {
	// Local Ollama models are discovered from /api/tags and often only provide
	// names such as "qwen3-coder:30b". This fallback is used by
	// modelReasoningDefaultsOn when no catalog metadata is present.
	return (
		request.providerId === "ollama" &&
		normalizedModelId(request).includes("qwen3")
	);
}

export function isCerebrasProvider(
	request: Pick<GatewayStreamRequest, "providerId">,
	context: GatewayProviderContext,
): boolean {
	const providerIds = [
		request.providerId,
		context.config.providerId,
		context.provider.id,
	].map((id) => id.toLowerCase());

	return (
		providerIds.includes("cerebras") ||
		isProviderBaseOrigin(context, "https://api.cerebras.ai")
	);
}

export function modelReasoningDefaultsOn(options: {
	request: Pick<GatewayStreamRequest, "providerId" | "modelId">;
	context: GatewayProviderContext;
}): boolean {
	return (
		getReasoningDefaultOnMetadata(options.context) ??
		isOllamaQwen3ModelIdFallback(options.request)
	);
}

import type {
	ModelCollection,
	ModelInfo,
	ProviderInfo,
} from "../catalog/types";
import { BUILTIN_PROVIDER_COLLECTION_LIST } from "./builtins";

function buildInitialRegistry(): Map<string, ModelCollection> {
	const map = new Map<string, ModelCollection>();
	for (const collection of BUILTIN_PROVIDER_COLLECTION_LIST) {
		map.set(collection.provider.id, {
			provider: { ...collection.provider },
			models: Object.fromEntries(
				Object.entries(collection.models).map(([id, model]) => [
					id,
					{ ...model },
				]),
			),
		});
	}
	return map;
}

const PROVIDER_CACHE: Map<string, ModelCollection> = buildInitialRegistry();
const CUSTOM_MODELS: Map<string, Map<string, ModelInfo>> = new Map();
const CUSTOM_PROVIDERS: Map<string, ModelCollection> = new Map();

function getProviderFromCache(providerId: string): ModelCollection | undefined {
	return CUSTOM_PROVIDERS.get(providerId) ?? PROVIDER_CACHE.get(providerId);
}

export function getProviderIds(): string[] {
	const builtInIds = Array.from(PROVIDER_CACHE.keys());
	const customIds = Array.from(CUSTOM_PROVIDERS.keys()).filter(
		(id) => !PROVIDER_CACHE.has(id),
	);
	return [...builtInIds, ...customIds];
}

export function hasProvider(providerId: string): boolean {
	return PROVIDER_CACHE.has(providerId) || CUSTOM_PROVIDERS.has(providerId);
}

export async function getProvider(
	providerId: string,
): Promise<ProviderInfo | undefined> {
	return getProviderFromCache(providerId)?.provider;
}

export function getProviderCollectionSync(
	providerId: string,
): ModelCollection | undefined {
	return getProviderFromCache(providerId);
}

export async function getProviderCollection(
	providerId: string,
): Promise<ModelCollection | undefined> {
	return getProviderFromCache(providerId);
}

export async function getModelsForProvider(
	providerId: string,
): Promise<Record<string, ModelInfo>> {
	const collection = getProviderFromCache(providerId);
	const builtInModels = collection?.models ?? {};
	const customModels = CUSTOM_MODELS.get(providerId);
	if (customModels) {
		return { ...builtInModels, ...Object.fromEntries(customModels) };
	}
	return builtInModels;
}

export async function getAllProviders(): Promise<ProviderInfo[]> {
	return getProviderIds()
		.map((id) => getProviderFromCache(id)?.provider)
		.filter((p): p is ProviderInfo => p !== undefined);
}

export function registerProvider(collection: ModelCollection): void {
	CUSTOM_PROVIDERS.set(collection.provider.id, collection);
}

export function registerModel(
	providerId: string,
	modelId: string,
	info: ModelInfo,
): void {
	if (!CUSTOM_MODELS.has(providerId)) {
		CUSTOM_MODELS.set(providerId, new Map());
	}
	CUSTOM_MODELS.get(providerId)?.set(modelId, { ...info, id: modelId });
}

export function unregisterModel(providerId: string, modelId: string): boolean {
	return CUSTOM_MODELS.get(providerId)?.delete(modelId) ?? false;
}

export function unregisterProvider(providerId: string): boolean {
	CUSTOM_MODELS.delete(providerId);
	return CUSTOM_PROVIDERS.delete(providerId);
}

export function resetRegistry(): void {
	CUSTOM_MODELS.clear();
	CUSTOM_PROVIDERS.clear();
}

// MODEL_COLLECTIONS_BY_PROVIDER_ID: live view merging custom providers over builtins
export const MODEL_COLLECTIONS_BY_PROVIDER_ID: Record<string, ModelCollection> =
	new Proxy({} as Record<string, ModelCollection>, {
		get(_target, key: string) {
			return getProviderFromCache(key);
		},
		has(_target, key: string) {
			return PROVIDER_CACHE.has(key) || CUSTOM_PROVIDERS.has(key);
		},
		ownKeys() {
			return getProviderIds();
		},
		getOwnPropertyDescriptor(_target, key: string) {
			const val = getProviderFromCache(key as string);
			if (val === undefined) return undefined;
			return { configurable: true, enumerable: true, value: val };
		},
	});

import { describe, expect, it } from "vitest";
import type { ModelInfo } from "../catalog/types";
import {
	CODEX_EFFECTIVE_CONTEXT_WINDOW_PERCENT,
	filterOpenAICodexModels,
} from "./openai-codex-models";

function makeModel(id: string, overrides: Partial<ModelInfo> = {}): ModelInfo {
	return {
		id,
		contextWindow: 400_000,
		maxInputTokens: 300_000,
		maxTokens: 100_000,
		family: id.replace(/^gpt-/, "gpt"),
		...overrides,
	};
}

function filterOne(
	id: string,
	overrides: Partial<ModelInfo> = {},
): ModelInfo | undefined {
	return filterOpenAICodexModels({ [id]: makeModel(id, overrides) })[id];
}

describe("filterOpenAICodexModels", () => {
	describe("model eligibility", () => {
		it.each([
			["gpt-5.4", true],
			["gpt-5.5", true],
			["gpt-5.5-codex", true],
			["gpt-6.0", true],
			["gpt-10.1", true],
		])("allows %s (newer than 5.3)", (id, allowed) => {
			expect(filterOne(id) !== undefined).toBe(allowed);
		});

		it.each([
			["gpt-5.3", "at the 5.3 cutoff"],
			["gpt-5.1", "older than 5.3"],
			["gpt-4.1", "older major version"],
			["gpt-5", "no minor version"],
			["chatgpt-5.5", "id does not start with gpt-"],
			["davinci", "not a gpt model"],
		])("rejects %s (%s)", (id) => {
			expect(filterOne(id)).toBeUndefined();
		});

		it.each([
			["o-series", "o4"],
			["pro variant", "gpt5.5-pro"],
			["nano variant", "gpt5.5-nano"],
		])("rejects %s families regardless of id version", (_label, family) => {
			expect(filterOne("gpt-6.0", { family })).toBeUndefined();
		});

		it("falls back to the id version check when family is missing", () => {
			expect(filterOne("gpt-6.0", { family: undefined })).toBeDefined();
			expect(filterOne("gpt-5.0", { family: undefined })).toBeUndefined();
		});
	});

	describe("context window adjustment", () => {
		it.each([
			"gpt-5.4",
			"gpt-5.4-mini",
			"gpt-6.0",
		])("scales %s maxInputTokens down to the effective Codex budget — the backend cap applies to every model, not just gpt-5.5", (id) => {
			const maxInputTokens = 200_000;
			const result = filterOne(id, { maxInputTokens });
			expect(result?.maxInputTokens).toBe(
				maxInputTokens * CODEX_EFFECTIVE_CONTEXT_WINDOW_PERCENT,
			);
		});

		it("leaves other limits untouched for non-5.5 models", () => {
			const result = filterOne("gpt-6.0", {
				contextWindow: 500_000,
				maxTokens: 64_000,
			});
			expect(result?.contextWindow).toBe(500_000);
			expect(result?.maxTokens).toBe(64_000);
		});

		it("preserves an undefined maxInputTokens instead of producing NaN", () => {
			const result = filterOne("gpt-6.0", { maxInputTokens: undefined });
			expect(result?.maxInputTokens).toBeUndefined();
		});

		it("overrides gpt-5.5 limits with the ChatGPT backend caps", () => {
			const result = filterOne("gpt-5.5-codex", {
				contextWindow: 1_000_000,
				maxInputTokens: 900_000,
				maxTokens: 900_000,
			});
			expect(result).toMatchObject({
				contextWindow: 400_000,
				maxInputTokens: 272_000 * CODEX_EFFECTIVE_CONTEXT_WINDOW_PERCENT,
				maxTokens: 128_000,
			});
		});

		it("does not mutate the input models", () => {
			const model = makeModel("gpt-6.0");
			const snapshot = structuredClone(model);
			filterOpenAICodexModels({ "gpt-6.0": model });
			expect(model).toEqual(snapshot);
		});
	});

	it("keeps allowed models and drops disallowed ones from a mixed catalog", () => {
		const models: Record<string, ModelInfo> = {
			"gpt-5.5": makeModel("gpt-5.5"),
			"gpt-6.0": makeModel("gpt-6.0"),
			"gpt-5.1": makeModel("gpt-5.1"),
			"o4-mini": makeModel("o4-mini", { family: "o4" }),
		};
		expect(Object.keys(filterOpenAICodexModels(models)).sort()).toEqual([
			"gpt-5.5",
			"gpt-6.0",
		]);
	});
});

import type { ModelInfo } from "../catalog/types";

/**
 * The ChatGPT/Codex backend starts rejecting requests around 95% of a
 * model's advertised input cap, so every model exposed through this
 * provider gets its maxInputTokens scaled down to the effective budget.
 *
 * REF: https://github.com/openai/codex/issues/19319
 */
export const CODEX_EFFECTIVE_CONTEXT_WINDOW_PERCENT = 0.95;

const GPT_VERSION_REGEX = /^gpt-(\d+\.\d+)/;

function isOpenAICodexAllowedModel(id: string, model: ModelInfo): boolean {
	// O, pro, and nano variants are not supported
	const family = model.family;
	if (
		family &&
		(family.startsWith("o") ||
			family.includes("pro") ||
			family.includes("nano"))
	) {
		return false;
	}
	// Must be newer than 5.3
	const match = id.match(GPT_VERSION_REGEX);
	return match ? Number.parseFloat(match[1]) > 5.3 : false;
}

/**
 * Applies the effective input budget to every allowed model. GPT-5.5
 * additionally gets hardcoded limits because the ChatGPT/Codex backend
 * enforces a 272K input / 128K output cap that is lower than what the
 * generated OpenAI API catalog reports.
 */
function toOpenAICodexModel(id: string, model: ModelInfo): ModelInfo {
	if (id.includes("gpt-5.5")) {
		return {
			...model,
			contextWindow: 400_000,
			maxInputTokens: 272_000 * CODEX_EFFECTIVE_CONTEXT_WINDOW_PERCENT,
			maxTokens: 128_000,
		};
	}
	return {
		...model,
		maxInputTokens: model.maxInputTokens
			? model.maxInputTokens * CODEX_EFFECTIVE_CONTEXT_WINDOW_PERCENT
			: model.maxInputTokens,
	};
}

export function filterOpenAICodexModels(
	models: Record<string, ModelInfo>,
): Record<string, ModelInfo> {
	const result: Record<string, ModelInfo> = {};
	for (const [id, model] of Object.entries(models)) {
		if (isOpenAICodexAllowedModel(id, model)) {
			result[id] = toOpenAICodexModel(id, model);
		}
	}
	return result;
}

/**
 * Relates the provider identifiers used at each stage of catalog generation and
 * runtime provider selection:
 *
 * - `modelsDevKey` is the provider's key in the models.dev API payload.
 * - `generatedProviderId` is Cline's canonical ID for the provider spec and
 *   model catalog generated from that payload. Generation maps
 *   `modelsDevKey -> generatedProviderId` so upstream names do not leak into
 *   Cline's public provider IDs.
 * - `runtimeProviderId` is the ID of a configured provider implementation that
 *   should read models from that generated catalog.
 *
 * Generated and runtime IDs are separate because multiple runtime transports or
 * authentication methods can share one catalog. For example, `openai-native`,
 * `openai-codex`, and `openai-codex-cli` are distinct runtime providers, but all
 * resolve to the `openai-native` catalog generated from models.dev's `openai`
 * entry. `resolveProviderModelCatalogKeys` performs that runtime-to-catalog
 * lookup. An omitted generated or runtime ID means that row participates only
 * in the other applicable lookup.
 */
