function dedupe(values: readonly string[]): string[] {
	return [...new Set(values)];
}

export const MODELS_DEV_PROVIDER_KEY_MAP = Object.fromEntries(
	PROVIDER_IDS_MAP.flatMap((entry) =>
		entry.generatedProviderId
			? [[entry.modelsDevKey, entry.generatedProviderId]]
			: [],
	),
);

/**
 * Providers that must remain excluded even when their models.dev entry uses a
 * supported AI SDK package. IDs use Cline's generated provider identifiers
 * after applying MODELS_DEV_PROVIDER_KEY_MAP.
 */
export const MODELS_DEV_BLOCKED_PROVIDER_IDS: ReadonlySet<string> = new Set();

export const MODELS_DEV_CURRENT_BUILTIN_PROVIDER_KEYS = new Set(
	PROVIDER_IDS_MAP.map((entry) => entry.modelsDevKey),
);

export function resolveGeneratedProviderIdForModelsDevKey(
	modelsDevKey: string,
): string | undefined {
	return MODELS_DEV_PROVIDER_KEY_MAP[modelsDevKey];
}

export function resolveProviderModelCatalogKeys(providerId: string): string[] {
	const mapped = PROVIDER_IDS_MAP.flatMap((entry) => {
		if (!entry.generatedProviderId) {
			return [];
		}
		if (
			entry.generatedProviderId === providerId ||
			entry.runtimeProviderId === providerId
		) {
			return [entry.generatedProviderId];
		}
		return [];
	});

	if (providerId === "nousResearch") {
		return dedupe([...mapped, "nousresearch", providerId]);
	}

	return dedupe([...mapped, providerId]);
}

import { createHash } from "node:crypto";
import {
	existsSync,
	mkdirSync,
	readdirSync,
	renameSync,
	rmSync,
	statSync,
	writeFileSync,
} from "node:fs";
import { join, resolve } from "node:path";
import type { GatewayStreamRequest } from "@cline/shared";
import { estimateTokens } from "@cline/shared";

type CaptureMode = "off" | "summary" | "full";
type CaptureStage = "ai_sdk_prompt" | "wire_request";

const DEFAULT_MAX_PREVIEW_BYTES = 64 * 1024;
const CAPTURE_FILE_EXTENSION = ".provider-request.json";
const CAPTURE_TMP_EXTENSION = ".tmp";
const CLEANUP_TTL_MS = 24 * 60 * 60 * 1000;
const cleanupDirs = new Set<string>();
const attemptCounters = new Map<string, number>();

function readCaptureMode(): CaptureMode {
	const raw = process.env.CLINE_CAPTURE_PROVIDER_REQUEST?.trim().toLowerCase();
	if (raw === "summary" || raw === "full") {
		return raw;
	}
	return "off";
}

function isWireCaptureEnabled(): boolean {
	return process.env.CLINE_CAPTURE_WIRE?.trim().toLowerCase() === "true";
}

function readMaxPreviewBytes(): number {
	const parsed = Number(process.env.CLINE_CAPTURE_MAX_PREVIEW_BYTES);
	return Number.isFinite(parsed) && parsed > 0
		? Math.floor(parsed)
		: DEFAULT_MAX_PREVIEW_BYTES;
}

function isCleanupEnabled(): boolean {
	return process.env.CLINE_CAPTURE_CLEANUP?.trim().toLowerCase() !== "off";
}

function resolveCaptureDir(): string | undefined {
	const explicit = process.env.CLINE_CAPTURE_DIR?.trim();
	if (explicit) {
		return resolve(explicit);
	}
	const dataDir = process.env.CLINE_DATA_DIR?.trim();
	if (dataDir) {
		return resolve(dataDir, "provider-request-captures");
	}
	return undefined;
}

function safeStringify(value: unknown): string {
	const seen = new WeakSet<object>();
	try {
		return (
			JSON.stringify(value, (_key, nestedValue: unknown) => {
				if (typeof nestedValue === "bigint") {
					return nestedValue.toString();
				}
				if (typeof nestedValue !== "object" || nestedValue === null) {
					return nestedValue;
				}
				if (seen.has(nestedValue)) {
					return "[Circular]";
				}
				seen.add(nestedValue);
				return nestedValue;
			}) ?? ""
		);
	} catch {
		return String(value ?? "");
	}
}

function hashString(value: string): string {
	return createHash("sha256").update(value).digest("hex");
}

function byteLength(value: string): number {
	return Buffer.byteLength(value, "utf8");
}

function previewValue(
	value: unknown,
	maxBytes = DEFAULT_MAX_PREVIEW_BYTES,
): unknown {
	const serialized = safeStringify(value);
	if (byteLength(serialized) <= maxBytes) {
		return value;
	}
	const previewBuffer = Buffer.from(serialized, "utf8").subarray(0, maxBytes);
	let preview = previewBuffer.toString("utf8");
	while (byteLength(preview) > maxBytes) {
		preview = preview.slice(0, -1);
	}
	return {
		truncated: true,
		bytes: byteLength(serialized),
		sha256: hashString(serialized),
		preview,
	};
}

function summarizeContent(value: unknown): {
	bytes: number;
	estimatedTokens: number;
	sha256: string;
	kind: string;
} {
	const serialized = typeof value === "string" ? value : safeStringify(value);
	return {
		bytes: byteLength(serialized),
		estimatedTokens: estimateTokens(byteLength(serialized)),
		sha256: hashString(serialized),
		kind: Array.isArray(value) ? "array" : typeof value,
	};
}

function summarizeMessages(messages: unknown): Record<string, unknown> {
	if (!Array.isArray(messages)) {
		return summarizeContent(messages);
	}

	const roleCounts: Record<string, number> = {};
	let reasoningBlockCount = 0;
	let toolResultCount = 0;
	const messageSummaries = messages.map((message, index) => {
		const record =
			message && typeof message === "object"
				? (message as Record<string, unknown>)
				: {};
		const role = typeof record.role === "string" ? record.role : "unknown";
		roleCounts[role] = (roleCounts[role] ?? 0) + 1;
		const content = record.content;
		const contentArray = Array.isArray(content) ? content : [content];
		for (const part of contentArray) {
			if (!part || typeof part !== "object") continue;
			const type = (part as Record<string, unknown>).type;
			if (type === "reasoning") reasoningBlockCount += 1;
			if (type === "tool-result" || role === "tool") toolResultCount += 1;
		}
		const contentSummary = summarizeContent(content);
		return {
			index,
			role,
			contentParts: contentArray.length,
			contentBytes: contentSummary.bytes,
			estimatedTokens: contentSummary.estimatedTokens,
			sha256: contentSummary.sha256,
		};
	});

	const largestMessages = [...messageSummaries]
		.sort((a, b) => b.contentBytes - a.contentBytes)
		.slice(0, 5)
		.map((message) => ({ ...message }));
	const serialized = safeStringify(messages);
	return {
		messageCount: messages.length,
		roleCounts,
		totalBytes: byteLength(serialized),
		estimatedTokens: estimateTokens(byteLength(serialized)),
		sha256: hashString(serialized),
		reasoningBlockCount,
		toolResultCount,
		largestMessages,
		messages: messageSummaries,
	};
}

function parseJsonString(value: unknown): unknown {
	if (typeof value !== "string") return undefined;
	const trimmed = value.trim();
	if (!trimmed.startsWith("{") && !trimmed.startsWith("[")) return undefined;
	try {
		return JSON.parse(trimmed);
	} catch {
		return undefined;
	}
}

function extractProviderMessages(
	payloadRecord: Record<string, unknown>,
): unknown {
	if ("messages" in payloadRecord) return payloadRecord.messages;
	const body = payloadRecord.body;
	const parsedBody = parseJsonString(body);
	if (parsedBody && typeof parsedBody === "object") {
		const bodyRecord = parsedBody as Record<string, unknown>;
		if ("messages" in bodyRecord) return bodyRecord.messages;
		if ("prompt" in bodyRecord) return bodyRecord.prompt;
		if ("contents" in bodyRecord) return bodyRecord.contents;
	}
	return undefined;
}

function captureCorrelation(
	request: GatewayStreamRequest,
): Record<string, unknown> {
	const metadata =
		request.metadata && typeof request.metadata === "object"
			? request.metadata
			: {};
	return {
		...metadata,
		providerId: request.providerId,
		modelId: request.modelId,
	};
}

function safeFilePart(value: unknown): string | undefined {
	if (typeof value !== "string" && typeof value !== "number") return undefined;
	const raw = String(value).trim();
	if (!raw) return undefined;
	const safe = raw.replace(/[^a-zA-Z0-9_-]+/g, "_").replace(/^_+|_+$/g, "");
	return safe || undefined;
}

function captureIdForCorrelation(correlation: Record<string, unknown>): string {
	const explicit = safeFilePart(correlation.captureId);
	if (explicit) return explicit;
	const hash = hashString(safeStringify(correlation)).slice(0, 16);
	const runId = safeFilePart(correlation.runId);
	const iteration = safeFilePart(correlation.iteration);
	return ["cap", runId, iteration, hash].filter(Boolean).join("_");
}

function nextAttempt(captureId: string, stage: CaptureStage): number {
	const key = `${captureId}:${stage}`;
	const next = (attemptCounters.get(key) ?? 0) + 1;
	attemptCounters.set(key, next);
	return next;
}

function cleanupOldCaptures(dir: string): void {
	if (!isCleanupEnabled() || cleanupDirs.has(dir)) return;
	cleanupDirs.add(dir);
	try {
		const cutoff = Date.now() - CLEANUP_TTL_MS;
		for (const file of readdirSync(dir)) {
			if (
				!file.endsWith(CAPTURE_FILE_EXTENSION) &&
				!(
					file.includes(CAPTURE_FILE_EXTENSION) &&
					file.endsWith(CAPTURE_TMP_EXTENSION)
				)
			) {
				continue;
			}
			const path = join(dir, file);
			const stat = statSync(path);
			if (stat.mtimeMs < cutoff) {
				rmSync(path, { force: true });
			}
		}
	} catch {
		// Capture cleanup must never affect model execution.
	}
}

function writeCapture(record: Record<string, unknown>): void {
	try {
		const dir = resolveCaptureDir();
		if (!dir) return;
		mkdirSync(dir, { recursive: true });
		cleanupOldCaptures(dir);
		const correlation =
			record.correlation && typeof record.correlation === "object"
				? (record.correlation as Record<string, unknown>)
				: {};
		const captureId = captureIdForCorrelation(correlation);
		const stage =
			record.captureStage === "ai_sdk_prompt" ||
			record.captureStage === "wire_request"
				? record.captureStage
				: "ai_sdk_prompt";
		const attempt = nextAttempt(captureId, stage);
		const finalPath = join(
			dir,
			`${captureId}.${stage}.${attempt}${CAPTURE_FILE_EXTENSION}`,
		);
		const tmpPath = `${finalPath}.${process.pid}.${Date.now()}${CAPTURE_TMP_EXTENSION}`;
		writeFileSync(tmpPath, `${safeStringify({ ...record, attempt })}\n`, {
			encoding: "utf8",
			mode: 0o600,
		});
		renameSync(tmpPath, finalPath);
		if (existsSync(tmpPath)) rmSync(tmpPath, { force: true });
	} catch {
		// Provider-request capture must never affect model execution.
	}
}

export function recordProviderRequestCapture(input: {
	stage: CaptureStage;
	request: GatewayStreamRequest;
	payload: unknown;
}): void {
	try {
		const mode = readCaptureMode();
		if (mode === "off") return;
		const payloadRecord =
			input.payload && typeof input.payload === "object"
				? (input.payload as Record<string, unknown>)
				: { value: input.payload };
		const messages = extractProviderMessages(payloadRecord);
		const serializedPayload = safeStringify(input.payload);
		writeCapture({
			timestamp: new Date().toISOString(),
			captureStage: input.stage,
			mode,
			correlation: captureCorrelation(input.request),
			summary: {
				payloadBytes: byteLength(serializedPayload),
				estimatedTokens: estimateTokens(byteLength(serializedPayload)),
				sha256: hashString(serializedPayload),
				messages: summarizeMessages(messages),
			},
			...(mode === "full"
				? { payload: previewValue(input.payload, readMaxPreviewBytes()) }
				: {}),
		});
	} catch {
		// Provider-request capture must never affect model execution.
	}
}

async function readRequestBody(
	input: Parameters<typeof fetch>[0],
	init: Parameters<typeof fetch>[1],
): Promise<unknown> {
	const body = init?.body;
	if (body !== undefined && body !== null) {
		if (typeof body === "string") return body;
		if (body instanceof URLSearchParams) return body.toString();
		if (body instanceof ArrayBuffer) return Buffer.from(body).toString("utf8");
		if (ArrayBuffer.isView(body)) {
			return Buffer.from(
				body.buffer,
				body.byteOffset,
				body.byteLength,
			).toString("utf8");
		}
		return { type: body.constructor?.name ?? typeof body };
	}
	if (input instanceof Request) {
		try {
			return await input.clone().text();
		} catch {
			return { type: "Request", bodyReadable: false };
		}
	}
	return undefined;
}

export function wrapFetchForProviderRequestCapture(
	baseFetch: typeof fetch | undefined,
	request: GatewayStreamRequest,
): typeof fetch | undefined {
	if (!isWireCaptureEnabled()) {
		return baseFetch;
	}
	const delegate = baseFetch ?? globalThis.fetch;
	if (!delegate) {
		return baseFetch;
	}
	const captureFetch = (async (input, init) => {
		void readRequestBody(input, init)
			.then((body) => {
				recordProviderRequestCapture({
					stage: "wire_request",
					request,
					payload: {
						url: input instanceof Request ? input.url : String(input),
						method:
							init?.method ??
							(input instanceof Request ? input.method : undefined) ??
							"GET",
						body,
					},
				});
			})
			.catch(() => {
				// Provider-request capture must never affect model execution.
			});
		return delegate(input, init);
	}) as typeof fetch;
	const delegateWithPreconnect = delegate as typeof fetch & {
		preconnect?: (...args: unknown[]) => unknown;
	};
	if (typeof delegateWithPreconnect.preconnect === "function") {
		(
			captureFetch as typeof fetch & {
				preconnect?: (...args: unknown[]) => unknown;
			}
		).preconnect = delegateWithPreconnect.preconnect.bind(delegate);
	}
	return captureFetch;
}

import type {
	GatewayModelDefinition,
	GatewayModelSelection,
	GatewayProviderConfig,
	GatewayProviderFactory,
	GatewayProviderManifest,
	GatewayProviderMetadata,
	GatewayProviderRegistration,
	GatewayResolvedModel,
	GatewayResolvedProviderConfig,
} from "@cline/shared";

interface ProviderRecord {
	manifest: GatewayProviderManifest;
	defaults?: GatewayResolvedProviderConfig;
	createProvider?: GatewayProviderFactory;
	loadProvider?: GatewayProviderRegistration["loadProvider"];
}

interface ProviderConfigRecord extends GatewayResolvedProviderConfig {
	enabled: boolean;
	defaultModelId?: string;
	models?: readonly Omit<GatewayModelDefinition, "providerId">[];
}

function cloneManifest(
	manifest: GatewayProviderManifest,
): GatewayProviderManifest {
	return {
		...manifest,
		models: manifest.models.map((model) => ({ ...model })),
		capabilities: manifest.capabilities
			? [...manifest.capabilities]
			: undefined,
		env: manifest.env ? [...manifest.env] : undefined,
		api: manifest.api,
		apiKeyEnv: manifest.apiKeyEnv ? [...manifest.apiKeyEnv] : undefined,
		docsUrl: manifest.docsUrl,
		metadata: manifest.metadata ? { ...manifest.metadata } : undefined,
	};
}

function mergeModels(
	manifest: GatewayProviderManifest,
	config: ProviderConfigRecord | undefined,
): readonly GatewayModelDefinition[] {
	const merged = new Map<string, GatewayModelDefinition>();

	for (const model of manifest.models) {
		merged.set(model.id, { ...model });
	}

	for (const model of config?.models ?? []) {
		merged.set(model.id, {
			...model,
			providerId: manifest.id,
		});
	}

	return Array.from(merged.values());
}

function mergeProviderMetadata(
	base: GatewayProviderMetadata | undefined,
	override: GatewayProviderMetadata | undefined,
): GatewayProviderMetadata | undefined {
	// Routing metadata merges at the promptCache/reasoning branch boundary:
	// omitted branches inherit, provided branches replace in full. Route arrays
	// are intentionally not concatenated so overrides remain explicit.
	const routing =
		base?.routing || override?.routing
			? {
					...(base?.routing ?? {}),
					...(override?.routing ?? {}),
				}
			: undefined;
	const metadata: GatewayProviderMetadata = {
		...(base ?? {}),
		...(override ?? {}),
		...(routing ? { routing } : {}),
	};

	return Object.keys(metadata).length > 0 ? metadata : undefined;
}

/**
 * Resolve a regional base URL from merged provider options: `apiLine` is the
 * caller-selected line ("china" | "international") and `apiLineBaseUrls` maps
 * lines to endpoints (registered as a builtin default from the provider
 * manifest). Explicit caller base URLs always win over this resolution.
 */
function resolveApiLineBaseUrl(
	options: Record<string, unknown>,
): string | undefined {
	const apiLine = options.apiLine;
	if (apiLine !== "china" && apiLine !== "international") {
		return undefined;
	}
	const baseUrls = options.apiLineBaseUrls;
	if (typeof baseUrls !== "object" || baseUrls === null) {
		return undefined;
	}
	const baseUrl = (baseUrls as Record<string, unknown>)[apiLine];
	return typeof baseUrl === "string" && baseUrl.trim().length > 0
		? baseUrl
		: undefined;
}

function createUnregisteredModel(
	provider: GatewayProviderManifest,
	modelId: string,
): GatewayModelDefinition {
	return {
		id: modelId,
		name: modelId,
		providerId: provider.id,
	};
}

export class GatewayRegistry {
	private readonly providers = new Map<string, ProviderRecord>();
	private readonly providerConfigs = new Map<string, ProviderConfigRecord>();
	private readonly fallbackFetch?: typeof fetch;

	constructor(fetchImpl?: typeof fetch) {
		this.fallbackFetch = fetchImpl;
	}

	registerProvider(registration: GatewayProviderRegistration): void {
		if (!registration.createProvider && !registration.loadProvider) {
			throw new Error(
				`Provider "${registration.manifest.id}" must include createProvider or loadProvider.`,
			);
		}

		this.providers.set(registration.manifest.id, {
			manifest: cloneManifest(registration.manifest),
			defaults: registration.defaults
				? {
						providerId: registration.manifest.id,
						apiKey: registration.defaults.apiKey,
						apiKeyResolver: registration.defaults.apiKeyResolver,
						apiKeyEnv: registration.defaults.apiKeyEnv,
						baseUrl: registration.defaults.baseUrl,
						headers: registration.defaults.headers
							? { ...registration.defaults.headers }
							: undefined,
						timeoutMs: registration.defaults.timeoutMs,
						fetch: registration.defaults.fetch,
						options: registration.defaults.options
							? { ...registration.defaults.options }
							: undefined,
						metadata: registration.defaults.metadata
							? { ...registration.defaults.metadata }
							: undefined,
					}
				: undefined,
			createProvider: registration.createProvider,
			loadProvider: registration.loadProvider,
		});
	}

	configureProvider(config: GatewayProviderConfig): void {
		this.providerConfigs.set(config.providerId, {
			providerId: config.providerId,
			apiKey: config.apiKey,
			apiKeyResolver: config.apiKeyResolver,
			apiKeyEnv: config.apiKeyEnv,
			baseUrl: config.baseUrl,
			headers: config.headers ? { ...config.headers } : undefined,
			timeoutMs: config.timeoutMs,
			fetch: config.fetch,
			options: config.options ? { ...config.options } : undefined,
			metadata: config.metadata ? { ...config.metadata } : undefined,
			enabled: config.enabled ?? true,
			defaultModelId: config.defaultModelId,
			models: config.models?.map((model) => ({ ...model })),
		});
	}

	listProviders(): GatewayProviderManifest[] {
		return Array.from(this.providers.values())
			.map((record) => this.getManifest(record.manifest.id))
			.filter(
				(manifest): manifest is GatewayProviderManifest =>
					manifest !== undefined,
			);
	}

	listModels(providerId?: string): GatewayModelDefinition[] {
		if (providerId) {
			return [...(this.getManifest(providerId)?.models ?? [])];
		}

		return this.listProviders().flatMap((provider) =>
			provider.models.map((model) => ({ ...model })),
		);
	}

	getManifest(providerId: string): GatewayProviderManifest | undefined {
		const record = this.providers.get(providerId);
		if (!record) {
			return undefined;
		}

		const config = this.providerConfigs.get(providerId);
		if (config && !config.enabled) {
			return undefined;
		}

		const models = mergeModels(record.manifest, config);
		const defaultModelId =
			config?.defaultModelId ?? record.manifest.defaultModelId ?? models[0]?.id;

		if (!defaultModelId) {
			return undefined;
		}

		return {
			...cloneManifest(record.manifest),
			defaultModelId,
			models,
			metadata: mergeProviderMetadata(
				record.manifest.metadata,
				config?.metadata,
			),
		};
	}

	resolveModel(selection: GatewayModelSelection): GatewayResolvedModel {
		const provider = this.getManifest(selection.providerId);
		if (!provider) {
			throw new Error(
				`Unknown or disabled provider "${selection.providerId}".`,
			);
		}

		const modelId = selection.modelId ?? provider.defaultModelId;
		const model =
			provider.models.find((entry) => entry.id === modelId) ??
			createUnregisteredModel(provider, modelId);

		return {
			provider,
			model,
		};
	}

	async createProvider(providerId: string): Promise<{
		manifest: GatewayProviderManifest;
		config: GatewayResolvedProviderConfig;
		createProvider: GatewayProviderFactory;
	}> {
		const record = this.providers.get(providerId);
		if (!record) {
			throw new Error(`Unknown provider "${providerId}".`);
		}

		if (!record.createProvider) {
			const loaded = await record.loadProvider?.();
			if (!loaded?.createProvider) {
				throw new Error(`Provider "${providerId}" could not be loaded.`);
			}
			record.createProvider = loaded.createProvider;
		}

		const manifest = this.getManifest(providerId);
		if (!manifest) {
			throw new Error(`Provider "${providerId}" is disabled.`);
		}

		const config = this.providerConfigs.get(providerId);
		const metadata = mergeProviderMetadata(
			record.defaults?.metadata,
			config?.metadata,
		);
		const options = {
			...(record.defaults?.options ?? {}),
			...(config?.options ?? {}),
		};

		return {
			manifest,
			config: {
				providerId,
				apiKey: config?.apiKey ?? record.defaults?.apiKey,
				apiKeyResolver:
					config?.apiKeyResolver ?? record.defaults?.apiKeyResolver,
				apiKeyEnv: config?.apiKeyEnv ?? record.defaults?.apiKeyEnv,
				baseUrl:
					config?.baseUrl ??
					resolveApiLineBaseUrl(options) ??
					record.defaults?.baseUrl,
				headers: {
					...(record.defaults?.headers ?? {}),
					...(config?.headers ?? {}),
				},
				timeoutMs: config?.timeoutMs ?? record.defaults?.timeoutMs,
				fetch: config?.fetch ?? record.defaults?.fetch ?? this.fallbackFetch,
				options,
				metadata,
			},
			createProvider: record.createProvider,
		};
	}
}

import { describe, expect, it } from "vitest";
import { resolveProviderRequestHeaders } from "./request-headers";

function jwtWithPayload(payload: Record<string, unknown>): string {
	return `header.${Buffer.from(JSON.stringify(payload), "utf8").toString("base64url")}.sig`;
}

describe("resolveProviderRequestHeaders", () => {
	it("adds required Cline billing headers after stored, config, and session layers", () => {
		const headers = resolveProviderRequestHeaders({
			providerId: "cline",
			sessionId: "sess-1",
			source: "cli",
			defaultSource: "core",
			client: {
				name: "cline-cli",
				version: "3.0.38",
			},
			coreVersion: "0.2.0",
			headers: {
				stored: {
					"X-CLIENT-TYPE": "stored-client",
					"x-stored": "stored",
					"x-shared": "stored-loses",
				},
				config: {
					"X-Task-ID": "config-task",
					"x-config": "config",
					"x-shared": "config-wins",
				},
				session: {
					"X-CLIENT-VERSION": "session-version",
					"x-session": "session",
				},
			},
		});

		expect(headers).toMatchObject({
			"HTTP-Referer": "https://cline.bot",
			"X-Title": "Cline",
			"User-Agent": "Cline/3.0.38",
			"X-IS-MULTIROOT": "false",
			"X-CLIENT-TYPE": "cline-cli",
			"X-CLIENT-VERSION": "3.0.38",
			"X-PLATFORM": "cli",
			"X-PLATFORM-VERSION": "3.0.38",
			"X-CORE-VERSION": "0.2.0",
			"X-Task-ID": "sess-1",
			"x-config": "config",
			"x-session": "session",
			"x-shared": "config-wins",
			"x-stored": "stored",
		});
	});

	it("uses host client context for Cline billing headers when provided", () => {
		const headers = resolveProviderRequestHeaders({
			providerId: "cline-pass",
			sessionId: "sess-vscode",
			source: "core",
			defaultSource: "core",
			client: {
				name: "VSCode Extension",
				version: "9.9.9",
				platform: "Visual Studio Code",
				platformVersion: "1.103.0",
				isMultiRoot: true,
			},
			coreVersion: "0.2.0",
		});

		expect(headers).toMatchObject({
			"User-Agent": "Cline/9.9.9",
			"X-IS-MULTIROOT": "true",
			"X-CLIENT-TYPE": "VSCode Extension",
			"X-CLIENT-VERSION": "9.9.9",
			"X-PLATFORM": "Visual Studio Code",
			"X-PLATFORM-VERSION": "1.103.0",
			"X-CORE-VERSION": "0.2.0",
			"X-Task-ID": "sess-vscode",
		});
	});

	it("adds OpenAI Codex headers and derives the account id from the access token", () => {
		const token = jwtWithPayload({
			"https://api.openai.com/auth": {
				chatgpt_account_id: "acct-derived",
			},
		});

		const headers = resolveProviderRequestHeaders({
			providerId: "openai-codex",
			sessionId: "sess-codex",
			defaultSource: "cli",
			coreVersion: "0.2.0",
			openAiCodex: {
				accessToken: token,
				userAgentVersion: "3.0.38",
			},
			headers: {
				stored: {
					originator: "stored-originator",
					"x-stored": "stored",
				},
				config: {
					session_id: "config-session",
					"x-config": "config",
				},
			},
		});

		expect(headers).toMatchObject({
			originator: "cline",
			session_id: "sess-codex",
			"User-Agent": "Cline/3.0.38",
			"ChatGPT-Account-Id": "acct-derived",
			"x-config": "config",
			"x-stored": "stored",
		});
	});

	it("preserves existing precedence for providers without required headers", () => {
		expect(
			resolveProviderRequestHeaders({
				providerId: "anthropic",
				sessionId: "sess-plain",
				defaultSource: "cli",
				coreVersion: "0.2.0",
				headers: {
					stored: { "x-stored": "stored" },
					config: { "x-config": "config" },
				},
			}),
		).toEqual({ "x-config": "config" });

		expect(
			resolveProviderRequestHeaders({
				providerId: "anthropic",
				sessionId: "sess-plain",
				defaultSource: "cli",
				coreVersion: "0.2.0",
				headers: {
					stored: { "x-stored": "stored" },
					config: { "x-config": "config" },
					session: { "x-session": "session" },
				},
			}),
		).toEqual({ "x-session": "session" });
	});
});

import { decodeJwtPayload } from "@cline/shared";

export interface ProviderRequestHeaderClientContext {
	name?: string;
	version?: string;
	versionHeaderFallback?: string;
	platform?: string;
	platformVersion?: string;
	isMultiRoot?: boolean;
}

export interface ProviderRequestHeaderLayers {
	stored?: Record<string, string>;
	config?: Record<string, string>;
	session?: Record<string, string>;
}

export interface OpenAICodexRequestHeaderContext {
	accountId?: string;
	accessToken?: string;
	userAgentVersion?: string;
}

export interface ResolveProviderRequestHeadersInput {
	providerId: string;
	sessionId: string;
	source?: string;
	defaultSource: string;
	client?: ProviderRequestHeaderClientContext;
	coreVersion: string;
	openAiCodex?: OpenAICodexRequestHeaderContext;
	headers?: ProviderRequestHeaderLayers;
}

const DEFAULT_CLINE_REQUEST_HEADERS: Record<string, string> = {
	"HTTP-Referer": "https://cline.bot",
	"X-Title": "Cline",
	"X-IS-MULTIROOT": "false",
	"X-CLIENT-TYPE": "cline-sdk",
};

function isClineBillingProvider(providerId: string): boolean {
	return providerId === "cline" || providerId === "cline-pass";
}

function trimNonEmpty(value: string | undefined): string | undefined {
	const trimmed = value?.trim();
	return trimmed && trimmed.length > 0 ? trimmed : undefined;
}

function resolveSource(
	source: string | undefined,
	defaultSource: string,
): string {
	return trimNonEmpty(source) ?? defaultSource;
}

function resolveClineClientVersion(
	client: ProviderRequestHeaderClientContext | undefined,
): string {
	return (
		trimNonEmpty(client?.version) ??
		trimNonEmpty(client?.versionHeaderFallback) ??
		"unknown"
	);
}

function buildClineRequestHeaders(
	input: ResolveProviderRequestHeadersInput,
): Record<string, string> | undefined {
	if (!isClineBillingProvider(input.providerId)) {
		return undefined;
	}
	const source = resolveSource(input.source, input.defaultSource);
	const clientType = trimNonEmpty(input.client?.name) ?? `cline-${source}`;
	const clientVersion = resolveClineClientVersion(input.client);
	const platform = trimNonEmpty(input.client?.platform) ?? source;
	const platformVersion =
		trimNonEmpty(input.client?.platformVersion) ?? clientVersion;
	return {
		...DEFAULT_CLINE_REQUEST_HEADERS,
		"User-Agent": `Cline/${clientVersion}`,
		"X-IS-MULTIROOT": input.client?.isMultiRoot === true ? "true" : "false",
		"X-CLIENT-TYPE": clientType,
		"X-CLIENT-VERSION": clientVersion,
		"X-PLATFORM": platform,
		"X-PLATFORM-VERSION": platformVersion,
		"X-CORE-VERSION": input.coreVersion,
		"X-Task-ID": input.sessionId,
	};
}

function deriveOpenAICodexAccountId(
	accessToken: string | undefined,
): string | undefined {
	const payload = decodeJwtPayload(accessToken) as
		| {
				"https://api.openai.com/auth"?: { chatgpt_account_id?: string };
				organizations?: Array<{ id?: string }>;
				chatgpt_account_id?: string;
		  }
		| undefined;
	const authAccountId =
		payload?.["https://api.openai.com/auth"]?.chatgpt_account_id;
	if (typeof authAccountId === "string" && authAccountId.length > 0) {
		return authAccountId;
	}
	const orgAccountId = payload?.organizations?.[0]?.id;
	if (typeof orgAccountId === "string" && orgAccountId.length > 0) {
		return orgAccountId;
	}
	const rootAccountId = payload?.chatgpt_account_id;
	if (typeof rootAccountId === "string" && rootAccountId.length > 0) {
		return rootAccountId;
	}
	return undefined;
}

function buildOpenAICodexRequestHeaders(
	input: ResolveProviderRequestHeadersInput,
): Record<string, string> | undefined {
	if (input.providerId !== "openai-codex") {
		return undefined;
	}
	const accountId =
		trimNonEmpty(input.openAiCodex?.accountId) ??
		deriveOpenAICodexAccountId(input.openAiCodex?.accessToken);
	return {
		originator: "cline",
		session_id: input.sessionId,
		"User-Agent": `Cline/${trimNonEmpty(input.openAiCodex?.userAgentVersion) ?? "1.0.0"}`,
		...(accountId ? { "ChatGPT-Account-Id": accountId } : {}),
	};
}

function resolveRequiredProviderHeaders(
	input: ResolveProviderRequestHeadersInput,
): Record<string, string> | undefined {
	return (
		buildClineRequestHeaders(input) ?? buildOpenAICodexRequestHeaders(input)
	);
}

function resolveDefaultProviderHeaders(
	headers: ProviderRequestHeaderLayers | undefined,
): Record<string, string> | undefined {
	return headers?.session ?? headers?.config ?? headers?.stored;
}

export function resolveProviderRequestHeaders(
	input: ResolveProviderRequestHeadersInput,
): Record<string, string> | undefined {
	const requiredHeaders = resolveRequiredProviderHeaders(input);
	if (requiredHeaders) {
		return {
			...(input.headers?.stored ?? {}),
			...(input.headers?.config ?? {}),
			...(input.headers?.session ?? {}),
			...requiredHeaders,
		};
	}
	const headers = resolveDefaultProviderHeaders(input.headers);
	return headers ? { ...headers } : undefined;
}

import type {
	GatewayModelRoute,
	GatewayProviderContext,
	GatewayProviderManifest,
} from "@cline/shared";
import { describe, expect, it } from "vitest";
import {
	isAnthropicCompatibleModel,
	isAnthropicCompatibleModelId,
	isClaudeModelId,
	isGlmModel,
	isQwenModel,
	resolveClaudeThinkingEra,
} from "../model-facts";
import {
	applyPromptCacheToLastTextPart,
	resolveAnthropicReasoningRequestPolicy,
	resolvePromptCacheRoute,
	shouldApplyPromptCache,
} from "./anthropic-compatible";

function makeProvider(
	metadata?: GatewayProviderManifest["metadata"],
): GatewayProviderManifest {
	return {
		id: "test-provider",
		name: "Test Provider",
		defaultModelId: "default-model",
		models: [
			{
				id: "default-model",
				name: "Default Model",
				providerId: "test-provider",
				capabilities: ["text"],
			},
		],
		metadata,
	};
}

function makeContext(
	family?: string,
	metadata?: GatewayProviderManifest["metadata"],
	capabilities?: GatewayProviderContext["model"]["capabilities"],
): GatewayProviderContext {
	return {
		provider: makeProvider(metadata),
		model: {
			id: "model-id",
			name: "Model",
			providerId: "test-provider",
			capabilities,
			metadata: family ? { family } : undefined,
		},
		config: {
			providerId: "test-provider",
		},
	};
}

function metadataWithRouting(options: {
	promptCacheRoutes?: GatewayModelRoute[];
	reasoningRoutes?: GatewayModelRoute[];
}): GatewayProviderManifest["metadata"] {
	return {
		routing: {
			...(options.promptCacheRoutes
				? {
						promptCache: {
							format: "anthropic-cache-control",
							routes: options.promptCacheRoutes,
						},
					}
				: {}),
			...(options.reasoningRoutes
				? {
						reasoning: {
							format: "anthropic-thinking",
							routes: options.reasoningRoutes,
						},
					}
				: {}),
		},
	};
}

describe("anthropic-compatible routing helpers", () => {
	it("matches family metadata case-insensitively", () => {
		expect(
			isAnthropicCompatibleModel({
				family: "Claude-Sonnet",
			}),
		).toBe(true);
		expect(
			isAnthropicCompatibleModel({
				family: "Anthropic",
			}),
		).toBe(true);
	});

	it("falls back to model id when family is whitespace-only", () => {
		expect(
			isAnthropicCompatibleModel({
				family: "   ",
				modelId: "anthropic.claude-sonnet-4-6",
			}),
		).toBe(true);
	});

	it("recognizes bedrock and sap-style anthropic model ids", () => {
		expect(isAnthropicCompatibleModelId("anthropic.claude-sonnet-4-6")).toBe(
			true,
		);
		expect(
			isAnthropicCompatibleModelId("eu.anthropic.claude-opus-4-6-v1"),
		).toBe(true);
		expect(isAnthropicCompatibleModelId("anthropic--claude-3.5-sonnet")).toBe(
			true,
		);
		expect(isAnthropicCompatibleModelId("custom/anthropic-alias")).toBe(true);
	});

	it("does not match unrelated model ids", () => {
		expect(isAnthropicCompatibleModelId("openai/gpt-5.4")).toBe(false);
		expect(isAnthropicCompatibleModelId("gemini-3.1-flash-lite-preview")).toBe(
			false,
		);
	});

	it("keeps Qwen outside Anthropic compatibility and routes cache by provider metadata", () => {
		expect(isAnthropicCompatibleModelId("qwen/qwen3.6-plus")).toBe(false);
		expect(isQwenModel({ modelId: "qwen/qwen3.6-plus" })).toBe(true);
		expect(isQwenModel({ modelId: "alibaba/qwen3.6-plus" })).toBe(true);
		expect(isQwenModel({ family: "qwen" })).toBe(true);
		expect(isQwenModel({ family: "qwen3.6" })).toBe(true);
		expect(isQwenModel({ modelId: "anthropic/claude-sonnet-4.6" })).toBe(false);
		expect(
			resolvePromptCacheRoute(
				{
					providerId: "test-provider",
					modelId: "qwen/qwen3.6-plus",
					messages: [],
				},
				makeContext(),
			),
		).toBeUndefined();
		expect(
			resolvePromptCacheRoute(
				{
					providerId: "test-provider",
					modelId: "alibaba/qwen3.6-plus",
					messages: [],
				},
				makeContext(
					"qwen3.6",
					metadataWithRouting({
						promptCacheRoutes: [
							{
								matcher: "model-family",
								family: "qwen",
								requiredCapability: "prompt-cache",
							},
						],
					}),
					["text", "prompt-cache"],
				),
			),
		).toEqual({
			matcher: "model-family",
			family: "qwen",
			requiredCapability: "prompt-cache",
		});
		expect(
			resolvePromptCacheRoute(
				{
					providerId: "test-provider",
					modelId: "alibaba/qwen3.6-plus",
					messages: [],
				},
				makeContext(
					"qwen",
					metadataWithRouting({
						promptCacheRoutes: [
							{
								matcher: "model-family",
								family: "qwen",
								requiredCapability: "prompt-cache",
							},
						],
					}),
					["text", "prompt-cache"],
				),
			),
		).toEqual({
			matcher: "model-family",
			family: "qwen",
			requiredCapability: "prompt-cache",
		});
		expect(
			resolvePromptCacheRoute(
				{
					providerId: "test-provider",
					modelId: "alibaba/qwen3.6-plus",
					messages: [],
				},
				makeContext(
					"qwen",
					metadataWithRouting({
						promptCacheRoutes: [
							{
								matcher: "model-family",
								family: "qwen",
								requiredCapability: "prompt-cache",
							},
						],
					}),
					["text"],
				),
			),
		).toBeUndefined();
		expect(
			resolvePromptCacheRoute(
				{
					providerId: "test-provider",
					modelId: "qwen/qwen3.6-plus",
					messages: [],
				},
				makeContext(
					undefined,
					metadataWithRouting({
						promptCacheRoutes: [
							{ matcher: "model-id", modelId: "qwen/qwen3.6-plus" },
						],
					}),
				),
			),
		).toEqual({ matcher: "model-id", modelId: "qwen/qwen3.6-plus" });
	});

	it("keeps Vertex Claude detection scoped to model id", () => {
		expect(isClaudeModelId("anthropic.claude-sonnet-4-6")).toBe(true);
		expect(isClaudeModelId("anthropic-vertex-experimental")).toBe(false);
	});

	it("matches GLM when either family or model id contains glm", () => {
		expect(
			isGlmModel({ modelId: "provider/glm-4.6" }, makeContext("other-family")),
		).toBe(true);
		expect(
			isGlmModel({ modelId: "provider/other-model" }, makeContext("zai-glm")),
		).toBe(true);
	});

	it("requires an explicit prompt-cache route", () => {
		expect(
			shouldApplyPromptCache(
				{
					providerId: "test-provider",
					modelId: "anthropic.claude-sonnet-4-5",
					messages: [],
				},
				makeContext(
					undefined,
					metadataWithRouting({
						promptCacheRoutes: [{ matcher: "anthropic-compatible" }],
					}),
				),
			),
		).toBe(true);

		expect(
			shouldApplyPromptCache(
				{
					providerId: "test-provider",
					modelId: "anthropic.claude-sonnet-4-5",
					messages: [],
				},
				makeContext(),
			),
		).toBe(false);

		expect(
			shouldApplyPromptCache(
				{
					providerId: "test-provider",
					modelId: "openai/gpt-5.4",
					messages: [],
				},
				makeContext(
					undefined,
					metadataWithRouting({
						promptCacheRoutes: [{ matcher: "anthropic-compatible" }],
					}),
				),
			),
		).toBe(false);
	});

	it("honors legacy promptCacheStrategy when routing metadata is absent", () => {
		const request = {
			providerId: "test-provider",
			modelId: "anthropic/claude-3.5-sonnet",
			messages: [],
		};
		const context = makeContext(undefined, {
			promptCacheStrategy: "anthropic-automatic",
		});

