function makeContext(options?: {
	metadata?: GatewayProviderManifest["metadata"];
	family?: string;
}): GatewayProviderContext {
	return {
		provider: {
			id: "bedrock",
			name: "AWS Bedrock",
			defaultModelId: "default-model",
			models: [],
			metadata: options?.metadata ?? BEDROCK_ROUTING_METADATA,
		},
		model: {
			id: "model-id",
			name: "Model",
			providerId: "bedrock",
			metadata: options?.family ? { family: options.family } : undefined,
		},
		config: {
			providerId: "bedrock",
		},
	};
}

function makeRequest(modelId: string): GatewayStreamRequest {
	return {
		providerId: "bedrock",
		modelId,
		messages: [],
	};
}

describe("bedrock cache-point routing", () => {
	it("resolves the route for anthropic-compatible bedrock model ids", () => {
		const request = makeRequest("global.anthropic.claude-sonnet-4-6");
		expect(resolveBedrockCachePointRoute(request, makeContext())).toEqual({
			matcher: "anthropic-compatible",
		});
		expect(shouldApplyBedrockCachePoint(request, makeContext())).toBe(true);
	});

	it("does not resolve for non-anthropic bedrock models", () => {
		const request = makeRequest("minimax.minimax-m2.5");
		expect(
			resolveBedrockCachePointRoute(request, makeContext()),
		).toBeUndefined();
		expect(shouldApplyBedrockCachePoint(request, makeContext())).toBe(false);
	});

	it("does not resolve for anthropic-cache-control metadata", () => {
		const request = makeRequest("anthropic.claude-sonnet-4-6");
		const context = makeContext({
			metadata: {
				routing: {
					promptCache: {
						format: "anthropic-cache-control",
						routes: [{ matcher: "anthropic-compatible" }],
					},
				},
			},
		});
		expect(shouldApplyBedrockCachePoint(request, context)).toBe(false);
	});

	it("resolves through family metadata when the model id is an alias", () => {
		const request = makeRequest("my-claude-alias");
		expect(
			shouldApplyBedrockCachePoint(
				request,
				makeContext({ family: "claude-sonnet" }),
			),
		).toBe(true);
	});
});

describe("applyBedrockCachePointToLastUserMessage", () => {
	it("attaches a message-level cachePoint marker to the last user message", () => {
		const messages: Array<Record<string, unknown>> = [
			{ role: "user", content: [{ type: "text", text: "first" }] },
			{ role: "assistant", content: [{ type: "text", text: "answer" }] },
			{ role: "user", content: [{ type: "text", text: "second" }] },
		];

		applyBedrockCachePointToLastUserMessage(messages);

		expect(messages[0]).not.toHaveProperty("providerOptions");
		expect(messages[1]).not.toHaveProperty("providerOptions");
		expect(messages[2].providerOptions).toEqual({
			bedrock: { cachePoint: { type: "default" } },
		});
	});

	it("preserves existing message provider options", () => {
		const messages: Array<Record<string, unknown>> = [
			{
				role: "user",
				content: [{ type: "text", text: "hello" }],
				providerOptions: { other: { keep: true } },
			},
		];

		applyBedrockCachePointToLastUserMessage(messages);

		expect(messages[0].providerOptions).toEqual({
			other: { keep: true },
			bedrock: { cachePoint: { type: "default" } },
		});
	});

	it("is a no-op when there is no user message", () => {
		const messages: Array<Record<string, unknown>> = [
			{ role: "assistant", content: [{ type: "text", text: "answer" }] },
		];

		applyBedrockCachePointToLastUserMessage(messages);

		expect(messages[0]).not.toHaveProperty("providerOptions");
	});
});

import type {
	GatewayModelRoute,
	GatewayProviderContext,
	GatewayProviderMetadata,
	GatewayStreamRequest,
} from "@cline/shared";
import { modelRouteMatches, resolveModelFamily } from "../model-facts";

/**
 * Bedrock's Converse API expresses prompt-cache checkpoints as dedicated
 * `cachePoint` content blocks. `@ai-sdk/amazon-bedrock` only emits them from
 * `providerOptions.bedrock.cachePoint` markers and silently drops the
 * Anthropic `cache_control` dialect, so Bedrock needs its own prompt-cache
 * wire format.
 */
export const BEDROCK_ROUTING_METADATA: GatewayProviderMetadata = {
	routing: {
		promptCache: {
			format: "bedrock-cache-point",
			routes: [{ matcher: "anthropic-compatible" }],
		},
		reasoning: {
			format: "anthropic-thinking",
			routes: [{ matcher: "anthropic-compatible" }],
		},
	},
};

export function resolveBedrockCachePointRoute(
	request: GatewayStreamRequest,
	context: GatewayProviderContext,
): GatewayModelRoute | undefined {
	const promptCache = context.provider.metadata?.routing?.promptCache;
	if (promptCache?.format !== "bedrock-cache-point") {
		return undefined;
	}

	return promptCache.routes.find((route) =>
		modelRouteMatches(route, {
			modelId: request.modelId,
			family: resolveModelFamily(context),
			capabilities: context.model.capabilities,
		}),
	);
}

export function shouldApplyBedrockCachePoint(
	request: GatewayStreamRequest,
	context: GatewayProviderContext,
): boolean {
	return resolveBedrockCachePointRoute(request, context) !== undefined;
}

export function createBedrockCachePointProviderOptions() {
	return {
		bedrock: { cachePoint: { type: "default" as const } },
	};
}

/**
 * Attach a message-level cache-point marker to the last user message. The
 * Bedrock message converter appends the `cachePoint` block after that
 * message's content, caching the whole prefix (tools, system, and history)
 * up to it — mirroring the Anthropic writer's checkpoint placement.
 */
export function applyBedrockCachePointToLastUserMessage(
	messages: Array<Record<string, unknown>>,
): void {
	for (let i = messages.length - 1; i >= 0; i--) {
		const message = messages[i];
		if (message?.role !== "user") {
			continue;
		}
		message.providerOptions = {
			...(message.providerOptions as Record<string, unknown> | undefined),
			...createBedrockCachePointProviderOptions(),
		};
		return;
	}
}

import type {
	GatewayProviderContext,
	GatewayStreamRequest,
} from "@cline/shared";
import {
	buildAnthropicCompatibleReasoningOptions,
	resolveAnthropicReasoningRequestPolicy,
	resolveReasoningRoute,
	shouldApplyPromptCache,
} from "./anthropic-compatible";
import type {
	AiSdkProviderOptionsTarget,
	ProviderOptionSuppression,
} from "./provider-options-types";
import { createEphemeralCacheControl } from "./utils";

export function buildOpenAINativeProviderOptions(): Record<string, unknown> {
	return { truncation: "auto" };
}

function buildCompatibleThinkingOptions(options: {
	request: GatewayStreamRequest;
	context: GatewayProviderContext;
	suppressions: ProviderOptionSuppression;
}): Record<string, unknown> {
	const { request, context, suppressions } = options;
	if (suppressions.genericThinking) {
		return {};
	}
	if (request.reasoning?.enabled !== true) {
		return {};
	}

	const anthropicPolicy = resolveAnthropicReasoningRequestPolicy(
		request,
		context,
	);
	const hasAnthropicReasoningRoute =
		resolveReasoningRoute(request, context) !== undefined;
	if (
		!hasAnthropicReasoningRoute ||
		anthropicPolicy.kind !== "anthropic-adaptive"
	) {
		return {};
	}
	return { thinking: { type: "adaptive" } };
}

export function buildCompatibleProviderOptions(options: {
	request: GatewayStreamRequest;
	context: GatewayProviderContext;
	target: AiSdkProviderOptionsTarget;
	suppressions: ProviderOptionSuppression;
}): Record<string, unknown> {
	const { request, context, target, suppressions } = options;
	const hasPromptCacheRoute = shouldApplyPromptCache(request, context);
	const reasoning = buildAnthropicCompatibleReasoningOptions(request, context);
	const promptCache = hasPromptCacheRoute ? createEphemeralCacheControl() : {};

	return {
		...(target === "openai-compatible" ? { strictJsonSchema: false } : {}),
		...buildCompatibleThinkingOptions({ request, context, suppressions }),
		...(reasoning ? { reasoning } : {}),
		...promptCache,
		...(["openai", "openai-native"].includes(request.providerId)
			? buildOpenAINativeProviderOptions()
			: {}),
	};
}

import type {
	GatewayProviderContext,
	GatewayProviderMetadata,
	GatewayStreamRequest,
} from "@cline/shared";
import { isGlmModel } from "../model-facts";
import type { ProviderOptionsPatch } from "./utils";

/**
 * GLM thinking routing.
 *
 * Native Z.AI uses `thinking: { type: "enabled" | "disabled" }`.
 * Routed OpenAI-compatible GLM endpoints should use the generic `reasoning`
 * control shape. The return value is a normal provider-options patch so the
 * composer can rely on merge order instead of out-of-band flags.
 */

export const GLM_THINKING_ROUTING_METADATA: GatewayProviderMetadata = {
	routing: {
		reasoning: {
			format: "glm-thinking",
			routes: [
				{ matcher: "model-family", family: "glm" },
				{ matcher: "model-family", family: "glm-air" },
				{ matcher: "model-family", family: "glm-flash" },
			],
		},
	},
};

function buildNativeZaiThinkingOptions(request: GatewayStreamRequest) {
	if (request.reasoning?.enabled === undefined) {
		return undefined;
	}
	return {
		thinking: {
			type: request.reasoning.enabled ? "enabled" : "disabled",
		},
	};
}

function buildRoutedGlmReasoningOptions(request: GatewayStreamRequest) {
	if (request.reasoning?.enabled === true) {
		return {
			reasoning: {
				enabled: true,
			},
		};
	}
	if (request.reasoning?.enabled === false) {
		return {
			reasoning: {
				exclude: true,
			},
		};
	}
	return undefined;
}

export function buildNativeGlmThinkingProviderOptionsPatch(
	request: GatewayStreamRequest,
	providerOptionsKey: string,
): ProviderOptionsPatch | undefined {
	// Native Z.AI GLM endpoints expect `thinking.type`; they do not accept the
	// routed `reasoning.enabled` / `reasoning.exclude` shape.
	const nativeThinking = buildNativeZaiThinkingOptions(request);
	return nativeThinking
		? {
				openaiCompatible: nativeThinking,
				[request.providerId]: nativeThinking,
				...(providerOptionsKey !== request.providerId
					? { [providerOptionsKey]: nativeThinking }
					: {}),
			}
		: undefined;
}

export function buildRoutedGlmReasoningProviderOptionsPatch(
	request: GatewayStreamRequest,
	context: GatewayProviderContext,
	providerOptionsKey: string,
	options?: { includeProviderBuckets?: boolean },
): ProviderOptionsPatch | undefined {
	// Routed GLM endpoints stay OpenAI-compatible and use the generic
	// `reasoning` include/exclude shape instead of native Z.AI `thinking.type`.
	if (!isGlmModel(request, context)) {
		return undefined;
	}

	const routed = buildRoutedGlmReasoningOptions(request);
	if (!routed) {
		return undefined;
	}

	return {
		openaiCompatible: routed,
		...(options?.includeProviderBuckets === false
			? {}
			: {
					[request.providerId]: routed,
					...(providerOptionsKey !== request.providerId
						? { [providerOptionsKey]: routed }
						: {}),
				}),
	};
}

