			makeContext({
				providerId: "fireworks",
				modelId: "accounts/fireworks/models/kimi-k3",
				reasoningOptions,
			}),
		);
		if (resolvePortableReasoning(gatewayRequest)) {
			expect(result.fireworks).not.toHaveProperty("reasoningEffort");
