import type {
	GatewayProviderContext,
	GatewayStreamRequest,
} from "@cline/shared";
import { buildAnthropicProviderOptions } from "./anthropic-compatible";
import { buildCompatibleProviderOptions } from "./generic-compatible";
import { withoutPortableReasoning } from "./portable-reasoning";
import {
	buildProviderOptionRulePatches,
	matchProviderOptionRules,
	PROVIDER_OPTION_RULES,
	resolveProviderOptionSuppressions,
} from "./provider-option-rules";
import {
	type AiSdkProviderOptionsTarget,
	inferProviderOptionsTarget,
	type ProviderOptionMatchInput,
} from "./provider-options-types";
import { normalizeReasoningRequest } from "./reasoning-options";
import { type ProviderOptionsPatch, toProviderOptionsKey } from "./utils";

export type { AiSdkProviderOptionsTarget } from "./provider-options-types";
export type { ProviderOptionsPatch } from "./utils";

/**
 * Merge patches in order. Later patches override earlier ones per bucket key;
 * nested object values are replaced, not deep-merged.
 */
export function mergeProviderOptionPatches(
	patches: ReadonlyArray<ProviderOptionsPatch | undefined>,
): Record<string, unknown> {
	const result: Record<string, Record<string, unknown>> = {};
	for (const patch of patches) {
		if (!patch) {
			continue;
		}
		for (const [bucket, options] of Object.entries(patch)) {
			result[bucket] = { ...(result[bucket] ?? {}), ...options };
		}
	}
	return result;
}

function buildBaseProviderOptionsPatch(
	compatibleOptions: Record<string, unknown>,
	anthropicOptions: Record<string, unknown>,
): ProviderOptionsPatch {
	return {
		anthropic: anthropicOptions,
		openaiCompatible: compatibleOptions,
	};
}

/**
 * Compose AI SDK `providerOptions` from named provider/model-family rules.
 *
 * The rule table in `provider-option-rules.ts` is the behavior matrix for
 * special providers and model families. Keep the composer boring: build shared
 * buckets once, then merge ordered rule patches.
 *
 * Routing ownership boundary:
 * - Gateway model capabilities say what a model can do, such as reasoning.
 * - Model metadata records stable known-model facts, such as
 *   `reasoningDefaultOn`.
 * - Provider metadata records stable provider policy, such as prompt caching.
 * - Provider-option rules encode only non-portable request intent into
 *   provider wire formats, such as exact budgets and native toggle objects.
 */
export function composeAiSdkProviderOptions(
	request: GatewayStreamRequest,
	context: GatewayProviderContext,
	target: AiSdkProviderOptionsTarget = inferProviderOptionsTarget(
		request.providerId,
	),
): Record<string, unknown> {
	const normalizedRequest = normalizeReasoningRequest(
		withoutPortableReasoning(request),
		context,
	);
	const providerOptionsKey = toProviderOptionsKey(normalizedRequest.providerId);
	const matchInput: ProviderOptionMatchInput = {
		request: normalizedRequest,
		context,
		providerOptionsKey,
		target,
	};
	const matchedRules = matchProviderOptionRules(
		PROVIDER_OPTION_RULES,
		matchInput,
	);
	const suppressions = resolveProviderOptionSuppressions(matchedRules);
	const compatibleOptions = buildCompatibleProviderOptions({
		request: normalizedRequest,
		context,
		target,
		suppressions,
	});
	const anthropicOptions = buildAnthropicProviderOptions(
		normalizedRequest,
		context,
	);
	const buildInput = {
		...matchInput,
		compatibleOptions,
		anthropicOptions,
		suppressions,
	};

	return mergeProviderOptionPatches([
		buildBaseProviderOptionsPatch(compatibleOptions, anthropicOptions),
		...buildProviderOptionRulePatches(matchedRules, buildInput),
	]);
}

import type {
	GatewayProviderContext,
	GatewayStreamRequest,
} from "@cline/shared";
import { DEFAULT_GATEWAY_MAX_OUTPUT_TOKENS } from "../gateway";
import { isPositiveFiniteNumber } from "../utils";

// OpenRouter separates total output limits (`max_tokens` / `max_output_tokens`)
// from `reasoning.max_tokens`, which caps only the reasoning-token portion.
// Sources:
// - https://openrouter.ai/docs/api/reference/parameters
// - https://openrouter.ai/docs/api/reference/responses/reasoning
const OPENROUTER_REASONING_BUDGET_FRACTION = 0.6;

export function hasReasoningControls(
	reasoning: GatewayStreamRequest["reasoning"],
): boolean {
	return (
		reasoning?.enabled !== undefined ||
		typeof reasoning?.budgetTokens === "number"
	);
}

function resolveOpenRouterReasoningMaxTokens(
	request: GatewayStreamRequest,
	context?: GatewayProviderContext,
): number {
	const outputMaxTokens = isPositiveFiniteNumber(request.maxTokens)
		? request.maxTokens
		: isPositiveFiniteNumber(context?.model.maxOutputTokens)
			? context.model.maxOutputTokens
			: DEFAULT_GATEWAY_MAX_OUTPUT_TOKENS;
	return Math.max(
		1,
		Math.floor(outputMaxTokens * OPENROUTER_REASONING_BUDGET_FRACTION),
	);
}

export function buildOpenRouterReasoningOptions(
	request: GatewayStreamRequest,
	context?: GatewayProviderContext,
): Record<string, unknown> | undefined {
	const reasoning = request.reasoning;
	if (!hasReasoningControls(reasoning)) {
		return undefined;
	}

	if (reasoning?.enabled === false) {
		return { effort: "none" };
	}

	// AI SDK `maxOutputTokens` still caps the whole response. This provider option
	// reserves room within that response by capping OpenRouter reasoning tokens.
	// Preserve explicit reasoning budgets when present; otherwise derive the cap
	// from the resolved request budget, model catalog output limit, or default.
	if (typeof reasoning?.budgetTokens === "number") {
		return { max_tokens: reasoning.budgetTokens };
	}

	if (reasoning?.enabled === true) {
		return {
			enabled: true,
			max_tokens: resolveOpenRouterReasoningMaxTokens(request, context),
		};
	}

	return undefined;
}

import type {
	GatewayProviderContext,
	GatewayStreamRequest,
	ModelReasoningOption,
} from "@cline/shared";
import { describe, expect, it } from "vitest";
import { normalizeReasoningRequest } from "./reasoning-options";

function makeRequest(
	reasoning: GatewayStreamRequest["reasoning"],
	overrides: Partial<GatewayStreamRequest> = {},
): GatewayStreamRequest {
	return {
		providerId: "test",
		modelId: "test-model",
		messages: [],
		maxTokens: 10_000,
		reasoning,
		...overrides,
	};
}

function makeContext(
	reasoningOptions: readonly ModelReasoningOption[] | undefined,
	options?: {
		modelId?: string;
		metadata?: GatewayProviderContext["provider"]["metadata"];
	},
): GatewayProviderContext {
	const modelId = options?.modelId ?? "test-model";
	return {
		provider: {
			id: "test",
			name: "Test",
			defaultModelId: modelId,
			models: [],
			metadata: options?.metadata,
		},
		model: {
			id: modelId,
			name: "Test model",
			providerId: "test",
			maxOutputTokens: 10_000,
			reasoningOptions,
		},
		config: { providerId: "test" },
	};
}

describe("normalizeReasoningRequest", () => {
	it("omits controls for an explicitly empty models.dev option list", () => {
		expect(
			normalizeReasoningRequest(
				makeRequest({ enabled: true, effort: "max" }),
				makeContext([]),
			).reasoning,
		).toBeUndefined();
	});

	it("maps effort to the nearest advertised value, preferring higher on ties", () => {
		const context = makeContext([{ type: "effort", values: ["low", "high"] }]);
		expect(
			normalizeReasoningRequest(makeRequest({ effort: "medium" }), context)
				.reasoning,
		).toEqual({ enabled: undefined, effort: "high", budgetTokens: undefined });
	});

	it("emits only enabled state for toggle-only models", () => {
		expect(
			normalizeReasoningRequest(
				makeRequest({ effort: "max" }),
				makeContext([{ type: "toggle" }]),
			).reasoning,
		).toEqual({ enabled: true });
	});

	it("preserves an enabled request for a provider-default effort control", () => {
		expect(
			normalizeReasoningRequest(
				makeRequest({ enabled: true }),
				makeContext([{ type: "effort", values: ["none", "default"] }]),
			).reasoning,
		).toEqual({ enabled: true });
	});

	it("selects the nearest advertised effort when enabled is the only input", () => {
		expect(
			normalizeReasoningRequest(
				makeRequest({ enabled: true }),
				makeContext([{ type: "effort", values: ["high"] }]),
			).reasoning,
		).toEqual({
			enabled: undefined,
			effort: "high",
			budgetTokens: undefined,
		});
	});

	it("derives and clamps a budget for budget-controlled models", () => {
		const context = makeContext([
			{ type: "budget_tokens", min: 512, max: 4096 },
		]);
		expect(
			normalizeReasoningRequest(makeRequest({ effort: "high" }), context)
				.reasoning,
		).toEqual({ enabled: true, budgetTokens: 4096 });
		expect(
			normalizeReasoningRequest(makeRequest({ budgetTokens: 128 }), context)
				.reasoning,
		).toEqual({ enabled: true, budgetTokens: 512 });
	});

	it("reserves output headroom only when the model matches an Anthropic reasoning route", () => {
		const metadata: GatewayProviderContext["provider"]["metadata"] = {
			routing: {
				reasoning: {
					format: "anthropic-thinking",
					routes: [{ matcher: "anthropic-compatible" }],
				},
			},
		};
		const options: ModelReasoningOption[] = [
			{ type: "budget_tokens", min: 128, max: 32_768 },
		];

		expect(
			normalizeReasoningRequest(
				makeRequest(
					{ budgetTokens: 128 },
					{ modelId: "gemini-2.5-pro", maxTokens: 64 },
				),
				makeContext(options, { modelId: "gemini-2.5-pro", metadata }),
			).reasoning,
		).toEqual({ enabled: true, budgetTokens: 128 });

		expect(
			normalizeReasoningRequest(
				makeRequest(
					{ budgetTokens: 4096 },
					{ modelId: "claude-sonnet-4-5", maxTokens: 2048 },
				),
				makeContext(options, {
					modelId: "claude-sonnet-4-5",
					metadata,
				}),
			).reasoning,
		).toEqual({ enabled: true, budgetTokens: 2047 });
	});

	it("does not invent an off control when models.dev does not advertise one", () => {
		expect(
			normalizeReasoningRequest(
				makeRequest({ enabled: false }),
				makeContext([{ type: "effort", values: ["low", "high"] }]),
			).reasoning,
		).toBeUndefined();
	});

	it("ignores Cline Fable's advertised off control because backend reasoning is mandatory", () => {
		const controls: ModelReasoningOption[] = [
			{ type: "toggle" },
			{ type: "effort", values: ["low", "medium", "high", "xhigh"] },
		];
		const context = makeContext(controls, {
			modelId: "anthropic/claude-fable-5",
		});

		expect(
			normalizeReasoningRequest(
				makeRequest(
					{ enabled: false },
					{
						providerId: "cline",
						modelId: "anthropic/claude-fable-5",
					},
				),
				context,
			).reasoning,
		).toBeUndefined();
		expect(
			normalizeReasoningRequest(
				makeRequest(
					{ enabled: false },
					{
						providerId: "vercel-ai-gateway",
						modelId: "anthropic/claude-fable-5",
					},
				),
				context,
			).reasoning,
		).toEqual({ enabled: false });
	});

	it("uses conservative effort values for custom models without metadata", () => {
		expect(
			normalizeReasoningRequest(
				makeRequest({ effort: "max" }),
				makeContext(undefined),
			).reasoning?.effort,
		).toBe("high");
	});
});

import {
	type GatewayProviderContext,
	type GatewayStreamRequest,
	isClineProvider,
	type ModelReasoningOption,
	resolveReasoningBudgetFromRatio,
} from "@cline/shared";
import {
	getModelReasoningControls,
	isClaudeFableModelId,
	normalizeReasoningEffort,
	providerReasoningRouteMatches,
} from "../model-facts";

function clampBudget(
	budgetTokens: number,
	option: Extract<ModelReasoningOption, { type: "budget_tokens" }>,
	maximum = Number.MAX_SAFE_INTEGER,
): number {
	if (budgetTokens === -1 && option.min === -1) {
		return -1;
	}

	const minimum = Math.max(option.min ?? 0, 0);
	const cappedMaximum = Math.min(
		option.max ?? Number.MAX_SAFE_INTEGER,
		maximum,
	);
	return Math.min(Math.max(Math.floor(budgetTokens), minimum), cappedMaximum);
}

/**
 * Normalize abstract reasoning intent against the provider/model controls
 * advertised by models.dev. Provider adapters remain responsible only for
 * translating the normalized request into their wire shape.
 */
export function normalizeReasoningRequest(
	request: GatewayStreamRequest,
	context: GatewayProviderContext,
): GatewayStreamRequest {
	const reasoning = request.reasoning;
	if (!reasoning) {
		return request;
	}

	// Cline routes Claude through an OpenRouter-compatible backend. Vercel's
	// catalog advertises a toggle for Fable 5, but Fable reasoning is mandatory
	// and the backend rejects an explicit disable. Treat "off" as unsupported
	// and let the model keep its mandatory default.
	if (
		reasoning.enabled === false &&
		isClineProvider(request.providerId) &&
		isClaudeFableModelId(request.modelId)
	) {
		return { ...request, reasoning: undefined };
	}

	const options = context.model.reasoningOptions;
	if (options === undefined) {
		const modelId = request.modelId.toLowerCase();
		if (
			reasoning.enabled === false &&
			(isClaudeFableModelId(modelId) ||
				modelId.includes("stepfun/step-3.7-flash"))
		) {
			return { ...request, reasoning: undefined };
		}
		// Custom/unlisted models get only broadly supported effort values.
		const effort = reasoning.effort
			? reasoning.effort === "minimal"
				? "low"
				: reasoning.effort === "xhigh" || reasoning.effort === "max"
					? "high"
					: reasoning.effort
			: undefined;
		return {
			...request,
			reasoning: { ...reasoning, effort },
		};
	}

	// models.dev uses an explicitly empty list for reasoning models with no
	// advertised user-facing control.
	if (options.length === 0) {
		return { ...request, reasoning: undefined };
	}

	const controls = getModelReasoningControls(options);
	if (!controls) {
		return { ...request, reasoning: undefined };
	}

	if (reasoning.enabled === false) {
		return controls.supportsOff
			? { ...request, reasoning: { enabled: false } }
			: { ...request, reasoning: undefined };
	}

	const hasExplicitBudget = typeof reasoning.budgetTokens === "number";
	const effort = reasoning.effort
		? normalizeReasoningEffort(reasoning.effort, controls.efforts)
		: reasoning.enabled === true &&
				!hasExplicitBudget &&
				!controls.supportsDefault
			? normalizeReasoningEffort("medium", controls.efforts)
			: undefined;
	const isAnthropicBudget = providerReasoningRouteMatches(
		"anthropic-thinking",
		request,
		context,
	);
	const outputCap = request.maxTokens ?? context.model.maxOutputTokens;
	const maximumBudget = Math.min(
		controls.budget?.max ?? Number.MAX_SAFE_INTEGER,
		isAnthropicBudget && outputCap !== undefined
			? Math.max(outputCap - 1, 1)
			: Number.MAX_SAFE_INTEGER,
	);
	const explicitBudget =
		typeof reasoning.budgetTokens === "number" && controls.budget
			? clampBudget(reasoning.budgetTokens, controls.budget, maximumBudget)
			: undefined;

	if (effort) {
		return {
			...request,
			reasoning: {
				enabled: reasoning.effort ? reasoning.enabled : undefined,
				effort,
				budgetTokens: explicitBudget,
			},
		};
	}

	if (reasoning.enabled === true && !hasExplicitBudget && controls.effort) {
		return { ...request, reasoning: { enabled: true } };
	}

	if (controls.budget) {
		const scaleTokens =
			isAnthropicBudget && maximumBudget < Number.MAX_SAFE_INTEGER
				? maximumBudget
				: (outputCap ?? controls.budget.max);
		const derivedBudget =
			explicitBudget ??
			(reasoning.effort && scaleTokens !== undefined
				? resolveReasoningBudgetFromRatio({
						effort:
							isAnthropicBudget && reasoning.effort === "max"
								? "xhigh"
								: reasoning.effort,
						maxBudget: maximumBudget,
						scaleTokens,
						minimumBudget: Math.max(controls.budget.min ?? 1, 1),
					})
				: isAnthropicBudget && reasoning.enabled === true
					? Math.max(controls.budget.min ?? 1024, 1)
					: undefined);
		return derivedBudget !== undefined || reasoning.enabled === true
			? {
					...request,
					reasoning: {
						enabled: reasoning.enabled ?? true,
						budgetTokens: derivedBudget,
					},
				}
			: { ...request, reasoning: undefined };
	}

	if (controls.toggle) {
		return {
			...request,
			reasoning: {
				enabled:
					reasoning.enabled ??
					(reasoning.effort !== undefined ||
						reasoning.budgetTokens !== undefined),
			},
		};
	}

	if (controls.supportsDefault && reasoning.enabled === true) {
		return { ...request, reasoning: { enabled: true } };
	}

	return { ...request, reasoning: undefined };
}

export type ProviderOptionsPatch = Record<string, Record<string, unknown>>;

export function toProviderOptionsKey(providerId: string): string {
	return providerId.replace(/-([a-z0-9])/gi, (_match, char: string) =>
		char.toUpperCase(),
	);
}

export function createEphemeralCacheControl() {
	return {
		cache_control: { type: "ephemeral" as const },
	};
}

/**
 * Target the concrete provider id and, when distinct, its camelCase alias
 * bucket (e.g. `vercel-ai-gateway` + `vercelAiGateway`).
 */
export function buildProviderAndAliasPatch(options: {
	providerId: string;
	providerOptionsKey: string;
	bucketOptions: Record<string, unknown>;
}): ProviderOptionsPatch {
	const { providerId, providerOptionsKey, bucketOptions } = options;
	const needsAlias =
		providerOptionsKey !== providerId && providerOptionsKey !== "anthropic";
	return {
		[providerId]: bucketOptions,
		...(needsAlias ? { [providerOptionsKey]: bucketOptions } : {}),
	};
}

export function buildThinkingPatch(options: {
	providerId: string;
	providerOptionsKey: string;
	thinkingType: "enabled" | "disabled";
}): ProviderOptionsPatch {
	const bucketOptions = { thinking: { type: options.thinkingType } };
	return {
		...buildProviderAndAliasPatch({
			providerId: options.providerId,
			providerOptionsKey: options.providerOptionsKey,
			bucketOptions,
		}),
		openaiCompatible: bucketOptions,
	};
}

/**
 * API Stream Types
 *
 * Unified streaming response types that all providers yield.
 * This provides a consistent interface regardless of the underlying provider.
 */

/**
 * The main stream type - an async generator that yields chunks
 */
export type ApiStream = AsyncGenerator<ApiStreamChunk> & { id?: string };

/**
 * Union of all possible chunk types
 */
export type ApiStreamChunk =
	| ApiStreamTextChunk
	| ApiStreamReasoningChunk
	| ApiStreamUsageChunk
	| ApiStreamToolCallsChunk
	| ApiStreamDoneChunk;

/**
 * Text content chunk
 */
export interface ApiStreamTextChunk {
	type: "text";
	/** Text content generated by the model */
	text: string;
	/** Response ID associated with this chunk */
	id: string;
	/** Thought signature (used by Gemini) */
	signature?: string;
}

/**
 * Reasoning/thinking content chunk
 */
export interface ApiStreamReasoningChunk {
	type: "reasoning";
	/** The reasoning text generated by the model */
	reasoning: string;
	/** Additional reasoning details (provider-specific) */
	details?: unknown;
	/** Signature for the thinking block (Anthropic, Gemini) */
	signature?: string;
	/** Redacted reasoning data */
	redacted_data?: string;
	/** Response ID associated with this chunk */
	id: string;
}

/**
 * Usage/token count chunk
 */
export interface ApiStreamUsageChunk {
	type: "usage";
	/** Total number of input tokens reported by the provider */
	inputTokens: number;
	/** Number of output tokens */
	outputTokens: number;
	/** Number of tokens written to cache */
	cacheWriteTokens?: number;
	/** Number of tokens read from cache */
	cacheReadTokens?: number;
	/** Number of thinking/reasoning tokens */
	thoughtsTokenCount?: number;
	/** Total cost in USD (if calculable) */
	totalCost?: number;
	/** Response ID */
	id: string;
}

/**
 * Tool call chunk
 */
export interface ApiStreamToolCallsChunk {
	type: "tool_calls";
	/** The tool call information */
	tool_call: ApiStreamToolCall;
	/** Response ID */
	id: string;
	/** Thought signature (Gemini) */
	signature?: string;
}

/**
 * Tool call details
 */
export interface ApiStreamToolCall {
	/** Call ID for this tool invocation */
	call_id?: string;
	/** Function/tool information */
	function: {
		/** Tool call ID */
		id?: string;
		/** Name of the tool */
		name?: string;
		/** Arguments passed to the tool (can be string or parsed object) */
		arguments?: string | Record<string, unknown>;
	};
}

/**
 * Stream completion chunk - indicates the stream has finished
 */
export interface ApiStreamDoneChunk {
	type: "done";
	/** Whether the stream completed successfully */
	success: boolean;
	/** Error message if the stream failed */
	error?: string;
	/** Reason for incomplete response (e.g., "max_output_tokens") */
	incompleteReason?: string;
	/** Response ID */
	id: string;
}

export function isPositiveFiniteNumber(value: unknown): value is number {
	return typeof value === "number" && Number.isFinite(value) && value > 0;
}

