import { mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { afterEach, describe, expect, it, vi } from "vitest";
import { toLiveProviderConfig } from "./provider-live-config";

describe("toLiveProviderConfig", () => {
	afterEach(() => {
		vi.unstubAllEnvs();
	});

	it("resolves api keys, base URLs, and headers from environment variables", () => {
		vi.stubEnv("LIVE_PROVIDER_API_KEY", "oauth-token");
		vi.stubEnv("LIVE_PROVIDER_BASE_URL", "https://example.test/v1");
		vi.stubEnv("LIVE_PROVIDER_ACCOUNT_ID", "acct-123");

		expect(
			toLiveProviderConfig({
				provider: "openai-codex",
				model: "gpt-5.4",
				apiKeyEnv: "LIVE_PROVIDER_API_KEY",
				baseUrlEnv: "LIVE_PROVIDER_BASE_URL",
				headers: {
					originator: "cline-live-test",
				},
				headersEnv: {
					"ChatGPT-Account-Id": "LIVE_PROVIDER_ACCOUNT_ID",
				},
				reasoning: {
					effort: "high",
				},
			}),
		).toMatchObject({
			providerId: "openai-codex",
			modelId: "gpt-5.4",
			apiKey: "oauth-token",
			baseUrl: "https://example.test/v1",
			headers: {
				originator: "cline-live-test",
				"ChatGPT-Account-Id": "acct-123",
			},
			reasoningEffort: "high",
		});
	});

	it("throws a clear error when an env-backed secret is missing", () => {
		expect(() =>
			toLiveProviderConfig({
				provider: "openai-codex",
				apiKeyEnv: "MISSING_LIVE_PROVIDER_API_KEY",
			}),
		).toThrow(
			"apiKeyEnv references unset or empty environment variable MISSING_LIVE_PROVIDER_API_KEY",
		);
	});

	it("loads OpenAI Codex OAuth credentials from saved provider settings", () => {
		const dir = mkdtempSync(path.join(tmpdir(), "llms-live-provider-"));
		const providersPath = path.join(dir, "providers.json");
		vi.stubEnv("CLINE_PROVIDER_SETTINGS_PATH", providersPath);
		writeFileSync(
			providersPath,
			JSON.stringify({
				version: 1,
				providers: {
					"openai-codex": {
						settings: {
							provider: "openai-codex",
							auth: {
								accessToken: "saved-access-token",
								accountId: "saved-account-id",
							},
						},
					},
				},
			}),
			"utf8",
		);

		expect(
			toLiveProviderConfig({
				provider: "openai-codex",
				model: "gpt-5.4",
				headers: {
					originator: "cline-live-test",
				},
			}),
		).toMatchObject({
			providerId: "openai-codex",
			modelId: "gpt-5.4",
			apiKey: "saved-access-token",
			headers: {
				originator: "cline-live-test",
				"ChatGPT-Account-Id": "saved-account-id",
			},
		});
	});
});

import { existsSync, readFileSync } from "node:fs";
import { resolveProviderSettingsPath } from "@cline/shared/storage";

type ProviderConfig = import("../providers").ProviderConfig;

type StoredProviderSettingsLike = {
	providers?: Record<
		string,
		{
			settings?: {
				auth?: {
					accessToken?: string;
					accountId?: string;
				};
				apiKey?: string;
			};
		}
	>;
};

function readObject(input: unknown): Record<string, unknown> {
	return input && typeof input === "object" && !Array.isArray(input)
		? (input as Record<string, unknown>)
		: {};
}

function readEnvValue(envName: unknown, label: string): string | undefined {
	if (typeof envName !== "string" || envName.trim().length === 0) {
		return undefined;
	}
	const value = process.env[envName]?.trim();
	if (!value) {
		throw new Error(
			`${label} references unset or empty environment variable ${envName}`,
		);
	}
	return value;
}

function readStringHeaders(input: unknown): Record<string, string> {
	const record = readObject(input);
	return Object.fromEntries(
		Object.entries(record).filter(
			([key, value]) => typeof key === "string" && typeof value === "string",
		),
	) as Record<string, string>;
}

function readEnvHeaders(input: unknown): Record<string, string> {
	const record = readObject(input);
	return Object.fromEntries(
		Object.entries(record)
			.map(([key, envName]) => [
				key,
				readEnvValue(envName, `headersEnv.${key}`),
			])
			.filter((entry): entry is [string, string] => entry[1] !== undefined),
	);
}

function readSavedOpenAICodexSettings():
	| { accessToken?: string; accountId?: string }
	| undefined {
	const filePath = resolveProviderSettingsPath();
	if (!existsSync(filePath)) {
		return undefined;
	}
	try {
		const raw = readFileSync(filePath, "utf8");
		const parsed = JSON.parse(raw) as StoredProviderSettingsLike;
		const settings = parsed.providers?.["openai-codex"]?.settings;
		return {
			accessToken:
				settings?.auth?.accessToken?.trim() || settings?.apiKey?.trim(),
			accountId: settings?.auth?.accountId?.trim(),
		};
	} catch {
		return undefined;
	}
}

function decodeJwtPayload(token: string): Record<string, unknown> | undefined {
	const payload = token.split(".")[1];
	if (!payload) {
		return undefined;
	}
	try {
		const base64 = payload.replace(/-/g, "+").replace(/_/g, "/");
		const padded = base64.padEnd(
			base64.length + ((4 - (base64.length % 4)) % 4),
			"=",
		);
		return JSON.parse(Buffer.from(padded, "base64").toString("utf8")) as Record<
			string,
			unknown
		>;
	} catch {
		return undefined;
	}
}

function deriveOpenAICodexAccountId(
	accessToken: string | undefined,
): string | undefined {
	if (!accessToken) {
		return undefined;
	}
	const payload = decodeJwtPayload(accessToken);
	const auth = readObject(payload?.["https://api.openai.com/auth"]);
	const authAccountId = auth.chatgpt_account_id;
	if (typeof authAccountId === "string" && authAccountId.length > 0) {
		return authAccountId;
	}
	const organizations = payload?.organizations;
	if (Array.isArray(organizations)) {
		const organization = readObject(organizations[0]);
		const orgId = organization.id;
		if (typeof orgId === "string" && orgId.length > 0) {
			return orgId;
		}
	}
	const rootAccountId = payload?.chatgpt_account_id;
	return typeof rootAccountId === "string" && rootAccountId.length > 0
		? rootAccountId
		: undefined;
}

export function toLiveProviderConfig(settingsInput: unknown): ProviderConfig {
	const settings = readObject(settingsInput);
	const provider = settings.provider;
	if (typeof provider !== "string" || provider.trim().length === 0) {
		throw new Error("live provider entry must include a provider string");
	}
	const savedCodex =
		provider === "openai-codex" ? readSavedOpenAICodexSettings() : undefined;

	const config: ProviderConfig = {
		providerId: provider,
		modelId: typeof settings.model === "string" ? settings.model : "default",
	};
	const apiKey =
		typeof settings.apiKey === "string"
			? settings.apiKey
			: (readEnvValue(settings.apiKeyEnv, "apiKeyEnv") ??
				savedCodex?.accessToken);
	if (apiKey) {
		config.apiKey = apiKey;
	}
	const baseUrl =
		typeof settings.baseUrl === "string"
			? settings.baseUrl
			: readEnvValue(settings.baseUrlEnv, "baseUrlEnv");
	if (baseUrl) {
		config.baseUrl = baseUrl;
	}
	const headers = {
		...readStringHeaders(settings.headers),
		...readEnvHeaders(settings.headersEnv),
	};
	const codexAccountId =
		savedCodex?.accountId || deriveOpenAICodexAccountId(apiKey);
	if (
		provider === "openai-codex" &&
		codexAccountId &&
		!headers["ChatGPT-Account-Id"]
	) {
		headers["ChatGPT-Account-Id"] = codexAccountId;
	}
	if (Object.keys(headers).length > 0) {
		config.headers = headers;
	}
	if (
		settings.reasoning &&
		typeof settings.reasoning === "object" &&
		!Array.isArray(settings.reasoning)
	) {
		const reasoning = settings.reasoning as Record<string, unknown>;
		if (typeof reasoning.enabled === "boolean") {
			config.thinking = reasoning.enabled;
		}
		if (typeof reasoning.effort === "string" && reasoning.effort !== "none") {
			config.reasoningEffort = reasoning.effort as
				| "minimal"
				| "low"
				| "medium"
				| "high"
				| "xhigh"
				| "max";
		}
		if (typeof reasoning.budgetTokens === "number") {
			config.thinkingBudgetTokens = reasoning.budgetTokens;
		}
	}
	return config;
}

import { describe, expect, it } from "vitest";
import { createHandlerAsync, type ProviderConfig } from "../providers";

type ReasoningControl = { enabled: boolean };

type LiveCase = {
	label: string;
	config: ProviderConfig;
	expectedBody: Record<string, unknown>;
	unexpectedBodyKeys?: string[];
};

type LiveMetrics = {
	usageSeen: boolean;
	reasoningChunks: number;
};

type CapturedRequest = {
	url: string;
	body: unknown;
};

const LIVE_TEST_ENABLED = process.env.LLMS_LIVE_MINIMAX_ROUTING_TESTS === "1";
const PROVIDER_TIMEOUT_MS = Number(
	process.env.LLMS_LIVE_PROVIDER_TIMEOUT_MS ?? "120000",
);
const DEFAULT_PROMPT =
	"What is 12*13? Answer with only the number and no explanation.";

function readRequiredEnv(name: string): string {
	const value = process.env[name]?.trim();
	if (!value) {
		throw new Error(`Set ${name} to run MiniMax M3 live routing tests.`);
	}
	return value;
}

function makeConfig(options: {
	providerId: string;
	modelId: string;
	apiKeyEnv: string;
	reasoning: ReasoningControl;
	fetch: typeof fetch;
}): ProviderConfig {
	return {
		providerId: options.providerId,
		modelId: options.modelId,
		apiKey: readRequiredEnv(options.apiKeyEnv),
		fetch: options.fetch,
		thinking: options.reasoning.enabled,
		maxOutputTokens: 64,
	};
}

async function readRequestBody(
	body: unknown,
): Promise<Record<string, unknown>> {
	if (typeof body === "string") {
		return JSON.parse(body) as Record<string, unknown>;
	}
	if (body instanceof Uint8Array) {
		return JSON.parse(new TextDecoder().decode(body)) as Record<
			string,
			unknown
		>;
	}
	if (body instanceof ArrayBuffer) {
		return JSON.parse(new TextDecoder().decode(body)) as Record<
			string,
			unknown
		>;
	}
	return body && typeof body === "object"
		? (body as Record<string, unknown>)
		: {};
}

async function runLiveRequest(config: ProviderConfig): Promise<LiveMetrics> {
	const handler = await createHandlerAsync(config);
	const metrics: LiveMetrics = { usageSeen: false, reasoningChunks: 0 };
	const stream = handler.createMessage("You are concise.", [
		{ role: "user", content: DEFAULT_PROMPT },
	]);

	for await (const chunk of stream) {
		if (chunk.type === "usage") {
			metrics.usageSeen = true;
		}
		if (chunk.type === "reasoning") {
			metrics.reasoningChunks += 1;
		}
		if (chunk.type === "done" && !chunk.success) {
			throw new Error(chunk.error ?? "done chunk reported success=false");
		}
	}

	return metrics;
}

function buildCases(): LiveCase[] {
	const cases: LiveCase[] = [];
	const addCase = (options: {
		label: string;
		providerId: string;
		modelId: string;
		apiKeyEnv: string;
		reasoning: ReasoningControl;
		expectedBody: Record<string, unknown>;
		unexpectedBodyKeys?: string[];
	}) => {
		const captured: CapturedRequest[] = [];
		const captureFetch: typeof fetch = async (input, init) => {
			captured.push({ url: String(input), body: init?.body });
			return fetch(input, init);
		};
		const config = makeConfig({ ...options, fetch: captureFetch });
		cases.push({
			label: options.label,
			config: {
				...config,
				metadata: {
					...(config.metadata ?? {}),
					get capturedRequests() {
						return captured;
					},
				},
			},
			expectedBody: options.expectedBody,
			unexpectedBodyKeys: options.unexpectedBodyKeys,
		});
	};

	addCase({
		label: "direct MiniMax M3 reasoning enabled",
		providerId: "minimax",
		modelId: "MiniMax-M3",
		apiKeyEnv: "MINIMAX_API_KEY",
		reasoning: { enabled: true },
		expectedBody: { thinking: { type: "adaptive" } },
		unexpectedBodyKeys: [
			"reasoning",
			"effort",
			"reasoningEffort",
			"reasoningSummary",
		],
	});
	addCase({
		label: "direct MiniMax M3 reasoning disabled",
		providerId: "minimax",
		modelId: "MiniMax-M3",
		apiKeyEnv: "MINIMAX_API_KEY",
		reasoning: { enabled: false },
		expectedBody: { thinking: { type: "disabled" } },
		unexpectedBodyKeys: [
			"reasoning",
			"effort",
			"reasoningEffort",
			"reasoningSummary",
		],
	});
	addCase({
		label: "OpenRouter MiniMax M3 reasoning enabled",
		providerId: "openrouter",
		modelId: "minimax/minimax-m3",
		apiKeyEnv: "OPENROUTER_API_KEY",
		reasoning: { enabled: true },
		expectedBody: { reasoning: { enabled: true } },
		unexpectedBodyKeys: ["thinking"],
	});
	addCase({
		label: "OpenRouter MiniMax M3 reasoning disabled",
		providerId: "openrouter",
		modelId: "minimax/minimax-m3",
		apiKeyEnv: "OPENROUTER_API_KEY",
		reasoning: { enabled: false },
		expectedBody: { reasoning: { effort: "none" } },
		unexpectedBodyKeys: ["thinking"],
	});
	addCase({
		label: "Vercel AI Gateway MiniMax M3 reasoning enabled",
		providerId: "vercel-ai-gateway",
		modelId: "minimax/minimax-m3",
		apiKeyEnv: "AI_GATEWAY_API_KEY",
		reasoning: { enabled: true },
		expectedBody: { reasoning: { enabled: true } },
		unexpectedBodyKeys: ["thinking"],
	});
	addCase({
		label: "Vercel AI Gateway MiniMax M3 reasoning disabled",
		providerId: "vercel-ai-gateway",
		modelId: "minimax/minimax-m3",
		apiKeyEnv: "AI_GATEWAY_API_KEY",
		reasoning: { enabled: false },
		expectedBody: { reasoning: { exclude: true } },
		unexpectedBodyKeys: ["thinking"],
	});
	addCase({
		label: "Cline Gateway MiniMax M3 reasoning enabled",
		providerId: "cline",
		modelId: "minimax/minimax-m3",
		apiKeyEnv: "CLINE_API_KEY",
		reasoning: { enabled: true },
		expectedBody: { reasoning: { enabled: true } },
		unexpectedBodyKeys: ["thinking"],
	});
	addCase({
		label: "Cline Gateway MiniMax M3 reasoning disabled",
		providerId: "cline",
		modelId: "minimax/minimax-m3",
		apiKeyEnv: "CLINE_API_KEY",
		reasoning: { enabled: false },
		expectedBody: { reasoning: { enabled: false } },
		unexpectedBodyKeys: ["thinking"],
	});

	return cases;
}

function getCapturedRequests(config: ProviderConfig): CapturedRequest[] {
	const metadata = config.metadata as
		| { capturedRequests?: CapturedRequest[] }
		| undefined;
	return metadata?.capturedRequests ?? [];
}

describe("live MiniMax M3 provider routing mechanics", () => {
	const runLive = LIVE_TEST_ENABLED ? it : it.skip;

	runLive(
		"sends explicit reasoning controls for every MiniMax M3 route",
		async () => {
			const failures: string[] = [];

			for (const liveCase of buildCases()) {
				try {
					const metrics = await runLiveRequest(liveCase.config);
					expect(metrics.usageSeen, liveCase.label).toBe(true);
					const request = getCapturedRequests(liveCase.config).at(-1);
					expect(request, liveCase.label).toBeDefined();
					const body = await readRequestBody(request?.body);
					expect(body, liveCase.label).toEqual(
						expect.objectContaining(liveCase.expectedBody),
					);
					for (const key of liveCase.unexpectedBodyKeys ?? []) {
						expect(body, liveCase.label).not.toHaveProperty(key);
					}
				} catch (error) {
					failures.push(
						`${liveCase.label}: ${
							error instanceof Error ? error.message : String(error)
						}`,
					);
				}
			}

			if (failures.length > 0) {
				throw new Error(
					`MiniMax M3 routing failures (${failures.length}):\n${failures.join(
						"\n",
					)}`,
				);
			}
		},
		PROVIDER_TIMEOUT_MS,
	);
});

import { readFileSync } from "node:fs";
import path from "node:path";
import { describe, it } from "vitest";
import * as LlmsProviders from "../providers";
import { toLiveProviderConfig } from "./provider-live-config";
import {
	LIVE_PROVIDER_CONCURRENCY,
	runLiveProviderTargets,
} from "./provider-live-runner";

type ProviderConfig = import("../providers").ProviderConfig;

interface StoredProviderSettingsEntryLike {
	settings?: unknown;
}

interface StoredProviderSettingsLike {
	providers?: Record<string, unknown>;
}

interface ProviderTarget {
	label: string;
	config: ProviderConfig;
	systemPrompt: string;
	userPrompt: string;
	runs: number;
	expectations: LiveReasoningExpectations;
}

const LIVE_TEST_ENABLED = process.env.LLMS_LIVE_REASONING_TESTS === "1";
const PROVIDERS_FILE_ENV = "LLMS_LIVE_REASONING_PROVIDERS_PATH";
const PROVIDER_TIMEOUT_MS = Number(
	process.env.LLMS_LIVE_PROVIDER_TIMEOUT_MS ?? "90000",
);
const PROVIDER_RETRIES = Number(process.env.LLMS_LIVE_PROVIDER_RETRIES ?? "2");
const PROVIDER_ATTEMPTS = Number.isFinite(PROVIDER_RETRIES)
	? Math.max(1, Math.floor(PROVIDER_RETRIES) + 1)
	: 1;
const DEFAULT_SYSTEM_PROMPT = "You are a concise assistant.";
const DEFAULT_USER_PROMPT =
	"Solve briefly: what is 47*83? Then give one short sentence.";

interface LiveProviderEntryLike {
	settings?: unknown;
	expectations?: unknown;
	systemPrompt?: unknown;
	userPrompt?: unknown;
	prompt?: unknown;
	runs?: unknown;
}

interface LiveReasoningExpectations {
	requireUsage: boolean;
	requireReasoningSignal: boolean;
	requireReasoningChunk: boolean;
	requireNoReasoningChunk: boolean;
	requireNoReasoningSignal: boolean;
}

interface LiveRunMetrics {
	usageSeen: boolean;
	reasoningChunkCount: number;
	reasoningTokenCountMax: number;
}

function parseExpectations(input: unknown): LiveReasoningExpectations {
	const value =
		input && typeof input === "object"
			? (input as Record<string, unknown>)
			: {};
	return {
		requireUsage: value.requireUsage !== false,
		requireReasoningSignal: value.requireReasoningSignal === true,
		requireReasoningChunk: value.requireReasoningChunk === true,
		requireNoReasoningChunk: value.requireNoReasoningChunk === true,
		requireNoReasoningSignal: value.requireNoReasoningSignal === true,
	};
}

function toTarget(
	label: string,
	settingsInput: unknown,
	entry?: LiveProviderEntryLike,
): ProviderTarget {
	const config = toLiveProviderConfig(settingsInput);
	const runsCandidate = entry?.runs;
	const runs =
		typeof runsCandidate === "number" &&
		Number.isFinite(runsCandidate) &&
		runsCandidate > 0
			? Math.floor(runsCandidate)
			: 1;
	const expectations = parseExpectations(entry?.expectations);
	if (
		(expectations.requireReasoningChunk ||
			expectations.requireReasoningSignal) &&
		(expectations.requireNoReasoningChunk ||
			expectations.requireNoReasoningSignal)
	) {
		throw new Error(
			`${label}: positive and negative reasoning expectations are mutually exclusive`,
		);
	}
	if (
		expectations.requireNoReasoningChunk &&
		expectations.requireNoReasoningSignal
	) {
		throw new Error(
			`${label}: requireNoReasoningSignal already includes requireNoReasoningChunk`,
		);
	}

	return {
		label: `${label} (${config.providerId})`,
		config,
		systemPrompt:
			typeof entry?.systemPrompt === "string"
				? entry.systemPrompt
				: DEFAULT_SYSTEM_PROMPT,
		userPrompt:
			typeof entry?.userPrompt === "string"
				? entry.userPrompt
				: typeof entry?.prompt === "string"
					? entry.prompt
					: DEFAULT_USER_PROMPT,
		runs,
		expectations,
	};
}

function requireProvidersFilePath(): string {
	const filePath = process.env[PROVIDERS_FILE_ENV];
	if (!filePath) {
		throw new Error(
			`Set ${PROVIDERS_FILE_ENV} to a provider json path before running live reasoning tests.`,
		);
	}
	return path.resolve(filePath);
}

function toTargetsFromStoredFormat(
	json: StoredProviderSettingsLike,
): ProviderTarget[] {
	const entries = Object.entries(json.providers ?? {});
	return entries.map(([entryKey, entryValue]) => {
		const maybeEntry = entryValue as LiveProviderEntryLike &
			StoredProviderSettingsEntryLike;
		const rawSettings = maybeEntry.settings ?? entryValue;
		return toTarget(entryKey, rawSettings, maybeEntry);
	});
}

function loadProviderTargets(filePath: string): ProviderTarget[] {
	const raw = readFileSync(filePath, "utf8");
	const parsed = JSON.parse(raw) as unknown;

	if (Array.isArray(parsed)) {
		return parsed.map((entry, index) => {
			if (entry && typeof entry === "object" && "settings" in entry) {
				const wrapped = entry as LiveProviderEntryLike;
				return toTarget(`index:${index}`, wrapped.settings, wrapped);
			}
			return toTarget(`index:${index}`, entry);
		});
	}

	return toTargetsFromStoredFormat(parsed as StoredProviderSettingsLike);
}

async function withTimeout<T>(
	promise: Promise<T>,
	timeoutMs: number,
	label: string,
): Promise<T> {
	let timeout: NodeJS.Timeout | undefined;
	const timeoutPromise = new Promise<T>((_, reject) => {
		timeout = setTimeout(() => {
			reject(new Error(`Timed out after ${timeoutMs}ms: ${label}`));
		}, timeoutMs);
	});

	try {
		return await Promise.race([promise, timeoutPromise]);
	} finally {
		if (timeout) {
			clearTimeout(timeout);
		}
	}
}

function assertTargetExpectations(
	target: ProviderTarget,
	metrics: LiveRunMetrics,
): void {
	const errors: string[] = [];
	const expectations = target.expectations;
	if (expectations.requireUsage && !metrics.usageSeen) {
		errors.push("expected at least one usage chunk");
	}
	if (
		expectations.requireReasoningSignal &&
		metrics.reasoningChunkCount <= 0 &&
		metrics.reasoningTokenCountMax <= 0
	) {
		errors.push(
			"expected reasoning signal (reasoning chunk or reasoning tokens)",
		);
	}
	if (expectations.requireReasoningChunk && metrics.reasoningChunkCount <= 0) {
		errors.push("expected at least one reasoning chunk");
	}
	if (expectations.requireNoReasoningChunk && metrics.reasoningChunkCount > 0) {
		errors.push(
			`expected no reasoning chunks, got ${metrics.reasoningChunkCount}`,
		);
	}
	if (
		expectations.requireNoReasoningSignal &&
		(metrics.reasoningChunkCount > 0 || metrics.reasoningTokenCountMax > 0)
	) {
		errors.push(
			`expected no reasoning signal, got ${metrics.reasoningChunkCount} reasoning chunks and ${metrics.reasoningTokenCountMax} reasoning tokens`,
		);
	}
	if (errors.length > 0) {
		throw new Error(errors.join("; "));
	}
}

async function runReasoningPrompt(target: ProviderTarget): Promise<void> {
	const handler = await LlmsProviders.createHandlerAsync(target.config);
	const metrics: LiveRunMetrics = {
		usageSeen: false,
		reasoningChunkCount: 0,
		reasoningTokenCountMax: 0,
	};

	for (let run = 0; run < target.runs; run++) {
		const stream = handler.createMessage(target.systemPrompt, [
			{ role: "user", content: target.userPrompt },
		]);
		for await (const chunk of stream) {
			if (chunk.type === "reasoning") {
				metrics.reasoningChunkCount += 1;
				continue;
			}
			if (chunk.type === "usage") {
				metrics.usageSeen = true;
				metrics.reasoningTokenCountMax = Math.max(
					metrics.reasoningTokenCountMax,
					chunk.thoughtsTokenCount ?? 0,
				);
				continue;
			}
			if (chunk.type === "done" && !chunk.success) {
				throw new Error(chunk.error ?? "done chunk reported success=false");
			}
		}
	}
	assertTargetExpectations(target, metrics);
}

describe("live provider reasoning smoke test", () => {
	const runLive = LIVE_TEST_ENABLED ? it : it.skip;
	runLive(
		"runs reasoning-enabled provider configs and reports failures",
		async () => {
			const filePath = requireProvidersFilePath();
			const targets = loadProviderTargets(filePath);
			if (!targets.length) {
				throw new Error(`No providers found in ${filePath}.`);
			}

			const failures = await runLiveProviderTargets({
				targets,
				concurrency: LIVE_PROVIDER_CONCURRENCY,
				runTarget: async (target) => {
					let success = false;
					let lastError: unknown;
					for (let attempt = 1; attempt <= PROVIDER_ATTEMPTS; attempt++) {
						try {
							await withTimeout(
								runReasoningPrompt(target),
								PROVIDER_TIMEOUT_MS,
								target.label,
							);
							success = true;
							break;
						} catch (error) {
							lastError = error;
						}
					}
					if (success) {
						return undefined;
					}
					const message =
						lastError instanceof Error ? lastError.message : String(lastError);
					return `${target.label}: ${message}`;
				},
			});

			if (failures.length > 0) {
				throw new Error(
					`Providers with error responses (${failures.length}):\n${failures.join("\n")}`,
				);
			}
		},
		300_000,
	);
});

const DEFAULT_PROVIDER_CONCURRENCY = 3;

export const LIVE_PROVIDER_CONCURRENCY = parseLiveProviderConcurrency(
	process.env.LLMS_LIVE_PROVIDER_CONCURRENCY,
);

function parseLiveProviderConcurrency(value: string | undefined): number {
	if (!value) {
		return DEFAULT_PROVIDER_CONCURRENCY;
	}
	const parsed = Number(value);
	if (!Number.isFinite(parsed)) {
		return DEFAULT_PROVIDER_CONCURRENCY;
	}
	return Math.max(1, Math.floor(parsed));
}

export async function runLiveProviderTargets<Target>(options: {
	targets: readonly Target[];
	concurrency?: number;
	runTarget(target: Target): Promise<string | undefined>;
}): Promise<string[]> {
	const concurrency = Math.max(
		1,
		Math.floor(options.concurrency ?? LIVE_PROVIDER_CONCURRENCY),
	);
	const failures: string[] = [];
	let nextIndex = 0;

	async function worker(): Promise<void> {
		while (true) {
			const target = options.targets[nextIndex];
			nextIndex += 1;
			if (target === undefined) {
				return;
			}
			const failure = await options.runTarget(target);
			if (failure) {
				failures.push(failure);
			}
		}
	}

	const workerCount = Math.min(concurrency, options.targets.length);
	await Promise.all(Array.from({ length: workerCount }, () => worker()));
	return failures;
}

