								target.label,
							);
							success = true;
							break;
						} catch (error) {
							lastError = error;
						}
					}
					if (success) {
						return undefined;
					}
					const message =
						lastError instanceof Error ? lastError.message : String(lastError);
					return `${target.label}: ${message}`;
				},
			});

			if (failures.length > 0) {
				throw new Error(
					`Providers with error responses (${failures.length}):\n${failures.join("\n")}`,
				);
			}
		},
		300_000,
	);
});

