/**
 * AgentRuntime contract types (ported from clinee `@cline/shared`).
 *
 * These are the canonical type definitions consumed by `AgentRuntime`.
 *
 */

import type { ModelInfo } from "./llms/model-info";
import type {
	ToolApprovalRequest,
	ToolApprovalResult,
	ToolPolicy,
} from "./llms/tools";
import type { BasicLogger } from "./logging/logger";
import type { ITelemetryService } from "./services/telemetry";

// =============================================================================
// Lightweight telemetry surface used by AgentRuntime
// =============================================================================

// =============================================================================
// Message parts
// =============================================================================

export interface AgentTextPart {
	type: "text";
	text: string;
}

export interface AgentReasoningPart {
	type: "reasoning";
	text: string;
	redacted?: boolean;
	metadata?: unknown;
}

export interface AgentImagePart {
	type: "image";
	image: string | Uint8Array | ArrayBuffer | URL;
	mediaType?: string;
}

export interface AgentFilePart {
	type: "file";
	path: string;
	content: string;
}

export interface AgentToolCallPart {
	type: "tool-call";
	toolCallId: string;
	toolName: string;
	input: unknown;
	metadata?: unknown;
}

export interface AgentToolResultPart {
	type: "tool-result";
	toolCallId: string;
	toolName: string;
	output: unknown;
	isError?: boolean;
}

export type AgentMessagePart =
	| AgentTextPart
	| AgentReasoningPart
	| AgentImagePart
	| AgentFilePart
	| AgentToolCallPart
	| AgentToolResultPart;

// =============================================================================
// Messages and token usage
// =============================================================================

export type AgentMessageRole = "user" | "assistant" | "tool";

export interface AgentTokenUsage {
	inputTokens: number;
	outputTokens: number;
	cacheReadTokens: number;
	cacheWriteTokens: number;
	/** Provider-reported hidden reasoning tokens, when available. */
	reasoningTokenCount?: number;
}

/**
 * Canonical `AgentUsage` shape for the new runtime.
 *
 * This supersedes the legacy `AgentUsage` (now `LegacyAgentUsage` in
 * `./agents/types`). The old, host-facing shape is
 * retained for `AgentResult`/`AgentUsageEvent` consumers via the facade.
 */
export interface AgentUsage extends AgentTokenUsage {
	totalCost?: number;
}

export interface AgentMessage {
	id: string;
	role: AgentMessageRole;
	content: AgentMessagePart[];
	createdAt: number;
	metadata?: Record<string, unknown>;
	modelInfo?: {
		id: string;
		provider: string;
		family?: string;
	};
	metrics?: AgentTokenUsage & {
		cost?: number;
	};
}

// =============================================================================
// Runtime state
// =============================================================================

export type AgentRole = string;

export type AgentRunStatus =
	| "idle"
	| "running"
	| "completed"
	| "aborted"
	| "failed";

export interface AgentRuntimeStateSnapshot {
	agentId: string;
	agentRole?: AgentRole;
	parentAgentId?: string | null;
	conversationId?: string;
	runId?: string;
	status: AgentRunStatus;
	iteration: number;
	messages: readonly AgentMessage[];
	pendingToolCalls: readonly string[];
	usage: AgentUsage;
	lastError?: string;
	/** Classification of `lastError` when it came from a provider stream. */
	lastErrorClass?: ProviderErrorClass;
}

// =============================================================================
// Tools
// =============================================================================

export interface AgentToolDefinition {
	name: string;
	description: string;
	inputSchema: Record<string, unknown>;
	lifecycle?: {
		/**
		 * Whether a successful call to this tool completes the current run.
		 */
		completesRun?: boolean;
	};
}

export interface AgentToolResult<TOutput = unknown> {
	output: TOutput;
	isError?: boolean;
	metadata?: Record<string, unknown>;
}

export interface AgentToolContext {
	sessionId?: string;
	agentId: string;
	conversationId?: string;
	runId?: string;
	iteration: number;
	toolCallId?: string;
	signal?: AbortSignal;
	metadata?: Record<string, unknown>;
	snapshot?: AgentRuntimeStateSnapshot;
	emitUpdate?: (update: unknown) => void;
}

export interface AgentTool<TInput = unknown, TOutput = unknown>
	extends AgentToolDefinition {
	timeoutMs?: number;
	retryable?: boolean;
	maxRetries?: number;
	execute: (
		input: TInput,
		context: AgentToolContext,
	) => Promise<TOutput> | TOutput;
}

// =============================================================================
// Model adapter contract
// =============================================================================

export interface AgentModelRequest {
	systemPrompt?: string;
	messages: readonly AgentMessage[];
	tools: readonly AgentToolDefinition[];
	signal?: AbortSignal;
	options?: Record<string, unknown>;
}

export interface AgentRuntimePrepareTurnContext {
	agentId: string;
	conversationId?: string;
	parentAgentId?: string | null;
	iteration: number;
	messages: readonly AgentMessage[];
	systemPrompt?: string;
	tools: readonly AgentToolDefinition[];
	model: {
		id?: string;
		provider?: string;
		info?: ModelInfo;
	};
	signal?: AbortSignal;
	/**
	 * Set when the previous model request was rejected as exceeding the
	 * model's context window; asks the prepare-turn pipeline to force a
	 * compaction rather than trust its token estimates.
	 */
	overflowRecovery?: boolean;
	emitStatusNotice?: (
		message: string,
		metadata?: Record<string, unknown>,
	) => void;
}

export interface AgentRuntimePrepareTurnResult {
	messages?: readonly AgentMessage[];
	systemPrompt?: string;
}

export type AgentModelFinishReason =
	| "stop"
	| "tool-calls"
	| "max-tokens"
	| "aborted"
	| "error";

/**
 * Coarse classification of a provider error, derived from the raw provider
 * error object before it is flattened into a display string. Shared by the
 * runtime's recovery policy and telemetry (`error_class`). Extend with new
 * classes (auth, rate_limit, billing, ...) as consumers need them.
 */
export type ProviderErrorClass = "context_window_exceeded" | "unknown";

export type AgentModelEvent =
	| { type: "text-delta"; text: string }
	| {
			type: "reasoning-delta";
			text: string;
			redacted?: boolean;
			metadata?: unknown;
	  }
	| {
			type: "tool-call-delta";
			index?: number;
			toolCallId?: string;
			toolName?: string;
			inputText?: string;
			input?: unknown;
			metadata?: unknown;
	  }
	| {
			/**
			 * A model-generated file (e.g. an image from an image-output
			 * model). `data` is base64-encoded file data (or a URL for
			 * URL-referenced files). Runtimes assemble it into the assistant
			 * message (`AgentImagePart` for `image/*`, `AgentFilePart`
			 * otherwise) so a file-only turn is not treated as empty.
			 */
			type: "file";
			data: string;
			mediaType: string;
	  }
	| {
			type: "usage";
			usage: Partial<AgentUsage>;
	  }
	| {
			type: "finish";
			reason: AgentModelFinishReason;
			error?: string;
			errorClass?: ProviderErrorClass;
			/**
			 * The model layer already recorded `sdk.error` telemetry for this
			 * failure at its own error boundary. `error` is a flattened string,
			 * so this bit carries reporting ownership across the boundary: the
			 * agent loop skips re-reporting when it is set, and still reports
			 * failures from model implementations that do not record their own
			 * telemetry.
			 */
			errorReported?: boolean;
	  };

export interface AgentModel {
	stream: (
		request: AgentModelRequest,
	) => AsyncIterable<AgentModelEvent> | Promise<AsyncIterable<AgentModelEvent>>;
}

// =============================================================================
// Hook contexts
// =============================================================================

export interface AgentBeforeModelContext {
	snapshot: AgentRuntimeStateSnapshot;
	request: AgentModelRequest;
}

export interface AgentStopControl {
	stop?: boolean;
	reason?: string;
}

export interface AgentBeforeModelResult {
	stop?: boolean;
	reason?: string;
	messages?: readonly AgentMessage[];
	tools?: readonly AgentToolDefinition[];
	options?: Record<string, unknown>;
}

export interface AgentAfterModelContext {
	snapshot: AgentRuntimeStateSnapshot;
	assistantMessage: AgentMessage;
	finishReason: AgentModelFinishReason;
}

export interface AgentBeforeToolContext {
	snapshot: AgentRuntimeStateSnapshot;
	tool: AgentTool;
	toolCall: AgentToolCallPart;
	input: unknown;
}

export interface AgentBeforeToolResult {
	skip?: boolean;
	stop?: boolean;
	reason?: string;
	input?: unknown;
	policy?: ToolPolicy;
}

export interface AgentAfterToolContext {
	snapshot: AgentRuntimeStateSnapshot;
	tool: AgentTool;
	toolCall: AgentToolCallPart;
	input: unknown;
	result: AgentToolResult;
	startedAt: Date;
	endedAt: Date;
	durationMs: number;
}

export interface AgentAfterToolResult {
	stop?: boolean;
	reason?: string;
	result?: AgentToolResult;
}

export interface AgentRunLifecycleContext {
	snapshot: AgentRuntimeStateSnapshot;
}

// =============================================================================
// Runtime hook bag
// =============================================================================

/**
 * 7-callback hook bag consumed by `AgentRuntime`.
 */
export interface AgentRuntimeHooks {
	beforeRun?: (
		context: AgentRunLifecycleContext,
	) => AgentStopControl | undefined | Promise<AgentStopControl | undefined>;
	afterRun?: (
		context: AgentRunLifecycleContext & { result: AgentRunResult },
	) => void | Promise<void>;
	beforeModel?: (
		context: AgentBeforeModelContext,
	) =>
		| AgentBeforeModelResult
		| undefined
		| Promise<AgentBeforeModelResult | undefined>;
	afterModel?: (
		context: AgentAfterModelContext,
	) => AgentStopControl | undefined | Promise<AgentStopControl | undefined>;
	beforeTool?: (
		context: AgentBeforeToolContext,
	) =>
		| AgentBeforeToolResult
		| undefined
		| Promise<AgentBeforeToolResult | undefined>;
	afterTool?: (
		context: AgentAfterToolContext,
	) =>
		| AgentAfterToolResult
		| undefined
		| Promise<AgentAfterToolResult | undefined>;
	onEvent?: (event: AgentRuntimeEvent) => void | Promise<void>;
}

// =============================================================================
// Plugins
// =============================================================================

export interface AgentRuntimePluginContext {
	agentId: string;
	agentRole?: AgentRole;
	systemPrompt?: string;
}

export interface AgentRuntimePluginSetup {
	// biome-ignore lint/suspicious/noExplicitAny: tool input/output types vary per tool
	tools?: readonly AgentTool<any, any>[];
	hooks?: Partial<AgentRuntimeHooks>;
}

export interface AgentRuntimePlugin {
	name: string;
	setup?: (
		context: AgentRuntimePluginContext,
	) =>
		| AgentRuntimePluginSetup
		| undefined
		| Promise<AgentRuntimePluginSetup | undefined>;
}

// =============================================================================
// Runtime config
// =============================================================================

export interface AgentRuntimeConfig {
	/**
	 * Core/hub runtime session identifier.
	 *
	 * The host-owned lifecycle id for the task/session containing this runtime.
	 * It is stable for hub subscriptions, session persistence, abort/stop
	 * commands, and approval routing. It can differ from `conversationId`, which
	 * tracks the agent transcript.
	 */
	sessionId?: string;
	agentId?: string;
	/**
	 * Agent conversation/transcript identifier.
	 *
	 * Used by the stateless agent loop, tools, hooks, telemetry, and model
	 * history correlation. This id follows the current conversation store and
	 * should not be used as the hub/session routing key.
	 */
	conversationId?: string;
	parentAgentId?: string | null;
	agentRole?: AgentRole;
	systemPrompt?: string;
	messageModelInfo?: AgentMessage["modelInfo"];
	model: AgentModel;
	modelOptions?: Record<string, unknown>;
	// biome-ignore lint/suspicious/noExplicitAny: tool input/output types vary per tool
	tools?: readonly AgentTool<any, any>[];
	hooks?: Partial<AgentRuntimeHooks>;
	plugins?: readonly AgentRuntimePlugin[];
	logger?: BasicLogger;
	telemetry?: ITelemetryService;
	initialMessages?: readonly AgentMessage[];
	maxIterations?: number;
	completionPolicy?: {
		requireCompletionTool?: boolean;
		completionGuard?: () => string | undefined;
	};
	toolExecution?: "sequential" | "parallel";
	toolPolicies?: Record<string, ToolPolicy>;
	toolContextMetadata?: Record<string, unknown>;
	requestToolApproval?: (
		request: ToolApprovalRequest,
	) => Promise<ToolApprovalResult> | ToolApprovalResult;
	/**
	 * Optional host-owned request projection hook invoked before each model call.
	 *
	 * Returned messages affect only the provider request for the current call.
	 * They do not replace the canonical runtime transcript, are not persisted as
	 * session history, and are not reflected in AgentRunResult.messages.
	 */
	prepareTurn?: (
		context: AgentRuntimePrepareTurnContext,
	) =>
		| Promise<AgentRuntimePrepareTurnResult | undefined>
		| AgentRuntimePrepareTurnResult
		| undefined;
	// Optional host callback used by interactive sessions to inject a queued
	// user steering message between agent loop iterations, before the next
	// model request.
	consumePendingUserMessage?: () =>
		| string
		| undefined
		| Promise<string | undefined>;
}

// =============================================================================
// Runtime event union (13 variants)
// =============================================================================

export type AgentRuntimeEvent =
	| {
			type: "run-started";
			snapshot: AgentRuntimeStateSnapshot;
	  }
	| {
			type: "message-added";
			snapshot: AgentRuntimeStateSnapshot;
			message: AgentMessage;
	  }
	| {
			type: "turn-started";
			snapshot: AgentRuntimeStateSnapshot;
			iteration: number;
	  }
	| {
			type: "assistant-text-delta";
			snapshot: AgentRuntimeStateSnapshot;
			iteration: number;
			text: string;
			accumulatedText: string;
	  }
	| {
			type: "assistant-reasoning-delta";
			snapshot: AgentRuntimeStateSnapshot;
			iteration: number;
			text: string;
			accumulatedText: string;
			redacted?: boolean;
			metadata?: unknown;
	  }
	| {
			type: "assistant-message";
			snapshot: AgentRuntimeStateSnapshot;
			iteration: number;
			message: AgentMessage;
			finishReason: AgentModelFinishReason;
	  }
	| {
			type: "tool-started";
			snapshot: AgentRuntimeStateSnapshot;
			iteration: number;
			toolCall: AgentToolCallPart;
	  }
	| {
			type: "tool-updated";
			snapshot: AgentRuntimeStateSnapshot;
			iteration: number;
			toolCall: AgentToolCallPart;
			update: unknown;
	  }
	| {
			type: "tool-finished";
			snapshot: AgentRuntimeStateSnapshot;
			iteration: number;
			toolCall: AgentToolCallPart;
			message: AgentMessage;
	  }
	| {
			type: "usage-updated";
			snapshot: AgentRuntimeStateSnapshot;
			usage: AgentUsage;
	  }
	| {
			type: "turn-finished";
			snapshot: AgentRuntimeStateSnapshot;
			iteration: number;
			toolCallCount: number;
	  }
	| {
			type: "status-notice";
			snapshot: AgentRuntimeStateSnapshot;
			message: string;
			metadata?: Record<string, unknown>;
	  }
	| {
			type: "run-finished";
			snapshot: AgentRuntimeStateSnapshot;
			result: AgentRunResult;
	  }
	| {
			type: "run-failed";
			snapshot: AgentRuntimeStateSnapshot;
			error: Error;
			/** Classification of the provider error that failed the run. */
			errorClass?: ProviderErrorClass;
	  };

// =============================================================================
// Run result
// =============================================================================

export interface AgentRunResult {
	agentId: string;
	agentRole?: AgentRole;
	runId: string;
	status: Exclude<AgentRunStatus, "idle" | "running">;
	iterations: number;
	outputText: string;
	messages: readonly AgentMessage[];
	usage: AgentUsage;
	error?: Error;
}

/**
 * Agent Types and Zod Schemas
 *
 * Canonical type definitions for agent configuration, events, hooks,
 * extensions, and results.
 *
 * ProviderConfig is left as `unknown` here so that shared stays
 * dependency-free of @cline/llms. Consuming packages narrow it
 * via re-exports. ModelInfo lives in shared (../llms/model-info)
 * and is used directly.
 */

import { z } from "zod";
import type {
	AgentRuntimeHooks,
	AgentTool,
	ProviderErrorClass,
} from "../agent";
import type { ExtensionContext } from "../extensions/context";
import type {
	AgentExtensionApi,
	AgentExtensionHooks,
	AgentExtensionRegistry as AgentExtensionRegistryGeneric,
	ContributionRegistryExtension,
	PluginManifest,
	PluginSetupContext,
} from "../extensions/contribution-registry";
import type { HookControl } from "../hooks/contracts";
import type { Message, MessageWithMetadata } from "../llms/messages";
import type { ModelInfo } from "../llms/model-info";
import { ModelInfoSchema } from "../llms/model-info";
import {
	type ReasoningEffort,
	ReasoningEffortSchema,
} from "../llms/reasoning-options";

export {
	REASONING_LEVELS,
	type ReasoningEffort,
	ReasoningEffortSchema,
	type ReasoningLevel,
	ReasoningLevelSchema,
} from "../llms/reasoning-options";

import type {
	ToolApprovalRequest,
	ToolApprovalResult,
	ToolCallRecord,
	ToolPolicy,
} from "../llms/tools";
import { ToolCallRecordSchema } from "../llms/tools";
import type { BasicLogger } from "../logging/logger";
import type { ITelemetryService } from "../services/telemetry";
import type { WorkspaceInfo } from "../session/workspace";

// =============================================================================
// Agent Events
// =============================================================================

/**
 * Events emitted during agent execution
 */
export type AgentEvent =
	| AgentContentStartEvent
	| AgentContentUpdateEvent
	| AgentContentEndEvent
	| AgentIterationStartEvent
	| AgentIterationEndEvent
	| AgentNoticeEvent
	| AgentUsageEvent
	| AgentDoneEvent
	| AgentErrorEvent;

export type AgentContentType = "text" | "reasoning" | "tool";

export interface AgentEventMetadata {
	/** Current ID */
	agentId?: string;
	/** Task ID */
	conversationId?: string;
	/** ID of the agent that created this agent */
	parentAgentId?: string | null;
}

export interface AgentContentStartEvent extends AgentEventMetadata {
	type: "content_start";
	contentType: AgentContentType;
	/** The text chunk received from the model */
	text?: string;
	/** Accumulated text so far in this turn */
	accumulated?: string;
	/** The reasoning/thinking text from the model */
	reasoning?: string;
	/** Whether this is redacted reasoning */
	redacted?: boolean;
	/** Name of the tool being called */
	toolName?: string;
	/** Unique identifier for this tool call */
	toolCallId?: string;
	/** Input being passed to the tool */
	input?: unknown;
}

export interface AgentContentUpdateEvent extends AgentEventMetadata {
	type: "content_update";
	contentType: "tool";
	/** Name of the tool emitting progress */
	toolName?: string;
	/** Unique identifier for this tool call */
	toolCallId?: string;
	/** Partial result emitted by the tool */
	update: unknown;
}

export interface AgentContentEndEvent extends AgentEventMetadata {
	type: "content_end";
	contentType: AgentContentType;
	/** Final text generated for this turn */
	text?: string;
	/** Final reasoning/thinking text generated for this turn */
	reasoning?: string;
	/** Name of the tool that completed */
	toolName?: string;
	/** Unique identifier for this tool call */
	toolCallId?: string;
	/** Output from the tool */
	output?: unknown;
	/** Error message if the tool failed */
	error?: string;
	/** Time taken in milliseconds for tool content */
	durationMs?: number;
}

export interface AgentIterationStartEvent extends AgentEventMetadata {
	type: "iteration_start";
	/** The iteration number (1-based) */
	iteration: number;
}

export interface AgentIterationEndEvent extends AgentEventMetadata {
	type: "iteration_end";
	/** The iteration number that just completed */
	iteration: number;
	/** Whether this iteration had any tool calls */
	hadToolCalls: boolean;
	/** Number of tool calls in this iteration */
	toolCallCount: number;
}

export interface AgentUsageEvent extends AgentEventMetadata {
	type: "usage";
	/** Number of input tokens for this turn */
	inputTokens: number;
	/** Number of output tokens for this turn */
	outputTokens: number;
	/** Tokens read from cache */
	cacheReadTokens?: number;
	/** Tokens written to cache */
	cacheWriteTokens?: number;
	/** Cost for this turn */
	cost?: number;

	/** Accumulated totals */
	totalInputTokens: number;
	totalCacheReadTokens?: number;
	totalCacheWriteTokens?: number;
	totalOutputTokens: number;
	totalCost?: number;
}

export interface AgentNoticeEvent extends AgentEventMetadata {
	type: "notice";
	noticeType: "recovery" | "stop" | "status";
	message: string;
	displayRole?: "system" | "status";
	reason?:
		| "api_error"
		| "invalid_tool_call"
		| "completion_without_submit"
		| "tool_execution_failed"
		| "mistake_limit"
		| "auto_compaction"
		| "manual_compaction"
		| "compaction_budget_emergency";
	metadata?: Record<string, unknown>;
}

export interface AgentDoneEvent extends AgentEventMetadata {
	type: "done";
	/** The reason the agent stopped */
	reason: AgentFinishReason;
	/** Final text output */
	text: string;
	/** Total number of iterations */
	iterations: number;
	/** Aggregated usage information */
	usage?: LegacyAgentUsage;
}

export interface AgentErrorEvent extends AgentEventMetadata {
	type: "error";
	/** The error that occurred */
	error: Error;
	/** Classification of the provider error, when known. */
	errorClass?: ProviderErrorClass;
	/** Whether the error is recoverable */
	recoverable: boolean;
	/** Current iteration when error occurred */
	iteration: number;
}

export interface ConsecutiveMistakeLimitContext {
	iteration: number;
	consecutiveMistakes: number;
	maxConsecutiveMistakes: number;
	reason: "api_error" | "invalid_tool_call" | "tool_execution_failed";
	details?: string;
}

export type ConsecutiveMistakeLimitDecision =
	| {
			action: "continue";
			/**
			 * Optional guidance appended as a user message before continuing.
			 */
			guidance?: string;
	  }
	| {
			action: "stop";
			/**
			 * Optional reason surfaced when stopping due to the limit.
			 */
			reason?: string;
	  };

export interface LoopDetectionConfig {
	softThreshold: number;
	hardThreshold: number;
}

export interface AgentExecutionConfig {
	/**
	 * Maximum consecutive internal mistakes before escalation.
	 * Mistakes include API turn failures, invalid/missing tool-call arguments,
	 * and iterations where every executed tool call fails.
	 * @default 6
	 */
	maxConsecutiveMistakes?: number;
	/**
	 * After this many consecutive iterations with tool calls,
	 * inject a reminder text block asking the agent to answer if it has enough info.
	 * Set to `0` or omit to disable.
	 * @default 0
	 */
	reminderAfterIterations?: number;
	/**
	 * Custom reminder text to inject after `reminderAfterIterations`.
	 * @default "REMINDER: If you have gathered enough information to answer the user's question, please provide your final answer now without using any more tools."
	 */
	reminderText?: string;
	/**
	 * Repeated tool call loop detection. When enabled, the agent detects
	 * consecutive identical tool calls and intervenes:
	 * - At `softThreshold`: injects a recovery notice urging a different approach.
	 * - At `hardThreshold`: triggers the consecutive-mistake-limit decision path.
	 *
	 * Set to `false` to explicitly disable. Omit or leave `undefined` for no detection.
	 * The CLI enables this by default with `{ softThreshold: 3, hardThreshold: 5 }`.
	 */
	loopDetection?: false | Partial<LoopDetectionConfig>;
}

// =============================================================================
// Hooks
// =============================================================================

/**
 * Hook error handling behavior.
 * - "ignore": swallow hook errors and continue agent execution
 * - "throw": fail agent execution when a hook throws
 */
export type HookErrorMode = "ignore" | "throw";

/**
 * Common controls supported by lifecycle hooks.
 */
export type AgentHookControl = Omit<HookControl, "appendMessages"> & {
	/**
	 * Optional messages appended to history.
	 * Primarily used by before-agent-start hook stages.
	 */
	appendMessages?: Message[];
	/**
	 * Optional replacement message history.
	 * Primarily used by before-agent-start hooks and host-owned context pipelines.
	 */
	replaceMessages?: Message[];
};

export interface AgentHookRunStartContext {
	/**
	 * ID of the agent
	 */
	agentId: string;
	/**
	 * Session ID
	 */
	conversationId: string;
	/**
	 * ID of the agent that spawned the agent that is executing this run
	 */
	parentAgentId: string | null;
	/**
	 * The prompt submitted by user
	 */
	userMessage: string;
}

export interface AgentHookScheduleContext {
	scheduleId: string;
	executionId?: string;
	trigger: "scheduled" | "manual";
	triggeredAt?: string;
}

/**
 * Workspace location fields shared by session-scoped and run-scoped contexts.
 *
 * These fields are always sourced from the host session config — never from
 * `process.cwd()`. Plugins and hooks must use these values when they need to
 * resolve paths relative to the session's working directory or project root,
 * because the `--cwd` CLI flag sets the session cwd without calling
 * `process.chdir()`, so `process.cwd()` may return the wrong path.
 */
export interface SessionWorkspaceEnv {
	/**
	 * The session's active working directory as configured by the host (e.g.
	 * via `--cwd`). Always accurate — never use `process.cwd()` in plugins or
	 * hooks; use this field instead.
	 */
	cwd?: string;
	/**
	 * The workspace / project root when it differs from `cwd`. Global plugins
	 * installed outside the project should use this rather than
	 * `import.meta.url` tricks or `process.cwd()`.
	 */
	workspaceRoot?: string;
	/**
	 * Structured workspace and git metadata for the session.
	 *
	 * Contains the same information as the `{{CLINE_METADATA}}` block in the
	 * system prompt but in structured form: `rootPath`, `hint`,
	 * `associatedRemoteUrls`, `latestGitCommitHash`, `latestGitBranchName`.
	 *
	 * Plugins and hooks can use this for branch-aware logic, commit
	 * attribution, or tooling integrations without running their own `git`
	 * calls. Populated once per session at session-start time.
	 */
	workspaceInfo?: WorkspaceInfo;
}

/**
 * Fired exactly once for the lifetime of an agent conversation, before the
 * first run starts. This is the right place for session-scoped setup.
 */
export interface AgentHookSessionStartContext extends SessionWorkspaceEnv {
	agentId: string;
	conversationId: string;
	parentAgentId: string | null;
	schedule?: AgentHookScheduleContext;
}

/**
 * Fired once per `run()` / `continue()` invocation after user input has been
 * accepted and before the loop enters its first iteration.
 */
export interface AgentHookRunEndContext {
	agentId: string;
	conversationId: string;
	parentAgentId: string | null;
	result: AgentResult;
}

/**
 * Fired at the top of every loop iteration, before any turn-level prompt or
 * model preparation occurs.
 */
export interface AgentHookIterationStartContext {
	agentId: string;
	conversationId: string;
	parentAgentId: string | null;
	iteration: number;
}

export interface AgentHookIterationEndContext {
	agentId: string;
	conversationId: string;
	parentAgentId: string | null;
	iteration: number;
	hadToolCalls: boolean;
	toolCallCount: number;
}

export interface AgentHookTurnStartContext {
	agentId: string;
	conversationId: string;
	parentAgentId: string | null;
	iteration: number;
	messages: Message[];
}

/**
 * Fired immediately before the model call for an iteration.
 *
 * Compared with `onIterationStart`, this hook runs later: after turn-start
 * processing and with the exact message list that will be sent to the model.
 * It can still influence the upcoming turn by replacing the system prompt,
 * appending messages, or cancelling the run.
 */
export interface AgentHookBeforeAgentStartContext {
	agentId: string;
	conversationId: string;
	parentAgentId: string | null;
	iteration: number;
	systemPrompt: string;
	messages: Message[];
}

export interface AgentHookTurnEndContext {
	agentId: string;
	conversationId: string;
	parentAgentId: string | null;
	iteration: number;
	turn: ProcessedTurn;
}

export interface AgentHookToolCallStartContext {
	agentId: string;
	conversationId: string;
	parentAgentId: string | null;
	iteration: number;
	call: PendingToolCall;
}

export interface AgentHookToolCallEndContext {
	agentId: string;
	conversationId: string;
	parentAgentId: string | null;
	iteration: number;
	record: ToolCallRecord;
}

export interface AgentHookErrorContext {
	agentId: string;
	conversationId: string;
	parentAgentId: string | null;
	iteration: number;
	error: Error;
}

export interface AgentHookStopErrorContext {
	agentId: string;
	conversationId: string;
	parentAgentId: string | null;
	iteration: number;
	error: Error;
}

export interface AgentHookSessionShutdownContext {
	agentId: string;
	conversationId: string;
	/** Stable core session id for the root session, when provided by the host. */
	sessionId?: string;
	parentAgentId: string | null;
	/**
	 * Optional reason for shutdown (e.g. "ctrl_d", "process_exit")
	 */
