/**
 * Lifecycle hooks for observing or influencing agent execution.
 */
export type AgentHooks = Partial<AgentRuntimeHooks>;

// =============================================================================
// Agent Finish Reasons
// =============================================================================

/**
 * Reasons why the agent stopped executing
 */
export type AgentFinishReason =
	| "completed" // Normal completion (no more tool calls)
	| "max_iterations" // Hit the maximum iteration limit
	| "aborted" // User or system aborted
	| "mistake_limit" // Stopped after repeated recoverable mistakes
	| "error"; // Unrecoverable error occurred

export const AgentFinishReasonSchema = z.enum([
	"completed",
	"max_iterations",
	"aborted",
	"mistake_limit",
	"error",
]);

// =============================================================================
// Agent Usage
// =============================================================================

/**
 * Aggregated token usage and cost information (legacy, host-facing shape).
 *
 * Renamed from `AgentUsage` to make room for the runtime's stricter
 * `AgentUsage` (see `../agent.ts`). Retained because
 * the host-facing `AgentResult`/`AgentUsageEvent` surface and the
 * `AgentUsageSchema` Zod schema use this more-permissive shape (all
 * cache/cost fields optional). The facade adapter converts between the
 * two shapes at runtime.
 */
export interface LegacyAgentUsage {
	/** Total input tokens across all iterations */
	inputTokens: number;
	/** Total output tokens across all iterations */
	outputTokens: number;
	/** Total tokens read from cache */
	cacheReadTokens?: number;
	/** Total tokens written to cache */
	cacheWriteTokens?: number;
	/** Total cost in dollars */
	totalCost?: number;
}

export const AgentUsageSchema = z.object({
	inputTokens: z.number(),
	outputTokens: z.number(),
	cacheReadTokens: z.number().optional(),
	cacheWriteTokens: z.number().optional(),
	totalCost: z.number().optional(),
});

export interface AgentPrepareTurnContext {
	agentId: string;
	conversationId: string;
	parentAgentId: string | null;
	iteration: number;
	messages: MessageWithMetadata[];
	apiMessages: MessageWithMetadata[];
	abortSignal: AbortSignal;
	systemPrompt: string;
	tools: AgentTool[];
	model: {
		id: string;
		provider: string;
		info?: ModelInfo;
	};
	/**
	 * Set when the previous model request was rejected as exceeding the
	 * model's context window; asks the prepare-turn pipeline to force a
	 * compaction rather than trust its token estimates.
	 */
	overflowRecovery?: boolean;
	emitStatusNotice?: (
		message: string,
		metadata?: Record<string, unknown>,
	) => void;
}

export interface AgentPrepareTurnResult {
	messages?: MessageWithMetadata[];
	systemPrompt?: string;
}

// =============================================================================
// Agent Result
// =============================================================================

/**
 * Result returned from Agent.run()
 */
export interface AgentResult {
	/** Final text output from the agent */
	text: string;
	/** Aggregated token usage and cost */
	usage: LegacyAgentUsage;
	/** Full conversation history */
	messages: MessageWithMetadata[];
	/** All tool calls made during execution */
	toolCalls: ToolCallRecord[];
	/** Number of loop iterations */
	iterations: number;
	/** Why the agent stopped */
	finishReason: AgentFinishReason;
	/** Model information used */
	model: {
		id: string;
		provider: string;
		info?: ModelInfo;
	};
	/** Start time of the run */
	startedAt: Date;
	/** End time of the run */
	endedAt: Date;
	/** Total duration in milliseconds */
	durationMs: number;
}

export const AgentResultSchema = z.object({
	text: z.string(),
	usage: AgentUsageSchema,
	messages: z.array(z.custom<MessageWithMetadata>()),
	toolCalls: z.array(ToolCallRecordSchema),
	iterations: z.number(),
	finishReason: AgentFinishReasonSchema,
	model: z.object({
		id: z.string(),
		provider: z.string(),
		info: ModelInfoSchema.optional(),
	}),
	startedAt: z.date(),
	endedAt: z.date(),
	durationMs: z.number(),
});

// =============================================================================
// Agent Configuration
// =============================================================================

/**
 * Configuration for creating an Agent
 */
export interface AgentConfig {
	/**
	 * Core/hub runtime session identifier.
	 *
	 * The host-owned lifecycle id for this task/session. Core uses it for
	 * persistence, event routing, abort/stop operations, and approval delivery.
	 * This is intentionally separate from `conversationId`, which identifies the
	 * model transcript managed by the agent runtime.
	 */
	sessionId?: string;
	// -------------------------------------------------------------------------
	// Provider Settings
	// -------------------------------------------------------------------------

	/** Provider ID (e.g., "anthropic", "openai", "gemini") */
	providerId: string;
	/** Model ID to use */
	modelId: string;
	/** API key for the provider */
	apiKey?: string;
	/** Custom base URL for the API */
	baseUrl?: string;
	/** Additional headers for API requests */
	headers?: Record<string, string>;
	/**
	 * Called when a run fails with an auth-like provider error (e.g. an OAuth
	 * access token that expired mid-run). Hosts refresh credentials and push
	 * the new key into the runtime via `updateConnection`; returning `true`
	 * makes the runtime retry the failed run once with the refreshed
	 * connection.
	 */
	onAuthError?: () => Promise<boolean>;
	/** Optional provider model catalog overrides */
	knownModels?: Record<string, ModelInfo>;
	/** Optional pre-resolved provider configuration (includes provider-specific fields like aws/gcp). */
	providerConfig?: unknown;
	/**
	 * Optional preloaded conversation history for resume flows.
	 * When provided, start by calling continue() to preserve history.
	 */
	initialMessages?: Message[];

	// -------------------------------------------------------------------------
	// Agent Behavior
	// -------------------------------------------------------------------------

	/** System prompt for the agent */
	systemPrompt: string;
	/** Tools available to the agent */
	tools: AgentTool[];
	/**
	 * Maximum number of loop iterations
	 * If undefined, no iteration cap is enforced.
	 */
	maxIterations?: number;
	/**
	 * Maximum number of tool calls to execute concurrently in a single iteration.
	 * @default 8
	 */
	maxParallelToolCalls?: number;
	/**
	 * Maximum output tokens per API call
	 */
	maxTokensPerTurn?: number;
	/**
	 * Sampling temperature per API call
	 */
	temperature?: number;
	/**
	 * Timeout for each API call in milliseconds
	 * @default 180000 (3 minutes)
	 */
	apiTimeoutMs?: number;
	/**
	 * Optional runtime file-content loader used when user files are attached.
	 * When omitted, attached files will be represented as loader errors.
	 */
	userFileContentLoader?: (path: string) => Promise<string>;
	/**
	 * Optional metadata merged into every tool execution context.
	 * Hosts can use this to thread runtime-specific identifiers such as session IDs.
	 */
	toolContextMetadata?: Record<string, unknown>;
	/** Execution guardrails and recovery settings. */
	execution?: AgentExecutionConfig;

	// -------------------------------------------------------------------------
	// Reasoning Settings (for capable models)
	// -------------------------------------------------------------------------

	/**
	 * Reasoning effort level
	 */
	reasoningEffort?: ReasoningEffort;
	/**
	 * Maximum tokens for thinking/reasoning
	 */
	thinkingBudgetTokens?: number;
	/**
	 * Enable default thinking/reasoning behavior for supported models.
	 */
	thinking?: boolean;

	// -------------------------------------------------------------------------
	// Callbacks
	// -------------------------------------------------------------------------

	/**
	 * Callback for agent events (streaming, progress, etc.)
	 */
	onEvent?: (event: AgentEvent) => void;
	/**
	 * Lifecycle hooks for observing or influencing agent execution.
	 */
	hooks?: AgentHooks;
	/**
	 * Optional parent agent ID for spawned/delegated runs.
	 * Root agents should leave this undefined.
	 */
	parentAgentId?: string;
	/**
	 * Extension modules that can intercept lifecycle events and register tools/commands.
	 */
	extensions?: AgentExtension[];
	/**
	 * How hook errors should be handled.
	 * @default "ignore"
	 */
	hookErrorMode?: HookErrorMode;
	/**
	 * Optional schedule metadata for runs initiated by scheduler services.
	 * Used by session_start lifecycle hooks.
	 */
	schedule?: AgentHookScheduleContext;
	/**
	 * Per-tool execution policy. Tool names not listed here default to enabled + autoApprove.
	 */
	toolPolicies?: Record<string, ToolPolicy>;
	/**
	 * Optional callback to request client approval when a tool policy disables auto-approval.
	 */
	requestToolApproval?: (
		request: ToolApprovalRequest,
	) => Promise<ToolApprovalResult> | ToolApprovalResult;
	/**
	 * Optional callback invoked when consecutive mistakes reach maxConsecutiveMistakes.
	 */
	onConsecutiveMistakeLimitReached?: (
		context: ConsecutiveMistakeLimitContext,
	) =>
		| Promise<ConsecutiveMistakeLimitDecision>
		| ConsecutiveMistakeLimitDecision;
	/**
	 * Optional logger for tracing agent loop lifecycle and recoverable failures.
	 */
	logger?: BasicLogger;
	/**
	 * Optional request projection hook invoked before each model call.
	 *
	 * Returned messages affect only the provider request for the current call.
	 * They do not replace the canonical runtime transcript, are not persisted as
	 * session history, and are not reflected in AgentRunResult.messages.
	 *
	 * Hosts that need durable redaction or normalization must apply it before a
	 * message enters the canonical transcript.
	 */
	prepareTurn?: (
		context: AgentPrepareTurnContext,
	) =>
		| Promise<AgentPrepareTurnResult | undefined>
		| AgentPrepareTurnResult
		| undefined;
	/**
	 * Optional Telemetry service for emitting structured events about agent execution to configured telemetry backends.
	 */
	telemetry?: ITelemetryService;
	/**
	 * Ambient runtime context: user identity, client surface, workspace, logger,
	 * and telemetry. Threaded through to ProviderConfig so handlers can access it.
	 */
	extensionContext?: ExtensionContext;

	// -------------------------------------------------------------------------
	// Completion Guard
	// -------------------------------------------------------------------------

	/**
	 * First-class runtime completion policy. Tool-based completion is resolved
	 * from the final agent tool list, so built-in and plugin tools can opt in
	 * with `lifecycle.completesRun`.
	 *
	 * `completionGuard` runs when the model returns no tool calls.
	 * If it returns a non-empty string, that string is injected as a
	 * system-level nudge and the loop continues instead of completing.
	 * Use this to prevent premature exit when the agent has unfinished
	 * obligations (e.g. in-progress team tasks).
	 */
	completionPolicy?: {
		requireCompletionTool?: boolean;
		completionGuard?: () => string | undefined;
	};

	// -------------------------------------------------------------------------
	// Pending User Messages
	// -------------------------------------------------------------------------

	/**
	 * Optional callback invoked at the top of each agent loop iteration
	 * (after the first). If it returns a non-empty string, that string is
	 * injected as a user message into the conversation before the next API
	 * call. This allows the host to feed user input into a running loop
	 * without waiting for the current run to finish.
	 */
	consumePendingUserMessage?: () => string | undefined;

	// -------------------------------------------------------------------------
	// Cancellation
	// -------------------------------------------------------------------------

	/**
	 * Abort signal for cancellation
	 */
	abortSignal?: AbortSignal;
}

export const AgentConfigSchema = z.object({
	sessionId: z.string().optional(),
	// Provider Settings
	providerId: z.string(),
	modelId: z.string(),
	apiKey: z.string().optional(),
	baseUrl: z.string().url().optional(),
	headers: z.record(z.string(), z.string()).optional(),
	knownModels: z.record(z.string(), ModelInfoSchema).optional(),
	providerConfig: z.unknown().optional(),
	initialMessages: z.array(z.custom<Message>()).optional(),

	// Agent Behavior
	systemPrompt: z.string(),
	tools: z.array(z.custom<AgentTool>()),
	maxIterations: z.number().positive().optional(),
	maxParallelToolCalls: z.number().int().positive().default(8),
	maxTokensPerTurn: z.number().positive().optional(),
	temperature: z.number().nonnegative().optional(),
	apiTimeoutMs: z.number().positive().default(180000),
	userFileContentLoader: z
		.function()
		.input([z.string()])
		.output(z.promise(z.string()))
		.optional(),
	toolContextMetadata: z.record(z.string(), z.unknown()).optional(),
	execution: z
		.object({
			maxConsecutiveMistakes: z.number().int().positive().optional(),
			reminderAfterIterations: z.number().nonnegative().optional(),
			reminderText: z.string().optional(),
			loopDetection: z
				.union([
					z.literal(false),
					z.object({
						softThreshold: z.number().int().positive().optional(),
						hardThreshold: z.number().int().positive().optional(),
					}),
				])
				.optional(),
		})
		.optional(),
	// Reasoning Settings
	reasoningEffort: ReasoningEffortSchema.optional(),
	thinkingBudgetTokens: z.number().positive().optional(),
	thinking: z.boolean().optional(),

	// Callbacks
	onEvent: z
		.function()
		.input([z.custom<AgentEvent>()])
		.output(z.void())
		.optional(),
	hooks: z.custom<AgentHooks>().optional(),
	parentAgentId: z.string().optional(),
	extensions: z.array(z.custom<AgentExtension>()).optional(),
	hookErrorMode: z.enum(["ignore", "throw"]).default("ignore"),
	toolPolicies: z
		.record(
			z.string(),
			z.object({
				enabled: z.boolean().optional(),
				autoApprove: z.boolean().optional(),
			}),
		)
		.optional(),
	requestToolApproval: z
		.function()
		.input([
			z.object({
				sessionId: z.string(),
				agentId: z.string(),
				conversationId: z.string(),
				iteration: z.number(),
				toolCallId: z.string(),
				toolName: z.string(),
				input: z.unknown(),
				policy: z
					.object({
						enabled: z.boolean().optional(),
						autoApprove: z.boolean().optional(),
					})
					.default({}),
			}),
		])
		.output(
			z.union([
				z.object({
					approved: z.boolean(),
					reason: z.string().optional(),
				}),
				z.promise(
					z.object({
						approved: z.boolean(),
						reason: z.string().optional(),
					}),
				),
			]),
		)
		.optional(),
	onConsecutiveMistakeLimitReached: z
		.function()
		.input([
			z.object({
				iteration: z.number().int().positive(),
				consecutiveMistakes: z.number().int().positive(),
				maxConsecutiveMistakes: z.number().int().positive(),
				reason: z.enum([
					"api_error",
					"invalid_tool_call",
					"tool_execution_failed",
				]),
				details: z.string().optional(),
			}),
		])
		.output(
			z.union([
				z.object({
					action: z.literal("continue"),
					guidance: z.string().optional(),
				}),
				z.object({
					action: z.literal("stop"),
					reason: z.string().optional(),
				}),
				z.promise(
					z.union([
						z.object({
							action: z.literal("continue"),
							guidance: z.string().optional(),
						}),
						z.object({
							action: z.literal("stop"),
							reason: z.string().optional(),
						}),
					]),
				),
			]),
		)
		.optional(),
	logger: z.custom<BasicLogger>().optional(),
	extensionContext: z.custom<ExtensionContext>().optional(),

	// Cancellation
	abortSignal: z.custom<AbortSignal>().optional(),
});

// =============================================================================
// Internal Types
// =============================================================================

/**
 * Pending tool call from the model
 */
export interface PendingToolCall {
	id: string;
	name: string;
	input: unknown;
	signature?: string;
	review?: boolean;
}

/**
 * Processed response from one turn of the loop
 */
export interface ProcessedTurn {
	/** Text output from the model */
	text: string;
	/** Reasoning/thinking content */
	reasoning?: string;
	/** Tool calls requested by the model */
	toolCalls: PendingToolCall[];
	/** Model-emitted tool calls that were invalid or missing required fields */
	invalidToolCalls: Array<{
		id: string;
		name?: string;
		input?: unknown;
		reason: "missing_name" | "missing_arguments" | "invalid_arguments";
	}>;
	/** Token usage for this turn */
	usage: {
		inputTokens: number;
		outputTokens: number;
		cacheReadTokens?: number;
		cacheWriteTokens?: number;
		cost?: number;
	};
	/** Whether the response was truncated */
	truncated: boolean;
	/** Response ID from the API */
	responseId?: string;
}

import { z } from "zod";

/**
 * Zod schemas for automation spec frontmatter. Used by the parser in
 * `@cline/core` to validate frontmatter shape before normalization.
 *
 * The schemas are deliberately permissive: they accept the raw parsed YAML
 * object and let the parser layer apply normalization rules (trim, default
 * enabled, resolve title, body->prompt fallback, etc).
 */

const nonEmptyString = z.string().min(1);

const tagsSchema = z.array(z.string()).optional();

const metadataSchema = z.record(z.string(), z.unknown()).optional();

const modeSchema = z.enum(["act", "plan", "yolo", "zen"]).optional();

const modelSelectionSchema = z
	.object({
		providerId: nonEmptyString,
		modelId: z.string().optional(),
	})
	.optional();

/**
 * Fields accepted across every trigger kind. Trigger-specific fields live on
 * their respective discriminants and are rejected when they appear on the
 * wrong kind.
 */
const commonFrontmatterFields = {
	id: z.string().optional(),
	title: z.string().optional(),
	prompt: z.string().optional(),
	workspaceRoot: z.string().optional(),
	cwd: z.string().optional(),
	modelSelection: modelSelectionSchema,
	systemPrompt: z.string().optional(),
	mode: modeSchema,
	timeoutSeconds: z.number().int().positive().optional(),
	maxIterations: z.number().int().positive().optional(),
	tags: tagsSchema,
	enabled: z.boolean().optional(),
	metadata: metadataSchema,
} as const;

export const AutomationOneOffFrontmatterSchema = z
	.object({
		...commonFrontmatterFields,
	})
	.strict();

export const AutomationScheduleFrontmatterSchema = z
	.object({
		...commonFrontmatterFields,
		schedule: nonEmptyString,
		timezone: z.string().optional(),
	})
	.strict();

export const AutomationEventFrontmatterSchema = z
	.object({
		...commonFrontmatterFields,
		event: nonEmptyString,
		filters: z.record(z.string(), z.unknown()).optional(),
		debounceSeconds: z.number().int().nonnegative().optional(),
		dedupeWindowSeconds: z.number().int().nonnegative().optional(),
		cooldownSeconds: z.number().int().nonnegative().optional(),
		maxParallel: z.number().int().positive().optional(),
	})
	.strict();

/**
 * Field names that are only valid on schedule specs.
 */
export const SCHEDULE_ONLY_FIELDS = ["schedule", "timezone"] as const;

/**
 * Field names that are only valid on event specs.
 */
export const EVENT_ONLY_FIELDS = [
	"event",
	"filters",
	"debounceSeconds",
	"dedupeWindowSeconds",
	"cooldownSeconds",
	"maxParallel",
] as const;

export type AutomationOneOffFrontmatter = z.infer<
	typeof AutomationOneOffFrontmatterSchema
>;
export type AutomationScheduleFrontmatter = z.infer<
	typeof AutomationScheduleFrontmatterSchema
>;
export type AutomationEventFrontmatter = z.infer<
	typeof AutomationEventFrontmatterSchema
>;

import type { GatewayModelSelection } from "../llms/gateway";
import type { AgentMode } from "../session/runtime-config";

/**
 * Trigger kinds supported by the automation subsystem.
 *
 * - `one_off`: a single run materialized from a `.cline/cron/*.md` spec.
 * - `schedule`: recurring runs materialized from a `.cline/cron/*.cron.md` spec.
 * - `event`: reactive runs materialized from a `.cline/cron/events/*.event.md`
 *   spec. Event-driven specs are defined here for contract completeness but
 *   runtime matching lives in a later feature.
 */
export type AutomationTriggerKind = "one_off" | "schedule" | "event";

/**
 * Trigger kinds persisted on `cron_runs`. Event-driven, manual, and retry
 * triggers are all first-class run sources in addition to the spec-defined
 * `one_off` and `schedule` kinds.
 */
export type AutomationRunTriggerKind =
	| "one_off"
	| "schedule"
	| "event"
	| "manual"
	| "retry";

/**
 * Lifecycle status of a queued run row in `cron_runs`.
 */
export type AutomationRunStatus =
	| "queued"
	| "running"
	| "done"
	| "failed"
	| "cancelled";

/**
 * Parse status persisted on a `cron_specs` row.
 */
export type AutomationSpecParseStatus = "valid" | "invalid";

/**
 * Common fields shared by every automation spec after parsing.
 *
 * `id` is the stable external identity derived from the frontmatter `id` field
 * when present, or from the normalized relative source path as a fallback.
 */
export interface AutomationSpecCommon {
	/** Stable external identity: frontmatter id, else normalized relative path. */
	id: string;
	/** Optional explicit frontmatter `id` (undefined when falling back to path). */
	externalId?: string;
	/** Human-readable title used in reports and list APIs. */
	title: string;
	/** Prompt text: frontmatter `prompt` if provided, otherwise the markdown body. */
	prompt: string;
	/** Absolute workspace root the automation run executes against. */
	workspaceRoot: string;
	/** Working directory inside the workspace (defaults to workspaceRoot at runtime). */
	cwd?: string;
	/** Optional model selection; when omitted the runtime default is used. */
	modelSelection?: GatewayModelSelection;
	/** System prompt override. */
	systemPrompt?: string;
	/** Agent mode. Defaults to `act` at runtime if omitted. */
	mode?: AgentMode;
	/** Hard timeout enforced by the runner. */
	timeoutSeconds?: number;
	/** Maximum agent iterations. */
	maxIterations?: number;
	/** Free-form tags. */
	tags?: readonly string[];
	/** Whether the spec is enabled. Defaults to `true`. */
	enabled: boolean;
	/** Arbitrary user metadata; stored verbatim as JSON. */
	metadata?: Readonly<Record<string, unknown>>;
}

export interface AutomationOneOffSpec extends AutomationSpecCommon {
	triggerKind: "one_off";
}

export interface AutomationScheduleSpec extends AutomationSpecCommon {
	triggerKind: "schedule";
	/** Cron expression (5 or 6 fields, parser validated by the scheduler). */
	schedule: string;
	/** IANA timezone name. Optional; falls back to runtime default. */
	timezone?: string;
}

/**
 * Event-driven spec. Feature 2 owns the matcher; Feature 1 only needs the
 * contract so `.event.md` specs parsed later surface the expected shape.
 */
export interface AutomationEventSpec extends AutomationSpecCommon {
	triggerKind: "event";
	event: string;
	filters?: Readonly<Record<string, unknown>>;
	debounceSeconds?: number;
	dedupeWindowSeconds?: number;
	cooldownSeconds?: number;
	maxParallel?: number;
}

/**
 * Discriminated union of all automation specs.
 */
export type AutomationSpec =
	| AutomationOneOffSpec
	| AutomationScheduleSpec
	| AutomationEventSpec;

/**
 * Normalized automation event envelope. Feature 2 will flesh out matching on
 * top of this contract; Feature 1 ships the scaffold so downstream modules can
 * reference it without cyclic dependencies.
 */
export interface AutomationEventEnvelope {
	eventId: string;
	eventType: string;
	source: string;
	subject?: string;
	occurredAt: string;
	workspaceRoot?: string;
	payload: unknown;
	attributes?: Readonly<Record<string, unknown>>;
	dedupeKey?: string;
}

/**
 * Source-file metadata passed into the parser. Filesystem I/O (reading the
 * file, hashing the bytes, stat-ing mtime) happens in core; the parser stays
 * pure and takes these values as inputs.
 */
export interface AutomationSpecSource {
	/**
	 * POSIX-normalized path of the source file relative to `.cline/cron/`.
	 * Used as the identity fallback and persisted in `cron_specs.source_path`.
	 */
	normalizedRelativePath: string;
	/** Bare filename (e.g. `repo-cleanup.md`). */
	filename: string;
	/** File mtime in milliseconds since the epoch. */
	mtimeMs: number;
	/** Content hash (hex sha256) of the raw file bytes. */
	hash: string;
}

export interface ParsedSpecOk {
	ok: true;
	spec: AutomationSpec;
	source: AutomationSpecSource;
	/** Non-fatal parser warnings. */
	warnings: readonly ParseIssueDetail[];
}

export interface ParsedSpecError {
	ok: false;
	source: AutomationSpecSource;
	issue: ParseIssue;
}

export type ParsedSpec = ParsedSpecOk | ParsedSpecError;

/**
 * Categorization of parser issues. `unsupported` is reserved for spec shapes
 * that are syntactically valid but intentionally deferred (e.g. `.event.md`
 * before Feature 2 lands). All other kinds are fatal for that file.
 */
export type ParseIssueKind =
	| "yaml"
	| "schema"
	| "missing_required"
	| "conflicting_fields"
	| "empty_prompt"
	| "unsupported";

export interface ParseIssueDetail {
	field?: string;
	message: string;
}

export interface ParseIssue {
	kind: ParseIssueKind;
	message: string;
	details?: readonly ParseIssueDetail[];
}

