export const PLATFORMS = CONNECTOR_PLATFORMS;
export const shouldIncludeField = shouldIncludeConnectorField;

/**
 * Types for hub-owned connector supervision.
 *
 * A connector is a separate process holding third-party credentials (a Slack
 * socket, a Telegram poll loop). The hub supervises those processes: it is the
 * single authority on which instances may run, it reaps their state when they
 * die, and it restarts them with backoff. These records are what it reports
 * about that work.
 */

/** How a supervised connector process came under the hub's watch. */
export type SupervisedConnectorOrigin =
	/** The current hub spawned it, so it has a live child handle. */
	| "spawned"
	/** It predates the current hub, which adopted it by pid from its state file. */
	| "adopted";

export type SupervisedConnectorState =
	/** Process is alive as far as the hub can tell. */
	| "running"
	/** Died and is waiting out its restart backoff. */
	| "backoff"
	/** Died too many times in a row; the hub has given up restarting it. */
	| "failed"
	/** Stopped on request; the hub will not restart it. */
	| "stopped";

export type SupervisedConnectorRecord = {
	channel: string;
	instanceId: string;
	state: SupervisedConnectorState;
	origin: SupervisedConnectorOrigin;
	pid?: number;
	startedAt?: string;
	/** Consecutive restarts that have not yet been cleared by a stable run. */
	restarts: number;
	/** When the next restart attempt is due, while in "backoff". */
	nextRestartAt?: string;
	lastExitCode?: number;
	lastExitSignal?: string;
	lastError?: string;
};

export type ConnectorStartRequest = {
	channel: string;
	instanceId: string;
	/** Connector CLI arguments, excluding the channel name itself. */
	args: string[];
	/**
	 * Replace a running instance instead of reporting it as already running.
	 * Used by `connect --restart`.
	 */
	restart?: boolean;
};

export type ConnectorStartResult = {
	/** False when an instance was already running and `restart` was not set. */
	started: boolean;
	record: SupervisedConnectorRecord;
	/** Why `started` is false, when it is. */
	reason?: "already_running";
};

export type ConnectorStopRequest = {
	channel: string;
	instanceId: string;
	/** Stop auto-restarting this instance as well. Defaults to true. */
	disableAutostart?: boolean;
};

export type ConnectorStopResultPayload = {
	stopped: boolean;
	channel: string;
	instanceId: string;
};

/**
 * Shared types describing automation cron specs parsed from Markdown files.
 * Split out from `@cline/core` so the parser can live in `shared` where
 * multiple consumers (hub daemon, CLI tools, enterprise adapters) can validate
 * the same `.cline/cron/` spec format without pulling in core's stateful
 * orchestration layer.
 */

export type CronTriggerKind = "one_off" | "schedule" | "event";

/**
 * Which trigger kind was inferred from the source file path.
 * - `*.cron.md` -> schedule
 * - `events/*.event.md` -> event
 * - everything else under `.cline/cron/*.md` -> one_off
 */
export interface CronSpecModelSelection {
	providerId?: string;
	modelId?: string;
}

export type CronSpecMode = "act" | "plan" | "yolo";
export type CronSpecExtensionKind = "rules" | "skills" | "plugins";

export interface CronSpecCommonFields {
	/** Optional explicit id from frontmatter; falls back to relative path. */
	id?: string;
	title?: string;
	prompt?: string;
	workspaceRoot?: string;
	mode?: CronSpecMode;
	systemPrompt?: string;
	modelSelection?: CronSpecModelSelection;
	maxIterations?: number;
	timeoutSeconds?: number;
	tools?: string[];
	notesDirectory?: string;
	extensions?: CronSpecExtensionKind[];
	source?: string;
	tags?: string[];
	enabled?: boolean;
	metadata?: Record<string, unknown>;
}

export interface CronOneOffSpec extends CronSpecCommonFields {
	triggerKind: "one_off";
}

export interface CronScheduleSpec extends CronSpecCommonFields {
	triggerKind: "schedule";
	schedule: string;
	timezone?: string;
}

export interface CronEventSpec extends CronSpecCommonFields {
	triggerKind: "event";
	event: string;
	filters?: Record<string, unknown>;
	debounceSeconds?: number;
	dedupeWindowSeconds?: number;
	cooldownSeconds?: number;
	maxParallel?: number;
}

export type CronSpec = CronOneOffSpec | CronScheduleSpec | CronEventSpec;

/**
 * Result of parsing one file. Always produces a record — even invalid specs
 * are surfaced so the store can durably record parse errors rather than
 * silently dropping state.
 */
export interface CronSpecParseResult {
	/** Stable external identity: frontmatter `id` or normalized relative path. */
	externalId: string;
	/** Normalized posix-style path relative to `.cline/cron/`. */
	relativePath: string;
	/** Trigger kind inferred from file naming. */
	triggerKind: CronTriggerKind;
	/** Raw file body (without frontmatter). */
	body: string;
	/** sha256 of canonical frontmatter JSON + body. */
	contentHash: string;
	/** When the parse succeeded. */
	spec?: CronSpec;
	/** Parse error message when the spec is invalid. */
	error?: string;
}

/**
 * Normalized automation event envelope. Used by the event-driven feature
 * (Feature 2) but defined here so core, adapters, and shared validation
 * agree on the shape from day one.
 */
export interface AutomationEventEnvelope {
	eventId: string;
	eventType: string;
	source: string;
	subject?: string;
	occurredAt: string;
	workspaceRoot?: string;
	payload?: Record<string, unknown>;
	attributes?: Record<string, unknown>;
	dedupeKey?: string;
}

import {
	existsSync,
	mkdirSync,
	mkdtempSync,
	rmSync,
	writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { SqliteConnectorStore } from "./connector-store";

describe("SqliteConnectorStore", () => {
	const previousDataDir = process.env.CLINE_DATA_DIR;
	const previousSettingsPath = process.env.CLINE_CONNECTOR_SETTINGS_PATH;
	const previousDbPath = process.env.CLINE_CONNECTORS_DB_PATH;
	const tempRoots: string[] = [];

	afterEach(() => {
		process.env.CLINE_DATA_DIR = previousDataDir;
		process.env.CLINE_CONNECTOR_SETTINGS_PATH = previousSettingsPath;
		process.env.CLINE_CONNECTORS_DB_PATH = previousDbPath;
		if (previousDataDir === undefined) delete process.env.CLINE_DATA_DIR;
		if (previousSettingsPath === undefined)
			delete process.env.CLINE_CONNECTOR_SETTINGS_PATH;
		if (previousDbPath === undefined)
			delete process.env.CLINE_CONNECTORS_DB_PATH;
		for (const root of tempRoots.splice(0)) {
			rmSync(root, { recursive: true, force: true });
		}
	});

	function useTempDataDir(): string {
		const root = mkdtempSync(join(tmpdir(), "connector-store-"));
		tempRoots.push(root);
		process.env.CLINE_DATA_DIR = root;
		delete process.env.CLINE_CONNECTOR_SETTINGS_PATH;
		delete process.env.CLINE_CONNECTORS_DB_PATH;
		return root;
	}

	function withStore<T>(fn: (store: SqliteConnectorStore) => T): T {
		const store = new SqliteConnectorStore();
		try {
			return fn(store);
		} finally {
			store.close();
		}
	}

	it("upserts and reads connector configuration", () => {
		useTempDataDir();
		withStore((store) => {
			store.upsertConfig({
				channel: "telegram",
				values: { "-k": "123:token" },
				security: { enabled: true, values: { userId: "42" } },
			});
			const record = store.getConfig("telegram");
			expect(record?.type).toBe("telegram");
			expect(record?.values).toEqual({ "-k": "123:token" });
			expect(record?.security).toEqual({
				enabled: true,
				values: { userId: "42" },
			});
		});
	});

	it("refreshes stored launch args while preserving autostart state", () => {
		useTempDataDir();
		withStore((store) => {
			store.recordConnected("telegram", "cline_bot", ["-k", "123:token"]);
			store.setEnabled("telegram", false);
			store.upsertConfig({
				channel: "telegram",
				values: { "-k": "456:rotated" },
			});
			expect(store.getConnection("telegram", "cline_bot")?.connectArgs).toEqual(
				["-k", "123:token"],
			);
			store.upsertConfig({
				channel: "telegram",
				values: { "-k": "456:rotated" },
				updateConnectArgs: () => ["-k", "456:rotated"],
			});
			expect(store.getConfig("telegram")?.values).toEqual({
				"-k": "456:rotated",
			});
			const connection = store.getConnection("telegram", "cline_bot");
			expect(connection?.connectArgs).toEqual(["-k", "456:rotated"]);
			expect(connection?.lastSuccessfulArgs).toEqual(["-k", "123:token"]);
			expect(connection?.enabled).toBe(false);
		});
	});

	it("records each instance independently and re-enables only the restarted one", () => {
		useTempDataDir();
		withStore((store) => {
			store.recordConnected("slack", "workspace-a", [
				"--bot-token",
				"xoxb",
				"--app-token",
				"xapp",
			]);
			store.recordConnected("slack", "workspace-b", [
				"--bot-token",
				"xoxb-other",
			]);
			expect(store.getConfig("slack")).toBeUndefined();
			expect(store.listConnections("slack")).toHaveLength(2);

			store.setEnabled("slack", false);
			expect(
				store.listConnections("slack").every((entry) => !entry.enabled),
			).toBe(true);

			store.recordConnected("slack", "workspace-a", ["--bot-token", "xoxb2"]);
			expect(store.getConnection("slack", "workspace-a")).toEqual(
				expect.objectContaining({
					enabled: true,
					connectArgs: ["--bot-token", "xoxb2"],
				}),
			);
			expect(store.getConnection("slack", "workspace-b")?.enabled).toBe(false);
		});
	});

	it("round-trips empty connect args for env-only starts", () => {
		useTempDataDir();
		withStore((store) => {
			store.recordConnected("telegram", "cline_bot", []);

			expect(store.getConnection("telegram", "cline_bot")?.connectArgs).toEqual(
				[],
			);
			expect(store.getConnection("telegram", "cline_bot")?.enabled).toBe(true);
		});
	});

	it("disables autostart for all connectors", () => {
		useTempDataDir();
		withStore((store) => {
			store.recordConnected("slack", "workspace", ["--bot-token", "xoxb"]);
			store.recordConnected("telegram", "cline_bot", ["-k", "123:token"]);
			store.disableAll();
			expect(store.listConnections().every((entry) => !entry.enabled)).toBe(
				true,
			);
		});
	});

	it("deletes dashboard config without clearing CLI autostart state", () => {
		useTempDataDir();
		withStore((store) => {
			store.recordConnected("telegram", "cline_bot", ["-k", "123:token"]);
			store.upsertConfig({
				channel: "telegram",
				values: { "-k": "123:token" },
				security: { enabled: true, values: { userId: "42" } },
			});

			expect(store.deleteConfig("telegram")).toBe(true);
			expect(store.getConfig("telegram")).toBeUndefined();
			expect(store.getConnection("telegram", "cline_bot")).toEqual(
				expect.objectContaining({
					channel: "telegram",
					instanceId: "cline_bot",
					connectArgs: ["-k", "123:token"],
					enabled: true,
				}),
			);
			expect(store.deleteConfig("telegram")).toBe(false);
		});
	});

	it("removes config-only rows when dashboard config is deleted", () => {
		useTempDataDir();
		withStore((store) => {
			store.upsertConfig({
				channel: "telegram",
				values: { "-k": "123:token" },
			});

			expect(store.deleteConfig("telegram")).toBe(true);
			expect(store.getConfig("telegram")).toBeUndefined();
		});
	});

	it("saves channel-wide config without rewriting ambiguous instance args", () => {
		useTempDataDir();
		withStore((store) => {
			store.recordConnected("telegram", "first_bot", ["-k", "first:token"]);
			store.recordConnected("telegram", "second_bot", ["-k", "second:token"]);

			store.upsertConfig({
				channel: "telegram",
				values: { "-k": "replacement:token" },
				updateConnectArgs: () => ["-k", "replacement:token"],
			});

			expect(store.getConfig("telegram")?.values).toEqual({
				"-k": "replacement:token",
			});
			expect(
				store.listConnections("telegram").map((entry) => entry.connectArgs),
			).toEqual([
				["-k", "first:token"],
				["-k", "second:token"],
			]);
		});
	});

	it("imports the legacy JSON settings file once and renames it", () => {
		const root = useTempDataDir();
		const legacyPath = join(root, "connectors", "settings.json");
		mkdirSync(dirname(legacyPath), { recursive: true });
		writeFileSync(
			legacyPath,
			JSON.stringify({
				version: 1,
				connectors: {
					telegram: {
						type: "telegram",
						values: { "-k": "123:legacy-token" },
						security: { enabled: true, values: { userId: "7" } },
						configuredAt: "2026-01-01T00:00:00.000Z",
						updatedAt: "2026-01-02T00:00:00.000Z",
					},
				},
			}),
			"utf8",
		);

		withStore((store) => {
			const record = store.getConfig("telegram");
			expect(record?.values).toEqual({ "-k": "123:legacy-token" });
			expect(record?.security).toEqual({
				enabled: true,
				values: { userId: "7" },
			});
			expect(record?.configuredAt).toBe("2026-01-01T00:00:00.000Z");
		});

		expect(existsSync(legacyPath)).toBe(false);
		expect(existsSync(`${legacyPath}.migrated`)).toBe(true);
	});

	it("does not overwrite existing rows during legacy import", () => {
		const root = useTempDataDir();
		withStore((store) => {
			store.upsertConfig({
				channel: "telegram",
				values: { "-k": "123:current" },
			});
		});

		const legacyPath = join(root, "connectors", "settings.json");
		mkdirSync(dirname(legacyPath), { recursive: true });
		writeFileSync(
			legacyPath,
			JSON.stringify({
				version: 1,
				connectors: {
					telegram: {
						type: "telegram",
						values: { "-k": "999:stale" },
						configuredAt: "2026-01-01T00:00:00.000Z",
						updatedAt: "2026-01-01T00:00:00.000Z",
					},
				},
			}),
			"utf8",
		);

		withStore((store) => {
			expect(store.getConfig("telegram")?.values).toEqual({
				"-k": "123:current",
			});
		});
	});
});

import { existsSync, readFileSync, renameSync } from "node:fs";
import {
	resolveConnectorSettingsPath,
	resolveConnectorsDbPath,
} from "../storage/paths";
import {
	asOptionalString,
	asString,
	loadSqliteDb,
	nowIso,
	type SqliteDb,
	toBoolInt,
} from "./sqlite-db";

export interface ConnectorSecurityConfig {
	enabled: boolean;
	values: Record<string, string>;
}

/** Dashboard-managed configuration for a connector channel. */
export interface ConnectorConfigRecord {
	channel: string;
	type: string;
	values: Record<string, string>;
	security?: ConnectorSecurityConfig;
	configuredAt: string;
	updatedAt: string;
}

/** A successfully launched connector instance eligible for auto-reconnect. */
export interface ConnectorConnectionRecord {
	channel: string;
	instanceId: string;
	connectArgs: string[];
	lastSuccessfulArgs: string[];
	enabled: boolean;
	updatedAt: string;
	lastConnectedAt: string;
}

const CONNECTOR_CONFIG_SCHEMA = `CREATE TABLE IF NOT EXISTS connector_configs (
	channel TEXT PRIMARY KEY,
	type TEXT NOT NULL,
	values_json TEXT NOT NULL DEFAULT '{}',
	security_enabled INTEGER NOT NULL DEFAULT 0,
	security_values_json TEXT NOT NULL DEFAULT '{}',
	configured_at TEXT NOT NULL,
	updated_at TEXT NOT NULL
);`;

const CONNECTOR_CONNECTION_SCHEMA = `CREATE TABLE IF NOT EXISTS connector_connections (
	channel TEXT NOT NULL,
	instance_id TEXT NOT NULL,
	connect_args_json TEXT NOT NULL,
	last_successful_args_json TEXT NOT NULL,
	enabled INTEGER NOT NULL DEFAULT 1,
	updated_at TEXT NOT NULL,
	last_connected_at TEXT NOT NULL,
	PRIMARY KEY (channel, instance_id)
);`;

export function ensureConnectorSchema(db: SqliteDb): void {
	db.exec("PRAGMA journal_mode = WAL;");
	db.exec("PRAGMA busy_timeout = 5000;");
	db.exec(CONNECTOR_CONFIG_SCHEMA);
	db.exec(CONNECTOR_CONNECTION_SCHEMA);
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parseStringRecord(raw: unknown): Record<string, string> {
	if (typeof raw !== "string" || !raw) {
		return {};
	}
	try {
		const parsed = JSON.parse(raw) as unknown;
		if (!isRecord(parsed)) {
			return {};
		}
		const entries: Record<string, string> = {};
		for (const [key, value] of Object.entries(parsed)) {
			if (typeof value === "string") {
				entries[key] = value;
			}
		}
		return entries;
	} catch {
		return {};
	}
}

function parseStringArray(raw: unknown): string[] | undefined {
	if (typeof raw !== "string" || !raw) {
		return undefined;
	}
	try {
		const parsed = JSON.parse(raw) as unknown;
		if (!Array.isArray(parsed)) {
			return undefined;
		}
		return parsed.filter((value) => typeof value === "string");
	} catch {
		return undefined;
	}
}

export interface SqliteConnectorStoreOptions {
	dbPath?: string;
}

/**
 * SQLite-backed store for connector configuration and credentials.
 * Replaces the legacy `~/.cline/data/connectors/settings.json` file; any
 * existing legacy file is imported on first open and renamed so the two
 * stores cannot diverge.
 */
export class SqliteConnectorStore {
	private readonly dbPath: string;
	private db: SqliteDb | undefined;

	constructor(options: SqliteConnectorStoreOptions = {}) {
		this.dbPath = options.dbPath ?? resolveConnectorsDbPath();
	}

	private getRawDb(): SqliteDb {
		if (this.db) {
			return this.db;
		}
		const db = loadSqliteDb(this.dbPath);
		ensureConnectorSchema(db);
		this.db = db;
		this.importLegacyJsonSettings();
		return db;
	}

	close(): void {
		this.db?.close?.();
		this.db = undefined;
	}

	getConfig(channel: string): ConnectorConfigRecord | undefined {
		const row = this.getRawDb()
			.prepare(`SELECT * FROM connector_configs WHERE channel = ?`)
			.get(channel);
		return row ? rowToConfigRecord(row) : undefined;
	}

	listConfigs(): ConnectorConfigRecord[] {
		return this.getRawDb()
			.prepare(`SELECT * FROM connector_configs ORDER BY channel ASC`)
			.all()
			.map(rowToConfigRecord);
	}

	getConnection(
		channel: string,
		instanceId: string,
	): ConnectorConnectionRecord | undefined {
		const row = this.getRawDb()
			.prepare(
				`SELECT * FROM connector_connections
				 WHERE channel = ? AND instance_id = ?`,
			)
			.get(channel, instanceId);
		return row ? rowToConnectionRecord(row) : undefined;
	}

	listConnections(channel?: string): ConnectorConnectionRecord[] {
		const rows = channel
			? this.getRawDb()
					.prepare(
						`SELECT * FROM connector_connections
						 WHERE channel = ?
						 ORDER BY instance_id ASC`,
					)
					.all(channel)
			: this.getRawDb()
					.prepare(
						`SELECT * FROM connector_connections
						 ORDER BY channel ASC, instance_id ASC`,
					)
					.all();
		return rows.map(rowToConnectionRecord);
	}

	/**
	 * Create or update dashboard configuration. If exactly one persisted
	 * instance exists, its desired reconnect arguments may be updated
	 * atomically. With multiple instances, only the channel-wide dashboard
	 * configuration is updated because choosing reconnect args is ambiguous.
	 */
	upsertConfig(entry: {
		channel: string;
		type?: string;
		values: Record<string, string>;
		security?: ConnectorSecurityConfig;
		updateConnectArgs?: (existing: {
			config?: ConnectorConfigRecord;
			connection: ConnectorConnectionRecord;
		}) => string[];
		configuredAt?: string;
		updatedAt?: string;
	}): void {
		const now = nowIso();
		const db = this.getRawDb();
		db.exec("BEGIN IMMEDIATE;");
		try {
			const existingConfigRow = db
				.prepare(`SELECT * FROM connector_configs WHERE channel = ?`)
				.get(entry.channel);
			const existingConfig = existingConfigRow
				? rowToConfigRecord(existingConfigRow)
				: undefined;
			const connectionRows = db
				.prepare(`SELECT * FROM connector_connections WHERE channel = ?`)
				.all(entry.channel);
			const connections = connectionRows.map(rowToConnectionRecord);
			const updatedConnectionArgs =
				entry.updateConnectArgs && connections.length === 1 && connections[0]
					? entry.updateConnectArgs({
							config: existingConfig,
							connection: connections[0],
						})
					: undefined;
			db.prepare(
				`INSERT INTO connector_configs (
					channel, type, values_json, security_enabled,
					security_values_json, configured_at, updated_at
				) VALUES (?, ?, ?, ?, ?, ?, ?)
				ON CONFLICT(channel) DO UPDATE SET
					type = excluded.type,
					values_json = excluded.values_json,
					security_enabled = excluded.security_enabled,
					security_values_json = excluded.security_values_json,
					configured_at = excluded.configured_at,
					updated_at = excluded.updated_at`,
			).run(
				entry.channel,
				entry.type ?? entry.channel,
				JSON.stringify(entry.values),
				toBoolInt(entry.security?.enabled === true),
				JSON.stringify(entry.security?.values ?? {}),
				entry.configuredAt ?? existingConfig?.configuredAt ?? now,
				entry.updatedAt ?? now,
			);
			if (updatedConnectionArgs && connections[0]) {
				db.prepare(
					`UPDATE connector_connections
					 SET connect_args_json = ?, updated_at = ?
					 WHERE channel = ? AND instance_id = ?`,
				).run(
					JSON.stringify(updatedConnectionArgs),
					now,
					entry.channel,
					connections[0].instanceId,
				);
			}
			db.exec("COMMIT;");
		} catch (error) {
			try {
				db.exec("ROLLBACK;");
			} catch {
				// Preserve the original transaction failure.
			}
			throw error;
		}
	}

	/**
	 * Record a successful `cline connect <channel>` start: keep the exact args
	 * (auth flags included) for auto-reconnect and re-enable the channel.
	 */
	recordConnected(
		channel: string,
		instanceId: string,
		connectArgs: string[],
	): void {
		const now = nowIso();
		this.getRawDb()
			.prepare(
				`INSERT INTO connector_connections (
					channel, instance_id, connect_args_json,
					last_successful_args_json, enabled, updated_at, last_connected_at
				) VALUES (?, ?, ?, ?, 1, ?, ?)
				ON CONFLICT(channel, instance_id) DO UPDATE SET
					connect_args_json = excluded.connect_args_json,
					last_successful_args_json = excluded.last_successful_args_json,
					enabled = 1,
					updated_at = excluded.updated_at,
					last_connected_at = excluded.last_connected_at`,
			)
			.run(
				channel,
				instanceId,
				JSON.stringify(connectArgs),
				JSON.stringify(connectArgs),
				now,
				now,
			);
	}

	/** Toggle auto-reconnect for one instance or every instance in a channel. */
	setEnabled(channel: string, enabled: boolean, instanceId?: string): void {
		if (instanceId) {
			this.getRawDb()
				.prepare(
					`UPDATE connector_connections
					 SET enabled = ?, updated_at = ?
					 WHERE channel = ? AND instance_id = ?`,
				)
				.run(toBoolInt(enabled), nowIso(), channel, instanceId);
			return;
		}
		this.getRawDb()
			.prepare(
				`UPDATE connector_connections
				 SET enabled = ?, updated_at = ?
				 WHERE channel = ?`,
			)
			.run(toBoolInt(enabled), nowIso(), channel);
	}

	deleteConnection(channel: string, instanceId: string): boolean {
		const changes =
			this.getRawDb()
				.prepare(
					`DELETE FROM connector_connections
					 WHERE channel = ? AND instance_id = ?`,
				)
				.run(channel, instanceId).changes ?? 0;
		return changes > 0;
	}

	disableAll(): void {
		this.getRawDb()
			.prepare(`UPDATE connector_connections SET enabled = 0, updated_at = ?`)
			.run(nowIso());
	}

	/**
	 * Remove only dashboard-managed configuration. Persisted CLI instances live
	 * in a separate table and are intentionally unaffected.
	 */
	deleteConfig(channel: string): boolean {
		const changes =
			this.getRawDb()
				.prepare(`DELETE FROM connector_configs WHERE channel = ?`)
				.run(channel).changes ?? 0;
		return changes > 0;
	}

	/**
	 * One-time import of the legacy JSON settings file. Existing DB rows win;
	 * the file is renamed (not deleted) afterwards so older builds cannot keep
	 * writing to a store that is no longer read.
	 */
	private importLegacyJsonSettings(): void {
		const legacyPath = resolveConnectorSettingsPath();
		if (!existsSync(legacyPath)) {
			return;
		}
		try {
			const parsed = JSON.parse(readFileSync(legacyPath, "utf8")) as unknown;
			const connectors =
				isRecord(parsed) && isRecord(parsed.connectors)
					? parsed.connectors
					: {};
			for (const [channel, value] of Object.entries(connectors)) {
				if (!isRecord(value) || this.getConfig(channel)) {
					continue;
				}
				const values: Record<string, string> = {};
				if (isRecord(value.values)) {
					for (const [key, raw] of Object.entries(value.values)) {
						if (typeof raw === "string") {
							values[key] = raw;
						}
					}
				}
				const securityValues: Record<string, string> = {};
				const security = isRecord(value.security) ? value.security : undefined;
				if (security && isRecord(security.values)) {
					for (const [key, raw] of Object.entries(security.values)) {
						if (typeof raw === "string") {
							securityValues[key] = raw;
						}
					}
				}
				this.upsertConfig({
					channel,
					type: typeof value.type === "string" ? value.type : channel,
					values,
					security: security
						? { enabled: security.enabled === true, values: securityValues }
						: undefined,
					configuredAt:
						typeof value.configuredAt === "string"
							? value.configuredAt
							: undefined,
					updatedAt:
						typeof value.updatedAt === "string" ? value.updatedAt : undefined,
				});
			}
			renameSync(legacyPath, `${legacyPath}.migrated`);
		} catch {
			// Leave an unreadable legacy file in place; the DB is authoritative.
		}
	}
}

function rowToConfigRecord(
	row: Record<string, unknown>,
): ConnectorConfigRecord {
	const securityEnabled = row.security_enabled === 1;
	const securityValues = parseStringRecord(row.security_values_json);
	const hasSecurity = securityEnabled || Object.keys(securityValues).length > 0;
	return {
		channel: asString(row.channel),
		type: asString(row.type),
		values: parseStringRecord(row.values_json),
		security: hasSecurity
			? { enabled: securityEnabled, values: securityValues }
			: undefined,
		configuredAt: asString(row.configured_at),
		updatedAt: asString(row.updated_at),
	};
}

function rowToConnectionRecord(
	row: Record<string, unknown>,
): ConnectorConnectionRecord {
	return {
		channel: asString(row.channel),
		instanceId: asString(row.instance_id),
		connectArgs: parseStringArray(row.connect_args_json) ?? [],
		lastSuccessfulArgs: parseStringArray(row.last_successful_args_json) ?? [],
		enabled: row.enabled === 1,
		updatedAt: asString(row.updated_at),
		lastConnectedAt:
			asOptionalString(row.last_connected_at) ?? asString(row.updated_at),
	};
}

/**
 * Convenience wrapper that opens the store, runs `fn`, and always closes the
 * DB handle. Suitable for the infrequent configure/connect/stop operations;
 * long-lived processes that poll the store should hold their own instance.
 */
export function withConnectorStore<T>(
	fn: (store: SqliteConnectorStore) => T,
): T {
	const store = new SqliteConnectorStore();
	try {
		return fn(store);
	} finally {
		store.close();
	}
}

