		column: "metadata_json",
		sql: "ALTER TABLE sessions ADD COLUMN metadata_json TEXT;",
	},
	{
		table: "sessions",
		column: "transcript_path",
		sql: "ALTER TABLE sessions ADD COLUMN transcript_path TEXT NOT NULL DEFAULT '';",
	},
	{
		table: "schedules",
		column: "claim_token",
		sql: "ALTER TABLE schedules ADD COLUMN claim_token TEXT;",
	},
	{
		table: "schedules",
		column: "claim_started_at",
		sql: "ALTER TABLE schedules ADD COLUMN claim_started_at TEXT;",
	},
	{
		table: "schedules",
		column: "claim_until_at",
		sql: "ALTER TABLE schedules ADD COLUMN claim_until_at TEXT;",
	},
];

function getColumnNames(db: SqliteDb, table: string): Set<string> {
	return new Set(
		db
			.prepare(`PRAGMA table_info(${table});`)
			.all()
			.map((c) => c.name as string),
	);
}

export function ensureSessionSchema(
	db: SqliteDb,
	options: SessionSchemaOptions = {},
): void {
	db.exec("PRAGMA journal_mode = WAL;");
	db.exec("PRAGMA busy_timeout = 5000;");
	for (const stmt of SCHEMA_STATEMENTS) {
		db.exec(stmt);
	}

	if (!options.includeLegacyMigrations) return;

	const columnCache = new Map<string, Set<string>>();
	const getColumns = (table: string) => {
		let cols = columnCache.get(table);
		if (!cols) {
			cols = getColumnNames(db, table);
			columnCache.set(table, cols);
		}
		return cols;
	};

	for (const migration of LEGACY_MIGRATIONS) {
		if (!getColumns(migration.table).has(migration.column)) {
			db.exec(migration.sql);
			if (migration.column === "workspace_root") {
				db.exec(
					"UPDATE sessions SET workspace_root = cwd WHERE workspace_root IS NULL OR workspace_root = '';",
				);
			}
			columnCache.delete(migration.table);
		}
	}
}

export type Disposable =
	| (() => void | Promise<void>)
	| { dispose: () => void | Promise<void> };

const registry: Disposable[] = [];

/**
 * Register a disposable to be cleaned up when `disposeAll()` is called.
 * Accepts either a function or an object with a `dispose` method.
 */
export function registerDisposable(disposable: Disposable): void {
	registry.push(disposable);
}

/**
 * Dispose all registered disposables in registration order.
 * Errors from individual disposables are suppressed so all run.
 */
export async function disposeAll(): Promise<void> {
	const items = registry.splice(0);
	await Promise.all(
		items.map((d) => {
			try {
				const result = typeof d === "function" ? d() : d.dispose();
				return result ?? Promise.resolve();
			} catch {
				return Promise.resolve();
			}
		}),
	);
}

import type { BasicLogger } from "../logging/logger";
import type { ITelemetryService } from "../services/telemetry";
import type { WorkspaceInfo } from "../session/workspace";
import type {
	AgentExtensionAutomationContext,
	AgentExtensionSessionContext,
} from "./contribution-registry";

/**
 * The IDE or client surface the user is running Cline from.
 */
export type ClientName =
	| "cline-vscode"
	| "cline-jetbrains"
	| "cline-cli"
	| "cline-sdk"
	| "cline-kanban"
	| "cline-acp"
	| "cline-platform"
	| (string & {});

/**
 * Identity of the calling client and host surface.
 */
export interface ClientContext {
	/** Client type emitted to Cline request headers, e.g. "VSCode Extension", "cline-cli", "cline-sdk" */
	name: ClientName;
	/** Cline client/extension semver string, e.g. "3.12.0" */
	version?: string;
	/** Host platform display name, e.g. "Visual Studio Code", "Cursor", "cli" */
	platform?: string;
	/** Host platform version, e.g. vscode.version or the CLI version */
	platformVersion?: string;
	/** Whether the host workspace currently has multiple roots. */
	isMultiRoot?: boolean;
}

/**
 * Identity of the authenticated user.
 */
export interface UserContext {
	/** PostHog / analytics distinct ID */
	distinctId?: string;
	email?: string;
	organizationId?: string;
}

/**
 * Everything needed to describe the workspace and build the system prompt.
 *
 * Extends WorkspaceInfo (rootPath + git fields) with the additional fields
 * required by buildClineSystemPrompt, so callers can spread a WorkspaceInfo
 * and add only what they know.
 */
export interface WorkspaceContext extends WorkspaceInfo {
	/**
	 * Current working directory. May differ from rootPath in multi-root
	 * workspaces or when the user cd'd inside the workspace.
	 */
	cwd?: string;
	/** Human-readable workspace name shown in the system prompt */
	workspaceName?: string;
	/**
	 * Pre-serialized workspace metadata block that replaces {{CLINE_METADATA}}
	 * in the system prompt template.
	 */
	metadata?: string;
	/** Agent mode: "act" | "plan" | "yolo" */
	mode?: string;
	/** Additional rules/instructions injected into the system prompt */
	rules?: string;
	/** IDE display name, e.g. "VS Code", "JetBrains", "Terminal Shell" */
	ide?: string;
	/** Node process.platform string, e.g. "darwin", "win32", "linux" */
	platform?: string;
}

/**
 * Ambient runtime context carried alongside ProviderConfig.
 *
 * Captures who is calling (user + client), where they are (workspace),
 * and which services to use for logging and telemetry. None of these
 * belong in the LLM provider credential config.
 */
export interface ExtensionContext {
	user?: UserContext;
	client?: ClientContext;
	workspace?: WorkspaceContext;
	/** Core session metadata forwarded into plugin setup context. */
	session?: AgentExtensionSessionContext;
	/**
	 * Host-provided automation ingress for plugins. Present when the session is
	 * started through a ClineCore instance with automation enabled.
	 */
	automation?: AgentExtensionAutomationContext;
	logger?: BasicLogger;
	telemetry?: ITelemetryService;
}

import { describe, expect, it, vi } from "vitest";
import { createContributionRegistry } from "./contribution-registry";

describe("ContributionRegistry automation event contributions", () => {
	it("accepts skills-only plugins without setup contributions", async () => {
		const registry = createContributionRegistry({
			extensions: [
				{
					name: "skill-pack",
					manifest: { capabilities: ["skills"] },
				},
			],
		});

		await expect(registry.initialize()).resolves.toBeUndefined();
		expect(registry.getRegistrySnapshot()).toMatchObject({
			tools: [],
			commands: [],
			rules: [],
			messageBuilder: [],
			providers: [],
			automationEventTypes: [],
			mcpServers: [],
		});
	});

	it("registers automation event types declared by plugins", async () => {
		const registry = createContributionRegistry({
			extensions: [
				{
					name: "local-events",
					manifest: { capabilities: ["automationEvents"] },
					setup(api) {
						api.registerAutomationEventType({
							eventType: " local.manual_test ",
							source: " local ",
							description: "Manual local smoke test",
							attributesSchema: {
								type: "object",
								properties: { topic: { type: "string" } },
							},
							examples: [
								{
									eventId: "evt_1",
									eventType: "local.manual_test",
									source: "local",
									occurredAt: "2026-04-24T10:00:00.000Z",
									attributes: { topic: "cron-feature-2" },
								},
							],
						});
					},
				},
			],
		});

		await registry.initialize();

		expect(registry.getRegistrySnapshot().automationEventTypes).toEqual([
			expect.objectContaining({
				eventType: "local.manual_test",
				source: "local",
				description: "Manual local smoke test",
			}),
		]);
		expect(registry.getRegisteredAutomationEventTypes()).toHaveLength(1);
	});

	it("passes automation ingestion context into setup", async () => {
		const ingestEvent = vi.fn();
		const registry = createContributionRegistry({
			setupContext: {
				automation: { ingestEvent },
			},
			extensions: [
				{
					name: "event-source",
					manifest: { capabilities: ["automationEvents"] },
					setup(_api, ctx) {
						ctx.automation?.ingestEvent({
							eventId: "evt_plugin_1",
							eventType: "local.plugin_event",
							source: "local-plugin",
							occurredAt: "2026-04-24T10:00:00.000Z",
						});
					},
				},
			],
		});

		await registry.initialize();

		expect(ingestEvent).toHaveBeenCalledWith(
			expect.objectContaining({
				eventId: "evt_plugin_1",
				eventType: "local.plugin_event",
			}),
		);
	});

	it("passes caller identity and logger context into setup", async () => {
		const logger = {
			debug: vi.fn(),
			log: vi.fn(),
			error: vi.fn(),
		};
		const registry = createContributionRegistry({
			setupContext: {
				session: { sessionId: "sess-1" },
				client: { name: "cline-sdk", version: "1.0.0" },
				user: { distinctId: "user-1" },
				workspaceInfo: { rootPath: "/tmp/workspace" },
				logger,
			},
			extensions: [
				{
					name: "context-plugin",
					manifest: { capabilities: ["tools"] },
					setup(_api, ctx) {
						ctx.logger?.log("plugin setup", {
							sessionId: ctx.session?.sessionId,
							client: ctx.client?.name,
						});
					},
				},
			],
		});

		await registry.initialize();

		expect(logger.log).toHaveBeenCalledWith("plugin setup", {
			sessionId: "sess-1",
			client: "cline-sdk",
		});
	});

	it("requires the automationEvents capability before registration", async () => {
		const registry = createContributionRegistry({
			extensions: [
				{
					name: "missing-capability",
					manifest: { capabilities: ["tools"] },
					setup(api) {
						api.registerAutomationEventType({
							eventType: "local.bad",
							source: "local",
						});
					},
				},
			],
		});

		await expect(registry.initialize()).rejects.toThrow(
			/registerAutomationEventType requires the "automationEvents" capability/,
		);
	});

	it("registers MCP servers declared by plugins", async () => {
		const registry = createContributionRegistry({
			extensions: [
				{
					name: "github-pack",
					manifest: { capabilities: ["mcp"] },
					setup(api) {
						api.registerMcpServer({
							name: "github",
							transport: {
								type: "stdio",
								command: "npx",
								args: ["-y", "@modelcontextprotocol/server-github"],
							},
						});
					},
				},
			],
		});

		await registry.initialize();

		expect(registry.getRegisteredMcpServers()).toEqual([
			expect.objectContaining({
				name: "github",
				metadata: {
					source: "plugin",
					plugin: "github-pack",
				},
			}),
		]);
	});
});

import type { AgentRuntimeHooks, AgentTool } from "../agent";
import type { AutomationEventEnvelope } from "../cron";
import type { BasicLogger } from "../logging/logger";
import type { ITelemetryService } from "../services/telemetry";
import type { WorkspaceInfo } from "../session/workspace";
import type { ClientContext, UserContext } from "./context";

export interface AgentExtensionCommand {
	name: string;
	description?: string;
	handler?: (
		input: string,
	) => Promise<AgentExtensionCommandResult> | AgentExtensionCommandResult;
}

export type AgentExtensionCommandResult =
	| string
	| {
			reply?: string;
			submitPrompt?: string;
	  };

export interface AgentExtensionRule {
	id: string;
	content: string | (() => string | Promise<string>);
	source?: string;
}

export interface AgentExtensionMessageBuilder<TMessage = unknown> {
	name: string;
	build: (message: TMessage) => TMessage | Promise<TMessage>;
}

export interface AgentExtensionProvider {
	name: string;
	description?: string;
	metadata?: Record<string, unknown>;
}

export interface AgentExtensionAutomationEventType {
	/** Normalized event type a plugin can emit, e.g. `github.pull_request.opened`. */
	eventType: string;
	/** Normalized source identifier, e.g. `github`, `linear`, or `local`. */
	source: string;
	description?: string;
	attributesSchema?: Record<string, unknown>;
	payloadSchema?: Record<string, unknown>;
	examples?: AutomationEventEnvelope[];
	metadata?: Record<string, unknown>;
}

export interface AgentExtensionMcpEnvValue {
	// Read this environment variable from the host process. Defaults to the target env var name.
	fromEnv?: string;
	// Literal fallback value used when `fromEnv` is omitted or not set.
	value?: string;
	// Skip the MCP server when no value can be resolved.
	required?: boolean;
}

export type AgentExtensionMcpEnv = Record<
	string,
	string | AgentExtensionMcpEnvValue
>;

export interface AgentExtensionMcpStdioTransport {
	type: "stdio";
	command: string;
	args?: string[];
	cwd?: string;
	env?: Record<string, string>;
}

export interface AgentExtensionMcpSseTransport {
	type: "sse";
	url: string;
	headers?: Record<string, string>;
}

export interface AgentExtensionMcpStreamableHttpTransport {
	type: "streamableHttp";
	url: string;
	headers?: Record<string, string>;
}

export type AgentExtensionMcpTransport =
	| AgentExtensionMcpStdioTransport
	| AgentExtensionMcpSseTransport
	| AgentExtensionMcpStreamableHttpTransport;

export interface AgentExtensionMcpServer {
	name: string;
	transport: AgentExtensionMcpTransport;
	// Top-level env values are merged into stdio process env only.
	env?: AgentExtensionMcpEnv;
	metadata?: Record<string, unknown>;
}

export interface AgentExtensionAutomationContext {
	/**
	 * Submit a normalized automation event to the host. Raw webhook or connector
	 * payloads should be translated into an `AutomationEventEnvelope` first.
	 */
	ingestEvent: (event: AutomationEventEnvelope) => void | Promise<void>;
}

export interface AgentExtensionSessionContext {
	/** Stable core session id for the root session that loaded the plugin. */
	sessionId?: string;
}

/**
 * API surface passed to an extension's `setup()` method.
 *
 * Use it to register the contributions the extension wants to make — tools,
 * commands, message builders, providers, and automation event types. All
 * registrations accumulate into the `ContributionRegistry` and are available to
 * the host after `setup()` completes.
 */
export interface AgentExtensionApi<TTool = AgentTool, TMessage = unknown> {
	/** Register a tool the agent can invoke during its run. Requires the `tools` capability. */
	registerTool: (tool: TTool) => void;
	/** Register a slash command available in connected chat surfaces. Requires the `commands` capability. */
	registerCommand: (command: AgentExtensionCommand) => void;
	/** Register prompt rules included in the runtime system prompt. Requires the `rules` capability. */
	registerRule: (rule: AgentExtensionRule) => void;
	/** Register a named message builder for transforming messages before they are sent. Requires the `messageBuilders` capability. */
	registerMessageBuilder: (
		builder: AgentExtensionMessageBuilder<TMessage>,
	) => void;
	/** Register a provider contribution (e.g. a custom model provider). Requires the `providers` capability. */
	registerProvider: (provider: AgentExtensionProvider) => void;
	/** Register a normalized automation event type the plugin can emit. Requires the `automationEvents` capability. */
	registerAutomationEventType: (
		eventType: AgentExtensionAutomationEventType,
	) => void;
	// Register an MCP server exposed as runtime tools. Requires the `mcp` capability.
	registerMcpServer: (server: AgentExtensionMcpServer) => void;
}

export type AgentExtensionHooks = Partial<AgentRuntimeHooks>;

/**
 * Session-scoped workspace context passed as the second argument to an
 * extension's `setup(api, ctx)` method.
 *
 * These values are always sourced from the host session config — never from
 * `process.cwd()`. Use them to resolve paths or build workspace-aware tool
 * schemas at registration time.
 *
 * All fields are optional so `setup()` callers that do not have host context
 * (e.g. unit tests) can omit them without breaking plugins.
 */
export interface PluginSetupContext {
	/**
	 * Core session metadata known before the first agent run starts.
	 * Agent-level ids such as `agentId` and `conversationId` are available on
	 * lifecycle hook contexts once SessionRuntime creates them.
	 */
	session?: AgentExtensionSessionContext;
	/** Host/client identity such as `cline-cli`, `cline-vscode`, or an SDK app. */
	client?: ClientContext;
	/** Authenticated user or organization identity when the host provides it. */
	user?: UserContext;
	/**
	 * Structured workspace and git metadata for the session. Contains
	 * `rootPath`, `hint`, `associatedRemoteUrls`, `latestGitCommitHash`, and
	 * `latestGitBranchName`. Use `rootPath` for workspace-relative paths and
	 * the git fields for branch-aware registration or commit attribution at
	 * setup time.
	 */
	workspaceInfo?: WorkspaceInfo;
	/**
	 * Automation ingress made available by hosts that enable ClineCore
	 * automation. Plugins should feature-detect this property so the same plugin
	 * can run in hosts that do not enable automation.
	 */
	automation?: AgentExtensionAutomationContext;
	/** Host-provided logger scoped to this session/plugin setup. */
	logger?: BasicLogger;
	/**
	 * Host-provided telemetry service. Feature-detect it
	 * (`ctx.telemetry?.capture(...)`): it is undefined when the host has no
	 * telemetry service.
	 *
	 * In-process plugins receive the host service directly. Sandboxed plugins
	 * receive a bridge — the live service cannot cross the JSON IPC boundary —
	 * that forwards `capture`/`captureRequired`/`recordCounter`/
	 * `recordHistogram`/`recordGauge` to the host, which namespaces every
	 * event and metric under `plugin.`, stamps `plugin_name`, and drops them
	 * when the user has opted out of telemetry. Bridge caveats: properties
	 * must be JSON-serializable; `isEnabled()` always reports `true` (the
	 * host is the arbiter, so do not gate expensive property computation on
	 * it); identity and common-property setters are no-ops.
	 */
	telemetry?: ITelemetryService;
}

const ExtensionCapabilityOptions = [
	"hooks",
	"tools",
	"commands",
	"rules",
	"skills",
	"messageBuilders",
	"providers",
	"automationEvents",
	"mcp",
] as const;

export type AgentExtensionCapability =
	(typeof ExtensionCapabilityOptions)[number];

export interface PluginManifest {
	paths?: string[];
	capabilities: AgentExtensionCapability[];
	providerIds?: string[];
	modelIds?: string[];
}

export interface AgentExtensionRegistry<TTool = AgentTool, TMessage = unknown> {
	tools: TTool[];
	commands: AgentExtensionCommand[];
	rules: AgentExtensionRule[];
	messageBuilder: AgentExtensionMessageBuilder<TMessage>[];
	providers: AgentExtensionProvider[];
	automationEventTypes: AgentExtensionAutomationEventType[];
	mcpServers: AgentExtensionMcpServer[];
}

/**
 * Base shape for a plugin or extension that can be loaded into a
 * `ContributionRegistry`.
 *
 * An extension declares what it does through its `manifest` (capabilities and
 * hook stages) and implements the corresponding handler methods. The registry
 * validates at setup time that every declared stage has a matching handler and
 * that no undeclared handlers are present.
 *
 * Hook handler properties are typed `unknown` here so that the generic base
 * interface stays free of agent-specific imports. Concrete extension types
 * (e.g. `AgentExtension` in `@cline/agents`) narrow them to the correct
 * context and return types.
 */
export interface ContributionRegistryExtension<
	TTool = AgentTool,
	TMessage = unknown,
> {
	type?: string; // Default to plugin for now.
	/** Unique identifier for this extension, used in error messages and hook handler names. */
	name: string;
	/** Declares what capabilities and hook stages this extension uses. Validated before `setup()` runs. */
	manifest: PluginManifest;
	/** Indicates whether this extension is disabled. Disabled extensions are ignored during setup. */
	disabled?: boolean;
	/** Runtime-native hooks consumed directly by `@cline/agents`. */
	hooks?: AgentExtensionHooks;
	/**
	 * Called once during registry setup to register tools, commands, and other
	 * contributions.
	 *
	 * The optional second argument provides workspace context that is always
	 * sourced from the host session config — never from `process.cwd()`. Use
	 * `ctx.workspaceInfo?.rootPath` instead of `process.cwd()` or
	 * `import.meta.url` tricks when you need workspace-relative paths.
	 */
	setup?: (
		api: AgentExtensionApi<TTool, TMessage>,
		ctx: PluginSetupContext,
	) => void | Promise<void>;
}

export interface ContributionRegistryOptions<
	TExtension extends ContributionRegistryExtension<TTool, TMessage>,
	TTool = AgentTool,
	TMessage = unknown,
> {
	extensions?: TExtension[];
	/** Workspace context forwarded to each extension's `setup(api, ctx)` call. */
	setupContext?: PluginSetupContext;
}

export interface ContributionRegistryInitializeOptions {
	tolerateSetupErrors?: boolean;
}

interface NormalizedExtension<
	TExtension extends ContributionRegistryExtension<TTool, TMessage>,
	TTool,
	TMessage,
> {
	extension: TExtension;
	order: number;
	manifest: {
		capabilities: Set<AgentExtensionCapability>;
		raw: PluginManifest;
	};
}

const ALLOWED_CAPABILITIES = new Set<AgentExtensionCapability>(
	ExtensionCapabilityOptions,
);

function asExtensionName<TTool, TMessage>(
	extension: ContributionRegistryExtension<TTool, TMessage>,
	order: number,
): string {
	return extension.name || `extension_${String(order).padStart(4, "0")}`;
}

function hasValidStringArray(value: unknown): value is string[] {
	return (
		Array.isArray(value) && value.every((entry) => typeof entry === "string")
	);
}

function normalizeOptionalStringArray(value: unknown): string[] | undefined {
	if (!Array.isArray(value)) {
		return undefined;
	}
	const normalized = value
		.filter((entry): entry is string => typeof entry === "string")
		.map((entry) => entry.trim())
		.filter((entry) => entry.length > 0);
	return normalized.length > 0 ? normalized : undefined;
}

export function normalizePluginManifest(
	manifest: PluginManifest,
): PluginManifest {
	const providerIds = normalizeOptionalStringArray(manifest.providerIds);
	const modelIds = normalizeOptionalStringArray(manifest.modelIds);
	return {
		...manifest,
		...(providerIds ? { providerIds } : {}),
		...(modelIds ? { modelIds } : {}),
	};
}

function normalizeManifest<
	TExtension extends ContributionRegistryExtension<TTool, TMessage>,
	TTool,
	TMessage,
>(
	extension: TExtension,
	order: number,
): NormalizedExtension<TExtension, TTool, TMessage>["manifest"] {
	const extensionName = asExtensionName(extension, order);
	const manifest = extension.manifest;
	if (!manifest || typeof manifest !== "object") {
		throw new Error(
			`Invalid manifest for extension "${extensionName}": manifest is required`,
		);
	}
	if (
		!Array.isArray(manifest.capabilities) ||
		manifest.capabilities.length === 0
	) {
		throw new Error(
			`Invalid manifest for extension "${extensionName}": capabilities must be a non-empty array`,
		);
	}

	const capabilities = new Set<AgentExtensionCapability>();
	for (const capability of manifest.capabilities) {
		if (!ALLOWED_CAPABILITIES.has(capability)) {
			throw new Error(
				`Invalid manifest for extension "${extensionName}": unsupported capability "${String(capability)}"`,
			);
		}
		capabilities.add(capability);
	}

	if (
		Object.hasOwn(manifest, "providerIds") &&
		!hasValidStringArray(manifest.providerIds)
	) {
		throw new Error(
			`Invalid manifest for extension "${extensionName}": providerIds must be a string array when provided`,
		);
	}
	if (
		Object.hasOwn(manifest, "modelIds") &&
		!hasValidStringArray(manifest.modelIds)
	) {
		throw new Error(
			`Invalid manifest for extension "${extensionName}": modelIds must be a string array when provided`,
		);
	}
	const hookCapabilityEnabled = capabilities.has("hooks");
	const extensionDefinesHooks = extension.hooks !== undefined;
	if (extensionDefinesHooks && !hookCapabilityEnabled) {
		throw new Error(
			`Invalid manifest for extension "${extensionName}": runtime hooks require the "hooks" capability`,
		);
	}

	return {
		capabilities,
		raw: normalizePluginManifest(manifest),
	};
}

function normalizeAutomationEventType(
	input: AgentExtensionAutomationEventType,
	extensionName: string,
): AgentExtensionAutomationEventType {
	if (!input || typeof input !== "object") {
		throw new Error(
			`Invalid automation event contribution for extension "${extensionName}": expected object`,
		);
	}
	const eventType =
		typeof input.eventType === "string" ? input.eventType.trim() : "";
	const source = typeof input.source === "string" ? input.source.trim() : "";
	if (!eventType) {
		throw new Error(
			`Invalid automation event contribution for extension "${extensionName}": eventType is required`,
		);
	}
	if (!source) {
		throw new Error(
			`Invalid automation event contribution for extension "${extensionName}": source is required`,
		);
	}
	return {
		...input,
		eventType,
		source,
		examples: input.examples ? [...input.examples] : undefined,
		metadata: input.metadata ? { ...input.metadata } : undefined,
	};
}

export class ContributionRegistry<
	TExtension extends ContributionRegistryExtension<TTool, TMessage>,
	TTool = AgentTool,
	TMessage = unknown,
> {
	private readonly extensions: TExtension[];
	private readonly registry: AgentExtensionRegistry<TTool, TMessage> = {
		tools: [],
		commands: [],
		rules: [],
		messageBuilder: [],
		providers: [],
		automationEventTypes: [],
		mcpServers: [],
	};
	private normalized: NormalizedExtension<TExtension, TTool, TMessage>[] = [];
	private phase: "resolve" | "validate" | "setup" | "activate" | "run" =
		"resolve";
	private readonly setupContext: PluginSetupContext;

	constructor(
		options: ContributionRegistryOptions<TExtension, TTool, TMessage> = {},
	) {
		this.extensions = options.extensions ?? [];
		this.setupContext = options.setupContext ?? {};
	}

	resolve(): void {
		if (this.phase !== "resolve") return;
		this.normalized = this.extensions.map((extension, order) => ({
			extension,
			order,
			manifest: {
				capabilities: new Set(),
				raw: extension.manifest,
			},
		}));
		this.phase = "validate";
	}

	validate(): void {
		if (this.phase === "resolve") this.resolve();
		if (this.phase !== "validate") return;
		this.normalized = this.normalized.map((entry) => ({
			...entry,
			manifest: normalizeManifest<TExtension, TTool, TMessage>(
				entry.extension,
				entry.order,
			),
		}));
		this.phase = "setup";
	}

	async setup(
		options: ContributionRegistryInitializeOptions = {},
	): Promise<void> {
		if (this.phase === "resolve") this.resolve();
		if (this.phase === "validate") this.validate();
		if (this.phase !== "setup") return;

		let firstSetupError: unknown;
		const successfulSetups: AgentExtensionRegistry<TTool, TMessage>[] = [];
		for (const entry of this.normalized) {
			const { extension } = entry;
			if (extension.disabled) continue;
			const extensionName = asExtensionName(extension, entry.order);
			const pending: AgentExtensionRegistry<TTool, TMessage> = {
				tools: [],
				commands: [],
				rules: [],
				messageBuilder: [],
				providers: [],
				automationEventTypes: [],
				mcpServers: [],
			};
			const api: AgentExtensionApi<TTool, TMessage> = {
				registerTool: (tool) => pending.tools.push(tool),
				registerCommand: (command) => pending.commands.push(command),
				registerRule: (rule) => {
					if (!entry.manifest.capabilities.has("rules")) {
						throw new Error(
							`Invalid setup for extension "${extensionName}": registerRule requires the "rules" capability`,
						);
					}
					pending.rules.push(rule);
				},
				registerMessageBuilder: (builder) =>
					pending.messageBuilder.push(builder),
				registerProvider: (provider) => pending.providers.push(provider),
				registerAutomationEventType: (eventType) => {
					if (!entry.manifest.capabilities.has("automationEvents")) {
						throw new Error(
							`Invalid setup for extension "${extensionName}": registerAutomationEventType requires the "automationEvents" capability`,
						);
					}
					pending.automationEventTypes.push(
						normalizeAutomationEventType(eventType, extensionName),
					);
				},
				registerMcpServer: (server) => {
					if (!entry.manifest.capabilities.has("mcp")) {
						throw new Error(
							`Invalid setup for extension "${extensionName}": registerMcpServer requires the "mcp" capability`,
						);
					}
					pending.mcpServers.push({
						...server,
						metadata: {
							...(server.metadata ?? {}),
							source: "plugin",
							plugin: extensionName,
						},
					});
				},
			};
			const setupContext = entry.manifest.capabilities.has("automationEvents")
				? this.setupContext
				: {
						...this.setupContext,
						automation: undefined,
					};
			try {
				await extension.setup?.(api, setupContext);
				successfulSetups.push(pending);
			} catch (error) {
				if (options.tolerateSetupErrors !== true) {
					throw error;
				}
				firstSetupError ??= error;
			}
		}
		if (firstSetupError && options.tolerateSetupErrors !== true) {
			throw firstSetupError;
		}
		for (const pending of successfulSetups) {
			this.registry.tools.push(...pending.tools);
			this.registry.commands.push(...pending.commands);
			this.registry.rules.push(...pending.rules);
			this.registry.messageBuilder.push(...pending.messageBuilder);
			this.registry.providers.push(...pending.providers);
			this.registry.automationEventTypes.push(...pending.automationEventTypes);
			this.registry.mcpServers.push(...pending.mcpServers);
		}
		this.phase = "activate";
		if (firstSetupError) {
			throw firstSetupError;
		}
	}

	activate(): void {
		if (this.phase === "resolve") this.resolve();
		if (this.phase === "validate") this.validate();
		if (this.phase === "setup") {
			throw new Error(
				"Contribution registry setup must complete before activation",
			);
		}
		if (this.phase !== "activate") return;
		this.phase = "run";
	}

	async initialize(
		options: ContributionRegistryInitializeOptions = {},
	): Promise<void> {
		this.resolve();
		this.validate();
		try {
			await this.setup(options);
		} finally {
			if (this.phase === "activate") {
				this.activate();
			}
		}
	}

	isActivated(): boolean {
		return this.phase === "run";
	}

	getRegistrySnapshot(): AgentExtensionRegistry<TTool, TMessage> {
		return {
			tools: [...this.registry.tools],
			commands: [...this.registry.commands],
			rules: [...this.registry.rules],
			messageBuilder: [...this.registry.messageBuilder],
			providers: [...this.registry.providers],
			automationEventTypes: [...this.registry.automationEventTypes],
			mcpServers: [...this.registry.mcpServers],
		};
	}

	getRegisteredTools(): TTool[] {
		return [...this.registry.tools];
	}

	getRegisteredRules(): AgentExtensionRule[] {
		return [...this.registry.rules];
	}

	getRegisteredAutomationEventTypes(): AgentExtensionAutomationEventType[] {
		return [...this.registry.automationEventTypes];
	}

	getRegisteredMcpServers(): AgentExtensionMcpServer[] {
		return [...this.registry.mcpServers];
	}

	getValidatedExtensions(): TExtension[] {
		if (this.phase === "resolve") this.resolve();
		if (this.phase === "validate") this.validate();
		return this.normalized
			.slice()
			.sort((a, b) => a.order - b.order)
			.map(({ extension }) => extension);
	}
}

export function createContributionRegistry<
	TExtension extends ContributionRegistryExtension<TTool, TMessage>,
	TTool = AgentTool,
	TMessage = unknown,
>(
	options: ContributionRegistryOptions<TExtension, TTool, TMessage> = {},
): ContributionRegistry<TExtension, TTool, TMessage> {
	return new ContributionRegistry(options);
}

