/**
 * Cross-package logging surface for hosts that inject their own logger (for example `pino` or the VS Code API).
 *
 * {@link BasicLogger.debug} is for verbose diagnostics (hosts typically gate this behind a debug log level).
 * {@link BasicLogger.log} is the primary channel for operational messages that are not errors.
 * {@link BasicLogger.error} is optional; when omitted, hosts may route failures through {@link BasicLogger.log}
 * with {@link BasicLogMetadata.severity} `"error"` or handle errors elsewhere.
 *
 * Use {@link noopBasicLogger} when you need a fully-defined no-op implementation.
 */

/**
 * Optional structured fields used across the SDK and recommended for host log backends.
 * Callers may add other keys freely; these names are the shared convention for cross-component queries.
 */
export interface BasicLogMetadata extends Record<string, unknown> {
	sessionId?: string;
	runId?: string;
	providerId?: string;
	toolName?: string;
	durationMs?: number;
	/**
	 * When using {@link BasicLogger.log}, disambiguates severity for backends that map a single `log`
	 * method onto multiple output levels (for example Pino `info` vs `warn`).
	 */
	severity?: "info" | "warn" | "error";
}

export interface BasicLogger {
	/** Verbose diagnostics; hosts should no-op or filter when not in debug mode. */
	debug: (message: string, metadata?: BasicLogMetadata) => void;
	/** Operational messages (replaces former `info` / non-error `warn` split). */
	log: (message: string, metadata?: BasicLogMetadata) => void;
	error?: (
		message: string,
		metadata?: BasicLogMetadata & { error?: unknown },
	) => void;
}

/** All levels implemented as no-ops; safe default when no logger is injected. */
export const noopBasicLogger: BasicLogger = {
	debug: () => {},
	log: () => {},
	error: () => {},
};

import { describe, expect, it } from "vitest";
import {
	clampMcpTimeoutSeconds,
	DEFAULT_MCP_TIMEOUT_SECONDS,
	formatMcpTimeoutErrorMessage,
	isMcpTimeoutConfigured,
	MAX_MCP_TIMEOUT_SECONDS,
	MIN_MCP_TIMEOUT_SECONDS,
	resolveMcpTimeoutSeconds,
} from "./mcp";

describe("resolveMcpTimeoutSeconds", () => {
	it("returns the default for missing or non-numeric values", () => {
		expect(resolveMcpTimeoutSeconds(undefined)).toBe(
			DEFAULT_MCP_TIMEOUT_SECONDS,
		);
		expect(resolveMcpTimeoutSeconds(null)).toBe(DEFAULT_MCP_TIMEOUT_SECONDS);
		expect(resolveMcpTimeoutSeconds("120")).toBe(DEFAULT_MCP_TIMEOUT_SECONDS);
		expect(resolveMcpTimeoutSeconds(Number.NaN)).toBe(
			DEFAULT_MCP_TIMEOUT_SECONDS,
		);
		expect(resolveMcpTimeoutSeconds(Infinity)).toBe(
			DEFAULT_MCP_TIMEOUT_SECONDS,
		);
	});

	it("passes through valid values unchanged", () => {
		expect(resolveMcpTimeoutSeconds(60)).toBe(60);
		expect(resolveMcpTimeoutSeconds(1)).toBe(1);
		expect(resolveMcpTimeoutSeconds(3600)).toBe(3600);
	});

	it("clamps values outside the bounds", () => {
		expect(resolveMcpTimeoutSeconds(0)).toBe(MIN_MCP_TIMEOUT_SECONDS);
		expect(resolveMcpTimeoutSeconds(-5)).toBe(MIN_MCP_TIMEOUT_SECONDS);
		// A milliseconds/seconds mix-up (60000 meaning 60s) clamps instead of
		// becoming ~16 hours.
		expect(resolveMcpTimeoutSeconds(60000)).toBe(MAX_MCP_TIMEOUT_SECONDS);
	});
});

describe("isMcpTimeoutConfigured", () => {
	it("accepts only finite numeric values", () => {
		expect(isMcpTimeoutConfigured(60)).toBe(true);
		expect(isMcpTimeoutConfigured(undefined)).toBe(false);
		expect(isMcpTimeoutConfigured(null)).toBe(false);
		expect(isMcpTimeoutConfigured("60")).toBe(false);
		expect(isMcpTimeoutConfigured(Number.NaN)).toBe(false);
		expect(isMcpTimeoutConfigured(Infinity)).toBe(false);
	});
});

describe("clampMcpTimeoutSeconds", () => {
	it("clamps into [MIN, MAX]", () => {
		expect(clampMcpTimeoutSeconds(0)).toBe(MIN_MCP_TIMEOUT_SECONDS);
		expect(clampMcpTimeoutSeconds(120)).toBe(120);
		expect(clampMcpTimeoutSeconds(999999)).toBe(MAX_MCP_TIMEOUT_SECONDS);
