	"CLINE_CONNECTOR_STARTING_INSTANCE";
export const CLINE_CONNECTOR_SUPERVISED_ENV = "CLINE_CONNECTOR_SUPERVISED";

export interface ConnectorCliLaunchSpec {
	launcher: string;
	connectArgsPrefix: string[];
	cwd: string;
}

/** Identifies one connector instance: an adapter channel plus its instance id. */
export interface ConnectorInstanceRef {
	channel: string;
	instanceId: string;
}

/**
 * Latched result of {@link claimHubDaemonProcess}, so the sentinel can be
 * removed from the environment while the process still knows what it is.
 */
let claimedHubDaemonProcess: boolean | undefined;

/**
 * Take the daemon sentinel out of the environment, remembering its value.
 *
 * The sentinel selects which personality the shared CLI binary boots, so it must
 * not outlive that decision: the hub daemon hosts session runtimes, and every
 * process a session spawns - agent shell commands, MCP servers, hooks, plugin
 * sandboxes - inherits its environment. An inherited sentinel makes each of
 * those try to become a hub daemon instead of running the command, and they die
 * on EADDRINUSE against the real hub. Observed as every `cline` invocation from
 * a Slack connector agent failing, `cline --help` included, because the
 * personality is chosen before any argument parsing.
 *
 * Call this once from an entrypoint, in place of {@link isHubDaemonProcess}.
 * Spawn paths that deliberately start a daemon set the variable explicitly on
 * the child environment, so they are unaffected.
 */
export function claimHubDaemonProcess(
	env: Record<string, string | undefined> = process.env,
): boolean {
	claimedHubDaemonProcess = env[CLINE_RUN_AS_HUB_DAEMON_ENV] === "1";
	delete env[CLINE_RUN_AS_HUB_DAEMON_ENV];
	return claimedHubDaemonProcess;
}

/**
 * Whether this process is the hub daemon.
 *
 * Reads the latch first so callers still get the right answer after
 * {@link claimHubDaemonProcess} has scrubbed the environment - notably the
 * guards that stop a daemon from spawning another daemon. An explicitly passed
 * environment is always read verbatim.
 */
export function isHubDaemonProcess(
	env?: Record<string, string | undefined>,
): boolean {
	if (env) {
		return env[CLINE_RUN_AS_HUB_DAEMON_ENV] === "1";
	}
	return (
		claimedHubDaemonProcess ?? process.env[CLINE_RUN_AS_HUB_DAEMON_ENV] === "1"
	);
}

export function setConnectorCliLaunchSpec(
	spec: ConnectorCliLaunchSpec,
	env: Record<string, string | undefined> = process.env,
): void {
	env[CLINE_CONNECTOR_CLI_LAUNCH_ENV] = JSON.stringify(spec);
}

/** Latched result of {@link claimSupervisedConnectorProcess}. */
let claimedSupervisedConnectorProcess: boolean | undefined;

/**
 * Take the supervised-connector marker out of the environment, remembering it.
 *
 * Same hazard as {@link claimHubDaemonProcess}: a supervised connector hosts
 * agent sessions, and everything they spawn — shell commands, MCP servers, hooks
 * — inherits its environment. An inherited marker makes a nested `cline connect`
 * think it is the process the hub is tracking, so it runs the connector in the
 * foreground of that shell command instead of handing it to the hub.
 *
 * Call once from an entrypoint, in place of
 * {@link isSupervisedConnectorProcess}. The supervisor sets the marker
 * explicitly on the child environment, so it is unaffected.
 */
export function claimSupervisedConnectorProcess(
	env: Record<string, string | undefined> = process.env,
): boolean {
	claimedSupervisedConnectorProcess =
		env[CLINE_CONNECTOR_SUPERVISED_ENV] === "1";
	delete env[CLINE_CONNECTOR_SUPERVISED_ENV];
	return claimedSupervisedConnectorProcess;
}

/**
 * True in a connector process the hub supervisor launched.
 *
 * Such a process must run the connector itself rather than doing what a
 * user-invoked background `connect` does — asking the hub to start it (which
 * would loop straight back here) or spawning its own detached child and exiting
 * (which would leave the supervisor holding a handle to a process that is
 * already gone).
 *
 * Reads the latch first so callers still get the right answer after
 * {@link claimSupervisedConnectorProcess} has scrubbed the environment. An
 * explicitly passed environment is always read verbatim.
 */
export function isSupervisedConnectorProcess(
	env?: Record<string, string | undefined>,
): boolean {
	if (env) {
		return env[CLINE_CONNECTOR_SUPERVISED_ENV] === "1";
	}
	return (
		claimedSupervisedConnectorProcess ??
		process.env[CLINE_CONNECTOR_SUPERVISED_ENV] === "1"
	);
}

/**
 * Announce the connector instance this process is in the middle of starting.
 *
 * A connector starts its own hub daemon, and the daemon then reconnects every
 * persisted connector. The instance doing the starting is not yet registered as
 * active when the daemon boots, so without this marker the daemon launches a
 * second copy of it - two processes holding the same bot token. The daemon
 * inherits this variable from the connector that spawned it, so it can tell
 * "the connector that is bringing me up" apart from "a connector left over from
 * a previous hub session", which genuinely does need restarting.
 */
export function setStartingConnectorInstance(
	ref: ConnectorInstanceRef,
	env: Record<string, string | undefined> = process.env,
): void {
	env[CLINE_CONNECTOR_STARTING_INSTANCE_ENV] = JSON.stringify(ref);
}

export function readStartingConnectorInstance(
	env: Record<string, string | undefined> = process.env,
): ConnectorInstanceRef | undefined {
	const raw = env[CLINE_CONNECTOR_STARTING_INSTANCE_ENV];
	if (!raw) {
		return undefined;
	}
	try {
		const parsed = JSON.parse(raw) as Partial<ConnectorInstanceRef>;
		if (
			typeof parsed.channel !== "string" ||
			!parsed.channel.trim() ||
			typeof parsed.instanceId !== "string" ||
			!parsed.instanceId.trim()
		) {
			return undefined;
		}
		return { channel: parsed.channel, instanceId: parsed.instanceId };
	} catch {
		return undefined;
	}
}

export function readConnectorCliLaunchSpec(
	env: Record<string, string | undefined> = process.env,
): ConnectorCliLaunchSpec | undefined {
	const raw = env[CLINE_CONNECTOR_CLI_LAUNCH_ENV];
	if (!raw) {
		return undefined;
	}
	try {
		const parsed = JSON.parse(raw) as Partial<ConnectorCliLaunchSpec>;
		if (
			typeof parsed.launcher !== "string" ||
			!parsed.launcher.trim() ||
			!Array.isArray(parsed.connectArgsPrefix) ||
			!parsed.connectArgsPrefix.every((arg) => typeof arg === "string") ||
			typeof parsed.cwd !== "string" ||
			!parsed.cwd.trim()
		) {
			return undefined;
		}
		return {
			launcher: parsed.launcher,
			connectArgsPrefix: parsed.connectArgsPrefix,
			cwd: parsed.cwd,
		};
	} catch {
		return undefined;
	}
}

import { parseKeyPairsIntoRecord } from "../parse/headers/utils";
import type { OpenTelemetryClientConfig, TelemetryMetadata } from "./telemetry";

export interface ClineTelemetryServiceConfig extends OpenTelemetryClientConfig {
	metadata: TelemetryMetadata;
}

function getTelemetryBuildTimeConfig(): OpenTelemetryClientConfig {
	if (!process.env) {
		return {
			enabled: false,
		};
	}

	return {
		enabled:
			process.env.OTEL_TELEMETRY_ENABLED === "1" ||
			process.env.OTEL_TELEMETRY_ENABLED === "true",
		metricsExporter: process.env.OTEL_METRICS_EXPORTER || "otlp",
		logsExporter: process.env.OTEL_LOGS_EXPORTER || "otlp",
		tracesExporter: process.env.OTEL_TRACES_EXPORTER,
		otlpProtocol: process.env.OTEL_EXPORTER_OTLP_PROTOCOL || "http/json",
		otlpEndpoint: process.env.OTEL_EXPORTER_OTLP_ENDPOINT,
		metricExportInterval: process.env.OTEL_METRIC_EXPORT_INTERVAL
			? Number.parseInt(process.env.OTEL_METRIC_EXPORT_INTERVAL, 10)
			: undefined,
		otlpHeaders: process.env.OTEL_EXPORTER_OTLP_HEADERS
			? parseKeyPairsIntoRecord(process.env.OTEL_EXPORTER_OTLP_HEADERS)
			: undefined,
	};
}

export function createClineTelemetryServiceMetadata(
	overrides: Partial<TelemetryMetadata> = {},
): TelemetryMetadata {
	return {
		extension_version: "unknown",
		cline_type: "unknown",
		platform: "terminal",
		platform_version: process?.version || "unknown",
		os_type: process?.platform || "unknown",
		os_version:
			process?.platform === "win32"
				? (process?.env?.OS ?? "unknown")
				: "unknown",
		...overrides,
	};
}

export function createClineTelemetryServiceConfig(
	configOverrides: Partial<ClineTelemetryServiceConfig> = {},
): ClineTelemetryServiceConfig {
	return {
		...getTelemetryBuildTimeConfig(),
		...configOverrides,
		metadata: createClineTelemetryServiceMetadata(configOverrides.metadata),
	};
}

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import {
	captureSdkError,
	normalizeSdkError,
	resetSdkErrorRateLimiterForTests,
	SDK_ERROR_RATE_LIMIT_MAX_PER_WINDOW,
	SDK_ERROR_RATE_LIMIT_WINDOW_MS,
	SDK_ERROR_TELEMETRY_EVENT,
} from "./telemetry";

beforeEach(() => {
	resetSdkErrorRateLimiterForTests();
});

describe("SDK error telemetry", () => {
	it("normalizes unknown errors with sanitized, bounded messages", () => {
		const normalized = normalizeSdkError(
			new Error(
				"request failed: authorization=Bearer abc123 /Users/beatrix/project C:\\Users\\beatrix\\project C:/Users/beatrix/project",
			),
		);

		expect(normalized.error_type).toBe("Error");
		expect(String(normalized.error_message)).toContain("[redacted]");
		expect(String(normalized.error_message)).not.toContain("beatrix");
		expect(String(normalized.error_message)).not.toContain("abc123");
	});

	it("bounds sanitized error messages", () => {
		const normalized = normalizeSdkError(new Error("x".repeat(100)), 48);

		expect(normalized.error_message).toHaveLength(48);
	});

	it("uses a stable fallback for errors without a message", () => {
		expect(normalizeSdkError(new Error("")).error_message).toBe(
			"Unknown error",
		);
		expect(normalizeSdkError([]).error_message).toBe("Unknown error");
		expect(normalizeSdkError({}).error_message).toBe("Unknown error");
	});

	it("prefers an explicitly extracted message while preserving raw metadata", () => {
		const normalized = normalizeSdkError(
			Object.assign(
				new Error("No output generated. Check the stream for errors."),
				{
					code: "invalid_request_error",
					statusCode: 400,
				},
			),
			undefined,
			"prompt is too long",
		);

		expect(normalized).toMatchObject({
			error_type: "Error",
			error_message: "prompt is too long",
			error_code: "invalid_request_error",
			error_status: 400,
		});
	});

	it("captures canonical SDK error events with context", () => {
		const telemetry = {
			capture: vi.fn(),
		};

		captureSdkError(telemetry as never, {
			component: "core",
			operation: "session.shutdown",
			error: Object.assign(new Error("boom"), { code: "EBOOM", status: 503 }),
			severity: "warn",
			context: {
				sessionId: "s1",
				component: "context",
				operation: "context.operation",
				severity: "fatal",
				handled: false,
				error_type: "ContextError",
				error_message: "unsanitized context message",
				error_code: "CONTEXT",
				error_status: 400,
			},
		});

		expect(telemetry.capture).toHaveBeenCalledWith({
			event: SDK_ERROR_TELEMETRY_EVENT,
			properties: expect.objectContaining({
				component: "core",
				operation: "session.shutdown",
				severity: "warn",
				handled: true,
				error_type: "Error",
				error_message: "boom",
				error_code: "EBOOM",
				error_status: 503,
				sessionId: "s1",
			}),
		});
	});
});

describe("SDK error rate limiting", () => {
	afterEach(() => {
		vi.useRealTimers();
	});

	function captureRepeatedly(count: number, message: (i: number) => string) {
		const capture = vi.fn();
		for (let i = 0; i < count; i++) {
			captureSdkError({ capture } as never, {
				component: "llms",
				operation: "provider.stream",
				error: new Error(message(i)),
			});
		}
		return capture;
	}

	it("emits the first N identical failures per window, then suppresses", () => {
		const capture = captureRepeatedly(100, () => "Upstream returned HTTP 429");

		expect(capture).toHaveBeenCalledTimes(SDK_ERROR_RATE_LIMIT_MAX_PER_WINDOW);
	});

	it("does not suppress distinct failures", () => {
		const capture = captureRepeatedly(10, (i) => `distinct ${"x".repeat(i)}`);

		expect(capture).toHaveBeenCalledTimes(10);
	});

	it("coalesces messages that differ only by numbers", () => {
		const capture = captureRepeatedly(
			100,
			(i) => `run failed at iteration ${i}`,
		);

		expect(capture).toHaveBeenCalledTimes(SDK_ERROR_RATE_LIMIT_MAX_PER_WINDOW);
	});

	it("keeps failures with distinct error_status on separate budgets", () => {
		const capture = vi.fn();
		for (const status of [429, 401]) {
			for (let i = 0; i < 100; i++) {
				captureSdkError({ capture } as never, {
					component: "llms",
					operation: "provider.stream",
					error: Object.assign(new Error(`Upstream returned HTTP ${status}`), {
						status,
					}),
				});
			}
		}

		// A hot rate-limit loop must not consume the auth failure's budget.
		expect(capture).toHaveBeenCalledTimes(
			2 * SDK_ERROR_RATE_LIMIT_MAX_PER_WINDOW,
		);
		const statuses = capture.mock.calls.map(
			([call]) => call.properties.error_status,
		);
		expect(statuses.filter((status) => status === 429)).toHaveLength(
			SDK_ERROR_RATE_LIMIT_MAX_PER_WINDOW,
		);
		expect(statuses.filter((status) => status === 401)).toHaveLength(
			SDK_ERROR_RATE_LIMIT_MAX_PER_WINDOW,
		);
	});

	it("keeps failures with distinct error_code on separate budgets", () => {
		const capture = vi.fn();
		for (const code of ["rate_limit_error", "authentication_error"]) {
			for (let i = 0; i < 100; i++) {
				captureSdkError({ capture } as never, {
					component: "llms",
					operation: "provider.stream",
					error: Object.assign(new Error("request rejected"), { code }),
				});
			}
		}

		expect(capture).toHaveBeenCalledTimes(
			2 * SDK_ERROR_RATE_LIMIT_MAX_PER_WINDOW,
		);
	});

	it("returns whether the failure was recorded", () => {
		const capture = vi.fn();
		const input = {
			component: "llms",
			operation: "provider.stream",
			error: new Error("boom"),
		} as const;

		expect(captureSdkError(undefined, input)).toBe(false);
		expect(captureSdkError({ capture } as never, input)).toBe(true);
		// Rate-limit-suppressed failures still count as recorded.
		for (let i = 0; i < 100; i++) {
			expect(captureSdkError({ capture } as never, input)).toBe(true);
		}
	});

	it("carries suppressed_count onto the next emission after the window rolls over", () => {
		vi.useFakeTimers();
		const capture = captureRepeatedly(
			SDK_ERROR_RATE_LIMIT_MAX_PER_WINDOW + 7,
			() => "Upstream returned HTTP 429",
		);
		expect(capture).toHaveBeenCalledTimes(SDK_ERROR_RATE_LIMIT_MAX_PER_WINDOW);

		vi.advanceTimersByTime(SDK_ERROR_RATE_LIMIT_WINDOW_MS);
		captureSdkError({ capture } as never, {
			component: "llms",
			operation: "provider.stream",
			error: new Error("Upstream returned HTTP 429"),
		});

		expect(capture).toHaveBeenLastCalledWith({
			event: SDK_ERROR_TELEMETRY_EVENT,
			properties: expect.objectContaining({
				error_message: "Upstream returned HTTP 429",
				suppressed_count: 7,
			}),
		});
	});

	it("keeps a 12-hour hot loop bounded to dozens of events", () => {
		vi.useFakeTimers();
		const capture = vi.fn();

		// One identical failure every 10 seconds for 12 hours.
		for (let i = 0; i < (12 * SDK_ERROR_RATE_LIMIT_WINDOW_MS) / 10_000; i++) {
			captureSdkError({ capture } as never, {
				component: "llms",
				operation: "provider.stream",
				error: new Error("Upstream returned HTTP 429"),
			});
			vi.advanceTimersByTime(10_000);
		}

		expect(capture).toHaveBeenCalledTimes(
			12 * SDK_ERROR_RATE_LIMIT_MAX_PER_WINDOW,
		);
	});
});

