export const WorkspaceInfoSchema = z.object({
	rootPath: z.string().min(1),
	hint: z.string().min(1).optional(),
	associatedRemoteUrls: z.array(z.string().min(1)).optional(),
	latestGitCommitHash: z.string().min(1).optional(),
	latestGitBranchName: z.string().min(1).optional(),
});

export const WorkspaceManifestSchema = z.object({
	currentWorkspacePath: z.string().min(1).optional(),
	workspaces: z.record(z.string().min(1), WorkspaceInfoSchema),
});

export type WorkspaceManifest = z.infer<typeof WorkspaceManifestSchema>;

export function emptyWorkspaceManifest(): WorkspaceManifest {
	return { workspaces: {} };
}

export interface WorkspaceInfo {
	rootPath: string;
	hint?: string;
	associatedRemoteUrls?: string[];
	latestGitCommitHash?: string;
	latestGitBranchName?: string;
}

export function upsertWorkspaceInfo(
	manifest: WorkspaceManifest,
	info: WorkspaceInfo,
): WorkspaceManifest {
	const nextManifest: WorkspaceManifest = {
		...manifest,
		workspaces: {
			...manifest.workspaces,
			[info.rootPath]: info,
		},
	};
	if (!nextManifest.currentWorkspacePath) {
		nextManifest.currentWorkspacePath = info.rootPath;
	}
	return WorkspaceManifestSchema.parse(nextManifest);
}

export const CLINE_WORKSPACES_DIRECTORY_NAME = "workspaces";
export const CLINE_CHAT_WORKSPACE_DIRECTORY_NAME = "chat";

// Default data-dir anchors for the structural check below. The Node resolver
// derives the real location from resolveClineDataDir(), which defaults to
// `~/.cline/data`.
const CLINE_CONFIG_DIRECTORY_NAME = ".cline";
const CLINE_DATA_DIRECTORY_NAME = "data";

/**
 * Browser-safe structural check for the shared chat workspace that hosts
 * sessions started without a project: `.cline/data/workspaces/chat`. Matches
 * the directory itself only — project folders created inside it are regular
 * workspaces. Matches the default data-dir layout; explicit `CLINE_DATA_DIR`
 * overrides are not detectable from a bare path string.
 */
export function isChatWorkspacePath(path: string): boolean {
	const normalizedPath = path.trim();
	const isWindowsAbsolute =
		/^[A-Za-z]:[\\/]/.test(normalizedPath) || normalizedPath.startsWith("\\\\");
	const isPosixAbsolute = normalizedPath.startsWith("/");
	if (!isWindowsAbsolute && !isPosixAbsolute) {
		return false;
	}
	const segments = normalizedPath
		.split(isWindowsAbsolute ? /[\\/]+/ : /\/+/)
		.filter(Boolean);
	const chatDirectory = segments.at(-1) ?? "";
	const workspacesDirectory = segments.at(-2) ?? "";
	const dataDirectory = segments.at(-3) ?? "";
	const configDirectory = segments.at(-4) ?? "";
	return (
		configDirectory === CLINE_CONFIG_DIRECTORY_NAME &&
		dataDirectory === CLINE_DATA_DIRECTORY_NAME &&
		workspacesDirectory === CLINE_WORKSPACES_DIRECTORY_NAME &&
		chatDirectory === CLINE_CHAT_WORKSPACE_DIRECTORY_NAME
	);
}

import { mkdirSync, mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { resolveExistingFilePath } from "./path-resolution";

describe("resolveExistingFilePath", () => {
	it("returns the literal path when it already exists", () => {
		const dir = mkdtempSync(join(tmpdir(), "path-resolution-literal-"));
		const filePath = join(dir, "plain.txt");
		writeFileSync(filePath, "hi");

		expect(resolveExistingFilePath(filePath)).toBe(filePath);
	});

	it("returns undefined when the file truly does not exist", () => {
		const dir = mkdtempSync(join(tmpdir(), "path-resolution-missing-"));
		expect(resolveExistingFilePath(join(dir, "nope.txt"))).toBeUndefined();
	});

	it("resolves macOS screenshot paths with narrow no-break space before PM", () => {
		// macOS Sonoma+ embeds U+202F before AM/PM. Callers often hand us a
		// path with a regular space because clipboards / terminals collapse
		// U+202F → U+0020 in transit.
		const dir = mkdtempSync(join(tmpdir(), "path-resolution-nnbsp-pm-"));
		const onDisk = "Screenshot 2026-05-12 at 4.42.48\u202FPM.png";
		const requested = join(dir, "Screenshot 2026-05-12 at 4.42.48 PM.png");
		writeFileSync(join(dir, onDisk), "hello");

		expect(resolveExistingFilePath(requested)).toBe(join(dir, onDisk));
	});

	it("resolves macOS screenshot paths with lowercase am/pm (en_AU style)", () => {
		const dir = mkdtempSync(join(tmpdir(), "path-resolution-nnbsp-am-"));
		const onDisk = "Screenshot 2026-01-01 at 10.00.00\u202Fam.png";
		const requested = join(dir, "Screenshot 2026-01-01 at 10.00.00 am.png");
		writeFileSync(join(dir, onDisk), "hello");

		expect(resolveExistingFilePath(requested)).toBe(join(dir, onDisk));
	});

	it("does not rewrite AM/PM text in directory components", () => {
		const parentDir = mkdtempSync(join(tmpdir(), "path-resolution-dir-ampm-"));
		const dir = join(parentDir, "my AM.photos");
		mkdirSync(dir);
		const onDisk = "Screenshot 2026-05-12 at 4.42.48\u202FPM.png";
		const requested = join(dir, "Screenshot 2026-05-12 at 4.42.48 PM.png");
		writeFileSync(join(dir, onDisk), "hello");

		expect(resolveExistingFilePath(requested)).toBe(join(dir, onDisk));
	});

	it("falls back to a parent-directory scan for arbitrary Unicode-space mismatches", () => {
		// Exercises the readdirSync fallback for cases the targeted
		// variants don't cover (here U+00A0 in the middle of a name).
		const dir = mkdtempSync(join(tmpdir(), "path-resolution-nbsp-mid-"));
		const onDisk = "weird\u00a0name.png";
		const requested = join(dir, "weird name.png");
		writeFileSync(join(dir, onDisk), "hello");

		expect(resolveExistingFilePath(requested)).toBe(join(dir, onDisk));
	});
});

/**
 * Path-resolution helpers that tolerate Unicode variants commonly seen on
 * macOS filenames (most notably U+202F NARROW NO-BREAK SPACE in screenshot
 * timestamps like "Screenshot 2026-05-12 at 4.42.48\u202FPM.png").
 *
 * When such a path travels through clipboards, terminals, paste-decoders,
 * or other layers that normalize whitespace, U+202F can collapse to a
 * regular space (U+0020). The on-disk filename still contains U+202F, so
 * a literal `fs.stat` / `fs.readFile` will fail with ENOENT.
 *
 * `resolveExistingFilePath` tries a small set of targeted variants and a
 * last-resort parent-directory scan to recover the actual filename.
 */
import { existsSync, readdirSync } from "node:fs";
import { basename, dirname, join } from "node:path";

// Unicode whitespace code points that show up in macOS-generated filenames
// (or get substituted away by clipboards / terminals).
const UNICODE_SPACES_RE = /[\u00A0\u2000-\u200A\u202F\u205F\u3000]/g;
const NARROW_NO_BREAK_SPACE = "\u202F";

// Build a "canonical whitespace" key for comparing a pasted/typed path
// against actual on-disk entries regardless of which exotic space variant
// was used between segments.
function collapseUnicodeWhitespace(name: string): string {
	return name.normalize("NFC").replace(UNICODE_SPACES_RE, " ");
}

function tryMacOSAmPmVariant(filePath: string): string {
	// macOS Sonoma+ inserts U+202F before AM/PM in screenshot names. Some
	// locales (e.g. en_AU) emit lowercase am/pm; hence the /i flag.
	const fileName = basename(filePath);
	const variantName = fileName.replace(
		/ (AM|PM)\./gi,
		`${NARROW_NO_BREAK_SPACE}$1.`,
	);
	return variantName === fileName
		? filePath
		: join(dirname(filePath), variantName);
}

function tryNFDVariant(filePath: string): string {
	// HFS+ / some APFS configurations store filenames decomposed. Users
	// typically type or paste NFC. Try the NFD variant when the literal
	// path didn't resolve.
	return filePath.normalize("NFD");
}

function tryCurlyApostropheVariant(filePath: string): string {
	// macOS uses U+2019 (right single quotation mark) in localized
	// screenshot names like "Capture d'écran". Users typically type U+0027.
	return filePath.replace(/'/g, "\u2019");
}

function scanDirForCanonicalMatch(filePath: string): string | undefined {
	// Last-resort fallback: enumerate the parent directory and look for an
	// entry whose canonical-whitespace form matches the requested basename.
	// Catches arbitrary exotic-space mismatches the targeted variants
	// above don't cover.
	const dir = dirname(filePath);
	const wanted = collapseUnicodeWhitespace(basename(filePath));
	try {
		for (const entry of readdirSync(dir)) {
			if (collapseUnicodeWhitespace(entry) === wanted) {
				return join(dir, entry);
			}
		}
	} catch {
		// Directory unreadable or missing -- nothing to fall back to.
	}
	return undefined;
}

/**
 * Resolve a possibly-mangled file path to an actual on-disk entry.
 *
 * Returns the literal path when it already exists; otherwise tries a small
 * set of macOS-specific variants (narrow no-break space before AM/PM, NFD
 * normalization, curly apostrophe) before falling back to a parent-directory
 * scan that compares filenames after collapsing exotic Unicode whitespace.
 *
 * Returns `undefined` when no matching file can be located.
 */
export function resolveExistingFilePath(filePath: string): string | undefined {
	if (existsSync(filePath)) {
		return filePath;
	}

	const amPmVariant = tryMacOSAmPmVariant(filePath);
	if (amPmVariant !== filePath && existsSync(amPmVariant)) {
		return amPmVariant;
	}

	const nfdVariant = tryNFDVariant(filePath);
	if (nfdVariant !== filePath && existsSync(nfdVariant)) {
		return nfdVariant;
	}

	const curlyVariant = tryCurlyApostropheVariant(filePath);
	if (curlyVariant !== filePath && existsSync(curlyVariant)) {
		return curlyVariant;
	}

	const nfdCurlyVariant = tryCurlyApostropheVariant(nfdVariant);
	if (
		nfdCurlyVariant !== nfdVariant &&
		nfdCurlyVariant !== curlyVariant &&
		existsSync(nfdCurlyVariant)
	) {
		return nfdCurlyVariant;
	}

	return scanDirForCanonicalMatch(filePath);
}

import { join } from "node:path";
import { afterEach, describe, expect, it, vi } from "vitest";

type EnvSnapshot = {
	HOME: string | undefined;
	USERPROFILE: string | undefined;
	HOMEDRIVE: string | undefined;
	HOMEPATH: string | undefined;
	CLINE_DIR: string | undefined;
};

function captureEnv(): EnvSnapshot {
	return {
		HOME: process.env.HOME,
		USERPROFILE: process.env.USERPROFILE,
		HOMEDRIVE: process.env.HOMEDRIVE,
		HOMEPATH: process.env.HOMEPATH,
		CLINE_DIR: process.env.CLINE_DIR,
	};
}

function restoreEnv(snapshot: EnvSnapshot): void {
	process.env.HOME = snapshot.HOME;
	process.env.USERPROFILE = snapshot.USERPROFILE;
	process.env.HOMEDRIVE = snapshot.HOMEDRIVE;
	process.env.HOMEPATH = snapshot.HOMEPATH;
	process.env.CLINE_DIR = snapshot.CLINE_DIR;
}

describe("storage home directory fallback", () => {
	let snapshot: EnvSnapshot = captureEnv();

	afterEach(() => {
		restoreEnv(snapshot);
		vi.resetModules();
	});

	it("uses USERPROFILE when HOME is unset", async () => {
		snapshot = captureEnv();
		delete process.env.HOME;
		process.env.USERPROFILE = "C:\\Users\\saoud";
		delete process.env.HOMEDRIVE;
		delete process.env.HOMEPATH;
		delete process.env.CLINE_DIR;

		const { resolveClineDir } = await import("./paths");
		expect(resolveClineDir()).toBe(join("C:\\Users\\saoud", ".cline"));
	});

	it("treats HOME=~ as unset and falls back to USERPROFILE", async () => {
		snapshot = captureEnv();
		process.env.HOME = "~";
		process.env.USERPROFILE = "C:\\Users\\saoud";
		delete process.env.HOMEDRIVE;
		delete process.env.HOMEPATH;
		delete process.env.CLINE_DIR;

		const { resolveClineDir } = await import("./paths");
		expect(resolveClineDir()).toBe(join("C:\\Users\\saoud", ".cline"));
	});
});

