const TEAM_TASK_REQUIRED_FIELDS_BY_ACTION = {
	create: ["title", "description"],
	list: [],
	claim: ["taskId"],
	complete: ["taskId", "summary"],
	block: ["taskId", "reason"],
} as const;

type TeamTaskAction = "create" | "list" | "claim" | "complete" | "block";

