type DisclosureState = {
	isOpen: boolean;
	panelId: string;
	setIsOpen: (open: boolean) => void;
};

type ReasoningContextValue = DisclosureState & {
	isStreaming: boolean;
};

const ReasoningContext = createContext<ReasoningContextValue | null>(null);

function useReasoning(): ReasoningContextValue {
	const context = useContext(ReasoningContext);
	if (!context) {
		throw new Error("Reasoning components must be rendered inside Reasoning");
	}
	return context;
}

export type ReasoningProps = Omit<
	HTMLAttributes<HTMLDivElement>,
	"onChange"
> & {
	isStreaming?: boolean;
	open?: boolean;
	defaultOpen?: boolean;
	onOpenChange?: (open: boolean) => void;
};

export const Reasoning = ({
	className,
	defaultOpen = false,
	isStreaming = false,
	onOpenChange,
	open,
	...props
}: ReasoningProps) => {
	const [internalOpen, setInternalOpen] = useState(defaultOpen);
	const panelId = useId();
	const isOpen = open ?? internalOpen;
	const setIsOpen = useCallback(
		(nextOpen: boolean) => {
			if (open === undefined) setInternalOpen(nextOpen);
			onOpenChange?.(nextOpen);
		},
		[onOpenChange, open],
	);
	const value = useMemo(
		() => ({ isOpen, isStreaming, panelId, setIsOpen }),
		[isOpen, isStreaming, panelId, setIsOpen],
	);

	return (
		<ReasoningContext.Provider value={value}>
			<div
				{...props}
				className={classNames("cline-chat-reasoning", className)}
				data-streaming={isStreaming || undefined}
			/>
		</ReasoningContext.Provider>
	);
};

