import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const packageRoot = join(import.meta.dir, "..");
const sourcePath = join(packageRoot, "theme", "tokens.css");
const themePath = join(packageRoot, "theme", "theme.css");
const scopedOutputPath = join(packageRoot, "theme", "scoped-tokens.css");
const componentThemeOutputPath = join(
	packageRoot,
	"theme",
	"component-theme.css",
);
const checkOnly = process.argv.includes("--check");
const scopedHeader = `/*
 * Generated by scripts/generate-theme.ts from theme/tokens.css.
 * Edit tokens.css, then run \`bun run generate:theme\`.
 */

`;
const componentThemeHeader = `/*
 * Generated by scripts/generate-theme.ts from theme/tokens.css and
 * theme/theme.css. Edit those sources, then run \`bun run generate:theme\`.
 *
 * These package-specific names keep embedded components from changing generic
 * host utilities such as bg-background, text-foreground, and rounded-lg.
 */

`;

function replaceSelector(
	source: string,
	selector: string,
	replacement: string,
): string {
	const ruleStart = `${selector} {`;
	if (source.split(ruleStart).length !== 2) {
		throw new Error(`${ruleStart} must occur exactly once in ${sourcePath}`);
	}
	return source.replace(ruleStart, `${replacement} {`);
}

function readBlock(source: string, selector: string): string {
	const start = source.indexOf(`${selector} {`);
	if (start < 0) throw new Error(`Missing ${selector} block`);
	const bodyStart = source.indexOf("{", start) + 1;
	let depth = 1;
	for (let index = bodyStart; index < source.length; index += 1) {
		if (source[index] === "{") depth += 1;
		if (source[index] === "}") depth -= 1;
		if (depth === 0) return source.slice(bodyStart, index);
	}
	throw new Error(`Unclosed ${selector} block`);
}

function declarationNames(source: string): string[] {
	return Array.from(
		source.matchAll(/(^|\n)\s*(--[a-z0-9-]+)\s*:/g),
		(match) => match[2],
	);
}

function componentThemeName(rawName: string): string {
	if (rawName.startsWith("--font-weight-")) {
		return rawName.replace("--font-weight-", "--font-weight-cline-ui-");
	}
	if (rawName.startsWith("--font-")) {
		return rawName.replace("--font-", "--font-cline-ui-");
	}
	if (rawName.startsWith("--text-")) {
		const [size, ...companions] = rawName.slice("--text-".length).split("--");
		return `--text-cline-ui-${size}${companions.length ? `--${companions.join("--")}` : ""}`;
	}
	throw new Error(`Unsupported component typography token ${rawName}`);
}

function mappedDeclaration(mappedName: string, rawName: string): string {
	const declaration = `\t${mappedName}: var(${rawName});`;
	return declaration.length < 80
		? declaration
		: `\t${mappedName}: var(\n\t\t${rawName}\n\t);`;
}

function generateComponentTheme(tokens: string, theme: string): string {
	const themeNames = declarationNames(readBlock(theme, "@theme inline"));
	const colorNames = themeNames.filter((name) => name.startsWith("--color-"));
	const radiusNames = themeNames.filter((name) => name.startsWith("--radius-"));
	const typographyNames = declarationNames(readBlock(tokens, ":root")).filter(
		(name) =>
			name.startsWith("--font-") ||
			name.startsWith("--font-weight-") ||
			name.startsWith("--text-"),
	);

	const declarations = [
		...colorNames.map((name) => {
			const rawName = name.replace("--color-", "--");
			return mappedDeclaration(
				name.replace("--color-", "--color-cline-ui-"),
				rawName,
			);
		}),
		"",
		...typographyNames.map((name) =>
			mappedDeclaration(componentThemeName(name), name),
		),
		"",
		...radiusNames.map((name) =>
			mappedDeclaration(name.replace("--radius-", "--radius-cline-ui-"), name),
		),
	];

	return `${componentThemeHeader}@custom-variant cline-ui-dark (&:is(.dark *));\n\n@theme inline {\n${declarations.join("\n")}\n}\n`;
}

const source = readFileSync(sourcePath, "utf8");
const theme = readFileSync(themePath, "utf8");
const sourceWithoutHeader = source.replace(/^\/\*[\s\S]*?\*\/\s*/, "");
if (sourceWithoutHeader === source) {
	throw new Error(`${sourcePath} must start with a contract comment`);
}
const generatedScopedTokens =
	scopedHeader +
	replaceSelector(
		replaceSelector(sourceWithoutHeader, ":root", ".cline-ui-theme"),
		".dark",
		".dark .cline-ui-theme,\n.cline-ui-theme.dark",
	);
const generatedComponentTheme = generateComponentTheme(source, theme);
const outputs = [
	[scopedOutputPath, generatedScopedTokens],
	[componentThemeOutputPath, generatedComponentTheme],
] as const;

if (checkOnly) {
	for (const [outputPath, generated] of outputs) {
		if (readFileSync(outputPath, "utf8") !== generated) {
			throw new Error(`${outputPath} is out of date`);
		}
	}
	console.log("@cline/ui generated theme files are current");
} else {
	for (const [outputPath, generated] of outputs) {
		writeFileSync(outputPath, generated);
	}
	console.log("Generated @cline/ui scoped and component themes");
}

import {
	mkdirSync,
	mkdtempSync,
	readdirSync,
	readFileSync,
	rmSync,
	writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { basename, join, resolve } from "node:path";

const packageRoot = join(import.meta.dir, "..");
const importCheck = `
import { existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import {
	AgentAskQuestion,
	AgentApprovalCard,
	AgentAurora,
	AgentHeroHeading,
	AgentPromptQueue,
	AgentQuickActions,
	SearchCombobox,
	SessionStatus,
} from "@cline/ui";
import { Conversation, Message } from "@cline/ui/components/agent-chat";

for (const specifier of [
	"@cline/ui/components.css",
	"@cline/ui/components/markdown.css",
	"@cline/ui/theme/scoped-tokens.css",
]) {
	if (!existsSync(fileURLToPath(import.meta.resolve(specifier)))) {
		throw new Error("packed CSS export does not exist: " + specifier);
	}
}

const css = import.meta.resolve("@cline/ui/components/agent-chat.css");
const tokens = import.meta.resolve("@cline/ui/theme/tokens.css");
if (
	!AgentApprovalCard ||
	!AgentAskQuestion ||
	!AgentAurora ||
	!AgentHeroHeading ||
	!AgentPromptQueue ||
	!SearchCombobox ||
	!AgentQuickActions ||
	!SessionStatus ||
	!Conversation ||
	!Message ||
	!css ||
	!tokens
) {
	process.exit(1);
}
`;

async function run(command: string[], cwd: string): Promise<void> {
	const child = Bun.spawn(command, {
		cwd,
		stderr: "inherit",
		stdout: "inherit",
	});
	const exitCode = await child.exited;
	if (exitCode !== 0) {
		throw new Error(`${command.join(" ")} exited with ${exitCode}`);
	}
}

function createConsumer(root: string): void {
	mkdirSync(root, { recursive: true });
	writeFileSync(
		join(root, "package.json"),
		`${JSON.stringify({ name: "cline-ui-smoke", private: true, type: "module" }, null, 2)}\n`,
	);
}

async function compileTailwind(
	root: string,
	name: string,
	inputLines: string[],
	runner: string[],
): Promise<string> {
	const input = join(root, `${name}.css`);
	const output = join(root, `${name}-output.css`);
	writeFileSync(input, [...inputLines, ""].join("\n"));
	await run([...runner, "-i", input, "-o", output, "--minify"], root);
	return readFileSync(output, "utf8");
}

function expectCandidate(css: string, candidate: string): void {
	const selector = `.${candidate.replaceAll(":", "\\:").replaceAll("/", "\\/")}`;
	if (!css.includes(selector)) {
		throw new Error(`packed Tailwind source did not emit ${candidate}`);
	}
}

function expectFragment(css: string, fragment: string, contract: string): void {
	if (!css.includes(fragment)) {
		throw new Error(`${contract} did not emit ${fragment}`);
	}
}

async function verifyTailwindContract(
	root: string,
	runner: string[],
): Promise<void> {
	const css = await compileTailwind(
		root,
		"tailwind",
		[
			'@import "tailwindcss";',
			'@import "@cline/ui/theme/scoped-tokens.css";',
			'@import "@cline/ui/components.css";',
			"@theme inline {",
			"\t--color-background: var(--host-background);",
			"\t--radius-lg: var(--host-radius-lg);",
			"\t--text-sm--letter-spacing: var(--host-letter-spacing);",
			"}",
			'@source inline("bg-background rounded-lg text-sm");',
		],
		runner,
	);
	for (const candidate of [
		"bg-cline-ui-background/95",
		"border-cline-ui-border/60",
		"text-cline-ui-muted-foreground",
		"bg-cline-ui-primary/10",
		"max-h-56",
		"leading-none",
		"max-h-44",
		"not-last:border-b",
		"focus-visible:outline-3",
		"min-h-8",
		"resize-none",
	]) {
		expectCandidate(css, candidate);
	}
	for (const fragment of [
		"background-color:var(--host-background)",
		"border-radius:var(--host-radius-lg)",
		"letter-spacing:var(--host-letter-spacing)",
	]) {
		expectFragment(css, fragment, "host Tailwind namespace");
	}

	const noPreflightCss = await compileTailwind(
		root,
		"tailwind-no-preflight",
		[
			"@layer theme, base, components, utilities;",
			'@import "tailwindcss/theme.css" layer(theme);',
			'@import "@cline/ui/theme/scoped-tokens.css";',
			'@import "@cline/ui/components.css";',
			'@import "tailwindcss/utilities.css" layer(utilities);',
		],
		runner,
	);
	for (const fragment of [
		"box-sizing:border-box",
		"border-style:solid",
		"font-family:inherit",
		"margin:.5rem 0 0",
		"padding-block:0",
	]) {
		expectFragment(noPreflightCss, fragment, "no-Preflight Tailwind contract");
	}
}

const temporaryRoot = mkdtempSync(join(tmpdir(), "cline-ui-package-"));

try {
	let archive = process.argv[2] ? resolve(process.argv[2]) : undefined;
	if (!archive) {
		const packDirectory = join(temporaryRoot, "pack");
		mkdirSync(packDirectory, { recursive: true });
		await run(
			[
				process.execPath,
				"pm",
				"pack",
				"--ignore-scripts",
				"--destination",
				packDirectory,
			],
			packageRoot,
		);
		const archiveName = readdirSync(packDirectory).find((name) =>
			name.endsWith(".tgz"),
		);
		if (!archiveName) throw new Error("bun pm pack did not create an archive");
		archive = join(packDirectory, archiveName);
	}

	const bunConsumer = join(temporaryRoot, "bun-consumer");
	createConsumer(bunConsumer);
	await run(
		[
			process.execPath,
			"add",
			"--ignore-scripts",
			archive,
			"react@19.2.4",
			"tailwindcss@4.2.0",
			"@tailwindcss/cli@4.2.0",
		],
		bunConsumer,
	);
	await run([process.execPath, "-e", importCheck], bunConsumer);
	await verifyTailwindContract(bunConsumer, [
		process.execPath,
		"x",
		"tailwindcss",
	]);

	const npmConsumer = join(temporaryRoot, "npm-consumer");
	createConsumer(npmConsumer);
	await run(
		[
			"npm",
			"install",
			"--ignore-scripts",
			"--no-audit",
			"--no-fund",
			archive,
			"react@18.3.1",
			"tailwindcss@4.2.0",
			"@tailwindcss/cli@4.2.0",
		],
		npmConsumer,
	);
	await run(["node", "--input-type=module", "-e", importCheck], npmConsumer);
	await verifyTailwindContract(npmConsumer, [
		"npx",
		"--no-install",
		"tailwindcss",
	]);
	console.log(
		`Verified packed ${basename(archive)} with Bun/React 19 and npm/Node/React 18, including Tailwind contracts`,
	);
} finally {
	rmSync(temporaryRoot, { force: true, recursive: true });
}

import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";

const packageRoot = join(import.meta.dir, "..");
const readThemeFile = (name: string) =>
	readFileSync(join(packageRoot, "theme", name), "utf8");

const tokens = readThemeFile("tokens.css");
const tokensWithoutComments = tokens.replace(/\/\*[\s\S]*?\*\//g, "");
const theme = readThemeFile("theme.css");
const componentTheme = readThemeFile("component-theme.css");
const base = readThemeFile("base.css");
const index = readThemeFile("index.css");
const components = readFileSync(join(packageRoot, "components.css"), "utf8");
const manifest = JSON.parse(
	readFileSync(join(packageRoot, "package.json"), "utf8"),
) as { exports?: Record<string, string> };

const requiredTokens = [
	"--background",
	"--foreground",
	"--primary",
	"--border",
	"--font-sans",
	"--font-mono",
	"--font-weight-normal",
	"--text-xs",
	"--text-6xl",
	"--sidebar",
];

for (const token of requiredTokens) {
	if (!tokens.includes(`${token}:`)) {
		throw new Error(`tokens.css is missing ${token}`);
	}
}

if (
	tokens.includes("--cline-") ||
	theme.includes("--cline-") ||
	base.includes("--cline-")
) {
	throw new Error("theme contract must not expose --cline-* variables");
}
if (/@(?:apply|custom-variant|layer|theme)\b/.test(tokensWithoutComments)) {
	throw new Error("tokens.css must remain framework-neutral");
}
if (theme.includes("tokens.css") || !theme.includes("@theme inline")) {
	throw new Error(
		"theme.css must contain only the Tailwind mapping and variants",
	);
}
if (
	!componentTheme.includes("Generated by scripts/generate-theme.ts") ||
	!componentTheme.includes("@custom-variant cline-ui-dark") ||
	!componentTheme.includes("@theme inline") ||
	componentTheme.includes("@custom-variant dark ")
) {
	throw new Error(
		"component-theme.css must contain the generated namespaced Tailwind contract",
	);
}
if (!components.includes('@import "./theme/component-theme.css";')) {
	throw new Error("components.css must import the namespaced component theme");
}
if (base.includes("#__next") || base.includes("@source")) {
	throw new Error("base.css must not contain consumer-specific shell policy");
}
if (
	!index.includes('@import "./tokens.css";') ||
	!index.includes('@import "./theme.css";') ||
	!index.includes('@import "./base.css";')
) {
	throw new Error("theme entry point must compose tokens, theme, and base CSS");
}
for (const subpath of [
	"./components.css",
	"./components/markdown.css",
	"./theme/index.css",
	"./theme/scoped-tokens.css",
	"./theme/tokens.css",
	"./theme/theme.css",
	"./theme/base.css",
]) {
	const target = manifest.exports?.[subpath];
	if (!target || !existsSync(join(packageRoot, target))) {
		throw new Error(`package.json export ${subpath} is missing or invalid`);
	}
}

console.log("@cline/ui theme contract is valid");

