#!/usr/bin/env bun

import { mkdtemp, readdir, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

type PackageInfo = {
	name: string;
	dir: string;
	workspace: string;
};

type PackedManifest = {
	name?: string;
	version?: string;
	dependencies?: Record<string, string>;
	exports?: unknown;
};

const root = join(import.meta.dir, "..");
const packagesDir = join(root, "packages");

async function runCommandOrThrow(
	cmd: string[],
	options: {
		cwd: string;
		env?: Record<string, string | undefined>;
		stdout?: "inherit" | "pipe";
		stderr?: "inherit" | "pipe";
	},
): Promise<string> {
	const proc = Bun.spawn(cmd, {
		cwd: options.cwd,
		env: options.env,
		stdout: options.stdout ?? "inherit",
		stderr: options.stderr ?? "inherit",
	});
	const exitCode = await proc.exited;
	const stdout =
		options.stdout === "pipe" && proc.stdout
			? await new Response(proc.stdout).text()
			: "";
	const stderr =
		options.stderr === "pipe" && proc.stderr
			? await new Response(proc.stderr).text()
			: "";
	if (exitCode !== 0) {
		throw new Error(
			stderr.trim() ||
				stdout.trim() ||
				`${cmd[0]} exited with code ${exitCode}`,
		);
	}
	return stdout;
}

async function listPublishedPackages(): Promise<PackageInfo[]> {
	const dirs = await readdir(packagesDir, { withFileTypes: true });
	const workspaces = dirs.filter((d) => d.isDirectory()).map((d) => d.name);
	const published: PackageInfo[] = [];

	for (const workspace of workspaces) {
		const pkgPath = join(packagesDir, workspace, "package.json");
		try {
			const pkg = JSON.parse(await readFile(pkgPath, "utf-8"));
			if (!pkg.internal && typeof pkg.name === "string") {
				published.push({
					name: pkg.name,
					dir: join(packagesDir, workspace),
					workspace,
				});
			}
		} catch {
			// skip directories without a package manifest
		}
	}

	return published;
}

async function packWorkspacePackage(
	pkg: PackageInfo,
	packRoot: string,
): Promise<string> {
	const destination = await mkdtemp(join(packRoot, `${pkg.workspace}-`));
	await runCommandOrThrow(["bun", "pm", "pack", "--destination", destination], {
		cwd: pkg.dir,
	});
	const files = (await readdir(destination)).filter((file) =>
		file.endsWith(".tgz"),
	);
	if (files.length !== 1) {
		throw new Error(
			`Expected one tarball for ${pkg.name}, found ${files.length} in ${destination}`,
		);
	}
	return join(destination, files[0]);
}

async function readPackedPackageJson(tarball: string): Promise<PackedManifest> {
	const raw = await runCommandOrThrow(
		["tar", "-xOf", tarball, "package/package.json"],
		{
			cwd: root,
			stdout: "pipe",
			stderr: "pipe",
		},
	);
	return JSON.parse(raw) as PackedManifest;
}

function containsDevelopmentExportCondition(value: unknown): boolean {
	if (value === null || typeof value !== "object") {
		return false;
	}
	if (Array.isArray(value)) {
		return value.some(containsDevelopmentExportCondition);
	}
	if (Object.hasOwn(value, "development")) {
		return true;
	}
	return Object.values(value).some(containsDevelopmentExportCondition);
}

async function main(): Promise<number> {
	const published = await listPublishedPackages();
	if (published.length === 0) {
		console.error("No published packages found");
		return 1;
	}

	console.log(
		`\nFound ${published.length} published package(s): ${published.map((pkg) => pkg.name).join(", ")}\n`,
	);

	const testDir = await mkdtemp(join(tmpdir(), "cline-pkg-verify-"));
	const packDir = await mkdtemp(join(tmpdir(), "cline-pkg-packs-"));
	const bunCacheDir = await mkdtemp(join(tmpdir(), "cline-pkg-bun-cache-"));
	const tarballs: { name: string; tarball: string }[] = [];
	const packedManifests = new Map<string, PackedManifest>();

	let exitCode = 0;

	try {
		console.log("--- Packing tarballs with Bun ---");
		for (const pkg of published) {
			const tarball = await packWorkspacePackage(pkg, packDir);
			tarballs.push({ name: pkg.name, tarball });
			packedManifests.set(pkg.name, await readPackedPackageJson(tarball));
			console.log(`  ${pkg.name} -> ${tarball.split("/").pop()}`);
		}

		console.log("\n--- Verifying packed manifest versions ---");
		let manifestFailed = false;
		for (const [pkgName, manifest] of packedManifests.entries()) {
			for (const [depName, depVersion] of Object.entries(
				manifest.dependencies ?? {},
			)) {
				const packedDep = packedManifests.get(depName);
				if (!packedDep) {
					continue;
				}
				if (depVersion !== packedDep.version) {
					console.error(
						`  FAIL ${pkgName}: dependencies.${depName} = "${depVersion}" but packed ${depName} version is "${packedDep.version}"`,
					);
					manifestFailed = true;
				}
			}
		}
		if (manifestFailed) {
			console.info(
				"\nPacked manifest dependency versions are not aligned. Please ensure that all workspace dependencies are declared with exact versions that match the packed versions.\n",
			);
			console.info(
				"Try running `bun scripts/version.ts <version>` to update package manifests and regenerate lockfile entries with exact versions for workspace dependencies, before running this script again.",
			);
			return 1;
		}
		console.log("  OK - packed workspace dependency versions are aligned\n");

		console.log("\n--- Verifying packed export maps ---");
		let exportMapFailed = false;
		for (const [pkgName, manifest] of packedManifests.entries()) {
			if (containsDevelopmentExportCondition(manifest.exports)) {
				console.error(
					`  FAIL ${pkgName}: packed package exports include a "development" condition`,
				);
				exportMapFailed = true;
			}
		}
		if (exportMapFailed) {
			console.info(
				"\nPublished packages must resolve to built dist files even when consumers enable custom development conditions.\n",
			);
			return 1;
		}
		console.log(
			"  OK - packed export maps do not include development conditions\n",
		);

		console.log("\n--- Installing packages in isolated directory ---");
		const tarballDependencies = Object.fromEntries(
			tarballs.map((entry) => [entry.name, `file:${entry.tarball}`]),
		);
		const testPkg = {
			name: "cline-pkg-verify",
			private: true,
			type: "module",
			dependencies: tarballDependencies,
			overrides: tarballDependencies,
		};
		await writeFile(
			join(testDir, "package.json"),
			JSON.stringify(testPkg, null, 2),
		);

		await runCommandOrThrow(["bun", "install", "--ignore-scripts"], {
			cwd: testDir,
			env: {
				...process.env,
				BUN_INSTALL_CACHE_DIR: bunCacheDir,
			},
			stdout: "pipe",
			stderr: "pipe",
		});
		console.log("  OK - bun install succeeded\n");

		console.log("--- Verifying module resolution ---");
		let importFailed = false;
		for (const pkg of published) {
			const testFile = join(testDir, `test-${pkg.workspace}.ts`);
			await writeFile(
				testFile,
				[
					`try {`,
					`  await import("${pkg.name}");`,
					`  console.log("  OK ${pkg.name}");`,
					`} catch (e: any) {`,
					`  console.error("  FAIL ${pkg.name}:", e.message);`,
					`  if (e.code) console.error("       code:", e.code);`,
					`  process.exitCode = 1;`,
					`}`,
				].join("\n"),
			);
			try {
				const proc = Bun.spawn(["bun", testFile], {
					cwd: testDir,
					stdout: "pipe",
					stderr: "pipe",
				});
				const result = await Promise.race([
					proc.exited,
					new Promise<never>((_, reject) =>
						setTimeout(() => {
							proc.kill();
							reject(new Error("timed out after 30s"));
						}, 30_000),
					),
				]);
				const stdout = await new Response(proc.stdout).text();
				const stderr = await new Response(proc.stderr).text();
				const output = (stdout + stderr).trim();
				if (output) console.log(output);
				if (result !== 0 || output.includes("FAIL")) {
					importFailed = true;
				}
			} catch (error: unknown) {
				importFailed = true;
				const message = error instanceof Error ? error.message : String(error);
				console.error(`  FAIL - could not import ${pkg.name}: ${message}`);
			}
		}

		console.log("\n--- Verifying publish-only package invariants ---");
		for (const pkg of published) {
			if (pkg.name !== "@cline/core") {
				continue;
			}

			const testFile = join(testDir, `test-${pkg.workspace}-publish-shape.ts`);
			await writeFile(
				testFile,
				[
					`import { readFileSync } from "node:fs";`,
					`import { join } from "node:path";`,
					`try {`,
					`  const root = await import("@cline/core");`,
					`  if (typeof root.ClineCore?.create !== "function") {`,
					`    console.error("  FAIL @cline/core: root export is missing ClineCore.create");`,
					`    process.exit(1);`,
					`  }`,
					`} catch (error) {`,
					`  const message = error instanceof Error ? error.message : String(error);`,
					`  console.error("  FAIL @cline/core: published runtime shape is invalid:", message);`,
					`  process.exit(1);`,
					`}`,
					`console.log("  OK @cline/core publish shape");`,
				].join("\n"),
			);
			try {
				const proc = Bun.spawn(["bun", testFile], {
					cwd: testDir,
					stdout: "pipe",
					stderr: "pipe",
				});
				const result = await Promise.race([
					proc.exited,
					new Promise<never>((_, reject) =>
						setTimeout(() => {
							proc.kill();
							reject(new Error("timed out after 30s"));
						}, 30_000),
					),
				]);
				const stdout = await new Response(proc.stdout).text();
				const stderr = await new Response(proc.stderr).text();
				const output = (stdout + stderr).trim();
				if (output) console.log(output);
				if (result !== 0 || output.includes("FAIL")) {
					importFailed = true;
				}
			} catch (error: unknown) {
				importFailed = true;
				const message = error instanceof Error ? error.message : String(error);
				console.error(
					`  FAIL - could not verify publish shape for ${pkg.name}: ${message}`,
				);
			}
		}

		if (importFailed) {
			console.error("\nSome packages failed to import.");
			exitCode = 1;
		} else {
			console.log("\nAll packages verified successfully.");
		}
	} catch (error: unknown) {
		exitCode = 1;
		const message = error instanceof Error ? error.message : String(error);
		console.error(`\nVerification failed:\n${message}`);
	} finally {
		await rm(testDir, { recursive: true, force: true });
		await rm(packDir, { recursive: true, force: true });
		await rm(bunCacheDir, { recursive: true, force: true });
	}

	return exitCode;
}

process.exit(await main());

#!/usr/bin/env bun

import { mkdtemp, readdir, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

const root = join(import.meta.dir, "..");
const npmCommand = process.platform === "win32" ? "npm.cmd" : "npm";

async function runCommand(
	cmd: string[],
	options: {
		cwd: string;
		env?: Record<string, string | undefined>;
		captureStdout?: boolean;
		timeoutMs?: number;
	},
): Promise<string> {
	const captureStdout = options.captureStdout === true;
	let timedOut = false;
	const proc = Bun.spawn(cmd, {
		cwd: options.cwd,
		env: {
			...process.env,
			...options.env,
		},
		stdout: captureStdout ? "pipe" : "inherit",
		stderr: "inherit",
	});
	const stdoutPromise =
		captureStdout && proc.stdout
			? new Response(proc.stdout).text()
			: Promise.resolve("");
	const timeout = setTimeout(
		() => {
			timedOut = true;
			proc.kill();
		},
		options.timeoutMs ?? 5 * 60_000,
	);
	timeout.unref();
	const exitCode = await proc.exited.finally(() => clearTimeout(timeout));
	const stdout = await stdoutPromise;
	if (exitCode !== 0) {
		if (timedOut) {
			throw new Error(
				`${cmd.join(" ")} timed out after ${options.timeoutMs ?? 5 * 60_000}ms`,
			);
		}
		throw new Error(`${cmd.join(" ")} exited with code ${exitCode}`);
	}
	return stdout.trim();
}

async function packWorkspace(
	workspace: "core" | "agents" | "llms" | "shared",
	packDir: string,
): Promise<string> {
	const destination = await mkdtemp(join(packDir, `${workspace}-`));
	await runCommand(["bun", "pm", "pack", "--destination", destination], {
		cwd: join(root, `packages/${workspace}`),
		timeoutMs: 2 * 60_000,
	});
	const files = (await readdir(destination)).filter((file) =>
		file.endsWith(".tgz"),
	);
	if (files.length !== 1) {
		throw new Error(
			`Expected one tarball for ${workspace}, found ${files.length}`,
		);
	}
	return join(destination, files[0]);
}

async function main(): Promise<void> {
	const packDir = await mkdtemp(join(tmpdir(), "cline-node-smoke-packs-"));
	const smokeDir = await mkdtemp(join(tmpdir(), "cline-node-smoke-"));
	const sessionsDir = await mkdtemp(join(tmpdir(), "cline-node-sessions-"));
	const npmCacheDir = await mkdtemp(join(tmpdir(), "cline-node-npm-cache-"));
	const npmEnv = { npm_config_cache: npmCacheDir };

	try {
		console.log("Packing smoke-test tarballs with Bun...");
		const tarballs = {
			core: await packWorkspace("core", packDir),
			agents: await packWorkspace("agents", packDir),
			llms: await packWorkspace("llms", packDir),
			shared: await packWorkspace("shared", packDir),
		};

		await writeFile(
			join(smokeDir, "package.json"),
			`${JSON.stringify(
				{
					name: "cline-node-smoke",
					private: true,
					type: "module",
					dependencies: {
						"@cline/core": `file:${tarballs.core}`,
						"@cline/agents": `file:${tarballs.agents}`,
						"@cline/llms": `file:${tarballs.llms}`,
						"@cline/shared": `file:${tarballs.shared}`,
					},
				},
				null,
				2,
			)}\n`,
		);

		console.log("Installing smoke-test dependencies...");
		await runCommand([npmCommand, "install"], {
			cwd: smokeDir,
			env: npmEnv,
			timeoutMs: 10 * 60_000,
		});

		const nodeMajor = Number(process.versions.node.split(".")[0] || "0");
		const smokeSource =
			nodeMajor >= 24
				? `
					const { SqliteSessionStore } = await import("@cline/core");
					const store = new SqliteSessionStore({ sessionsDir: process.env.CLINE_DATA_DIR });
					try {
						store.init();
						console.log("SQLite smoke test passed");
					} finally {
						store.close();
					}
				`
				: `
					const { resolveSessionBackend } = await import("@cline/core");
					await resolveSessionBackend({ backendMode: "local" });
					console.log("Node compatibility smoke test passed");
				`;
		const smokeFile = join(smokeDir, "smoke.mjs");
		await writeFile(smokeFile, `${smokeSource.trim()}\n`);

		console.log("Running smoke test...");
		await runCommand(["node", smokeFile], {
			cwd: smokeDir,
			env: {
				...npmEnv,
				CLINE_DATA_DIR: sessionsDir,
			},
			timeoutMs: 2 * 60_000,
		});
	} finally {
		await rm(packDir, { recursive: true, force: true });
		await rm(smokeDir, { recursive: true, force: true });
		await rm(sessionsDir, { recursive: true, force: true });
		await rm(npmCacheDir, { recursive: true, force: true });
	}
}

await main();

#!/usr/bin/env bun

/**
 * Cross-platform `clean` for the SDK monorepo.
 *
 * Deletes `dist` and `node_modules` from every workspace listed in the root
 * package.json, plus the repo root itself. Runs serially to avoid races between
 * sibling workspaces whose `node_modules` are wired together via symlinks /
 * junctions on Windows.
 *
 */

import { readFile, rm, stat } from "node:fs/promises";
import path from "node:path";
import { Glob } from "bun";

type RootPackageJson = {
	workspaces?: string[];
};

const TARGETS = ["dist", "node_modules"] as const;

const root = path.join(import.meta.dir, "..", "..");

async function readWorkspaceGlobs(): Promise<string[]> {
	const raw = await readFile(path.join(root, "package.json"), "utf8");
	const pkg = JSON.parse(raw) as RootPackageJson;
	return pkg.workspaces ?? [];
}

async function expandWorkspaces(globs: string[]): Promise<string[]> {
	const dirs = new Set<string>();

	for (const pattern of globs) {
		// Bun.Glob expects forward slashes. The workspaces field already uses
		// them, but normalize defensively.
		const normalized = pattern.replaceAll("\\", "/");
		const glob = new Glob(normalized);

		for await (const match of glob.scan({
			cwd: root,
			onlyFiles: false,
			absolute: false,
		})) {
			const absolute = path.join(root, match);
			let isDir = false;
			try {
				const info = await stat(absolute);
				isDir = info.isDirectory();
			} catch {
				continue;
			}
			if (isDir) {
				dirs.add(absolute);
			}
		}
	}

	return [...dirs].sort();
}

async function removeTargetsIn(dir: string): Promise<void> {
	for (const target of TARGETS) {
		const targetPath = path.join(dir, target);
		try {
			await rm(targetPath, { recursive: true, force: true });
			console.log(`  removed ${path.relative(root, targetPath) || target}`);
		} catch (err) {
			const message = err instanceof Error ? err.message : String(err);
			console.warn(
				`  skipped ${path.relative(root, targetPath) || target}: ${message}`,
			);
		}
	}
}

async function main(): Promise<void> {
	const globs = await readWorkspaceGlobs();
	const workspaceDirs = await expandWorkspaces(globs);

	// Always include the repo root last so its node_modules (which hosts the
	// hoisted binaries that just ran) is removed after every workspace is done.
	const allDirs = [...workspaceDirs, root];

	for (const dir of allDirs) {
		console.log(`cleaning ${path.relative(root, dir) || "."}`);
		await removeTargetsIn(dir);
	}
}

await main();

#!/usr/bin/env bun

/** biome-ignore-all lint/style/noNonNullAssertion: expected non-null assertions */

/**
 * Unified release script for SDK packages and CLI.
 *
 * Usage:
 *   bun release sdk                          # auto-increment patch, publish SDK
 *   bun release sdk 0.1.0                    # publish SDK at exact version
 *   bun release sdk 0.1.0 --tag next         # publish SDK with npm tag
 *   bun release cli                          # publish CLI from the current tagged commit
 *   bun release cli 0.1.0                    # require apps/cli/package.json to match
 *   bun release cli --dry-run                # preview without side effects
 *   bun release sdk --skip-tests             # skip the test suite
 *   bun release sdk --skip-git-tags          # skip git tag creation
 */

import { constants } from "node:fs";
import { copyFile, readdir, readFile, unlink } from "node:fs/promises";
import { join } from "node:path";
import { parseArgs } from "node:util";

// ── CLI args ──────────────────────────────────────────────────────────────────

const { values, positionals } = parseArgs({
	args: Bun.argv.slice(2),
	options: {
		"dry-run": { type: "boolean", default: false },
		tag: { type: "string", default: "latest" },
		"skip-tests": { type: "boolean", default: false },
		"skip-git-tags": { type: "boolean", default: false },
	},
	allowPositionals: true,
	strict: true,
});

const dryRun = values["dry-run"]!;
const npmTag = values.tag!;
const skipTests = values["skip-tests"]!;
const skipGitTags = values["skip-git-tags"]!;

const target = positionals[0] as "sdk" | "cli" | undefined;
const explicitVersion = positionals[1];

if (!target || !["sdk", "cli"].includes(target)) {
	console.error("Usage: bun release <sdk|cli> [version] [options]");
	console.error("");
	console.error("Targets:");
	console.error("  sdk   Publish @cline/{shared,llms,agents,core,sdk} to npm");
	console.error("  cli   Publish cline from an existing cli-vX.Y.Z git tag");
	console.error("");
	console.error("Options:");
	console.error(
		"  [version]        Semver version (omit to auto-increment patch)",
	);
	console.error('  --tag <tag>      npm dist-tag (default: "latest")');
	console.error("  --dry-run        Preview all steps without side effects");
	console.error("  --skip-tests     Skip running the test suite");
	console.error("  --skip-git-tags  Skip git tag creation");
	console.error("");
	console.error("Examples:");
	console.error("  bun release sdk");
	console.error("  bun release sdk 0.1.0");
	console.error("  bun release sdk 0.1.0 --tag next");
	console.error("  bun release cli");
	process.exit(1);
}

if (explicitVersion && !/^\d+\.\d+\.\d+(-[\w.]+)?$/.test(explicitVersion)) {
	console.error(`Invalid semver version: ${explicitVersion}`);
	process.exit(1);
}

// ── Constants ─────────────────────────────────────────────────────────────────

const SDK_PUBLISH_ORDER = ["shared", "llms", "agents", "core", "sdk"] as const;
const MAIN_BRANCH = "main";
const root = join(import.meta.dir, "..", "..");
const sdkRoot = join(import.meta.dir, "..");
const packagesDir = join(sdkRoot, "packages");
const cliDir = join(sdkRoot, "../apps/cli");

// ── Helpers ───────────────────────────────────────────────────────────────────

function header(msg: string): void {
	console.log(`\n${"─".repeat(60)}`);
	console.log(`  ${msg}`);
	console.log(`${"─".repeat(60)}\n`);
}

async function run(
	cmd: string[],
	options: { cwd?: string; stdout?: "inherit" | "pipe" } = {},
): Promise<string> {
	const cwd = options.cwd ?? root;
	const label = cmd.join(" ");

	if (dryRun) {
		console.log(`  [dry-run] ${label}`);
		return "";
	}

	console.log(`  $ ${label}`);

	const proc = Bun.spawn(cmd, {
		cwd,
		stdin: "inherit",
		stdout: options.stdout ?? "inherit",
		stderr: "inherit",
	});

	const exitCode = await proc.exited;
	const stdout =
		options.stdout === "pipe" && proc.stdout
			? await new Response(proc.stdout).text()
			: "";

	if (exitCode !== 0) {
		throw new Error(`Command failed (exit ${exitCode}): ${label}`);
	}
	return stdout;
}

async function stageSdkReadmeForPublish(
	workspace: (typeof SDK_PUBLISH_ORDER)[number],
): Promise<string | undefined> {
	if (workspace !== "sdk") {
		return undefined;
	}

	const destination = join(packagesDir, "sdk", "README.md");

	if (dryRun) {
		console.log(`  [dry-run] Copy README.md to ${destination}`);
		return undefined;
	}

	await copyFile(
		join(sdkRoot, "README.md"),
		destination,
		constants.COPYFILE_EXCL,
	);
	return destination;
}

async function removeStagedSdkReadme(path: string | undefined): Promise<void> {
	if (!path) {
		return;
	}

	await unlink(path);
}

async function confirm(prompt: string): Promise<boolean> {
	process.stdout.write(`${prompt} [y/N] `);
	for await (const line of console) {
		const answer = line.trim().toLowerCase();
		return answer === "y" || answer === "yes";
	}
	return false;
}

function incrementPatchVersion(input: string): string {
	const match = input.match(/^(\d+)\.(\d+)\.(\d+)(-[\w.]+)?$/);
	if (!match) {
		throw new Error(`Invalid semver version: ${input}`);
	}
	const [, major, minor, patch] = match;
	return `${major}.${minor}.${Number(patch) + 1}`;
}

async function resolveVersion(): Promise<string> {
	if (explicitVersion) return explicitVersion;

	// Read the current version from the first workspace package that has one,
	// same logic as version.ts.
	const dirs = await readdir(packagesDir, { withFileTypes: true });
	for (const dir of dirs) {
		if (!dir.isDirectory()) continue;
		try {
			const raw = await readFile(
				join(packagesDir, dir.name, "package.json"),
				"utf-8",
			);
			const pkg = JSON.parse(raw);
			if (typeof pkg.version === "string" && pkg.version !== "0.0.0") {
				const next = incrementPatchVersion(pkg.version);
				console.log(
					`  No version specified, auto-incrementing: ${pkg.version} -> ${next}`,
				);
				return next;
			}
		} catch {
			// skip
		}
	}
	throw new Error(
		"Could not determine current version from workspace packages.",
	);
}

async function resolveCliVersion(): Promise<string> {
	const raw = await readFile(join(cliDir, "package.json"), "utf-8");
	const pkg: unknown = JSON.parse(raw);
	const version =
		pkg !== null &&
		typeof pkg === "object" &&
		!Array.isArray(pkg) &&
		"version" in pkg &&
		typeof pkg.version === "string"
			? pkg.version
			: undefined;
	if (!version) {
		throw new Error("Could not determine version from apps/cli/package.json.");
	}
	if (!/^\d+\.\d+\.\d+(-[\w.]+)?$/.test(version)) {
		throw new Error(`Invalid apps/cli/package.json version: ${version}`);
	}
	if (explicitVersion && explicitVersion !== version) {
		throw new Error(
			`CLI version argument ${explicitVersion} does not match apps/cli/package.json version ${version}. Update apps/cli/package.json first.`,
		);
	}
	return version;
}

async function ensureMainBranch(): Promise<void> {
	const branch = (
		await run(["git", "rev-parse", "--abbrev-ref", "HEAD"], { stdout: "pipe" })
	).trim();

	if (dryRun) {
		console.log(`  [dry-run] Current branch: ${branch || "(unknown)"}`);
		return;
	}

	if (branch === MAIN_BRANCH) {
		console.log(`  Already on ${MAIN_BRANCH}`);
		return;
	}

	// Check for uncommitted changes before switching
	const status = (
		await run(["git", "status", "--porcelain"], { stdout: "pipe" })
	).trim();
	if (status) {
		throw new Error(
			`Working tree is dirty. Commit or stash changes before releasing.\n${status}`,
		);
	}

	console.log(`  Switching from ${branch} to ${MAIN_BRANCH}...`);
	await run(["git", "checkout", MAIN_BRANCH]);
	await run(["git", "pull", "--ff-only"]);
}

async function ensureCleanWorkingTree(): Promise<void> {
	const status = (
		await run(["git", "status", "--porcelain"], { stdout: "pipe" })
	).trim();
	if (status) {
		throw new Error(
			`Working tree is dirty. Commit or stash changes before releasing.\n${status}`,
		);
	}
}

async function ensureCliReleaseTag(version: string): Promise<void> {
	const expectedTag = `cli-v${version}`;
	if (dryRun) {
		console.log(`  [dry-run] Required pushed git tag: ${expectedTag}`);
		return;
	}
	const headCommit = (
		await run(["git", "rev-parse", "HEAD"], { stdout: "pipe" })
	).trim();
	const shortHead = headCommit.slice(0, 12);
	const tagsAtHead = (
		await run(["git", "tag", "--points-at", "HEAD"], { stdout: "pipe" })
	)
		.split(/\r?\n/)
		.map((tag) => tag.trim())
		.filter(Boolean);
	if (!tagsAtHead.includes(expectedTag)) {
		const localTagExists = (
			await run(["git", "tag", "--list", expectedTag], { stdout: "pipe" })
		).trim();
		if (localTagExists) {
			const taggedCommit = (
				await run(["git", "rev-parse", `${expectedTag}^{commit}`], {
					stdout: "pipe",
				})
			).trim();
			throw new Error(
				[
					`Tag ${expectedTag} points at ${taggedCommit.slice(0, 12)}, but current HEAD is ${shortHead}.`,
					"Check out the tagged commit before publishing:",
					`  git checkout ${expectedTag}`,
				].join("\n"),
			);
		}
		throw new Error(
			`Current HEAD is not tagged ${expectedTag}. Create and push the tag before publishing.`,
		);
	}
	const localTagCommit = (
		await run(
			["git", "rev-parse", "-q", "--verify", `${expectedTag}^{commit}`],
			{
				stdout: "pipe",
			},
		)
	).trim();
	if (localTagCommit !== headCommit) {
		throw new Error(
			`Current commit is not tagged ${expectedTag}. Create the tag on HEAD before publishing.`,
		);
	}

	const remoteRefs = (
		await run(
			[
				"git",
				"ls-remote",
				"origin",
				`refs/tags/${expectedTag}`,
				`refs/tags/${expectedTag}^{}`,
			],
			{ stdout: "pipe" },
		)
	)
		.split(/\r?\n/)
		.map((line) => line.trim())
		.filter(Boolean);
	const remotePeeledRef = remoteRefs.find((line) =>
		line.endsWith(`refs/tags/${expectedTag}^{}`),
	);
	const remoteTagRef = remoteRefs.find((line) =>
		line.endsWith(`refs/tags/${expectedTag}`),
	);
	const remoteTagCommit = (remotePeeledRef ?? remoteTagRef)?.split(/\s+/)[0];
	if (remoteTagCommit !== headCommit) {
		if (remoteTagCommit) {
			throw new Error(
				[
					`Remote tag ${expectedTag} points at ${remoteTagCommit.slice(0, 12)}, but current HEAD is ${shortHead}.`,
					"Check out the tagged commit or push the correct tag before publishing.",
				].join("\n"),
			);
		}
		throw new Error(
			`Remote tag ${expectedTag} must exist on origin and point at HEAD before publishing.`,
		);
	}
	console.log(`  Found pushed git tag: ${expectedTag}`);
}

async function getPublishedPackages(): Promise<
	{ name: string; workspace: string }[]
> {
	const dirs = await readdir(packagesDir, { withFileTypes: true });
	const packages: { name: string; workspace: string }[] = [];

	for (const dir of dirs) {
		if (!dir.isDirectory()) continue;
		try {
			const raw = await readFile(
				join(packagesDir, dir.name, "package.json"),
				"utf-8",
			);
			const pkg = JSON.parse(raw);
			if (!pkg.internal && typeof pkg.name === "string") {
				packages.push({ name: pkg.name, workspace: dir.name });
			}
		} catch {
			// skip directories without package.json
		}
	}
	return packages;
}

// ── SDK Release ───────────────────────────────────────────────────────────────

async function releaseSDK(version: string): Promise<number> {
	const published = await getPublishedPackages();
	const packageNames = published.map((p) => p.name);

	console.log(`\nRelease SDK`);
	console.log(`  Version:     ${version}`);
	console.log(`  Tag:         ${npmTag}`);
	console.log(`  Dry run:     ${dryRun}`);
	console.log(`  Skip tests:  ${skipTests}`);
	console.log(`  Packages:    ${packageNames.join(", ")}`);

	if (!dryRun) {
		const ok = await confirm("\nProceed with SDK release?");
		if (!ok) {
			console.log("Aborted.");
			return 1;
		}
	}

	// Step 1: Tests
	if (!skipTests) {
		header("Step 1/5: Running tests");
		await run(["bun", "run", "test"]);
	} else {
		header("Step 1/5: Skipping tests (--skip-tests)");
	}

	// Step 2: Update versions
	// version.ts handles: version bump -> lockfile regeneration -> generate:models -> format -> build
	header("Step 2/5: Updating package versions and lockfile");
	await run(["bun", "scripts/version.ts", version], { cwd: sdkRoot });

	// Step 3: Verify publishability
	header("Step 3/5: Verifying packed tarballs");
	await run(["bun", "scripts/check-publish.ts"], { cwd: sdkRoot });

	// Step 4: Publish in dependency order
	header("Step 4/5: Publishing packages");
	for (const workspace of SDK_PUBLISH_ORDER) {
		const pkgDir = join(packagesDir, workspace);
		const name = `@cline/${workspace}`;
		console.log(`  Publishing ${name}@${version} with tag '${npmTag}'...`);
		const stagedReadme = await stageSdkReadmeForPublish(workspace);
		try {
			await run(["bun", "publish", "--tag", npmTag, "--access", "public"], {
				cwd: pkgDir,
			});
		} finally {
			await removeStagedSdkReadme(stagedReadme);
		}
	}

	// Step 5: Git tag
	if (npmTag === "latest" && !skipGitTags) {
		header("Step 5/5: Creating git tag");
		const gitTag = `sdk-v${version}`;
		console.log(`  Creating tag: ${gitTag}`);
		await run(["git", "tag", "-a", gitTag, "-m", `SDK v${version}`]);

		if (!dryRun) {
			const pushOk = await confirm(
				"\nPush tag to remote? This makes the release public.",
			);
			if (pushOk) {
				await run(["git", "push", "origin", `refs/tags/${gitTag}`]);
			} else {
				console.log(`  Skipped pushing tag. Push manually with:`);
				console.log(`    git push origin refs/tags/${gitTag}`);
			}
		}
	} else if (skipGitTags) {
		header("Step 5/5: Skipping git tag (--skip-git-tags)");
	} else {
		header("Step 5/5: Skipping git tag (non-latest channel)");
	}

	// Done
	console.log(`\n${"═".repeat(60)}`);
	if (dryRun) {
		console.log("  Dry run complete. No SDK packages were published.");
	} else {
		console.log(`  Published SDK packages with tag '${npmTag}':`);
		for (const workspace of SDK_PUBLISH_ORDER) {
			console.log(`    - @cline/${workspace}@${version}`);
		}
	}
	console.log(`${"═".repeat(60)}\n`);

	return 0;
}

// ── CLI Release ───────────────────────────────────────────────────────────────
// Builds cross-platform binaries via apps/cli/script/build.ts, then publishes
// the generated platform packages and wrapper package to npm.

async function releaseCLI(version: string): Promise<number> {
	console.log(`\nRelease CLI`);
	console.log(`  Version:     ${version}`);
	console.log(`  Git tag:     cli-v${version}`);
	console.log(`  Tag:         ${npmTag}`);
	console.log(`  Dry run:     ${dryRun}`);
	console.log(`  Skip tests:  ${skipTests}`);

	if (!dryRun) {
		const ok = await confirm("\nProceed with CLI release?");
		if (!ok) {
			console.log("Aborted.");
			return 1;
		}
	}

	// Step 1: Tests
	if (!skipTests) {
		header("Step 1/3: Running tests");
		await run(["bun", "run", "test"]);
	} else {
		header("Step 1/3: Skipping tests (--skip-tests)");
	}

	// Step 2: Build all platform binaries
	header("Step 2/3: Cross-compiling for all platforms");
	await run(["bun", "script/build.ts", "--install-native-variants"], {
		cwd: cliDir,
	});

	// Step 3: Publish to npm
	header("Step 3/3: Publishing to npm");
	const npmArgs = ["bun", "script/publish-npm.ts", "--tag", npmTag];
	if (dryRun) {
		npmArgs.push("--dry-run");
	}
	await run(npmArgs, { cwd: cliDir });

	console.log(`\n${"═".repeat(60)}`);
	if (dryRun) {
		console.log("  Dry run complete. CLI was not published.");
	} else {
		console.log(`  CLI v${version} published to npm.`);
		console.log("");
		console.log("  Install via npm:");
		console.log("    npm install -g cline");
	}
	console.log(`${"═".repeat(60)}\n`);

	return 0;
}

// ── Main ──────────────────────────────────────────────────────────────────────

let exitCode: number;
if (target === "sdk") {
	header("Checking branch");
	await ensureMainBranch();
	const version = await resolveVersion();
	exitCode = await releaseSDK(version);
} else {
	header("Checking CLI release tag");
	const version = await resolveCliVersion();
	await ensureCleanWorkingTree();
	await ensureCliReleaseTag(version);
	exitCode = await releaseCLI(version);
}

process.exit(exitCode);

#!/usr/bin/env bun

import { readdir, readFile, rm, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { parseArgs } from "node:util";

const { values, positionals } = parseArgs({
	args: Bun.argv.slice(2),
	options: {
		dry: { type: "boolean", default: false },
	},
	allowPositionals: true,
	strict: true,
});

let version = positionals[0];

function incrementPatchVersion(input: string): string {
	const match = input.match(/^(\d+)\.(\d+)\.(\d+)(-[\w.]+)?$/);
	if (!match) {
		throw new Error(`Invalid semver version: ${input}`);
	}

	const [, major, minor, patch] = match;
	return `${major}.${minor}.${Number(patch) + 1}`;
}

const root = join(import.meta.dir, "..", "..");
const sdkRoot = join(import.meta.dir, "..");
const packagesDir = join(sdkRoot, "packages");
const dirs = await readdir(packagesDir, { withFileTypes: true });
const workspaces = dirs.filter((d) => d.isDirectory()).map((d) => d.name);

if (!version) {
	for (const workspace of workspaces) {
		const pkgPath = join(packagesDir, workspace, "package.json");
		try {
			const raw = await readFile(pkgPath, "utf-8");
			const pkg = JSON.parse(raw);
			if (typeof pkg.version === "string") {
				version = incrementPatchVersion(pkg.version);
				break;
			}
		} catch {
			// skip directories without a package.json
		}
	}

	if (!version) {
		console.error(
			"Could not determine a current version from workspace package.json files.",
		);
		process.exit(1);
	}
}

if (!/^\d+\.\d+\.\d+(-[\w.]+)?$/.test(version)) {
	console.error(`Invalid semver version: ${version}`);
	process.exit(1);
}

if (positionals[0] === undefined) {
	console.log(`No version provided, defaulting to next patch: ${version}`);
}

async function runCommandOrThrow(cmd: string[], cwd: string): Promise<void> {
	const proc = Bun.spawn(cmd, {
		cwd,
		stdout: "inherit",
		stderr: "inherit",
	});
	const exitCode = await proc.exited;
	if (exitCode !== 0) {
		throw new Error(`${cmd[0]} exited with code ${exitCode}`);
	}
}

let updated = 0;

for (const workspace of workspaces) {
	const pkgPath = join(packagesDir, workspace, "package.json");
	try {
		const raw = await readFile(pkgPath, "utf-8");
		const pkg = JSON.parse(raw);
		if (pkg.internal === true) {
			continue;
		}
		const oldVersion = pkg.version;
		pkg.version = version;

		const out = `${JSON.stringify(pkg, null, "\t")}\n`;

		if (values.dry) {
			console.log(`[dry] ${pkg.name}: ${oldVersion} → ${version}`);
		} else {
			await writeFile(pkgPath, out);
			console.log(`${pkg.name}: ${oldVersion} → ${version}`);
		}
		updated++;
	} catch {
		// skip directories without a package.json
	}
}

console.log(
	`\n${values.dry ? "[dry] " : ""}Updated ${updated} package(s) to v${version}`,
);

if (!values.dry) {
	const lockPath = join(root, "bun.lock");
	await rm(lockPath, { force: true });
	console.log("Removed stale bun.lock if present");
	await runCommandOrThrow(["bun", "install", "--lockfile-only"], root);
	await runCommandOrThrow(
		["bun", "-F", "@cline/llms", "generate:models"],
		root,
	);
	await runCommandOrThrow(["bun", "format", "--write"], root);
	await runCommandOrThrow(["bun", "run", "build"], root);
}
